export const part3: Record<string, string[]> = {
  "23:1": ["Successful indeed are the muminin,", "নিশ্চয়ই বিশ্বাসীরা সফলকাম।"],
  "23:2": ["those who are humbled in their prayers,", "যারা তাদের সংযোগ প্রার্থনা (সালাত)-এ ভক্তিপূর্ণ থাকে।"],
  "23:3": ["and who turn away from idle talk,", "এবং তারা অনর্থক কথা এড়িয়ে চলে।"],
  "23:4": ["and who are doers of the alms-due,", "এবং তারা তাদের বাধ্যতামূলক দান (যাকাত) প্রদান করে।"],
  "23:5": ["and who guard their private parts,", "এবং তারা তাদের যৌন শুদ্ধতা বজায় রাখে।"],
  "23:6": ["except with their mates or what their right hands possess — for they are not to be blamed;", "তাদের যৌন সম্পর্ক থাকে শুধু তাদের জীবনসংগীদের  সাথে, অথবা তাদের সাথে যারা তাদের জন্য বৈধ, ; সেক্ষেত্রে তারা দোষী হবে না।"],
  "23:7": ["but whoever seeks beyond that — those are the transgressors.", "যারা এইসব সীমা অতিক্রম করে তারাই সীমালঙ্ঘনকারী।"],
  "23:8": ["And those who keep their trusts and their pledges,", "যখন তাদেরকে কাছে কোন আমানত রাখা হয় অথবা কোন চুক্তি তারা করে, তারা আস্থাভাজন।"],
  "23:9": ["and who guard their prayers —", "এবং তারা নিয়মিত তাদের সংযোগ প্রার্থনা (সালাত) পালন করে।"],
  "23:10": ["those are the inheritors,", "উত্তরাধিকারীরা এমনই।"],
  "23:11": ["who inherit the Garden; they abide in it forever.", "তারা স্বর্গের উত্তরাধিকারী হবে, যেখানে তারা চিরকাল বসবাস করে।"],
  "23:12": ["We created the human from an extract of clay.", "আমরা মানুষকে সৃষ্টি করেছি এক বিশেষ ধরনের কাদামাটি থেকে ।"],
  "23:13": ["Then We made it a drop in a firm resting-place.", "পরবর্তীকালে, আমরা তাকে এক অতি ক্ষুদ্র ফোঁটা থেকে পুনঃসৃষ্টি করেছি, যা এক সুরক্ষিত আধারে রাখা হয়।"],
  "23:14": ["Then We created the drop into a clinging clot, then We created the clot into a lump, then We created the lump into bones, then We clothed the bones with flesh, then We raised it up as another creation. So blessed be Allah, the best of creators.", "এরপর আমরা ফোঁটাটিকে পরিণত করলাম ঝুলন্ত (ভ্রুনে), তারপর ঝুলন্ত (ভ্রুন) -কে পরিণত করলাম কামড়-সদৃশ (মানবাকৃতির ভ্রুনে), তারপর কামড়-সদৃশ (মানবাকৃতির ভ্রুন) থেকে সৃষ্টি করলাম হাড়, তারপর হাড়কে মাংস দিয়ে ঢেকে দিলাম। আমরা এভাবে এক নতুন সৃষ্টি তৈরি করি। পরম কল্যাণময় আল্লাহ, সর্বোত্তম সৃষ্টিকারী।"],
  "23:15": ["Then after that you will surely die.", "এরপর, পরবর্তীতে, তোমরা মারা যাও।"],
  "23:16": ["Then on the Day of the Rising you will be raised.", "তারপর, পুনরুত্থান দিবসে তোমরা পুনরুত্থিত হবে।"],
  "23:17": ["We created above you seven paths, and We were never unmindful of the creation.", "আমরা তোমাদের উপর স্তরে স্তরে সাতটি মহাবিশ্ব সৃষ্টি করেছি, এবং আমরা তাতে একটি সৃষ্টি সম্পর্কেও অনবগত নই।"],
  "23:18": ["And We sent down water from the sky in due measure, and We settled it in the earth; and We are able to take it away.", "আমরা আকাশ থেকে পানি বর্ষণ করি, যথাযথ পরিমাণে, এরপর আমরা তা ভূমির ভেতরে জমা করি। নিশ্চয়ই, আমরা তা সরিয়ে দিতে পারি।"],
  "23:19": ["Then We raised up for you, by it, gardens of palms and grapes; in them are many fruits for you, and from them you eat.", "এটি দিয়ে, আমরা তোমাদের জন্য উৎপন্ন করি খেজুর গাছ এবং আঙ্গুরের বাগান, সব রকমের ফল, এবং নানা ধরনের খাদ্য।"],
  "23:20": ["And a tree that comes out from Mount Sinai, growing with oil and a dye for those who eat.", "আবার, সিনাই এর স্থানীয় একটি গাছ তেল উৎপন্ন করে, সেই সাথে আহারকারীদের জন্য রুচি।"],
  "23:21": ["And in the livestock there is a lesson for you: We give you drink from what is in their bellies, and in them are many benefits for you, and from them you eat.", "এবং পালনযোগ্য পশুসম্বদ  থেকে তোমাদের  একটি শিক্ষা নেওয়া উচিত। তাদের পেট থেকে আমরা তোমাদেরকে (দুধ) পান করতে দেই, তাদের থেকে তোমরা অন্যান্য সুবিধাও নিয়ে থাকো, এবং তাদের কতককে তোমরা খাদ্য হিসেবে নাও।"],
  "23:22": ["And on them and on ships you are carried.", "তাদের উপর, এবং জাহাজগুলোতে, তোমরা আরোহণ করো।"],
  "23:23": ["We sent Nuh to his people, and he said: \"O my people, worship Allah — you have no ilah but Allah. Will you not be Allah-fearing?\"", "আমরা নূহকে তার লোকদের কাছে পাঠিয়েছিলাম, এই বলে যে, “হে আমার লোকেরা, আল্লাহর উপাসনা করো। তার পাশে তোমাদের অন্যকোন উপাস্য নেই। তোমরা কি সৎকর্মশীল হবে না?"],
  "23:24": ["The chiefs of his people who kafara said: \"This is nothing but a human like you, who wants to gain favor over you. Had Allah willed, Allah would have sent down malakat. We never heard of this among our forefathers of old.\"", "তার লোকদের মধ্যে যেসব নেতারা অবিশ্বাস করেছিল তারা বলল, “এ তো তোমাদের মত মানুষের চেয়ে বেশি কিছু না, যে তোমাদের মাঝে ক্ষ্যাতি অর্জন করতে চায়।যদি আল্লাহ চাইতেন, তিনি স্বর্গদূতদের পাঠাতে পারতেন। আমরা আমাদের পূর্বপুরুষদের কাছে কখনোই এরকম কিছু শুনিনি।"],
  "23:25": ["\"He is only a man with madness upon him — so wait with him for a time.\"", "সে কেবল একজন মানুষ যে পাগল হয়ে গেছে।   তাকে শুধু কিছু সময়ের জন্য  উপেক্ষা করো।”"],
  "23:26": ["He said: \"My Rabb, help me against their denial.\"", "সে বলল, “ আমার প্রভু, আমাকে বিজয় দান করুন, কারন তারা আমাকে অবিশ্বাস করেছে।”"],
  "23:27": ["So We inspired him: \"Make the ship under Our eyes and Our inspiration. Then, when Our command comes and the oven boils over, take into it two of every kind, and your household — except those of them against whom the word has already preceded — and do not plead with Me for those who did wrong; they will be drowned.\"", "আমরা এরপর তাকে প্রত্যাদেশ করলাম: “আমাদের নজরদারির অধীনে, এবং আমাদের  প্রত্যাদেশ  অনুযায়ী জলযান তৈরী করো। যখন আমাদের আদেশ এসে যায়; এবং আবহাওয়া ভীষণ উত্তপ্ত হয়ে পড়ে, তখন এতে (তোমার গৃহপালিত পশুর) প্রত্যেকের একটি জোড়া, এবং তোমার পরিবারকে  উঠিয়ে নাও, তাদেরকে ছাড়া যারা ধ্বংস হবার জন্য সাব্যস্ত হয়েছে। যারা সীমালংঘন করেছে তাদের পক্ষ হয়ে আমার সাথে কথা বলো না; তারা নিমজ্জিত হবে।"],
  "23:28": ["Then, when you and those with you are settled on the ship, say: \"Praise belongs to Allah, who rescued us from the wrongdoing people.\"", "“যখন তুমি  জলযানে   স্থির হবে  তাদের সাথে একত্রে  যারা তোমার সাথে  আছে, তুমি বলবে, ‘প্রশংসা আল্লাহর আমাদেরকে মন্দ লোকদের কাছ থেকে রক্ষা করার জন্য।’"],
  "23:29": ["And say: \"My Rabb, bring me down in a blessed resting-place — You are the best of settlers.\"", "“এবং বল, ‘আমার প্রভু, আমাকে এক পবিত্র স্থানে  নোঙ্গর করতে দিন; আপনি সর্বোত্তম উদ্ধারকারী।”"],
  "23:30": ["In that are signs, and We were surely testing.", "এগুলো তোমাদের জন্য যথেষ্ট প্রমাণ হওয়া উচিত। আমরা নিশ্চয় তোমাদের পরীক্ষায় ফেলবো।"],
  "23:31": ["Then We raised up after them another generation,", "পরবর্তীতে, আমরা তাদের পর আরেকটি প্রজন্মকে প্রতিষ্ঠা করেছিলাম।"],
  "23:32": ["and We sent among them a Rasul from themselves: \"Worship Allah — you have no ilah but Allah. Will you not be Allah-fearing?\"", "আমরা তাদের কাছে তাদের মধ্য থেকে একজন বার্তাবাহক পাঠিয়েছিলাম, এই বলে যে, “তোমরা আল্লাহর উপাসনা করবে। তাঁর পাশে তোমাদের অন্য কোন উপাস্য নেই। তোমরা কি সৎকর্মশীল হবে না?”"],
  "23:33": ["The chiefs of his people who kafara and denied the meeting of the Hereafter — and We had eased them in the lower life — said: \"This is nothing but a human like you; he eats of what you eat and drinks of what you drink.", "তার লোকদের মধ্যে যে নেতারা পরকালের ধারণাকে অবিশ্বাস ও প্রত্যাখ্যান করেছিল, -যদিও এই জীবনে আমরা তাদেরকে উদারভাবে দান করেছিলাম - বলল, “এ তো তোমাদের মত একজন মানুষের চেয়ে বেশি কিছু নয়। সে খায় যা থেকে  তোমরা খাও, এবং পান করে যেমন তোমরা পান  করো।”"],
  "23:34": ["If you obey a human like yourselves, you will surely be the khasirin.", "“যদি তোমরা তোমাদেরই মতন একজন মানুষকে মান্য কর, তাহলে তোমরা আসলেই ক্ষতিগ্রস্ত হবে।"],
  "23:35": ["Does he promise you that when you die and become dust and bones, you will be brought out?", "“সে কি তোমাদেরকে এই  প্রতিশ্রুতি দেয় যে, তোমরা মরে যেয়ে ধূলা এবং হাড়ে পরিণত হবার পর, তোমরা আবার আবির্ভূত হবে?"],
  "23:36": ["Far, far away is what you are promised!", "“অসম্ভব, সত্যিই অসম্ভব তোমাদেরকে যে  প্রতিশ্রুতি দেয়া হয়।"],
  "23:37": ["There is nothing but our nearer life: we die and we live, and we will not be raised.", "“আমরা শুধু এই জীবনেই বেঁচে থাকি - আমরা বেঁচে থাকি এবং মরে যাই-এবং আমরা কখনোই পুনরুত্থিত হবো না।"],
  "23:38": ["He is only a man who has fabricated a lie against Allah — and we will not believe him.\"", "সে কেবলই একজন মানুষ যে মিথ্যা রচনা করেছে এবং সেগুলো আল্লাহর প্রতি আরোপ করেছে। আমরা কখনোই তাকে বিশ্বাস করবো না।"],
  "23:39": ["He said: \"My Rabb, help me against their denial.\"", "সে বলল, “আমার প্রভু, আমাকে বিজয় দান করুন, কারণ তারা আমাকে অবিশ্বাস করেছে।”"],
  "23:40": ["\"In a little while they shall surely be regretful.\"", "তিনি বললেন, “শীঘ্রই তারা অনুতপ্ত হবে।”"],
  "23:41": ["So the shout seized them in truth, and We made them like worthless chaff. Away with the wrongdoing people!", "শাস্তি তাদের আঘাত করল, ন্যায়সঙ্গত ভাবে এবং এভাবে, আমরা তাদেরকে ধ্বংসাবশেষে পরিণত করলাম। অন্যায়কারীরা ধ্বংস  হল।"],
  "23:42": ["Then We raised up after them other generations.", "পরবর্তীতে, আমরা তাদের পর অন্যান্য প্রজন্মদের প্রতিষ্ঠা করেছিলাম।"],
  "23:43": ["No nation can outstrip its term, and they do not delay.", "কোন সম্প্রদায় এর পূর্বনির্ধারিত নিয়তি এগিয়ে নিতে পারে না, না পারে পেছাতে।"],
  "23:44": ["Then We sent Our rusul in succession. Whenever a Rasul came to a nation, they denied him, so We made some of them follow others and turned them into bygone tales. Away with people who do not believe!", "এরপর আমরা পর্যায়ক্রমে আমাদের বার্তাবাহক পাঠালাম। যতবারই কোন বার্তাবাহক তার সম্প্রদায়ের কাছে গিয়েছে, তারা তাকে অবিশ্বাস করেছে। পরিনামে, আমরা তাদের ধ্বংস করলাম, একটির পর আরেকটি, এবং তাদেরকে ইতিহাস বানালাম। অবিশ্বাস করা লোকেরা বিলুপ্ত হল।"],
  "23:45": ["Then We sent Musa and his brother Harun with Our signs and a clear warrant", "এরপর আমরা মুসা ও তার ভাই হারুনকে আমাদের প্রত্যাদেশাবলি এবং এক প্রগাঢ় প্রমাণ সহকারে পাঠিয়েছিলাম।"],
  "23:46": ["to Fir'awn and his chiefs, but they grew arrogant and were a people grown high,", "ফেরাউন এবং তার সভাসদের কাছে, কিন্তু তারা উদ্ধত হয়ে গেল। তারা অত্যাচারী লোক ছিল।"],
  "23:47": ["and they said: \"Shall we believe two humans like ourselves, when their people serve us?\"", "তারা বলল, “আমরা কি এমন দুজন মানুষের জন্য বিশ্বাস করবো যাদের লোকেরা আমাদের দাস?”"],
  "23:48": ["So they denied them both, and they were among the destroyed.", "তারা সে দুজনকে প্রত্যাখ্যান করেছিল, এবং পরিনামে, এরা ধ্বংস হল।"],
  "23:49": ["We gave Musa the Book, so that they might be guided.", "আমরা মুসাকে ঐশীগ্রন্থ দিয়েছিলাম, যাতে তারা পথপ্রাপ্ত হতে পারে।"],
  "23:50": ["And We made the son of Maryam and his mother a sign, and sheltered them both on a highland with a settled resting-place and a spring.", "আমরা মরিয়মের পুত্র এবং তার মাকে করলাম একটি নিদর্শন, এবং আমরা তাদেরকে খাদ্য ও পানীয় দিয়ে একটি সমতল পাহাড় চূড়ায় আশ্রয় প্রদান করেছিলাম।"],
  "23:51": ["O rusul, eat of the good things and do what is right — I know well what you do.", "হে তোমরা বার্তাবাহকেরা, ভাল খাদ্যসামগ্রী থেকে খাও, এবং সৎকর্মশীল কাজ করো।"],
  "23:52": ["Truly this community of yours is one community, and I am your Rabb — so be Allah-fearing.", "এমনই তোমাদের ধর্মগোষ্ঠী- এক ধর্মগোষ্ঠী - এবং আমি তোমাদের প্রভু; তোমরা আমাকে ভক্তি করবে।"],
  "23:53": ["But they split their affair into portions — every party rejoicing in what it has.", "কিন্তু তারা নিজেদের বিবাদপূর্ণ উপদলে ছিন্ন করল। প্রত্যেক দল তাদের নিজেদেরটা নিয়ে খুশী।"],
  "23:54": ["Leave them in their flood until a time.", "অতএব, তাদেরকে শুধু তাদের বিভ্রান্তিতে ছেড়ে দাও, কিছু সময়ের জন্য।"],
  "23:55": ["Do they reckon that the wealth and children We supply them with", "তারা কি মনে করে যে, যেহেতু আমরা তাদেরকে অর্থ ও সন্তানাদি প্রদান করেছি,"],
  "23:56": ["are Us hastening them the good things? No — they do not perceive.", "সেহেতু আমরা তাদের উপর অবশ্যই অনুগ্রহ বর্ষণও করতে থাকবো? বস্তুত, তাদের কোন ধারণা নেই।"],
  "23:57": ["Those who are awe-struck with fear of their Rabb,", "নিশ্চিতই, যারা ভক্তির সাথে তাদের প্রভুর ব্যাপারে সচেতন,"],
  "23:58": ["and who believe in the signs of their Rabb,", "এবং যারা তাদের প্রভুর প্রত্যাদেশে বিশ্বাস করে,"],
  "23:59": ["and who do not associate others with their Rabb,", "এবং যারা কখনোই তাদের প্রভুর পাশে কোন উপাস্য স্থাপন করে না,"],
  "23:60": ["and who give what they give with hearts trembling in awe, knowing that to their Rabb they will return —", "যখন তারা দান করে, তাদের হৃদয় তখন ভক্তিতে পূর্ণ থাকে। কারণ, তারা মানে যে তারা তাদের প্রভুর সামনে একত্রিত হবে,"],
  "23:61": ["those race toward the good things, and they are the forerunners.", "তারা সৎ কাজ করতে আগ্রহী ; তারা সেগুলো করতে প্রতিযোগীতা করে।"],
  "23:62": ["We burden no soul beyond its capacity; and with Us is a book that speaks the truth, and they will not be wronged.", "আমরা কখনও কোন আত্মার উপর তার  সাধ্যের অতিরিক্ত বোঝা চাপাই না, এবং আমরা একটি নথি রাখি যা সত্য বলে। কেউই অবিচার ভোগ করবে না।"],
  "23:63": ["But their hearts are drowned in this, and they have works besides that which they do.", "তাদের অন্তর যেহেতু এর প্রতি বেখবর, তারা এমন কাজ করে এর সাথে যা মেলে না; তাদের কাজ মন্দ।"],
  "23:64": ["Until, when We seize their softened ones with punishment, at once they cry out.", "এরপর, যখন আমরা তাদের নেতাদের শাস্তি দিয়ে প্রতিফল দেই , তারা অভিযোগ করে।"],
  "23:65": ["\"Do not cry out today — no help from Us will reach you.\"", "এখন অভিযোগ করো না; তোমরা আমাদের সব সাহায্য পরিত্যাগ করেছ।"],
  "23:66": ["My signs were recited to you, but you used to turn back on your heels,", "আমার প্রমাণাদি তোমাদের কাছে উপস্থাপন করা হচ্ছিল , কিন্তু তোমরা পিছু হটে গেলে।"],
  "23:67": ["arrogant toward it, talking by night, turning away.", "তোমরা এতো উদ্ধত ছিলে যে সেগুলো গ্রহণ করনি , এবং তোমরা স্পর্ধাসহকারে এগুলোকে উপেক্ষা করেছিলে।"],
  "23:68": ["Have they not pondered the word? Or has there come to them what did not come to their forefathers of old?", "কেন তারা এই ঐশীগ্রন্থের বিষয়ে ভেবে দেখে না? তারা কি অনুধাবন করে না যে, তারা এমনকিছু পেয়েছে, যা কখনো তাদের পূর্বপুরুষেরা পায়নি?"],
  "23:69": ["Or do they not recognize their Rasul, and so they disavow him?", "তারা কি তাদের বার্তাবাহকে চিনতে ব্যর্থ হয়েছে? এ কারণেই কি তারা তাকে উপেক্ষা করছে?"],
  "23:70": ["Or do they say, \"He is mad\"? No — he brought them the truth, and most of them are averse to the truth.", "তারা কি সিদ্ধান্তে এসেছে যে সে পাগল? নিশ্চয়ই, সে তাদের কাছে সত্য এনেছে, কিন্তু তাদের বেশিরভাগই সত্যকে ঘৃণা করে।"],
  "23:71": ["If the truth followed their desires, the heavens and the earth and whoever is in them would be corrupted. No — We brought them their reminder, but they turn away from their reminder.", "নিশ্চয়, সত্য যদি তাদের ইচ্ছামতো  হতো, তাহলে আকাশমন্ডলী ও পৃথিবীতে বিশৃঙ্খলা হতো; এদের মধ্যে সবকিছু কলুষিত হয়ে পড়তো। আমরা তাদেরকে তাদের প্রমাণ দিয়েছি, কিন্তু তারা তাদের প্রমাণ উপেক্ষা করছে।"],
  "23:72": ["Or do you ask them for a tribute? The tribute of your Rabb is better — and Allah is the best of providers.", "তুমি কি তাদের কাছে কোন পারিশ্রমিক চাইছো? তোমরা প্রভুর দেয়া পারিশ্রমিক অনেক উত্তম। তিনি সর্বোত্তম জীবিকা প্রদানকারী।"],
  "23:73": ["You call them to a straight path.", "নিশ্চিতভাবে, তুমি তাদেরকে এক সরল পথের দিকে আহবান করছ।"],
  "23:74": ["Those who do not believe in the Hereafter — from the path they surely swerve.", "যারা পরকালে অবিশ্বাস করে, অবশ্যই তারা সঠিক পথ থেকে বিচ্যুত হবে।"],
  "23:75": ["If We had mercy on them and uncovered the harm they suffer, they would plunge deeper into their transgression, wandering blind.", "এমনকি যখন আমরা তাদের উপর দয়া বর্ষণ করলাম, এবং তাদের সমস্যাগুলো দূর করে দিলাম, তখন সীমালঙ্ঘনে তারা আরো গভীরভাবে নিমজ্জিত হলো, এবং বিভ্রান্তিতে পড়েই রইল।"],
  "23:76": ["We seized them with punishment, but they did not humble themselves before their Rabb, nor do they plead humbly.", "এমনকি যখন আমরা তাদেরকে শাস্তি ভোগ করালাম, তারা কখনো তাদের প্রভুর কাছে মিনতি করতে ফেরেনি।"],
  "23:77": ["Until, when We open upon them a door of severe punishment, at once they are struck with despair.", "পরবর্তীতে, আমরা যখন তাদেরকে তাদের অর্জিত কঠিন শাস্তি দিয়ে প্রতিফল দিলাম, তারা প্রচণ্ড ধাক্কা খেলো।"],
  "23:78": ["It is Allah who raised up for you hearing, sight, and hearts — rarely do you give thanks.", "তিনিই সেই সত্ত্বা যিনি তোমাদের দান করেছেন শ্রবনশক্তি, দৃষ্টিশক্তি, এবং মস্তিষ্ক। তোমরা খুব কমই কৃতজ্ঞ।"],
  "23:79": ["It is Allah who spread you forth over the earth, and to Allah you will be gathered.", "তিনিই সেই সত্ত্বা যিনি তোমাদেরকে পৃথিবীতে প্রতিষ্ঠিত করেছেন, এবং তাঁর সামনেই তোমাদের তলব করা হবে।"],
  "23:80": ["It is Allah who gives life and death, and to Allah belongs the alternation of night and day — will you not reason?", "তিনিই সেই সত্ত্বা যিনি জীবন ও মৃত্যু নিয়ন্ত্রণ করেন, এবং তিনিই সেই সত্ত্বা যিনি রাত এবং দিনের পালা-বদল করান। তোমরা কি বোঝো না?"],
  "23:81": ["No — they say the like of what the ancients said.", "তারা বলেছিল যা তাদের পূর্বপুরুষরা বলেছিল।"],
  "23:82": ["They say: \"When we die and become dust and bones, will we really be raised?", "তারা বলেছিল, “আমরা মরে ধূলা ও হাড়ে পরিনত হবার পরও কি আমরা পুনরুত্থিত হবো?"],
  "23:83": ["We and our fathers were promised this before. This is nothing but the tales of the ancients.\"", "“অতীতেও এ ধরণের প্রতিশ্রুতি আমাদেরকে এবং আমাদের পিতামাতাদের দেয়া হয়েছিল। এগুলো অতীতের কল্পকাহিনীর চেয়ে বেশি কিছু নয়।”"],
  "23:84": ["Say: \"Whose is the earth and whoever is in it, if you know?\"", "বল, “পৃথিবী এবং এর উপরের সকলে কার অধীন, যদি তোমরা জেনে থাকো?”"],
  "23:85": ["They will say: \"To Allah.\" Say: \"Will you not remember?\"", "তারা বলবে, “আল্লাহর।” বল, “তাহলে কেন তোমরা মনোযোগী হও না?”"],
  "23:86": ["Say: \"Who is the Rabb of the seven heavens, and the Rabb of the mighty arsh?\"", "বল, “ কে সাতটি মহাবিশ্বের প্রভু; মহা রাজত্যের প্রভু?"],
  "23:87": ["They will say: \"To Allah.\" Say: \"Will you not be Allah-fearing?\"", "তারা বলবে, “আল্লাহ।” বল, “তাহলে কেন তোমরা সৎকর্মশীল হও না?”"],
  "23:88": ["Say: \"In whose hand is the dominion of all things, who grants refuge and from whom none is granted refuge — if you know?\"", "বল, “কার হাতে রয়েছে সবকিছুর উপর সকল সার্বভৌমত্ত্ব, এবং একমাত্র তিনিই সাহায্য করতে পারেন, কিন্তু তাঁর কোনও সাহায্যের প্রয়োজন হয় না, যদি তোমরা জানো?”"],
  "23:89": ["They will say: \"To Allah.\" Say: \"Then how are you bewitched?\"", "তারা বলবে, “আল্লাহ।” বল, “কোথায় তোমরা ভুল করেছ?”"],
  "23:90": ["No — We brought them the truth, and they are the kazibin.", "আমরা তাদেরকে সত্য দিয়েছি, অথচ তারা মিথ্যাবাদী।"],
  "23:91": ["Allah has taken no child, and there is no ilah beside Allah — for then each ilah would carry off what it created, and some would rise high over others. Exalted be Allah above what they describe!", "আল্লাহ কখনোই কোন পুত্র জন্ম দেননি। না তাঁর পাশে কখনো অন্য কোন উপাস্য ছিল। অন্যথায়, প্রত্যেক উপাস্য তার সৃষ্টিকে নিয়ে স্বাধীনতা ঘোষণা করতো, এবং তারা  কর্তৃত্তের জন্য একে অন্যের সাথে প্রতিযোগিতা করতো। মহিমা আল্লাহর, তাদের দাবির অনেক উর্ধ্বে।"],
  "23:92": ["Knower of the unseen and the witnessed — exalted is Allah above what they associate.", "সকল গোপন ও প্রকাশ্য বিষয়ের জ্ঞাতা; তিনি সমুচ্চ, অংশীদার থাকা থেকে অনেক ঊর্ধ্বে।"],
  "23:93": ["Say: \"My Rabb, if You show me what they are promised,", "বল, “আমার প্রভু,  তাদের অর্জিত (শাস্তি) আমাকে দেখান বা না দেখান,"],
  "23:94": ["my Rabb, do not place me among the wrongdoing people.\"", "“আমার প্রভু, আমাকে সীমালংঘনকারী লোকদের একজন করবেন না।”"],
  "23:95": ["We are well able to show you what We promise them.", "তাদের জন্য আমাদের সংরক্ষিত (শাস্তি) এমনকিছু যা আমরা তোমাকে সহজেই দেখাতে  পারি।"],
  "23:96": ["Push back evil with what is best — We know best what they describe.", "সুতরাং, ভাল দিয়ে তাদের মন্দ কাজ প্রতিহত কর; আমরা তাদের দাবি সম্পর্কে পূর্ণ অবগত।"],
  "23:97": ["And say: \"My Rabb, I seek refuge in You from the promptings of the devils,", "বল, “আমার প্রভু, আমি আপনার কাছে শয়তানদের প্ররোচনা থেকে আশ্রয় চাই।"],
  "23:98": ["and I seek refuge in You, my Rabb, that they should be present with me.\"", "“এবং আমি আপনার কাছে আশ্রয় চাই, আমার প্রভু, পাছে তারা আমার নিকটে চলে আসে।”"],
  "23:99": ["Until, when death comes to one of them, he says: \"My Rabb, send me back,", "মৃত্যু যখন তাদের কারো কাছে আসে, সে বলে, “আমার প্রভু, আমাকে ফেরত পাঠান।"],
  "23:100": ["that I may do right in what I left behind.\" Never — it is only a word he speaks; and behind them is a barrier until the day they are raised.", "“তাহলে আমি আমার ফেলে আসা সবকিছুতে সৎকাজ করবো।” সত্য নয়। এটি একটি মিথ্যা দাবি যা সে করে। একটি অন্তরায় এই দুনিয়া থেকে তার আত্মাকে আলাদা করে রাখবে পুনরুত্থান পর্যন্ত।"],
  "23:101": ["When the blast is blown, on that day there will be no kinship between them, and they will not ask one another.", "যখন শিঙায় ফুঁ দেয়া হবে, সেদিন তাদের মধ্যে কোন সম্পর্ক বিদ্যমান থাকবে না, না তারা একে অন্যের বিষয়ে পরোয়া করবে।"],
  "23:102": ["Those whose scales weigh heavy — those are the muflihin.", "তাদের ক্ষেত্রে  যাদের ওজন ভারি হবে, তারাই হবে বিজয়ী।"],
  "23:103": ["And those whose scales weigh light — those are the ones who lost themselves; in Jahannam they abide forever.", "তাদের ক্ষেত্রে যাদের ওজন হালকা, তারা সেই ব্যক্তি যারা তাদের আত্মা হারিয়েছে; তারা চিরদিন নরকে বাস করবে।"],
  "23:104": ["The fire scorches their faces, and in it they are scowling.", "আগুণ তাদের মুখমণ্ডল ছেয়ে ফেলবে, এবং তারা সেখানে স্থায়ী হবে শোচনীয়ভাবে।"],
  "23:105": ["\"Were My signs not recited to you, yet you denied them?\"", "আমার প্রত্যাদেশাবলি কি তোমাদের কাছে পাঠ করা হয়নি, এবং তোমরা কি সেগুলো প্রত্যাখ্যান করে যাও নি?"],
  "23:106": ["They say: \"Our Rabb, our wretchedness overcame us, and we were a people astray.", "তারা বলবে, “আমাদের প্রভু, আমাদের অন্যায় আমাদের আচ্ছন্ন করেছে এবং আমরাই বিপথগামী লোক ছিলাম।"],
  "23:107": ["Our Rabb, bring us out of it — and if we return, then we are wrongdoers.\"", "“আমাদের প্রভু, আমাদেরকে এর থেকে বের করুন; যদি আমরা (আমাদের পুরনো স্বভাবে) ফিরে যাই, তাহলে আমরা আসলেই অন্যায়কারী।”"],
  "23:108": ["It is said: \"Be driven away into it, and do not speak.\"", "তিঁনি বলবেন, “সেখানে বাস কর, অপদস্থ হয়ে, এবং আমার সাথে কথা বলো না।”"],
  "23:109": ["\"There was a group of My servants who said: 'Our Rabb, we believe — so forgive us and have mercy on us; You are the best of the merciful.'\"", "“আমার বান্দাদের একটি দল বলতো, ‘আমাদের প্রভু, আমরা বিশ্বাস করেছি, তাই আমাদের ক্ষমা করুন এবং আমাদের উপর দয়া বর্ষণ করুন। সকল দয়াশীলদের মধ্যে আপনি সবচেয়ে দয়াশীল।’"],
  "23:110": ["You took them in mockery until they made you forget My reminder, and you used to laugh at them.", "\"“কিন্তু তোমরা তাদের ব্যঙ্গ ও পরিহাস করেছিলে, এতটা পরিমাণে যে তোমরা আঁমাকেই ভুলে গিয়েছিলে।"],
  "23:111": ["I have rewarded them this day for their steadfastness — they are the winners.", "“তাদের অবিচলতার বদলে, আজ আমি তাদের পুরস্কৃত করেছি,  তাদেরকে বিজয়ী করে।”"],
  "23:112": ["Say: \"How long did you tarry in the earth, in counted years?\"", "তিনি বললেন, “তোমরা পৃথিবীতে কত সময় কাটিয়েছো? কত বছর?”"],
  "23:113": ["They say: \"We tarried a day or part of a day — ask the counters.\"", "তারা বলল, “আমরা একদিন বা একদিনের কিছু অংশ কাটিয়েছি। যারা গননা করেছে তাদের জিজ্ঞেস করুন।”"],
  "23:114": ["Say: \"You tarried only a little — if only you knew.\"", "তিনি বললেন, “প্রকৃতপক্ষে, তোমরা মাত্র অল্পকালই অবস্থান করেছিলে, যদি তোমরা জানতে।"],
  "23:115": ["Did you reckon We created you in vain, and that to Us you will not return?", "“তোমরা কি মনে করেছিলে যে আমরা তোমাদের অনর্থক সৃষ্টি করেছি; যে তোমাদেরকে আমাদের কাছে ফিরিয়ে আনা হবে না?”"],
  "23:116": ["Exalted be Allah, the true King — there is no ilah but Allah, Rabb of the noble arsh.", "আল্লাহ সবচেয়ে উর্ধ্বে, প্রকৃত সার্বভৌমত্বের অধিকারী। তাঁর পাশাপাশি অন্য কোনও উপাস্য নেই; সর্বোচ্চ সম্মানিত প্রভু, সকল কর্তৃত্বের অধিকারী।"],
  "23:117": ["Whoever calls upon another ilah beside Allah, with no proof for it — his reckoning is only with his Rabb. The kafirin will not succeed.", "যে আল্লাহর পাশা পাশি অন্য উপাস্যদের ডাকে, এবং কোনও ধরণের প্রমাণ ছাড়াই, তার হিসাবকৃত বিষয় তার প্রভুর নিকট। অবিশ্বাসীরা কখনো সফল হয় না।"],
  "23:118": ["And say: \"My Rabb, forgive and have mercy — You are the best of the merciful.\"", "বল, “আমার প্রভু, আমাদেরকে ক্ষমা ও করুণা বর্ষণ করুন।সকল করুণাময়ের মধ্যে আপনিই সর্বশ্রেষ্ঠ করুণাময়।”"],
  "24:1": ["A chapter We sent down and ordained, and We sent down in it clear signs, so that you may remember.", "একটি সুরা যা আমরা অবতীর্ণ করেছি, এবং আমরা একটি আইন হিসেবে জারি করেছি। আমরা এতে স্পষ্ট প্রত্যাদেশ প্রকাশ করেছি, যাতে তোমরা মনোযোগ দিতে পারো।"],
  "24:2": ["The adulteress and the adulterer: flog each one of them with a hundred lashes, and let no pity for the two of them take hold of you in the law of Allah, if you believe in Allah and the last day; and let a party of the muminin witness their punishment.", "ব্যভিচারিণী নারী এবং ব্যভিচারি পুরুষ, এদের প্রত্যেককে তোমরা একশত কশাঘাত করবে। তাদের প্রতি সমবেদনা দ্বারা প্রভাবিত হয়ে আল্লাহর আইন নির্বাহ করা থেকে পিছপা হইয়ো না, যদি তোমরা সত্যই আল্লাহ ও শেষ দিনে বিশ্বাস করে থাকো। এবং একদল বিশ্বাসীদের প্রত্যক্ষ করতে দাও তাদের শাস্তি।"],
  "24:3": ["The adulterer shall marry none but an adulteress or an idolatress, and the adulteress shall be married by none but an adulterer or an idolater; and that is forbidden to the muminin.", "ব্যভিচারি পুরুষ শেষ পর্যন্ত ব্যভিচারিণী নারী অথবা প্রতিমা উপাসককে বিয়ে করবে। এবং ব্যভিচারিণী শেষ পর্যন্ত ব্যভিচারি পুরুষ অথবা প্রতিমা উপাসককে বিয়ে করবে। এটা বিশ্বাসীদের জন্য নিষিদ্ধ।"],
  "24:4": ["And those who accuse the fortified nisa, then do not bring four witnesses: flog them with eighty lashes, and never accept their testimony again; and those are the transgressors.", "যারা বিবাহিত নারীদের ব্যভিচারের অপরাধে অভিযুক্ত করে, এরপর চারজন সাক্ষী হাজির করতে ব্যর্থ হয়, তোমরা তাদেরকে আশিটি কশাঘাত করবে, এবং তাদের থেকে কোন সাক্ষী গ্রহণ করো না; তারা অন্যায়কারী।"],
  "24:5": ["Except those who turned back after that and reformed — then Allah is forgiving, merciful.", "এরপর যদি তারা অনুশোচনা করে ও সংশোধিত হয়, তবে আল্লাহ ক্ষমাশীল, করুণাময়।"],
  "24:6": ["And those who accuse their spouses and have no witnesses but themselves: the testimony of one of them is four testimonies by Allah that he is truly among the sadiqin.", "তাদের ক্ষেত্রে যারা নিজেদের সঙ্গিদের অভিযুক্ত করে, অন্য কোন সাক্ষী ছাড়া, তবে সাক্ষ্যটি  গ্রহণযোগ্য হতে পারে যদি সে আল্লাহর নামে চার বার শপথ করে যে সে সত্য বলছে।"],
  "24:7": ["And the fifth, that the curse of Allah be upon him if he is among the kazibin.", "পঞ্চম শপথটি হবে আল্লাহর দণ্ডাদেশ তার উপর টেনে আনা, যদি সে মিথ্যা বলে থাকে।"],
  "24:8": ["And the punishment shall be warded off from her by her testifying with four testimonies by Allah that he is among the kazibin.", "সে (নারী) নির্দোষ বিবেচিত হবে যদি সে (নারী) আল্লাহর নামে চার বার শপথ করে যে সে (পুরুষ) একজন মিথ্যাবাদী।"],
  "24:9": ["And the fifth, that the wrath of Allah be upon her if he is among the sadiqin.", "পঞ্চম শপথটি হবে আল্লাহর ক্রোধ তার উপর টেনে আনা, যদি সে (পুরুষ) সত্য বলে থাকে।"],
  "24:10": ["Were it not for Allah's favor upon you and Allah's mercy — and Allah is relenting, wise.", "এটা আল্লাহর দয়া এবং করুণা তোমাদের প্রতি। আল্লাহ আত্মার মুক্তিদানকারী, সবচেয়ে জ্ঞানী।"],
  "24:11": ["Truly those who brought the fabrication are a band of you; think it not an evil for you — rather it is good for you; for every person of them is what he earned of the sin, and those who took charge of the greatest part of it, his is a punishment most great.", "তোমাদের মধ্যে একটি দল এক বড় মিথ্যা তৈরি করেছে। ভেবো না যে এটা তোমাদের জন্য মন্দ ছিল, বরং, এটা তোমাদের জন্য ভালো ছিল। ইতোমধ্যে, তাদের প্রত্যেকে এ অপরাধে  তার নিজের অংশ অর্জন করেছে। আর তার ক্ষেত্রে যে এই পুরো ঘটনার সুত্রপাত করেছিল, সে এক ভয়ানক শাস্তি টেনে এনেছে।"],
  "24:12": ["Why did not the believing men and the believing nisa, when you heard it, assume good of themselves and say: this is a clear fabrication?", "যখন তোমরা তা শুনলে, বিশ্বাসী পুরুষ এবং বিশ্বাসী নারীদের উচিত ছিল নিজেদের ব্যাপারে উত্তম ধারনা রাখা, এবং বলা উচিত ছিল, “এটা স্পষ্টতই এক বড় মিথ্যা”।"],
  "24:13": ["Why did they not bring against it four witnesses? So when they did not bring the witnesses, those are, in the sight of Allah, the kazibin.", "শুধু যদি তারা চারজন সাক্ষী উপস্থিত করতো (তোমরা তাদের বিশ্বাস করতে পারতে)। যদি তারা সাক্ষী উপস্থিত করতে ব্যর্থ হয়, তবে তারা, আল্লাহর কাছে, মিথ্যাবাদী।"],
  "24:14": ["Were it not for Allah's favor upon you and Allah's mercy, in the present world and the world to come, a most great punishment would have touched you over what you poured forth into.", "যদি তোমাদের প্রতি এই দুনিয়া ও পরকালে আল্লাহর অনুগ্রহ, এবং  তাঁর দয়া না হতো, তোমরা এই ঘটনার কারনে এক মহা শাস্তি ভোগ করতে।"],
  "24:15": ["When you received it with your tongues and said with your mouths what you had no knowledge of, and reckoned it slight, while in Allah's sight it was great.", "তোমরা নিজেদের মুখে এ মিথ্যা উদ্ভাবন করেছিলে, এবং তোমাদের অন্যরা তা নিজের মুখে পুনরাবৃত্তি করছিলে প্রমান ছাড়াই। তোমরা ভেবেছিলে এটা সাধারন কিছু, যখন এটা ছিল, আল্লাহর কাছে গুরুতর ব্যাপার।"],
  "24:16": ["Why did you not, when you heard it, say: it is not for us to speak of this; glory be to You — this is a stunning slander, great.", "যখন তোমরা তা শুনেছিলে, তোমাদের বলা উচিত ছিল, “আমরা এর পুনরাবৃত্তি করবো না। মহিমা তোমার। এটা এক ঘোর মিথ্যাচার”।"],
  "24:17": ["Allah admonishes you never to return to the like of it, if you are muminin.", "আল্লাহ তোমাদের সাবধান করেন যে তোমরা পুনরায় এরকম কখনো করবে না, যদি তোমরা বিশ্বাসী হও।"],
  "24:18": ["And Allah makes clear for you the signs; and Allah is knowing, wise.", "আল্লাহ এভাবে তোমাদের জন্য প্রকাশনাবলী ব্যাখ্যা করেন। আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।"],
  "24:19": ["Truly those who love that obscenity be spread among those who believe: for them is a painful punishment in the present world and the world to come; and Allah knows, and you know not.", "বিশ্বাসীদের মধ্যে অনৈতিকতা ছড়িয়ে যাওয়া দেখতে যারা ভালোবাসে তারা এই জীবনে ও পরকালে টেনে এনেছে এক যন্ত্রণাদায়্ক শাস্তি। আল্লাহ জানেন, যখন তোমরা জানো না।"],
  "24:20": ["Were it not for Allah's favor upon you and Allah's mercy — and Allah is compassionate, merciful.", "আল্লাহ তোমাদেরকে তাঁর অনুগ্রহ ও দয়া বর্ষণ করেন। আল্লাহ বিশ্বাসীদের প্রতি সবচেয়ে দয়ালু, সবচেয়ে করুণাময়।"],
  "24:21": ["O you who believe, do not follow the footsteps of Shaytan; and whoever follows the footsteps of Shaytan — he commands obscenity and the rejected; and were it not for Allah's favor upon you and Allah's mercy, not one of you would ever be purified, but Allah purifies whomever Allah wills; and Allah is all-hearing, knowing.", "ও যারা তোমরা বিশ্বাস করো, শয়তানের পদাঙ্ক অনুসরণ করো না। যে কেউ শয়তানের পদাঙ্ক অনুসরণ করে, তার জানা উচিত যে, সে মন্দ ও অনৈতিকতার ওকালতি করে। যদি তোমাদের প্রতি আল্লাহর অনুগ্রহ ও তার দয়া না হতো, তোমাদের কেউ পরিশুদ্ধ হতে না। কিন্তু আল্লাহ যাকে ইচ্ছা পরিশুদ্ধ করেন। আল্লাহ  শ্রবণকারী, জ্ঞাতা।"],
  "24:22": ["And let not those of bounty among you and of abundance withhold from giving to their relatives, and the needy, and those who emigrated in the way of Allah; and let them pardon and overlook — do you not love that Allah forgive you? And Allah is forgiving, merciful.", "তোমাদের মধ্যে পুঁজি ও সম্পদে যারা সৌভাগ্যশালী তারা তাদের আত্মীয়সজন, দরিদ্র এবং যারা আল্লাহর উদ্দেশ্যে দেশত্যাগ করেছে তাদের প্রতি দানশীল হবে। তারা তাদের সাথে দয়াশীল ও সহনশীল ব্যবহার করবে; তোমরা কি আল্লাহর ক্ষমা পেতে ভালবাসো না? আল্লাহ ক্ষমাশীল, সবচেয়ে দয়াময়।"],
  "24:23": ["Truly those who accuse the fortified, unmindful, believing nisa: cursed are they in the present world and the world to come, and for them is a punishment most great.", "নিশ্চয়, বিবাহিত ধর্মভীরু বিশ্বাসী নারীদের উপর যারা মিথ্যা অভিযোগ আরোপ করে, তারা এই জীবন ও পরকালে দন্ডাদেশ টেনে এনেছে; তারা টেনে এনেছে এক ভয়ানক শাস্তি।"],
  "24:24": ["On a day when their tongues and their hands and their feet will testify against them for what they used to do.", "সে দিন আসবে যখন তাদের নিজেদের জিহবা, হাত, ও পা, যাকিছু তারা করেছিল তার সাক্ষী দেবে।"],
  "24:25": ["On that day Allah will pay them their due in full, and they will know that Allah is the clear truth.", "সেই দিন, আল্লাহ তদেরকে তাদের কাজের জন্য পরিপূর্ণ প্রতিদান দেবেন, এবং তারা দেখবে যে আল্লাহই সত্য।"],
  "24:26": ["The vile nisa belong to the vile men, and the vile men belong to the vile nisa; and the good nisa belong to the good men, and the good men belong to the good nisa; those are cleared of what they say; for them is forgiveness and a generous provision.", "মন্দ নারীরা মন্দ পুরুষের জন্য, এবং মন্দ পুরুষরা মন্দ নারীদের জন্য, এবং ভালো নারীরা ভালো পুরুষদের জন্য, এবং ভালো পুরুষরা ভালো নারীদের জন্য। এরা এমন অভিযোগের ক্ষেত্রে নির্দোষ। তারা ক্ষমা এবং এক উদার পুরুস্কার লাভ করেছে।"],
  "24:27": ["O you who believe, do not enter any house other than your own until you have asked leave and greeted the people of it; that is better for you, so that you may remember.", "হে তোমরা যারা বিশ্বাস করো, তোমাদের নিজেদের ঘর ছাড়া অন্যের ঘরে সেখানে বসবাসকারীদের অনুমতি ছাড়া, এবং তাদেরকে অভিবাদন না করে প্রবেশ করো না এটা তোমাদের জন্য উত্তম, যাতে তোমরা মনোযোগ দিতে পারো।"],
  "24:28": ["So if you find no one in it, do not enter it until leave is given to you; and if you are told to turn back, then turn back — that is purer for you; and Allah knows what you do.", "যদি তোমরা সেখানে কাউকে না পাও, সেখানে প্রবেশ করো না, যতক্ষণ না তোমরা অনুমতি পাও। যদি তোমাদেরকে বলা হয়, “ফিরে যাও, ” তোমরা অবশ্যই ফিরে যাবে। এটাই তোমাদের জন্য অধিকতর শুদ্ধ। যা কিছু তোমরা করো আল্লাহ সে সম্পর্কে সম্পূর্ণ অবগত।"],
  "24:29": ["There is no blame on you that you enter houses not lived in, in which there is provision for you; and Allah knows what you make manifest and what you hide.", "তোমরা কোন ভুল করো না বসতিহীন বাড়িতে প্রবেশ করে  যেখানে তোমাদের কিছু আছে। আল্লাহ জানেন সবকিছু যা তোমরা প্রকাশ করো, এবং সবকিছু যা তোমরা গোপন করো।"],
  "24:30": ["Tell the believing men that they lower some of their sights and guard their openings; that is purer for them; truly Allah is all-aware of what they do.", "বিশ্বাসী পুরুষদের বল যে তারা যেন তাদের দৃষ্টি নত রাখে (এবং নারীদের দিকে তাকিয়ে না থাকে), এবং তারা যেন চরিত্র বজায় রাখে। এটা তাদের জন্য অধিকতর শুদ্ধ। যা কিছু তারা করে আল্লাহ সে সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "24:31": ["And tell the believing nisa that they lower some of their sights and guard their openings, and that they not display their adornment except what appears of it, and that they draw their coverings over their chests, and that they not display their adornment except to their husbands, or their fathers, or the fathers of their husbands, or their sons, or the sons of their husbands, or their brothers, or the sons of their brothers, or the sons of their sisters, or their nisa, or those whom their right hands possess, or the attendants following them without desire among men, or the young children who have not yet become aware of nisa's nakedness; and let them not strike with their feet so that what they hide of their adornment may be known; and turn to Allah all together, O muminin, so that you may attain success.", "আর বিশ্বাসী নারীদের বল তাদের দৃষ্টি নত রাখতে, এবং তারা যেন চরিত্র বজায় রাখে। তারা তাদের শরীরের কোন অংশ প্রকাশ করবে না, সেগুলো ছাড়া যা প্রয়োজনীয়। তারা তাদের বক্ষ ঢেকে রাখবে তাদের স্বামী, তাদের পিতা, তাদের স্বামীদের পিতা, তাদের পুত্র, তাদের স্বামীদের পুত্র, তাদের ভাই, তাদের ভাইদের পুত্র, তাদের বোনদের পুত্র, অন্য নারী, সেসব পুরুষ চাকর বা কর্মচারী যাদের যৌনশক্তি নিষ্ক্রিয় হয়ে গেছে, অথবা সেসব শিশু যারা বয়: সন্ধিতে পৌঁছেনি তারা ব্যতীত অন্যদের সামনে এই পরিধান নীতি শিথিল করবে না। হাটার সময় তারা তাদের পা জোরে আঘাত করবে না, তাদের শরীরের নির্দিষ্ট অঙ্গগুলোকে ঝাঁকানো এবং প্রকাশ করার উদ্দেশ্যে। তোমরা সকলে আল্লাহর কাছে অনুশোচনা করবে, হে বিশ্বাসীরা, যাতে তোমরা সফলকাম হতে পারো।"],
  "24:32": ["And arrange the marriage of the single ones among you and the salihin among your servants male and maids; if they are poor, Allah will enrich them of Allah's bounty; and Allah is all-ample, knowing.", "তোমাদের মধ্যে যারা অবিবাহিত, তাদেরকে বিবাহের জন্য উৎসাহিত করো। তারা বিয়ে করতে পারে তোমাদের অধস্তন সৎ-কর্মশীল পুরুষ এবং নারীদের, যদি তারা দরিদ্র হয়।  আল্লাহ তাদের নিজ অনুগ্রহে ধনী করে তুলবেন। আল্লাহ উদার, জ্ঞানী।"],
  "24:33": ["And let those who find no means of marriage keep chaste until Allah enriches them of Allah's bounty; and those who seek the contract from among those whom your right hands possess — write the contract with them if you know good in them, and give them from the wealth of Allah that was given to you; and do not compel your young nisa into prostitution if they desire fortification, seeking the goods of the worldly life; and whoever compels them — then Allah, after their being compelled, is forgiving, merciful.", "যারা বিয়ে করার ব্যয়ভার বহন করতে পারে না তারা নৈতিকতা বজায় রাখবে যতক্ষণ না আল্লাহ তাঁর অনুগ্রহ থেকে তাদেরকে জীবিকা প্রদান করেন। তোমাদের দাস-দাসীদের মধ্যে যারা বিয়ে করার জন্য মুক্তি পেতে আশা, তোমরা তাদের আশা পুরন করবে, যখন তোমরা উপলব্ধি করো যে তারা সৎ। আর তাদেরকে আল্লাহর অর্থ থেকে দাও যা তিনি তোমাদের উপর অর্পণ করেছেন। তোমরা তোমাদের মেয়েদের পতিতাবৃত্তিতে বলপ্রয়োগ করবে না, এই বিশ্বের বস্তুসামগ্রির খোঁজে, যদি তারা সতীত্ব বজায় রাখতে চায়। যদি কেউ তাদেরকে বলপ্রয়োগ করে, তবে আল্লাহ ক্ষমাশীল, করুণাময়, এ কারণে  যে তাদেরকে বলপ্রয়োগ করা হচ্ছে।"],
  "24:34": ["And We have sent down to you clear signs, and an example from those who passed on before you, and an admonition for the mindful.", "আমরা তোমার কাছে প্রকাশ করেছি স্পষ্টকারী প্রকাশনাবলি, এবং অতীত প্রজন্ম থেকে উদাহরণ, আর সৎ-কর্মীদের জন্য একটি আলোক বর্তিকা।"],
  "24:35": ["Allah is the light of the heavens and the earth; the likeness of Allah's light is as a niche wherein is a lamp, the lamp in a glass, the glass as if a brilliant star — a lamp kindled from a blessed tree, an olive neither of the east nor of the west, whose oil nearly shines though no fire has touched it: light upon light; Allah guides whomever Allah wills to Allah's light; and Allah strikes the examples for humankind; and Allah has knowledge of all things.", "আল্লাহ আকাশমন্ডলী ও পৃথিবীর আলো। তাঁর আলোর উপমা যেন একটি কাচেঁর পাত্রে স্থাপিত কোন প্রদীপের পিছনে থাকা একটি অবতল দর্পণ। কাচেঁর পাত্রটি যেন একটি উজ্জ্বল, মুক্তার মত  তারা। এর জ্বালানি সরবরাহ করা হয় একটি বরকতময় তেল উৎপাদনকারী গাছ থেকে, যা না পূর্বদেশীয়, না পশ্চিমা। এর তেল প্রায় স্ব-দ্যুতিমান, একে জ্বালাতে কোন আগুনের প্রয়োজন হয় না। আলোর উপর আলো। আল্লাহ যাকে ইচ্ছা তাঁর আলোর দিকে পথ দেখান। আল্লাহ এভাবে লোকদের জন্য রূপক বর্ণনা করেন। আল্লাহ সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "24:36": ["In houses Allah permitted to be raised, and that Allah's name be remembered in them; glory be to Allah is proclaimed in them by morning and by evening.", "আল্লাহর দ্বারা মর্যাদায় উন্নিত ঘর গুলোতে (আল্লাহর পথনির্দেশনা পাওয়া যায়), কেননা সেখানে তাঁর নাম স্মরণ করা হয়। সেখানে তাঁর পবিত্রতা ঘোষণা করা হয়, দিনে ও রাতে-"],
  "24:37": ["Men whom neither commerce nor trade turns from the remembrance of Allah, and from establishing the prayer, and from giving the alms; they hold reverent awe of a day in which hearts and sights turn over.", "লোকেদের যারা কর্মব্যস্ততা বা ব্যবসার কারণে আল্লাহর স্মরণ থেকে অন্যমনষ্ক হয় না; তারা সংযোগ প্রার্থনা (সালাত) পালন করে, এবং বাধ্যতামূলক  দান (যাকাত) দেয়, আর তারা সেদিন সম্পর্কে সচেতন, যখন মন ও চোখ আতঙ্কিত হবে।"],
  "24:38": ["So that Allah may requite them the best of what they did, and increase them from Allah's bounty; and Allah provides for whomever Allah wills without measure.", "আল্লাহ অবশ্যই তাদের ভালো কাজের জন্য তাদের পুরস্কৃত করবেন, এবং তাঁর অনুগ্রহ তাদের প্রতি বর্ষণ করবেন। আল্লাহ যাকে ইচ্ছা সীমাহীন জীবিকা দান করেন।"],
  "24:39": ["And those who disbelieve — their deeds are as a mirage in a lowland, which the thirsty one thinks water, until, when one comes to it, one finds nothing, and finds Allah there; so Allah pays the account in full; and Allah is swift in reckoning.", "তাদের ক্ষেত্রে যারা অবিশ্বাস করে, তাদের কাজগুলো মরুভূমির মরীচিকার মতো। তৃষ্ণার্ত ব্যক্তি ভাবে যে এটা পানি। কিন্তু যখন সে এর কাছে পৌঁছায়, সে দেখে যে এটা কিছুই না এবং সেখানে সে পরিবর্তে আল্লাহকে পায়, তাকে তার কাজের পূর্ণ প্রতিফল দেয়ার জন্য। আল্লাহ সবচেয়ে দক্ষ হিসাব গ্রহণকারী।"],
  "24:40": ["Or as darknesses in a deep sea, covered by a wave above which is a wave, above which is a cloud — darknesses, some over others; when one puts out one's hand, one nearly does not see it; and whoever Allah has not made a light for has no light.", "আরেকটি উপমা হলো কোন উত্তাল মহাসাগরের মধ্যভাগে থাকা যেখানে আছে পুরোপুরি অন্ধকার, সাথে আছে ঢেউ এর উপর ঢেউ, আরো আছে ঘন কুয়াশা। অন্ধকারের উপর অন্ধকার – যদি সে তার নিজের হাতের দিকে তাকাতো, সে তা প্রায় দেখতেই পেতো না। যাকে আল্লাহ আলো থেকে বঞ্চিত করেন, তার কোন আলো থাকবে না।"],
  "24:41": ["Have you not seen that Allah is glorified by all who are in the heavens and the earth, and the birds ranked in rows? Each has known its prayer and its glorification; and Allah knows what they do.", "তুমি কি অনুধাবন করো না যে আকাশমণ্ডলী ও পৃথিবীর সকলে আল্লাহর মহিমা ঘোষণা করে, এমনকি পাখিরাও, যখন তারা শ্রেণীবদ্ধ হয়ে উড়ে? প্রত্যেকে জানে নিজের প্রার্থনা এবং গুণকীর্তন পদ্ধতি। আল্লাহ সম্পূর্ণ জানেন যা কিছু তারা করে।"],
  "24:42": ["And to Allah belongs the dominion of the heavens and the earth; and to Allah is the arrival.", "আকাশমণ্ডলী ও পৃথিবীর সার্বভৌম ক্ষমতা আল্লাহর, এবং আল্লাহর দিকেই চূড়ান্ত নিয়তি।"],
  "24:43": ["Have you not seen that Allah drives clouds along, then joins them together, then makes them a mass, and you see the rain coming forth from within it? And Allah sends down from the sky, from mountains within it, hail, and strikes with it whomever Allah wills, and turns it away from whomever Allah wills; the flash of its lightning nearly takes away the sights.", "তুমি কি অনুধাবন করো না যে আল্লাহ মেঘমালাকে চালনা করেন, তারপর এদেরকে একত্রে পুঞ্জিভুত করেন, এরপর এদের একটির উপর অন্যটিকে স্তুপ করেন, তারপর তুমি এদের থেকে বৃষ্টি বের হয়ে আসতে দেখ? তিনি আকাশ থেকে ভারী তুষারপাতবর্ষণ করেন যাকে ইচ্ছা ঢেকে দিতে, আবার যার থেকে ইচ্ছা একে সরিয়ে দেন। তুষারের উজ্জলতা চোখকে প্রায় অন্ধ করে দেয়।"],
  "24:44": ["Allah turns the night and the day about; truly in that is a lesson for those endowed with sights.", "আল্লাহ রাত ও দিনকে নিয়ন্ত্রন করেন। এটা তাদের জন্য শিক্ষা হওয়া উচিৎ যারা দৃষ্টির অধিকারী।"],
  "24:45": ["And Allah created every creature from water; so among them are those who walk on their bellies, and among them are those who walk on two legs, and among them are those who walk on four; Allah creates what Allah wills; truly Allah is powerful over all things.", "আর আল্লাহ প্রত্যেক জীবন্ত সৃষ্টিকে পানি থেকে সৃষ্টি করেছেন। তাদের কেউ কেউ পেটে ভর দিয়ে হাটে, কেউ দুই পায়ে হাটে, এবং কেউ চার পায়ে হাটে। আল্লাহ সৃষ্টি করেন যা তিনি ইচ্ছা করেণ। আল্লাহ সর্বশক্তিমান।"],
  "24:46": ["We have sent down clear signs; and Allah guides whomever Allah wills to a straight path.", "আমরা তোমার কাছে স্পষ্টকারী প্রকাশনাবলী অবতীর্ণ করেছি, এরপর আল্লাহ যাকে ইচ্ছা সরল পথে পরিচালিত করেন।"],
  "24:47": ["And they say: we believe in Allah and the Rasul and we obey; then a party of them turns away after that; and those are not muminin.", "তারা বলে, “আমরা আল্লাহ ও বার্তাবাহককে বিশ্বাস করি, এবং আমরা মান্য করি,” কিন্তু এরপর তাদের কেউ কেউ পরবর্তীতে পিছলে পিছনে পরে যায়। এরা বিশ্বাসী নয়।"],
  "24:48": ["And when they are called to Allah and the Rasul so that judgment be made between them, behold a party of them turns away.", "যখন তাদেরকে তাদের মধ্যে ফয়সালা করার জন্য আল্লাহ এবং তাঁর বার্তাবাহকের দিকে আমন্ত্রন জানানো হয়, তদের কেউ কেউ মর্মাহত হয়।"],
  "24:49": ["And if the truth be on their side, they come to it willingly, submissive.", "কিন্তু, রায় তাদের পক্ষে হলে, তারা নির্দ্বিধায় তা মেনে নেয়।"],
  "24:50": ["Is there a sickness in their hearts, or did they doubt, or do they fear that Allah and the Rasul should be unjust to them? No, those are the unjust.", "তাদের হৃদয়ে কি কোন রোগ আছে? তারা কি সন্দিহান? তারা কি ভয় পায় যে আল্লাহ এবং তাঁর বার্তাবাহক তাদের সাথে অন্যায় করতে পারেন? প্রকৃতপক্ষে, তারই অন্যায়কারী।"],
  "24:51": ["The word of the muminin, when they are called to Allah and the Rasul so that judgment be made between them, is only that they say: we hear and we obey; and those are the ones who attain success.", "যখন তাদের বিষয়ে ফয়সালার করার জন্য আল্লাহ এবং তাঁর বার্তাবাহকের দিকে আমন্ত্রন জানানো হয়, তখন বিশ্বাসীদের উক্তি কেবল এটাই হয় “আমরা শুনি এবং আমরা মান্য করি”। এরাই জয়ী।"],
  "24:52": ["And whoever obeys Allah and the Rasul, and holds reverent awe of Allah, and is mindful of Allah: those are the winners.", "যারা আল্লাহ এবং তাঁর বার্তাবাহককে মান্য করে, এবং আল্লাহকে ভক্তি করে এবং তাঁকে মেনে চলে, এরাই বিজয়ী।"],
  "24:53": ["And they swore by Allah with the utmost of their oaths: if you order them they will surely go out; say: do not swear; known obedience; truly Allah is aware of what you do.", "তারা আল্লাহর নামে শপথ করে, দৃঢ়ভাবে, যে যদি তুমি তাদেরকে সমবেত হবার আদেশ করতে, তারা সমবেত হতো। বল, “শপথ করো না। অনুগত থাকা একটি  দায়িত্ব। তোমরা যা কিছু করো আল্লাহ তা সম্পর্কে সম্পূর্ণ অবগত।\""],
  "24:54": ["Say: obey Allah and obey the Rasul; so if they turn away, upon the Rasul is only the burden carried, and upon you is only the burden you carried; if you obey the Rasul you are guided; and upon the Rasul is only the clear delivery.", "বল, “আল্লাহকে মান্য করো, এবং মান্য করো বার্তাবাহককে।\" যদি তারা অগ্রাহ্য করে, তবে সে তার দায়িত্বের জন্য দায়ী, এবং তোমরা তোমাদের দায়িত্বের জন্য দায়ী। যদি তোমরা তাকে মান্য করো, তোমরা সুপথপ্রাপ্ত হবে। বার্তাবাহকের কর্তব্য তো কেবল (বার্তা) পৌঁছে দেয়া।"],
  "24:55": ["Allah has promised those among you who believe and do the salihin deeds: Allah will surely make them successors in the land as Allah made successors those before them, and will surely establish for them their religion that was approved for them, and will surely substitute for them, after their fear, security — they shall worship Me, not joining anything with Me; and whoever disbelieves after that, those are the transgressors.", "তোমাদের মধ্যে যারা বিশ্বাস করে এবং সৎ জীবন যাপন করে তাদেরকে আল্লাহ প্রতিশ্রুতি দেন যে, তিনি পৃথিবীতে তাদেরকে শাসন কর্তৃত্ব দান করবেন, যেমন তিনি তাদের পূর্ববর্তীদের যারা ছিল তাদের জন্য করেছিলেন, এবং তাদের জন্য প্রতিষ্ঠিত করবেন সে ধর্মকে যা তিনি তাদের জন্য পছন্দ করেছেন, এবং তাদের জন্য ভয়কে শান্তি ও নিরাপত্তা দিয়ে প্রতিস্থাপন করবেন। এসবের কারন হচ্ছে, তারা একমাত্র  আমার উপাসনা করে; তারা কখনো আমার পাশে কোন উপাস্য স্থাপন করে না। যারা এরপরও অবিশ্বাস করে, তারা সত্যিকার পাপী।"],
  "24:56": ["And establish the prayer and give the alms and obey the Rasul, so that you may be shown mercy.", "তোমরা সংযোগ প্রার্থনা (সালাত) পালন করবে ও বাধ্যতামূলক দান (যাকাত) দেবে, এবং বার্তাবাহককে মান্য করবে, যাতে তোমরা দয়া অর্জন করতে পারো।"],
  "24:57": ["Do not reckon those who disbelieve able to frustrate Allah in the land; and their refuge is the fire — and wretched is the arrival.", "ভেবো না যারা অবিশ্বাস যারা অবিশ্বাস কোরে তারা কখনো পার পেয়ে যাবে। তাদের চূড়ান্ত বাসস্থান নরক; কি এক শোচনীয় নিয়তি।"],
  "24:58": ["O you who believe, let those whom your right hands possess ask your leave, and those among you who have not reached maturity, three times: before the dawn prayer, and when you lay aside your garments at midday, and after the evening prayer; three times of nakedness for you; there is no blame on you and no blame on them after these; go about among one another as you please; thus Allah makes clear for you the signs; and Allah is knowing, wise.", "হে তোমরা যারা বিশ্বাস করো, তোমাদের ভৃত্য ও শিশুরা যারা বয়ঃসন্ধিতে পৌঁছেনি, তাদেরকে অবশ্যই  (তোমাদের কক্ষে প্রবেশের আগে) অনুমতির জন্য অনুরোধ করতে হবে। তিনটি সময়ে এটি করতে হবে- ভোরের প্রার্থনার আগে, দুপুরে যখন তোমরা বিশ্রামের জন্য তোমাদের পোশাক পরিবর্তন করো, এবং রাতের প্রার্থনার পর। এগুলো তোমাদের জন্য তিনটি ব্যক্তিগত সময়। অন্য সময়ে, একে অন্যের সাথে মিলে যাওয়াতে তোমাদের বা তাদের  কোন দোষ নেই। আল্লাহ এভাবে প্রকাশনাবলি তোমাদের জন্য সুস্পষ্ট করেন। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "24:59": ["And when the children among you reach maturity, let them ask leave as leave was asked by those before them; thus Allah makes clear for you Allah's signs; and Allah is knowing, wise.", "যখন শিশুরা বয়ঃসন্ধিতে পৌঁছায়, তাদেরকে অবশ্যই (প্রবেশের আগে) অনুমতি চাইতে হবে, তাদের মত যারা তাদের পূর্বে প্রাপ্তবয়স্ক হয়ে (প্রবেশের আগে) অনুমতি চেয়েছে। আল্লাহ এভাবে তোমাদের জন্য তাঁর প্রকাশনাবলি সুস্পষ্ট করেন। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "24:60": ["And the nisa who stay seated, who do not hope for marriage: there is no blame on them that they lay aside their outer garments without displaying the adornment; and that they refrain is better for them; and Allah is all-hearing, knowing.", "বয়স্কা নারী যারা বিবাহের প্রত্যাশা করে না, তারা পোশাক পরিধান নীতিতে শিথিলতা করে কোন দোষ করে না, এ শর্তে যে তারা শরীরের খুব বেশি প্রকাশ করবে না। শালীনতা বজায় রাখা তাদের জন্য উত্তম। আল্লাহ শ্রোতা, জ্ঞাতা।"],
  "24:61": ["There is no restriction upon the blind, nor upon the lame, nor upon the sick, nor upon yourselves, that you eat from your houses, or the houses of your fathers, or the houses of your mothers, or the houses of your brothers, or the houses of your sisters, or the houses of your paternal uncles, or the houses of your paternal aunts, or the houses of your maternal uncles, or the houses of your maternal aunts, or what you hold the keys of, or your trusted friends; there is no blame on you that you eat together or separately; so when you enter houses, greet one another with a salutation from the presence of Allah, blessed and good; thus Allah makes clear for you the signs, so that you may reason.", "অন্ধের কোন দোষ নেই, পঙ্গুর কোন দোষ নেই, অক্ষমেরও কোন দোষ নেই, ঠিক যেমন তোমাদের কোন দোষ নেই পানাহার করতে যদি তা নিজেদের ঘরে করো, অথবা তোমাদের পিতাদের ঘরে, অথবা তোমাদের মাতাদের ঘরে, অথবা তোমাদের ভাইদের ঘরে, অথবা তোমাদের বোনদের ঘরে, অথবা তোমাদের চাচাদের ঘরে, অথবা তোমাদের ফুপুদের ঘরে, অথবা তোমাদের মামাদের ঘরে, অথবা তোমাদের খালাদের ঘরে, অথবা সে ঘরে যা তোমাদের আর যার চাবি তোমাদের কাছে আছে, অথবা তোমাদের বন্ধুদের ঘরে। তোমরা কোন ভুল করো না একসাথে বা আলাদাভাবে আহার করে। যখন তোমরা কোন ঘরে প্রবেশ করো, তোমরা পরস্পরকে অভিবাদন জানাবে আল্লাহর পক্ষ থেকে পাওয়া সে অভিবাদনের মাধ্যমে, যা পবিত্র ও মঙ্গলময়। আল্লাহ এভাবে  প্রকাশনাবলি তোমাদের জন্য ব্যাখ্যা করেন যাতে তোমরা বুঝতে পারো।"],
  "24:62": ["Truly the muminin are those who believe in Allah and the Rasul, and who, when they are with the Rasul upon a matter that gathers them, do not go away until they ask the Rasul's leave; truly those who ask your leave are those who believe in Allah and the Rasul; so when they ask your leave for some affair of theirs, give leave to whichever of them you will, and ask Allah's forgiveness for them; truly Allah is forgiving, merciful.", "প্রকৃত বিশ্বাসী তারা যারা আল্লাহ ও তাঁর বার্তাবাহককে বিশ্বাস করে, আর যখন তার সাথে কোন সামাজিক বৈঠকে থাকে, তারা অনুমতি ছাড়া তাকে ছেড়ে যায় না। যারা অনুমতি চায় তারাই তো সে ব্যাক্তি যারা আল্লাহ ও তাঁর বার্তাবাহককে বিশ্বাস করে। যদি তারা তোমার অনুমতি চায়, তাদের কোন কাজে যাবার জন্য, তুমি যাকেই ইচ্ছা অনুমতি দিতে পার, এবং আল্লাহর কাছে তাদের জন্য ক্ষমা চাও। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "24:63": ["Do not make the calling of the Rasul among you like the calling of some of you to others; truly Allah knows those among you who slip away stealthily; so let those who differ from the Rasul's command beware, lest a trial befall them or a painful punishment strike them.", "বার্তাবাহকের অনুরোধকে সেভাবে গন্য করো না যেভাবে তোমরা পরস্পরের অনুরোধকে গন্য করো। আল্লাহ তোমাদের মধ্যে তাদের ব্যাপারে পূর্ণ অবগত যারা চুপিসারে সরে পড়ে তুচ্ছ অজুহাত দেখিয়ে। তাদেরকে সতর্ক করো- যারা তার হুকুম অমান্য করে- কেননা এক বিপর্যয় তাদের আঘাত করতে পারে, অথবা এক কঠোর শাস্তি।"],
  "24:64": ["Unquestionably to Allah belongs whatever is in the heavens and the earth; Allah has full knowledge of what you are upon; and on the day they are returned to Allah, Allah will inform them of all that they did; and Allah has knowledge of all things.", "নিঃসন্দেহে, আল্লাহর অধীনে রয়েছে আকাশমণ্ডলী ও পৃথিবীর সবকিছু। তোমরা থাকতে পারো এমন প্রত্যেক অবস্থা সম্পর্কে সম্পূর্ণরূপে তিনি জানেন। যেদিন তোমরা তাঁর কাছে ফিরে যাবে, তিনি তাদেরকে জানাবেন সে সম্পর্কে যা কিছু তারা করেছিল। আল্লাহ সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "25:1": ["Blessed be the One who sent down the Criterion upon Allah's servant, that it may be a warner to the worlds", "সবচেয়ে অনুগ্রহময় সেই সত্ত্বা যিনি তাঁর বান্দার কাছে বিধানগ্রন্থ প্রকাশ করেছেন, যাতে সে পুরো বিশ্বের কাছে একজন সতর্ককারী হিসেবে কাজে আসতে পারে।"],
  "25:2": ["The One to whom belongs the kingdom of the heavens and the earth, who took no child and has no partner in the kingdom, and created everything, then measured it with a measure", "সেই সত্ত্বা যাঁর অধীনে রয়েছে আকাশমণ্ডলী ও পৃথিবীর সার্বভৌমত্ব। কখনো তাঁর পুত্র ছিল না, না তাঁর কোন অংশীদার আছে সার্বভৌমত্বে। তিনি সবকিছু যথাযথ পরিমাপে সৃষ্টি করেছেন; তিনি সবকিছুর নকশা করেছেন সুনির্দিষ্টভাবে।"],
  "25:3": ["Yet they have taken, besides Allah, alihah that create nothing while they themselves are created, that possess for themselves neither harm nor benefit, and possess neither death nor life nor any rising", "এরপরও, তারা তাঁর পাশে উপাস্যদের স্থাপন করে যারা কোনকিছু সৃষ্টি করেনি- তারা নিজেরাই সৃষ্টি হয়েছে- এবং এমনকি তাদের নিজেদের ক্ষতি বা উপকার করারও কোন ক্ষমতা নেই, না তাদের কোন ক্ষমতা আছে জীবন, বা মৃত্যু, বা পুনরুত্থান নিয়ন্ত্রণের।"],
  "25:4": ["The kafirin say: This is nothing but a fabrication he fabricated, and other people helped him with it. So they have come with wrong and swerving falsehood", "যারা অবিশ্বাস করেছে তারা বলল, “এটি একটি মিথ্যা উদ্ভাবন যা সে তৈরী করেছে, অন্য আরোকিছু লোকের সাহায্যে।” তারা আল্লাহনিন্দা এবং এক মিথ্যাচার করেছে।"],
  "25:5": ["And they say: Tales of the ancients — he had them written down, and they are dictated to him morning and evening", "তারা আরো বলেছে, “অতীতের কল্পকাহীনি যা সে লিখে রেখেছে; তারা দিনে-রাতে তার কাছে পাঠ করতো।"],
  "25:6": ["Say: Allah sent it down — the One who knows the secret in the heavens and the earth. Allah is ever Forgiving, Raheem", "বল, \"এটি সেই সত্ত্বার দ্বারা প্রকাশিত যিনি আকাশ ও পৃথিবীর গোপন বিষয় জানেন। তিনি ক্ষমাশীল, পরম করুণাময়।\""],
  "25:7": ["And they say: What is with this Rasul — he eats food and walks in the markets? Why has no malakat been sent down to him, to be a warner beside him?", "এবং তারা বলল, \"কেমন করে এই বার্তাবাহক খাবার খায় এবং বাজারে হাটে? শুধু  যদি কোন ফেরেশতা তার সাথে আসতো, তার সাথে ধর্মপ্রচারক হিসেবে কাজ করতে।\""],
  "25:8": ["Or that a hoard be cast to him, or that there be a garden for him to eat from. And the wrongdoers say: You follow only a man under a spell", "অথবা, \"শুধু যদি তাকে একটি ধনভাণ্ডার দেয়া হতো!” অথবা, \"শুধু যদি তার একটি ফলবাগান থাকতো যা থেকে সে খেত!” সীমালঙ্ঘনকারীরা আরো বলে, \"তোমরা একজন জাদুগ্রস্থ মানুষের অনুসরণ করছো।\""],
  "25:9": ["See how they strike examples for you — they have gone astray and can find no way", "লক্ষ্য করো কিভাবে তারা তোমাকে ডেকেছিল সব ধরণের নামে, এবং কিভাবে এটি তাদের বিপথে  নিয়েছে, কখনো তাদের পথ পুনরায় পাবার মত নয়।"],
  "25:10": ["Blessed be the One who, if Allah willed, would assign to you better than that: gardens beneath which rivers flow, and would assign you palaces", "সবচেয়ে অনুগ্রহময় সেই সত্ত্বা যিনি পারেন, যদি তিনি ইচ্ছা করেন, তোমাকে তাদের দাবী থেকে অনেক উত্তম দেন- প্রবাহিত ঝর্ণাসহ বাগান, এবং অনেক প্রাসাদ।"],
  "25:11": ["No — they denied the Hour, and We readied a blaze for whoever denies the Hour", "প্রকৃতপক্ষে, তারা অবিশ্বাস করেছে সেই সময়ের (পুনরুত্থান দিনে), এবং যারা সেই  সময়ের অবিশ্বাস করে আমরা  তাদের জন্য  প্রস্তুত রেখেছি জ্বলন্ত নরক।"],
  "25:12": ["When they see it from a distant place, they hear its raging and its roaring", "যখন এটি দূর থেকে তাদেরকে দেখবে, তারা এর ক্রোধ এবং ধোঁয়ার শব্দ শুনবে।"],
  "25:13": ["And when they are cast, bound together, into a straitened place, they call there for destruction", "আর তাদেরকে যখন তাতে নিক্ষেপ করা হবে, এক সংকীর্ণ জায়গা  দিয়ে, সকলকে শিকলবদ্ধ করে, তারা তাদের অনুতাপ প্রকাশ করবে।"],
  "25:14": ["Call not today for one destruction — call for many destructions", "ঐ দিন, তোমরা শুধু একবার  অনুতাপ প্রকাশ করবে না; তোমরা অসংখ্য অনুতাপের মধ্যে দিয়ে যাবে।"],
  "25:15": ["Say: Is that better, or the Garden of Eternity that the the Raheem promised the mindful? It shall be for them a recompense and a final arrival", "বল, \"এটা ভালো, নাকি চিরস্থায়ী স্বর্গোদ্যান, যার প্রতিশ্রুতি   সৎকর্মশীলদের দেয়া হয়েছে? এটি তাদের  যথাযোগ্য পুরষ্কার; এক যথাযোগ্য নিয়তি।"],
  "25:16": ["They shall have in it whatever they will, abiding forever. That was upon your Rabb a promise to be asked for", "তারা সেখানে যাকিছু তাদের ইচ্ছা তা পায়, চিরদিন ধরে। এটি তোমার প্রভুর অলঙ্ঘনীয় অঙ্গীকার।"],
  "25:17": ["And the day We gather them and what they worship besides Allah, Allah will say: Did you lead these servants of Mine astray, or did they stray from the way?", "সে দিন যখন তিনি তাদের একত্রে তলব করবেন, সেই সব উপাস্যদের সাথে  যাদেরকে তারা আল্লাহর পাশে স্থাপন করেছিল, তিনি বলবেন, \"তোমরা কি আমার এই বান্দাদের  বিপথে পরিচালিত করেছিলে, নাকি তারা নিজেরাই বিপথে গিয়েছিলো?\""],
  "25:18": ["They will say: Glory be to You! It was not fitting for us to take protectors besides You; but You let them and their fathers enjoy themselves until they forgot the Remembrance and became a ruined people", "তারা বলবে, \"আপনি মহিমান্বিত, এটি আমাদের জন্য ঠিক হতো না যে আমরা আপনার পাশে কোন  উপাস্য স্থাপন করি। কিন্তু, আপনি তাদেরকে উপভোগ করতে দিয়েছিলেন, তাদের মাতা-পিতার সাথে। পরিনামে, তারা সেই বার্তা উপেক্ষা করেছিল, এবং এভাবে অন্যায়কারীতে পরিনত হয়েছিল।"],
  "25:19": ["So they have already denied you in what you say, and you can neither avert anything nor find help. And whoever of you does wrong, We make that one taste a great punishment", "আপনি যে  বার্তা তাদের দিয়েছিলেন তারা তা অবিশ্বাস করেছে, এবং, পরিনামে, না তোমরা তাদেরকে তাদের টেনে আনা শাস্তি থেকে রক্ষা করতে পারবে, না তোমরা তাদেরকে কোনভাবে  সাহায্য করতে পারবে। তোমাদের মধ্যে যেকেউ মন্দ কাজ করে, আমরা তাকে কঠিন শাস্তিতে সোপর্দ করবো।"],
  "25:20": ["We never sent before you any of the Rasuls but that they ate food and walked in the markets, and We made some of you a trial for others. Will you be of the sabirin? Your Rabb is All-Seeing", "আমরা তোমার আগে কোন বার্তাবাহক পাঠাইনি যে খাবার খেতো না এবং বাজারে চলাফেরা করতো না। আমরা এভাবে তোমাদেরকে পরস্পরের মাধ্যমে পরীক্ষা করি;  তোমরা কি দৃড়তার  সাথে অবিচল থাকবে? তোমাদের প্রভু দেখেন।"],
  "25:21": ["Those who have no hope of meeting Us say: If only malakat were sent down to us, or we could see our Rabb! They have grown arrogant within themselves and waxed greatly insolent", "যারা আমাদের সাথে সাক্ষাতের আশা করে না তারা বলল, \"শুধু যদি ফেরেশতারা আমাদের কাছে নেমে আসতো, অথবা আমরা আমাদের প্রভুকে দেখতে পারতাম (তবে আমরা বিশ্বাস করতাম)!” প্রকৃতপক্ষে, তারা চরম ঔদ্ধত্য প্রকাশ করেছে, এবং তৈরি করেছে এক স্থূল অসৎকর্মশীলতা।"],
  "25:22": ["The day they see the malakat — no glad tidings that day for the mujrimin, and they will say: A barrier, barred", "যেদিন তারা ফেরেশতাদের দেখবে,  অপরাধীদের জন্য তা সুখবর হবে না; তারা বলবে, \"এখন, আমরা স্থায়ীভাবে আটকে গেছি।\""],
  "25:23": ["We will proceed to what they did of deeds and make it scattered dust", "আমরা তাদের সব কাজ দেখবো, এবং সেগুলোকে নাকচ করে দেবো।"],
  "25:24": ["The companions of the Garden that day — a better settling place and a finer resting place", "স্বর্গের বাসিন্দারা ঐদিন অনেক  উত্তম অবস্থায় থাকবে; তারা উত্তম সংবাদ শুনবে।"],
  "25:25": ["The day the sky splits open with the gloom-clouds and the malakat are sent down in a sending-down", "আকাশমণ্ডলী বিদীর্ণ হবে, মেঘপুঞ্জে, এবং ফেরেশতারা দলে দলে নেমে আসবে।"],
  "25:26": ["True rule that day belongs to the the Raheem, and it shall be a hard day for the kafirin", "ঐ দিন সকল সার্বভৌমত্ব হবে পরম করুনাময়ের অধীনে। অবিশ্বাসীদের জন্য, তা হবে এক কঠিন দিন।"],
  "25:27": ["The day the wrongdoer bites his hands and says: If only I had taken a way with the Rasul", "সেদিন আসবে যখন সীমালঙ্ঘনকারী (নিদারুন যন্ত্রণায়) নিজের হাত কামড়াবে এবং বলবে, \"হায়, আমি যদি বার্তাবাহকের পথ অনুসরণ করতাম।"],
  "25:28": ["Woe is me! If only I had not taken so-and-so for a bosom friend", "\"হায়, দূর্ভোগ আমার, আমি যদি ঐ ব্যক্তিকে আমার বন্ধু হিসেবে না নিতাম।"],
  "25:29": ["That one led me astray from the Reminder after it came to me, and Shaytan is ever a forsaker of humankind", "“সে আমাকে বার্তা থেকে দূরে সরিয়ে দিয়েছে তা আমার কাছে আসার পর। নিশ্চয়, শয়তান তার মানব শিকারকে হতাশ করে। \""],
  "25:30": ["The Messenger will say: O my Rabb, my people took this Recitation as a forsaken thing", "বার্তাবাহক বলল, \"আমার প্রভু, আমার লোকেরা এই কুরআন পরিত্যাগ করেছে”।"],
  "25:31": ["Thus We made for every Nabi an enemy from among the mujrimin, and your Rabb suffices as Guide and Helper", "আমরা অপরাধীদের মধ্যে থেকে প্রত্যেক নবীর বিরুদ্ধে শত্রুদেরও দাড় করাই। তোমার প্রভু  একজন পথপ্রদর্শক, একজন মনিব হিসেবে যথেষ্ট।"],
  "25:32": ["The kafirin say: Why was the Recitation not sent down to him all at once, as a single whole? Thus — so that We may make it firm upon your heart — and recite it in measured recitation", "যারা অবিশ্বাস করেছে তারা বলল, “তার মাধ্যমে কুরআন পুরোটাই একবারে আসলো না কেন?”একে আমরা  ধীরে ধীরে তোমার কাছে প্রকাশ করেছি, তোমার স্মৃতিতে একে নিবদ্ধ করার জন্য। এটি একটি নির্দিষ্ট ক্রমে আমরা আবৃতি করেছি।"],
  "25:33": ["They never bring you an example but We bring you the truth and the finest interpretation", "যে যুক্তিই তারা  নিয়ে আসুক না কেন, আমরা তোমাকে সত্য, ও এক উত্তম বোধশক্তি প্রদান করি।"],
  "25:34": ["Those who are gathered on their faces toward Jahannam — those are the worst in place and the most astray in way", "যাদেরকে জোরপূর্বক নরকে তলব করা হবে তারা রয়েছে নিকৃষ্টতম অবস্থানে; সঠিক পথ থেকে এরা সবচেয়ে দূরে।"],
  "25:35": ["We gave Musa the Book and made his brother Harun a vizier beside him", "আমরা মূসাকে দিয়েছি  ঐশীগ্রন্থ, আর তার ভাই হারুনকে  নিযুক্ত করেছিলাম তার সহকারী হিসাবে।"],
  "25:36": ["We said: Go, both of you, to the people who denied Our signs — then We razed them, a razing", "আমরা বললাম, \"যাও, তোমরা দু'জনই, সে লোকদের কাছে যারা আমাদের প্রকাশনাবলি প্রত্যাখ্যান করেছে,”এবং পরবর্তীতে, প্রত্যাখ্যানকারীদেরকে আমরা পুরোপুরি ধ্বংস করে দিয়েছিলাম।"],
  "25:37": ["And the people of Nuh, when they denied the Rasuls, We drowned them and made them a sign for humankind, and We readied a painful punishment for the wrongdoers", "একইভাবে, যখন নূহের লোকেরা বার্তাবাহকদের অবিশ্বাস করেছিল, তাদেরকে আমরা ডুবিয়ে দিয়েছিলাম, এবং লোকদের জন্য আমরা তাদেরকে একটি নিদর্শন হিসাবে স্থাপন করেছিলাম। সীমালঙ্ঘনকারীদের জন্য আমরা প্রস্তুত করেছি এক যন্ত্রণাদায়ক শাস্তি।"],
  "25:38": ["And Aad and Thamud, and the people of al-Rass, and many generations between those", "আদ, সামূদ, আল-রাসের অধিবাসী, এবং তাদের মধ্যকার অনেক প্রজন্মকেও।"],
  "25:39": ["Each of them We struck examples for, and each We utterly destroyed", "এদের প্রত্যেক দলের কাছে, আমরা যথেষ্ট পরিমান উদাহরণ পাঠিয়েছিলাম, তাদেরকে আমরা ধ্বংস করার আগে।"],
  "25:40": ["They passed by the town that was rained the rain of evil — were they not seeing it? No, they had no hope of any rising", "তারা সে জনপদ পাশ দিয়ে গিয়েছে যাদের উপর বর্ষন করা হয়েছিল এক শোচনীয় বর্ষণ (সডম)। তারা কি তা দেখেনি? প্রকৃত বিষয় হচ্ছে, তারা  কখনোই পুনরুত্থানে বিশ্বাস করেনি।"],
  "25:41": ["And when they see you they take you only in mockery: Is this the one Allah sent as a Rasul?", "যখন তারা তোমাকে দেখতো, তারা সবসময় তোমাকে উপহাস করতো: \"এই ব্যক্তিকেই  কি  আল্লাহ বার্তাবাহক হবার জন্য বেছে নিয়েছেন?"],
  "25:42": ["He nearly led us astray from our alihah, had we not been sabir toward them. And they will know when they see the punishment who was most astray in way", "\"সে আমাদের উপাস্যদের থেকে আমাদেরকে প্রায় সরিয়েই দিয়েছিল, যদিনা আমরা তাদের প্রতি দৃঢ়তার সাথে অবিচল থাকতাম। তারা নিশ্চয়ই জানতে পারবে, যখন তারা শাস্তি দেখবে, কারা প্রকৃতপক্ষে পথভ্রষ্ট।"],
  "25:43": ["Have you seen the one who takes desire for a ilah? Will you be a guardian over that one?", "তুমি কি সে ব্যক্তিকে দেখেছ যার উপাস্য তার নিজের অহংবোধ? তুমি কি তার ওকালতি করবে?"],
  "25:44": ["Or do you reckon most of them hear or understand? They are only like cattle — rather, further astray in way", "তুমি কি মনে করো যে তাদের বেশিরভাগ শুনে, বা বুঝে? তারা তো কেবল পশুর মতো; না, তারা আরো অনেক নিকৃষ্ট।"],
  "25:45": ["Have you not turned to your Rabb? See how Allah spread the shadow. Had Allah willed, it would be still; then We made the sun its pointer", "তুমি কি দেখনি কিভাবে তোমার প্রভু ছায়াকে নকশা করেছেন? তিনি চাইলে, একে স্থির করে দিতে পারতেন, তাহলে সূর্যকে আমরা সেরুপে নকশা করতাম।"],
  "25:46": ["Then We draw it in toward Us, an easy drawing-in", "কিন্তু আমরা এভাবে নকশা করেছি যাতে তা ধীরে চলে।"],
  "25:47": ["Allah is the One who made the night a garment for you, and sleep a rest, and made the day a rising", "তিনিই সেই সত্ত্বা যিনি রাতকে  নকশা করেছেন একটি আবরণ হবার জন্য, এবং তোমাদের ঘুম ও বিশ্রামের জন্য। আর, তিনি দিনকে করেছেন একটি পুনরুত্থান।"],
  "25:48": ["Allah is the One who sent the wind as glad tidings before Allah's mercy, and We sent down from the sky purifying water", "তিনিই সেই সত্ত্বা যিনি তাঁর দয়ার শুভ ইংগিত দিয়ে বাতাসকে পাঠান, এবং আমরা আকাশ থেকে বিশুদ্ধ পানি অবতীর্ণ করি।"],
  "25:49": ["To give life by it to a dead town, and to give drink with it to much of what We created of livestock and people", "তা দিয়ে, আমরা মৃত ভূমিকে পুনরুজ্জীবিত করি এবং পানীয় প্রদান করি আমাদের সৃষ্টিকূল- বহুগুন পশু ও মানুষের জন্য।"],
  "25:50": ["We have turned it about among them so they might remember, yet most people refused, being nothing but kafirin", "আমরা একে তাদের মাঝে যথাযথ পরিমানে বন্টন করেছি, যাতে তারা উপদেশ গ্রহন করতে পারে। কিন্তু অধিকাংশ লোক অবিশ্বাসে অনড় থাকে।"],
  "25:51": ["Had We willed, We would have raised a warner in every town", "যদি আমরা চাইতাম, প্রত্যেক সম্প্রদায়ের কাছে আমরা একজন সতর্ককারী পাঠাতে পারতাম।"],
  "25:52": ["So do not obey the kafirin, and strive against them with it in a great striving", "একারণে, অবিশ্বাসীদের মান্য করো না, এবং এটি দিয়ে তাদের বিরুদ্ধে সংগ্রাম করো, এক মহা সংগ্রাম।"],
  "25:53": ["Allah is the One who let the two seas flow free — this one sweet and fresh, this one salty and bitter — and set between them a barrier and a barred partition", "তিনিই সে সত্ত্বা যিনি দুই সাগরকে মিলিয়ে দেন; একটি মিষ্ট ও সুস্বাদু, যখন অন্যটি লবনাক্ত ও পানের অনপুযুক্ত। আর, তিনি এদেরকে এক দুর্ভেদ্য, অনতিক্রম্য অন্তরায় (বাষ্পীভবন) দিয়ে আলাদা করেছেন।"],
  "25:54": ["Allah is the One who created from water a human being, and made that one kin by lineage and kin by marriage, and your Rabb is fully capable", "তিনিই সে সত্ত্বা যিনি পানি থেকে সৃষ্টি করেছেন মানুষকে, এরপর বিয়ে ও সংগমের দ্বারা তাকে বংশবৃদ্ধি করতে সক্ষম করেছেন। তোমার প্রভু সর্বশক্তিমান।"],
  "25:55": ["Yet they worship besides Allah what neither benefits nor harms them, and the kafir is a backer against their Rabb", "এরপরও, তারা আল্লাহর পাশে উপাস্যদের স্থাপন করে যারা না তাদের উপকার করতে পারে, না তাদের ক্ষতি করতে পারে। নিশ্চয়, অবিশ্বাসী তার প্রভুর শত্রু।"],
  "25:56": ["We sent you only as a bearer of glad tidings and a warner", "আমরা তোমাকে (রাশাদ) পাঠিয়েছি একজন সুসংবাদ বহনকারী, সেই সাথে একজন সতর্ককারী হিসেবে।"],
  "25:57": ["Say: I ask of you no wage for it, except that whoever wills may take a way to their Rabb", "বল, \"আমি তোমাদের কাছে কোন অর্থ চাই না। আমি তো কেবল তোমাদেরকে সাহায্য করতে চাই তোমাদের প্রভুর দিকে  সঠিক পথ পেতে, যদি তা তোমরা পছন্দ করো।"],
  "25:58": ["And trust in the Living One who does not die, and glorify with praise of Allah, and Allah suffices as All-Aware of the faults of the servants", "তুমি তোমার আস্থা সে সত্ত্বার উপর রাখবে যিনি জীবিত - সেই সত্ত্বা যিনি কখনো মারা যান না- আর তাঁর প্রশংসা করো এবং তাঁর মহিমা নিবেদন করো। তিনি তাঁর সৃষ্টিকূলের পাপের বিষয়ে সম্পূর্ন অবগত।"],
  "25:59": ["The One who created the heavens and the earth and what is between them in six days, then settled upon the high seat — the the Raheem — so ask concerning that one who is informed", "তিনিই সেই সত্ত্বা যিনি সৃষ্টি করেছেন আকাশমণ্ডলী ও পৃথিবী, এবং এদের মধ্যকার সবকিছু, ছয় দিনে, এরপর সকল কর্তৃত্ব গ্রহন করেছেন। পরম করুণাময় ; তাঁর বিষয়ে জিজ্ঞেস করো তাদেরকে যারা জ্ঞানে সুপ্রতিষ্ঠিত।"],
  "25:60": ["And when it is said to them: Bow down to the the Raheem, they say: And what is the the Raheem? Shall we bow to whatever you command us? And it increased them in aversion", "যখন তাদেরকে বলা হয়, \"সেজদাবনত হও পরম করুনাময়ের সামনে, তারা বলে, \"পরম করুণাময় কি? আমরা কি তাকে সেজদা করবো যার ওকালতি তুমি করো? এভাবে, এটি কেবল তাদের বিমুখতা বাড়ায়।"],
  "25:61": ["Blessed be the One who set in the sky great towers, and set in it a lamp and a luminous moon", "পরম অনুগ্রহময় সেই সত্ত্বা যিনি  আকাশে রেখেছেন নক্ষত্রপুঞ্জ, আর এতে  রেখেছেন একটি প্রদীপ, এবং এক উজ্জ্বল/দীপ্তিময় চাঁদ।"],
  "25:62": ["Allah is the One who made night and day follow in succession for whoever wills to remember or wills to be grateful", "তিনিই সে সত্ত্বা যিনি রাত এবং দিনকে  নকশা করেছেন পালা-বদল করতে: এটি যথেষ্ট প্রমান তাদের জন্য যারা উপদেশ গ্রহন করতে, বা কৃতজ্ঞ হতে চায়।"],
  "25:63": ["The servants of the the Raheem are those who walk upon the earth lightly, and when the ignorant address them, they say: Peace", "তারাই পরম করুণাময়ের উপাসনাকারী যারা পৃথিবীতে নম্রভাবে হাটে, আর যখন অজ্ঞরা তাদের সাথে কথা বলে, তারা কেবল বলে শান্তি।"],
  "25:64": ["And those who pass the night before their Rabb, bowing and standing", "রাতের একান্তে, তাদের প্রভুর বিষয়ে ধ্যান করে, এবং সেজদাবনত হয়।"],
  "25:65": ["Those who say: Our Rabb, avert from us the punishment of Jahannam — its punishment is a binding liability", "আর তারা বলে, \"আমাদের প্রভু, আমাদেরকে নরকের যন্ত্রণা থেকে নিষ্কৃতি দিন; এর শাস্তি ভয়ংকর।"],
  "25:66": ["Evil it is as a settling place and a dwelling", "এটি নিকৃষ্টতম আবাস; নিকৃষ্টতম নিয়তি।\""],
  "25:67": ["Those who, when they spend, neither exceed nor hold back, but hold to the just stand between the two", "তারা যখন দেয়, তারা না অপব্যয় করে, না কৃপণতা করে; তারা দেয় পরিমিত পরিমানে।"],
  "25:68": ["Those who call upon no other ilah with Allah, and kill not the soul Allah has forbidden except by right, and commit not adultery. Whoever does that will meet a load of sin", "তারা কখনো আল্লাহর পাশে অন্য কোন উপাস্যের কাছে মিনতি করে না, না তারা কোন আত্মাকে হত্যা করে- কারন আল্লাহ জীবনকে পবিত্র/অতি মূল্যবান করেছেন- বিচার প্রক্রিয়া ছাড়া। না তারা ব্যাভিচার করে। এ অপরাধগুলো যারা করে তাদেরকে মূল্য দিতে হবে।"],
  "25:69": ["The punishment is doubled for that one on the Day of Standing, and that one abides in it, humiliated", "তাদের জন্য পুনরুত্থান দিনে শাস্তি দ্বিগুন করা হয়, আর সেখানে তারা বাস করে অপদস্থ অবস্থায়।"],
  "25:70": ["Except whoever turns back and believes and does a salih deed — those, Allah will change their evils into good deeds, and Allah is Forgiving, Raheem", "তারা ছাড় পাবে যারা অনুশোচনা করে, বিশ্বাস করে, এবং সৎ জীবন-যাপন করে। আল্লাহ তাদের পাপগুলোকে কৃতিত্বে রূপান্তর করেন। আল্লাহ ক্ষমাকারী, সবচেয়ে দয়ালু।"],
  "25:71": ["And whoever turns back and does salihness — that one turns to Allah in a true turning", "যারা অনুশোচনা করে এবং সৎ জীবন-যাপন করে, আল্লাহ তাদেরকে উদ্ধার করেন; পরিপূর্ণভাবে।"],
  "25:72": ["Those who do not witness falsehood, and when they pass by idle talk, they pass on with dignity", "তারা মিথ্যা সাক্ষী দেয় না। যখন তারা অনর্থক কথার মুখোমুখি হয়, তারা তা উপেক্ষা করে।"],
  "25:73": ["Those who, when reminded of their Rabb's signs, do not fall upon them deaf and unseeing", "যখন তাদের প্রভুর প্রত্যাদেশাবলি স্মরণ করিয়ে দেয়া হয়, তারা কখনো সেগুলোর প্রতি  বধির ও অন্ধের মতো প্রতিক্রিয়া  করে না।"],
  "25:74": ["Those who say: Our Rabb, grant us from our spouses and our offspring a comfort of the eyes, and make us leaders of the mindful", "আর তারা বলে, “আমাদের প্রভু, আমাদের জন্য আমাদের সহধর্মী/সহধর্মীনি ও সন্তানদেরকে আনন্দের উৎস করুন, এবং আমাদেরকে সৎ-কর্মীদের অগ্রভাগে রাখুন\"।"],
  "25:75": ["Those are recompensed the chambers above for their patience, and meet therein greeting and peace", "এরা সে  ব্যক্তি যারা তাদের অবিচলতার বিনিময়ে স্বর্গ অর্জন করে; সেখানে তাদেরকে আনন্দঘন সম্ভাষন ও শান্তিপূর্ণ ভাবে গ্রহণ করা হয়।"],
  "25:76": ["Abiding therein — fair the settling place and good the dwelling", "চিরকাল তারা সেখানে বসবাস করে; কতই না চমৎকার নিয়তি; কতই না চমৎকার আবাস।"],
  "25:77": ["Say: My Rabb would have no care for you were it not for your calling. You have denied — so soon it will cling fast to you", "বল, “আমার প্রভুর নিকট তোমাদের উপাসনা দ্বারাই কেবল তোমরা মূল্য অর্জন করো। কিন্তু যদি তোমরা অবিশ্বাস করো, তোমরা টেনে আনবে অনিবার্য পরিনাম।\""],
  "26:1": ["Ta Sin Mim", "ত. স.ম."],
  "26:2": ["These are the signs of the clear Book", "এইসব (অক্ষরগুলো) এই সুস্পষ্টকারী ঐশীগ্রন্থের প্রমাণাদি গঠন করে।"],
  "26:3": ["Perhaps you would kill yourself with grief that they will not be muminin", "তুমি হয়তো নিজেকে দোষ দিবে যে তারা বিশ্বাসী নয়।"],
  "26:4": ["If We will, We shall send down upon them from the sky a sign, and their necks will become humbled to it", "যদি আমরা চাই, আমরা আকাশ থেকে একটি নিদর্শন পাঠাতে পারি যা বলপূর্বক তাদের ঘাড়কে অবনত করবে।"],
  "26:5": ["And there comes to them no newly-arriving reminder from the Rahman but they turn away from it", "যখনই পরম করুণাময়ের পক্ষ থেকে কোন স্মারক তাদের কাছে আসে, যা নতুন, তারা অনীহায় মুখ ফিরিয়ে নেয়।"],
  "26:6": ["So they have denied; and there will come to them tidings of what they used to mock", "যেহেতু তারা অবিশ্বাস করেছে, তারা তাদের অমনোযোগীতার পরিণাম ডেকে এনেছে।"],
  "26:7": ["Have they not seen the earth, how much We have grown in it of every honored kind", "তারা কি পৃথিবীটা দেখেনি, এবং সেখানে কত ধরনের সুন্দর উদ্ভিদ আমরা জন্মিয়েছি?"],
  "26:8": ["Indeed in that is a sign, and most of them were not muminin", "এটা তাদের জন্য যথেষ্ট প্রমান হওয়া উচিৎ, কিন্তু তাদের বেশির ভাগ বিশ্বাসী নয়।"],
  "26:9": ["And your Rabb is the Mighty, the Raheem", "অত্যন্ত নিশ্চিত ভাবে, তোমার প্রভু সর্বশক্তিমান, পরম দয়ালু।"],
  "26:10": ["And when your Rabb called Musa: Go to the wrongdoing people", "স্মরণ করো যে তোমার প্রভু মুসাকে ডেকেছিলেনঃ “সীমালঙ্ঘনকারী লোকদের কাছে যাও”।"],
  "26:11": ["The people of Fir'awn — will they not fear", "“ফেরাউনের  লোকেরা; হয়তো তারা সংশোধিত হবে।”"],
  "26:12": ["He said: My Rabb, I fear that they will deny me", "সে বলল, “আমার প্রভু, আমার ভয় হয় পাছে তারা আমাকে অবিশ্বাস করে।"],
  "26:13": ["And my chest is straitened and my tongue will not set out, so send to Harun", "“আমার মেজাজ বিগড়ে যেতে পারে। আমার জিহবা আটকে যায়; আমার ভাই হারুনকে ডেকে পাঠান।"],
  "26:14": ["And they hold a charge against me, so I fear they will kill me", "“তাছাড়া, তারা আমাকে একজন পলাতক হিসাবে দেখে; আমার ভয় হয় পাছে তারা আমাকে হত্যা করে।”"],
  "26:15": ["Allah said: Nay — so go, both of you, with Our signs; We are with you, hearing", "তিনি বললেন, “না, (তারা তা করবে না)। আমার প্রমাণাদি নিয়ে যাও। আমরা তোমাদের সাথে থাকবো, শুনবো।"],
  "26:16": ["So go, both of you, to Fir'awn and say: We are rusul of the Rabb of the worlds", "“ফেরাউনের কাছে যাও এবং বলো, ‘আমরা মহাবিশ্বের প্রভুর পক্ষ থেকে বার্তাবাহক।"],
  "26:17": ["That you send with us the children of Israel", "“‘ইসরাইলের সন্তানদের যেতে দাও।’”"],
  "26:18": ["Fir'awn said: Did we not raise you among us as a child, and you tarried among us years of your life-term", "সে বলল, “আমরা কি শিশুকাল থেকে তোমাকে বড় করিনি, আর তুমি আমাদের সাথে বহু বছর থেকেছ?"],
  "26:19": ["And you did your deed that you did, and you are of the unmuminin", "“এরপর তোমার যা অপরাধ তা তুমি করেছ, এবং তুমি ছিলে অকৃতজ্ঞ।”"],
  "26:20": ["Musa said: I did it when I was of the dallin", "সে বলল, “নিশ্চয়, আমি তা করেছিলাম যখন আমি পথভ্রষ্ট ছিলাম।"],
  "26:21": ["So I fled from you when I feared you; then my Rabb granted me judgment and made me one of the Rasuls", "“এরপর আমি তোমাদের ভয়ে পালালাম, এবং আমার প্রভু আমাকে প্রজ্ঞা দান করলেন এবং আমাকে করলেন বার্তাবাহকদের একজন।"],
  "26:22": ["And is that the favor you hold over me — that you enslaved the children of Israel", "“তুমি অহংকার করছো যে তুমি আমাকে অনুগ্রহ করেছিলে, অথচ ইসরাইলের সন্তানদের দাস করে রেখেছো!”"],
  "26:23": ["Fir'awn said: And what is the Rabb of the worlds", "ফেরাউন বলল, “মহাবিশ্বের প্রভু কি?”"],
  "26:24": ["Musa said: The Rabb of the heavens and the earth and what is between them, if you are certain", "সে বলল, “আকাশমণ্ডলী ও পৃথিবী, এবং এদের মধ্যকার সবকিছুর প্রভু। এ বিষয়ে তোমাদের নিশ্চিত হওয়া উচিত।\""],
  "26:25": ["Fir'awn said to those around him: Do you not hear", "সে তার চারপাশে যারা ছিল তাদের বলল, “তোমরা কি এমনকিছু শুনেছো?”"],
  "26:26": ["Musa said: Your Rabb and the Rabb of your ancient fathers", "সে বলল, “তোমাদের প্রভু এবং তোমাদের পূর্বপুরুষদের প্রভু।”"],
  "26:27": ["Fir'awn said: Your Rasul who was sent to you is surely a madman", "সে বলল, “তোমাদের  বার্তাবাহক যাকে তোমাদের কাছে পাঠানো হয়েছে সে  পাগল।\""],
  "26:28": ["Musa said: The Rabb of the east and the west and what is between them, if you reason", "সে বলল, “পূর্ব ও পশ্চিম, এবং এদের মধ্যকার সবকিছুর প্রভু, যদি তোমরা বুঝো।”"],
  "26:29": ["Fir'awn said: If you take a ilah other than me, I shall surely make you one of the imprisoned", "সে বলল, “যদি তুমি কোন উপাস্য গ্রহন করো, আমাকে ছাড়া, আমি তোমাকে কারারুদ্ধ করবো।”"],
  "26:30": ["Musa said: Even if I bring you something clear", "সে বলল, “আমি যদি তোমাকে প্রগাঢ় কিছু দেখাই?”"],
  "26:31": ["Fir'awn said: Then bring it, if you are of the sadiqin", "সে বলল, “তাহলে তা দেখাও, যদি তুমি সত্যবাদী হয়ে থাকো।”"],
  "26:32": ["So he cast his staff, and there it was, a clear serpent", "সে তখন তার লাঠি নিক্ষেপ করলো, যার ফলে এটি এক দৃশ্যমান সাপে পরিণত হলো।"],
  "26:33": ["And he pulled out his hand, and there it was, white for the onlookers", "আর সে তার হাত বের করলো, এবং এটি দর্শকদের কাছে শুভ্র দেখাল।"],
  "26:34": ["Fir'awn said to the chiefs around him: This is surely a knowing sorcerer", "সে তার চারপাশের সভাসদদের বলল, “এ এক অভিজ্ঞ যাদুকর।"],
  "26:35": ["He intends to drive you out of your land by his sorcery — so what do you order", "“সে তোমাদেরকে তোমাদের দেশ থেকে বের করে নিতে চায়, তার যাদু দিয়ে। তোমাদের পরামর্শ কি?”"],
  "26:36": ["They said: Postpone him and his brother, and send into the towns gatherers", "তারা বলল, “তাকে ও তার ভাইকে অবকাশ দিন, এবং আহবানকারী পাঠান প্রত্যেক শহরে।"],
  "26:37": ["Who will bring you every knowing sorcerer", "“তারা ডেকে আনুক প্রত্যেক অভিজ্ঞ যাদুকরকে।”"],
  "26:38": ["So the sorcerers were gathered for the appointed time of a known day", "যাদুকরদের জড়ো করা হলো নির্ধারিত সময়ে, নির্ধারিত দিনে।"],
  "26:39": ["And it was said to the people: Will you gather", "লোকদের বলা হলো: “প্রত্যেকে আসো; চল একসাথে সবাই এখানে জড়ো হই।"],
  "26:40": ["So that we may follow the sorcerers, if they are the overcomers", "“হয়তো আমরা জাদুকরদের অনুসরণ করবো, যদি তারা জয়ী হয়।”"],
  "26:41": ["So when the sorcerers came, they said to Fir'awn: Is there for us a reward if we are the overcomers", "যখন যাদুকররা আসলো, তারা ফেরাউনকে বলল, \"আমাদেরকে কি কিছু দেওয়া হবে, যদি আমরাই বিজয়ী  হই? ”"],
  "26:42": ["Fir'awn said: Yes — and you shall then be among the brought-near", "সে বলল, “হ্যা নিশ্চয়; এমনকি তোমরা আমার কাছের হবে।”"],
  "26:43": ["Musa said to them: Cast whatever you are casting", "মূসা তাদেরকে বলল, “ছুঁড়ো যা তোমরা ছুড়তে যাচ্ছ।”"],
  "26:44": ["So they cast their ropes and their staffs, saying: By the might of Fir'awn, we shall surely be the overcomers", "তারা তাদের রশি ও লাঠি ছুড়লো, এবং বলল, “মহামান্য ফেরাউন শপথ, আমরাই বিজয়ী হবো।"],
  "26:45": ["So Musa cast his staff, and there it was, swallowing what they were fabricating", "মূসা তার  লাঠি ছুড়লো, যার ফলে এটি গিলে ফেললো যা তারা বানিয়েছিল।"],
  "26:46": ["Then the sorcerers were thrown down, prostrating", "যাদুকররা সেজদায় পড়লো।"],
  "26:47": ["They said: We believe in the Rabb of the worlds", "তারা বলল, \"আমরা মহাবিশ্বের প্রভুকে বিশ্বাস করি।"],
  "26:48": ["The Rabb of Musa and Harun", "\"মূসা এবং হারুনের প্রভু।\""],
  "26:49": ["Fir'awn said: You believed him before I gave you leave? He is your chief, the one who taught you sorcery! Soon you will know: I shall cut off your hands and your feet from behind, and I shall crucify you all together", "সে বলল, \"আমি তোমাদের অনুমতি দেয়ার আগেই কি তোমরা তার সাথে বিশ্বাস করলে? সে নিশ্চয় তোমাদের শিক্ষক হবে, যে তোমাদেরকে যাদু শিখিয়েছে। নিশ্চয় তোমরা দেখতে পাবে। আমি বিপরীত দিক থেকে তোমাদের হাত ও পা  কাটবো। তোমাদের সবাইকে আমি ক্রুশবিদ্ধ করবো। \""],
  "26:50": ["They said: No harm — to our Rabb we are turning", "তারা বলল, “তা আমাদের সিদ্ধান্ত পরিবর্তণ করবে না; আমরাতো আমাদের প্রভুর নিকট ফিরে যাবো।"],
  "26:51": ["We hope that our Rabb will forgive us our errors, that we were the first of the muminin", "“আমরা আশা করি যে আমাদের প্রভু আমাদের পাপগুলো মাফ করবেন, বিশেষত যখন আমরাই প্রথম বিশ্বাসী।”"],
  "26:52": ["And We revealed to Musa: Set out by night with My servants — you will indeed be followed", "আমরা মূসাকে প্রত্যাদেশ করলামঃ “আমার বান্দাদের নিয়ে যাত্রা করো; তোমাদের পিছু নেয়া হবে।”"],
  "26:53": ["So Fir'awn sent into the towns gatherers", "ফেরাউন শহরগুলোতে আহ্বানকারী পাঠালো।"],
  "26:54": ["These are a small band, few indeed", "(ঘোষনা করতে যে,) “এটি ছোট একটা চক্র।"],
  "26:55": ["And they are surely a rage to us", "তারা এখন আমাদের বিরোধীতা করছে।"],
  "26:56": ["And we are surely all on guard", "আসো আমরা সবাই এদের বিষয়ে সতর্ক হই।”"],
  "26:57": ["So We brought them out of gardens and springs", "পরিনামে, আমরা তাদেরকে বঞ্চিত করেছি বাগান ও ঝর্ণা থেকে।"],
  "26:58": ["And hoards, and a noble station", "আর সম্পদ ও  সম্মানিত অবস্থান থেকে।"],
  "26:59": ["Thus — and We made the children of Israel inherit them", "এরপর আমরা একে ইসরাইলের সন্তানদের জন্য একটি উত্তরাধিকার করলাম।"],
  "26:60": ["So they pursued them at sunrise", "তারা তাদেরকে পূর্বদিকে ধাওয়া করলো।"],
  "26:61": ["So when the two hosts came in sight of each other, the companions of Musa said: We are surely overtaken", "যখন উভয় দল একে অন্যকে দেখলো, মূসার লোকেরা বলল, “আমরা ধরা পড়ে যাবো।”"],
  "26:62": ["Musa said: Nay! My Rabb is with me — Allah will guide me", "সে বলল, “কোনভাবেই না। আমার প্রভু আমার সাথে আছেন; তিনি আমাকে পথ দেখাবেন।’’"],
  "26:63": ["So We revealed to Musa: Strike the sea with your staff. And it split open, and each part became like the great towering rock", "আমরা তখন মূসাকে প্রত্যাদেশ করলামঃ “তোমার লাঠি দিয়ে সাগরে আঘাত করো,” যারফলে এটি ভাগ হয়ে গেলো। প্রত্যেক ভাগ ছিল এক বিশাল পাহাড়ের মতো।"],
  "26:64": ["And We brought the others near", "তখন আমরা তাদের সবাইকে পার করালাম।"],
  "26:65": ["And We delivered Musa and all who were with him", "এভাবে আমরা মূসাকে এবং তার সাথে যারা ছিল সকলকে বাচালাম।"],
  "26:66": ["Then We drowned the others", "আর আমরা অন্যদের ডুবিয়ে দিলাম।"],
  "26:67": ["Indeed in that is a sign, and most of them were not muminin", "এটি যথেষ্ট প্রমান হওয়া উচিত, কিন্তু অধিকাংশ লোকই বিশ্বাসী নয়।"],
  "26:68": ["And your Rabb is the Mighty, the Raheem", "অত্যন্ত নিশ্চিতভাবে, তোমার প্রভু সর্বশক্তিমান, সবচেয়ে দয়ালু।"],
  "26:69": ["And relate to them the account of Ibrahim", "তাদের কাছে ইব্রাহিমের ইতিহাস বর্ণনা করো।"],
  "26:70": ["When he said to his father and his people: What do you serve", "সে তার পিতা ও তার লোকদের বলেছিল, “এটা কিসের উপাসনা  তোমরা  করছো?”"],
  "26:71": ["They said: We serve idols, and we stay cleaving to them", "তারা বলল, “আমরা মূর্তির উপাসনা করি; আমরা এদের প্রতি সম্পূর্ণ  নিবেদিত।"],
  "26:72": ["He said: Do they hear you when you call", "সে বলল, “তোমরা যখন প্রার্থনা করো তারা কি শুনতে পায়?”"],
  "26:73": ["Or do they benefit you, or harm you", "তারা কি তোমাদের উপকার, বা ক্ষতি করতে পারে?”"],
  "26:74": ["They said: Rather, we found our fathers doing likewise", "তারা বলল, “না; কিন্ত আমরা আমাদের পিতা-মাতাকে এটি করতে দেখেছি।”"],
  "26:75": ["He said: Have you considered what you have been serving", "সে বলল, “তোমরা কি এইসব উপাস্যদের দেখো, তোমরা যাদের উপাসনা করো।"],
  "26:76": ["You and your ancient fathers", "“তোমরা এবং তোমাদের পূর্বপুরুষরা।"],
  "26:77": ["Then they are an enemy to me, except the Rabb of the worlds", "আমি তাদের বিরুদ্ধে, কারণ আমি কেবল মহাবিশ্বের প্রভুর প্রতিই নিবেদিত।"],
  "26:78": ["The One who created me, so Allah will guide me", "সেই সত্ত্বা যিনি আমায় সৃষ্টি করেছেন, এবং আমাকে পথ দেখিয়েছেন।"],
  "26:79": ["And the One who feeds me and gives me drink", "সেই সত্ত্বা যিনি আমাকে খাবার দেন এবং আমাকে পানি দেন।"],
  "26:80": ["And when I am sick, Allah heals me", "“আর যখন আমি অসুস্থ হই, তিনি আমাকে নিরাময় করেন।"],
  "26:81": ["And the One who puts me to death, then brings me to life", "“সেই সত্ত্বা যিনি আমাকে মৃত্যু দেন, এরপর আবার আমাকে জীবন দেন।"],
  "26:82": ["And the One in whom I hope will forgive me my fault on the day of judgment", "“সেই সত্ত্বা যিনি বিচার দিনে আশা করি   আমার পাপগুলো ক্ষমা করে দেবেন।"],
  "26:83": ["My Rabb, grant me judgment and join me with the salihin", "“আমার প্রভু, আমাকে প্রজ্ঞা দান করূন, এবং আমাকে সৎকর্মশীলদের অন্তর্ভূক্ত করুন।"],
  "26:84": ["And make for me a tongue of truth among the later ones", "“আমি যেন ভবিষ্যৎ প্রজন্মের জন্য একটি ভাল উদাহরণ স্থাপন করি।"],
  "26:85": ["And make me one of the inheritors of the garden of bliss", "“আমাকে পরম সুখের স্বর্গের উত্তরাধিকারীদের একজন করুন।"],
  "26:86": ["And forgive my father — he was of the dallin", "“আর আমার পিতাকে ক্ষমা করুন, যেহেতু সে বিপথে গিয়েছে।"],
  "26:87": ["And do not disgrace me on the day they are raised", "“এবংপুনরুত্থান দিনে আমাকে পরিত্যাগ করবেন না।”"],
  "26:88": ["The day when neither wealth nor children avail", "এটা সে দিন যখন না অর্থ, না সন্তানাদি, সাহায্য করতে পারবে।"],
  "26:89": ["Except one who comes to Allah with a sound heart", "কেবল তারা (রক্ষা পাবে) যারা তাদের পুরো হৃদয় সহ আল্লাহর কাছে আসে।"],
  "26:90": ["And the garden is brought near to the ones who fear", "সৎকর্মশীলদের কাছে স্বর্গ উপাস্থাপন করা হবে।"],
  "26:91": ["And the blaze comes forth for the misled", "পথভ্রষ্টদের জন্য নরক স্থাপন করা হবে।"],
  "26:92": ["And it is said to them: Where is what you used to serve", "তাদেরকে জিজ্ঞেস করা হবে, “তোমাদের উপাস্যরা কোথায় তোমরা যাদের উপাসনা করতে।"],
  "26:93": ["Apart from Allah? Will they help you, or help themselves", "“আল্লাহর পাশে? তারা কি এখন তোমাদের সাহায্য করতে পারে? তারা কি তাদের নিজেদের সাহায্য করতে পারে?”"],
  "26:94": ["So they are hurled into it — they and the misled ones", "তাদেরকে তার মধ্যে নিক্ষেপ করা হবে, পথভ্রষ্টদের সাথে একসঙ্গে।"],
  "26:95": ["And all the hosts of Iblis", "আর শয়তানের সকল সৈন্যদের।"],
  "26:96": ["Saying, while in it they contend", "তারা বলবে যেহেতু তারা সেখানে কলহ করবে,"],
  "26:97": ["By Allah, we were surely in clear astray", "“আল্লাহর শপথ, আমরা অনেক পথভ্রষ্ট ছিলাম।"],
  "26:98": ["When we made you equal with the Rabb of the worlds", "“কিভাবে আমরা তোমাদেরকে মহাবিশ্বের প্রভুর সাথে সমকক্ষ করতে পারলাম?"],
  "26:99": ["And nothing misled us but the mujrimin", "“যারা আমাদেরকে ভুল পথে চালিয়েছিল তারা ছিল অন্যায়কারী।"],
  "26:100": ["So we have no intercessors", "“এখন আমাদের কোন সুপারিশকারি নাই।"],
  "26:101": ["And no devoted bosom-friend", "“না কোন অন্তরঙ্গ বন্ধু।"],
  "26:102": ["If only we had a turn back, that we might be among the muminin", "“যদি শুধু আমরা আরেকটি সুযোগ পেতাম, আমরা তবে বিশ্বাস করতাম”"],
  "26:103": ["Indeed in that is a sign, and most of them were not muminin", "এটি একটি ভালো শিক্ষা হওয়া উচিত। কিন্তু অধিকাংশ লোক বিশ্বাসী নয়।"],
  "26:104": ["And your Rabb is the Mighty, the Raheem", "তোমার প্রভু সর্বশক্তিমান, সবচেয়ে দয়ালু।"],
  "26:105": ["The people of Nuh denied the Rasuls", "নূহের লোকেরা বার্তাবাহকদের অবিশ্বাস করেছিলো।"],
  "26:106": ["When their brother Nuh said to them: Will you not fear", "তাদের ভাই নূহ তাদেরকে বলল, “তোমরা কি সৎকর্মশীল হবে না?"],
  "26:107": ["I am to you a Rasul, trustworthy", "“আমি তোমাদের প্রতি এক বিশ্বস্ত বার্তাবাহক।।"],
  "26:108": ["So fear Allah and obey me", "“তোমরা আল্লাহকে ভক্তি করবে এবং আমাকে মান্য করবে।"],
  "26:109": ["And I ask you no reward for it — my reward is only upon the Rabb of the worlds", "“আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না। আমার পারিশ্রমিক আসে মহাবিশ্বের প্রভুর কাছ থেকে।"],
  "26:110": ["So fear Allah and obey me", "“তোমরা আল্লাহকে ভক্তি করবে এবং আমাকে মান্য করবে।”"],
  "26:111": ["They said: Shall we believe you, when the vilest ones follow you", "তারা বলল, “কিভাবে আমরা তোমার সাথে বিশ্বাস করতে পারি, যখন আমাদের মধ্যে যারা নিকৃষ্ট তারা তোমাকে অনুসরণ করেছে?”"],
  "26:112": ["He said: And what knowledge have I of what they used to do", "সে বলল, “তারা কি করেছে আমি  কেমন করে জানবো?"],
  "26:113": ["Their reckoning is only upon my Rabb — if only you perceived", "“তাদের বিচারের ভার তো কেবল আমার প্রভুর কাছে, যদি তোমরা অনুধাবন করতে পারতে।"],
  "26:114": ["And I am not one to drive away the muminin", "“আমি কখনো বিশ্বাসীদের অগ্রাহ্য করবো না।"],
  "26:115": ["I am only a clear warner", "“আমি একজন স্পষ্ট সতর্ককারীর চেয়ে বেশি কিছু নই।”"],
  "26:116": ["They said: If you do not desist, Nuh, you shall be among the stoned ones", "তারা বলল, “যদি না তুমি বিরত হও, হে নূহ, তোমাকে পাথর মারা হবে।”"],
  "26:117": ["He said: My Rabb, my people have denied me", "সে বলল, “আমার প্রভু, আমার লোকেরা আমাকে অবিশ্বাস করেছে।"],
  "26:118": ["So decide between me and them with a decisive decision, and deliver me and those with me of the muminin", "“আমাকে তাদের বিরুদ্ধে বিজয় দান করুন, আর আমাকে এবং আমার বিশ্বাসী সাথীদের উদ্ধার করুন।”"],
  "26:119": ["So We delivered him and those with him in the laden ship", "আমরা উদ্ধার করেছিলাম তাকে এবং তাদেরকে যারা তার সাথে ছিল বোঝাইকৃত নৌকায়।"],
  "26:120": ["Then We drowned the rest", "এরপর আমরা অন্যদের ডুবিয়ে দিয়েছিলাম।"],
  "26:121": ["Indeed in that is a sign, and most of them were not muminin", "এটা একটা শিক্ষা হওয়া উচিত, কিন্তু অধিকাংশ লোক বিশ্বাসী নয়।"],
  "26:122": ["And your Rabb is the Mighty, the Raheem", "অত্যন্ত নিশ্চিতভাবে, তোমার প্রভু সর্বশক্তিমান, সবচেয়ে দয়ালু।"],
  "26:123": ["Ad denied the Rasuls", "আদ জাতি  বার্তাবাহকদের অবিশ্বাস করেছিল।"],
  "26:124": ["When their brother Hud said to them: Will you not fear", "তাদের ভাই হুদ তাদেরকে বলেছিল, \"তোমরা কি সৎকর্মশীল হবে না?"],
  "26:125": ["I am to you a Rasul, trustworthy", "\"আমি তোমাদের কাছে এক বিশ্বস্ত বার্তাবাহক।"],
  "26:126": ["So fear Allah and obey me", "তোমরা আল্লাহকে ভক্তি করবে, এবং আমাকে মান্য করবে।"],
  "26:127": ["And I ask you no reward for it — my reward is only upon the Rabb of the worlds", "\"আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না; আমার পারিশ্রমিক আসে মহাবিশ্বের প্রভুর কাছ থেকে।"],
  "26:128": ["Do you build on every height a landmark, amusing yourselves", "\"তোমরা প্রত্যেক পাহাড়ে অট্রালিকা বানাও অহমিকা ভরে।"],
  "26:129": ["And you take grand works, that perhaps you may live forever", "\"তোমরা দালান বানাও এমন ভাবে যেন তোমরা চিরকাল টিকে থাকবে।"],
  "26:130": ["And when you seize, you seize as overpowering ones", "\"আর যখন তোমরা আঘাত করো, তোমরা আঘাত করো নির্দয়ভাবে।"],
  "26:131": ["So fear Allah and obey me", "\"তোমরা আল্লাহকে ভক্তি করবে এবং আমাকে মান্য করবে।"],
  "26:132": ["And fear the One who supplied you with what you know", "\"সে সত্ত্বাকে ভক্তি করো যিনি তোমাদের প্রদান করেছেন সে সবকিছু যা তোমরা জানো।"],
  "26:133": ["Supplied you with cattle and sons", "\"তিনি তোমাদেরকে গৃহপালিত পশু ও সন্তানাদি প্রদান করছেন।"],
  "26:134": ["And gardens and springs", "\"আর বাগান ও ঝর্ণাসমূহ।"],
  "26:135": ["I fear for you the punishment of a mighty day", "\"আমি তোমাদের জন্য এক ভয়ানক দিনের শাস্তির ভয় করি।\""],
  "26:136": ["They said: It is all one to us whether you admonish or are not among the admonishers", "তারা বলল, \"তুমি প্রচার করো আর না করো উভয় সমান।"],
  "26:137": ["This is nothing but the creation of the ancients", "\"ঐ দূর্ভোগ আমাদের পূর্বপুরুষ পর্যন্তই সীমাবদ্ধ ছিল।"],
  "26:138": ["And we shall not be punished", "\"কখনোই কোন শাস্তি আমাদের উপর  আসবে না।\""],
  "26:139": ["So they denied him, and We destroyed them. Indeed in that is a sign, and most of them were not muminin", "এভাবে তারা অবিশ্বাস করলো এবং, পরিনামে, আমরা তাদেরকে ধ্বংস করলাম। এটি একটি শিক্ষা হওয়া উচিত, কিন্তু অধিকাংশ লোক বিশ্বাসী নয়।"],
  "26:140": ["And your Rabb is the Mighty, the Raheem", "অত্যন্ত নিশ্চিতভাবে, তোমার প্রভু সর্বশক্তিমান, সবচেয়ে দয়ালু।"],
  "26:141": ["Thamud denied the Rasuls", "সামূদ জাতি বার্তাবাহকদের অবিশ্বাস করেছিল।"],
  "26:142": ["When their brother Salih said to them: Will you not fear", "তাদের ভাই সালেহ তাদেরকে বলেছিল, \"তোমরা কি সৎকর্মশীল হবে না?"],
  "26:143": ["I am to you a Rasul, trustworthy", "\"আমি তোমাদের কাছে একজন বিশ্বস্ত বার্তাবাহক।"],
  "26:144": ["So fear Allah and obey me", "\"তোমরা আল্লাহকে ভক্তি করবে, এবং আমাকে মান্য করবে।"],
  "26:145": ["And I ask you no reward for it — my reward is only upon the Rabb of the worlds", "আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না; আমার পারিশ্রমিক কেবল মহাবিশ্বের প্রভুর কাছ থেকে আসে।"],
  "26:146": ["Will you be left secure in what is here", "তোমরা কি ধরে নিচ্ছ যে, তোমরা চিরকাল এই অবস্থায় নিরাপদে রয়ে যাবে?"],
  "26:147": ["In gardens and springs", "\"তোমরা বাগান ও ঝর্ণাসমূহ উপভোগ করো।"],
  "26:148": ["And crops and palms whose spathes are tender", "\"আর শস্যাদি ও সুস্বাদু ফল সহ খেঁজুর গাছ।"],
  "26:149": ["And you hew houses from the rocky landforms, skillfully", "\"তোমরা পর্বতসমুহে বিলাসবহুল অট্রালিকা খোদাই করো।"],
  "26:150": ["So fear Allah and obey me", "\"তোমরা আল্লাহকে ভক্তি করবে, এবং আমাকে মান্য করবে।"],
  "26:151": ["And do not obey the command of the exceeders", "\"সীমালঙ্ঘনকারীদের মান্য করো না।"],
  "26:152": ["Who corrupt in the earth and do not set right", "\"যারা ভালো কাজ নয়, মন্দ করে।"],
  "26:153": ["They said: You are only one of the bewitched ones", "তারা বলল, \"তুমি যাদুগ্রস্থ।"],
  "26:154": ["You are only a human like us — so bring a sign, if you are of the sadiqin", "\"তুমি আমাদের মতো মানুষের চেয়ে বেশি কিছু নও। একটি অলৌকিকতা দেখাও, যদি তুমি সত্যবাদী হও।\""],
  "26:155": ["He said: This is a naqah — she has her drinking-place and you have your drinking-place on a known day", "সে বলল, \"এই যে একটি উট যেটা এর জন্য নির্ধারিত দিনটিতেই শুধু পান করবে; সে দিনটি যা পান করার জন্য তোমাদের নির্দিষ্ট দিনগুলো থেকে আলাদা।"],
  "26:156": ["And do not touch her with harm, lest the punishment of a mighty day seize you", "\"কোন ক্ষতির উদ্দেশ্যে তাকে স্পর্শ করো না, পাছে তোমরা এক ভয়ানক দিনে শাস্তি টেনে আনো।\""],
  "26:157": ["So they cut her down, and in the morning they were regretters", "তারা তাকে জবাই করলো, এবং এভাবে দুঃখ টেনে আনলো।"],
  "26:158": ["So the punishment seized them. Indeed in that is a sign, and most of them were not muminin", "শাস্তি তাদেরকে ছেয়ে ফেলল। এটি একটি শিক্ষা হওয়া উচিত, কিন্তু অধিকাংশ লোক বিশ্বাসী নয়।"],
  "26:159": ["And your Rabb is the Mighty, the Raheem", "অত্যন্ত নিশ্চিতভাবে, তোমার প্রভু সর্বশক্তিমান, সবচেয়ে দয়ালু।"],
  "26:160": ["The people of Lut denied the Rasuls", "লূতের লোকেরা বার্তাবাহকদেরকে অবিশ্বাস করেছিলো।"],
  "26:161": ["When their brother Lut said to them: Will you not fear", "তাদের ভাই লূত তাদেরকে বলল, \"তোমরা কি সৎকর্মশীল হবে না?"],
  "26:162": ["I am to you a Rasul, trustworthy", "\"আমি তোমাদের কাছে এক বিশ্বস্ত বার্তাবাহক।"],
  "26:163": ["So fear Allah and obey me", "\"তোমরা আল্লাহকে ভক্তি করবে, এবং আমাকে মান্য করবে।"],
  "26:164": ["And I ask you no reward for it — my reward is only upon the Rabb of the worlds", "\"আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না; আমার পারিশ্রমিক কেবল মহাবিশ্বের প্রভুর কাছ থেকে আসে।"],
  "26:165": ["Do you come to the males of the worlds", "\"সকল লোকদের থেকে, তোমরা কি পুরুষদের সাথে যৌনচর্চা করো?"],
  "26:166": ["And leave what your Rabb created for you of your spouses? Nay, you are a transgressing people", "\"তোমরা স্ত্রীদের পরিত্যাগ করো যাদেরকে তোমাদের প্রভু তোমাদের জন্য সৃষ্টি করেছেন! নিশ্চয়, তোমরা সীমালঙ্ঘনকারী লোক।\""],
  "26:167": ["They said: If you do not desist, Lut, you shall be among the driven-out ones", "তারা বলল, \"যদি না তুমি বিরত হও, হে লূত, তুমি নির্বাসিত হবে।\""],
  "26:168": ["He said: I am indeed among those who detest your deed", "সে বলল, \"আমি তোমাদের কার্যকলাপের অত্যন্ত ঘৃণা করি।\""],
  "26:169": ["My Rabb, deliver me and my family from what they do", "\"আমার প্রভু, আমাকে এবং আমার পরিবারকে তাদের কাজগুলো থেকে রক্ষা করুন।\""],
  "26:170": ["So We delivered him and his family, all together", "আমরা তাকে এবং তার পরিবারের সকলকে রক্ষা করলাম।"],
  "26:171": ["Except an jawza among the left-behind", "কিন্তু বৃদ্ধ মহিলাকে নয়; সে ছিল দন্ডাজ্ঞাপ্রাপ্ত।"],
  "26:172": ["Then We razed the others", "এরপর আমরা অন্যদের ধ্বংস করলাম।"],
  "26:173": ["And We rained upon them a rain — and evil was the rain of the warned ones", "আমরা তাদের প্রতি এক যন্ত্রণাদায়ক বৃষ্টি বর্ষণ করলাম; তাদের জন্য কতই না ভয়ংকর বর্ষণ ছিল যাদেরকে সতর্ক করা হয়েছিল!"],
  "26:174": ["Indeed in that is a sign, and most of them were not muminin", "এটি একটি শিক্ষা হওয়া উচিত, কিন্তু অধিকাংশ লোক বিশ্বাসী নয়।"],
  "26:175": ["And your Rabb is the Mighty, the Raheem", "নিশ্চিতভাবে, তোমার প্রভু সর্বশক্তিমান, পরম দয়ালু।"],
  "26:176": ["The people of al-Aykah denied the Rasuls", "বনবাসিরা বার্তাবাহকদের অবিশ্বাস করেছিল।"],
  "26:177": ["When Shu'ayb said to them: Will you not fear", "শোয়াইব তাদের বলেছিল, ““তোমরা কি সৎকর্মশীল হবে না?”"],
  "26:178": ["I am to you a Rasul, trustworthy", "\"আমি তোমাদের কাছে এক বিশ্বস্ত বার্তাবাহক।"],
  "26:179": ["So fear Allah and obey me", "\"তোমরা আল্লাহকে ভক্তি করবে, এবং আমাকে মান্য করবে।"],
  "26:180": ["And I ask you no reward for it — my reward is only upon the Rabb of the worlds", "\"আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না; আমার পারিশ্রমিক কেবল মহাবিশ্বের প্রভুর কাছ থেকে আসে।"],
  "26:181": ["Give full measure and do not be among the khasirin", "\"তোমরা পূর্ণ পরিমাপে দিবে যখন তোমরা লেনদেন করো, প্রতারণা করো না।"],
  "26:182": ["And weigh with the upright scale", "\"তোমরা সঠিক পাল্লায় ওজন করবে।"],
  "26:183": ["And do not diminish the people their things, and do not ravage the earth, corrupting", "\"লোকদেরকে তাদের অধিকারের বিষয়ে প্রতারণা করো না, এবং পৃথিবীতে দূর্নীতি করে বেড়িও না।"],
  "26:184": ["And fear the One who created you and the ancient generations", "\"সেই সত্ত্বাকে ভক্তি করো যিনি তোমাদেরকে এবং পূর্ববর্তী প্রজন্মদেরকে সৃষ্টি করেছেন।\""],
  "26:185": ["They said: You are only one of the bewitched ones", "তারা বলল, \"তুমি যাদুগ্রস্থ।"],
  "26:186": ["And you are only a human like us — and we think you are among the kazibin", "\"তুমি আমাদের মতো একজন মানুষের চেয়ে বেশি কিছু না। প্রকৃতপক্ষে, আমরা মনে করি তুমি একজন মিথ্যাবাদী"],
  "26:187": ["So make fragments of the sky fall upon us, if you are of the sadiqin", "\"আকাশ থেকে আমাদের উপর বস্তুপিন্ড ফেল, যদি তুমি সত্যবাদী হও।\""],
  "26:188": ["He said: My Rabb knows best what you do", "সে বলল, \"আমার প্রভু সে সত্ত্বা যিনি তোমরা  যা কিছু  করো সব জানেন।\""],
  "26:189": ["So they denied him, and the punishment of the day of the canopy seized them — it was the punishment of a mighty day", "তারা তাকে অবিশ্বাস করলো এবং, পরিনামে, তারা আচ্ছাদন দিনের শাস্তি টেনে আনলো। এটি ছিল এক ভয়ানক দিনের শাস্তি।"],
  "26:190": ["Indeed in that is a sign, and most of them were not muminin", "এটি একটি শিক্ষা হওয়া উচিত, কিন্তু অধিকাংশ লোক বিশ্বাসী নয়।"],
  "26:191": ["And your Rabb is the Mighty, the Raheem", "নিশ্চিতভাবে, তোমার প্রভু সর্বশক্তিমান, পরম দয়ালু।"],
  "26:192": ["And it is surely a sending-down from the Rabb of the worlds", "এটি মহাবিশ্বের প্রভুর কাছ থেকে একটি প্রত্যাদেশ।"],
  "26:193": ["The trustworthy spirit brought it down", "বিশ্বস্ত আত্মা (জিব্রাইল) একে নিয়ে অবতরন করেছিল।"],
  "26:194": ["Upon your heart, that you may be among the warners", "তোমার হৃদয়ে একে প্রকাশ করতে, যেন তুমি সতর্ককারীদের একজন হতে পারো।"],
  "26:195": ["In a clear Arabic tongue", "নিখুঁত আরবি ভাষায়।"],
  "26:196": ["And it is surely in the scriptures of the ancients", "এর ভবিষ্যৎবানী করা হয়েছে পূর্ববর্তী প্রজন্মের গ্রন্থগুলোতে।"],
  "26:197": ["Was it not a sign for them that the learned ones of the children of Israel knew it", "তাদের জন্য এটি কি যথেষ্ট নিদর্শন নয় যে ইসরাইলের সন্তানদের মধ্যে পণ্ডিতগণের এটি জানা ছিল?"],
  "26:198": ["And had We sent it down upon some of the non-Arabs", "আমরা যদি এটা সেসব লোকদের কাছে প্রকাশ করতাম যারা আরবি জানে না।"],
  "26:199": ["And he had recited it to them, they would not have believed in it", "আর তাকে (আরবীতে) এটি আবৃতি করতে দিতাম,  তারা কখনোই এতে বিশ্বাস করতে পারতো না।"],
  "26:200": ["Thus We threaded it into the hearts of the mujrimin", "আমরা এভাবে এটিকে অপরাধীদের হৃদয়ে (বিদেশী ভাষার মতো) করে দেই।"],
  "26:201": ["They will not believe in it until they see the painful punishment", "সুতরাং,তারা এতে বিশ্বাস করতে পারে না; যতক্ষণ না তারা যন্ত্রণাদায়ক শাস্তি দেখে।"],
  "26:202": ["It will come to them suddenly, while they do not perceive", "এটি তাদের কাছে হঠাৎ করেই আসবে, যখন তারা প্রায় তার আশা-ই করবে না।"],
  "26:203": ["Then they say: Are we to be reprieved", "তখন তারা বলবে, \"আমরা কি অবকাশ পেতে পারি?\""],
  "26:204": ["Do they ask Our punishment to hasten", "তারা কি আমাদের শাস্তিকে চ্যালেঞ্জ করেনি?"],
  "26:205": ["Have you seen: if We let them enjoy for years", "তুমি যেমনটি দেখছ, আমরা তাদেরকে বছরের পর বছর উপভোগ করতে দিয়েছি।"],
  "26:206": ["Then there comes to them what they were promised", "এরপর শাস্তি তাদের কাছে চলে এসেছে,  ঠিক যেরকম প্রতিশ্রুতি দেয়া হয়েছে।"],
  "26:207": ["Of no avail to them is what they were given to enjoy", "তাদের বিপুল সম্পদ তাদেরকে সামান্যতম সাহায্যও করেনি।"],
  "26:208": ["And We destroyed no town but that it had warners", "আমরা সতর্ককারী না পাঠিয়ে কখনো কোন সম্প্রদায়কে ধ্বংস করি না।"],
  "26:209": ["A reminder — and We were not unjust", "অতএব, এটি একটি স্মারক, কারণ আমরা কখনো অন্যায়কারী নই।"],
  "26:210": ["And the devils did not bring it down", "শয়তানেরা কখনো একে প্রকাশ করতে পারবে না।"],
  "26:211": ["And it does not befit them, nor are they able", "না তারা তা করবে, না করতে পারবে।"],
  "26:212": ["They are indeed cut off from the hearing", "কারণ তাদেরকে শুনতে বাঁধা দেয়া হয়।"],
  "26:213": ["So do not call upon any other ilah with Allah, lest you be among the punished", "অতএব, আল্লাহর পাশে অন্য কোন উপাস্যকে আল্লাহতুল্য করো না, পাছে তুমি শাস্তি টেনে আনো।"],
  "26:214": ["And warn your kin, the nearest ones", "তুমি তোমার নিকটতম লোকদের কাছে প্রচার করবে।"],
  "26:215": ["And lower your wing to those who follow you of the muminin", "আর বিশ্বাসীরা যারা তোমার অনুসরণ করে, তাদের প্রতি তোমর দয়ার বাহু প্রসারিত করো।"],
  "26:216": ["So if they disobey you, say: I am clear of what you do", "যদি তারা তোমাকে অমান্য করে, তাহলে বল, \"যা তোমরা করো তার জন্য আমি দায়ী নই।\""],
  "26:217": ["And rely upon the Mighty, the Raheem", "আর তোমার আস্থা রাখো সর্বশক্তিমান, পরম দয়ালুর প্রতি।"],
  "26:218": ["The One who sees you when you stand", "যিনি তোমাকে দেখেন, যখন তুমি রাতে ধ্যান করো।"],
  "26:219": ["And your turning among those who prostrate", "এবং বারংবার তোমার সেজদা।"],
  "26:220": ["Allah is the Hearing, the Knowing", "তিনি সর্বশ্রোতা, সর্বজ্ঞ।"],
  "26:221": ["Shall I inform you of those upon whom the devils descend", "আমি কি তোমাদের বলবো শয়তানরা কাদের কাছে অবতরণ করে।"],
  "26:222": ["They descend upon every fabricating sinner", "তারা অবতরণ করে প্রত্যেক অপরাধী উদ্ভাবনকারীদের কাছে।"],
  "26:223": ["They cast the hearing, and most of them are liars", "তারা শুনার ভান করে, কিন্তু তাদের বেশিরভাগ মিথ্যাবাদী।"],
  "26:224": ["And the poets — the misled ones follow them", "কবিদের ক্ষেত্রে, পথভ্রষ্টরাই কেবল তাদের অনুসরণ করে।"],
  "26:225": ["Do you not see that they wander in every valley", "তুমি কি দেখো না যে, তাদের আনুগত্য পরিস্থিতি অনুসারে পরিবর্তিত হয়?"],
  "26:226": ["And that they say what they do not do", "আর যে, তারা বলে যা তারা করে না?"],
  "26:227": ["Except those who believe and do salih deeds and remember Allah much, and vindicate themselves after they were wronged — and the wrongdoers will soon know to what turning-place they turn", "তাদের ছাড়া যারা বিশ্বাস করে, একটি সৎ জীবন যাপন করে, প্রতিনিয়ত আল্লাহর স্মরণ করে, এবং তাদের অধিকারের জন্য সোচ্চার হয়। নিশ্চয়ই সীমালঙ্ঘনকারীরা দেখতে পাবে যে তাদের চুড়ান্ত নিয়তি কি।"],
  "27:1": ["Ta Sin. Those are the signs of the Recitation and a clear book.", "ত. স. এই (অক্ষরগুলো) কুরআনে প্রমান গঠন করে; এক জ্ঞানগর্ভ ঐশীগ্রন্থ।"],
  "27:2": ["Guidance and good news for the muminin.", "একটি আলোকবর্তিকা, এবং সুসংবাদ, বিশ্বাসীদের জন্য।"],
  "27:3": ["Those who keep up the prayer and give the alms, and they of the hereafter are certain.", "যারা সংযোগ প্রার্থনা (সালাত) পালন করে, বাধ্যতামূলক দান (যাকাত)দেয়, এবং তারা পরকালের বিষয়ে সম্পূর্ণরূপে নিশ্চিত।"],
  "27:4": ["Those who do not believe in the hereafter — their deeds are adorned to them, so they wander blind.", "যারা পরকালে বিশ্বাস করে না, আমরা তাদের চোখে তাদের কাজকে সাজিয়ে দেই। ফলে, তারা ভুল করতে থাকে।"],
  "27:5": ["Those are the ones for whom is the evil punishment, and they in the hereafter are the greatest losers.", "এরাই নিকৃষ্ট শাস্তি টেনে আনে, এবং পরকালে, তারা সর্বাধিক ক্ষতিগ্রস্থ হবে।"],
  "27:6": ["You are indeed receiving the Recitation from the presence of a Wise, Knowing one.", "নিশ্চিতভাবে, তুমি কুরআন গ্রহণ করছো এক প্রজ্ঞাময়, সর্বজ্ঞের কাছ থেকে।"],
  "27:7": ["When Musa said to his household: I have perceived a fire; I will bring you news from it, or bring you a flaming brand, so that you may warm yourselves.", "স্মরণ করো যে মুসা তার পরিবারকে বলেছিল, “আমি আগুন দেখছি, আমি তোমাদের জন্য সেখান থেকে সংবাদ অথবা তোমাদেরকে উষ্ণ রাখতে মশাল নিয়ে আসছি।"],
  "27:8": ["When he came to it, a call came: Blessed is whoever is in the fire and whoever is around it; exalted is Allah, Rabb of the worlds.", "যখন সে এর কাছে আসলো, তাকে ডাকা হলঃ “পবিত্র সেই সত্ত্বা (যিনি কথা বলছেন) আগুনের মধ্যে থেকে, এবং তারা যারা এর চারিদিকে আছে”। মহিমা আল্লাহর, মহাবিশ্বের প্রভু।"],
  "27:9": ["O Musa, indeed it is I, Allah, the Mighty, the Wise.", "হে মুসা, এতো আমি, আল্লাহ, সর্বশক্তিমান, সবথেকে জ্ঞানী।"],
  "27:10": ["Cast your staff. When he saw it quivering as if it were a serpent, he turned and fled and did not look back. O Musa, do not fear; with Me the Rasuls do not fear.", "“তোমার লাঠি নিচে ছুড়ে ফেলো।\" যখন সে এটাকে দানবের মত চলতে দেখল, সে ঘুরে দাঁড়ালো এবং পালালো। “হে মুসা ভয় করো না। আমার বার্তাবাহকেরা ভয় পায়না।"],
  "27:11": ["Except one who has done wrong, then substituted good after evil — then I am All-Forgiving, Raheem.", "“তারা ছাড়া যারা কোন সীমালঙ্ঘন করে, এরপর পাপের পরিবর্তে সৎ-কর্ম করে; আমি ক্ষমাশীল, পরম দয়ালু।"],
  "27:12": ["Put your hand into your pocket; it will come out white without any evil — among nine signs to Fir'awn and his people. They were a defiant people.", "“তুমি তোমার হাত তোমার বাহুর মধ্যে রাখো; এটা সাদা হয়ে বেরিয়ে আসবে, কোন খুঁত ছাড়া। এইগুলো হলো ফেরাউন এবং তার লোকদের প্রতি নয়টি অলৌকিকতা, কারন তারা ছিল পাপী লোক”।"],
  "27:13": ["When Our signs came to them, clear to see, they said: This is clear magic.", "যখন আমাদের অলৌকিকতাগুলো তাদের কাছে উপস্থাপন করা হোল, স্পষ্ট এবং প্রগাঢ়, তারা বলল, “এ তো স্পষ্টতই জাদু”।"],
  "27:14": ["They denied them while their own selves were certain of them, out of wrong and arrogance. So see how was the end of the corrupters.", "তারা সেগুলকে প্রত্যাখ্যান করলো এবং তাদের ভুল পথে একদম নিশ্চিত ছিল, তাদের ঔদ্ধত্যের কারনে। লক্ষ্য করো মন্দ কর্মীদের পরিণতি।"],
  "27:15": ["We gave Dawud and Sulayman knowledge, and they said: Praise belongs to Allah who favored us over many of Allah's believing servants.", "আমরা দাউদ এবং সুলাইমানকে জ্ঞান দান করেছিলাম, এবং তারা বলল, “প্রশংসা আল্লাহর তাঁর অনেক বিশ্বাসী বান্দাদের থেকে আমাদেরকে অধিক সৌভাগ্যশালী করার জন্য”।"],
  "27:16": ["Sulayman succeeded Dawud, and said: O people, we have been taught the speech of birds, and we have been given of everything. This is indeed the clear bounty.", "সুলাইমান ছিল দাউদের উত্তরাধিকারী। সে বলল, “হে লোকেরা, আমাদেরকে পাখিদের ভাষা বোঝার ক্ষমতা দান করা হয়েছে, এবং আমাদের প্রদান করা হয়েছে সকল ধরনের জিনিস। এটা নিশ্চয় প্রকৃত আনুগ্রহ”।"],
  "27:17": ["Gathered for Sulayman were his hosts of jinn and humans and birds, and they were marshaled.", "সুলাইমান সেবায় নিয়জিত ছিল তার বাধ্য জিন ও মানব সৈন্যরা, সেই সাথে পাখিরা, সকলেই ছিল তার আয়ত্তাধীন।"],
  "27:18": ["Until when they came upon the Valley of the Ants, an ant said: O ants, enter your dwellings, lest Sulayman and his hosts crush you without perceiving.", "যখন তারা পিঁপড়াদের উপত্যকার কাছাকাছি আসলো, একটি পিঁপড়া বলল, “হে পিঁপড়াগণ, তোমাদের বাড়ির ভেতরে চলে যাও, পাছে তোমারা সুলাইমান ও তার সৈন্যদের অজ্ঞাতসারে পিষ্ট হয়ে যাও”।"],
  "27:19": ["He smiled, laughing at her words, and said: My Rabb, inspire me to thank You for Your blessing which You blessed me and my parents with, and to do good that pleases You, and admit me by Your mercy among Your salih servants.", "সে তার (স্ত্রী লিঙ্গ) কথায় হাসল,  এবং বলল, “আমার প্রভু, আমাকে পরিচালিত করুন আপনার অনুগ্রহের প্রতি কৃতজ্ঞ হতে যা আপনি আমার এবং আমার পিতামাতার উপর অর্পণ করেছেন, এবং সেই সৎকর্ম করতে যা আপনাকে সন্তুষ্ট করে। আপনার দয়ায় আমাকে অন্তর্ভুক্ত করুন আপনার সৎ-কর্মী বান্দাদের সাহচর্যে।"],
  "27:20": ["He reviewed the birds and said: Why do I not see the hoopoe? Is it among the absent?", "সে পাখিদের পরিদর্শন করলো, এবং বললঃ “আমি হুদহুদকে দেখছি না কেন? সে অনুপস্থিত কেন?"],
  "27:21": ["I will surely punish it with a severe punishment, or slaughter it, or it must bring me a clear warrant.", "“আমি তাকে কঠোর শাস্তি দেবো বা তাকে জবেহ করবো যদিনা সে উপযুক্ত কারন দর্শায়।"],
  "27:22": ["It stayed not long, then said: I have encompassed what you did not encompass, and I bring you from Saba certain news.", "সে বেশিক্ষন অপেক্ষা করলো না। (হুপু পাখি) বলল, “আমার কাছে সংবাদ আছে যা আপনার কাছে নাই। আমি সাবা থেকে আপনার জন্য, কিছু গুরুত্বপূর্ণ তথ্য এনেছি।"],
  "27:23": ["I found an imra'a ruling them, and she has been given of everything, and she has a mighty high-seat.", "আমি এক নারীকে দেখেছি তাদেরকে শাসন করতে, যাকে সবকিছু দিয়ে অনুগ্রহ করা হয়েছে, এবং সে এক অসাধারন প্রাসাদের অধিকারী।"],
  "27:24": ["I found her and her people prostrating to the sun instead of Allah, and the devil has adorned their deeds to them, so he barred them from the way, and they are not guided.", "“আমি তাকে এবং তার লোকদের আল্লাহর বদলে সূর্যকে সেজদা করতে দেখেছি। শয়তান তাদের কাজকে তাদের চোখে সাজিয়ে দিয়েছে, এবং তাদেরকে পথ থেকে নিবৃত রেখেছে; ফলস্বরূপ, তারা পথপ্রাপ্ত নয়”।"],
  "27:25": ["Will they not prostrate to Allah, who brings out the hidden in the heavens and the earth, and knows what you conceal and what you declare?", "তাদের উচিৎ ছিল আল্লাহকে সেজদা করা, সেই সত্ত্বা যিনি আকাশমণ্ডলী ও পৃথিবীর সকল রহস্য প্রকাশ করেন, এবং সেই সত্ত্বা  যিনি জানেন যা কিছু তোমরা গোপন করো এবং যা কিছু তোমরা প্রকাশ করো।"],
  "27:26": ["Allah — there is no ilah but Allah — Rabb of the mighty high-seat.", "ঈশ্বরঃ তাঁর পাশে অন্য কোন উপাস্য নাই, মহান রাজত্বের প্রভু।"],
  "27:27": ["He said: We shall see whether you have spoken the truth or are one of the kazibin.", "(সুলেমান) বলল, “আমরা দেখব তুমি কি সত্য বলেছো নাকি তুমি এক মিথ্যাবাদী।"],
  "27:28": ["Take this letter of mine, cast it to them, then turn away from them, and see what they return.", "“আমার কাছ থেকে এই চিঠি নাও, এটা তাদেরকে দাও, এরপর তাদের জবাবের প্রতি লক্ষ্য রাখো।"],
  "27:29": ["She said: O chiefs, a noble letter has been cast to me.", "সে বলল, “হে আমার উপদেষ্টা মণ্ডলী, আমি এক সন্মানিত চিঠি পেয়েছি।"],
  "27:30": ["It is from Sulayman, and it reads: In the name of Allah, the Compassionate, the Raheem.", "“এটা সুলাইমানের কাছ থেকে, এবং এটা হলো, “পরম করুণাময়, পরম দয়ালু আল্লাহর নামে।\""],
  "27:31": ["Do not rise against me, but come to me submitting.", "“এই ঘোষণা দিয়ে “উদ্ধত হয়ো না; আমার কাছে আসো আত্মসমর্পণকারী হিসাবে”।"],
  "27:32": ["She said: O chiefs, advise me in my affair; I was not one to decide an affair until you bear witness.", "সে বলল, “হে আমার উপদেষ্টা মণ্ডলী, আমাকে এই বিষয়ে পরামর্শ দাও। আমি কোন সিদ্ধান্ত নিচ্ছি না যতক্ষণ না তোমরা আমাকে উপদেশ দাও”।"],
  "27:33": ["They said: We have strength and severe might, and the affair is yours; so see what you command.", "তারা বলল, “আমাদের শক্তি আছে, আমাদের যুদ্ধের দক্ষতা আছে, আর চূড়ান্ত হুকুম আপনার হাতে। আপনি সিদ্ধান্ত নিন কি করতে হবে।"],
  "27:34": ["She said: When kings enter a town they corrupt it and abase its honored people, and so they do.", "সে বলল, “রাজারা কোন ভূখণ্ডকে আক্রমণ করলে তা বিপর্যস্ত করে দেয়, এবং এর মর্যাদাসম্পন্ন লোকদের অধীনস্থ করে নেয়। এটাই তারা সাধারণত করে থাকে।"],
  "27:35": ["I will send them a gift, and I will see what the envoys return with.", "“আমি তাদের কাছে একটি উপহার পাঠাচ্ছি; দেখি বার্তাবাহকরা কি নিয়ে ফিরে আসে”।"],
  "27:36": ["When it came to Sulayman he said: Are you supplying me with wealth? What Allah has given me is better than what you gave. Rather, you rejoice in your gift.", "যখন হুপু পাখি সুলেমানের কাছে ফিরে এলো (সে তাকে সংবাদটি দিলো), এবং সে জবাবে বলল (সাবার লোকদের): “তোমরা কি আমাকে অর্থ দিচ্ছ? আল্লাহ আমাকে যা দিয়েছেন তা তোমাদেরকে যা  দিয়েছেন তা থেকে অনেক উত্তম। তোমরা সে লোক যারা এমন উপহারে আনন্দ করে”।"],
  "27:37": ["Go back to them; We will come to them with hosts they cannot withstand, and We will bring them out of it, abased and belittled.", "(হুপু পাখিকে, সে বলল) “তাদের কাছে ফিরে যাও (এবং তাদের জানাও যে) আমরা তাদের কাছে আসবো এমন সেনাবাহিনী নিয়ে যা তারা কল্পনা করতে পারে না। আমরা তাদেরকে উচ্ছেদ করবো, অপমানিত এবং অপদস্থ করে।"],
  "27:38": ["He said: O chiefs, which of you will bring me her high-seat before they come to me submitting?", "সে বলল, “হে সভাসদবর্গ/পরিষদবর্গ/প্রধানগণ, তোমাদের মধ্যে কে আমাকে তার প্রাসাদ এনে দিতে পারে, তারা এখানে  আত্মসমর্পণকারী হিসাবে পৌঁছনোর আগে।"],
  "27:39": ["A mighty one of the jinn said: I will bring it to you before you rise from your place; I am strong and trustworthy for it.", "জিনদের মধ্যে একজন শক্তিশালী জিন বলল, “আপনি উঠে দাঁড়ানোর আগে আমি তা আপনার কাছে নিয়ে আসতে পারি। আমি যথেষ্ট শক্তিশালী তা করার জন্য”।"],
  "27:40": ["The one who had knowledge of the writings said: I will bring it to you before your glance returns to you. And when he saw it settled before him, he said: This is from the bounty of my Rabb, to test me whether I am grateful or ungrateful. Whoever gives thanks does so only for his own self; and whoever is ungrateful — my Rabb is free of need and noble.", "যে গ্রন্থ থেকে জ্ঞান অর্জন করেছিল সে বলল, “আপনি চোখের পলক ফেলার আগেই আপনার কাছে আমি তা নিয়ে আসতে পারি”।  সে যখন  তার সামনে তা রক্ষিত দেখল, সে বলল, “এটা আমার প্রভুর পক্ষ থেকে একটি অনুগ্রহ, যার দ্বারা তিনি আমাকে পরীক্ষা করেন,  এটা দেখাতে আমি কৃতজ্ঞ নাকি অকৃতজ্ঞ। যে কৃতজ্ঞ সে তার নিজের ভালোর জন্যই কৃতজ্ঞ, এবং যদি কেউ অকৃতজ্ঞ হয়, তবে আমার প্রভুর তাকে কোন প্রয়োজন নেই, পরম সন্মানিত।"],
  "27:41": ["He said: Alter the look of her high-seat for her; we shall see whether she is guided or is one of those who are not guided.", "সে বলল, “তার প্রাসাদ তার জন্য পুনরায় সাজাও। দেখা যাক সে পথপ্রাপ্ত হবে, নাকি পথভ্রষ্টদের সাথে চলবে”।"],
  "27:42": ["When she came, it was said: Is this your high-seat? She said: It is as if it is it. We had been given knowledge before this, and we were submitters.", "যখন সে পৌঁছাল, তাকে জিজ্ঞাসা করা হল, “তোমার প্রাসাদ কি দেখতে এমন?”সে বলল, “মনে হচ্ছে এটা যেন সেটাই”। “আমরা আগেই জানতাম সে কি করতে যাচ্ছে, এবং ইতিমধ্যে আমারা আত্মসমর্পণকারী ছিলাম”।"],
  "27:43": ["What she used to worship instead of Allah barred her; she was from a committing kufr people.", "সে আল্লাহর বদলে অন্য উপাস্যদের উপাসনা তাকে পথ থেকে সরিয়ে নিয়েছিল; সে অবিশ্বাসী লোকদের অন্তর্ভুক্ত ছিল।"],
  "27:44": ["It was said to her: Enter the palace. When she saw it she thought it was a deep pool, and she uncovered her shins. He said: It is a palace paved with crystal-glass. She said: My Rabb, I have wronged myself, and I submit with Sulayman to Allah, Rabb of the worlds.", "তাকে বলা হল, “প্রাসাদের ভেতরে যাও”। যখন সে এটার অভ্যন্তরভাগ দেখল, সে ভাবল এটা একটি জলাশয়, এবং সে (তার পোশাক উঁচু করে ধরল) তার পাগুলো অনাবৃত করে। সে বলল, “এই অভ্যন্তরভাগ এখন স্ফটিক দিয়ে বাঁধানো”। সে বলল, “আমার প্রভু, আমি আমার আত্মার ক্ষতি করেছি। আমি এখন সুলেমানের সাথে আল্লাহর কাছে আত্মসমর্পণ করছি, যিনি মহাবিশ্বের প্রভু”।"],
  "27:45": ["We sent to Thamud their brother Salih: Worship Allah. But they were two parties contending.", "আমরা সামুদ জাতির কাছে তাদের ভাই সালেহকে পাঠিয়েছি, এই বলে যে, “তোমরা আল্লাহর উপাসনা করবে”। কিন্তু তারা দুটি বিবাদকারী দলে বিভক্ত হল।"],
  "27:46": ["He said: My people, why do you hasten the evil before the good? Why do you not seek forgiveness of Allah, that you may be shown mercy?", "সে বলল, “হে আমার লোকেরা, কেন তোমরা ভালো কাজের বদলে মন্দ কাজে তাড়াহুড়ো করো? যদি কেবল তোমরা আল্লাহর কাছে ক্ষমাপ্রাপ্তির জন্য মিনতি করো, তোমরা দয়া পেতে পারো”।"],
  "27:47": ["They said: We augur ill of you and of those with you. He said: Your omen rests with Allah; rather, you are a people being tested.", "তারা বলল, “আমারা তোমাকে আমাদের জন্য  অশুভ লক্ষণ মনে করি, তোমাকে এবং তোমার সাথে যারা যোগ দিয়েছে ”। সে বলল, “তোমাদের পূর্ব লক্ষণ সম্পূর্ণরূপে আল্লাহর দ্বারা নিয়ন্ত্রিত। নিশ্চয়, তোমরা পথভ্রষ্ট লোক”।"],
  "27:48": ["There were in the town nine men who corrupted in the land and did not set right.", "সেই শহরে ছিল নয়জন দুর্বৃত্তদলের লোক যারা ছিল পাপিষ্ঠ, এবং কখন ভালো কিছু করতো না।"],
  "27:49": ["They swore to one another by Allah: We will attack him and his household by night, then we will say to his next of kin: We did not witness the destruction of his household, and we are sadiq.", "তারা বলল “চল আমরা আল্লাহর নামে শপথ করি যে আমরা তাকে এবং তার লোকদের  হত্যা করবো, এরপর তার গোষ্ঠীকে বলব, “আমরা তাদের মৃত্যুর ব্যাপারে কিছুই জানি না। আমরা সত্যবাদী”।"],
  "27:50": ["They planned a plan, and We planned a plan, while they did not perceive.", "তারা কুমন্ত্রনা এবং চক্রান্ত করলো, এবং আমরা ও চক্রান্ত  করলাম এবং কৌশল অবলম্বন করলাম, যা তারা বুঝতে পারেনি।"],
  "27:51": ["So see how was the end of their plan: We razed them and their people all together.", "লক্ষ্য করো তাদের চক্রান্তের পরিণাম; আমরা তাদেরকে এবং তাদের সব লোকদের ধ্বংস করেছিলাম।"],
  "27:52": ["Those are their houses, collapsed, because of the wrong they did. In that is a sign for people who know.", "এইযে তাদের ঘরবাড়ি একদম ধংসপ্রাপ্ত, তাদের সীমালঙ্ঘনের কারনে। এটা একটা শিক্ষা হওয়া উচিৎ সেসব লোকদের জন্য যারা জানে।"],
  "27:53": ["We saved those who believed and were mindful.", "আমরা রক্ষা করি তাদেরকে যারা বিশ্বাস করে এবং সৎ-জীবন যাপন করে।"],
  "27:54": ["And Lut, when he said to his people: Do you commit the obscenity while you see?", "লুত তার লোকদের বলল, “কেমন করে তোমরা জনসমক্ষে এমন নিদারুন ঘৃণ্য কাজ করতে পারো, যখন তোমরা দেখছ?"],
  "27:55": ["Do you indeed approach the males of the worlds and abandon the mates your Rabb created for you? Rather, you are an ignorant people.", "‘তোমরা পুরুষদের সাথে যৌন চর্চা করো, কামাসক্ত হয়ে, নারীদের বদলে। নিশ্চয় তোমরা অজ্ঞ লোক”।"],
  "27:56": ["The answer of his people was only to say: Drive out the family of Lut from your town; they are people who purify themselves.", "তার লোকদের থেকে একমাত্র জবাব ছিল, “লুতের পরিবারকে তোমাদের শহর থেকে বের করে দাও; তারা সে লোক যারা শুদ্ধ হতে চায়”।"],
  "27:57": ["We saved him and his family except his imra'a — We decreed her among those left behind.", "ফলসরুপ, আমরা তাকে এবং তার পরিবারকে রক্ষা করলাম, তার স্ত্রী ছাড়া, আমরা তাকে ধ্বংসপ্রাপ্তদের মধ্যে অন্তর্ভুক্ত করলাম।"],
  "27:58": ["We rained upon them a rain; evil was the rain of those who were warned.", "আমরা এক নির্দিষ্ট বর্ষা তাদের উপর বর্ষণ করেছিলাম। এটা ছিল এক শোচনীয় বর্ষা সে লোকদের উপর যাদেরকে সতর্ক করা হয়েছিল।"],
  "27:59": ["Say: Praise belongs to Allah, and peace upon the servants whom Allah has chosen. Is Allah better, or those they associate?", "বল, “প্রশংসা আল্লাহর এবং শান্তি বর্ষিত হোক তাঁর বান্দাদের উপর যাদেরকে তিনি পছন্দ করেছেন। আল্লাহ উত্তম, নাকি সেসব উপাস্যরা যাদেরকে কিছু লোক স্থাপন করে?”"],
  "27:60": ["Who created the heavens and the earth, and sent down for you water from the sky, and with it We grew gardens of splendor whose trees you could not grow — is there a ilah with Allah? Rather, they are a people who set up equals.", "কে সেই সত্ত্বা যিনি আকাশমণ্ডলী এবং পৃথিবী সৃষ্টি করেছেন? কে সেই সত্ত্বা যিনি আকাশ থেকে তোমাদের কাছে পানি বর্ষণ করেন, যা দিয়ে আমরা উৎপন্ন করি সৌন্দর্যে পরিপূর্ণ বাগান- তোমরা এর বৃক্ষাদি উৎপাদন করতে পারতে না? সে কি আল্লাহর সাথে অন্য কোন উপাস্য? নিশ্চয়, তারা সে লোক যারা পথভ্রষ্ট হয়েছে।"],
  "27:61": ["Who made the earth a settled abode, and made rivers amidst it, and made anchors for it, and made between the two seas a barrier — is there a ilah with Allah? Rather, most of them do not know.", "কে সেই সত্ত্বা যিনি পৃথিবীকে বাসযোগ্য করেছেন, নদীগুলোকে এর মাঝে প্রবাহিত করেছেন, এর উপর স্থাপন করেছেন পাহাড়-পর্বত, এবং দুই পানির মাঝে এক অন্তরায় সৃষ্টি করেছেন? সে কি আল্লাহর সাথে অন্য কোন উপাস্য? নিশ্চয়, তাদের বেশির ভাগই জানে না।"],
  "27:62": ["Who answers the one in distress when he calls, and uncovers the evil, and makes you successors on the earth — is there a ilah with Allah? Little do you remember.", "কে সেই সত্ত্বা যিনি তাদেরকে উদ্ধার করেন যারা মরিয়া হয়ে তাঁকে ডাকতে থাকে, তিনি দুর্দশা দূর করেন, এবং তোমাদেরকে পৃথিবীর উত্তরাধিকারী করেন? সে কি আল্লাহর সাথে অন্য কোন উপাস্য? তোমরা খুব কমই মনোনিবেশ করো।"],
  "27:63": ["Who guides you in the darknesses of the dry land and the sea, and who sends the wind as good news ahead of Allah's mercy — is there a ilah with Allah? Exalted is Allah above what they associate.", "কে সেই সত্ত্বা যিনি তোমাদেরকে স্থল এবং সাগরের অন্ধকারে পথ দেখান? কে সেই সত্ত্বা যিনি সুসংবাদ সহ বায়ু প্রেরন করেন, তার দয়ার পূর্বাভাস হিসাবে? এটি  কি আল্লাহর সাথে অন্য কোন খোদা? আল্লাহ পরম মহিমান্বিত, কোন অংশীদার থাকার ঊর্ধ্বে।"],
  "27:64": ["Who begins the creation then repeats it, and who provides you from the sky and the earth — is there a ilah with Allah? Say: Bring your clear proof, if you are sadiq.", "কে সেই সত্ত্বা যিনি সৃষ্টির সুচনা করেন, এরপর তার পুনরাবৃত্তি ঘটান? কে সেই সত্ত্বা যিনি আকাশমণ্ডলী এবং পৃথিবী থেকে তোমাদের জীবিকা প্রদান করেন। এটি  কি আল্লাহর সাথে অন্য কোন খোদা? বল, “আমাকে তোমাদের প্রমান দেখাও, যদি তোমরা সত্যবাদী হয়ে থাকো।”"],
  "27:65": ["Say: None in the heavens and the earth knows the unseen except Allah. They do not perceive when they will be raised.", "বল, “আকাশমণ্ডলী এবং পৃথিবীতে আল্লাহ ছাড়া কেউই ভবিষ্যৎ জানে না। তারা এমনকি এটাও বুঝতে পারেনা কিভাবে এবং কখন তারা পুনরুত্থিত হবে”।"],
  "27:66": ["Rather, their knowledge overtakes them in the hereafter; rather, they are in doubt about it; rather, they are unperceiving of it.", "প্রকৃত পক্ষে, পরকাল সম্পর্কে তাদের জ্ঞান বিভ্রান্ত/দিধাগ্রস্থ। প্রকৃত পক্ষে, তারা এ বিষয়ে সন্ধেহ পোষণ করে। প্রকৃত পক্ষে, এ বিষয়ে তারা সম্পূর্ণ অমনোযোগী।"],
  "27:67": ["Those who disbelieve say: When we have become dust, and our fathers, shall we indeed be brought out?", "যারা অবিশ্বাস করে তারা বলল, “আমরা এবং আমাদের পিতামাতারা ধুলোতে পরিণত হবার পরও কি আমাদের বের করে আনা হবে?"],
  "27:68": ["We and our fathers were promised this before. This is nothing but tales of the ancients.", "“অতীতেও আমাদেরকে একই প্রতিশ্রুতি দেয়া হয়েছে। এগুলো অতীতের কল্পকাহিনী ছাড়া কিছুই না”।"],
  "27:69": ["Say: Journey through the earth, and see how was the end of the mujrimin.", "বল, “পৃথিবীতে ঘুরে দেখো এবং অপরাধীদের পরিণাম লক্ষ্য করো”।"],
  "27:70": ["Do not grieve over them, and do not be in straitness over what they plan.", "তাদের জন্য দুঃখ করো না, এবং তাদের চক্রান্তে বিরক্ত হইও না।"],
  "27:71": ["They say: When is this promise, if you are sadiq?", "তারা বলে, “কখন সেই প্রতিশ্রুতি পূর্ণ হবে, যদি তোমরা সত্যবাদী হও?”"],
  "27:72": ["Say: Perhaps some of what you hasten is close behind you.", "বল, “তোমরা ইতিমধ্যেই তোমাদের চ্যালেঞ্জ করা কিছু শাস্তি ভোগ করছো”।"],
  "27:73": ["Your Rabb is full of bounty upon people, but most of them are not grateful.", "তোমার প্রভু মানুষের প্রতি অত্যন্ত অনুগ্রহশীল, কিন্তু তাদের বেশির ভাগ অকৃতজ্ঞ।"],
  "27:74": ["Your Rabb knows what their chests conceal and what they declare.", "তোমার প্রভু সম্পূর্ণ রুপে জানেন তাদের বুকে কি লুকানো আছে, আর তারা  কি প্রকাশ করে।"],
  "27:75": ["Nothing absent is in the heaven and the earth but it is in a clear record.", "আকাশ মণ্ডলী এবং পৃথিবীতে কোন কিছু নেই যা (আল্লাহ থেকে) লুকানো আছে; সবকিছুই রয়েছে এক প্রগাঢ় নথিতে।"],
  "27:76": ["This Recitation narrates to the children of Israel most of what they differ about.", "এই কুরআন ইসরাইলের সন্তানদের জন্য অনেক বিষয়াদি নিষ্পত্তি করে; বিষয়াদি যেগুলো নিয়ে তারা এখনো বিবাদ করছে।"],
  "27:77": ["It is guidance and mercy for the muminin.", "এবং সুনিশ্চিত ভাবে, এটা বিশ্বাসীদের জন্য একটি পথপ্রদর্শক এবং দয়া।"],
  "27:78": ["Your Rabb will judge between them by Allah's judgment; Allah is the Mighty, the Knowing.", "তোমার প্রভুই সেই সত্ত্বা যিনি তাঁর আইন অনুসারে তাদের মাঝে বিচার করেন।"],
  "27:79": ["So trust in Allah; you are upon the clear truth.", "অতএব, আল্লাহর উপর তোমার আস্থা রাখো; তুমি সুস্পষ্ট সত্য অনুসরণ করছ।"],
  "27:80": ["You do not make the dead hear, nor do you make the deaf hear the call when they turn their backs.", "তুমি পারবে না মৃতকে, না বধিরকে, ডাক শোনাতে, যদি তারা মুখ ফিরিয়ে নেয়।"],
  "27:81": ["You cannot guide the blind out of their straying; you make none hear except whoever believes in Our signs, and they are submitters.", "না তুমি অন্ধদেরকে তাদের পথভ্রষ্টতা থেকে পথ দেখাতে পারবে। শুধু তারা তোমার কথা শুনবে যারা আমাদের প্রকাশনাবলীতে বিশ্বাস করে, এবং আত্মসমর্পণকারী হবার সিদ্ধান্ত নেয়।"],
  "27:82": ["When the word befalls them, We will bring out for them a creature from the earth speaking to them that the people had no certainty in Our signs.", "সঠিক সময়ে আমরা তাদের জন্য উপস্থাপন করবো ভূমিজাত উপাদান দিয়ে বানানো এক সৃষ্টি, যা ঘোষণা করবে যে লোকরা আমাদের প্রকাশনাবলীর বিষয়ে নিশ্চিত নয়।"],
  "27:83": ["The day We gather from every people a company of those who denied Our signs, and they are marshaled.", "সে দিন আসবে যখন আমরা প্রত্যেক জনপদ থেকে বলপূর্বক তলব করবো তাদের কতককে যারা আমাদের প্রমানগুলো বিশ্বাস করেনি।"],
  "27:84": ["Until when they come, Allah will say: Did you deny My signs without having encompassed them in knowledge? What was it that you were doing?", "যখন তারা উপস্থিত হবে, তিনি বলবেন, “তোমরা আমার প্রকাশনাবলী প্রত্যাখ্যান করেছ, তার বিষয়ে জ্ঞান অর্জন করার আগেই। এটাই  কি তা নয় যা তোমরা করেছিলে।"],
  "27:85": ["The word befalls them for the wrong they did, and they do not speak.", "তারা নিজেদের উপর টেনে আনবে তাদের অন্যায়াচরণের প্রতিফল, তারা কিছুই বলবে না।"],
  "27:86": ["Do they not see that We made the night for them to rest in, and the day for seeing? In that are signs for people who believe.", "তারা কি দেখেনি যে আমরা রাতকে বানিয়েছি তাদের বিশ্রামের জন্য, এবং দিনকে করেছি আলোকিত? এগুলো যথেষ্ট প্রমান হওয়া উচিৎ সে সব লোকদের জন্য যারা বিশ্বাস করে।"],
  "27:87": ["The day the trumpet is blown, and all who are in the heavens and the earth are seized with dread except whom Allah wills; and all come to Allah humbled.", "সেই দিনে যখন শিংগায় ফু দেয়া হবে, আকাশমণ্ডলী এবং পৃথিবীর সকলে ভীত হয়ে পড়বে, আল্লাহ যাদেরকে চান তারা ব্যতিত। সকলেই তাঁর সামনে আসবে, বলপূর্বক।"],
  "27:88": ["You see the mountains, thinking them motionless, while they pass with the passing of the clouds — the doing of Allah, who perfected everything. Allah is fully aware of what you do.", "তুমি যখন পর্বতগুলোকে দেখো, তুমি মনে করো যে তারা নিশ্চল দাড়িয়ে আছে। কিন্তু তারা চলছে, মেঘমালার মত। এমনই আল্লাহর নির্মাণ, যিনি সবকিছুকে নিখুঁত করেছেন। তিনি সম্পূর্ণরুপে জানেন তোমরা যাকিছু করো।"],
  "27:89": ["Whoever comes with the good will have better than it, and they that day are secure from dread.", "যারা (তাদের নথীতে) ভালো কাজ নিয়ে আসবে তারা অনেক উত্তম পুরস্কার পাবে, এবং তারা সেই দিনের বিভীষিকা থেকে সম্পূর্ণ নিরাপদ থাকবে।"],
  "27:90": ["Whoever comes with the evil, their faces are thrust into the fire. Are you recompensed except for what you used to do?", "তাদের ক্ষেত্রে যারা মন্দ কাজ নিয়ে আসবে, তাদেরকে বলপূর্বক নরকে পাঠানো হবে। তোমরা কি তারই প্রতিফল পাওনা যা তোমরা করেছ?"],
  "27:91": ["I was commanded only to serve the Rabb of this town, who made it sacred; to Allah belongs everything. And I was commanded to be one of the submitters.", "আমি কেবল এই শহরের প্রভুর উপাসনা করতে আদেশ প্রাপ্ত হয়েছি-তিনি একে এক নিরাপদ উপাসনা স্থল করেছেন-এবং সকল বস্তু অধিকারী। আমি  আদেশ প্রাপ্ত হয়েছি একজন আত্মসমর্পণকারী হতে।"],
  "27:92": ["And to recite the Recitation. Whoever is guided is guided only for himself; and whoever goes astray — say: I am only one of the warners.", "এবং কুরআন পাঠ করতে। যেকেউ পথপ্রাপ্ত হয় সে তার নিজের ভালোর জন্যই পথপ্রাপ্ত হয়, এবং যদি তারা বিপথগামী হয়, তবে বল, “আমি কেবল একজন সতর্ককারী”।"],
  "27:93": ["And say: Praise belongs to Allah. Allah will show you Allah's signs, and you will recognize them. Your Rabb is not unmindful of what you do.", "এবং বল, “প্রশংসা আল্লাহর; তিনি তোমাদেরকে তাঁর প্রমান দেখাবেন, যতক্ষণ না তোমরা সেগুলো চিনতে পারো। তোমরা যা কিছুই করো তোমার প্রভু তা সম্পর্কে কখনই অনবহিত নন”।"],
  "28:1": ["Ta Sin Mim", "ত. শ. ম."],
  "28:2": ["Those are the signs of the clear Book.", "এই (অক্ষরগুলো) এই জ্ঞানগর্ভ গ্রন্থের প্রমান গঠন করে।"],
  "28:3": ["We recite to you from the account of Musa and Fir'awn in truth, for a people who believe.", "আমরা এখানে তোমার কাছে মুসা এবং ফেরাউনের কিছু ইতিহাস আবৃত্তি করছি, সত্য সহকারে, সেসব লোকদের উপকারের জন্য যারা বিশ্বাস করে।"],
  "28:4": ["Fir'awn exalted himself in the land and made its people parties, subjecting a party of them, slaughtering their sons and letting their nisa live; he was indeed among the corrupters.", "ফেরাউন পৃথিবীতে স্বেচ্ছাচারী শাসকে পরিণত হয়েছিল, এবং কিছু লোকের বিরুদ্ধে বৈষম্যসূচক আচরণ করেছিল। সে অত্যাচার করছিল তাদের এক অসহায় দলের উপরে, যাদের পুত্রদের সে হত্যা করতো, আর তাদের কন্যাদের জীবিত রাখতো। নিশ্চয়, সে ছিল পাপী।"],
  "28:5": ["And We wanted to favor those who were subjected in the land, and to make them leaders, and make them the heirs,", "যারা পৃথিবীতে নির্যাতিত ছিল আমরা চাইলাম তাদেরকে ক্ষতিপূরণ দিতে, তাদেরকে নেতা বানাতে এবং উত্তরাধিকারী করতে।"],
  "28:6": ["and to establish them in the land, and to show Fir'awn and Haman and their hosts, from them, that which they used to beware.", "এবং তাদেরকে পৃথিবীতে প্রতিষ্ঠিত করতে, এবং ফেরাউন, হামান এবং তাদের সেনাবাহিনীকে আস্বাদন করাতে তাদের নিজেদের ঔষধের স্বাদ।"],
  "28:7": ["And We inspired Musa's mother: nurse him; then, when you fear for him, cast him into the sea, and do not fear and do not grieve; We will return him to you and make him among the Rasuls.", "আমরা মুসার মাকে অনুপ্রেরণা দিলাম “তাকে দুধ পাণ করাও, এবং যখন তুমি তার জীবন নিয়ে আশঙ্কা করো, তাকে নদীতে ভাসিয়ে দাও, কোন ভয় বা দুঃখ না করে। আমরা তাকে তোমার কাছে ফিরিয়ে দেবো, এবং তাকে বানাবো বার্তাবাহকদের একজন।\""],
  "28:8": ["So the house of Fir'awn picked him up, to be for them an enemy and a grief; Fir'awn and Haman and their hosts were indeed erring.", "ফেরাউনের পরিবার তাকে তুলে নিল, পরিনামে সে কেবল বিরোধী দলের নেতৃত্ব দিল এবং তাদের দুঃখের কারন হয়ে দাঁড়ালো। এটা এ কারনে যে ফেরাউন, হামান এবং তাদের সেনাবাহিনী ছিল সীমালঙ্ঘনকারী।"],
  "28:9": ["And Fir'awn's imra'a said: a delight to my eye and yours; do not kill him; perhaps he may benefit us, or we may take him as a son; and they did not perceive.", "ফেরাউনের স্ত্রী বলল, “এটা তোমার এবং আমার জন্য এক সুখকর প্রাপ্তি হতে পারে। তাকে হত্যা করো না, কারন সে হয়তো আমাদের কিছু উপকারে আসতে পারে, অথবা আমরা তাঁকে আমাদের সন্তান হিসাবে দত্তক নিতে পারি। \" তাদের কোন ধারনাই ছিল না।"],
  "28:10": ["And the heart of Musa's mother became empty; she had nearly disclosed him, had We not bound her heart, so that she would be among the muminin.", "মুসার মায়ের মন এতো উদ্বিগ্ন হয়ে পড়ছিল যে সে তার পরিচয় প্রায় প্রকাশ করেই ফেলেছিল। কিন্তু আমরা তার হৃদয়কে দৃঢ় করেছিলাম, তাকে একজন বিশ্বাসী বানানোর জন্য।"],
  "28:11": ["She said to his sister: track him; so she watched him from the side, while they did not perceive.", "সে তার বোনকে বলল, “তার পথ অনুসরণ করো।\" সে তাকে দূর থকে লক্ষ্য করছিল, তাদের অজ্ঞাতসারে।"],
  "28:12": ["And We barred him from the wet-nurses before; so she said: shall I point you to a household that will undertake him for you, and they are sincere to him?", "আমরা তাকে সব স্তন্যদানকারী মায়েদের থেকে বিরত রেখেছিলাম।(তার বোন) তখন বলল, “আমি তোমাদের একটি পরিবারের সন্ধান দিতে পারি যারা তাকে তোমাদের জন্য লালন পালন করতে পারবে, এবং তার ভালো যত্ন নেবে।\""],
  "28:13": ["So We returned him to his mother, that her eye might be comforted and she might not grieve, and that she might know Allah's promise is true; but most of them do not know.", "এভাবে আমরা তাকে তার মায়ের কাছে ফিরিয়ে দিলাম, তাকে খুশি করতে, তার উদ্বেগ দূর করতে, এবং তাকে জানাতে যে আল্লাহর অঙ্গীকার সত্য। কিন্তু, তাদের বেশির ভাগই জানে না।"],
  "28:14": ["And when he reached his full strength and was settled, We gave him judgment and knowledge; and thus We repay the doers of good.", "যখন সে পরিণত বয়সে পৌঁছল এবং সবল হলো, আমরা তাকে প্রজ্ঞা ও জ্ঞান দান করলাম। আমরা এভাবে সৎ-কর্মীদের পুরস্কৃত করি।"],
  "28:15": ["And he entered the town at a time of unmindfulness of its people, and found in it two men fighting — one of his party and one of his enemy; so the one of his party called him for help against the one of his enemy, and Musa struck him and finished him. He said: this is of the work of Shaytan; he is an enemy, clearly misguiding.", "একবার সে অপ্রত্যাশিতভাবে শহরে প্রবেশ করলো, যেন লোকেরা তাকে চিনতে না পারে। সে দুজন লোককে লড়াই করতে দেখল; একজন ছিল (হিব্রু) তার লোকদের মধ্যে থেকে, এবং অন্যজন ছিল (একজন মিশরীয়) তার শত্রুদের থেকে। তার দলের লোকটি শত্রুর বিরুদ্ধে সাহায্য চেয়ে তাকে ডাকল। মুসা তাকে ঘুষি মারল, এতে তার মৃত্যু হল। সে বলল, “এটা শয়তানের কাজ, সে এক প্রকৃত শত্রু, এবং ঘোর পথভ্রষ্টকারী।\""],
  "28:16": ["He said: my Rabb, I have wronged myself, so forgive me. So Allah forgave him; indeed, Allah alone is the Forgiving, the Raheem.", "সে বলল, “আমার প্রভু, আমি আমার আত্মার ক্ষতি করেছি। দয়া করে আমাকে ক্ষমা করুন, ” এবং তিনি তাকে ক্ষমা করে দিলেন। তিনি ক্ষমাশীল, পরম দয়ালু।"],
  "28:17": ["He said: my Rabb, for what You have bestowed on me, I will never be a backer of the guilty.", "সে বলল, “আমর প্রভু, আমার উপর আপনার আশীর্বাদের বিনিময়ে, আমি কখনো কোন অপরাধীর সমর্থনকারী হবো না।\""],
  "28:18": ["So he was in the town come morning, fearful, watching; and the one who had sought his help yesterday was crying out to him for help. Musa said to him: you are clearly misled.", "সকালে, সে শহরের ভেতরে ছিল, ভীত এবং সতর্ক অবস্থায়। যে ব্যক্তি গতকাল তার কছে সাহায্য চেয়েছিল, সে পুনরায় তার কাছে সাহায্য চাইল। মুসা তাকে বলল, “তুমি আসলেই এক সমস্যা সৃষ্টিকারী।\""],
  "28:19": ["So when he wanted to seize with might the one who was an enemy to both of them, he said: Musa, do you want to kill me as you killed a soul yesterday? You only want to be an overpowering one in the land, and you do not want to be among those who set things right.", "তাদের উভয়ের শত্রুকে আঘাত করতে উদ্যত হবার আগেই, সে বলে উঠল, “হে মুসা, তুমি কি আমাকে খুন করতে চাও, যেমন গতকাল আরেকজনকে খুন করেছিলে? স্পষ্টতই, তুমি পৃথিবীতে অত্যাচারী হতে চাও; তুমি সৎ-কর্মী হতে চাও না।"],
  "28:20": ["And a man came from the far end of the town, hastening; he said: Musa, the chiefs are conferring about you to kill you, so leave; I am among the nasihin to you.", "শহরের অন্যপ্রান্ত থেকে এক লোক দৌড়ে এসে বলল, “হে মুসা, লোকেরা তোমাকে হত্যা করার পরিকল্পনা করছে। তুমি বরং অনতিবিলম্বে বেড়িয়ে পড়ো। আমি তোমাকে সু-পরামর্শ দিচ্ছি।\""],
  "28:21": ["So he left it, fearful, watching; he said: my Rabb, deliver me from the wrongdoing people.", "সে শহর থেকে পালালো, ভীত এবং সতর্ক অবস্থায়। সে বলল, “আমার প্রভু, আমাকে নিষ্ঠুর লোকদের থেকে রক্ষা করুন।\""],
  "28:22": ["And when he set out toward Madyan, he said: perhaps my Rabb will guide me to the straight way.", "মাদিয়ানের উদ্দেশ্যে যাত্রা করার সময়, সে বলল, “আমার প্রভু যেন আমাকে সঠিক পথে পরিচালিত করেন।\""],
  "28:23": ["And when he arrived at the water of Madyan, he found at it a group of people giving drink, and found apart from them two nisa holding back. He said: what is your affair? They said: we do not give drink until the keepers depart, and our father is an old man.", "যখন সে মাদিয়ানের পানির কাছে পৌঁছল, সে দেখল লোকেরা ভিড় করে (পশুদের) পানি পান করাচ্ছে, এবং লক্ষ্য করলো দুজন নারী পাশে অপেক্ষা করছে। সে বলল, “তোমাদের কি প্রয়োজন?” তারা বলল, \"আমরা আমাদের পশুদের পানি পান করাতে পারছি না, যতক্ষণ না ভিড় সরে যায়, এবং আমাদের পিতা একজন বৃদ্ধ লোক।\""],
  "28:24": ["So he gave drink to the two, then turned aside to the shade and said: my Rabb, whatever good You send down to me, I am in need.", "সে তাদের পশুগুলোকে পানি পান করাল, এরপর ছায়ায় যেয়ে বলল, “আমার প্রভু, যা কিছুই আপনি আমার জন্য পাঠান, আমার তা ভীষণ প্রয়োজন।\""],
  "28:25": ["Then one of the two came to him, walking shyly; she said: my father invites you, to repay you the reward for what you gave drink to us. So when he came to him and narrated to him the account, he said: do not fear; you have been delivered from the wrongdoing people.", "অবিলম্বে, দুই নারীর একজন তার কাছে আসলো, লাজুকভাবে, এবং বলল, “আমার পিতা আপনাকে আমন্ত্রন করেছেন আপনাকে পারিশ্রমিক দিতে আমদের পশুগুলোকে পানি পান করানোর জন্য।\" যখন সে তার সাথে সাক্ষাৎ করলো, এবং তাকে তার কাহিনী শোনালো, সে বলল, “ভয় করো না। তুমি অত্যাচারী লোকদের থেকে রক্ষা পেয়েছো।\""],
  "28:26": ["One of the two said: father, hire him; the best you can hire is the strong, the trustworthy.", "দুজন নারীর একজন বলল, “হে আমার পিতা, তাকে কাজে নিযুক্ত করুন। কাজে নিযুক্ত করার জন্য সে সবচেয়ে ভালো, কারন সে শক্তিশালী এবং সৎ।\""],
  "28:27": ["He said: I want to marry you to one of these two daughters of mine, on condition that you hire me for eight pilgrimages; and if you complete ten, it is from your own favor. And I do not want to be hard on you; you will find me, Allah willing, among the salihin.", "সে বলল, “আমি তোমাকে আমরা দুই কন্যার একজনকে বিয়ে করার প্রস্তাব দিতে চাই, আমার জন্য আট তীর্থযাত্রা কাজ করার বদলে, যদি তুমি তা দশ কর, তা হবে তোমার দিক থেকে ঐচ্ছিক। আমি এই বিষয়টি তোমার জন্য খুব কঠিন করতে চাই না। আল্লাহ চাইলে, তুমি আমাকে পাবে, সৎকর্মশীল।\""],
  "28:28": ["He said: that is between me and you; whichever of the two terms I complete, there is no wrong against me, and Allah is trustee over what we say.", "সে বলল, “আপনার ও আমার মধ্যে এটি একটি চুক্তি। যে সময়কালই আমি পূর্ণ করি, আপনি কোনটিতেই বিরূপ হবেন না। আমরা যা বললাম আল্লাহ তার জামিনদার। \""],
  "28:29": ["And when Musa completed the term and journeyed on with his family, he saw from the side of the Mount a fire; he said to his family: stay, I have seen a fire; perhaps I will bring you news from it, or a brand from the fire, so that you may warm yourselves.", "যখন সে তার চুক্তি পূর্ণ করল, সে তার পরিবারকে নিয়ে যাত্রা করল (মিশরের দিকে)। সে সিনাই পর্বতের ঢাল থেকে আগুন দেখল। সে তার পরিবারকে বলল, “এখানে থাকো। আমি আগুন দেখেছি। হতে পারে আমি তোমাদের জন্য কোন খবর আনতে পারবো, অথবা আগুনের এক অংশ, (আনতে পারবো) তোমাদের উষ্ণতা দিতে।\""],
  "28:30": ["And when he came to it, he was called from the bank of the valley, on the right, in the blessed spot, from the tree: O Musa, I am Allah, Rabb of the worlds.", "যখন সে তার কাছ পৌঁছাল, তাকে উপত্যকার ডান প্রান্ত থেকে ডাকা হল, পবিত্র স্থানে যেখানে জলন্ত ঝোপ অবস্থিত ছিলঃ “হে মুসা, এ হল আমি, আল্লাহ; মহা বিশ্বের প্রভু।"],
  "28:31": ["And: cast your staff. So when he saw it shaking as if it were a serpent, he turned away fleeing and did not turn back. O Musa, come forward and do not fear; you are among the secure.", "“তোমার লাঠি ছুড়ে ফেল।\" যখন সে এটাকে দানবের মত চলতে দেখল, সে পেছনে ফিরে পালালো। “হে মুসা, ফিরে এসো; ভয় করো না। তুমি সম্পূর্ণ নিরাপদ।"],
  "28:32": ["Thread your hand into your pocket: it will come out white, without any blemish; and press your wing to yourself, in awe. Those are two clear proofs from your Rabb to Fir'awn and his assembly; they were a defiant people.", "“তোমার হাত তোমার পকেটে রাখো; এটি সাদা হয়ে বের হয়ে আসবে কোন ত্রুটি ছাড়াই। তোমার বাহুদ্বয় ভাঁজ করো এবং ভয় মুক্ত হও। এই হলো দুটি প্রমান তোমার প্রভুর পক্ষ থেকে, ফেরাউন এবং তার সভাসদদের দেখানোর জন্য; তারা হচ্ছে পাপী লোক।\""],
  "28:33": ["He said: my Rabb, I killed a soul among them, so I fear that they will kill me.", "সে বলল, “আমার প্রভু, আমি তাদের একজনকে হত্যা করেছি, এবং আমার ভয় হয় যে তারা আমাকে হত্যা করবে।"],
  "28:34": ["And my brother Harun is more eloquent of tongue than I; so send him with me as a backer, to confirm me; I fear that they will give me the lie.", "“আর, আমার ভাই হারুন আমার চেয়ে অধিক বাকপটু। তাকে আমার সাথে পাঠান একজন সাহায্যকারী হিসাবে আমাকে সমর্থন করতে এবং আমার শক্তি জোগাতে। আমি ভয় করি পাছে তারা আমাকে অবিশ্বাস করে।\""],
  "28:35": ["Allah said: We will strengthen your arm with your brother, and give you two a warrant, so they will not reach you two. With our signs, you two and whoever follows you are the overcomers.", "তিনি বললেন, “আমরা তোমাকে তোমার ভাইয়ের দ্বারা শক্তিশালী করবো, এবং আমরা তোমাদের উভয়কে সুস্পষ্ট কর্তৃত্ব প্রদান করবো। ফলে, তারা তোমাদের দুজনের একজনকেও স্পর্শ করতে পারবে না। আমাদের নিদর্শনাবলীর নিয়ে, তোমরা দুজন, তোমাদেরকে যারা অনুসরণ করে তারা সহ, জয়ী হবে।\""],
  "28:36": ["And when Musa came to them with our clear signs, they said: this is nothing but fabricated magic, and we have not heard of this among our fathers of old.", "যখন মুসা তাদের কাছে গেল আমাদের স্পষ্ট এবং প্রগাঢ় প্রমান সহ, তারা বলল, “এটা তো অলীক জাদু। আমরা কখনো আমাদের প্রাচীন পূর্বপুরুষদের থেকে এরুপ শুনিনি।\""],
  "28:37": ["And Musa said: my Rabb knows best who came with the guidance from Allah, and whose will be the final end of the abode; the wrongdoers do not attain success.", "মুসা বলল, “আমার প্রভু সবচেয়ে ভাল জানেন কে তাঁর থেকে পথনির্দেশনা নিয়ে এসেছে, এবং কে হবে চূড়ান্ত বিজয়ী। নিশ্চিতভাবে, সীমালঙ্ঘনকারীরা কখনই সফল হয় না।\""],
  "28:38": ["And Fir'awn said: O chiefs, I know of no ilah for you other than me; so kindle for me, O Haman, over the clay, and make for me a tower, so that I may climb up to the ilah of Musa — I think he is among the kazibin.", "ফেরাউন বলল, “হে আমার সভাসদগণ, তোমাদের জন্য আমি ছাড়া অন্য কোন উপাস্যকে আমার জানা নেই। অতএব, ইট পোড়াও, হে হামান, একটা মিনার তৈরি করার জন্য, যাতে আমি মুসার উপাস্যকে এক নজর দেখতে পারি। আমি নিশ্চিত যে সে এক মিথ্যাবাদী।\""],
  "28:39": ["And he and his hosts grew arrogant in the land without right, and they supposed that they would not be returned to us.", "এভাবে, সে এবং তার সৈন্যবাহিনী পৃথিবীতে ঔদ্ধত্য করতে থাকলো, কোন অধিকার ছাড়াই, এবং ভাবল যে তারা আমাদের কাছে ফিরে আসবে না।"],
  "28:40": ["So We seized him and his hosts, and cast them into the sea; so look how was the final fate of the wrongdoers.", "ফলস্বরূপ, আমি তাকে এবং তার সৈন্যবাহিনীকে শাস্তি দিয়েছিলাম, তাদেরকে সমুদ্রে নিক্ষেপ করে। সীমালঙ্ঘনকারীদের পরিণাম লক্ষ্য করো।"],
  "28:41": ["And We made them leaders calling to the fire; and on the Day of Standing they will not be helped.", "আমরা তাদেরকে ইমাম করেছিলাম যারা তাদের লোকদের নরকের দিকে পরিচালিত করেছিল। উপরন্তু, পুনরুত্থানের দিনে, তাদের কোন সাহায্যকারী থাকবে না।"],
  "28:42": ["And We made a curse follow them in this nearer life; and on the Day of Standing they are among the despised.", "তারা এই জীবনে টেনে এনেছে দণ্ডাদেশ, এবং পুনরুত্থানের দিনে তারা হবে ঘৃণিত।"],
  "28:43": ["And We surely gave Musa the Book, after We destroyed the former generations — insights for the people, and guidance and a mercy, so that they might remember.", "আমরা মুসাকে দিয়েছিলাম ঐশীগ্রন্থ – পূর্ববর্তী প্রজন্মদের ধ্বংস করে দেবার পর, এবং তাদের মাধ্যমে উদাহরন স্থাপন করার পর – লোকদের জন্য প্রদান করতে, জ্ঞানবর্তিকা আর পথনির্দেশনা, এবং দয়া, যাতে তারা মনোযোগ দিতে পারে।"],
  "28:44": ["And you were not by the side of the western slope when We decreed to Musa the affair, and you were not among the witnesses.", "তুমি উপস্থিত ছিলে না পশ্চিমা পর্বতের ঢালে, যখন আমরা মুসার কাছে হুকুম জারী করেছিলাম; তুমি প্রত্যক্ষদর্শী ছিলে না।"],
  "28:45": ["But We raised up generations, and the life-term was prolonged over them; and you were not lodging among the people of Madyan, reciting to them our signs, but We were the senders.", "কিন্তু আমরা প্রতিষ্ঠিত করেছিলাম অনেক প্রজন্মকে, এবং, সময়ের ব্যাপ্তির কারনে, (তারা পথভ্রষ্ট হয়েছিল)। না তুমি ছিলে মাদিয়ানের লোকদের মধ্যে, তাদের কাছে আমাদের প্রকাশনাবলী আবৃত্তি করতে। কিন্তু আমরা ঠিকই বার্তাবাহক পাঠিয়েছিলাম।"],
  "28:46": ["And you were not by the side of the Mount when We called; but it is a mercy from your Rabb, that you may warn a people to whom no warner came before you, so that they might remember.", "না তুমি ছিলে সিনাই পর্বতের ঢালে যখন আমারা (মুসাকে) ডেকেছিলাম। কিন্তু এটা তোমার প্রভুর পক্ষ থেকে করুনা, (লোকদের প্রতি), সেসব লোকদের সতর্ক করতে যারা তোমার আগে কোন সতর্ককারী পায়নি, যাতে তারা মনোযোগ দিতে পারে।"],
  "28:47": ["And lest an affliction strike them for what their hands have sent forward, and they say: our Rabb, why did You not send us a Rasul, so that we would follow your signs and be among the muminin?", "যাতে, তারা বলতে না পারে, যখন কোন বিপর্যয় তাদের নিজেদের কাজের পরিণাম স্বরূপ তাদের আঘাত করে, “আমাদের প্রভু, আপনি যদি আমাদের কাছে কোন বার্তাবাহক পাঠাতেন, আমরা আপনার প্রকাশনাবলী অনুসরণ করতাম, এবং বিশ্বাসী হতাম।\""],
  "28:48": ["So when the truth came to them from us, they said: why was he not given the like of what Musa was given? Did they not disbelieve in what was given to Musa before? They said: two magics backing each other; and they said: we are committing kufr in everything.", "এখন যখন আমাদের পক্ষ থেকে সত্য তাদের কাছে এসেছে, তারা বলল, “শুধু যদি আমাদেরকে তা দেয়া হতো যা মুসাকে দেয়া হয়েছিল!” তারা কি অতীতে অবিশ্বাস করেনি যা মুসাকে দেয়া হয়েছিল তাতে? তারা বলল, “উভয় (ঐশীগ্রন্থই) জাদু, যার একটিকে অন্যটি নকল করেছে। তারা আরও বলল, “আমরা দুটিতেই অবিশ্বাসী।\""],
  "28:49": ["Say: then bring a book from Allah, more guiding than these two, and I will follow it, if you are sadiq.", "বল, “তাহলে আল্লাহর কাছ থেকে এই দুটির থেকে উত্তম পথনির্দেশনা সহ একটি ঐশীগ্রন্থ নিয়ে আসো, যাতে আমি তা অনুসরণ করতে পারি, যদি তোমরা  সত্যবাদী হয়ে থাকো।\""],
  "28:50": ["So if they do not answer you, then know that they only follow their desires; and who is more misled than the one who follows their desire without guidance from Allah? Allah does not guide the wrongdoing people.", "যদি তারা তোমার ডাকে সাড়া দিতে ব্যর্থ হয়, তবে জেনে নাও যে তারা কেবল তাদের নিজেদের মতামতের অনুসরণ করে। তাদের থেকে কে অধিক পথভ্রষ্ট যারা তাদের নিজেদের মতামতের অনুসরণ করে, আল্লাহর থেকে পথনির্দেশনা ছাড়াই? আল্লাহ এমন অন্যায়কারী লোকদের পথপ্রদর্শন করেন না।"],
  "28:51": ["And We surely joined the word for them, so that they might remember.", "আমরা তাদের কাছে বার্তা পৌঁছিয়েছি, যাতে তারা মনোযোগ দেয়।"],
  "28:52": ["Those to whom We gave the Book before it — they believe in it.", "যাদেরকে আমরা পূর্ববর্তী ঐশীগ্রন্থ দিয়ে আশীর্বাদ করেছি তারা এতে বিশ্বাস করবে।"],
  "28:53": ["And when it is recited to them, they say: we believe in it; it is the truth from our Rabb; we were, before it, submitted.", "যখন এটি তাদের কাছে আবৃত্তি করা হয়, তারা বলে, “আমরা এটাতে বিশ্বাস করি, এটি আমাদের প্রভুর পক্ষ থেকে সত্য। এমনকি এটি শোনার আগেও, আমরা আত্মসমর্পণকারী ছিলাম।\""],
  "28:54": ["Those will be given their reward twice, for what they sabirly bore; and they ward off the bad with the good, and from what We provided them they spend.", "এদেরকে আমরা দিগুন পুরস্কার প্রদান করি, কারন তারা দৃঢ়তার সাথে অধ্যবসায়ী। তারা মন্দ কাজকে প্রতিহত করে ভালো কাজ দিয়ে, এবং তাদের কাছে আমাদের জীবিকা থেকে, তারা দেয়।"],
  "28:55": ["And when they hear idle talk, they turn aside from it and say: our deeds are for us and your deeds are for you; peace be upon you — we do not seek the ignorant.", "যখন তারা অসার কথাবার্তার সম্মুখীন হয়, তারা তা উপেক্ষা করে এবং বলে, “আমরা দায়ী আমাদের কাজের জন্য, এবং তোমরা দায়ী তোমাদের কাজের জন্য। তোমাদের উপর শান্তি বর্ষিত হোক। আমরা অজ্ঞদের মতো আচরণ করতে চাই না।\""],
  "28:56": ["You do not guide whom you love; but Allah guides whom Allah wills, and Allah knows best the guided ones.", "তুমি যাকে ভালোবাসো তাকে পথ প্রদর্শন করতে পারো না। আল্লাহ-ই একমাত্র সত্ত্বা যিনি পথপ্রদর্শন করেন তাঁর ইচ্ছানুসারে, এবং যারা পথ পাবার যোগ্য তাদের বিষয়ে তাঁর জ্ঞান অনুসারে।"],
  "28:57": ["And they say: if we follow the guidance with you, we will be snatched from our land. Did We not establish for them a secure sanctuary, to which are gathered the fruits of everything, as provision from our presence? But most of them do not know.", "তারা বলল, “যদি আমরা তোমার পথনির্দেশনা অনুসরণ করি, আমরা নির্যাতন ভোগ করবো।\" আমরা কি তাদের জন্য একটি পবিত্র আশ্রয় স্থল স্থাপন করিনি, যাতে সকল প্রকার ফল সহজলভ্য করা হয়েছে, আমাদের পক্ষ থেকে জীবিকা হিসাবে? নিশ্চয়, তাদের অধিকাংশ জানে না।"],
  "28:58": ["And how many a town We destroyed that exulted in its living; so those are their dwellings — hardly dwelt in after them — and We were the inheritors.", "অনেক সম্প্রদায়কে আমরা ধ্বংস করেছি জীবনের প্রতি তারা অকৃতজ্ঞ হয়ে পড়ার কারনে। ফলস্বরূপ, এই হচ্ছে তাদের ঘরবাড়ি, যেগুলো তাদের পর বসতিহীন ধ্বংসাবশেষ ছাড়া কিছুই নয়, অল্প কিছু ব্যতিক্রম। আমরাই উত্তরাধিকারী ছিলাম।"],
  "28:59": ["And your Rabb would never destroy the towns until raising in their mother-town a Rasul, reciting to them our signs; and We were never destroyers of the towns unless their people were wrongdoers.", "কারন তোমার প্রভু কখনই কোন জনপদকে ধ্বংস করেন না তাদের কাছে আমাদের প্রকাশনাবলী আবৃত্তি করতে তাদের মধ্যে বার্তাবাহক না পাঠিয়ে। আমরা কখনই কোন জনপদকে ধ্বংস করি না, যদিনা এর লোকরা অন্যায়কারী হয়।"],
  "28:60": ["And whatever you are given of anything is the enjoyment of the nearer life and its adornment; and what is with Allah is better and more lasting; will you not reason?", "যা কিছু তোমাদের দেওয়া হয়েছে তা শুধু এই জীবনের বস্তুসমগ্রি, এবং এর অসার আড়ম্বর। যা আল্লাহর কাছে আছে তা অনেক উত্তম, এবং চিরস্থায়ী। তোমারা কি বুঝো না।"],
  "28:61": ["So is the one We promised a good promise — and they will meet it — like the one We let enjoy the enjoyment of the nearer life, and then they, on the Day of Standing, are among the brought-before?", "যাকে আমরা অঙ্গিকার করেছি এক উত্তম প্রতিশ্রুতির যা অবশ্যই ঘটবে, সে  কি তার মতো যাকে আমরা এই জীবনের ক্ষণস্থায়ী বস্তুসমগ্রি প্রদান করেছি, এরপর পুনরুত্থান দিনে সে ভোগ করবে চিরস্থায়ী নরকভোগ।"],
  "28:62": ["And on the day they are called — where are the associates of Allah that you used to claim?", "সে দিন আসবে যখন তিনি তাদের ডেকে বলবেন, “কোথাই সেই উপাস্যরা যাদেরকে তোমরা আমার পাশে স্থাপন করেছিলে?”"],
  "28:63": ["Those on whom the word holds true said: our Rabb, these are the ones we misled; we misled them as we were misled. We disavow them before you; they were not worshipping us.", "যারা দণ্ডাদেশ প্রাপ্ত হয়েছে তারা বলবে, “আমাদের প্রভু, এরাই সেসব বাক্তি যাদের আমরা পথভ্রষ্ট করেছিলাম; আমরা তাদের পথভ্রষ্ট করেছিলাম শুধু এই কারনে যে আমরা নিজেরাই পথভ্রষ্ট ছিলাম। আমরা এখন নিজেদেরকে সম্পূর্ণ রুপে আপনার কাছে উৎসর্গ করছি। তারা আসলে আমাদের উপাসনা করত না।\""],
  "28:64": ["And it was said: call your associates; so they called them, but they did not answer them, and they saw the chastisement — if only they had been guided.", "তাদেরকে বলা হবে, “তোমাদের উপাস্যদের ডাকো (তোমাদেরকে সাহায্য করতে)।\" তারা তাদেরকে ডাকবে, কিন্তু তারা ডাকে সাড়া দেবে না। তারা শাস্তি ভোগ করবে, এবং আফসোস করবে “হায় যদি আমরা পথপ্রাপ্ত হতাম!”"],
  "28:65": ["And on the day they are called — what did you answer the Rasuls?", "সেই দিন, তিনি সকলকে জিজ্ঞাসা করবেন, “বার্তাবাহকদের ডাকে তোমাদের সাড়া কেমন ছিল?”"],
  "28:66": ["So the tidings were unperceived to them on that day, and they will not ask one another.", "সে দিন এসব ঘটনায় তারা এতোই স্তব্ধ হবে যে তারা নির্বাক হয়ে পড়বে।"],
  "28:67": ["As for the one who repented and believed and did salih work — then perhaps they will be among the muflihin.", "তাদের ক্ষেত্রে যারা অনুশোচনা করে, বিশ্বাস করে, এবং সৎ জীবন যাপন করে, তারা শেষ পর্যন্ত বিজয়ীদের অন্তর্ভুক্ত হবে।"],
  "28:68": ["And your Rabb creates what Allah wills and chooses; the choice was not theirs. Glory be to Allah, exalted above what they associate.", "তোমার প্রভুই সেই সত্ত্বা যিনি সৃষ্টি করেন যা কিছু তার ইচ্ছা, এবং পছন্দ  করেন, আর কেউ  পছন্দ করতে অংশ নেয়না। মহিমা আল্লাহর, পরম সমুচ্চ। অংশীদারের প্রয়োজন থেকে তিনি অনেক ঊর্ধ্বে।"],
  "28:69": ["And your Rabb knows what their chests conceal and what they declare openly.", "তোমার প্রভু জানেন তাদের বুকে লুকানো গভীরতম চিন্তাগুলো, সেই সাথে যা কিছু তারা প্রকাশ করে।"],
  "28:70": ["And Allah — there is no ilah but Allah; to Allah belongs the praise in the first and the last, and to Allah belongs the judgment, and to Allah you are returned.", "তিনি সেই এক আল্লাহ; তাঁর পাশে আর কোন উপাস্য নেই। সকল প্রশংসা তাঁর, এই প্রথম জীবনে, এবং পরকালে। তাঁর অধীনে সকল ফয়সালা  এবং তাঁর কাছেই তোমরা ফিরে যাবে।"],
  "28:71": ["Say: have you considered — if Allah made the night unceasing over you until the Day of Standing, what ilah other than Allah would bring you light? Will you not hear?", "বল, “কি হতো যদি আল্লাহ রাতকে চিরস্থায়ী করে দিতেন, পুনরুত্থান দিবস পর্যন্ত? আল্লাহ ছাড়া, কোন উপাস্য তোমাদের আলো দিতে পারে? তোমরা কি শোনো না?"],
  "28:72": ["Say: have you considered — if Allah made the day unceasing over you until the Day of Standing, what ilah other than Allah would bring you night in which you rest? Will you not see?", "বল, “কি হতো যদি আল্লাহ দিবালোককে চিরস্থায়ী করে দিতেন, পুনরুত্থান দিবস পর্যন্ত? আল্লাহ ছাড়া, কোন উপাস্য তোমাদের বিশ্রামের জন্য রাত দিতে পারে? তোমরা কি দেখো না?"],
  "28:73": ["And of Allah's mercy, Allah made for you the night and the day, that you may rest in it and seek of Allah's bounty, and so that you may give thanks.", "এটা তাঁর পক্ষ থেকে করুনা যে তিনি তোমাদের জন্য সৃষ্টি করেছেন রাত এবং দিনকে, (রাতের বেলায়) বিশ্রাম নেবার জন্য এরপর (দিনের বেলায়) তাঁর দেওয়া জীবিকা অন্বেষণ করার জন্য, যাতে তোমরা কৃতজ্ঞ হতে পারো।"],
  "28:74": ["And on the day they are called — where are the associates of Allah that you used to claim?", "সে দিন আসবে যখন তিনি তাদেরকে জিজ্ঞাসা করবেন, “কোথায় সেই শরীক উপাস্যরা যাদেরকে তোমরা উদ্ভাবন করেছেন আমার সমকক্ষ করতে?”"],
  "28:75": ["And We will pull out from every community a witness, and We will say: produce your clear proof; then they will know that the truth belongs to Allah, and lost from them will be what they used to fabricate.", "আমরা প্রত্যেক সম্প্রদায় থেকে একজন সাক্ষী বাছাই করবো, এরপর বলবো, “তোমাদের প্রমান উপস্থাপন করো”। তখন তারা উপলব্ধি করবে যে সকল সত্য আল্লাহর অধীন, আর তাদের মিথ্যা উদ্ভাবিত শরীক উপাস্যরা  তাদের পরিত্যাগ করবে।"],
  "28:76": ["Qarun was of the people of Musa, and he wronged them; and We gave him from the hoards such that their keys would strain a band of the mighty. When his people said to him: do not rejoice; Allah does not love the rejoicing ones.", "কারুন (ক্রিতদাস পরিচালক) ছিল মুসার লোকদের একজন যে তাদের সাথে প্রতারণা করেছিল এবং তাদের নির্যাতন করতো। আমি তাকে এতো ধনসম্পদ দিয়েছিলাম যে সেগুলোর চাবি সবচেয়ে শক্তিশালী দলের জন্যও খুব ভারি ছিল। তার লোকেরা তাকে বলল, “এতো উদ্ধত হইও না; আল্লাহ তাদেরকে ভালোবাসেন না যারা উদ্ধত।"],
  "28:77": ["And seek, in what Allah has given you, the last abode; and do not forget your allotted portion of the nearer life; and do good as Allah did good to you; and do not seek corruption in the land — Allah does not love the corrupters.", "“পরকালের বাসস্থান অন্বেষণে তোমার উপর আল্লাহর অর্পণ করা জীবিকা ব্যবহার করো, এই দুনিয়ায় তোমার অংশ উপেক্ষা না করে। দানশীল হও, যেমন আল্লাহ তোমার প্রতি দানশীল হয়েছেন। পৃথিবীতে দুর্নীতি করতে থেকোকো না। আল্লাহ দুর্নীতিপরায়ণদের ভালোবাসেন না।"],
  "28:78": ["He said: I was only given it on account of knowledge I have. Did he not know that Allah destroyed before him, among the generations, ones stronger than him in strength and greater in gathering? And the guilty are not asked about their offenses.", "সে বলল, “আমি এই সবকিছু অর্জন করেছি আমার নিজের কশুলতার কারনে।” সে কি উপলব্ধি করেনি যে আল্লাহ তার পূর্বে প্রজন্মদের ধ্বংস করেছিলেন যারা তার থেকে অধিক শক্তিশালী আর সংখ্যায় অধিক ছিল? সেই (ধ্বংস প্রাপ্ত) সীমালঙ্ঘনকারীরা তাদের অপরাধ সম্পর্কে জিজ্ঞাসিত হয়নি।"],
  "28:79": ["So he went out to his people in his adornment; those who desire the nearer life said: would that we had the like of what Qarun was given — he is indeed one of mighty portion.", "এক দিন, সে তার লোকদের কাছে পূর্ণ জাঁকজমকের সাথে বের হয়ে আসলো। যারা এই পার্থিব জীবনকে প্রাধান্য দিত তারা বলল, “আহা, আমাদের যদি তা থাকতো যা কারুন অর্জন করেছে। নিশ্চয়, সে খুব সৌভাগ্যশালী।\""],
  "28:80": ["And those given the knowledge said: woe to you; Allah's recompense is better for the one who believes and does salih work — and none meets it but the sabirin ones.", "তাদের ক্ষেত্রে যারা জ্ঞান পেয়ে সৌভাগ্যশালী ছিল, তারা বলল, “দুর্ভোগ তোমাদের,  আল্লাহর প্রতিদান তাদের জন্য অনেক উত্তম যারা বিশ্বাস করে এবং সৎ জীবন যাপন করে।\" অবিচলরা ছাড়া কেউ তা অর্জন করে না।"],
  "28:81": ["So We sank the earth with him and with his dwelling; and he had no band to help him apart from Allah, and he was not among the helped ones.", "আমরা তখন তাকে ও তার প্রাসাদকে জমিন দিয়ে গ্রাস করালাম। কোন সেনাবাহিনী আল্লাহর বিরুদ্ধে তাকে সাহায্য করতে পারতো না; বিজয়ী হওয়া তার নিয়তিতে ছিল না।"],
  "28:82": ["And come morning, those who had wished for his place yesterday were saying: it is as if Allah spreads the provision for whom Allah wills among the servants, and straitens; if Allah had not shown us favor, Allah would have sunk us too; it is as if the kafirin do not attain success.", "আগের দিন যারা তার প্রতি ঈর্ষান্বিত ছিল তারা বলল, “আমরা এখন উপলব্ধি করলাম যে আল্লাহই সেই সত্ত্বা যিনি তাঁর বান্দাদের মধ্যে থেকে যাকে চান তাকে জীবিকা প্রদান করেন, এবং তা রোধ করেন। যদি আমাদের প্রতি আল্লাহর অনুগ্রহ না হতো, তিনি আমাদেরকেও জমিন দিয়ে  গ্রাস করাতে পারতেন। আমরা এখন উপলব্ধি করলাম যে অবিশ্বাসীরা কখনই সফলকাম হয় না।\""],
  "28:83": ["That is the last abode; We make it for those who do not desire exaltation in the land nor corruption; and the final end is for the mindful ones.", "আমরা পরকালের গৃহ তাদের জন্য সংরক্ষিত রেখেছি যারা পৃথিবীতে না আত্মপ্রশংসা খোঁজে, না দুর্নীতি করে। চূড়ান্ত বিজয় সৎ-কর্মীদের।"],
  "28:84": ["Whoever comes with the good, theirs is better than it; and whoever comes with the bad — the doers of the bad deeds are only repaid what they used to do.", "যে কেউ সৎ-কর্ম করে সে আরো উত্তম পুরস্কার পায়। তাদের ক্ষেত্রে যারা পাপ করে, তাদের পাপের শাস্তি ঠিক তাদের কাজের সমতুল্য।"],
  "28:85": ["Indeed, the one who ordained the Recitation upon you will surely return you to the place of return. Say: my Rabb knows best who came with the guidance, and who is in clear error.", "নিশ্চয়, সেই সত্ত্বা যিনি তোমার জন্য কুরআন আদিষ্ট করেছেন, তিনি তোমাকে তলব করবেন এক পূর্ব নির্ধারিত সাক্ষাৎকারে। বল, “আমার প্রভু সম্পূর্ণ অবগত তাদের ব্যাপারে যারা পথনির্দেশনা ধারন করে, এবং তাদের ব্যাপারে যারা বিপথগামী।\""],
  "28:86": ["And you were not hoping that the Book would be cast to you, except as a mercy from your Rabb; so never be a backer of the kafirin.", "তুমি কখনই আশা করনি এই ঐশীগ্রন্থ তোমরা চলার পথে আসবে; কিন্তু এটা তোমার প্রভুর পক্ষ থেকে এক দয়া। অতএব, তুমি অবিশ্বাসীদের পক্ষ নেবে না।"],
  "28:87": ["And let them not bar you from the signs of Allah after they were sent down to you; and call to your Rabb, and never be among the associaters.", "না তুমি আল্লাহর প্রকাশনাবলী থেকে সরে যাবে, সেগুলো তোমার কাছে আসার পর, এবং অন্যদের তোমার প্রভুর দিকে অমন্ত্রন করবে। এবং কখনোই শরিক উপাসনায় পতিত হবে না।"],
  "28:88": ["And do not call, along with Allah, any other ilah; there is no ilah but Allah; everything perishes except the face of Allah; to Allah belongs the judgment, and to Allah you are returned.", "তুমি আল্লাহর পাশে অন্য কোন উপাস্যের উপাসনা করবে না। তাঁর পাশে অন্য কোন উপাস্য নেই। তাঁর উপস্থিতি ব্যতিত সবকিছু ধ্বংসশীল। সকল সার্বভৌমত্ব তাঁর, এবং তাঁর কাছেই তোমরা ফিরে যাবে।"],
  "29:1": ["Alif Lam Mim", "অ. ল. ম."],
  "29:2": ["Do people think that they will be left alone just by saying \"We believe,\" while they will not be tried?", "লোকেরা কি মনে করে যে তাদেরকে এই বললেই ছেড়ে দেয়া হবে,  \"আমরা বিশ্বাস করি,” পরীক্ষা করা ছাড়াই?"],
  "29:3": ["We have surely tried those before them, so Allah will surely know those who were sadiq and will surely know the kazibin.", "তাদের পূর্ববর্তীদেরকেও আমরা পরীক্ষা করেছি, কারণ আল্লাহ অবশ্যই সত্যবাদীদের আলাদা করবেন, আর তিনি অবশ্যই মিথ্যাবাদীদেরকে প্রকাশ করে দেবেন।"],
  "29:4": ["Or do those who do evil deeds think they will outstrip Us? Evil is what they decree.", "যারা পাপ করে তারা কি মনে করে যে তারা কখনো আমাদের বোকা বানাতে পারবে? নিশ্চয়, তাদের বিচার ভুল।"],
  "29:5": ["Whoever hopes to meet Allah — the term of Allah is surely coming, and Allah is the All-Hearing, the All-Knowing.", "যেকেউ আল্লাহর সাক্ষাত আশা করে, (তার জানা উচিত যে) আল্লাহর সাথে এমন এক সাক্ষাৎকার নিশ্চয় সংঘটিত হবে। তিনি সর্বশ্রোতা, সর্বজ্ঞ।"],
  "29:6": ["Whoever strives, strives only for his own soul; Allah is free of need of the worlds.", "যারা সংগ্রাম করে, তাদের নিজেদের ভালোর জন্য সংগ্রাম করে। আল্লাহর কাউকে প্রয়োজন নেই।"],
  "29:7": ["Those who believe and do salih deeds — We will surely absolve them of their evil deeds, and We will surely reward them with the best of what they used to do.", "যারা বিশ্বাস করে ও সৎ জীবন-যাপন করে, আমরা অবশ্যই তাদের পাপগুলোকে মাফ করে দেবো, এবং নিশ্চয়ই তাদেরকে উদারভাবে পুরষ্কৃত করবো তাদের সৎকর্মের জন্য।"],
  "29:8": ["We charged the human with good toward the two parents; but if they both strive against you to make you associate with Allah that of which you have no knowledge, do not obey them. To Allah is your return, and Allah will tell you what you used to do.", "আমরা মানুষকে তার পিতামাতাকে সম্মান করতে আদেশ দিয়েছি। কিন্তু যদি তারা আমার পাশে উপাস্যদের স্থাপন করতে তোমাকে জোর করার চেষ্টা করে, তাদেরকে মান্য করবে না। আমার কাছে তোমাদের চুড়ান্ত নিয়তি, এরপর আমি তোমাদেরকে জানাবো যাকিছু তোমরা করেছিলে।"],
  "29:9": ["Those who believe and do salih deeds — We will surely enter them among the salihin.", "যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে, আমরা নিশ্চয় তাদেরকে সৎকর্মশীলদের সাথে প্রবেশ করাবো।"],
  "29:10": ["Among the people is one who says \"We believe in Allah,\" but when harmed in Allah's cause, he regards the trial of people as the punishment of Allah. Yet if help comes from your Rabb, he says: \"We were with you.\" Is not Allah best aware of what is in the breasts of the worlds?", "লোকদের মধ্যে এমন আছে যারা বলে, \"আমরা আল্লাহতে বিশ্বাস করি,”কিন্তু যখনই আল্লাহর কারনে তারা কোন কষ্ট ভোগ করে, তারা লোকদের অত্যাচারকে আল্লাহর শাস্তির মত মনে করে। কিন্তু তোমার কাছে তোমার প্রভুর অনুগ্রহ আসলে, তারা বলে, \"আমরা তোমাদের সাথে ছিলাম।”আল্লাহ কি লোকদের গভীরতম চিন্তাগুলোর বিষয়ে সম্পূর্ণ সচেতন নন?"],
  "29:11": ["Allah will surely know those who believe, and Allah will surely know the munafiqin.", "যারা বিশ্বাস করে নিশ্চয় আল্লাহ তাদেরকে আলাদা করবেন,  এবং নিশ্চয় তিনি ভন্ডদের প্রকাশ করে দেবেন।"],
  "29:12": ["Those who disbelieve say to those who believe: \"Follow our way, and we will bear your errors.\" Yet they bear nothing of their errors at all — truly they are liars.", "যারা অবিশ্বাস করেছে তারা বিশ্বাসীদের  বলেছে, \"যদি তোমরা আমাদের পথ অনুসরণ করো, আমরা তোমাদের পাপভার  নিবো।” সত্য নয়; তারা তাদের কোন পাপভার বহন করতে পারবে না। তারা মিথ্যাবাদী।"],
  "29:13": ["They will surely bear their own weights, and weights along with their weights; and they will be asked on the Day of Resurrection about what they used to fabricate.", "প্রকৃতপক্ষে, তারা তাদের নিজেদের পাপভার বহন করবে, সেই সাথে অন্যদের পাপের বোঝা, যেগুলোর জন্য তারা দায়ী ছিল। নিশ্চয়, পুনরুত্থান দিবসে তাদেরকে তাদের মিথ্যা দাবীর বিষয়ে জিজ্ঞেস করা হবে।"],
  "29:14": ["We sent Nuh to his people, and he tarried among them a thousand years less fifty years; then the deluge seized them while they were wrongdoers.", "আমরা নূহকে তার লোকদের কাছে পাঠিয়েছিলাম, এবং সে তাদের সাথে পঞ্চাশ কম এক হাজার বছর  অবস্থান করেছিল। পরবর্তীতে, তারা তাদের সীমালঙ্ঘনের কারণে বন্যা টেনে এনেছিল।"],
  "29:15": ["We saved him and the companions of the ship, and We made it a sign for the worlds.", "আমরা তাকে ও তার সাথে যারা নৌকায় ছিল তাদেরকে রক্ষা করেছিলাম, এবং আমরা একে সব লোকদের জন্য একটি শিক্ষা হিসেবে স্থাপন করলাম।"],
  "29:16": ["And Ibrahim, when he said to his people: \"Worship Allah and be mindful of Allah; that is best for you, if you know.\"", "ইব্রাহিম তার লোকদের বলেছিল, \"তোমরা আল্লাহর উপাসনা করবে, এবং তাকে ভক্তি করবে। এটা তোমাদের জন্য উত্তম, যদি শুধু তোমরা জানতে।"],
  "29:17": ["You worship only idols besides Allah, and you invent a fabrication. Those you worship besides Allah possess no provision for you — so seek provision from Allah, worship Allah, and be grateful to Allah; to Allah you return.", "\"তোমরা আল্লাহর পরিবর্তে যা কিছুর উপাসনা করো তা ক্ষমতাহীন শরিক-উপাস্য; তোমরা এক মিথ্যা উদ্ভাবন করেছো।\" আল্লাহর পাশে যেসব উপাস্যদের উপাসনা তোমরা করো তাদের কাছে তোমাদের জন্য কোন জীবিকা নেই। অতএব, তোমরা শুধু আল্লাহর কাছে জীবিকা খুঁজবে। তোমরা কেবল তার উপাসনা করবে, এবং তার প্রতি কৃতজ্ঞ  হও; তাঁর কাছেই তোমাদের চুড়ান্ত প্রত্যাবর্তন।"],
  "29:18": ["If you deny, then nations before you denied; and the Rasul's duty is only the clear delivery.", "যদি তোমরা অবিশ্বাস করো, তোমাদের আগও প্রজন্মগুলো অবিশ্বাস করেছে। বার্তাবাহকের একমাত্র কাজ (বার্তা) পৌঁছে দেয়া।"],
  "29:19": ["Have they not seen how Allah begins the creation, then repeats it? That is easy for Allah.", "তারা কি দেখেনি কিভাবে আল্লাহ সৃষ্টির সূচনা করেন, এরপর এর পুনরাবৃত্তি করেন? এটি করা আল্লাহর জন্য সহজ।"],
  "29:20": ["Say: \"Journey through the earth and look at how the creation began; then Allah will raise up the final raising. Allah has power over everything.\"", "বল, \"পৃথিবী ঘুড়ে বেড়াও এবং জীবনের উৎপত্তি খুঁজে বের করো।\" কারণ আল্লাহ এভাবে পরকালে সৃষ্টির সূচনা করবেন। আল্লাহ সর্বশক্তিমান।"],
  "29:21": ["Allah punishes whom Allah wills and shows mercy to whom Allah wills, and to Allah you are turned.", "তিনি যাকে ইচ্ছা শাস্তি দেন, এবং যার প্রতি ইচ্ছা তার দয়া বর্ষণ করেন। অবশেষে, তাঁর দিকেই  তোমরা ফিরবে।"],
  "29:22": ["There is no escaping for you on earth or in heaven, and you have, besides Allah, no protector and no helper.", "তোমাদের কেউ এই বাস্তবতা এড়িয়ে যেতে পারবে না, পৃথিবীতে বা আকাশমণ্ডলীতে, এবং আল্লাহর পাশে প্রভু ও মনিব হিসেবে তোমাদের কেউ নেই।"],
  "29:23": ["Those who disbelieve in the signs of Allah and in meeting with Allah — those have despaired of Allah's mercy, and for them is a painful punishment.", "যারা আল্লাহর প্রকাশনাবলিতে, আর তাঁর সাথে সাক্ষাতে অবিশ্বাস করে, তারা আমার দয়া থেকে নিরাশ হয়েছে। তারা টেনে এনেছে এক যন্ত্রণাকর শাস্তি।"],
  "29:24": ["The answer of his people was only that they said: \"Kill him or burn him.\" So Allah saved him from the fire. In that are signs for people who believe.", "প্রতিক্রিয়ায় তার লোকেরা শুধু বলেছিল, \"তাকে হত্যা করো, অথবা  পুড়িয়ে ফেলো।” কিন্তু আল্লাহ তাকে আগুন থেকে রক্ষা করলেন। এটি সে লোকদের জন্য শিক্ষা হওয়া উচিত যারা বিশ্বাস করে।"],
  "29:25": ["He said: \"You have taken idols besides Allah for affection among you in the life of this world. Then on the Day of Resurrection you will disown one another, and you will curse one another. Your destination is the Fire, and you have no helpers.\"", "সে বলল, \"তোমরা  সামাজিক চাপের কারনে আল্লাহর পাশে ক্ষমতাহীন উপাস্যের উপাসনা করো, শুধুমাত্র এই পার্থিব জীবনে তোমাদের মধ্যে কিছু বন্ধুত্ব রক্ষার জন্য। কিন্তু এরপর, পুনরুত্থান দিবসে, তোমরা একে অপরকে পরিত্যাগ করবে, এবং একে অপরকে অভিশাপ দিবে। তোমাদের নিয়তি নরক, যেখানে তোমরা পরস্পরকে সাহায্য করতে পারবে না।\""],
  "29:26": ["And Lut believed in him and said: \"I am emigrating to my Rabb; indeed Allah is the Mighty, the Wise.\"", "লূত তার সাথে বিশ্বাস করেছিল এবং বলেছিল, \"আমি আমার প্রভুর উদ্দেশ্যে দেশত্যাগ করছি। তিনি সর্বশক্তিমান, সবচেয়ে জ্ঞানী। \""],
  "29:27": ["We granted him Ishaq and Yaqub, and placed among his descendants Nabihood and scripture, and gave him his reward in this world; and in the later world he is surely among the salihin.", "আমরা তাকে ইসহাক ও ইয়াকুব দান করেছিলাম, আমরা তার বংশধরদের মধ্যে  নবুওয়ত ও কিতাবের নিয়োগ দিয়েছিলিম/ দায়িত্ব দিয়েছিলাম, আমরা তাকে দিয়েছিলাম তার প্রাপ্য প্রতিদান, এবং  পরকালে সে অবশ্যই সৎকর্মশীলদের সাথে থাকবে।"],
  "29:28": ["And Lut, when he said to his people: \"You commit the obscenity that no one in the worlds has done before you.\"", "লূত তার লোকদের বলল, \"তোমরা এমন ঘৃন্য কাজ করো, যা বিশ্বে তোমাদের আগে আর কেউ করেনি।"],
  "29:29": ["Do you come to men, cut off the way, and commit the dreadful in your gatherings? The answer of his people was only that they said: \"Bring us the punishment of Allah, if you are among the sadiqin.\"", "\"তোমরা পুরুষদের সাথে যৌন চর্চা করো, তোমরা রাজপথে ডাকাতি করো, এবং তোমাদের সমাজে তোমরা সব রকমের পাপ অনুমোদন করো।” প্রতিক্রিয়ায় তার লোকেরা কেবল বলেছিল, \"আমাদের কাছে আল্লাহর শাস্তি নিয়ে আসো, যদি তুমি সত্যবাদী হও।\""],
  "29:30": ["He said: \"My Rabb, help me against the people who do corruption.\"", "সে বলল, \"আমার প্রভু, এইসব অন্যায়কারী লোকদের উপর আমাকে বিজয় দান করুন।"],
  "29:31": ["And when Our malakat came to Ibrahim with the good news, they said: \"We are to destroy the people of this town, for its people were wrongdoers.\"", "যখন আমাদের ফেরেশতারা ইব্রাহিমের কাছে (ইসহাকের জন্মের) সুসংবাদ নিয়ে যায়, তারা এও বলে, “আমরা ঐ (সডম) শহরের  লোকদের ধ্বংস করতে যাচ্ছি। কারণ এর লোকেরা অন্যায়কারী। \""],
  "29:32": ["He said: \"Yet Lut is in it.\" They said: \"We know best who is in it. We will surely save him and his people, except his imra'a — she was among those left behind.\"", "সে বলল, \"কিন্তু সেখানে লূত থাকে।” তারা বলল, \"সেখানে যারা থাকে আমরা তাদের প্রত্যেকের বিষয়ে সম্পূর্ণ অবগত। আমরা অবশ্যই তাকে ও তার পরিবারকে রক্ষা করবো, তার স্ত্রী ছাড়া; সে ধ্বংসপ্রাপ্ত।\""],
  "29:33": ["And when Our malakat came to Lut, he was distressed on their account and felt straitened for room. They said: \"Do not fear and do not grieve; We will save you and your people, except your imra'a — she was among those left behind.\"", "যখন আমাদের ফেরেশতারা লূতের কাছে পৌঁছলো, তাদের সাথে দূর্ব্যবহার করা হলো, এবং সে তাদের উপস্থিতিতে বিব্রত হলো। কিন্তু তারা বলল, \"ভয় করো না, এবং দুশ্চিন্তা করো না। আমরা তোমাকে ও তোমার পরিবারকে রক্ষা করবো, তোমার স্ত্রী ছাড়া; সে ধ্বংসপ্রাপ্ত।"],
  "29:34": ["We are sending down upon the people of this town an affliction from the heaven, for what they used to defiantly do.", "\"আমরা আকাশ থেকে এই শহরের লোকদের উপর দূর্যোগ অবতীর্ণ করবো, তাদের অন্যায়ের পরিনামে।\""],
  "29:35": ["We have surely left from it a clear sign for people who reason.", "আমরা তাদের কিছু ধ্বংসস্তূপকে রেখে দিয়েছি, সেসব লোকদের জন্য একটি দিব্যমান শিক্ষা হিসেবে যারা বুঝে।"],
  "29:36": ["And to Madyan, their brother Shu'ayb; he said: \"O my people, worship Allah, hope for the Last Day, and do not ravage the earth as corrupters.\"", "মাদিয়ানবাসীদের কাছে আমরা তাদের ভাই শোয়াইবকে পাঠিয়েছিলাম। সে বলেছিল, \"হে আমার লোকেরা, তোমরা আল্লাহর উপাসনা করবে ও শেষ দিনের কামনা করবে, এবং পৃথিবীতে দূর্নীতি করে বেড়াবে না।\""],
  "29:37": ["They denied him, so the quake seized them, and they became sprawled in their home.", "তারা তাকে অবিশ্বাস করেছিল এবং পরিনামে, ভূমিকম্প তাদের ধ্বংস করেছিল; সকালের মধ্যেই তারা তাদের ঘরে মৃত পড়ে ছিল।"],
  "29:38": ["And Aad and Thamud — and it has been made clear to you from their dwellings. The devil adorned their deeds for them and barred them from the way, though they were perceptive.", "একইভাবে, আদ ও সামূদ (ধ্বংস হয়েছিল)। তাদের ধ্বংসস্তূপই তোমাদের কাছে তা সুস্পষ্ট করে তোলে। শয়তান তাদের চোখে তাদের কাজকে সাজিয়ে রেখেছিল, এবং পথ থেকে তাদেরকে সরিয়ে দিয়েছিল, যদিও তারা ছিল দৃষ্টি সম্পন্ন।"],
  "29:39": ["And Qarun and Fir'awn and Haman — Musa came to them with the clear proofs, but they grew arrogant in the earth, and they were not ahead.", "এছাড়াও ক্বারুন, ফেরাউন, এবং হামান; মূসা তাদের কাছে পরিষ্কার নিদর্শনাবলি নিয়ে গিয়েছিল। কিন্তু পৃথিবীতে তারা অত্যাচার করেই যাচ্ছিলো। ফলস্বরুপ, তারা (শাস্তি) এড়াতে পারলো না।"],
  "29:40": ["Each We seized for its offense: among them are those upon whom We sent a burning storm, and among them are those whom the shout seized, and among them are those whom We caused the earth to swallow, and among them are those whom We drowned. Allah would not wrong them, but they were wronging themselves.", "সে সকল অবিশ্বাসীরা তাদের পাপের ফলস্বরূপ ধ্বংস হয়েছিল। আমরা তাদের কাউকে ধ্বংস করেছিলাম ঝড়ো বাতাস দিয়ে,  কাউকে ধ্বংস করেছিল ভূমিকম্প, কাউকে পৃথিবী গিলে ফেলেছিল, আর কাউকে আমরা ডুবিয়ে দিয়েছিলাম।  আল্লাহ তাদের প্রতি কোন অন্যায় করেননি; তারা নিজেরাই তাদের আত্মার প্রতি অন্যায় করেছিল।"],
  "29:41": ["The likeness of those who took protectors besides Allah is the likeness of the spider that took a house. The weakest of houses is the spider's house — if they knew.", "যারা আল্লাহর পাশে অন্য মনিবদের গ্রহন করে তাদের উপমা হচ্ছে মাকড়সা ও তার ঘর সরুপ; সব ঘরের মধ্যে মাকড়সার ঘরই সবচেয়ে ভঙ্গুর, শুধু যদি তারা জানতো।"],
  "29:42": ["Allah knows whatever they call upon besides Allah — anything at all — and Allah is the Mighty, the Wise.", "আল্লাহ ভালো করেই জানেন যে, তাঁকে বাদ দিয়ে তারা যা কিছুরই উপাসনা করে, তা আসলে কিছুই নয়।তিনি সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "29:43": ["These are the likenesses We strike for people, and none reason them out except those who know.", "এইসব উদাহরণ আমরা লোকেদের জন্য বর্ণনা করি, এবং জ্ঞানীরা  ছাড়া কেউই এগুলোর মর্ম উপলব্ধি করে না।"],
  "29:44": ["Allah created the heavens and the earth in truth. In that is a sign for the muminin.", "আল্লাহ আকাশমন্ডলী ও পৃথিবী সৃষ্টি করেছেন, সত্যের সাথে। বিশ্বাসীদের জন্য এটি যথেষ্ঠ প্রমান যোগায়।"],
  "29:45": ["Recite what was revealed to you of the scripture, and establish the prayer. The prayer restrains from obscenity and the dreadful, and the remembrance of Allah is greatest. Allah knows what you do.", "তুমি আবৃতি করবে ঐশীগ্রন্থের যা তোমার কাছে প্রকাশ করা হয়েছে, এবং সংযোগ প্রার্থনা (সালাত) পালন করো, কারন সংযোগ প্রার্থনা মন্দ ও অধর্ম থেকে দূরে রাখে। কিন্তু (সালাতের মাধ্যমে) আল্লাহর স্মরণ করাই হলো সবচেয়ে গুরুত্বপূর্ণ লক্ষ্য। তোমরা যা কিছুই করো  আল্লাহ তা জানেন।"],
  "29:46": ["Do not dispute with the people of the scripture except in the best way, except for those of them who wronged. And say: \"We believe in what was revealed to us and what was revealed to you. Our ilah and your ilah is One, and to Allah we submit.\"", "যথাসম্ভব উত্তম পন্থা ব্যতিত ঐশীগ্রন্থের লোকেদের (ইহুদি, খ্রিস্টান, ও মুসলিমদের) সাথে বিতর্ক করো না- যদি না তারা সীমালঙ্ঘন করে- আর বল, \"আমরা বিশ্বাস করি যা আমাদের কাছে প্রকাশ করা হয়েছে ও যা তোমাদের কাছে প্রকাশ করা হয়েছে, আর আমাদের উপাস্য ও তোমাদের উপাস্য এক এবং একই/অভিন্ন; তার কাছেই আমরা আত্মসমর্পণকারী। \""],
  "29:47": ["And thus We revealed the scripture to you. Those to whom We gave the scripture believe in it, and among these are some who believe in it; and none deny Our signs except the kafirin.", "আমরা তোমার কাছে এই ঐশীগ্রন্থ প্রকাশ করেছি, এবং যাদেরকে আমরা পূর্বের ঐশীগ্রন্থ দিয়ে সৌভাগ্যশালী করেছি তারা এতে বিশ্বাস করবে। এছাড়াও, তোমার লোকদের কেউ কেউ এতে বিশ্বাস করবে। নিশ্চয়, যারা আমাদের প্রকাশনাবলি উপেক্ষা করে তারাই প্রকৃত অবিশ্বাসী।"],
  "29:48": ["You did not recite any book before it, nor did you trace it with your right hand — otherwise the voiders would have doubted.", "তুমি পূর্ববর্তী ঐশীগ্রন্থগুলো পড়োনি, না তুমি সেগুলো নিজের হাতে লিখেছ। সেক্ষেত্রে, প্রত্যাখ্যানকারীদের সন্দেহ করার কারন থাকতে পারতো।"],
  "29:49": ["Rather, it is clear signs in the breasts of those who were given knowledge, and none deny Our signs except the wrongdoers.", "প্রকৃতপক্ষে, এই আয়াতগুলি জ্ঞানীদের বুকের ভিতরে স্পষ্ট।শুধু অন্যায়কারীরাই আমাদের প্রকাশনাবলি প্রত্যাখ্যান করবে।"],
  "29:50": ["They say: \"Why are no signs sent down to him from his Rabb?\" Say: \"The signs are only with Allah, and I am only a clear warner.\"", "তারা বলল, \"শুধু যদি তার প্রভুর পক্ষ থেকে তার কাছে অলৌকিকতা আসতো!” বল, \"সকল অলৌকিকতা কেবল আল্লাহ থেকে আসে; আমি একজন স্পষ্ট সতর্ককারীর চেয়ে বেশি কিছু নই।\""],
  "29:51": ["Is it not sufficient for them that We revealed to you the scripture, recited to them? In that is a mercy and a reminder for people who believe.", "এটি কি যথেষ্ট অলৌকিকতা নয় যে আমরা তোমার কাছে এই গ্রন্থ অবতীর্ণ করেছি, যা তাদের কাছে আবৃতি করা হয়? এটি নিশ্চয় একটি দয়া ও এক স্মারক সে লোকদের জন্য যারা বিশ্বাস করে।"],
  "29:52": ["Say: \"Allah is sufficient as a witness between me and you. Allah knows what is in the heavens and the earth. Those who believe in falsehood and disbelieve in Allah — those are the khasirin.\"", "বল, \"আমার এবং তোমাদের মাঝে সাক্ষী হিসেবে আল্লাহ যথেষ্ট। তিনি আকাশমণ্ডলী ও পৃথিবীর সবকিছু জানেন। নিশ্চয়, যারা মিথ্যায় বিশ্বাস করে এবং আল্লাহতে অবিশ্বাস করে তারাই প্রকৃত ক্ষতিগ্রস্ত।\""],
  "29:53": ["They ask you to hasten the punishment; were it not for an appointed term, the punishment would have come to them — and it will surely come to them suddenly while they do not perceive.", "তারা তোমাকে শাস্তি আনার জন্য চ্যালেঞ্জ করে! যদি এক পূর্বনির্ধারিত সময় না থাকতো, শাস্তি তাদের কাছে তৎক্ষণাৎ আসতো। নিশ্চয়, এটি তাদের কাছে হঠাৎ করেই আসবে, যখন তারা খুব কমই এর আশা করবে।"],
  "29:54": ["They hasten you for the punishment, and Jahannam indeed encompasses the kafirin.", "শাস্তি আনার জন্য তারা তোমাকে চ্যালেঞ্জ করে! নরক তো ইতোমধ্যে অবিশ্বাসীদের ঘিরেই ফেলেছে।"],
  "29:55": ["On the day the punishment covers them from above them and from beneath their feet, and it says: \"Taste what you used to do.\"", "সেদিন আসবে যখন শাস্তি তাদের ঘেরাও করে ফেলবে, তাদের উপর থেকে এবং তাদের পায়ের নিচ থেকে; সে বলবে, \"তোমাদের কাজের ফল আস্বাদন করো।\""],
  "29:56": ["O servants of Allah who believe, the earth of Allah is spacious — so worship Allah alone.", "হে আমার বান্দারা যারা বিশ্বাস করো, আমার পৃথিবী প্রশস্ত, তাই আমার উপাসনা করো।"],
  "29:57": ["Every soul tastes death; then to Us you return.", "প্রত্যেক আত্মা মৃত্যুর স্বাদ আস্বাদন করবে, এরপর পরিশেষে আমাদের কাছেই তোমরা ফিরে আসবে।"],
  "29:58": ["Those who believe and do salih deeds — We will surely settle them in the Garden in upper chambers, with rivers flowing beneath them, abiding therein forever. An excellent reward for the doers.", "যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে, নিশ্চয় আমরা তাদেরকে প্রতিষ্ঠিত করবো স্বর্গে, অট্রালিকা ও প্রবাহিত ঝর্ণা সহ। তারা সেখানে চিরকাল বাস করে। কতই না সুন্দর পুরষ্কার তাদের জন্য যারা কর্ম করে!"],
  "29:59": ["Those who are sabir and rely upon their Rabb.", "তারা সে ব্যক্তি যারা দৃঢ়তার সাথে অবিচল থাকে, আর তাদের প্রভুর উপর আস্থা রাখে।"],
  "29:60": ["How many a creature there is that does not carry its provision — Allah provides for it and for you; Allah is the All-Hearing, the All-Knowing.", "বহু প্রানি আছে যেগুলো এদের জীবিকা বহন করে না, আল্লাহ এদের জন্য প্রদান করেন, একইভাবে তোমাদের জন্যও। তিনি শুনেন, সর্বজ্ঞ।"],
  "29:61": ["If you ask them who created the heavens and the earth and subjected the sun and the moon, they will surely say: \"Allah.\" So how are they turned away?", "যদি তুমি তাদের জিজ্ঞেস করো, \"কে আকাশমণ্ডলী ও পৃথিবী সৃষ্টি করেছেন, আর তোমাদের সেবায় সূর্য ও চাঁদকে নিয়োজিত করেছেন, ” তারা বলবে, \"আল্লাহ।” তাহলে কেন তারা বিচ্যুত হয়?"],
  "29:62": ["Allah spreads out provision for whom Allah wills among the servants, and restricts it; indeed Allah knows everything.", "আল্লাহই সে সত্ত্বা যিনি তার সৃষ্টিকূল থেকে যে কারো জন্য ইচ্ছে জীবিকা বৃদ্ধি করেন, আর তা সীমাবদ্ধ রাখেন। আল্লাহ সবকিছুর বিষয়ে পূর্ণ সচেতন।"],
  "29:63": ["If you ask them who sends down water from the heaven and revives the earth with it after its death, they will surely say: \"Allah.\" Say: \"Praise belongs to Allah.\" Yet most of them do not reason.", "যদি তুমি তাদের জিজ্ঞেস করো, \"কে আকাশ থেকে পানি অবতীর্ণ করেন মৃত জমিকে পুনরুজ্জীবিত করার জন্য\" , তারা বলবে, \"আল্লাহ।\" বল, \"প্রশংসা আল্লাহর।\"  তাদের বেশির ভাগ বুঝে না।"],
  "29:64": ["This worldly life is nothing but diversion and play, and the later dwelling is the true life — if only they knew.", "এই পার্থিব জীবন অহমিকা এবং রঙ্গ-খেলার চেয়ে বেশি কিছু নয়, যেখানে পরকালের আবাসই সত্যিকার জীবন, যদি শুধু তারা জানতো।"],
  "29:65": ["When they ride in the ship, they call upon Allah, devoting religion to Allah alone; but when Allah saves them to dry land, they associate partners.", "যখন তারা কোন জাহাজে আরোহণ করে, তারা আল্লাহর কাছে মিনতি করে, তাদের প্রার্থনাকে তাঁর কাছেই নিবেদন করে। কিন্তু যখনই তাদেরকে তিনি তীরে এনে রক্ষা করেন, তারা পুনরায় শিরক করতে থাকে।"],
  "29:66": ["To disbelieve in what We gave them and to enjoy themselves — soon they will know.", "তাদেরকে অবিশ্বাস করতে দাও যা আমরা তাদেরকে দিয়েছি, এবং তাদেরকে কিছু কালের জন্য উপভোগ করতে দাও; তারা নিশ্চয় দেখতে পাবে।"],
  "29:67": ["Have they not seen that We have made a sanctuary secure, while people are snatched away all around them? Do they believe in falsehood and disbelieve in the blessing of Allah?", "তারা কি দেখেনি যে আমরা একটি পবিত্র উপাসনার স্থান প্রতিষ্ঠা করেছি যাকে আমরা নিরাপদ করেছি, যখন তাদের চারপাশের সকল লোকেরা অনবরত বিপদে আছে? তারা কি এরপরও মিথ্যায় বিশ্বাস করবে, এবং আল্লাহর অনুগ্রহকে প্রত্যাখ্যান করবে?"],
  "29:68": ["Who is more wrong than one who fabricates a lie against Allah, or denies the truth when it comes to him? Is Jahannam not a lodging for the kafirin?", "তার চেয়ে কে বেশি মন্দ যে মিথ্যা উদ্ভাবন করে এবং সেগুলো আল্লাহর প্রতি আরোপ করে, অথবা সত্য প্রত্যাখ্যান করে যখন তা তার কাছে আসে? নরকই কি অবিশ্বাসীদের জন্য উচিত শাস্তি নয়?"],
  "29:69": ["Those who strive for Us — We will surely guide them on Our ways, and Allah is surely with the doers of good.", "আর যারা আমাদের কারনে সংগ্রাম করে, আমরা নিশ্চয় তাদেরকে আমাদের পথ দেখাবো।  নিশ্চিতই, আল্লাহ সৎকর্মশীলদের সাথে আছেন।"],
  "30:1": ["Alif Lam Mim", "অ.ল.ম"],
  "30:2": ["The Romans have been overcome", "নিশ্চয়, রোমানরা পরাজিত হবে।"],
  "30:3": ["In the nearest land, and they, after their overcoming, will overcome", "নিকটতম ভূমিতে। তাদের পরাজয়ের পর, তারা আবার জেগে উঠবে এবং জয়ী হবে।"],
  "30:4": ["Within a few years; to Allah belongs the command, before and after; and that day the muminin will rejoice", "কয়েক বছরের মধ্যে। এমনই আল্লাহর সিদ্ধান্ত, প্রথম এবং দ্বিতীয় উভয় ভবিষৎবাণীর ক্ষেত্রে। ঐ দিন, বিশ্বাসীরা আনন্দ করবে।"],
  "30:5": ["In the help of Allah; Allah helps whom Allah wills, and Allah is the Mighty in Power, the Raheem", "আল্লাহর বিজয়ে। তিনি যাকে ইচ্ছা বিজয় দান করেন। তিনি সর্বশক্তিমান, সবচেয়ে দয়ালু।"],
  "30:6": ["Allah's promise; Allah does not fail the promise, but most people do not know", "এমনই আল্লাহর অঙ্গীকার এবং আল্লাহ কখনো তার অঙ্গীকার ভঙ্গ করেন না- কিন্তু অধিকাংশ লোক জানেনা।"],
  "30:7": ["They know the surface of the lower life, and of the last they are unmindful", "তারা কেবল এই পার্থিব জিনিসের প্রতি গুরুত্ব দেয় যা তাদের কাছে দৃশ্যমান,  যখন পরকালের বিষয়ে পুরোপুরি বেখেয়াল থাকে।"],
  "30:8": ["Have they not reflected within themselves? Allah did not create the heavens and the earth and what is between them except in truth and for an appointed term; yet many of the people are kafirin in the meeting of their Rabb", "কেন তারা নিজেদের বিষয়ে চিন্তা করে না? আল্লাহ আকাশমন্ডলী ও পৃথিবী, এবং এদের মধ্যকার সবকিছু, একটি সুনির্দিষ্ট উদ্দেশ্য, এবং একটি সুনির্দিষ্ট জীবনকাল ব্যতিত সৃষ্টি করেননি। কিন্তু, অধিকাংশ লোক, তাদের প্রভুর সাথে সাক্ষাতের বিষয়ে, অবিশ্বাসী।"],
  "30:9": ["Have they not journeyed in the land and seen how was the end of those before them? They were greater in strength than them, and they stirred up the land and built it up more than these built it, and their envoys came to them with clear proofs; Allah was not to wrong them, but they wronged themselves", "তারা কি পৃথিবী ঘুরে দেখেনি এবং তাদের পূর্বে যারা ছিল তাদের পরিনাম লক্ষ্য করেনি? তারা ছিল পৃথিবীতে আরো ক্ষমতাবান, আরো সমৃদ্ধশালী, এবং আরো উৎপাদনশীল। তাদের বার্তাবাহকগন তাদের কাছে পরিষ্কার নিদর্শনাবলি নিয়ে গিয়েছিল। পরিনামে, আল্লাহ তাদের প্রতি অন্যায় করেননি, তারাই তাদের নিজেদের আত্মার প্রতি অন্যায় করেছিল।"],
  "30:10": ["Then the end of those who did the worst was that they denied the signs of Allah and mocked them", "যারা মন্দ কাজ করেছিল তাদের পরিনাম মন্দই হওয়ার ছিল। এর কারন হল তারা আল্লাহর প্রকাশনাবলি প্রত্যাখ্যান করত, এবং সেগুলোকে উপহাস করত।"],
  "30:11": ["Allah begins the creation, then repeats it; then to Allah you return", "আল্লাহই সে সত্ত্বা যিনি সৃষ্টির সূচনা করেন এবং এর পুনরাবৃত্তি করেন। অবশেষে, তোমাদের তার কাছে ফিরে যেতে হবে।"],
  "30:12": ["And the day the Hour arises, the mujrimin will be despair-struck", "সে দিনে যখন সে ঘণ্টা সংঘটিত হবে, অপরাধীরা আতংকিত হবে।"],
  "30:13": ["And there will be none from their associates to intercede for them, and they had been kafirin in their associates", "তাদের উপাস্যদের কোন ক্ষমতা থাকবে না তাদের পক্ষ হয়ে সুপারিশ করার ; পক্ষান্তরে, তারা তাদের উপাস্যদের প্রত্যাখ্যান করবে।"],
  "30:14": ["And the day the Hour arises, that day they part", "যে দিন সময় আসবে, তারা পরস্পর থেকে দুরে চলে যাবে।"],
  "30:15": ["Then as for those who believed and did good deeds, they are in a garden, delighting", "আর যারা বিশ্বাস করে এবং সৎ জীবন যাপন করে, তারা থাকবে স্বর্গে, আনন্দের সাথে।"],
  "30:16": ["And as for those who kafara and denied our signs and the meeting of the last, those are arraigned in the punishment", "আর যারা অবিশ্বাস করে, আর আমাদের প্রকাশনাবলি এবং পরকালের সাক্ষাতকে প্রত্যাখ্যান করে, তারা চিরকাল শাস্তিতে থাকবে।"],
  "30:17": ["So glory be to Allah when you enter evening and when you enter morning", "অতএব, তোমরা আল্লাহর মহিমা ঘোষণা করবে যখন তোমরা রাতে ঘুমাতে যাও, এবং যখন তোমরা সকালে ঘুম থেকে ওঠো।"],
  "30:18": ["And to Allah belongs praise in the heavens and the earth, and at evening, and when you come forth at midday", "আকাশমন্ডলী এবং পৃথিবীতে সকল প্রশংসা তাঁর জন্য,  বিকেল জুড়ে, একই সাথে তোমাদের দিনের মধ্যভাগে।"],
  "30:19": ["Allah brings out the living from the dead and brings out the dead from the living, and revives the earth after its death; and thus you are brought out", "তিনি মৃত থেকে জীবিতকে তৈরি করেন, আর মৃতকে তৈরি করেন জীবিত থেকে, এবং তিনি ভূমিকে পুনরুজ্জীবিত করেন তা মরে যাবার পর; একইভাবে তোমরা পুনরুজ্জীবিত হও।"],
  "30:20": ["And among the signs: that Allah created you from dust, then suddenly you are humans spreading abroad", "তাঁর প্রমাণাদির মধ্যে আছে যে তিনি তোমাদেরকে ধূলা থেকে সৃষ্টি করেছেন, এরপর তোমরা প্রজননশীল মানুষ হয়ে ওঠো।"],
  "30:21": ["And among the signs: that Allah made for you mates from yourselves that you may find rest in them, and placed between you affection and mercy; in that are signs for a people who reflect", "তাঁর প্রমাণসমূহের মধ্যে রয়েছে যে তিনি তোমাদের মধ্যে থেকে তোমাদের জন্য স্বামী-স্ত্রী সৃষ্টি করেছেন, যাতে পরস্পরের সাথে প্রশান্তি ও সন্তুষ্টিতে থাকো,  আর তিনি তোমাদের সঙ্গীদের প্রতি তোমাদের হৃদয়ে ভালবাসা ও যত্ন রেখেছেন। এর মধ্যে, যথেষ্ট প্রমান আছে সে লোকদের জন্য যারা চিন্তা করে।"],
  "30:22": ["And among the signs: the creation of the heavens and the earth, and the difference of your tongues and your colors; in that is a sign for those who know", "তাঁর প্রমাণসমূহের মধ্যে রয়েছে আকাশমণ্ডলী ও পৃথিবীর সৃষ্টি, এবং তোমাদের ভাষা ও রঙের ভিন্নতা। এসবের মধ্যে, নিদর্শনাবলি আছে জ্ঞানবানদের জন্য।"],
  "30:23": ["And among the signs: your sleep by night and by day, and your seeking of the bounty; in that are signs for a people who hear", "তাঁর প্রমাণসমূহের মধ্যে রয়েছে তোমাদের ঘুম রাতে বা দিনে, এবং তাঁর জীবিকার খোঁজে তোমাদের কাজ করা। এর মাঝে, যথেষ্ট প্রমান রয়েছে সে লোকদের জন্য যারা শুনতে পারে।"],
  "30:24": ["And among the signs: Allah shows you lightning, for fear and for hope, and sends down from the sky water, and revives the earth after its death; in that are signs for a people who understand", "তাঁর প্রমাণসমূহের মধ্যে রয়েছে যে তিনি তোমাদের বজ্রপাত দেখান ভয় উদ্রেককারী সেই সাথে আশা স্বরূপ, এরপর তিনি আকাশ থেকে পানি বর্ষণ করেন জমিকে পুনরুজ্জীবিত করতে যা ছিল মৃত। এসবের মধ্যে, সে লোকদের জন্য যথেষ্ট প্রমান আছে যারা বুঝে।"],
  "30:25": ["And among the signs: that the heaven and the earth stand by Allah's command; then when Allah calls you with a call from the earth, suddenly you come out", "তাঁর প্রমাণসমূহের মধ্যে রয়েছে যে আকাশ ও পৃথিবী তাঁর নিয়ন্ত্রনে দাঁড়িয়ে আছে। অবশেষে, যখন তিনি তোমাদেরকে ডাকেন মাটি থেকে বের হতে, একটি ডাক, তোমরা সাথে সাথে বের হয়ে আসবে।"],
  "30:26": ["And to Allah belongs whoever is in the heavens and the earth; all are devout to Allah", "আকাশমণ্ডলী ও পৃথিবীর সবাই তাঁরই; সবাই তাঁর আজ্ঞাধীন।"],
  "30:27": ["And Allah is the one who begins the creation, then repeats it, and that is lighter upon Allah; and the highest likeness in the heavens and the earth belongs to Allah, and Allah is the Mighty in Power, the Wise", "আর তিনিই সেই সত্ত্বা যিনি সৃষ্টির সূচনা করেন, এরপর তার পুনরাবৃত্তি করেন; এটা এমনকি তাঁর জন্য আরো  সহজ। সবচেয়ে মহিমান্বিত উপমা তারই, আকাশমণ্ডলী ও পৃথিবীতে, এবং তিনি সর্বশক্তিমান, সবথেকে জ্ঞানী।"],
  "30:28": ["Allah strikes for you a parable from yourselves: do you have, from what your right hands possess, any partners in what we provided you, so that you are equal in it, fearing them as you fear your own selves? Thus we spell out the signs for a people who understand", "তিনি তোমাদের জন্য এখানে একটি উদাহরণ দেন তোমাদের নিজেদের মধ্য থেকে: তোমরা কি তোমাদের ভৃত্য বা অধস্তনদের কখনো সে স্তরে উঠাও যেখানে তারা তোমাদের প্রতিদ্বন্দ্বিতা করে, এবং সে বিন্দুতে যে তোমরা তাদেরকে ততটুকু আনুগত্য প্রদর্শন করো যতটুকু তোমাদেরকে প্রদর্শন করা হয়? আমরা এভাবে সে লোকদের জন্য প্রকাশনাবলি ব্যাখ্যা করি যারা বুঝে।"],
  "30:29": ["Rather, those who wronged followed their desires without knowledge; who guides one whom Allah has led astray? And there are no helpers for them", "নিশ্চয়, সীমালঙ্ঘনকারীরা তাদের নিজেদের মত অনুসরণ করেছে, জ্ঞান ছাড়াই। কে তবে তাদেরকে পথ দেখাতে পারে যারা আল্লাহর দ্বারা পথভ্রষ্ট হয়েছে? কেউ কখনো তাদের সাহায্য করতে পারবে না।"],
  "30:30": ["So set your face to the religion, upright; it is the origination of Allah upon which Allah originated humankind; there is no change in the creation of Allah; that is the upright religion, but most people do not know", "অতএব, তোমরা নিজেদেরকে উৎসর্গ করবে কঠোর একেশ্বরবাদী ধর্মের প্রতি। এমনই সহজাত প্রবৃত্তি যা আল্লাহ লোকদের মধ্যে রেখেছেন। আল্লাহর এমন সৃষ্টি কখনো পরিবর্তন হবে না। এটাই নিঃখুত ধর্ম, কিন্তু অধিকাংশ লোক জানে না।"],
  "30:31": ["Turning back to Allah; be mindful of Allah, establish the prayer, and do not be among those who associate partners", "তোমরা তাঁর নিকট আত্মসমর্পণ করবে, তাঁকে ভক্তি-শ্রদ্ধা করবে, সংযোগ প্রার্থনা (সালাত) পালন করবে, এবং  তোমরা যা-ই করো না কেন – কখনো শরিক উপাসনায় পড়ো না।"],
  "30:32": ["Those who divided their religion and became parties, each party rejoicing in what they have", "(শিরক এ পড়ো না) তাদের মতো যারা নিজেদের ধর্মকে বিভিন্ন বর্ণে ভাগ করে; প্রত্যেকটি দল তাদের যা আছে তা নিয়ে আনন্দিত।"],
  "30:33": ["And when harm touches people they call their Rabb, turning back to Allah; then when Allah lets them taste from it mercy, suddenly a group of them associate partners with their Rabb", "যখন মানুষ দুর্দশাগ্রস্থ হয়, তারা তাদের প্রভুর দিকে ফিরে, নিজেদেরকে পুরোপুরি তাঁর কাছে উৎসর্গ করে। কিন্তু তারপর, যখনি তিনি তাদের উপর দয়া বর্ষণ করেন, তাদের কেউ কেউ শিরক উপাসনায় ফিরে যায়।"],
  "30:34": ["To disbelieve in what we gave them; so enjoy, and soon you will know", "আমরা তাদেরকে যা দিয়েছি তাতে তাদেরকে অকৃতজ্ঞ হতে দাও। সাময়িকভাবে উপভোগ করো; অবশ্যই তোমরা দেখতে পাবে।"],
  "30:35": ["Or did we send down to them a warrant that speaks of what they used to associate?", "আমরা কি তাদেরকে এমন অনমুদন দিয়েছি যা তাদের শিরককে নিয়মসিদ্ধ করে?"],
  "30:36": ["And when we let people taste mercy they rejoice in it; and if an evil strikes them for what their hands sent ahead, suddenly they despair", "যখন আমরা মানুষের উপর দয়া বর্ষণ করি, তারা তাতে আনন্দ করে। কিন্তু যখন তাদের উপর দুর্ভোগ পতিত হয়, তাদের নিজেদের কাজের পরিনামে, তারা হতাশ হয়ে যায়।"],
  "30:37": ["Do they not see that Allah spreads provision for whom Allah wills and measures it? In that are signs for a people who believe", "তারা কি এটা অনুধাবন করে না যে আল্লাহ যার জন্য ইচ্ছা জীবিকা বৃদ্ধি করেন, অথবা তা কমিয়ে দেন? এটা সেসব মানুষের জন্য শিক্ষা হওয়া উচিত যারা বিশ্বাস করে।"],
  "30:38": ["So give the near-relative the due, and the needy, and the wayfarer; that is better for those who want the face of Allah, and those are the ones who attain success", "অত:এব, তোমরা আত্মীয়দের দিবে তাদের  ন্যায্য অংশ (দানের), গরীবদেরও, এবং ভ্রমণরত ভীনদেশীদের। এটি তাদের জন্য উত্তম যারা আন্তরিকভাবে আল্লাহর সন্তুষ্টি খোঁজে; তারাই বিজয়ী।"],
  "30:39": ["And what you give of usury to grow in people's wealth grows not with Allah; and what you give of growth-dues wanting the face of Allah, those are the ones for whom it is multiplied", "চড়াসুদ, যা কিছু মানুষের সম্পদ বাড়ানোর জন্য চর্চা করা হয়, তা আল্লাহর দৃষ্টিতে কিছুই লাভ করে না। কিন্তু যদি তোমরা দান করো, আল্লাহর সন্তুষ্টির খোঁজে, এরাই সে ব্যক্তি যারা বহুগুণে তাদের পুরস্কার পায়।"],
  "30:40": ["Allah is the one who created you, then provided you, then gives you death, then gives you life; is there among your associates any who does anything of that? Glory be to Allah, exalted above what they associate", "আল্লাহই সে সত্ত্বা যিনি তোমাদের সৃষ্টি করেছেন। তিনিই সে সত্ত্বা যিনি তোমাদেরকে জীবিকা প্রদান করেন। তিনিই সে সত্ত্বা যিনি তোমাদের পুনরুত্থিত করেন। তোমাদের কোন উপাস্য কি এগুলোর কোনকিছু করতে পারে? মহিমা তাঁরই। কোন শরিক থাকা থেকে  তিনি অনেক উর্ধ্বে।"],
  "30:41": ["Corruption has appeared on the land and the sea for what people's hands have earned, to let them taste some of what they did, so that they may return", "স্থল ও সাগর জুড়ে দূর্যোগ ছড়িয়ে পড়েছে, মানুষ যা করেছে তার কারনে। তিনি এভাবে তাদের কিছু কাজের পরিনাম অস্বাদন করান, যাতে তারা ( ভাল কাজের দিকে) ফিরে আসে।"],
  "30:42": ["Say: journey in the land and see how was the end of those before; most of them were those who associate partners", "বল, \"পৃথিবীতে ঘুড়ে বেড়াও এবং তাদের পরিনাম লক্ষ্য করো যারা তোমাদের পূর্বে ছিল।” তাদের বেশির ভাগই ছিল শিরক কারি।"],
  "30:43": ["So set your face to the upright religion before a day comes from Allah for which there is no warding off; that day they are split apart", "অত:এব, তোমরা নিজেদেরকে এই নি:খুত ধর্মে পুরোপুরি উৎসর্গ করবে, সে দিন আসার আগে যা আল্লাহর দ্বারা অনিবার্য করা হয়েছে। ঐদিন, তারা প্রচন্ডভাবে আতংগ্রস্ত হবে।"],
  "30:44": ["Whoever disbelieves, the disbelief is upon them; and whoever does good, they prepare smooth ground for themselves", "যেকেউ অবিশ্বাস করে, তার নিজ আত্মার ক্ষতি করতেই অবিশ্বাস করে, পক্ষান্তরে যারা সৎ জীবন যাপন করে, তারা তা করে তাদের নিজের আত্মাকে শক্তিশালী ও উন্নত করতে।"],
  "30:45": ["Allah rewards those who believed and did good deeds from the bounty; Allah does not love the kafirin", "কারণ তিনি তাঁর ভান্ডার থেকে তাদেরকে উদারভাবে প্রতিদান দিবেন যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে। তিনি অবিশ্বাসীদের ভালবাসেন না।"],
  "30:46": ["And among the signs: that Allah sends the winds bearing glad tidings, to let you taste of the mercy, and so ships sail by Allah's command, and so you seek of the bounty, so that you give thanks", "তাঁর প্রমানসমূহের মধ্যে রয়েছে যে তিনি বাতাসকে শুভ পূর্বাভাস সহ পাঠান, তোমাদের প্রতি তাঁর দয়া বর্ষণ করতে, এবং তাঁর বিধান অনুসারে জাহাজগুলোকে সাগরে চলতে দিতে, এবং (বানিজ্যের মাধ্যমে) তোমাদের তাঁর ভান্ডার থেকে খুঁজতে দেওয়ার জন্য, যেন তোমরা কৃতজ্ঞ হতে পারো।"],
  "30:47": ["And we sent before you envoys to their people, and they came to them with clear proofs; then we requited those who committed crimes, and helping the muminin was a right due upon us", "লোকদের কাছে, জ্ঞানগর্ভ নিদর্শনাবলী দিয়ে। পরবর্তীতে, যারা সীমালঙ্ঘন করেছে তাদেরকে আমরা শাস্তি দিয়েছি। এটা আমাদের দায়িত্ব যে আমরা বিশ্বাসীদের বিজয় দান করি।"],
  "30:48": ["Allah is the one who sends the wind, and it stirs up clouds, and Allah spreads them in the sky as Allah wills, and makes them fragments, and you see the rain coming out from within them; then when with it Allah strikes whom Allah wills of the servants, suddenly they rejoice", "আল্লাহই সে সত্ত্বা যিনি বাতাস পাঠান, মেঘমালাকে সঞ্চালিত করতে, যাতে তাঁর ইচ্ছা অনুসারে আকাশজুড়ে ছড়িয়ে পড়ে। তিনি এরপর মেঘমালাকে স্তুপ করেন, এরপর তুমি তার মধ্যে থেকে বৃষ্টি নেমে আসতে দেখো। যখন তা বর্ষিত হয় যাদের উপর তিনি চান তাঁর বান্দাদের মধ্য থেকে, তারা আনন্দ করে।"],
  "30:49": ["Though before it was sent down upon them they had been despair-struck", "এটি তাদের উপর বর্ষণ হবার আগে, তারা হতাশা গ্রস্থ হয়েছিল।"],
  "30:50": ["So look to the vestiges of Allah's mercy, how Allah revives the earth after its death; that is a reviver of the dead, and Allah is powerful over everything", "তোমরা  মূল্যায়ন করবে আল্লাহর অবিরত দয়াকে, এবং যেভাবে তিনি যে ভূমি মৃত ছিল তাকে পুনরুজ্জীবিত করেন। তিনি ঠিক এমন নিশ্চিতভাবেই মৃতকে পুনরুজ্জীবিত করবেন। তিনি সর্বশক্তিমান।"],
  "30:51": ["And if we send a wind and they see it yellowed, they persist after it in disbelief", "আমরা যদি পরিবর্তে তাদের উপর হলুদ বালুঝড় পাঠাতাম, তারা অবিশ্বাস করতেই থাকতো।"],
  "30:52": ["You cannot make the dead hear, nor can you make the deaf hear the call when they turn their backs", "তুমি না মৃতকে, না বধিরকে, ডাক শুনাতে পারবে, তারা বিমুখ হয়ে পড়লে।"],
  "30:53": ["You do not guide the unseeing out of their straying; you make none hear except those who believe in our signs, and those are the ones who submit", "না তুমি অন্ধকে তাদের পথভ্রষ্টতা হতে ফিরিয়ে পথ দেখাতে পারবে। তুমি কেবল তাদেরকেই শোনাতে পারবে যারা আমাদের প্রকাশনাবলিতে বিশ্বাস করে, আর আত্মসমর্পণকারী হবার সিদ্ধান্ত নেয়।"],
  "30:54": ["Allah is the one who created you from weakness, then made, after weakness, strength, then made, after strength, weakness and grayness; Allah creates what Allah wills, and Allah is the Knowing, the Powerful", "আল্লাহই সে সত্ত্বা যিনি তোমাদের দূর্বল করে সৃষ্টি করেছেন, এরপর দূর্বলতার পর শক্তি দান করেছেন, এরপর শক্তির পরে দিয়েছেন দূর্বলতা এবং ধূসর চুল। তিনি যা ইচ্ছা সৃষ্টি করেন। তিনি সর্বজ্ঞ, সর্বশক্তিমান।"],
  "30:55": ["And the day the Hour arises the mujrimin swear they tarried only an hour; thus they were turned away", "সেইদিনে যখন সে সময় সংঘটিত হবে, অপরাধীরা শপথ করে বলবে যে তারা (এই পৃথিবীতে) কেবল এক ঘন্টা অবস্থান করেছিল।  তারা এতোটাই ভুল ছিল।"],
  "30:56": ["And those given knowledge and faith say: you tarried in the decree of Allah until the day of raising; this is the day of raising, but you did not know", "যারা জ্ঞান ও বিশ্বাস দ্বারা অনুগ্রহপ্রাপ্ত হয়েছে তারা বলবে, \"তোমরা অবস্থান করেছ, আল্লাহর বিধান অনুসারে, পুনরুত্থান দিবস পর্যন্ত। এখন, এটাই পুনরুত্থান দিবস, কিন্তু তোমরা তা চিনতে ব্যর্থ হয়েছ।\""],
  "30:57": ["That day the excuses of those who wronged benefit them not, nor are they allowed to make amends", "একারনে, কোন ক্ষমাপ্রার্থনা, ঐদিন, সীমালঙ্ঘনকারীদের কাজে আসবে না, না তারা ক্ষমাপ্রাপ্ত হবে।"],
  "30:58": ["We have struck for people in this recitation every parable; and if a sign comes to them, those who disbelieve will surely say: you are nothing but voiders", "এভাবে, আমরা এই কোর'আনে লোকদের জন্য সব রকমের উদাহরণ দিয়েছি। এরপরও, অবিশ্বাসীদেরকে তুমি যে প্রমানই দেখাও না কেন, তারা বলে “তোমরা মিথ্যাপন্থী। \""],
  "30:59": ["Thus Allah sets a seal on the hearts of those who do not know", "আল্লাহ এভাবে তাদের হৃদয় তালাবদ্ধ করে দেন যারা জানে না।"],
  "30:60": ["So be steadfast; the promise of Allah is true, and let not those who have no certainty take you lightly", "অতএব, তুমি দৃঢ়তার সাথে অবিচল থাকবে- কেননা আল্লাহর প্রতিশ্রুতি সত্য- এবং তাদের দ্বারা ভীত হয়ো না যারা নিশ্চয়তা অর্জন করেনি।"],
  "31:1": ["Alif Lam Mim.", "অ. ল. ম।"],
  "31:2": ["These are the verses of the wise Scripture.", "এই (অক্ষরগুলো) এই জ্ঞানগর্ভ বইয়ের প্রমান গঠন করে।"],
  "31:3": ["A guidance and a mercy for the doers of good.", "সৎকর্মশীলদের জন্য একটি আলোকবর্তিকা এবং দয়া।"],
  "31:4": ["Those who keep up the prayer and give the alms, and it is the Hereafter that they are certain of.", "যারা সংযোগ প্রার্থনা (সালাত) প্রতিষ্ঠা করে, যাকাত দেয় এবং আখেরাতের ব্যাপারে তারা সম্পূর্ণ নিশ্চিত।"],
  "31:5": ["Those are upon guidance from their Rabb, and those are the ones who attain success.", "তারা তাদের পালনকর্তার নির্দেশ অনুসরণ করে এবং তারাই বিজয়ী।"],
  "31:6": ["And among people are those who buy diversionary talk to lead astray from the path of Allah without knowledge, and take it in mockery; for those there is a humiliating punishment.", "লোকদের মধ্যে, রয়েছে তারা যারা ভিত্তিহীন হাদীস সমর্থন করে, আর এভাবে কোন জ্ঞান ছাড়া অন্যদেরকে আল্লাহর পথ হতে সরিয়ে দেয়, এবং একে নেয় অর্থহীনভাবে। এরা টেনে এনেছে এক লজ্জাজনক শাস্তি।"],
  "31:7": ["And when Our verses are recited to him, he turns away disdainfully, as though he had not heard them, as though there were a heaviness in his ears; so give him tidings of a painful punishment.", "আর যখন তাদের কারো কাছে আমাদের প্রকাশনাবলি আবৃত্তি করা হয়, সে ঔদ্ধত্যের সাথে মুখ ফিরিয়ে নেয় যেন সে কখনো সেগুলো শুনেনি, যেন তার কান বধির। তাকে এক যন্ত্রণাদায়ক শাস্তির প্রতিশ্রুতি দাও।"],
  "31:8": ["Indeed, those who believe and do good works — for them are gardens of bliss.", "নিশ্চয়, যারা বিশ্বাস করে এবং সৎ জীবন যাপন করে তারা পরম সুখের বাগানগুলোর যোগ্য।"],
  "31:9": ["Abiding therein forever; that is Allah's promise in truth, and Allah is the Mighty, the Wise.", "তারা সেখানে চিরকাল বাস করে। এটি আল্লাহর সত্য প্রতিশ্রুতি। তিনি সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "31:10": ["Allah created the skies without any pillars that you see, and cast into the earth firm anchors so it would not sway with you, and scattered in it every kind of creature; and We sent down water from the sky and grew in it every noble kind.", "তিনি আকাশমণ্ডলীকে খুঁটি ছাড়া সৃষ্টি করেছেন যা তোমরা দেখতে পাও। তিনি পৃথিবীতে স্থিতিস্থাপক (পর্বতমালা) স্থাপন করেছেন পাছে এটি তোমাদেরকে নিয়ে উলটে পড়ে, এবং তিনি এর উপর সব রকমের প্রাণী ছড়িয়ে দিয়েছেন। আমরা আকাশ থেকে পানি বর্ষন করি সব রকমের সুন্দর উদ্ভিদ জন্মাতে।"],
  "31:11": ["This is Allah's creation; so show Me what those other than Allah have created. Rather, the wrongdoers are in clear error.", "এমনই আল্লাহর সৃষ্টি ; আমাকে দেখাও তাঁর পাশে তোমাদের স্থাপন করা উপাস্যরা কি সৃষ্টি করেছে। নিশ্চয়, সীমালঙ্ঘনকারীরা সুদূরে পথভ্রষ্ট।"],
  "31:12": ["And We gave Luqman wisdom: \"Be grateful to Allah.\" Whoever is grateful is grateful only for the good of his own soul, and whoever is ungrateful — indeed, Allah is Self-Sufficient, Praised.", "আমরা লুকমানকে প্রজ্ঞা অর্পণ করেছিলাম: \"তুমি আল্লাহর প্রতি কৃতজ্ঞ হবে।” যেকেউ কৃতজ্ঞ সে তার নিজের ভালোর জন্যই কৃতজ্ঞ। আর যারা অকৃতজ্ঞ হয়ে যায়, আল্লাহ অভাবমুক্ত, প্রশংসনীয়।"],
  "31:13": ["And when Luqman said to his son, admonishing him: \"My son, do not associate others with Allah; indeed, to associate others with Allah is a tremendous wrong.\"", "স্মরণ করো যে লুকমান তার ছেলেকে বলেছিল, যখন সে তাকে জ্ঞান দিচ্ছিল, “হে আমার পুত্র, আল্লাহর পাশে কোন উপাস্য স্থাপন করো না; শিরক করা একটি ঘোর অবিচার।\""],
  "31:14": ["And We charged the human being concerning his parents: his mother carried him in weakness upon weakness, and his weaning came at two years: \"Be grateful to Me and to your parents. To Me is the final arrival.\"", "আমরা মানুষকে তার মাতাপিতার সম্মান করতে আদেশ করেছি। তার মা তাকে  গর্ভে ধারন করেছে, আর সেই ভার ভারী থেকে ভারী হয়েছে। দুধ ছাড়ানো অবধি  দু'বছর (নিবিড় পরিচর্যার) প্রয়োজন হয়। তোমরা কৃতজ্ঞ হবে আমার প্রতি, এবং তোমাদের মাতাপিতার প্রতি। আমার কাছেই চূড়ান্ত নিয়তি।"],
  "31:15": ["But if the two of them strive against you to make you associate with Me that of which you have no knowledge, then do not obey them; and accompany them in this present world with kindness, and follow the path of whoever turns back to Me. Then to Me is your return, and I will tell you what you used to do.", "যদি তারা আমার পাশে কোন উপাস্য স্থাপন করতে বল প্রয়োগ করে, তাদেরকে মান্য করো না। কিন্তু এই পৃথিবীতে তাদের সাথে অমায়িক আচরণ করে যাবে। তোমরা শুধু তাদের পথ অনুসরণ করবে যারা আমার কাছে আত্মসমর্পণ করেছে। শেষপর্যন্ত, তোমরা সবাই আমার কাছে ফিরবে, তখন আমি তোমাদের জানাবো যাকিছু তোমরা করেছো।"],
  "31:16": ["\"My son, if it be but the weight of a mustard-grain, and it lie within a rock, or in the skies, or in the earth, Allah will bring it forth. Indeed, Allah is Subtle, All-Aware.\"", "\"হে আমার পুত্র, জেনে রাখো যে যদি কোন কিছু একটি সরিষার দানার মতো ছোট-ও হয়, কোন পাথরের গভীরে, তা হোক আকাশমণ্ডলীতে বা পৃথিবীতে, আল্লাহ তা বের করে আনবেন। আল্লাহ মহিমান্বিত, অবগত।"],
  "31:17": ["\"My son, keep up the prayer, enjoin the good, forbid the rejected, and be of the sabirin over whatever befalls you. Indeed, that is among the matters of firm resolve.\"", "\"হে আমার পুত্র, তুমি সংযোগ প্রার্থনা (সালাত) পালন করবে। তুমি সৎকর্মের নির্দেশ দেবে এবং মন্দ কাজে নিষেধ করবে, আর প্রতিকূলতার মুখে দৃঢ় থাকবে। এগুলো সবচেয়ে সম্মানিত বৈশিষ্ট্য।"],
  "31:18": ["\"And do not turn your cheek away from people, and do not walk upon the earth exulting; indeed, Allah does not love any conceited vaunter.\"", "তুমি লোকদের সাথে উদ্ধত আচরণ করবে না, না তুমি গর্বভরে পৃথিবীতে ঘুড়ে বেড়াবে। আল্লাহ উদ্ধত  লোক-দেখানো মানুষকে পছন্দ করেন না।"],
  "31:19": ["\"And walk a middle course in your stride, and lower your voice; indeed, the most dreadful of voices is the voice of the donkey.\"", "\"নম্রভাবে হাটো এবং তোমার স্বর নিচু করো-  গাধার স্বরই সবচেয়ে কর্কশ।\""],
  "31:20": ["Have you not seen that Allah has subjected to you whatever is in the skies and whatever is in the earth, and has lavished upon you blessings outward and inward? Yet among people are those who dispute about Allah without knowledge, without guidance, and without an illuminating Scripture.", "তোমরা কি দেখ না যে আল্লাহ তোমাদের সেবায়  নিয়োজিত করেছেন আকাশমণ্ডলী ও পৃথিবীর সবকিছুকে, এবং তোমাদের প্রতি বর্ষণ করেছেন  তাঁর প্রকাশ্য ও গোপন অনুগ্রহ? তবুও, কিছু লোক আল্লাহ সম্পর্কে তর্ক করে জ্ঞান ছাড়া, পথনির্দেশনা ছাড়া, এবং জ্ঞানালোকপূর্ণ ঐশীগ্রন্থ ছাড়াই।"],
  "31:21": ["And when it is said to them, \"Follow what Allah has sent down,\" they say, \"Rather, we follow what we found our fathers upon.\" Even if Shaytan were calling them toward the punishment of the blaze?", "যখন তাদেরকে বলা হয়, \"আল্লাহর এইসব প্রকাশনাবলি অনুসরণ করো,”তারা বলে, \"না, আমরা কেবল অনুসরণ করি যা আমাদের পিতামাতাকে করতে দেখেছি।” শয়তান যদি তাদেরকে নরকের তীব্র যন্ত্রণার দিকে পরিচালনা করে থাকে, তবুও কি?"],
  "31:22": ["Whoever surrenders his whole being to Allah while doing good has held fast to the firmest handhold; and to Allah is the final outcome of all affairs.", "যারা সম্পূর্ণরূপে আল্লাহর কাছে আত্মসমর্পণ করে, সৎ জীবন যাপন করা অবস্থায়, তারা সবচেয়ে শক্তিশালী বাঁধন আঁকড়ে ধরেছে। কারন আল্লাহ সবকিছুর পূর্ণ নিয়ন্ত্রনে আছেন।"],
  "31:23": ["Whoever disbelieves, let not his disbelief grieve you; to Us is their return, and We will tell them what they did. Indeed, Allah is All-Knowing of the innermost hearts.", "আর যারা অবিশ্বাস করে, তাদের অবিশ্বাসের কারনে দুঃখ পেওনা। আমাদের কাছেই তাদের চূড়ান্ত প্রত্যাবর্তন, তারপর আমরা তাদেরকে সবকিছু জানাবো যা তারা করেছিল। আল্লাহ গভীরতম চিন্তাগুলো সম্পর্কে সম্পূর্ণ অবগত।"],
  "31:24": ["We let them enjoy a little, then We drive them toward a harsh punishment.", "আমরা তাদেরকে সাময়িক ভাবে উপভোগ করতে দেই, এরপর তাদেরকে কঠোর শাস্তিতে পতিত করি।"],
  "31:25": ["If you ask them who created the skies and the earth, they will surely say, \"Allah.\" Say: \"Praise be to Allah.\" Yet most of them do not know.", "যদি তুমি তাদেরকে জিজ্ঞেস করো, \"কে আকাশমণ্ডলী ও পৃথিবী সৃষ্টি করেছেন, ” তারা বলবে, \"আল্লাহ।” বল, \"প্রশংসা আল্লাহর।” তবুও, তাদের বেশিরভাগ-ই জানে না।"],
  "31:26": ["To Allah belongs whatever is in the skies and the earth; indeed, Allah is the Self-Sufficient, the Praised.", "আকাশমণ্ডলী এবং পৃথিবীর সবকিছু আল্লাহর। আল্লাহ সবচেয়ে ধনী, সবচেয়ে প্রশংসনীয়।"],
  "31:27": ["If all the trees on earth were pens, and the sea were supplied after it by seven further seas, the words of Allah would never run out; indeed, Allah is the Mighty, the Wise.", "যদি পৃথিবীর সকল গাছ দিয়ে কলম বানানো হতো, আর সাগর কালি সরবরাহ করতো, আরো সাত সাগর বাড়িয়ে দিয়ে, তবুও আল্লাহর কথা ফুরিয়ে যেতো না। আল্লাহ সর্বশক্তিমান, সবচেয়ে প্রজ্ঞাময়।"],
  "31:28": ["Your creation and your raising are but as a single soul; indeed, Allah is All-Hearing, All-Seeing.", "তোমাদের সকলের সৃষ্টি ও পুনরুত্থান এক ব্যক্তির মতোই। আল্লাহ শুনেন, দেখেন।"],
  "31:29": ["Do you not see that Allah merges the night into the day and merges the day into the night, and has subjected the sun and the moon, each running to an appointed term? And Allah is All-Aware of what you do.", "তোমরা কি অনুধাবন করো না যে আল্লাহ রাতকে দিনের মধ্যে মিলিয়ে দেন ও দিনকে রাতের মধ্যে মিলিয়ে দেন, এবং সূর্য ও চাঁদকে নিয়োজিত করেছেন তোমাদের সেবায়, প্রত্যেকেই নিজ কক্ষপথে একটি নির্দিষ্ট জীবনকালের জন্য চলছে, এবং আল্লাহ পুরোপুরি অবগত সবকিছু সম্পর্কে যা তোমরা করো?"],
  "31:30": ["That is because Allah is the Truth, and that what they call upon other than Allah is falsehood, and because Allah is the Most High, the Great.", "এটি প্রমান করে যে আল্লাহ সত্য, যেখানে তাঁর পাশে তারা যে শরীক স্থাপন করে তা মিথ্যা, এবং যে আল্লাহ সর্বোচ্চ, সবচেয়ে মহান।"],
  "31:31": ["Do you not see that the ships sail through the sea by Allah's blessing, so that Allah may show you something of Allah's signs? Indeed in that are signs for every sabir and grateful one.", "তুমি কি দেখো না যে জাহাজগুলো সাগরে ঘুড়ে বেড়ায়, আল্লাহর জীবিকা বহন করে, তোমাদেরকে তাঁর কিছু প্রমান দেখাতে? নিশ্চয়ই, এগুলো যথেষ্ট প্রমান হওয়া উচিত সকলের জন্য যারা অবিচল, কৃতজ্ঞ।"],
  "31:32": ["And when waves cover them like a canopy, they call upon Allah, devoting all devotion to Allah alone; then, when Allah delivers them to dry land, some of them are moderate. And none denies Our signs except every treacherous kafir.", "যখন প্রচন্ড ঢেউ তাদের ঘিরে ফেলে, তারা আল্লাহর কাছে মিনতি করে, তাদের প্রার্থনা কেবল তাঁর প্রতি আন্তরিকভাবে উৎসর্গ করে। কিন্তু যখনই তিনি তাদেরকে তীরে এনে উদ্ধার করেন, তাদের কেউ কেউ আগের অবস্থায় ফিরে যায়। কেউই আমাদের প্রকাশনাবলি অগ্রাহ্য করে না তারা ছাড়া যারা বিশ্বাসঘাতক, অকৃতজ্ঞ।"],
  "31:33": ["O people, be mindful of your Rabb and dread a day when no parent will answer for a child and no born one will answer for a parent in anything. Indeed, Allah's promise is true; so let not the life of this present world deceive you, and let not the Deceiver deceive you concerning Allah.", "হে লোকেরা, তোমরা তোমাদের প্রভুকে ভক্তি করবে, আর ভয় করো এমন এক দিনকে যখন কোন পিতা তার নিজ সন্তানকে সাহায্য করতে পারবে না, না কোন সন্তান তার পিতাকে সাহায্য করতে পারবে। অবশ্যই, আল্লাহর প্রতিশ্রুতি সত্য। একারনে, এই জীবন দ্বারা বিভ্রান্ত হইও না; আল্লাহ থেকে নিছক মোহের দ্বারা বিভ্রান্ত হইও না।"],
  "31:34": ["Indeed, with Allah is knowledge of the Hour; Allah sends down the rain and knows what is in the wombs. No soul knows what it will earn tomorrow, and no soul knows in which land it will die. Indeed, Allah is All-Knowing, All-Aware.", "আল্লাহর কাছে আছে সে ঘন্টা (বিশ্বের পরিসমাপ্তি) সম্পর্কিত জ্ঞান। তিনিই সে সত্ত্বা যিনি বৃষ্টি অবতীর্ণ করেন, এবং তিনি জানেন জরায়ুস্থ বস্তু সম্পর্কে। কোন আত্মা জানে না আগামীকাল তার সাথে কি ঘটবে, এবং কোন ব্যক্তি জানে না কোন স্থানে সে মারা যাবে। আল্লাহ সর্বজ্ঞ, অবগত।"],
  "32:1": ["Alif Lam Mim.", "অ. ল. ম."],
  "32:2": ["The sending down of the Book, in which there is no doubt, from the Rabb of all knowledge.", "গ্রন্থটি, কোন সন্দেহ ছাড়াই, এক প্রত্যাদেশ  মহাবিশ্বের প্রভুর পক্ষ থেকে।"],
  "32:3": ["Do they say, \"He invented it\"? No — it is the truth from your Rabb, to warn a people to whom no warner came before you, so that perhaps they may be guided.", "তারা বলল, \"সে এটি বানিয়েছে।” নিশ্চয়ই, এটি তোমার প্রভুর পক্ষ থেকে সত্য, সেসব লোকদের সতর্ক করতে যারা তোমার আগে কখনো কোন সতর্ককারী পায়নি, যাতে তারা সুপথপ্রাপ্ত হতে পারে।"],
  "32:4": ["Allah is the one who created the heavens and the earth and what is between them in six days, then settled upon the high seat. You have no guardian other than Allah and no intercessor. Will you not remember?", "আল্লাহই সে সত্ত্বা যিনি সৃষ্টি করেছেন আকাশমন্ডলী ও পৃথিবী, এবং এদের মধ্যকার সবকিছু ছয় দিনে, এরপর সকল কর্তৃত্ব গ্রহন করেছেন। তাঁর পাশে প্রভু হিসেবে তোমাদের কেউ নেই, না তোমাদের কোন সুপারিশকারী আছে। তোমরা কি মনোযোগ দেবে না?"],
  "32:5": ["Allah directs the affair from the heaven to the earth, then it ascends to Allah in a day whose measure is a thousand years of what you count.", "আকাশ থেকে পৃথিবী পর্যন্ত সকল বিষয় তাঁর দ্বারা নিয়ন্ত্রিত। তাঁর কাছে দিনটি তোমাদের এক হাজার বছরের সমান।"],
  "32:6": ["Such is Allah's knowledge of the hidden and the witnessed. Allah is the Mighty, the Raheem.", "সকল গোপন ও প্রকাশ্য বিষয়ের জ্ঞাতা; সর্বশক্তিমান, সবচেয়ে দয়ালু।"],
  "32:7": ["It is Allah who gave everything the excellence of its making; Allah began the creation of the human from clay.", "তিনি সে সত্ত্বা যিনি নিখুঁত করেছেন সবকিছুকে যা তিনি সৃষ্টি করেছেন, আর মানুষের সৃষ্টি শুরু করেছেন কাঁদা থেকে।"],
  "32:8": ["Then Allah made its offspring from an extract of a lowly water.", "তারপর তিনি একটি নির্দিষ্ট নীচুস্তরের তরলের মাধ্যমে তার প্রজনন অব্যাহত রাখেন।"],
  "32:9": ["Then Allah shaped it and blew into it of Allah's spirit, and gave you hearing and sight and hearts. How little you give thanks!", "তিনি তাকে আকার দিলেন এবং তার মধ্যে তাঁর রুহ থেকে ফুঁকে দিলেন। আর তিনি তোমাদেরকে দিয়েছেন শ্রবণশক্তি, দৃষ্টিশক্তি, এবং মস্তিষ্ক ; তোমরা খুব কমই কৃতজ্ঞ।"],
  "32:10": ["And they say: \"When we are lost in the earth, shall we really be in a new creation?\" No — they disbelieve in the meeting with their Rabb.", "তারা অবাক হয়, \"আমরা মাটিতে মিশে যাবার পর, আমরা কি আবার নতুন করে সৃষ্টি হবো?”এভাবে, তাদের প্রভুর সাথে সাক্ষাতের ব্যাপারে, তারা অবিশ্বাসী।"],
  "32:11": ["Say: \"The malakat of death, who is charged with you, will take you; then to your Rabb you will be returned.\"", "বল, \"তোমাদের মৃত্যু হবে ফেরেশতার মাধ্যমে যার দায়িত্বে তোমাদের রাখা হয়েছে, এরপর তোমাদের প্রভুর কাছে তোমরা ফিরে যাবে।\""],
  "32:12": ["If only you could see when the guilty are bowing their heads before their Rabb: \"Our Rabb, we have seen and we have heard; send us back, we will do right — we are certain now.\"", "যদি শুধু তুমি অপরাধীদের দেখতে পারতে যখন তারা তাদের প্রভুর সামনে মাথা নোয়ায়ঃ \"আমাদের প্রভু, এখন আমরা দেখেছি এবং আমরা শুনেছি। আমাদের ফেরত পাঠান এবং আমরা সৎকর্মশীল হবো। আমরা এখন নিশ্চয়তা অর্জন করেছি।\""],
  "32:13": ["If Allah had willed, Allah would have given every soul its guidance; but the word from Allah stands true: \"I will surely fill hell with jinn and people all together.\"", "আমরা যদি চাইতাম, প্রত্যেক আত্মাকে আমরা তার পথনির্দেশনা দিতে পারতাম, কিন্তু এটা ইতোমধ্যেই পূর্বনির্ধারিত যে আমি জ্বীন ও মানুষ দিয়ে নরক পূর্ণ করবো, সবাইকে একসাথে।"],
  "32:14": ["So taste, because you forgot the meeting of this day of yours — Allah has made you forgotten — and taste the everlasting punishment for what you used to do.", "এই দিনটিকে তোমাদের ভুলে যাওয়ার পরিনাম ভোগ করো; এখন আমরা তোমাদের ভুলে গেলাম। তোমরা তোমাদের নিজেদের কাজের বদলে চিরস্থায়ী শাস্তি টেনে এনেছ।"],
  "32:15": ["Only those believe in Allah's signs who, when they are reminded of them, fall down prostrate and glorify with the praise of their Rabb, and they are not proud.", "আমাদের প্রকাশনাবলিতে সত্যিকার অর্থে কেবল সে লোকেরা বিশ্বাস করে যারা তা শুনামাত্র সেজদায় পতিত হয়। তারা তাদের প্রভুর গুণকীর্তন এবং প্রশংসা করে, কোন ঔদ্ধত্যতা ছাড়া।"],
  "32:16": ["Who turn their sides from the beds, calling their Rabb in fear and in hope, and spend from what Allah has provided them.", "তাদের পার্শ্ব নির্দ্বিধায় শয্যা ত্যাগ করে, তাদের প্রভুর উপাসনা করার জন্য, ভক্তি ও আশা থেকে, আর আমাদের জীবিকা থেকে তারা দেয়।"],
  "32:17": ["No soul knows what comfort for the eyes is hidden away for them, as a reward for what they used to do.", "তোমাদের কোন ধারণা নেই তোমাদের (সৎ) কাজের জন্য পুরষ্কার হিসেবে কী পরিমান আনন্দ ও সুখ তোমাদের জন্য অপেক্ষা করছে।"],
  "32:18": ["Is one who was a mumin like one who was rebellious? They are not equal.", "যে ব্যক্তি একজন বিশ্বাসী সে কি ঐ ব্যক্তির মতো যে অন্যায়কারী? তারা সমান নয়।"],
  "32:19": ["As for those who believed and did salih deeds, theirs are the gardens of shelter, as a welcome gift for what they used to do.", "আর তাদের জন্য যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে, তারা যোগ্য হয়েছে চিরস্থায়ী স্বর্গের। এমনই তাদের আবাস, তাদের কাজের বদলায়।"],
  "32:20": ["As for those who were rebellious, their shelter is the fire. Every time they want to get out of it, they are put back into it, and it is said to them: \"Taste the punishment of the fire that you used to call a lie.\"", "আর অন্যায়কারীদের জন্য, তাদের নিয়তি নরক। প্রতিবার তারা এর থেকে বের হবার চেষ্টা করলে, তাদেরকে জোড়পূর্বক ফিরিয়ে দেয়া হবে। তাদেরকে বলা হবে, \"নরকের যন্ত্রনা আস্বাদন করো যাতে তোমরা অবিশ্বাস করতে।\""],
  "32:21": ["And Allah will surely make them taste the nearer punishment before the greater punishment, so that they may return.", "আমরা তাদেরকে (এই দুনিয়ায়) ছোট শাস্তি ভোগ করাই, তারা (পরকালের) বড় শাস্তি টেনে আনার আগে, যাতে তারা (একটি পূর্বাভাষ পায় এবং) সংশোধিত হতে পারে।"],
  "32:22": ["And who is more unjust than one who is reminded of the signs of their Rabb and then turns away from them? Allah will surely requite the guilty.", "কে অধিক মন্দ সে ব্যক্তির চেয়ে যাকে তার প্রভুর এই প্রকাশনাবলি স্মরণ করিয়ে দেয়া হয়, এরপর সেগুলোকে উপেক্ষাই করতে থাকে? আমরা নিশ্চয় অপরাধীকে শাস্তি দিবো।"],
  "32:23": ["And Allah gave Musa the Book — so do not be in doubt about the meeting with Allah — and Allah made it a guide for the children of Israel.", "আমরা মূসাকে ঐশীগ্রন্থ দিয়েছি- তাঁর সাথে সাক্ষাতের ব্যাপারে কোন সন্দেহ করো না- এবং একে আমরা ইসরাইলের সন্তানদের জন্য একটি পথপ্রদর্শক করেছিলাম।"],
  "32:24": ["And Allah made among them leaders who guide by Allah's command, because they were sabir and had certainty in Allah's signs.", "আমরা তাদের মধ্য থেকে ইমাম নিযুক্ত করেছিলাম যারা আমাদের প্রত্যাদেশ অনুসারে পথ প্রদর্শন করতো, কারন তারা ছিল দৃঢ়তার সাথে অবিচল এবং নিশ্চয়তা অর্জন করেছিল আমাদের প্রকাশনাবলি সম্পর্কে।"],
  "32:25": ["Your Rabb will decide between them on the day of rising concerning that in which they used to differ.", "তোমাদের প্রভু সে সত্ত্বা যিনি পুনরুত্থান দিবসে তাদের বিচার করবেন, তাদের বিবাদ করা সবকিছুর ব্যাপারে।"],
  "32:26": ["Has Allah not shown them how many generations before them Allah destroyed, while they walk in their dwellings? Truly in that are signs — will they not hear?", "তারা কি কখনো এটা উপলব্ধি করে যে তাদের আগে আমরা কত প্রজন্মকে ধ্বংস করেছি?  তারা এখন  বাস করে এবং চলাফেরা করে তাদের পূর্বপুরুষদের বাড়ি-ঘরে। এটি যথেষ্ট প্রমান হওয়া উচিত। তারা কি শুনে না?"],
  "32:27": ["Do they not see that Allah drives the water to the barren land and brings forth crops by it, from which their cattle and they themselves eat? Will they not see?", "তারা কি অনুধাবন করে না যে আমরা অনুর্বর জমিতে পানি প্রবাহিত করি, এবং তা দিয়ে ফসল উৎপাদন করি তাদের পশু সম্পদ খাওয়াতে, সেই সাথে তাদেরকেও? তারা কি দেখে না?"],
  "32:28": ["And they say: \"When is this triumph, if you are sadiq?\"", "তারা চ্যালেঞ্জ করে, \"কোথায় সেই বিজয়, যদি তোমরা সত্যবাদী হও?\""],
  "32:29": ["Say: \"On the day of triumph, the belief of those who kafara will not benefit them, nor will they be given respite.\"", "বল, \"যেদিন এমন বিজয় আসবে, বিশ্বাস করা তাদের উপকারে আসবে না যারা তার আগে বিশ্বাস করেনি, না তাদেরকে আরেকবার সুযোগ দেয়া হবে।\""],
  "32:30": ["So turn away from them and wait; they too are waiting.", "অতএব, তাদের উপেক্ষা করো এবং অপেক্ষা করো, তারাও অপেক্ষা করছে।"],
  "33:1": ["O Prophet, be mindful of Allah and do not obey the kafirin and the munafiqin; Allah is knowing, wise.", "হে নবী, তুমি আল্লাহকে ভক্তি করবে এবং অবিশ্বাসী ও ভন্ডদের মান্য করবে না। আল্লাহ সর্বজ্ঞ, সবচেয়ে প্রজ্ঞাময়।"],
  "33:2": ["And follow what is inspired to you from your Rabb; Allah is aware of all you do.", "অনুসরণ করো তোমার প্রভুর পক্ষ থেকে তোমার কাছে যা প্রকাশ করা হয়েছে। তোমরা সকলে যা করো তার সবকিছু সম্পর্কে আল্লাহ সম্পূর্ণ অবগত।"],
  "33:3": ["And trust in Allah; sufficient is Allah as trustee.", "আর আল্লাহর উপর তোমার আস্থা রাখো। সমর্থক হিসেবে আল্লাহ যথেষ্ট।"],
  "33:4": ["Allah has not made for any man two hearts inside his body, and Allah has not made your nisa, whom you declare against as their mothers, actually your mothers, nor has Allah made your adopted sons your true sons. That is only your saying with your mouths, while Allah speaks the truth and guides the way.", "আল্লাহ কোন মানুষের বুকে দু'টি হৃদয় দেননি। না তিনি মা'তে পরিনত করেন তোমাদের স্ত্রীদেরকে, যাদেরকে তোমরা (তোমাদের প্রথা অনুসারে) আলাদা করো। না তিনি তোমাদের পালিত সন্তানকে বংশগত সন্তানে পরিনত করেন। এগুলো তো মুখের কথা মাত্র যা তোমরা উদ্ভাবন করেছো। আল্লাহ সত্য বলেন, এবং তিনি (সঠিক) পথ দেখান।"],
  "33:5": ["Call them after their own fathers; that is more equitable with Allah. If you do not know their fathers, then they are your brothers in religion and your allies. There is no blame on you for what you err in, but only for what your hearts do deliberately. And Allah is forgiving, merciful.", "তোমরা তোমাদের পালিত সন্তানদের নাম দিবে যা তাদের বংশগত মাতাপিতার সাথে তাদের সম্পর্ক রক্ষা করে। এটা আল্লাহর দৃষ্টিতে অধিক ন্যায়সঙ্গত। যদি তোমরা তাদের মাতাপিতাকে না জানো, তাহলে, তোমাদের ধর্মের ভাই-বোন হিসেবে, তোমরা তাদেরকে তোমাদের পরিবারের  সদস্য হিসেবে গন্য করবে। তোমরা কোন পাপ করো না এইক্ষেত্রে যদি তোমরা ভুল করে ফেলো; তোমরা তোমাদের উদ্দেশ্যমূলক অভিপ্রায়ের জন্য দায়ী। আল্লাহ ক্ষমাকারী, পরম দয়ালু।"],
  "33:6": ["The Prophet is closer to the muminin than their own selves, and the Prophet's nisa are their mothers. And those joined by blood ties are closer to one another in Allah's decree than the muminin and the muhajirin, unless you do kindness to your allies. That has been written down in the decrees.", "তাদের একে অন্যের চেয়ে নবী বিশ্বাসীদের নিকটতর, আর তাদের কাছে তার স্ত্রীরা মায়ের মতন।  আল্লাহর ঐশীগ্রন্থ অনুসারে আত্মীয়দের উচিত একে অন্যের দেখ-ভাল করা। এভাবে, বিশ্বাসীরা দেখভাল করবে তাদের আত্মীয়দের যারা দেশান্তরিত হয়ে তাদের কাছে এসেছে, তবে আগে তাদের নিজ পরিবারের দেখভাল করবে। এগুলো এই ঐশীগ্রন্থের প্রত্যাদেশাবলি।"],
  "33:7": ["And when We took from the nabis their pact, and from you, and from Nuh, and Ibrahim, and Musa, and Isa son of Maryam, We took from them a hard pledge.", "স্মরণ করো যে আমরা নবীদের থেকে তাদের অঙ্গীকার নিয়েছিলাম, তোমাকে সহ (হে মুহাম্মদ), নূহ, ইব্রাহিম, মূসা, এবং মরিয়মের পূত্র ঈসা থেকেও। আমরা তাদের থেকে একটি  গুরুত্বপূর্ণ অঙ্গীকার নিয়েছিলাম।"],
  "33:8": ["So that Allah may ask the sadiqin about their sadiqness, and has prepared for the kafirin a painful punishment.", "পরবর্তীতে, তিনি অবশ্যই সত্যবাদীদের প্রশ্ন করবেন তাদের সত্যবাদীতা সম্পর্কে, এবং অবিশ্বাসীদের জন্য প্রস্তুত করেছেন (এই কুরআনীয় ঘটনার বিষয়ে) এক যন্ত্রণাকর শাস্তি।"],
  "33:9": ["O you who believe, remember Allah's favor upon you when hosts came at you and We sent against them a wind and hosts you never saw; and Allah sees all you do.", "হে বিশ্বাসীরা, তোমাদের উপর আল্লাহর অনুগ্রহ স্মরণ কর।যখন সৈন্যরা তোমাদের আক্রমণ করেছিলো, আমরা তাদের উপর পাঠিয়েছিলাম ঝড়ো বাতাস এবং অদৃশ্য সৈন্য। আল্লাহ সবকিছু দেখেন যা তোমরা করো।"],
  "33:10": ["When they came at you from above you and from below you, and when eyes swerved and hearts reached the throats, and you held all kinds of thoughts about Allah.", "যখন তারা এসেছিল তোমাদের উপর থেকে, এবং তোমাদের নিচ থেকে, তোমাদের চোখ আতংকিত হয়েছিল, তোমাদের হৃদয়ে ধৈর্য্য ফুরিয়ে গিয়েছিলো, এবং তোমরা আল্লাহ সম্পর্কে বেমানান ধারনা পোষন করছিলে।"],
  "33:11": ["There the muminin were tested and shaken with a severe shaking.", "ঠিক তখনই বিশ্বাসীদের সত্যিকারভাবে পরীক্ষা করা হয়েছিল;  তারা প্রচন্ড ভাবে কম্পিত হয়েছিল।"],
  "33:12": ["And when the munafiqin and those in whose hearts is sickness said, \"What Allah and the Rasul promised us is nothing but deception.\"", "ভন্ডরা ও যাদের হৃদয়ে সন্দেহ ছিল তারা বলল, \"আল্লাহ ও তাঁর বার্তাবাহক আমাদেরকে যে প্রতিশ্রুতি দিয়েছেন তা এক মোহের চেয়ে বেশি কিছু নয়।"],
  "33:13": ["And when a party of them said, \"O people of Yathrib, there is no standing place for you here, so turn back.\" And a group of them asked leave of the Prophet, saying, \"Our houses are exposed,\" though they were not exposed; they wanted only to flee.", "তাদের এক দল বলল, \"হে ইয়াসরেবের (মদিনার) লোকেরা, তোমরা বিজয় অর্জন করতে পারবে না; ফিরে যাও।” বাকীরা নবীর কাছে অজুহাত দাঁড় করালোঃ \"আমাদের ঘর অরক্ষিত, “যখন সেগুলো অরক্ষিত ছিল না। তারা কেবল পালাতে চেয়েছিল।"],
  "33:14": ["If the enemy had entered on them from all sides and they had been asked to betray, they would have done it, and would not have tarried over it but briefly.", "যদি শত্রুরা হামলা করতো এবং তাদের যোগ দিতে বলতো, তারা নির্দ্বিধায় শত্রুদের সাথে যোগ দিতো।"],
  "33:15": ["They had already pledged to Allah that they would not turn their backs; and a pledge to Allah will be asked about.", "তারা অতীতে আল্লাহর কাছে অঙ্গীকার করেছিল যে তারা পিছু হটে পালিয়ে যাবে না; আল্লাহর সাথে অঙ্গীকার করলে এক  মহা দায়িত্ব বর্তায়।"],
  "33:16": ["Say: \"Flight will not benefit you if you flee from death or from killing, and even then you will enjoy only a little.\"", "বল, \"যদি তোমরা পালাও, তোমরা কখনো পালাতে পারবে না মৃত্যু থেকে অথবা হত্যা হওয়া থেকে। যাই ঘটুক না কেন, তোমরা শুধু কিছুকাল বেশি বাঁচো। \""],
  "33:17": ["Say: \"Who is it that can shield you from Allah if Allah intends harm for you, or intends mercy for you?\" And they will find for themselves, besides Allah, no protector and no helper.", "বল, \"কে তোমাদেরকে আল্লাহ থেকে বাচাঁবে যদি তিনি তোমাদের জন্য কোন দূর্ভোগ চান, অথবা কোন অনুগ্রহ চান তোমাদের জন্য?” তারা কখনো পাবে না, আল্লাহর পাশে, অন্য কোন প্রভু ও মনিব।"],
  "33:18": ["Allah knows those among you who hold back, and those who say to their brothers, \"Come over to us,\" yet they hardly come to the fight at all.", "আল্লাহ পুরোপুরি অবগত তোমাদের মধ্যকার বিঘ্ন সৃষ্টিকারীদের বিষয়ে, এবং যারা তাদের সহযোদ্ধাদের বলে, \"চল আমরা সবাই পিছনে থাকি।” তারা খুব কমই প্রতিরক্ষার জন্য একত্রিত হয়।"],
  "33:19": ["They are stingy toward you; and when fear comes you see them looking at you, their eyes rolling like one overcome by death; and when the fear passes they lash at you with sharp tongues, stingy toward any good. Those are the ones who have not believed, so Allah has voided their deeds; and that is easy for Allah.", "এছাড়া, তারা তোমার সাথে আচরনে খুবই কৃপণ। যদি কোনকিছু সম্প্রদায়কে হুমকি দেয়, তুমি দেখ যে ভয়ে তাদের চোখ টলমল করে, যেন মৃত্যু তাদের কাছে এসেই পড়লো। একবার সংকট কেটে গেলে, তারা তোমাকে কষাঘাত করে তীক্ষ্ণ কথা দিয়ে। তারা তাদের সম্পদ নিয়েও খুব কৃপণ। এরা বিশ্বাসী নয়, আর, পরিনামে, আল্লাহ তাদের কাজকে নিষ্ফল করে দিয়েছেন। এটা করা আল্লাহর জন্য সহজ।"],
  "33:20": ["They think the parties have not gone. If the parties came, they would wish they were out in the open land among the desert Arabs, asking after news of you. And if they were among you, they would fight only a little.", "তারা ভেবেছিল হয়তো দলগুলো ফিরে আসতে পারে। সেক্ষেত্রে, তারা চাইতো যে  যদি তারা মরুভূমিতে হারিয়ে গিয়ে, দূর থেকে তোমাদের খবরাখবর নিতো। যদি তোমাদের সাথে তারা থাকাকালে দলগুলো তোমাদেরকে আক্রমণ করতো, তারা খুব কমই তোমাদের সহায়তা করতো।"],
  "33:21": ["Indeed, in the Rasul of Allah you have a good pattern for whoever hopes in Allah and the Last Day and remembers Allah much.", "তোমাদের মধ্যে তাদের জন্য আল্লাহর বার্তাবাহক একটি ভাল উদাহরণ স্থাপন করেছেন যারা আল্লাহ ও শেষ দিনের অন্বেষণ করে, এবং প্রতিনিয়ত আল্লাহর বিষয়ে চিন্তা করে।"],
  "33:22": ["And when the muminin saw the parties, they said, \"This is what Allah and the Rasul promised us, and Allah and the Rasul were true.\" And it increased them only in faith and submission.", "যখন সত্যিকার বিশ্বাসীরা দলগুলোকে দেখলো (আক্রমণ করতে প্রস্তুত), তারা বলল, \"এর প্রতিজ্ঞাই আল্লাহ ও তাঁর বার্তাবাহক আমাদেরকে করেছিলেন, আর আল্লাহ ও তাঁর বার্তাবাহক সত্যবাদী।”এই (বিপজ্জনক পরিস্থিতি) কেবল তাদের বিশ্বাসকে শক্তিশালী করেছিল এবং তাদের আত্মসমর্পণ বাড়িয়ে দিয়েছিল।"],
  "33:23": ["Among the muminin are men who were true to the pledge they owed Allah; some of them fulfilled their vow, and some are still waiting, and they have not changed in the least.", "বিশ্বাসীদের মধ্যে সে সব লোকেরা রয়েছে যারা আল্লাহর সাথে তাদের অঙ্গীকার পরিপূর্ণ করে। তাদের কেউ কেউ মারা যায়, যখন অন্যরা প্রস্তুত হয়ে থাকে, কখনো দ্বিধান্বিত না হয়ে।"],
  "33:24": ["So that Allah may repay the sadiqin for their sadiqness and punish the munafiqin if Allah wills, or turn to them in forgiveness; Allah is forgiving, merciful.", "আল্লাহ অবশ্যই সত্যবাদীদের প্রতিদান দেবেন তাদের সত্যবাদিতার জন্য, এবং ভণ্ডদের শাস্তি দেবেন, যদি তিনি এমনই চান, অথবা পাপমুক্ত করবেন। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "33:25": ["Allah drove back the kafirin in their rage; they gained no good. And Allah spared the muminin from the fighting; Allah is strong, mighty.", "যারা অবিশ্বাস করেছে আল্লাহ তাদেরকে পিছু হটতে বাধ্য করেছেন তাদের ক্রোধ নিয়ে, এবং তারা খালি হাতে ফিরেছে। আল্লাহ এভাবে কোন যুদ্ধ থেকে বিশ্বাসীদের নিষ্কৃতি দেন। আল্লাহ ক্ষমতাবান, সর্বশক্তিমান।"],
  "33:26": ["And Allah brought down those of the People of the Book who had backed them from their strongholds, and cast terror into their hearts: a party you slew and a party you took captive.", "নিরাপদ অবস্থান থেকে নামিয়ে দিয়েছিলেন, এবং তাদের হৃদয়ে আতংক ছুঁড়ে দিয়েছিলেন। তাদের কতককে তোমরা হত্যা করেছো, আর কতককে বন্দী করেছো।"],
  "33:27": ["And Allah made you inherit their land, their homes, their wealth, and a land you had never trodden; and Allah is powerful over all things.", "তিনি তোমাদেরকে উত্তরাধিকারি হতে দিয়েছেন তাদের ভূমি, তাদের বাড়ি-ঘর, তাদের অর্থ, এবং সেসব ভূমি যাতে তোমরা কখনো পা রাখোনি। আল্লাহ সবকিছুর পূর্ণ নিয়ন্ত্রনে আছেন।"],
  "33:28": ["O Prophet, say to your nisa: \"If you desire the life of this world and its adornment, then come, I will provide for you and release you with a beautiful release.\"", "হে নবী, তোমার স্ত্রীদের বল, \"যদি তোমরা এই জীবন এবং এর তুচ্ছ বিষয়াদির অন্বেষণ করো, তাহলে চলো আমি তোমাদের ক্ষতিপূরণ দিয়ে দেই এবং তোমাদেরকে আপসে চলে যেতে দেই।"],
  "33:29": ["But if you desire Allah and the Rasul and the final home, then Allah has prepared for those of you who do good a great reward.", "\"কিন্তু যদি তোমরা অন্বেষণ করো আল্লাহ ও তাঁর বার্তাবাহককে, এবং পরকালের আবাস, তাহলে তোমাদের মধ্যকার সৎকর্মশীলদের জন্য আল্লাহ প্রস্তুত রেখেছেন এক মহা প্রতিদান।\""],
  "33:30": ["O nisa of the Prophet, whoever of you commits a clear obscenity, the punishment will be doubled for her; and that is easy for Allah.", "হে নবীর স্ত্রীরা, যদি তোমাদের কেউ গুরুতর অপরাধ করো, শাস্তি তার জন্য দ্বিগুন হবে। এটি আল্লাহর জন্য করা সহজ।"],
  "33:31": ["And whoever of you is devout to Allah and the Rasul and does right, We will give her reward twice over, and We have prepared for her a generous provision.", "তোমাদের যেকেউ আল্লাহ ও তাঁর বার্তাবাহককে অনুসরণ করে, এবং সৎ জীবন-যাপন করে, আমরা তাকে দিবো দ্বিগুন প্রতিদান, এবং আমরা তার জন্য প্রস্তুত রেখেছি এক উদার জীবিকা।"],
  "33:32": ["O nisa of the Prophet, you are not like any other nisa. If you are mindful, then do not soften your speech, so that one in whose heart is sickness may hope; and speak a recognized word.", "হে নবীর স্ত্রীরা, তোমরা অন্য কোন নারীর মতো নও, যদি তোমরা সৎকর্মশীলতা পালন করো। (তোমাদের অধিকতর দায়িত্ব আছে।) অতএব, তোমরা খুব কোমলভাবে কথা বলবে না, পাছে যাদের হৃদয়ে রোগ আছে তারা ভুল ধারনা পেতে পারে; তোমরা শুধু ন্যায়সঙ্গত কথা বলবে।"],
  "33:33": ["Settle in your homes and do not display yourselves with the display of the former pagan ignorance; establish the prayer, give the purifying dues, and obey Allah and the Rasul. Allah only wills to remove from you all filth, people of the household, and to purify you thoroughly.", "তোমরা তোমাদের ঘরে থাকবে,এবং লোকদের সাথে খুব বেশি মেলামেশা করবে না, যেমন তোমরা পুরনো অজ্ঞতার দিনগুলোতে করতে। তোমরা সংযোগ প্রার্থনা (সালাত) পালন করবে, এবং বাধ্যতামূলক দান (যাকাত) দিবে, এবং আল্লাহ ও তাঁর বার্তাবাহককে মান্য করবে। আল্লাহ তোমাদের থেকে সকল অপবিত্রতা দূর করতে চান, হে তোমরা যারা পবিত্র ঘরের চতুর্দিকে বাস করো, এবং চান তোমাদের পরিপূর্ণ পরিশুদ্ধ করতে।"],
  "33:34": ["And remember what is recited in your homes of Allah's signs and the wisdom; Allah is subtle-kind, aware.", "স্মরণ রাখো তোমাদের ঘরে যা আবৃতি করা হয় আল্লাহর প্রকাশনাবলির এবং এর মধ্যে  বিদ্যমান প্রজ্ঞা। আল্লাহ মহিমান্বিত, অবগত।"],
  "33:35": ["Indeed, the muslimin men and muslimat nisa, the muminin men and muminat nisa, the qanitin men and qanitat nisa, the sadiqin men and sadiqat nisa, the sabirin men and sabirat nisa, the khashi'in men and khashi'at nisa, the mutasaddiqin men and mutasaddiqat nisa, the sa'imin men and sa'imat nisa, the hafizin men who guard their openings and the hafizat nisa who guard, and the dhakirin Allah much, men and the dhakirat nisa — Allah has prepared for them forgiveness and a great reward.", "আত্মসমর্পণকারী পুরুষ, আত্মসমর্পণকারী নারী, বিশ্বাসী পুরুষ, বিশ্বাসী নারী, অনুগত পুরুষ, অনুগত নারী, সত্যবাদী পুরুষ, সত্যবাদী নারী, অবিচল পুরুষ, অবিচল নারী, ভক্তি-শ্রদ্ধাকারী  পুরুষ, ভক্তি-শ্রদ্ধাকারী  নারী, দানশীল পুরুষ, দানশীল নারী, রোজাদার পুরুষ, রোজাদার নারী, চরিত্রবান পুরুষ, চরিত্রবান নারী, এবং পুরুষ যে অহরহ আল্লাহকে স্মরণ করে, এবং স্মরণকারী নারী; আল্লাহ তাদের জন্য প্রস্তুত রেখেছেন ক্ষমা এবং এক মহা প্রতিদান।"],
  "33:36": ["It is not for a believing man or a believing imra'a, when Allah and the Rasul have decided a matter, to have any choice in their own affair; whoever disobeys Allah and the Rasul has strayed into clear error.", "যদি আল্লাহ ও তাঁর বার্তাবাহক কোন আদেশ দেন তবে ঐ আদেশের ব্যাপারে, কোন বিশ্বাসী পুরুষ অথবা বিশ্বাসী নারীর কোন পছন্দ নেই। যেকেউ আল্লাহ ও তাঁর বার্তাবাহকের অবাধ্য হয়, সে বহুদূরে পথভ্রষ্ট হয়েছে।"],
  "33:37": ["And when you said to the one whom Allah had favored and whom you had favored, \"Hold fast to your imra'a and be mindful of Allah,\" while you concealed within yourself what Allah was to make manifest, fearing people, though Allah is more worthy to be feared. So when Zaid had done with her, We married her to you, so that there would be no constriction on the muminin concerning the nisa of their adopted sons once they have done with them; and Allah's command is always carried out.", "স্মরণ করো যে তুমি সে ব্যক্তিকে বলেছিলে যে আল্লাহর অনুগ্রহপ্রাপ্ত ছিল, এবং তোমার অনুগ্রহপ্রাপ্ত ছিল, \"তোমার স্ত্রীকে থাকতে দাও এবং আল্লাহকে ভক্তি করো,” আর তুমি তোমার নিজের ভিতর লুকাচ্ছিলে যা আল্লাহ ঘোষনা করতে চেয়েছিলেন। এভাবে, তুমি লোকদের ভয় করেছিলে, যখন তোমার কাছে কেবল আল্লাহকে ভয় করাই প্রত্যাশিত ছিল। যখন জায়েদ তার স্ত্রীর প্রতি পুরোপুরি আগ্রহ হারিয়েছিল, আমরা তাকে তোমার সাথে বিয়ে করালাম,  উদাহরণ স্থাপন করতে যে কোন পুরুষ তার পালিত পুত্রের তালাকপ্রাপ্তা স্ত্রীকে বিয়ে করতে পারে। আল্লাহর আদেশ পরিপূর্ণ হবেই।"],
  "33:38": ["No constriction lies on the Prophet in what Allah has ordained for him; that is the way of Allah with those who passed before; and Allah's command is a decreed decree.", "নবী কোন ভুল করছে না কোনকিছু করে যা আল্লাহর দ্বারা আইনসম্মত করা হয়েছে। এমনই আল্লাহর পদ্ধতি প্রারম্ভিক প্রজন্মগুলো থেকে। আল্লাহর আদেশ একটি পবিত্র দায়িত্ব।"],
  "33:39": ["Those are the ones who deliver the messages of Allah and hold reverent awe of Allah, and fear no one except Allah; and sufficient is Allah as reckoner.", "যারা আল্লাহর বার্তা পৌঁছে দেয়, এবং যারা একমাত্র তাঁর ভক্তি করে, তারা কখনো আল্লাহ ছাড়া কাউকে ভয় করবে না। আল্লাহ সবচেয়ে দক্ষ হিসাব গ্রহণকারী।"],
  "33:40": ["Muhammad is not the father of any of your men, but the Rasul of Allah and the seal of the nabis; and Allah knows all things.", "মুহাম্মদ তোমাদের মধ্যে কোন পুরুষের পিতা ছিল না। সে ছিল আল্লাহর একজন বার্তাবাহক এবং শেষ নবী। আল্লাহ সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "33:41": ["O you who believe, remember Allah with much remembrance.", "হে বিশ্বাসীরা, তোমরা আল্লাহকে বেশি বেশি স্মরণ করো।"],
  "33:42": ["And glorify Allah morning and evening.", "তোমরা দিন  রাত তাঁর মহিমা প্রকাশ করবে।"],
  "33:43": ["It is Allah who sends blessings upon you, and the malakat, to bring you out from darkness into light; and Allah is ever merciful to the muminin.", "তিনিই সে সত্ত্বা যিনি তোমাদের সাহায্য করেন, তাঁর ফেরেশতাদের সাথে, তোমাদেরকে অন্ধকার থেকে আলোয় পরিচালিত করতে। তিনি বিশ্বাসীদের প্রতি পরম দয়ালু।"],
  "33:44": ["Their greeting on the day they meet Allah will be \"Peace\"; and Allah has prepared for them a generous reward.", "তাঁর সাথে তাদের সাক্ষাতের দিনের অভিবাদন হলো, \"শান্তি,”এবং তিনি তাদের জন্য প্রস্তুত রেখেছেন এক উদার প্রতিদান।"],
  "33:45": ["O Prophet, We have sent you as a witness, a bearer of glad tidings, and a warner.", "হে নবী, আমরা তোমাকে পাঠিয়েছি একজন সাক্ষী হিসেবে, একজন সুসংবাদ বহনকারী, সেই সাথে একজন সতর্ককারী হিসেবে।"],
  "33:46": ["And a caller to Allah by Allah's permission, and a shining lamp.", "আল্লাহর দিকে আমন্ত্রন জানাতে, তাঁর ইচ্ছানুসারে, এবং একটি পথপ্রদর্শক আলোকবর্তিকা।"],
  "33:47": ["And give the muminin glad tidings that they will have from Allah a great favor.", "বিশ্বাসীদের সুসংবাদ দাও, যে তারা আল্লাহর থেকে এক বিশাল অনুগ্রহ লাভ করেছে।"],
  "33:48": ["And do not obey the kafirin and the munafiqin; disregard their harm, and trust in Allah; sufficient is Allah as trustee.", "অবিশ্বাসী ও ভন্ডদের মান্য করো না, তাদের অপমান উপেক্ষা করো, এবং আল্লাহর উপর তোমার আস্থা রাখো; একজন উকিল হিসেবে আল্লাহই যথেষ্ট।"],
  "33:49": ["O you who believe, when you marry believing nisa and then divorce them before you have touched them, you have no waiting period to count against them; so provide for them and release them with a beautiful release.", "হে তোমরা যারা বিশ্বাস করো, যদি তোমরা বিশ্বাসী নারীদেরকে বিয়ে করে থাকো, এরপর তাদের সঙ্গে যৌন সহবাসের আগেই তাদের তালাক দাও, তারা তোমাদের কাছে বাধ্য নয় অন্তবর্তী সময় অপেক্ষা করতে (অপর পুরুষকে বিয়ে করার আগে)। তোমরা ন্যায়সঙ্গতভাবে তাদেরকে ক্ষতিপূরণ দিবে, এবং তাদেরকে আপোষে যেতে দাও।"],
  "33:50": ["O Prophet, We have made lawful for you your nisa to whom you have given their dowries, and those whom your right hand possesses from what Allah granted you as spoils, and the daughters of your paternal uncles, the daughters of your paternal aunts, the daughters of your maternal uncles, and the daughters of your maternal aunts who emigrated with you; and a believing imra'a if she gives herself to the Prophet, should the Prophet wish to marry her — exclusively for you, apart from the muminin. We know what We have ordained for them concerning their nisa and those their right hands possess, so that no constriction falls on you; and Allah is forgiving, merciful.", "হে নবী, আমরা তোমার জন্য আইনসম্মত করেছি তোমার স্ত্রীদের যাদেরকে তুমি তাদের ন্যায্য মোহরানা পরিশোধ করেছ, অথবা যা ইতোমধ্যে তোমার, যেমন আল্লাহ তোমাকে দিয়েছেন। এছাড়া, তোমার জন্য বিয়ের ক্ষেত্রে আইনসম্মত তোমার পিতার ভাইয়ের কন্যারা, তোমার পিতার বোনের কন্যারা, তোমার মায়ের ভাইয়ের কন্যারা, তোমার মায়ের বোনের কন্যারা,  যারা তোমার সাথে দেশান্তরিত হয়েছে। এছাড়াও, কোন বিশ্বাসী নারী যদি নিজেকে নবীর কাছে নিবেদন করে – স্বেচ্ছায় মোহরানা ত্যাগ করে- নবী তাকে মোহরানা ছাড়াই বিয়ে করতে পারে, যদি সে তা-ই চায়। যদিও, তার স্বেচ্ছায় মোহরানা ত্যাগ শুধু নবীর ক্ষেত্রে প্রযোজ্য, এবং অন্য বিশ্বাসীদের ক্ষেত্রে নয়। আমরা ইতোমধ্যেই তাদের অধিকারের বিষয় আদেশ করেছি, তাদের সহধর্মী/সহধর্মীনি বা ইতোমধ্যেই তাদের যা আছে সে ব্যাপারে। এটা তোমাকে কোনপ্রকার বিব্রতকর অবস্থা থেকে নিষ্কৃতি দেয়ার জন্য। আল্লাহ ক্ষমাকারী, পরম দয়ালু।"],
  "33:51": ["You may put off whom you wish of them and take to yourself whom you wish; and if you seek again one you had set aside, there is no blame on you. That is nearer to comforting their eyes, so that they do not grieve and are content with what you have given them all. Allah knows what is in your hearts; and Allah is knowing, forbearing.", "তুমি ভদ্রভাবে তাদের যে কোন কারো থেকে দূরে থাকতে পারো, এবং তুমি তাদের যে কোন কাউকে কাছে আনতে পারো। যদি তুমি যে কোন কারো সাথে পূনর্মিলিত হও যার সাথে তুমি বিছিন্ন হয়েছিলে, তুমি কোন ভুল করো না। এই ভাবে, তারা সন্তুষ্ট থাকবে, কোনপ্রকার শোক থাকবে না, এবং তাতে তৃপ্ত থাকবে যা তুমি তাদের সবাইকে ন্যায়সঙ্গতভাবে প্রস্তাব করো। আল্লাহ জানেন যা তোমাদের হৃদয়ে আছে। আল্লাহ সর্বজ্ঞ, সহনশীল।"],
  "33:52": ["No (other) nisa are lawful for you after this, nor may you exchange them for other nisa, even if their beauty pleases you — except those whom your right hand possesses; and Allah watches all things.", "তোমার কাছে বর্ণনা করা প্রকারগুলোর  বাইরে, অন্য কোন নারীকে বিয়ে করা তোমার জন্য নিষেধ, না তুমি কোন নতুন স্ত্রী তাদের পরিবর্তে আনতে পারবে (নিষেধকৃত প্রকারগুলো থেকে), তুমি তাদের রূপে যতই মুগ্ধ হও না কেন। তুমি অবশ্যই তাদের নিয়ে তৃপ্ত থাকবে যাদেরকে ইতোমধ্যেই তোমার কাছে আইনসম্মত করা হয়েছে। আল্লাহ সবকিছুর উপর সতর্ক নজর রাখেন।"],
  "33:53": ["O you who believe, do not enter the houses of the Prophet unless permission is given to you for a meal, without waiting for it to be ready; but when you are invited, enter, and when you have eaten, disperse, without lingering for talk. That used to harm the Prophet, and the Prophet was too shy to ask you to leave; but Allah is not shy of the truth. And when you ask the Prophet's nisa for some goods, ask them from behind a veil; that is purer for your hearts and for their hearts. It is not for you to harm the Rasul of Allah, nor ever to marry the Prophet's nisa after the Prophet; that, in Allah's sight, is immense.", "হে যারা বিশ্বাস করো, নবীর ঘরে প্রবেশ করো না যদি না তোমাদেরকে খাওয়ার অনুমতি দেয়া হয়, না তোমরা কোনভাবে এমন আমন্ত্রণের জন্য জোর করবে। যদি তোমরা আমন্ত্রিত হও, তোমরা প্রবেশ করতে পারো। যখন তোমরা খাওয়া শেষ করো, তোমরা প্রস্থান করবে; তাকে দীর্ঘ আলোচনায় সম্পৃক্ত করো না। এটা নবীকে কষ্ট দিতো, এবং সে তোমাদেরকে বলতে খুব লজ্জা পেতো। কিন্তু, আল্লাহ সত্যে লজ্জা বোধ করেন না। যদি তার স্ত্রীদের কাছে তোমাদের কোন কিছু চাইতে হয়/ জিজ্ঞাসা করতে হয়, একটি পর্দার আড়াল থেকে তাদের জিজ্ঞাসা করো/ কাছে চাও। এটা তোমাদের হৃদয় এবং তাদের হৃদয়ের জন্য শুদ্ধতর। তোমরা তোমাদের আল্লাহর বার্তাবাহককে কষ্ট দিবে না। তোমরা তার পরে তার স্ত্রীদের বিয়ে করবে না, কারণ আল্লাহর দৃষ্টিতে তা হবে এক গুরুতর অপরাধ।"],
  "33:54": ["If you make a thing manifest or conceal it, Allah knows all things.", "তোমরা কোনকিছু প্রকাশ করো, অথবা তা গোপন করো, আল্লাহ সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "33:55": ["No blame rests on the Prophet's nisa in appearing before their fathers, their sons, their brothers, their brothers' sons, their sisters' sons, their nisa, and those whom their right hands possess. Be mindful of Allah; Allah witnesses all things.", "নারীরা (তাদের পোষাক নীতি) শিথিল করতে পারে তাদের পিতা, তাদের পুত্র, তাদের ভাই, তাদের ভাইদের পুত্র, তাদের বোনদের পুত্র, অন্য নারী, এবং তাদের (নারী) ভৃত্যদের কাছে। তারা আল্লাহকে ভক্তি করবে। আল্লাহ সবকিছু প্রত্যক্ষ করেন।"],
  "33:56": ["Allah and the malakat send blessings upon the Prophet. O you who believe, send blessings upon the Prophet and greet with a greeting of submission.", "আল্লাহ ও তাঁর ফেরেশতারা নবীকে সাহায্য ও সমর্থন করেন। হে তোমরা যারা বিশ্বাস করো, তোমরা তাকে সাহায্য ও সমর্থন করবে, আর তাকে গণ্য করবে যেভাবে তাকে গণ্য করা উচিত।"],
  "33:57": ["Those who harm Allah and the Rasul — Allah curses them in this world and the next, and has prepared for them a humiliating punishment.", "নিশ্চয়, যারা আল্লাহ ও তাঁর বার্তাবাহকের বিরোধীতা করে, আল্লাহ তাদেরকে অভিশাপ দেন কষ্ট দিতে এই জীবনে, এবং পরকালে; তিনি তাদের জন্য প্রস্তুত রেখেছেন এক লজ্জাকর শাস্তি।"],
  "33:58": ["And those who harm believing men and nisa for what they have not earned — they have taken up stunning-slander and clear sin.", "যারা বিশ্বাসী পুরুষ ও বিশ্বাসী নারীকে কষ্ট দেয়, যারা কোন ভুল করেনি, তারা শুধু মিথ্যাচার করেনি, বরং এক ঘোর পাপ করেছে।"],
  "33:59": ["O Prophet, tell your nisa and your daughters and the nisa of the muminin to draw over themselves some of their outer cloaks; that is nearer to their being recognized and not harmed; and Allah is forgiving, merciful.", "হে নবী, বলো তোমার স্ত্রীদের, তোমার কন্যাদের এবং বিশ্বাসীদের স্ত্রীদের যে তারা তাদের পোষাক দীর্ঘ করবে। এভাবে, তাদের চেনা যাবে (সৎকর্মশীল নারী হিসেবে) এবং অপমানিত হওয়া এড়াবে। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "33:60": ["If the munafiqin, and those in whose hearts is sickness, and the alarm-mongers in the town do not cease, We will surely stir you against them, and then they will not dwell beside you in it except a little while.", "যদি না  ভন্ডরা, এবং যাদের হৃদয়ে রোগ আছে, এবং শহরের জঘন্য মিথ্যুকরা (তোমাদের উপর অত্যাচার করা থেকে) বিরত হয়, আমরা অবশ্যই তোমাকে কর্তৃত্ব দিবো, এরপর কিছু সময়ের মধ্যে স্থান ত্যাগের জন্য তারা বাধ্য হবে।"],
  "33:61": ["Cursed; wherever they are overtaken, they will be seized and slain utterly.", "যেখানেই তারা যাক, তারা শাস্তি টেনে এনেছে; (যদি না তারা তোমাদের উপর আক্রমন করা বন্ধ করে,) তাদেরকে হয়তো বন্দী এবং হত্যা করা হবে।"],
  "33:62": ["That is the way of Allah with those who passed before, and you will never find any change in the way of Allah.", "এটি আল্লাহর চিরস্থায়ী পদ্ধতি, এবং তুমি দেখবে যে আল্লাহর পদ্ধতি অপরিবর্তনীয়।"],
  "33:63": ["People ask you about the Hour. Say: \"Its knowledge is with Allah alone. What can tell you — perhaps the Hour is near.\"", "লোকেরা তোমাকে সে ঘন্টা (বিশ্বের সমাপ্তি) সম্পর্কে জিজ্ঞেস করে। বল, \"এর জ্ঞান কেবল আল্লাহর কাছে। যতটুকু তুমি জানো, সে সময় হয়তো নিকটে।\""],
  "33:64": ["Allah has cursed the kafirin and prepared for them a blaze.", "আল্লাহ অবিশ্বাসীদের অভিশপ্ত করেছেন, এবং তাদের জন্য নরক প্রস্তুত রেখেছেন।"],
  "33:65": ["Abiding in it forever, finding no protector and no helper.", "সেখানে তারা চিরকাল থাকে। তারা কোন প্রভু পাবে না, না কোন সমর্থনকারী।"],
  "33:66": ["The day their faces are turned over in the Fire, they will say, \"If only we had obeyed Allah and obeyed the Rasul.\"", "যেদিন তারা নরকে নিক্ষিপ্ত হবে, তারা বলবে, \"আহা, আমরা যদি আল্লাহকে মান্য করতাম, এবং বার্তাবাহককে মান্য করতাম।"],
  "33:67": ["And they will say, \"Our Rabb, we obeyed our masters and our great ones, and they led us astray from the way.\"", "তারা আরো বলবে, \"আমাদের প্রভু, আমরা আমাদের মনিব ও নেতাদের মান্য করেছিলাম, কিন্তু তারা আমাদের বিপথে পরিচালিত করেছে।"],
  "33:68": ["\"Our Rabb, give them double the punishment, and curse them with a great curse.\"", "\"আমাদের প্রভু, তাদেরকে দ্বিগুন শাস্তি দিন, এবং তাদেরকে এক ভয়ানক অভিশাপে অভিশপ্ত করুন।\""],
  "33:69": ["O you who believe, do not be like those who harmed Musa; Allah cleared Musa of what they said, and Musa was ever honored with Allah.", "হে তোমরা যারা বিশ্বাস করো, তাদের মতো হয়ো না যারা মূসাকে আঘাত করেছিল, এরপর তারা যা বলেছিল তা থেকে আল্লাহ তাকে নির্দোষ প্রমান করলেন। সে ছিল, আল্লাহর দৃষ্টিতে, সম্মানিত।"],
  "33:70": ["O you who believe, be mindful of Allah and speak a straight word.", "হে তোমরা যারা বিশ্বাস করো, আল্লাহকে ভক্তি করো এবং কেবল সঠিক কথাটিই বলো।"],
  "33:71": ["Allah will set your deeds right for you and forgive you your offenses; whoever obeys Allah and the Rasul has won a great win.", "তাহলে তিনি তোমাদের কাজগুলো ঠিক করে দেবেন, এবং তোমাদের পাপগুলো ক্ষমা করবেন। যারা আল্লাহ এবং তাঁর বার্তাবাহককে মান্য করে তারা এক মহা বিজয়ে জয়ী হলো।"],
  "33:72": ["We offered the trust to the heavens and the earth and the mountains, but they refused to bear it and shrank in awe from it, and man bore it; truly, man is ever wrongful, ignorant.", "আমরা আকাশমন্ডলী ও পৃথিবী, এবং পর্বতগুলোকে (ইচ্ছা স্বাধীনতার) দায়িত্ব নিতে প্রস্তাব করেছিলাম, কিন্তু তারা তা বহন করতে অস্বীকার করলো, এবং তাতে ভীত হল। কিন্তু মানুষ তা গ্রহন করলো; সে ছিল সীমালঙ্ঘনকারী, অজ্ঞ।"],
  "33:73": ["So that Allah may punish the hypocritical men and nisa and the associating men and nisa, and turn in forgiveness to the believing men and nisa; and Allah is forgiving, merciful.", "কারণ আল্লাহ অবধারিতভাবে ভন্ড পুরুষ ও ভন্ড নারীদের, এবং শরিক উপাসনাকারী পুরুষ ও শরিক উপাসনাকারী নারীদের শাস্তি দিবেন। আল্লাহ বিশ্বাসী পুরুষ ও বিশ্বাসী নারীদের পাপমুক্ত করেন। আল্লাহ ক্ষমাকারী, পরম দয়ালু।"],
  "34:1": ["Praise be to Allah, to whom belongs what is in the heavens and what is in the earth, and to whom belongs the praise in the Hereafter; and Allah is the Wise, the Aware.", "প্রশংসা আল্লাহর - যাঁর অধীনে রয়েছে আকাশমন্ডলী ও পৃথিবীর সবকিছু; অধিকন্তু পরকালের সকল প্রশংসাও তাঁর জন্যই। তিনি সবচেয়ে প্রজ্ঞাময়, অবগত।"],
  "34:2": ["Allah knows what enters the earth and what comes out of it, and what comes down from the heaven and what ascends into it; and Allah is the Raheem, the Forgiving.", "তিনি জানেন সবকিছু যা মাটির ভেতর যায়, আর সবকিছু যা এর থেকে বের হয়ে আসে, আর সবকিছু যা আকাশ থেকে নেমে আসে, আর সবকিছু যা এর মধ্যে উত্থিত হয়। তিনি পরম দয়ালু, ক্ষমাশীল।"],
  "34:3": ["Those who disbelieve say: \"The Hour will not come to us.\" Say: \"Yes, by my Rabb, it shall surely come to you — knower of the unseen; not the weight of a mote in the heavens or in the earth escapes Allah, nor anything smaller than that or greater, but it is in a clear record.\"", "যারা অবিশ্বাস করে তারা বলেছে, \"সে সময় কখনো আসবে না!” বল, \"নিঃসন্দেহে - আমার প্রভুর শপথ - এটি অবশ্যই তোমাদের কাছে আসবে। তিনি ভবিষ্যৎ সম্পর্কে জানেন। এমনকি একটি পরমানুর ভরের সমতুল্য পরিমাণও তাঁর থেকে লুকানো নয়, হোক তা আকাশমন্ডলী অথবা পৃথিবীতে। না এমনকি তার চেয়ে ছোট কিছু অথবা বড় কিছু (লুকানো আছে)। সব কিছুই আছে এক জ্ঞানগর্ভ নথিতে।\""],
  "34:4": ["So that Allah may repay those who believe and do the good works — for them is forgiveness and a generous provision.", "অবশ্যই যারা বিশ্বাস করে এবং সৎ-জীবন-যাপন করে তিনি তাদেরকে পুরষ্কৃত করবেন। এরা ক্ষমা এবং এক উদার জীবিকার যোগ্য হয়েছে।"],
  "34:5": ["And those who strive against Our signs, seeking to overpower — for them is a punishment of a painful affliction.", "আর যারা অনবরত আমাদের প্রকাশনাবলিকে চ্যালেঞ্জ করে, তারা এক যন্ত্রণাদায়ক অপমানের শাস্তি অর্জন করেছে।"],
  "34:6": ["And those given knowledge see that what has been sent down to you from your Rabb is the truth, and it guides to the path of the Mighty, the Praised.", "এটা তাদের কাছে সুস্পষ্ট যারা জ্ঞান দ্বারা অনুগ্রহপ্রাপ্ত যে তোমার প্রভুর পক্ষ থেকে তোমার কাছে আসা এই প্রকাশনাবলি সত্য, এবং এটি সর্বশক্তিমান, সবচেয়ে প্রশংসনীয়ের দিকে পথনির্দেশ করে।"],
  "34:7": ["And those who disbelieve say: \"Shall we point you to a man who informs you that when you are torn apart, utterly torn, you will be in a new creation?\"", "যারা অবিশ্বাস করে তারা বলেছে, \"চল আমরা তোমাদেরকে একজন মানুষকে দেখাই  যে তোমাদের বলে যে তোমরা ছিন্ন-বিচ্ছিন্ন হবার পর তোমাদেরকে নতুন করে সৃষ্টি করা হবে।"],
  "34:8": ["Has he fabricated a lie against Allah, or is there madness in him? No — rather, those who do not believe in the Hereafter are in the punishment and the far error.", "\"হয় সে আল্লাহ সম্পর্কে মিথ্যা বানিয়েছে, নতুবা সে পাগল।” নিশ্চয়, যারা পরকালে অবিশ্বাস করে তারা সবচেয়ে নিকৃষ্ট শাস্তি টেনে এনেছে; তারা বহুদূর পথভ্রষ্ট হয়েছে।"],
  "34:9": ["Have they not looked at what is before them and behind them of the heaven and the earth? If We will, We sink the earth with them, or We drop upon them fragments from the sky. In that is a sign for every servant who turns back.", "তারা কি তাদের সম্মুখ এবং তাদের পিছনের সবকিছু দেখেনি, আকাশমণ্ডলী এবং পৃথিবীতে? যদি আমরা চাইতাম, আমরা পৃথিবীকে দিয়ে তাদের গ্রাস করাতে পারতাম, অথবা আকাশ থেকে তাদের উপর বস্তুপিণ্ডের পতন ঘটাতাম। এটা প্রত্যেক অনুগত বান্দার জন্য একটি যথেষ্ট প্রমান হওয়া উচিত।"],
  "34:10": ["And We gave Dawud a bounty from Us: \"O mountains, return his praise with him, and the birds,\" and We softened the iron for him.", "আমরা দাউদকে আমাদের পক্ষ থেকে অনুগ্রহ দান করেছিলাম: \"হে পর্বতসমূহ, তার সাথে আত্মসমর্পণ করো, আর তোমরাও, হে পাখিরা।” আমরা তার জন্য লোহাকে নরম করে দিয়েছিলাম।"],
  "34:11": ["\"Work ample coats of mail, and measure well in the links; and all of you do good — truly I see what you do.\"", "\"তুমি আত্ম-রক্ষার্থে ঢাল বানাও যা যথার্থই মানানসই হয়, এবং সৎকর্ম করো। যা কিছু তোমরা করো, আমি তা দেখি।\""],
  "34:12": ["And to Sulayman the wind: its morning a month and its evening a month; and We caused a spring of molten metal to flow for him. And of the jinn, some worked before him by the leave of his Rabb; and whichever of them swerved from Our command, We made him taste the punishment of the Blaze.", "সুলেমানের কাছে আমি বাতাসকে তার আজ্ঞাবহ করেছিলাম, যা আসতে ভ্রমন করতো একমাস আর যেতে একমাস। আর আমরা তার জন্য তেলের ঝর্ণা প্রবাহিত করেছিলাম। এছাড়াও, জীনরা তার জন্য কাজ করতো, তার প্রভুর অনুমতিতে। তাদের যেকেউ আমাদের আদেশকে উপেক্ষা করতো, আমরা তাকে কঠিন শাস্তি দিয়ে আয়ত্তে আনতাম।"],
  "34:13": ["They made for him what he wished: niches, and images, and basins like great cisterns, and firmly anchored cauldrons. \"Work, family of Dawud, in thanks.\" And few of My servants are thankful.", "তারা তার জন্য সবকিছুই বানাতো যা সে চাইতো - কুলুঙ্গি, মূর্তি, গভীর জলাশয়, এবং ভারী রান্নার পাত্র। হে দাউদের পরিবার, (সৎ) কর্ম করো তোমাদের কৃতজ্ঞতা প্রদর্শন করতে। আমার বান্দাদের মধ্যে অল্প সংখ্যকই শুধু কৃতজ্ঞ।"],
  "34:14": ["Then when We decreed death upon him, nothing pointed them to his death but a creature of the earth eating his staff; and when it fell down, the jinn realized that if they had known the unseen they would not have tarried in the humiliating punishment.", "যখন তার মৃত্যুর নির্ধারিত সময় এসে পড়লো, তাদের কাছে কোন ইঙ্গিত ছিল না যে সে মারা গিয়েছে। যতক্ষণ না একটি প্রানী তার লাঠি খাওয়ার চেষ্টা করলো, আর সে পড়ে গেল, তখনই জীনেরা বুঝলো যে সে মৃত। এভাবে তারা অনুধাবন করলো যে যদি তারা সত্যই অদৃশ্য বিষয় জানতো, তবে সে মারা যাওয়া মাত্রই তারা এত কষ্টকর কাজ করা বন্ধ করে দিতো।"],
  "34:15": ["For Saba there was a sign in their dwelling: two gardens, on the right and on the left. \"Eat of your Rabb's provision and give thanks for it — a good town and a forgiving Rabb.\"", "সাবার মাতৃভূমি ছিল এক বিস্ময়, ডানে ও বায়ে দু'টি বাগান সহ। তোমাদের প্রভুর জীবিকা থেকে খাও, এবং তাঁর প্রতি কৃতজ্ঞ হও- ভাল জমিনের জন্য, এবং এক ক্ষমাশীল প্রভু।"],
  "34:16": ["But they turned away, so We sent upon them the flood of the dam, and We substituted for their two gardens two gardens bearing bitter food, and tamarisk, and a few lote-trees.", "তারা মুখ ফিরিয়ে নিলো এবং, পরিনামে, আমরা তাদের উপর সর্বনাশা বন্যা প্রবাহিত করলাম, এবং আমরা তাদের দুই বাগানকে বদলে দিলাম খারাপ স্বাদের ফল বাগান, কাঁটাযুক্ত উদ্ভিদ, এবং অপর্যাপ্ত ফসলে।"],
  "34:17": ["That is how We repaid them for their disbelief — and do We repay anyone but the kafirin?", "আমরা এভাবে তাদের অবিশ্বাসের জন্য তাদেরকে শাস্তি দিয়েছি। আমরা কি শুধু অবিশ্বাসীদেরকেই শাস্তি দেই না?"],
  "34:18": ["And We placed between them and the towns We had blessed towns in plain sight, and We measured the journey through them: \"Journey through them nights and days, secure.\"", "আমরা তাদের ও যে সম্প্রদায়গুলোকে আমরা অনুগ্রহ করেছিলাম তাদের মাঝে অন্যান্য মরুদ্যান স্থাপন করেছিলাম, এবং আমরা এগুলোর মধ্যে যাত্রাকে নিরাপদ করেছিলাম: \"সেগুলোর মধ্যে দিনে এবং রাতে সম্পূর্ণ নিরাপদে ভ্রমণ করো।\""],
  "34:19": ["But they said: \"Our Rabb, stretch out our journeys,\" and they wronged themselves, so We made them into tales and tore them to pieces, utterly torn. In that are signs for every sabir, thankful one.", "কিন্তু (তারা অকৃতজ্ঞ হয়ে পড়লো এবং) চ্যালেঞ্জ করলো: \"আমাদের প্রভু, আমরা পরোয়া করি না যদি আপনি (কোন বিশ্রামস্থল ছাড়াই) আমাদের যাত্রার দূরত্ব বাড়িয়ে দেন।”তারা এভাবে তাদের নিজেদের আত্মার প্রতি অন্যায় করলো। ফলশ্রুতিতে, আমরা তাদেরকে ইতিহাস বানালাম, এবং তাদেরকে দেশজুড়ে ছোট ছোট সম্প্রদায়ে বিচ্ছিন্ন করে দিলাম। এগুলো তাদের জন্য শিক্ষা হওয়া উচিত যারা অবিচল, কৃতজ্ঞ।"],
  "34:20": ["And Iblis indeed proved true in his thinking about them, and they followed him — except for a party of the muminin.", "শয়তান তাদেরকে তৎক্ষণাৎ তার প্রত্যাশা পূর্ণ করতে দেখল। তারা তাকে অনুসরণ করলো, অল্প সংখ্যক বিশ্বাসী ছাড়া।"],
  "34:21": ["He had no warrant over them except that We might know who believes in the Hereaway from the one who stands in doubt of it; and your Rabb is guardian over everything.", "তাদের উপর কখনো তার কোন ক্ষমতা ছিল না। কিন্তু এভাবে যারা পরকালে বিশ্বাস করে তাদেরকে আমরা আলাদা করি তাদের থেকে যারা এ বিষয়ে সন্দিহান। তোমার প্রভু সবকিছুর পূর্ণ নিয়ন্ত্রনে আছেন।"],
  "34:22": ["Say: \"Call those you claim besides Allah; they own not the weight of a mote in the heavens or in the earth, and they have no partnership in the two, and no support comes to Allah from them.\"", "বল, \"সে উপাস্যদের কাছে চাও যাদেরকে তোমরা আল্লাহর পাশে স্থাপন করেছো। তারা আকাশমণ্ডলী, অথবা পৃথিবীর একটি পরমানুরও মালিক না। তারা সেখানকার কোন অংশীদারিত্বের মালিক না, না তিনি তাদেরকে তার সহকারী হবার অনুমতি দেন।\""],
  "34:23": ["And intercession avails nothing with Allah except for the one given leave; until, when the dread is lifted from their hearts, they say: \"What did your Rabb say?\" They say: \"The truth.\" And Allah is the High, the Great.", "তাঁর কাছে সুপারিশ করা অর্থহীন হবে, যদি না তা তাঁর ইচ্ছার সাথে মিলে যায়। তাদের মন যখন অবশেষে স্থির হয়, আর তারা জিজ্ঞেস কর, “তোমাদের প্রভু কি বলেছেন, ” তারা বলবে, \"সত্য।” তিনি সবচেয়ে উর্ধ্বে, সবচেয়ে মহান।"],
  "34:24": ["Say: \"Who provides for you from the heavens and the earth?\" Say: \"Allah.\" And either we or you are upon guidance or in clear error.", "বল, \"কে তোমাদের জীবিকা দেন, আকাশমণ্ডলী ও পৃথিবী থেকে?” বল, \"আল্লাহ, ”এবং \"হয় আমরা না হয় তোমরা সুপথপ্রাপ্ত, অথবা বহুদূরে পথভ্রষ্ট হয়েছি।\""],
  "34:25": ["Say: \"You will not be questioned about what we committed, nor will we be questioned about what you do.\"", "বল, \"তোমরা আমাদের অপরাধের জন্য দায়ী নও, না আমরা তার জন্য দায়ী যা তোমরা করো।\""],
  "34:26": ["Say: \"Our Rabb will gather us together, then decide between us in truth; and Allah is the Deciding, the Knowing.\"", "বল, \"আমাদের প্রভু তাঁর সামনে আমাদের সকলকে একত্রিত করবেন, তারপর তিনি আমাদের মাঝে ন্যায়সঙ্গত বিচার করবেন। তিনিই বিচারক, সর্বজ্ঞ।”"],
  "34:27": ["Say: \"Show me those you have joined to Allah as partners.\" No indeed! Rather, Allah is the Mighty, the Wise.", "বল, \"আমাকে সে উপাস্যদের দেখাও যাদেরকে তোমরা তাঁর সাথে শরিক হিসেবে স্থাপন করেছ!” বল, \"না; তিনিই সেই এক আল্লাহ, সর্বশক্তিমান, সবচেয়ে জ্ঞানী।\""],
  "34:28": ["And We sent you only to all people as a bringer of glad news and a warner — but most people do not know.", "(হে রাশাদ)  আমরা তোমাকে সব লোকদের কাছে পাঠিয়েছি, একজন সুসংবাদ বহনকারী, সেই সাথে একজন সতর্ককারী হিসেবে, কিন্তু অধিকাংশ লোক জানে না।"],
  "34:29": ["And they say: \"When is this promise, if you are sadiq?\"", "তারা চ্যালেঞ্জ করে, “কখন এই প্রতিশ্রুতি পূর্ন হবে, যদি তোমরা সত্যবাদী হও?”"],
  "34:30": ["Say: \"You have an appointed day which you will not delay by an hour, nor will you come early for it.\"", "বল, \"তোমাদের জন্য একটি নির্দিষ্ট সময় রয়েছে, একটি নির্দিষ্ট দিনে, যা তোমরা এক ঘণ্টার জন্যও পিছাতে পারবে না, না আগাতে পারবে।”"],
  "34:31": ["And those who disbelieve say: \"We will not believe in this Recitation, nor in what came before it.\" If you could only see when the wrongdoers stand before their Rabb, turning to one another in speech: those who were weakened say to those who grew proud, \"Had it not been for you, we would have been muminin.\"", "যারা অবিশ্বাস করেছে তারা বলেছে, \"আমরা এই কোর'আনে বিশ্বাস করবো না, না পূর্ববর্তী ঐশীগ্রন্থে।” যদি শুধু তুমি এসব সীমালঙ্ঘনকারীদেরকে দেখতে পেতে যখন তারা তাদের প্রভুর সামনে দাঁড়ায়! তারা আগে পিছে পরস্পরের সাথে বাদানুবাদ করবে। অনুসারীরা তাদের নেতাদের বলবে, \"তোমরা যদি না থাকতে, আমরা বিশ্বাসীই হতাম।\""],
  "34:32": ["Those who grew proud say to those who were weakened: \"Did we turn you away from the guidance after it came to you? No — you were committers of crime.\"", "সে নেতারা তাদেরকে বলবে যারা তাদের অনুসরণ করেছিল, \"আমরাই কি তোমাদের পথনির্দেশনা থেকে পথচ্যুত করেছি তোমাদের কাছে তা আসার পর? না; তোমরাই ছিলে অন্যায়কারী।\""],
  "34:33": ["And those who were weakened say to those who grew proud: \"No — it was your planning of night and day, when you commanded us to disbelieve in Allah and to make equals for Allah.\" And they hide their regret when they see the punishment; and We put fetters on the necks of those who kafara. Are they repaid except for what they did?", "অনুসারীরা তাদের নেতাদের বলবে, \"তোমরাই রাত-দিন ষড়যন্ত্র করেছিলে, তারপর আমাদেরকে আল্লাহর প্রতি অকৃতজ্ঞ হবার জন্য, এবং তাঁর সাথে সমমর্যাদা দিয়ে শরিক স্থাপন করতে আদেশ করেছিলে। \" তারা অনুশোচনায় জর্জরিত হবে,  যখন তারা শাস্তি দেখবে, কেননা আমরা তাদের ঘাড়ে শিকল পরাবো যারা অবিশ্বাস করেছিল। তারা যা করেছে তার জন্য কি তারা  ন্যায়সঙ্গত প্রতিফল পায়নি?"],
  "34:34": ["And We never sent a warner into a town without its ease-softened ones saying: \"We disbelieve in what you have been sent with.\"", "প্রত্যেকবার যখন আমরা কোন সম্প্রদায়ের কাছে কোন সতর্ককারী পাঠিয়েছি, ওই সম্প্রদায়ের নেতারা বলেছে, \"আমরা সে বার্তা প্রত্যাক্ষান করি, যা নিয়ে তোমরা প্রেরিত হয়েছো।\""],
  "34:35": ["And they say: \"We have more wealth and children, and we will not be punished.\"", "তারা আরো বলেছে, \"আমরা অধিক শক্তিশালী, বেশি টাকাকড়ি ও সন্তান-সন্ততিতে, আর আমাদেরকে শাস্তি দেয়া হবে না।\""],
  "34:36": ["Say: \"My Rabb spreads the provision for whom Allah wills and measures it — but most people do not know.\"", "বল, \"আমার প্রভু সে সত্তা যিনি সকল জীবিকা নিয়ন্ত্রণ করেন; তিনি যার জন্য ইচ্ছা জীবিকা দেন, অথবা এগুলো কমিয়ে দেন, কিন্তু অধিকাংশ লোক জানে না।\""],
  "34:37": ["Neither your wealth nor your children are what bring you near to Us in nearness, except for the one who believes and does good work; for those is a double repayment for what they did, and they are secure in the upper chambers.", "তোমাদের টাকা-পয়সা বা তোমাদের সন্তানাদি তোমাদেরকে আমাদের নিকটে আনে না। যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে শুধু তারাই তাদের কাজগুলোর জন্য পুরষ্কার পাবে, বহুগুনে বর্ধিত। স্বর্গীয় আবাসে তারা পূর্ণাঙ্গ শান্তিতে বাস করবে।"],
  "34:38": ["And those who strive against Our signs, seeking to overpower — those are present in the punishment.", "আর তাদের জন্য যারা আমাদের প্রকাশনাবলিকে অনাবরত চ্যালেঞ্জ করে যায়, তারা শাস্তিতে বাস করবে।"],
  "34:39": ["Say: \"My Rabb spreads the provision for whichever of Allah's servants Allah wills, and measures it; and whatever you spend of anything, Allah replaces it — and Allah is the best of providers.\"", "বল, \"আমার প্রভু সে সত্তা যিনি সকল জীবিকা নিয়ন্ত্রণ করেন; তিনি তাঁর বান্দাদের মধ্য থেকে যার জন্য পছন্দ করেন জীবিকা বাড়িয়ে দেন, অথবা এগুলো কমিয়ে দেন। তোমরা যা কিছু ব্যয় করো (আল্লাহর উদ্দেশ্যে), তিনি তার জন্য তোমাদের পুরষ্কৃত করবেন; তিনিই সর্বোত্তম জীবিকা প্রদানকারী।\""],
  "34:40": ["And on the day Allah gathers them all, then says to the malakat: \"Was it these who were worshipping you?\"", "সেদিন যখন তিনি তাদের সবাইকে তলব করবেন, তিনি ফেরেশতাদের বলবেন, \"এই লোকেরা কি তোমাদের উপাসনা করতো?”"],
  "34:41": ["They say: \"Glory be to You! You are our protector, not them.\" No — they worshipped the jinn; most of them believed in them.", "তারা উত্তর দিবে, “আপনি মহিমান্বিত। আপনি আমাদের প্রভু এবং আদেশ দাতা, তারা নয়। বরং, তারা জ্বীনদের উপাসনা করতো, তাদের অধিকাংশ তাতে বিশ্বাসী ছিল।”"],
  "34:42": ["So today none of you has power over another for benefit or harm; and We say to those who wronged: \"Taste the punishment of the Fire that you used to deny.\"", "সেদিন, একে অন্যকে সাহায্য বা ক্ষতি করার কোন ক্ষমতা তোমাদের থাকবে না, এবং আমরা সীমালঙ্ঘনকারীদের বলবো, “নরকের শাস্তি আস্বাদন করো যা তোমরা অস্বীকার করতে।”"],
  "34:43": ["And when Our clear signs are recited to them, they say: \"This is nothing but a man who wants to turn you away from what your fathers used to worship.\" And they say: \"This is nothing but a fabricated lie.\" And those who kafara say of the truth when it reached them: \"This is nothing but clear magic.\"", "তাদের কাছে যখন আমাদের প্রমাণ আবৃত্তি করা হয়েছিল, সম্পূর্ণরুপে স্পষ্ট, তারা বলেছিল, \"এ তো কেবলই একজন মানুষ যে তোমাদেরকে সে পথ থেকে সরিয়ে দিতে চায় যেভাবে তোমাদের মাতা-পিতারা উপাসনা করছে।” তারা আরো বলল, \"এগুলো বানোয়াট মিথ্যা।\" যারা অবিশ্বাস করেছে তাদের কাছে আসা সত্য সম্পর্কে  তারা এ-ও বলেছিল যে, \"এটা স্পষ্ট যাদু।\""],
  "34:44": ["We did not give them books to study, nor did We send to them before you any warner.", "আমরা তাদেরকে অধ্যয়ন করতে অন্যকোন গ্রন্থ দেইনি, না আমরা তোমার আগে তাদের কাছে অন্যকোন সতর্ককারী পাঠিয়েছি।"],
  "34:45": ["And those before them denied — though they did not reach a tenth of what We gave them — and they denied My rusul; so how dreadful was the rejection!", "যারা তাদের পূর্বে অবিশ্বাস করেছিল, এবং যদিও তারা এই প্রজন্মকে আমাদের দেয়া (অলৌকিকতার) এক-দশমাংশও দেখেনি, যখন তারা আমার বার্তাবাহকদের অবিশ্বাস করেছিল, কতই না কঠোর ছিল আমার শাস্তি!"],
  "34:46": ["Say: \"I admonish you with one thing: that you rise before Allah in twos and singly, and then reflect — there is no madness in your companion; he is only a warner to you, before a severe punishment.\"", "বল, \"আমি তোমাদের একটা বিষয় করতে বলি: নিজেদেরকে আল্লাহর কাছে উৎসর্গ করো, জোড়ায় জোড়ায় বা ব্যক্তিগতভাবে, এরপর ভেবে দেখো। তোমাদের বন্ধু (রাশাদ) পাগল নয়। সে তোমাদের কাছে একজন সুস্পষ্ট সতর্ককারী, এক ভয়ানক শাস্তি আসার ঠিক আগে।”"],
  "34:47": ["Say: \"Whatever wage I asked of you, it is yours; my wage is only upon Allah — and Allah is witness over everything.\"", "বল, \"আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না; তোমরা তা রাখতে পারো। আমার পারিশ্রমিক শুধুমাত্র আল্লাহর কাছ থেকে আসে। তিনি সবকিছু প্রত্যক্ষ করেন।\""],
  "34:48": ["Say: \"My Rabb casts the truth — knower of the unseen.\"", "বল, \"আমার প্রভু সত্যকে জয়ী করান। তিনি সকল গোপন বিষয় জানেন।\""],
  "34:49": ["Say: \"The truth has come, and falsehood neither begins nor returns.\"", "বল, \"সত্য এসেছে; যখন মিথ্যা না কোনকিছুর সূচনা করতে পারে, না এর পুনরাবৃত্তি করতে পারে।\""],
  "34:50": ["Say: \"If I err, I err only against myself; and if I am guided, it is by what my Rabb reveals. Truly Allah is Hearing, Near.\"", "বল, \"যদি আমি পথভ্রষ্ট হই, আমি পথভ্রষ্ট হই আমার নিজের ত্রুটির কারণে। আর যদি আমি পথপ্রাপ্ত হই, এটা আমার প্রভুর প্রত্যাদেশের বদৌলতে। তিনি শ্রবণকারী, নিকটবর্তী। \""],
  "34:51": ["If you could see when they are seized with dread, and there is no escape, and they are taken from a near place.", "যদি শুধু তুমি তাদেরকে দেখতে পারতে যখন সে মহা আতংক তাদের আঘাত করে; তখন তারা পলাতে পারবে না, এবং তাদেরকে জোরপূর্বক তুলে নেয়া হবে।"],
  "34:52": ["And they say: \"We believe in it.\" But how can they reach it from a far place?", "তারা তখন বলবে, \"আমরা এখন এতে বিশ্বাস করি,” কিন্তু তা অনেক বেশি দেরী হয়ে যাবে।"],
  "34:53": ["They kafara in it before, and they cast their guesses at the unseen from a far place.", "তারা অতীতে এটা প্রত্যাখ্যান করেছিল; পরিবর্তে তারা  মেনে চলার সিদ্ধান্ত নিয়েছিল ধারণা এবং অনুমাননির্ভর কর্ম।"],
  "34:54": ["And a barrier is set between them and what they desire, as was done with their parties before them; they were in disquieting doubt.", "পরিনামে, তারা সবকিছু থেকে বঞ্চিত হয়েছিল যার আকাঙ্ক্ষা তারা করতো। এটা সে একই ভাগ্য পূর্ববর্তী প্রজন্মে তাদের অনুরূপ লোকদের মতো। তারা খুব বেশি সন্দেহ পোষন করতো।"],
  "35:1": ["Praise belongs to Allah, originator of the heavens and the earth, who makes the malakat rusul with wings of two, and of three, and of four; Allah adds to the creation whatever Allah wills. Indeed Allah is over every thing powerful.", "প্রশংসা আল্লাহর, আকাশমণ্ডলী ও পৃথিবীর সূচনাকারী, এবং ফেরেশতাদের নিয়োগকারী পাখাযুক্ত বার্তাবাহক হবার জন্য-দুই, তিন, ও চার (পাখা)। তিনি সৃষ্টি বৃদ্ধি করেন যেমন তিনি চান। আল্লাহ সর্বশক্তিমান।"],
  "35:2": ["Whatever Allah opens for people of mercy, none can hold it back; and whatever Allah holds back, none can send it forth after that. And Allah is the Mighty, the Wise.", "যখন আল্লাহ লোকদের উপর দয়া বর্ষণ করেন, কোন শক্তি তা আটকাতে পারে না। এবং যদি তিনি তা আটকে রাখেন, কোন শক্তি, তিনি ব্যতিত, তা পাঠাতে পারে না। তিনিই সর্ব-শক্তিমান, সবথেকে জ্ঞানী।"],
  "35:3": ["O people, remember the blessing of Allah upon you. Is there any creator besides Allah providing you from the sky and the earth? There is no ilah but Allah. So how are you turned away?", "হে মানুষ, তোমাদের উপর আল্লাহর অনুগ্রহকে স্মরণ করো। আল্লাহ ছাড়া অন্য কোন সৃষ্টিকর্তা কি আছে যে তোমাদের জীবিকা দান করে আকাশমণ্ডলী এবং পৃথিবী থেকে? তাঁর পাশে অন্য কোন উপাস্য নেই। কেমন করে তোমরা পথভ্রষ্ট হও?"],
  "35:4": ["And if they deny you, rusul were denied before you; and to Allah the affairs return.", "যদি তারা তোমাকে অবিশ্বাস করে, তোমার পূর্বেও বার্তাবাহকদের অবিশ্বাস করা হয়েছে। আল্লাহ সকল বস্তুর নিয়ন্ত্রনে আছেন।"],
  "35:5": ["O people, the promise of Allah is true, so let not the nearer life deceive you, and let not the deceiver deceive you about Allah.", "হে মানুষ, আল্লাহর প্রতিশ্রুতি সত্য; অতএব, এই  নিম্নমানের জীবন দ্বারা বিভ্রান্ত হইও না। আল্লাহ থেকে নিছক বিভ্রমের দ্বারা বিচ্যুত হইও না।"],
  "35:6": ["Indeed Shaytan is an enemy to you, so take him for an enemy; he only calls his party to be among the companions of the blaze.", "শয়তান তোমাদের শত্রু, তাই তাকে শত্রু হিসাবে বিবেচনা করো। সে শুধু তার দলকে নরকের বাসিন্দা হতে আমন্ত্রন করে।"],
  "35:7": ["Those who disbelieve, for them is severe punishment; and those who believe and do salih deeds, for them is forgiveness and a great reward.", "যারা অবিশ্বাস করে তারা টেনে এনেছে এক ভীষণ শাস্তি, আর যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে তারা যোগ্য হয়েছে ক্ষমা ও এক মহা প্রতিদানের।"],
  "35:8": ["So is one whose evil deed is adorned for him so that he sees it as good? Indeed Allah leads astray whomever Allah wills and guides whomever Allah wills, so do not let your soul perish over them in regret; indeed Allah is knowing of what they do.", "সে ব্যক্তির প্রতি লক্ষ্য করো যার মন্দ কাজকে তার চোখে সাজিয়ে দেয়া হয়েছে, যতক্ষণ না সে ভাবে যে এটা সৎকাজ। আল্লাহ এভাবে পথভ্রষ্ট করেন যেকেউ চায় (পথভ্রষ্ট হতে), এবং তিনি পথপ্রদর্শন করেন যেকেউ চায় (সুপথপ্রাপ্ত হতে)। অতএব, তাদের জন্য দুঃখ করো না। আল্লাহ সবকিছু সম্পর্কে পূর্ণ অবগত যা তারা করে।"],
  "35:9": ["And Allah is the one who sends the winds, and they stir up clouds, and We drive them to a dead town, and We revive the earth with it after its death. Likewise is the rising.", "আল্লাহই সে সত্ত্বা যিনি বাতাস পাঠান মেঘমালাকে সঞ্চালিত করতে, এরপর আমরা সেগুলোকে অনুর্বর ভূমির দিকে চালনা করি, এবং এরকম ভূমিকে এগুলোর মৃত্যুর পর পুনরুজ্জীবিত করি। এভাবেই পুনরুত্থান হয়।"],
  "35:10": ["Whoever wants might, then to Allah belongs the might entirely. To Allah ascend the good word, and the salihin deed raises it. And those who plan evil deeds, for them is severe punishment; and the plan of those is ever ruined.", "যেকেউ মর্যাদা চায় তার জানা উচিত যে সকল মর্যাদা আল্লাহর। তাঁর দিকে ভালো কথা উত্থিত হয়, এবং তিনি সৎকর্মের উচ্চ-মূল্যায়ন করেন। আর যারা মন্দ কাজের ষড়যন্ত্র করে, তারা টেনে এনেছে কঠোর শাস্তি; এমন লোকদের ষড়যন্ত্রের নিয়তি হচ্ছে ব্যর্থ হওয়া।"],
  "35:11": ["And Allah created you from dust, then from a drop, then made you pairs; and no female bears or gives birth except by Allah's knowledge. And no life-term is prolonged for one of long life, nor diminished from its term, except in a record. Indeed that is easy for Allah.", "আল্লাহ তোমাদেরকে ধুলো থেকে সৃষ্টি করেছেন, এরপর ক্ষুদ্র ফোঁটা থেকে, এরপর তিনি তোমাদের সঙ্গিদের মাধ্যমে তোমাদের বংশবৃদ্ধি করান। কোন নারী গর্ভধারণ করে না, না জন্ম দেয়, তাঁর জ্ঞানের বাইরে। না কেউ দীর্ঘকাল বেঁচে থাকে, আর না কারো জীবন সংক্ষিপ্ত করা হয়, আগে থেকে বিদ্যমান কোন রেকর্ড অনুযায়ী ছাড়া। এটা আল্লাহর জন্য সহজ।"],
  "35:12": ["Not equal are the two seas: this one fresh, sweet, pleasant to drink, and this one salty, bitter; and from both you eat fresh flesh, and you extract adornment which you wear, and you see the ships plowing through it, that you may seek of Allah's bounty and that you may give thanks.", "দুই সাগর এক নয়; একটি বিশুদ্ধ ও সুস্বাদু, যখন অন্যটি লবনাক্ত ও পানের অযোগ্য। তাদের প্রত্যেকটি থেকে তোমরা কোমল মাংস খাও, এবং পরিধানের অলঙ্কার আহরণ করো। এবং তোমরা জাহাজগুলোকে দেখো এগুলোর মাঝে চলাচল করে, তাঁর জীবিকা অন্বেষ্ণণে, যাতে তোমরা কৃতজ্ঞ হতে পারো।"],
  "35:13": ["Allah makes the night enter into the day and makes the day enter into the night, and subjected the sun and the moon, each running for an appointed term. That is Allah, your Rabb; to Allah belongs the kingdom. And those whom you call upon besides Allah possess not even a speck.", "তিনি রাতকে দিনের মধ্যে মিলিয়ে দেন, এবং দিনকে রাতের মধ্যে মিলিয়ে দেন। তিনি সূর্য ও চাঁদকে একটি পূর্বনির্ধারিত সময়কালের জন্য চলতে নিয়োজিত করেছেন। এমনই আল্লাহ তোমাদের প্রভু; সকল রাজত্ব তাঁর। তাঁর পাশে যে উপাস্যই তোমরা স্থাপন করো না কেন তারা একটি বীজেরও মালিক না।"],
  "35:14": ["If you call them, they do not hear your call; and if they heard, they would not answer you. And on the Day of Resurrection they will disown your partnership, and none informs you like the All-Aware.", "যদি তোমরা তাদেরকে ডাকো, তারা শুনতে পারে না। এমনকি যদি তারা তোমাদের ডাক শোনেও, তারা তোমারদের ডাকে সাড়া দিতে পারে না।পুনরুত্থান দিনে, তারা তোমাদের প্রত্যাখ্যান করবে। পরম সর্বজ্ঞের মতো কেউ তোমাকে অবহিত করতে পারবে না।"],
  "35:15": ["O people, you are the needy toward Allah, and Allah is the Self-Sufficient, the Praiseworthy.", "হে মানুষ, তোমাদেরই আল্লাহকে প্রয়োজন, যখন আল্লাহর কাউকে কোন প্রয়োজন নেই, পরম প্রশংসনীয়।"],
  "35:16": ["If Allah wills, Allah does away with you and brings a new creation.", "তিনি যদি চান, তিনি তোমাদের সরিয়ে দিতে পারেন এবং পরিবর্তে নতুন সৃষ্টি করতে পারেন।"],
  "35:17": ["And that is not hard upon Allah.", "এটা আল্লাহর জন্য খুব কঠিন নয়।"],
  "35:18": ["And no laden soul bears the load of another; and if one burdened with weight calls another to carry it, nothing of it is carried, even if he is a close relative. You only warn those who revere their Rabb unseen and establish the prayer; and whoever purifies only purifies for his own soul; and to Allah is the arrival.", "কোন আত্মা অন্য আত্মার পাপ বহন করতে পারে না। যদি কোন পাপ ভারাক্রান্ত আত্মা অন্যকাউকে তার ভার বহন করার জন্য ডাকে, অন্যকোন আত্মা এর কোন অংশ বহন করতে পারবে না, এমনকি যদি তারা আত্মীয়ও হয়। একমাত্র সেসব লোকেরাই তোমার সতর্কবার্তায় মনোযোগ দেবে যারা তাদের প্রভুকে ভক্তি করে, এমনকি তাদের একাকীত্বেও; এবং সংযোগ প্রার্থনা (সালাত) পালন করে। যেকেউ তার আত্মাকে পরিশুদ্ধ করে, সে তার নিজের ভালোর জন্য তা করে। আল্লাহর কাছেই চূড়ান্ত নিয়তি।"],
  "35:19": ["And the blind and the seeing are not equal,", "অন্ধ এবং চক্ষুষ্মান সমান নয়।"],
  "35:20": ["nor are darkness and light,", "আর না অন্ধকার এবং আলো।"],
  "35:21": ["nor shade and scorching heat.", "না ছায়ার শীতলতা আর সূর্যের তাপ।"],
  "35:22": ["And not equal are the living and the dead. Indeed Allah hears whomever Allah wills, and you cannot make hear those in the graves.", "না জীবিত এবং মৃত; আল্লাহ যাকে ইচ্ছা শুনান। যারা কবরে আছে তাদেরকে তুমি শুনাতে পারো না।"],
  "35:23": ["You are only a warner.", "তুমি একজন সতর্ককারীর চেয়ে বেশি কিছু নও।"],
  "35:24": ["We sent you with the truth, as a bearer of glad tidings and a warner; and there is no nation but a warner has passed on among them.", "আমরা তোমাকে পাঠিয়েছি সত্য সহকারে, একজন সুসংবাদ বহনকারী, সেই সাথে সতর্ককারী হিসেবে। প্রত্যেক জনপদ অবশ্যই একজন সতর্ককারী পাবে।"],
  "35:25": ["And if they deny you, those before them denied; their rusul came to them with clear proofs, and scriptures, and the enlightening Book.", "যদি তারা তোমাকে অবিশ্বাস করে, তাদের পূর্বে যারা ছিল তারাও অবিশ্বাস করেছিল। তাদের বার্তাবাহকেরা তাদের কাছে স্পষ্ট প্রমান, এবং জবুর ও জ্ঞানালোকপূর্ণ ঐশীগ্রন্থ সহ গিয়েছিল,"],
  "35:26": ["Then those who kafara were seized — and how was the rejection!", "পরবর্তীতে, আমি তাদেরকে শাস্তি দিয়েছিলাম যারা অবিশ্বাস করেছিল; কত ভয়ানক ছিল আমার শাস্তি!"],
  "35:27": ["Have you not seen that Allah sends down water from the sky, and We bring forth with it fruits of differing colors? And from the mountains, fresh tracts white and red, of differing colors, and dusky black.", "তোমরা কি উপলব্ধি করো না যে আল্লাহ আকাশ থেকে পানি বর্ষন করেণ, যা দ্বারা আমরা বিভিন্ন রঙের ফল উৎপন্ন করি? এমনকি পাহাড়গুলোর রয়েছে বিভিন্ন রঙ; চূড়াগুলো সাদা, অথবা লাল, অথবা অন্য কোন রঙের। এবং দাঁড় কাকগুলো কালো।"],
  "35:28": ["And among people, and creatures, and livestock, likewise of differing colors. Only those among Allah's servants who have knowledge revere Allah; indeed Allah is mighty, forgiving.", "এছাড়াও, লোকেরা, প্রানীরা এবং পালিত পশুরা বিভিন্ন রঙের হয়। এ জন্যই আল্লাহকে সত্যিকারভাবে ভক্তি করে সেসব লোকেরা যারা জ্ঞানী। আল্লাহ সর্বশক্তিমান, ক্ষমাশীল।"],
  "35:29": ["Indeed those who recite the Book of Allah, establish the prayer, and spend of what We provided them, secretly and openly, hope for a trade that will never perish.", "নিশ্চয়, যারা আল্লাহর গ্রন্থ আবৃতি করে, সংযোগ প্রার্থনা (সালাত) পালন করে, এবং আমাদের জীবিকা থেকে তারা ব্যয় করে- গোপনে ও প্রকাশ্যে- তারা জড়িত রয়েছে একটি বিনিয়োগে যাতে কখনই লোকসান হয় না।"],
  "35:30": ["To pay them their rewards in full and increase them from Allah's bounty; indeed Allah is forgiving, thankful.", "তিনি তাদেরকে উদারভাবে প্রতিদান দেবেন, এবং তাদের প্রতি তাঁর অনুগ্রহ বহুগুনে বাড়িয়ে দেবেন। তিনি ক্ষমাশীল, গুণগ্রাহী।"],
  "35:31": ["And what We revealed to you of the Book is the truth, confirming what is before it; indeed Allah is ever well-aware, all-seeing of Allah's servants.", "এই ঐশীগ্রন্থে যা আমরা তোমার কাছে প্রকাশ করেছি তা সত্য, যা পূর্ববর্তী সকল ঐশীগ্রন্থকে পূর্ণতা দেয়। আল্লাহ তাঁর বান্দাদের ব্যাপারে পূর্ণ অবগত, দ্রষ্টা।"],
  "35:32": ["Then We bequeathed the Book to those We chose from Our servants; among them is one who wrongs himself, and among them one who takes the middle course, and among them a forerunner in good deeds by Allah's leave. That is the great bounty.", "আমরা প্রজন্ম থেকে প্রজন্মে ঐশীগ্রন্থ পৌঁছিয়েছি, এবং আমাদের বান্দাদের মধ্যে যাদেরকে আমরা পছন্দ করেছি তাদেরকে এটি গ্রহন করার অনুমতি দিয়েছি। পরবর্তীতে, তাদের কেউ কেউ নিজেদের আত্মার প্রতি অন্যায় করেছিল, অন্যরা শুধু কিছুকালের জন্য একে সমর্থন করেছিল, যেখানে অন্যরা আল্লাহর ইচ্ছানুসারে সৎকর্ম করতে উৎসাহী ছিল, এটাই মহা বিজয়।"],
  "35:33": ["Gardens of Eden they enter, adorned in them with bracelets of gold and pearls; and their garments therein are silk.", "তারা ইডেনের বাগানগুলোয় প্রবেশ করবে, যেখানে তাদেরকে সোনা ও মুক্তার কাঁকন দিয়ে সাজানো হবে, এবং সেখানে তাদের পোশাক হবে রেশমের তৈরি।"],
  "35:34": ["They say: praise belongs to Allah, who removed from us sorrow; indeed our Rabb is forgiving, thankful.", "তারা বলবে, “প্রশংসা আল্লাহর আমাদের সকল উদ্বেগ দূর করে দেয়ার জন্য। আমাদের প্রভু ক্ষমাশীল, গুণগ্রাহী।"],
  "35:35": ["Who settled us, by Allah's bounty, in the abode of residence; no toil touches us therein, and no weariness touches us therein.", "“তিনি আমাদেরকে অনন্ত সুখের আবাসে প্রবেশ করিয়েছেন, তাঁর অনুগ্রহে। আমরা কখনই এখানে একঘেয়ে হই না, না কখনো আমরা ক্লান্ত হই।"],
  "35:36": ["And those who disbelieve, for them is the fire of Hell: it is not decreed for them that they die, nor is anything of its punishment lightened for them. Thus We repay every kafir.", "তাদের ক্ষেত্রে যারা অবিশ্বাস করে, তারা টেনে এনেছে নরকের আগুন, যেখানে তারা কখনো মৃত্যুর মাধ্যমে শেষ হয় না, না শাস্তি তাদের জন্য কখনো লাঘব করা হয়। আমরা এভাবে অকৃতজ্ঞদের প্রতিফল দেই।"],
  "35:37": ["They cry out in it: our Rabb, take us out; we will do salihness, other than what we used to do. Did We not grant you a life long enough for whoever would remember to remember? And the warner came to you. So taste — and the wrongdoers have no helper.", "তারা সেখানে চিৎকার করবে, “আমাদের প্রভু, যদি আপনি এখান থেকে আমাদের বের করেন, আমরা সৎ কাজ করবো, যেসব কাজ আমরা করতাম তার পরিবর্তে”। আমরা কি তোমাদেরকে দীর্ঘ -জীবন দেইনি, সাথে অনবরত সতর্ক বার্তা তাদের জন্য যারা মনোযোগ দিতো? তোমরা কি সতর্ককারী পাওনি? অতএব, (পরিনাম) আস্বাদন করো। তাদেরকে সাহায্য করার জন্য সীমালঙ্ঘনকারীদের কেউ থাকবে না।"],
  "35:38": ["Indeed Allah knows the unseen of the heavens and the earth; indeed Allah is knowing of what the breasts hide.", "আল্লাহ আকাশমণ্ডলী এবং পৃথিবীর ভবিষ্যৎ সম্পর্কে অবগত।  তিনি সকল গভীরতম চিন্তা সম্পর্কে অবগত।"],
  "35:39": ["It is Allah who made you successors upon the earth; whoever disbelieves, his disbelief is upon him, and their disbelief increases the kafirin nothing with their Rabb but loathing, and their disbelief increases them nothing but loss.", "তিনি সেই সত্তা যিনি তোমাদেরকে পৃথিবীর উত্তরাধিকারী করেছেন। পরবর্তীতে, যেকেউ অবিশ্বাস করাকে পছন্দ করেছে তা তার নিজের ক্ষতির জন্য করেছে। অবিশ্বাসীদের অবিশ্বাস কেবল তাদের প্রতি তাদের প্রভুর ঘৃণাই বৃদ্ধি করে। অবিশ্বাসীদের অবিশ্বাস তাদেরকে ক্ষতির গভীরে নিমজ্জিত করে।"],
  "35:40": ["Say: have you seen your associates whom you call upon besides Allah? Show me what they created of the earth, or do they have a share in the heavens? Or did We give them a scripture, so that they stand upon clear proof from it? No — the wrongdoers promise one another nothing but deception.", "বল, “আল্লাহর পাশে তোমাদের স্থাপন করা উপাস্যদের বিষয়ে ভেবে দেখো; আমাকে দেখাও পৃথিবীতে তারা কি সৃষ্টি করেছে?” তাদের কি কোন অংশীদারিত্ব রয়েছে আকাশমণ্ডলীতে? আমরা কি তাদেরকে কোন গ্রন্থ দিয়েছি যাতে কোন সন্দেহ নেই? নিশ্চয়, যা সীমালঙ্ঘনকারীরা পরস্পরকে অঙ্গীকার করে তা এক  বিভ্রমের চেয়ে বেশি কিছু নয়।"],
  "35:41": ["Indeed Allah holds the heavens and the earth so they do not vanish; and if they were to vanish, none could hold them after Allah. Indeed Allah is ever forbearing, forgiving.", "আল্লাহ সেই সত্তা যিনি আকাশমণ্ডলী ও পৃথিবীকে ধরে আছেন, অন্যথায় সেগুলো মিলিয়ে যেতো। যদি অন্যকাউকে সেগুলো ধরতে হয়, সেগুলো অবশ্যই মিলিয়ে যাবে। আল্লাহ সহিষূ, ক্ষমাশীল।"],
  "35:42": ["They swore by Allah their utmost oaths: if a warner comes to them, they will surely be more rightly guided than any of the nations. But when the warner came to them, he increased them only in aversion.", "তারা ঈশরের নামে জোড়ালো শপথ করতো যে যদি কোন সতর্ককারী তাদের কাছে আসতো, তারা একটি নির্দিষ্ট জনপদ থেকে উত্তম পথপ্রাপ্ত হতো! কিন্তু, এখন যখন সতর্ককারী তাদের কাছে আসলো, এটি শুধু তাদেরকে আরো গভীর বিমুখতায় নিমজ্জিত করলো।"],
  "35:43": ["Out of arrogance in the land and evil scheming; and evil scheming encircles none but its own people. So do they look for anything but the way of the former ones? You will find no change in Allah's way, and no turning of Allah's way.", "তারা পৃথিবীতে ঔদ্ধত্য, এবং মন্দ ষড়যন্ত্র  অবলম্বন করেছিল, আর মন্দ ষড়যন্ত্র উল্টো তাদের উপরই এসে পড়ে যারা সেগুলোর পরিকল্পনা করে। তবে কি ওদের উচিত তাদের ভাগ্য ছাড়া অন্যকিছু আশা করা যারা অতীতে একই জিনিস করেছিলো? তুমি দেখবে যে আল্লাহর নিয়ম কখনই পরিবর্তনশীল নয়; তুমি দেখবে যে আল্লাহর নিয়ম অপরিবর্তনীয়।"],
  "35:44": ["Have they not journeyed in the land to see how the end was of those before them, though they were stronger than them in strength? And nothing in the heavens or the earth can render Allah powerless; indeed Allah is ever knowing, powerful.", "তারা কি পৃথিবীতে ঘোরেনি এবং তাদের পূর্বে যারা ছিল তাদের পরিনাম লক্ষ্য করেনি? তারা এমনকি তাদের থেকে অধিক শক্তিশালী ছিল। আকাশমণ্ডলীতে কোনোকিছুই আল্লাহ থেকে গোপন থাকতে পারে না, না পৃথিবীতে। তিনি সর্বজ্ঞ, সর্বশক্তিমান।"],
  "35:45": ["If Allah were to seize people for what they earn, Allah would not leave upon its surface any creature; but Allah postpones them to an appointed term. And when their term comes, indeed Allah is ever seeing of Allah's servants.", "যদি আল্লাহ মানুষকে তাদের পাপের জন্য শাস্তি দিতেন, তিনি পৃথিবীতে একটি সৃষ্টিকেও ছাড়তেন না। কিন্তু তিনি তাদেরকে এক পূর্বনির্ধারিত মেয়াদকাল পর্যন্ত অবকাশ দেন। একবার তাদের মেয়াদকাল সম্পূর্ণ হয়ে গেলে, তখন আল্লাহ তাঁর বান্দাদের দ্রষ্টা।"],
  "36:1": ["Ya Sin", "য়. শ. (ইয়া, সিন)"],
  "36:2": ["By the Wise Quran", "এবং কুরআন যা প্রজ্ঞায় পরিপূর্ণ।"],
  "36:3": ["You are indeed one of the Rasuls", "অবশ্যই, তুমি (রাশাদ) বার্তাবাহকদের একজন।"],
  "36:4": ["Upon a straight path", "এক সরল পথের উপর।"],
  "36:5": ["It is sent down by the Almighty, the Raheem", "এই প্রকাশনা সর্বশক্তিমান, পরম দয়ালুর পক্ষ থেকে।"],
  "36:6": ["To warn a people whose forefathers were never warned, and so they are unmindful", "সে লোকদের সতর্ক করতে যাদের পিতামাতাদেরকে কখনো সতর্ক করা হয়নি, আর সেজন্য, তারা অসচেতন।"],
  "36:7": ["The word has already proven true against most of them, yet they do not believe", "এটা পূর্ব-নির্ধারিত যে তাদের বেশির ভাগ বিশ্বাস করে না।"],
  "36:8": ["We have placed fetters around their necks, and they reach up to their chins, so they cannot raise their heads", "কারন আমরা তাদের ঘাড়ে শৃঙ্খল পড়াই, তাদের চিবুক পর্যন্ত। ফলস্বরুপ, তারা তাদের অবিশ্বাসে আবদ্ধ হয়ে যায়।"],
  "36:9": ["And We placed a barrier in front of them and a barrier behind them, and We covered them over, so they cannot see", "এবং আমরা তাদের সামনে একটি অন্তরায়, এবং তাদের পেছনে একটি অন্তরায় রাখি, আর এভাবে, আমরা তাদের পর্দাবৃত করি; তারা দেখতে পারে না।"],
  "36:10": ["And it is all the same to them whether you warn them or do not warn them — they will not believe", "তুমি তাদেরকে সতর্ক কর অথবা না কর উভয় তাদের জন্য সমান, তারা বিশ্বাস করতে পারে না।"],
  "36:11": ["You can only warn the one who follows the reminder and stands in awe of the Rahman in the unseen; so give him good news of forgiveness and a noble reward", "তোমার কথায় কেবল তারাই মনোযোগ দেবে যারা এই বার্তা মেনে চলে, এবং পরম করুণাময়কে ভক্তি করে- এমনকি তাদের একাকীত্বেও। তাদেরকে ক্ষমা এবং এক মহা প্রতিদানের সুসংবাদ দাও।"],
  "36:12": ["It is We who bring the dead to life and record what they send ahead and their tracks, and everything We have counted is in a clear record", "আমরা অবশ্যই মৃতকে পুনরুজ্জীবিত করবো, এবং আমরা সবকিছু নথিভুক্ত করেছি যা তারা এই জীবনে করেছে, সেই সাথে তার পরিণাম যা তাদের মৃত্যুর পরেও চলে। সবকিছু আমরা একটি সুস্পষ্ট নথিতে গুনে রেখেছি।"],
  "36:13": ["And set forth for them a parable: the people of the town, when the Rasuls came to them", "তাদের জন্য এক জনপদের লোকদের উদাহরণ বর্ণনা কর যারা বার্তাবাহকদের পেয়েছিল।"],
  "36:14": ["When We sent two to them and they denied them both, so We strengthened them with a third, and they said, \"We are MuRasul to you\"", "যখন আমরা তাদের কাছে দুই জন (বার্তাবাহক) পাঠালাম, তারা তাদের অবিশ্বাস করল। আমরা তখন তৃতীয় জনের দ্বারা তাদের সমর্থন করলাম। তারা বলল, “আমরা তোমাদের কাছে (আল্লাহর) বার্তাবাহক”।"],
  "36:15": ["They said, \"You are nothing but humans like us, and the Rahman has sent down nothing; you are only lying\"", "তারা বলল, “তোমরা তো আমাদের মত মানুষের চেয়ে বেশি কিছু নও। পরম করুণাময় কোন কিছু অবতীর্ণ করেননি। তোমরা মিথ্যাবাদী।\""],
  "36:16": ["They said, \"Our Rabb knows that we are truly rusul to you\"", "তারা বলল, “আমাদের প্রভু জানেন যে আমাদেরকে তোমাদের কাছে পাঠানো হয়েছে।"],
  "36:17": ["And nothing is upon us but the clear delivery", "আমাদের একমাত্র উদ্দেশ্য বার্তা পৌঁছে দেওয়া।\""],
  "36:18": ["They said, \"We take you as a bad omen; if you do not stop, we will stone you, and a painful punishment from us will touch you\"", "তারা বলল, “আমরা তোমাদেরকে অমঙ্গলের কারন মনে করি। যদি তোমরা বিরত না হও, আমরা অবশ্যই তোমাদের পাথর মারব, অথবা যন্ত্রণাদায়ক শাস্তি ভোগ করাবো।\""],
  "36:19": ["They said, \"Your bad omen rests with you — is it because you are reminded? No, you are a people who exceed all bounds\"", "তারা বলল, “তোমাদের মঙ্গল-অমঙ্গল তোমাদের সাড়াদানের উপর নির্ভর করে, যেহেতু এখন তোমাদেরকে স্মরণ করিয়ে দেয়া হয়েছে। নিশ্চয়, তোমরা সীমালঙ্ঘনকারী লোক।\""],
  "36:20": ["And from the far end of the town came a man, hastening; he said, \"O my people, follow the Rasuls\"", "একজন লোক শহরের অন্য প্রান্ত থেকে আসলো, বলার জন্য যে, “হে আমার লোকেরা, বার্তাবাহকদের অনুসরন করো।\""],
  "36:21": ["Follow those who ask you for no reward, and who are rightly guided", "“তাদের অনুসরন করো যারা তোমাদের কাছে কোন পারিশ্রমিক চায় না, এবং সুপথপ্রাপ্ত।"],
  "36:22": ["And why should I not worship the One who originated me, when to Allah you will all be returned", "“কেন আমি সেই সত্তার উপাসনা করবো না যিনি আমার সুচনা করেছেন এবং তাঁর দিকেই তোমাদের চূড়ান্ত প্রত্যাবর্তন।"],
  "36:23": ["Shall I take other alihah besides Allah? If the Rahman wills harm for me, their intercession cannot avail me at all, nor can they rescue me", "“তাঁর পাশে আমি কি উপাস্য স্থাপন করবো? যদি পরম করুণাময় আমার জন্য কোন ক্ষতি চান, তাদের সুপারিশ আমাকে সামান্যতম সাহায্যও করতে পারবে না, না তারা আমাকে উদ্ধার করতে পারবে।"],
  "36:24": ["Then I would indeed be in clear error", "“সেক্ষেত্রে, আমি সম্পূর্ণ পথভ্রষ্ট হব।"],
  "36:25": ["I have believed in your Rabb — so listen", "“আমি তোমাদের প্রভুকে বিশ্বাস করেছি; দয়া করে আমার কথা শোন।\""],
  "36:26": ["It was said, \"Enter the Garden.\" He said, \"If only my people knew", "(তার মৃত্যুর সময়) তাকে বলা হল, “স্বর্গে প্রবেশ করো”। সে বলল, “আহা। আমার লোকেরা যদি জানতো।\""],
  "36:27": ["how my Rabb forgave me and made me one of the honored ones\"", "“যে আমার প্রভু আমাকে ক্ষমা করেছেন, এবং আমাকে সন্মানিত করেছেন।\""],
  "36:28": ["And We sent down upon his people after him no host from the sky, nor had We any need to send one down", "তার পর আমরা তার লোকদের উপর আকাশ থেকে কোন সৈন্যবাহিনী অবতীর্ণ করিনি; তাদের অবতীর্ণ করার কোন প্রয়োজন আমাদের ছিল না।"],
  "36:29": ["It was but a single shout, and at once they were stilled", "এটা কেবল ছিল একটি বিকট শব্দ, যার ফলে তারা স্তব্ধ হয়ে গেল।"],
  "36:30": ["Oh, the regret for the servants! No Rasul comes to them without their mocking him", "কতটা দুঃখজনক লোকদের অবস্থা! যখনই কোন বার্তাবাহক তাদের কাছে গিয়েছে, তারা সবসময় তাকে উপহাস করেছে।"],
  "36:31": ["Do they not see how many generations We destroyed before them? They do not return to them", "তারা কি দেখেনি যে তাদের আগে কত প্রজন্মকে আমরা ধ্বংস করেছি, এবং তারা কখনই তাদের কাছে ফিরে আসে না?"],
  "36:32": ["And surely all of them, all together, will be brought before Us, present", "তাদের প্রত্যেককেই আমাদের সামনে তলব করা হবে।"],
  "36:33": ["And a sign for them is the dead earth: We gave it life and brought grain out of it, and from it they eat", "তাদের জন্য একটি নিদর্শন হলো মৃত ভুমিঃ আমরা একে পুনর্জীবিত করি এবং তাদের খাদ্যের জন্য তা থেকে শস্য উৎপাদন করি।"],
  "36:34": ["And We placed in it gardens of palms and grapes, and We made springs burst forth in it", "আমরা এতে উৎপাদন করি খেজুর ও আঙ্গুরের বাগান, এবং এর মধ্যে আমরা ঝর্ণাধারা উৎসারিত করি।"],
  "36:35": ["So that they may eat of its fruit, which their hands did not make — will they not then give thanks", "তাদেরকে ফল-ফলাদি প্রদান করার জন্য, এবং তাদের নিজেদের হাতে উৎপন্ন করতে দেয়ার জন্য যা কিছু তাদের প্রয়োজন। তারা কি কৃতজ্ঞ হবে?"],
  "36:36": ["Glory be to the One who created all the pairs — from what the earth grows, and from themselves, and from what they do not know", "মহিমা সে সত্তার যিনি পৃথিবীতে সকল প্রকার গাছপালা সৃষ্টি করেছেন, আর তাদেরকেও, এবং অন্যান্য সৃষ্টিকূল যা তারা এমনকি জানেও না।"],
  "36:37": ["And a sign for them is the night: We strip the day from it, and at once they are in darkness", "তাদের জন্য আরেকটি নিদর্শন হলো রাতঃ সেখান থেকে আমরা দিনের আলো দূর করি, যার ফলে তারা অন্ধকারাচ্ছন্ন হয়।"],
  "36:38": ["And the sun runs to its settling place; that is the decree of the Almighty, the Knowing", "সূর্য একটি নির্দিষ্ট অবস্থানে অস্ত যায়, সর্বশক্তিমান, সর্বজ্ঞের নকশা অনুসারে।"],
  "36:39": ["And the moon — We decreed for it stations, until it returns like an old, withered stalk", "আমরা চাঁদকে পর্যায়সমূহে দৃশ্যমান হবার জন্য নকশা করেছি, যতক্ষণ না এটি একটি পুরাতন বাঁকা আবরনের মত হয়ে যায়।"],
  "36:40": ["It is not for the sun to overtake the moon, nor does the night race ahead of the day; and each swims in an orbit", "সূর্য কখনো চাঁদকে ধরতে পারে না- রাত এবং দিন কখনো বিচ্যুত হয় না-তাদের প্রত্যেকে এর নিজের কক্ষপথে ভাসছে।"],
  "36:41": ["And a sign for them is that We carried their offspring in the laden ship", "তাদের জন্য আরেকটি নিদর্শন হলো যে তাদের  পূর্বপুরুষদের আমরা বোঝাই নৌযানে আরোহণ করিয়েছি।"],
  "36:42": ["And We created for them the like of it, which they ride", "অতঃপর তাদের আরোহণ করার জন্যও একই রকম সৃষ্টি করেছি।"],
  "36:43": ["And if We will, We drown them, and there is none to answer their cry, nor are they rescued", "আমরা যদি চাইতাম, আমরা তাদের ডুবিয়ে দিতে পারতাম, যাতে করে তাদের চিৎকার না শোনা যায়, না তারা রক্ষা পেতে পারে।"],
  "36:44": ["Except as a mercy from Us, and enjoyment for a while", "উপরন্তু, আমরা তাদের উপর করুনা বর্ষণ করেছি, এবং কিছু সময়ের জন্য তাদেরকে উপভোগ করতে দিয়েছি।"],
  "36:45": ["And when it is said to them, \"Guard against what lies before you and behind you, so that you may be shown mercy\"", "তা সত্ত্বেও, যখন তাদের বলা হয়, “তোমাদের অতীত থেকে শিক্ষা নিয়ে তোমাদের ভবিষ্যতে সৎকর্ম করো, যাতে তোমরা দয়া পেতে পারো,”"],
  "36:46": ["not a sign of their Rabb's signs comes to them without their turning away from it", "তাদেরকে যে প্রমাণই তাদের প্রভুর পক্ষ থেকে দেয়া হোক না কেন, তারা তা অনবরত উপেক্ষা করে।"],
  "36:47": ["and when it is said to them, \"Spend of what Allah has provided you,\" those who disbelieve say to those who believe, \"Are we to feed those whom Allah, if Allah willed, would feed? You are only in clear error\"", "যখন তাদের বলা হয়, “তোমাদেরকে আল্লাহর দেয়া জীবিকা থেকে দাও, যারা অবিশ্বাস করে তারা তাদেরকে বলে যারা বিশ্বাস করে, “কেন আমরা তাদেরকে দিতে যাবো যাদেরকে আল্লাহ খাওয়াতে পারেন, যদি তিনি তা চান? তোমরা প্রকৃতই বহুদূর পথভ্রষ্ট।”"],
  "36:48": ["And they say, \"When is this promise, if you are sadiq\"", "তারা আরো চ্যালেঞ্জ করে, “কখন সেই অঙ্গিকার পূর্ণ হবে, যদি তোমরা সত্যবাদী হও?”"],
  "36:49": ["They await nothing but a single blast that seizes them while they are contending", "তারা কেবল দেখবে ভয়াবহ শব্দ যা তাদের আচ্ছন্ন করবে, যখন তারা বিবাদ করে।"],
  "36:50": ["Then they cannot make a bequest, nor do they return to their families", "এমনকি অছিয়তনামা করারও কোন সময় তাদের থাকবে না, না তারা তাদের লোকদের কাছে ফিরে যেতে সমর্থ হবে।"],
  "36:51": ["And the blast is blown, and at once from the graves to their Rabb they come pouring forth", "শিঙ্গায় ফুঁ দেওয়া হবে, যার ফলে তারা কবর থেকে জেগে উঠবে এবং তাদের প্রভুর কাছে যাবে।"],
  "36:52": ["They say, \"Woe to us! Who has raised us from our resting place? This is what the Rahman promised, and the Rasuls spoke the truth\"", "তারা বলবে, “কতই না দুঃখ আমাদের। কে আমাদেরকে পুনরুত্থিত করলো আমাদের মৃত্যু থেকে? এটাই তো পরম করুণাময় অঙ্গিকার করেছিলেন। বার্তাবাহকরা ঠিক ছিল।”"],
  "36:53": ["It was but a single blast, and at once they are all brought before Us, present", "শুধুমাত্র একটি বিকট শব্দ হবে, যার ফলে তাদেরকে আমাদের সামনে একত্রিত করা হবে।"],
  "36:54": ["So today no soul is wronged in anything, and you are requited only for what you used to do", "সেই দিন, কোন আত্মার প্রতি সামান্যতম অন্যায় করা হবে না। তোমরা যাকিছু করেছিলে ঠিক তার জন্যই প্রতিদান পাবে।"],
  "36:55": ["Indeed, the companions of the Garden are this day busy with delight", "সেদিন, স্বর্গের বাসিন্দারা সানন্দে ব্যাস্ত থাকবে।"],
  "36:56": ["They and their spouses, in shade upon the couches, reclining", "তারা তাদের সঙ্গিদের সাথে চমৎকার ছায়ায় বাস করে, উপভোগ করে আরামদায়ক আসবাবপত্র।"],
  "36:57": ["They have therein fruits, and whatever they call for is theirs", "সেখানে তাদের থাকবে ফল-ফলাদি, তারা যা চায় সবকিছু পাবে।"],
  "36:58": ["\"Peace\" — a word from a Raheem Rabb", "পরম করুণাময় প্রভুর পক্ষ থেকে শান্তির অভিবাদন।"],
  "36:59": ["\"And stand apart today, O mujrimin\"", "আর তোমাদের ক্ষেত্রে, হে অপরাধীরা, তোমাদেরকে আলাদা রাখা হবে।"],
  "36:60": ["\"Did I not charge you, O children of Adam, not to worship Shaytan? Truly, Shaytan is a clear enemy to you\"", "আমি কি তোমাদের থেকে অঙ্গিকার নেইনি, হে আদম সন্তানেরা, যে, তোমরা শয়তানের উপাসনা করবে না? কেননা, সে তোমাদের ঘোরতম শত্রু?"],
  "36:61": ["\"And that you should serve Me — this is the straight path\"", "এবং যে তোমরা কেবল আমার উপাসনা করবে? এটাই সঠিক পথ।"],
  "36:62": ["\"Yet Shaytan has surely led a great multitude of you astray. Did you not understand\"", "সে তোমাদের বহু সংখ্যককে পথভ্রষ্ট করেছে। তোমাদের কি কোন বুঝার ক্ষমতা নেই ?"],
  "36:63": ["\"This is the Hell you were promised\"", "এটা সেই নরক তোমাদেরকে যার প্রতিশ্রুতি দেয়া হয়েছিল।"],
  "36:64": ["\"Enter it today, because of what you used to disbelieve\"", "আজ তোমরা এতে পুড়বে, তোমাদের অবিশ্বাসের ফলস্বরূপ।"],
  "36:65": ["Today We seal their mouths, and their hands speak to Us, and their feet testify to what they used to earn", "সে দিন আমরা তাদের মুখে মোহর এঁটে দেব তালা দেব; তাদের হাত ও পা সবকিছুর সাক্ষী দেবে যা তারা করেছিল।"],
  "36:66": ["And if We willed, We would blot out their eyes; then they would race along the path — but how could they see", "যদি আমরা চাই, আমরা তাদের চোখ পর্দাবৃত করতে পারি এবং, পরিনামে, যখন তারা পথ খুঁজবে, তারা দেখবে না।"],
  "36:67": ["And if We willed, We would transform them where they are, so they could not move on nor return", "যদি আমরা চাই, আমরা সেখানেই তাদেরকে স্থির করে দিতে পারি; ফলে, না তারা সামনে এগোতে পারে, না পিছনে যেতে পারে।"],
  "36:68": ["And whomever We grant a long life, We turn back in creation. Will they not understand", "যাকেই আমরা দীর্ঘ জীবন দেই, তাকে আমরা দুর্বলতায় ফিরিয়ে নেই। তারা কি বোঝে না?"],
  "36:69": ["We did not teach him poetry, nor does it befit him; it is only a reminder and a clear Quran", "যা আমরা তাকে (বার্তাবাহককে) শিখিয়েছিলাম তা কবিতা ছিল না, না সে (একজন কবি)। এটা তো এক অকাট্য প্রমান, এবং জ্ঞানগর্ভ কুরআন।"],
  "36:70": ["To warn whoever is alive, and so that the word may prove true against the kafirin", "তাদের কাছে প্রচার করতে যারা জীবিত, এবং অবিশ্বাসীদের প্রকাশ করতে।"],
  "36:71": ["Have they not seen that We created for them, by the work of Our hands, cattle, and they are their masters", "তারা কি দেখেনি যে আমরা তাদের জন্য সৃষ্টি করেছি, আমাদের নিজেদের হাতে, পালিত পশু, তারা যেগুলোর মালিক?"],
  "36:72": ["And We subdued them for them; from them come their mounts, and from them they eat", "এবং আমরা সেগুলোকে তাদের জন্য বশীভূত করে দিয়েছি; কতকগুলোর উপর তারা আরোহণ করে,  আর কতকগুলো তারা খায়।"],
  "36:73": ["And they have in them benefits and drink. Will they not give thanks", "তারা সেগুলো  থেকে অন্য সুবিধা পায়, সেইসাথে পানীয়। তারা কি কৃতজ্ঞ হবে না?"],
  "36:74": ["And they have taken alihah besides Allah, so that they might help them", "তারা আল্লাহর পাশে অন্য উপাস্য স্থাপন করে, হয়তো তারা তাদেরকে সাহায্য করতে পারবে!"],
  "36:75": ["They cannot help them, and they themselves are a host brought before them", "পক্ষান্তরে, তারা তাদের সাহায্য করতে পারে না; তারা শেষপর্যন্ত তাদের প্রতি নিবেদিত সৈন্য হিসেবে কাজ করতে থাকে।"],
  "36:76": ["So let not their words grieve you; We know what they hide and what they make open", "অতএব, তাদের কথায় দুঃখিত হইও না। আমরা সম্পূর্ণ অবগত সেসব কিছুর ব্যাপারে যা তারা গোপন করে এবং সবকিছু যা তারা প্রকাশ করে।"],
  "36:77": ["Has man not seen that We created him from a drop — and then he is an open contender", "মানুষ কি দেখে না যে আমরা তাকে একটি ক্ষুদ্র ফোঁটা থেকে সৃষ্টি করেছি, এরপর সে ঘোর শত্রুতে পরিণত হয়?"],
  "36:78": ["And he sets forth a parable for Us, having forgotten his own creation; he says, \"Who will give life to the bones when they are decayed\"", "সে আমাদের কাছে প্রশ্ন উত্থাপন করে- যখন ভুলে যায় তার প্রথম সৃষ্টিকে- “কে হাড়গুলো পুনরূজ্জীবিত করতে পারে সেগুলো পচেঁ যাবার পর?”"],
  "36:79": ["Say: \"The One who originated them the first time will give them life, and Allah is knowing of every creation\"", "বল, “সে সত্তা তাদেরকে পুনরুত্থিত করবেন যিনি প্রথম বার তাদের সূচনা করেছিলেন। তিনি সকল সৃষ্টি সম্পর্কে পূর্ণ অবগত”।"],
  "36:80": ["the One who made for you from the green tree a fire, and at once you kindle from it", "তিনি সে সত্তা যিনি তোমাদের জন্য সৃষ্টি করেছেন, সবুজ গাছপালা থেকে, জ্বালানী যা তোমরা আলোর জন্য পোড়াও।"],
  "36:81": ["Is the One who created the heavens and the earth not able to create the like of them? Yes — and Allah is the Creator, the Knowing", "যে সত্তা আকাশমণ্ডলী এবং পৃথিবী সৃষ্টি করেছেন তিনি কি একই জিনিস পুনরায় সৃষ্টি করতে সক্ষম নন? হ্যা নিশ্চয়; তিনি সৃষ্টিকর্তা, সর্বজ্ঞ।"],
  "36:82": ["Allah's command, when Allah wills a thing, is only to say to it, \"Be,\" and it is", "কোন আদেশ সম্পন্ন করার জন্য এটিকে শুধু তাঁর বলতে হয়, “হও”আর তা হয়ে যায়।"],
  "36:83": ["So glory be to the One in whose hand is the dominion of all things, and to whom you will be returned", "অতএব, মহিমা সে সত্তার যার হাতে সবকিছুর উপর সর্বভৌম ক্ষমতা রয়েছে, এবং তাঁর কাছে তোমরা ফিরে যাবে।"],
  "37:1": ["By those drawn up in ranks,", "সারিবদ্ধ সুবিন্যাসকারী।"],
  "37:2": ["and the drive-back driving back,", "তাদের দোষারোপকারী যাদের প্রতি দোষারোপ করা হবে।"],
  "37:3": ["and those who follow with a reminder,", "বার্তাসমূহের আবৃতিকারী।"],
  "37:4": ["your deity is surely One,", "তোমাদের উপাস্য কেবল একজন।"],
  "37:5": ["Rabb of the heavens and the earth and what is between them, and Rabb of the east.", "আকাশমন্ডলী ও পৃথিবী, এবং তাদের মধ্যকার সবকিছুর প্রভু, এবং পূর্বসমূহের প্রভু।"],
  "37:6": ["We adorned the lowest heaven with the adornment of stars,", "আমরা নিম্নতম আকাশকে সৌন্দর্যমন্ডিত গ্রহ দিয়ে সাজিয়েছি।"],
  "37:7": ["a guard against every defiant devil,", "আমরা একে প্রত্যেক মন্দ শয়তান থেকে সুরক্ষিত করেছি।"],
  "37:8": ["so that they cannot listen to the high assembly, and they are cast at from every side,", "তারা উর্ধ্ব সমাজে গুপ্তচরবৃত্তি করতে পারে না। প্রত্যেক পাশ থেকে তাদের দিকে বিস্ফোরক ছোড়া হয়।"],
  "37:9": ["driven away, and for them is a lasting punishment.", "তারা দোষী সাব্যস্ত হয়েছে; তারা টেনে এনেছে এক চিরস্থায়ী শাস্তি।"],
  "37:10": ["Except one who snatches a snatch; then a piercing fire-missile follows him.", "যদি তাদের কেউ শেষ সীমায় অনুপ্রবেশের স্পর্ধা দেখায়, সে এক ভয়ংকর উৎক্ষেপক দ্বারা আঘাতপ্রাপ্ত হয়।"],
  "37:11": ["So ask them: are they stronger in creation, or those whom We created? We created them from clinging clay.", "তাদের জিজ্ঞেস করো, “তাদেরকে সৃষ্টি করা কি বেশি কঠিন, না অন্যসব সৃষ্টি?” আমরা তাদেরকে কাদামাটি থেকে সৃষ্টি করেছি।"],
  "37:12": ["Nay, they marvel, and they mock.", "যখন তুমি বিস্মিত হও, তারা উপহাস করে।"],
  "37:13": ["And when they are reminded, they do not remember.", "যখন স্মরণ করিয়ে দেয়া হয়, তারা কোন মনোযোগ দেয় না।"],
  "37:14": ["And when they see a sign, they mock.", "যখন তারা প্রমান দেখে, তারা এর ব্যঙ্গ-বিদ্রুপ করে।"],
  "37:15": ["And they say: this is nothing but clear magic.", "তারা বলে, \"এটা স্পষ্টই জাদু!"],
  "37:16": ["When we die and become dust and bones, shall we be raised?", "\"আমরা মরে ধূলিকণা এবং হাড় হয়ে যাবার পরেও কি আমরা পুনরুত্থিত হবো?"],
  "37:17": ["Or our former fathers?", "\"এমনকি আমাদের প্রাচীন পূর্বপুরুষেরাও?\""],
  "37:18": ["Say: yes, and you will be subdued.", "বল, \"হ্যা, তোমাদের জোড়পুর্বক তলব করা হবে।\""],
  "37:19": ["It is but a single drive, and at once they are looking.", "কেবল একটি মৃদু দাক্কাই যথেষ্ট, যার ফলে তারা (দাঁড়িয়ে) দেখতে থাকবে।"],
  "37:20": ["And they say: woe to us, this is the day of requital.", "তারা বলবে, \"দুর্ভাগ্য আমাদের; এটাই সে বিচার দিবস।\""],
  "37:21": ["This is the day of decision which you used to deny.", "এটাই সে সিদ্ধান্তের দিন যাতে তোমরা অবিশ্বাস করতে।"],
  "37:22": ["Gather those who wronged, and their mates, and what they used to worship", "তলব করো সীমালঙ্ঘনকারীদের, এবং তাদের সঙ্গীদের, এবং সে উপাস্যদের যাদেরকে তারা উপাসনা করতো"],
  "37:23": ["besides Allah, then guide them to the path of the blaze.", "আল্লাহর পাশে, এবং তাদেরকে নরকের পথ দেখাও।"],
  "37:24": ["Stop them; they will be questioned.", "তাদেরকে থামাও, আর জিজ্ঞেস করো:"],
  "37:25": ["Why do you not help one another?", "কেন তোমরা একে অন্যকে সাহায্য করো না?\""],
  "37:26": ["Nay, today they have surrendered.", "তারা হবে, ঐদিন, পুরোপুরি সমর্পিত।"],
  "37:27": ["And some of them turn to one another, asking.", "তারা একে অন্যের কাছে আসবে, পরস্পরকে প্রশ্ন এবং দোষারোপ করতে করতে।"],
  "37:28": ["They say: you used to come to us from the right.", "তারা (তাদের নেতাদের) বলবে, \"তোমরা আমাদের কাছে ডান পাশ থেকে আসতে।\""],
  "37:29": ["They say: nay, you were not muminin.", "তারা উত্তর দিবে, \"তোমরাই তো বিশ্বাসী ছিলে না।"],
  "37:30": ["We had no warrant over you; rather, you were a transgressing people.", "\"তোমাদের উপর আমাদের কোন ক্ষমতা ছিল না; তোমরাই অন্যায়কারী ছিলে।"],
  "37:31": ["The word of our Rabb has befallen us; we will surely taste.", "\"আমরা আমাদের প্রভুর ন্যায্য বিচার পেয়েছি; এখন আমাদের ভোগ করতে হবে।"],
  "37:32": ["We misled you; we were misleaders.", "\"আমরা তোমাদের ভুল পথে চালিয়েছি, কেবল একারনে যে আমরাই পথভ্রষ্ট ছিলাম।"],
  "37:33": ["So that day they share in the punishment.", "সুতরাং, একসাথে তারা সবাই ঐদিন শাস্তির ভাগী হবে।"],
  "37:34": ["Thus We do with the mujrimin.", "এভাবেই আমরা অপরাধীদের প্রতিফল দেই।"],
  "37:35": ["When it was said to them: there is no deity but Allah, they were arrogant,", "যখন তাদের বলা হতো, \"লা ইলাহা ইল্লাহ [আল্লাহর পাশে অন্যকোন উপাস্য নেই],” তারা উদ্ধত হয়ে পড়তো।"],
  "37:36": ["and they say: shall we abandon our alihah for a mad poet?", "তারা বলতো, \"আমরা কি একজন পাগল কবির জন্য আমাদের উপাস্যদের ত্যাগ করবো।"],
  "37:37": ["Nay, he came with the truth and confirmed the Rasuls.", "প্রকৃতপক্ষে, সে সত্য এনেছে, এবং বার্তাবাহকদের নিশ্চিত করেছে।"],
  "37:38": ["You will surely taste the painful punishment,", "নিশ্চয়, তোমরা সবচেয়ে যন্ত্রণাকর শাস্তি আস্বাদন করবে।"],
  "37:39": ["and you are repaid only for what you used to do.", "তোমরা যা করেছ শুধু তার জন্য প্রতিফল পাও।"],
  "37:40": ["Except the devoted servants of Allah:", "শুধু আল্লাহর বান্দারা (রক্ষা পাবে) যারা সম্পূর্ণভাবে কেবল তার প্রতি নিবেদিত।"],
  "37:41": ["those have a known provision,", "তারা সে জীবিকার যোগ্য  হয়েছে যা বিশেষভাবে তাদের জন্য সংরক্ষিত।"],
  "37:42": ["fruits, and they are honored,", "সকল প্রকার ফল। তারা হবে সম্মানিত।"],
  "37:43": ["in gardens of bliss,", "পরম সুখের বাগানগুলোয়।"],
  "37:44": ["on couches, facing one another.", "আসবাবপত্রের উপর পরস্পর কাছাকাছি।"],
  "37:45": ["A cup from a flowing spring is carried around among them,", "তাদেরকে বিশুদ্ধ পানীয়ের পেয়ালা পরিবেশন করা হবে।"],
  "37:46": ["white, a delight for the drinkers,", "পানকারীদের জন্য স্বচ্ছ ও সুস্বাদু।"],
  "37:47": ["with no headiness in it, and they are not cut off from it.", "কখনো দূষিত নয়, এবং কখনো অবসাদগ্রস্থ করে না।"],
  "37:48": ["And with them are companions whose glances are restrained, wide of eye,", "তাদের সাথে থাকবে চমৎকার সাথীরা।"],
  "37:49": ["as if they were concealed eggs.", "ভঙ্গুর ডিমের মতো সুরক্ষিত।"],
  "37:50": ["And some of them turn to one another, asking.", "তারা পরস্পরের কাছে আসবে, এবং একে অন্যের সাথে পরামর্শ করবে।"],
  "37:51": ["One of them, a speaker, says: I had a companion", "তাদের একজন বলবে, \"আমার এক বন্ধু ছিল।"],
  "37:52": ["who used to say: are you really one of those who affirm?", "\"সে উপহাস করতো: 'তুমি কি এইসব বিশ্বাস করো?"],
  "37:53": ["When we die and become dust and bones, shall we be requited?", "\"'আমরা মরে ধুলো এবং হাড়ে পরিণত হবার পরেও কি আমাদেরকে হিসাবের জন্য ডাকা হবে?'\""],
  "37:54": ["He says: will you take a look?", "সে বলবে, \"একটু তাকিয়ে দেখো!\""],
  "37:55": ["He looked and saw him in the midst of the blaze.", "যখন সে তাকাবে, সে তার বন্ধুকে নরকের গভীরে দেখবে।"],
  "37:56": ["He says: by Allah, you nearly plunged me into ruin.", "সে (তার কাছে যাবে এবং) বলবে, \"আল্লাহর শপথ, তুমি তো আমাকে প্রায় ধ্বংসই করে দিয়েছিলে।"],
  "37:57": ["Were it not for the grace of my Rabb, I would have been among those brought before.", "\"যদি আমার প্রভুর অনুগ্রহ না থাকতো, এখন আমি হয়তো তোমার সাথে থাকতাম।"],
  "37:58": ["So are we not dead,", "\"(তুমি কি এখনও বিশ্বাস করো) যে আমরা মারা যাই, \""],
  "37:59": ["except for our first death, and we will not be punished?", "\"শুধু প্রথম মৃত্যুতেই, এবং আমরা কখনো কোন প্রতিফল পাই না?\""],
  "37:60": ["This is truly the great win.", "এমনই শ্রেষ্ঠ বিজয়।"],
  "37:61": ["For the like of this let the workers work.", "ঠিক এর জন্যই সকল কর্মীর কাজ করা উচিত।"],
  "37:62": ["Is that a better lodging, or the Zaqqum tree?", "এটা কি উত্তম নিয়তি, নাকি তিক্ততার গাছ?"],
  "37:63": ["We made it a trial for the wrongdoers.", "একে আমরা সীমালঙ্ঘনকারীদের জন্য একটি শাস্তিস্বরুপ করেছি।"],
  "37:64": ["It is a tree that comes out in the root of the blaze.", "এটা একটি গাছ যা নরকের মাঝখানে জন্মায়।"],
  "37:65": ["Its spathes are like the heads of devils.", "এর ফুলগুলো দেখায় শয়তানের মাথার মতো।"],
  "37:66": ["They will eat from it and fill their bellies with it.", "এটি থেকে তারা খাবে যতক্ষণ না তাদের পেট পূর্ণ হয়।"],
  "37:67": ["Then they have upon it a drink of scalding water,", "এরপর তাতে তারা নারকীয় পানীয় ঢালবে।"],
  "37:68": ["then their return is to the blaze.", "এরপর তারা নরকে ফিরে যাবে।"],
  "37:69": ["They found their fathers astray,", "তারা তাদের মাতা-পিতার অন্ধ অনুসরণ করেছিল"],
  "37:70": ["and they rush on their tracks.", "এবং তারা অন্ধভাবে তাদের পদাংক অনুসরণ করেছিল।"],
  "37:71": ["Most of the ancients went astray before them,", "পূর্ববর্তী অধিকাংশ প্রজন্মগুলো একইভাবে পথভ্রষ্ট হয়েছে।"],
  "37:72": ["and We sent warners among them.", "তাদের কাছে আমরা সতর্ককারী পাঠিয়েছি।"],
  "37:73": ["See how the end of the warned ones was.", "তাদের পরিনাম লক্ষ্য করো যাদেরকে সতর্ক করা হয়েছিল।"],
  "37:74": ["Except the devoted servants of Allah.", "শুধু আল্লাহর বান্দারা (রক্ষা পাবে) যারা কেবল পুরোপুরি তাঁর নিকট নিবেদিত।"],
  "37:75": ["Nuh called Us, and excellent are We as answerers.", "এভাবে, নূহ আমাদেরকে ডেকেছিল, এবং আমরাই সর্বোত্তম সাড়া দানকারী ছিলাম।"],
  "37:76": ["We saved him and his family from the great distress,", "আমরা তাকে এবং তার পরিবারকে মহাদূর্যোগ থেকে রক্ষা করেছিলাম।"],
  "37:77": ["and We made his offspring the ones who remained,", "আমরা তার সঙ্গী-সাথীদের বাচিয়ে রেখেছিলাম।"],
  "37:78": ["and We left a mention of him among the later ones.", "এবং পরবর্তী প্রজন্মের জন্য আমরা তার ইতিহাস সংরক্ষণ করেছিলাম।"],
  "37:79": ["Peace on Nuh among the worlds.", "লোকদের মধ্যে নূহের প্রতি শান্তি বর্ষিত হোক।"],
  "37:80": ["Thus We repay the good-doers.", "আমরা এভাবে সৎকর্মশীলদের পুরষ্কার দেই।"],
  "37:81": ["He is one of Our believing servants.", "সে আমাদের বিশ্বাসী বান্দাদের একজন।"],
  "37:82": ["Then We drowned the others.", "অন্য সবাইকে আমরা ডুবিয়ে দিয়েছিলাম।"],
  "37:83": ["Among his party was Ibrahim,", "তার অনুসারীদের মধ্যে ছিল ইব্রাহিম।"],
  "37:84": ["when he came to his Rabb with a sound heart.", "সে তার প্রভুর কাছে এসেছিল সম্পূর্ণ হৃদয় নিয়ে।"],
  "37:85": ["When he said to his father and his people: what do you worship?", "সে তার পিতা এবং তার লোকদের বলল, \"তোমরা কিসের উপাসনা করছো?"],
  "37:86": ["Do you want false alihah besides Allah?", "এইসব বানানো উপাস্যগুলোই কি তা, আল্লাহর বদলে, যা তোমরা চাও?\""],
  "37:87": ["What then do you suppose of the Rabb of the worlds?", "মহাবিশ্বের প্রভু সম্পর্কে তোমাদের ধারণা কি?\""],
  "37:88": ["He looked with a look at the stars,", "সে তারাগুলোর দিকে মনোযোগ দিয়ে তাকালো।"],
  "37:89": ["and said: I am sick.", "তারপর সে বাদ দিলো এবং বলল, “আমি এতে ক্লান্ত!\""],
  "37:90": ["So they turned away from him and left.", "তারা তার থেকে মুখ ফিরিয়ে নিল।"],
  "37:91": ["He turned to their alihah and said: do you not eat?", "তারপর সে তাদের উপাস্যদের দিকে ফিরলো, এ বলে যে, \"তোমরা কি খেতে পছন্দ করো?\""],
  "37:92": ["What is wrong with you that you do not speak?", "\"কেন তোমরা কথা বলো না?\""],
  "37:93": ["He turned on them, striking with the right hand.", "সে তারপর এগুলোকে ধ্বংস করলো?\""],
  "37:94": ["They came to him hurrying.", "তারা ভীষন রাগান্বিত হয়ে তার কাছে গেল।"],
  "37:95": ["He said: do you worship what you carve,", "সে বলল, \"কেমন করে তোমরা তার উপাসনা করো যা তোমরা খোদাই করো?"],
  "37:96": ["when Allah created you and what you make?", "\"অথচ আল্লাহ সৃষ্টি করেছেন তোমাদেরকে, এবং সবকিছুকে যা তোমরা বানাও!\""],
  "37:97": ["They said: build him a structure and cast him into the blaze.", "তারা বলল, \"চল আমরা এক বিশাল অগ্নিকুণ্ডলী বানাই, এবং তাকে এর মধ্যে নিক্ষেপ করি।\""],
  "37:98": ["They intended a scheme against him, so We made them the lowest.", "তারা তার বিরুদ্ধে ষড়যন্ত্র করলো, কিন্তু আমরা তাদের পরাজিত করলাম।"],
  "37:99": ["And he said: I am going to my Rabb, who will guide me.", "সে বলল, \"আমি আমার প্রভুর কাছে যাচ্ছি; তিনি আমাকে পথ দেখাবেন।\""],
  "37:100": ["My Rabb, grant me one of the salihin.", "\"আমার প্রভু, আমাকে সৎকর্মশীল সন্তান দান করুন।\""],
  "37:101": ["So We gave him good news of a forbearing boy.", "আমরা তাকে একটি ভালো সন্তানের সুসংবাদ দিলাম।"],
  "37:102": ["And when he reached with him the age of striving, he said: my son, I see in a dream that I am to slaughter you, so see what you think. He said: my father, do what you are commanded; you will find me, if Allah wills, of the sabirin.", "যখন সে তার সাথে কাজ করার মতো যথেষ্ঠ বড় হয়ে উঠলো, সে বলল, \"আমার পুত্র, আমি স্বপ্নে দেখি যে তোমাকে আমি উৎসর্গ করছি। তুমি কি ভাবছো? “সে বলল, \"হে আমার পিতা, আপনার প্রতি যা প্রত্যাদেশ হয় তা করুন। আল্লাহ চাইলে আপনি আমাকে পাবেন, ধৈর্যশীল।"],
  "37:103": ["When both had submitted and he laid him down upon the forehead,", "তারা উভয়ে আত্মসমর্পণ করল, এবং সে তার কপাল নীচে রাখলো (তাকে উৎসর্গ করতে)।"],
  "37:104": ["We called him: O Ibrahim,", "আমরা তাকে ডাকলাম: \"হে ইব্রাহীম।"],
  "37:105": ["you have confirmed the vision; thus We repay the good-doers.", "\"স্বপ্নটি তুমি বিশ্বাস করেছো।” আমরা এভাবে সৎকর্মশীলদের পুরষ্কার দেই।"],
  "37:106": ["This is the clear test.", "নিশ্চয় এটা ছিল এক কঠোর পরীক্ষা।"],
  "37:107": ["We ransomed him with a great slaughter,", "আমরা একটি পশু উৎসর্গের বদলে (ইসমাইলকে) মুক্তি দিলাম।"],
  "37:108": ["and We left a mention of him among the later ones.", "এবং আমরা তার ইতিহাসকে পরবর্তী প্রজন্মের জন্য সংরক্ষণ করলাম।"],
  "37:109": ["Peace on Ibrahim.", "ইব্রাহিমের উপর শান্তি বর্ষিত হোক।"],
  "37:110": ["Thus We repay the good-doers.", "আমরা এভাবে সৎকর্মশীলদের পুরষ্কার দেই।"],
  "37:111": ["He is one of Our believing servants.", "সে ছিল আমাদের বিশ্বাসী বান্দাদের একজন।"],
  "37:112": ["And We gave him good news of Isaac, a Nabi of the salihin.", "এরপর আমরা তাকে ইসহাকের জন্মের সুসংবাদ দিলাম, যে হবে সৎকর্মশীল নবীদের একজন।"],
  "37:113": ["We blessed him and Isaac; and among their offspring are one who does good and one who clearly wrongs himself.", "আমরা তাকে ও ইসহাককে সৌভাগ্যশীল করেছিলাম। তাদের বংশধরদের মধ্যে, কেউ কেউ সৎকর্মশীল, আর কেউ কেউ নীতিবিবর্জিত সীমালঙ্ঘনকারী।"],
  "37:114": ["We surely favored Musa and Harun.", "আমরা মূসা ও হারুনকেও আশীর্বাদ করেছিলাম।"],
  "37:115": ["We saved them and their people from the great distress,", "আমরা এক মহাদূর্যোগ থেকে তাদেরকে এবং তাদের লোকদের উদ্ধার করেছিলাম।"],
  "37:116": ["and We helped them, and they were the overcomers.", "আমরা তাদেরকে সমর্থন করেছিলাম, যতক্ষণ না তারা জয়ী হয়েছিল।"],
  "37:117": ["We gave them the clear scripture,", "আমরা তাদের উভয়কে জ্ঞানগর্ভ ঐশীগ্রন্থ দিয়েছিলাম।"],
  "37:118": ["and We guided them on the straight path.", "আমরা তাদেরকে সঠিক পথ প্রদর্শন করেছিলাম।"],
  "37:119": ["We left a mention of them among the later ones.", "পরবর্তী প্রজন্মের জন্য আমরা তাদের ইতিহাস সংরক্ষণ করেছিলাম।"],
  "37:120": ["Peace on Musa and Harun.", "মূসা এবং হারুনের উপর শান্তি বর্ষিত হোক।"],
  "37:121": ["Thus We repay the good-doers.", "এভাবে আমরা সৎকর্মশীলদের পুরষ্কার দেই।"],
  "37:122": ["They are two of Our believing servants.", "তাদের উভয়ে ছিল আমাদের সৎকর্মশীল বান্দাদের অন্তর্ভুক্ত।"],
  "37:123": ["Ilyas was one of the Rasuls,", "ইলিয়াস ছিল বার্তাবাহকদের একজন।"],
  "37:124": ["when he said to his people: will you not be mindful?", "সে তার লোকদের বলেছিল, \"তোমরা কি সৎকর্ম করবে না?"],
  "37:125": ["Do you call on Ba'l and abandon the best of creators?", "\"তোমরা কি উপাসনা করো এক মূর্তির, পরম সৃষ্টিকর্তার পরিবর্তে?"],
  "37:126": ["Allah is your Rabb and the Rabb of your former fathers.", "\"আল্লাহ; তোমাদের প্রভু, এবং তোমাদের পূর্বপুরুষের প্রভু!\""],
  "37:127": ["They denied him, and they will be brought before,", "তারা তাকে অবিশ্বাস করলো। পরিনামে, তাদেরকে হিসাবের জন্য ডাকা হবে।"],
  "37:128": ["except the devoted servants of Allah.", "শুধু্ আল্লাহর বান্দারা (রক্ষা পায়) যারা কেবল তাঁর প্রতি নিবেদিত।"],
  "37:129": ["We left a mention of him among the later ones.", "আমরা তার ইতিহাস পরবর্তী প্রজন্মের জন্য সংরক্ষণ করেছিলাম।"],
  "37:130": ["Peace on Ilyasin.", "শান্তি বর্ষিত হোক ইলিয়াসের উপর, এবং ইলিয়াসের মত সবার উপর।"],
  "37:131": ["Thus We repay the good-doers.", "আমরা এভাবে সৎকর্মশীলদের পুরষ্কার দেই।"],
  "37:132": ["He is one of Our believing servants.", "সে ছিল আমাদের বিশ্বাসী বান্দাদের একজন।"],
  "37:133": ["Lut was one of the Rasuls,", "লূত ছিল বার্তাবাহকদের একজন।"],
  "37:134": ["when We saved him and all his family,", "আমরা তাকে এবং তার পরিবারের সকলকে রক্ষা করেছিলাম।"],
  "37:135": ["except an jawza among those left behind.", "কেবল সেই বৃদ্ধ মহিলা ধ্বংস হয়েছিল।"],
  "37:136": ["Then We razed the others,", "আমরা অন্যদের সকলকে নির্মূল করলাম।"],
  "37:137": ["and you pass by them in the morning,", "এখনও তোমরা তাদের ধ্বংসস্তূপের পাশ দিয়ে যাও দিনে।"],
  "37:138": ["and by night; will you not reason?", "এবং রাতে। তোমরা কি বুঝবে?"],
  "37:139": ["Yunus was one of the Rasuls,", "ইউনুছ ছিল বার্তাবাহকদের একজন।"],
  "37:140": ["when he fled to the laden ship,", "সে বোঝাইকৃত জাহাজে পালালো।"],
  "37:141": ["cast lots, and was among the mudhadin.", "সে বিদ্রোহ করেছিল আর এভাবে, সে পরাজিতদের সাথে যোগ দিল।"],
  "37:142": ["The fish swallowed him, and he was blameworthy.", "ফলশ্রুতিতে, মাছ তাকে গিলে ফেললো, এবং সে-ই ছিল দোষী ব্যক্তি।"],
  "37:143": ["Had he not been one of those who glorify,", "যদি সে (আল্লাহর) ধ্যানে মগ্ন না হতো,"],
  "37:144": ["he would have tarried in its belly until the day they are raised.", "সে হয়তো এর পেটেই থাকতো পুনরুত্থান দিনের আগ পর্যন্ত।"],
  "37:145": ["So We cast him on the open ground, while he was sick,", "আমরা তাকে মরুভূমিতে নিক্ষেপ করলাম, মৃতপ্রায় অবস্থায়।"],
  "37:146": ["and We grew over him a gourd tree,", "আমরা তার জন্য একটি ভক্ষনযোগ্য ফলের গাছ জন্মাতে দিলাম।"],
  "37:147": ["and We sent him to a hundred thousand, or more.", "এরপর আমরা তাকে একশ হাজার, বা তার চেয়ে বেশির নিকট পাঠালাম।"],
  "37:148": ["They believed, so We gave them enjoyment for a time.", "তারা বিশ্বাস করেছিলো, এবং আমরা তাদেরকে এই জীবন উপভোগ করতে দিলাম।"],
  "37:149": ["So ask them: does your Rabb have daughters while they have sons?", "তাদেরকে জিজ্ঞেস করো তোমার প্রভুর কি কন্যা রয়েছে, যখন তাদের রয়েছে পুত্র!"],
  "37:150": ["Or did We create the malakat female, while they are witnesses?", "আমরা কি ফেরেশতাদের নারী রুপে সৃষ্টি করেছিলাম? তারা কি তা প্রত্যক্ষ করেছিল?"],
  "37:151": ["They surely say from their fabrication:", "নিশ্চয়, তারা গুরুতর ধর্মনিন্দা করে যখন তারা বলে-"],
  "37:152": ["Allah has begotten, and they are liars.", "\"আল্লাহ পুত্র জন্ম দিয়েছেন।” নিশ্চয়, তারা মিথ্যাবাদী।"],
  "37:153": ["Did Allah choose daughters over sons?", "তিনি কি ছেলেদের উপর মেয়েদের পছন্দ করেছিলেন?"],
  "37:154": ["What is wrong with you, how do you judge?", "তোমাদের যুক্তিতে সমস্যা কোথায়?"],
  "37:155": ["Will you not remember?", "কেন তোমরা মনোযোগ দাও না?"],
  "37:156": ["Or do you have a clear warrant?", "তোমাদের কি কোন প্রমান আছে?"],
  "37:157": ["Then bring your scripture, if you are sadiq.", "আমাদেরকে তোমাদের কিতাব দেখাও, যদি তোমরা সত্যবাদী হও।"],
  "37:158": ["They made kinship between Allah and the jinn, and the jinn knew that they will be brought before.", "তারা এমনকি তাঁর এবং জ্বীনদের মাঝে বিশেষ সম্পর্ক উদ্ভাবন করেছিল।"],
  "37:159": ["Glory be to Allah above what they describe,", "মহিমা আল্লাহর; তাদের দাবির অনেক উর্ধ্বে।"],
  "37:160": ["except the devoted servants of Allah.", "শুধু আল্লাহর বান্দারা (রক্ষা পাবে) যারা কেবল তার প্রতি নিবেদিত।"],
  "37:161": ["But you and what you worship,", "নিশ্চয়, তোমরা এবং যার উপাসনা তোমরা করো।"],
  "37:162": ["you cannot mislead anyone with it,", "তাঁর উপর কিছু চাপিয়ে দিতে পারে না।"],
  "37:163": ["except whoever enters the blaze.", "শুধু তোমরাই নরকে পুড়বে।"],
  "37:164": ["There is none of us but has a known station,", "আমাদের প্রত্যেকের একটি নির্দিষ্ট কাজ আছে।"],
  "37:165": ["and we are the ones in ranks,", "আমরাই বিন্যাসকারী।"],
  "37:166": ["and we are the ones who glorify.", "আমরা যথাযথভাবে (আমাদের প্রভুর) গুণগান করি।"],
  "37:167": ["They used to say:", "তারা বলতো যে,"],
  "37:168": ["if only we had a reminder from the ancients,", "যদি আমরা আমাদের পিতা-মাতা থেকে সঠিক নির্দেশনা পেতাম,"],
  "37:169": ["we would be the devoted servants of Allah.", "\"আমরা উপাসনাকারী হতাম; কেবল আল্লাহর প্রতি নিবেদিত। \""],
  "37:170": ["They kafara in it, so they will know.", "কিন্তু তারা অবিশ্বাস করেছিল, এবং তারা অবশ্যই দেখবে।"],
  "37:171": ["Our word has gone ahead for Our servants, the Rasuls:", "আমাদের বার্তাবাহক বান্দাদের জন্য আমাদের সিদ্ধান্ত ইতোমধ্যেই নির্ধারণ করা হয়েছে।"],
  "37:172": ["they are the helped ones,", "নিশ্চয় তারাই বিজয়ী।"],
  "37:173": ["and Our hosts are the overcomers.", "আমাদের সৈন্যরাই জয়লাভকারী।"],
  "37:174": ["So turn away from them for a time,", "অতএব কিছু সময়ের জন্য তাদের উপেক্ষা করো।"],
  "37:175": ["and see them; they will soon see.", "তাদেরকে লক্ষ্য করো; তারাও লক্ষ্য রাখবে।"],
  "37:176": ["Do they seek to hasten Our punishment?", "তারা কি আমাদের শাস্তিকে চ্যালেঞ্জ করে?"],
  "37:177": ["When it descends on their courtyard, evil will be the morning of the warned ones.", "একদিন যখন তা তাদের আঘাত করবে, এটা হবে এক শোচনীয় দিন; তাদেরকে যথেষ্ট পরিমানে সতর্ক করা হয়েছে।"],
  "37:178": ["And turn away from them for a time,", "তাদেরকে কিছু সময়ের জন্য উপেক্ষা করো।"],
  "37:179": ["and see; they will soon see.", "তাদেরকে লক্ষ্য করো; তারাও লক্ষ্য রাখবে।"],
  "37:180": ["Glory be to your Rabb, the Rabb of might, above what they describe,", "মহিমা তোমার প্রভুর, মহান প্রভু; তাদের দাবির অনেক উর্ধ্বে।"],
  "37:181": ["and peace be on the Rasuls,", "বার্তাবাহকদের উপর শান্তি বর্ষিত হোক।"],
  "37:182": ["and praise belongs to Allah, Rabb of the worlds.", "প্রশংসা আল্লাহর, মহাবিশ্বের প্রভু।"],
  "38:1": ["Sad. By the Qur'an, possessor of the reminder.", "স. (সা'দ), এবং কোর'আন যা বহন করে প্রমান।"],
  "38:2": ["Nay, those who disbelieve are in might and opposition.", "যারা অবিশ্বাস করে তারা ঔদ্ধত্য এবং অবাধ্যতায় নিমজ্জিত হয়েছে।"],
  "38:3": ["How many a generation We destroyed before them, and they cried out — but there was no time of escape.", "তাদের আগে অনেক প্রজন্মকে আমরা ধ্বংস করেছিলাম। তারা সাহায্যের জন্য ডেকেছিলো; বৃথাই।"],
  "38:4": ["And they marveled that a warner had come to them from among themselves. And the kafirin said: \"This is a lying sorcery.\"", "তারা অবাক হয়েছিল যে তাদের কাছে একজন সতর্ককারী এসেছে, তাদের মধ্য থেকে। অবিশ্বাসীরা বলল, \"একজন যাদুকর; মিথ্যুক।"],
  "38:5": ["\"Has he made the alihah into one ilah? Truly this is an astounding thing!\"", "সে কি বহু উপাস্যকে এক উপাস্য বানিয়ে ফেলেছে? এটি সত্যিই বিস্ময়কর।\""],
  "38:6": ["And their chiefs set out, saying: \"Go on, and be of the sabirin over your ilahs — this is surely something intended.\"", "নেতারা ঘোষনা করল, \"যাও এবং দৃড়তার সাথে অবিচল থেকে তোমাদের উপাস্যদের উপাসনা করো। এটাই তো কাম্য।"],
  "38:7": ["\"We have not heard of this in the later way; this is nothing but a fabrication.\"", "\"আমরা আমাদের পিতৃপুরুষদের ধর্ম থেকে কখনো এমন শুনিনি। এটি একটি মিথ্যা।"],
  "38:8": ["\"Has the reminder been sent down to him from among us?\" Nay, they are in doubt about My reminder — nay, they have not yet tasted the punishment.", "\"কেন তার কাছেই প্রমান আসলো, আমাদের পরিবর্তে? \"নিশ্চয়, তারা আমার প্রমানের বিষয়ে সন্দিহান। নিশ্চয়ই, তারা এখনো আমার শাস্তি আস্বাদন করেনি।"],
  "38:9": ["Or do they have the treasures of the mercy of your Rabb, the Mighty, the Grantor?", "তারা কি তোমার প্রভুর দয়ার ভান্ডারের মালিক, যিনি সর্বশক্তিমান, দাতা?"],
  "38:10": ["Or is the kingdom of the heavens and the earth and what is between them theirs? Then let them ascend by means.", "তারা কি আকাশমণ্ডলী ও পৃথিবী, এবং এগুলোর মধ্যকার সবকিছুর সার্বভৌমত্ব অধিকার করে? তাদেরকে সাহায্য করতে দাও তাদের নিজেদেরকেই।"],
  "38:11": ["There, every host is routed from among the confederates.", "পরিবর্তে, তারা যে শক্তিই একত্রিত করতে পারুক- এমনকি যদি তাদের সকল দল একত্রে জড়ো হয়ও- তারা পরাজিত হবে।"],
  "38:12": ["The people of Nuh, Aad, and Fir'awn of the Stakes denied before them.", "তাদের পূর্বে অবিশ্বাস করেছিল নূহের লোকেরা, আদ, এবং শক্তিশালী ফেরাউন।"],
  "38:13": ["And Thamud, and the people of Lut, and the companions of the Thicket — those were the confederates.", "এছাড়া, সামূদ, লূতের লোকেরা, (মাদিয়ানে) গভীর জংগলের অধিবাসীরা; তারা ছিল বিরোধী।"],
  "38:14": ["Every one of them denied the Rasuls, and so the punishment came true.", "তাদের প্রত্যেকে বার্তাবাহককে অবিশ্বাস করেছিল আর এভাবে, আমার শাস্তি ছিল অবধারিত।"],
  "38:15": ["These people await nothing but a single shout, with no interval in it.", "এই লোকেরা কেবল একটি আঘাত প্রত্যাশা করতে পারে, যা থেকে তারা কখনো পূর্বাবস্থায় ফেরে না।"],
  "38:16": ["And they say: \"Our Rabb, hasten our portion to us before the Day of Reckoning.\"", "তারা চ্যালেঞ্জ করেছিল: আমাদের প্রভু, কেন আপনি আমাদেরকে দ্রুত শাস্তি দেন না, বিচার দিনের পূর্বে।"],
  "38:17": ["Be sabir over what they say, and remember Our servant Dawud, the possessor of strength; truly he was ever-turning back.", "তাদের কথায় ধৈর্য ধরো, এবং আমাদের বান্দা দাউদকে স্মরণ করো, প্রাচুর্যশালী; সে ছিল অনুগত।"],
  "38:18": ["We subjected the mountains with him, glorifying at evening and at sunrise.", "আমরা পাহাড়কে তার সেবায় নিয়োজিত করেছিলাম, যারা তার সাথে গুণকীর্তন করতো রাতে এবং দিনে।"],
  "38:19": ["And the birds gathered, each of them ever-returning.", "পাখিরাও ছিল তার সেবায় নিয়োজিত; সকলে তার অনুগত ছিল।"],
  "38:20": ["And We strengthened his kingdom, and gave him wisdom and decisive speech.", "আমরা তার রাজত্বকে শক্তিশালী করেছিলাম, এবং তাকে প্রজ্ঞা ও ভাল যুক্তি দান করেছিলাম।"],
  "38:21": ["Has the account of the contenders come to you — when they climbed into the chamber?", "তুমি কি সেই বিবাদকারী লোকদের খবর পেয়েছো যারা চুপিসারে তার উপাসনাস্থলে ঢুকে পড়েছিল?"],
  "38:22": ["When they entered upon Dawud, and he dreaded them, they said: \"Do not fear — two contenders, one of whom has wronged the other; so judge between us with the truth, and do not transgress, and guide us to the even path.\"", "যখন তারা তার কক্ষে প্রবেশ করলো, সে চমকে উঠলো। তারা বলল, \"ভয় পাবেন না। আমরা একে অন্যের সাথে বিবাদে করছি এবং আমরা আপনার কাছে ন্যায় বিচার চাচ্ছি। আমাদের প্রতি অন্যায় করবেন না, এবং আমাদেরকে সঠিক পথ প্রদর্শন করুন।"],
  "38:23": ["\"This brother of mine has ninety-nine ewes, and I have one ewe; and he said: 'Entrust her to me,' and he overpowered me in the affair.\"", "আমার এই ভাই নিরান্নবইটি ভেড়ার মালিক, যেখানে আমি একটি ভেড়ার মালিক। সে আমার ভেড়াকে তারগুলোর সাথে মিশিয়ে ফেলতে চায়, এবং আমাকে চাপ দিয়েই যাচ্ছে।"],
  "38:24": ["He said: \"He has wronged you by asking for your ewe to add to his ewes; and indeed many partners wrong one another, except those who believe and do salih deeds — and few they are.\" And Dawud thought that We had only tested him, so he sought forgiveness of his Rabb, and fell down bowing, and turned back.", "সে বলল, “সে তোমার প্রতি অন্যায় করেছে তোমার ভেড়াটি তারগুলোর সাথে মিশিয়ে ফেলতে বলে। বেশির ভাগ লোকই যারা তাদের সম্পদ মিশিয়ে ফেলে তারা একে অন্যের সাথে অন্যায় আচরণ করে, তারা ছাড়া যারা বিশ্বাস করে এবং সৎকর্ম করে, এবং এরা সংখ্যায় খুবই অল্প।” পরবর্তীতে, দাউদ সন্দেহ পোষন করলো যে সে সঠিক বিচার করেছে কিনা। সে ভাবলো আমরা তাকে পরীক্ষা করছিলাম। সে এরপর তার প্রভুর কাছে ক্ষমার জন্য মিনতি করলো, নত হলো এবং অনুশোচনা করলো।"],
  "38:25": ["So We forgave him that; and truly with Us he has near access and a good return.", "এই বিষয়ে তাকে আমরা ক্ষমা করে দিয়েছিলাম। আমরা তাকে প্রদান করেছি আমাদের সাথে এক সম্মানিত অবস্থান, এবং এক চমৎকার আবাস।"],
  "38:26": ["O Dawud, We have made you a successor upon the earth, so judge between the people with the truth, and do not follow desire, lest it lead you astray from the way of Allah. Those who go astray from the way of Allah — theirs is a severe punishment for what they forgot of the Day of Reckoning.", "হে দাউদ, আমরা তোমাকে পৃথিবীতে একজন শাসক বানিয়েছি। অতএব, তুমি লোকদের মাঝে ন্যায় বিচার করবে, এবং তোমার ব্যক্তিগত মতের অনুসরণ করো না, পাছে তা তোমাকে আল্লাহর পথ থেকে সরিয়ে দেয়। অবশ্যই, যারা আল্লাহর পথ থেকে বিচ্যুত হয় তারা কঠোর শাস্তি টেনে আনে বিচার দিবসকে ভুলে যাবার জন্য।"],
  "38:27": ["We did not create the heaven and the earth and what is between them in vain; that is the thought of those who disbelieve. So woe to those who disbelieve from the Fire.", "আমরা আকাশমন্ডলী ও পৃথিবী, এবং এগুলোর মধ্যকার সবকিছু অনর্থক সৃষ্টি করিনি। যারা অবিশ্বাস করে তাদের চিন্তা-ভাবনা এমনই। অতএব, দূর্ভোগ তাদের প্রতি যারা অবিশ্বাস করে; তারা নরকে ভুগবে।"],
  "38:28": ["Shall We make those who believe and do salih deeds like the corrupters on the earth? Shall We make the mindful like the immoral?", "যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে তাদের সাথে কি আমরা তেমন আচরণ করবো যেমন আচরণ আমরা করি তাদের সাথে যারা পৃথিবীতে মন্দকর্ম করে? আমরা কি সৎকর্মশীলদের সাথে তেমন আচরণ করবো যেমন আচরণ আমরা করি অন্যায়কারীদের সাথে?"],
  "38:29": ["A blessed Book that We have sent down to you, so that they may reflect on its signs, and that people of understanding may remember.", "এটি একটি ঐশীগ্রন্থ যা আমরা তোমার কাছে অবতীর্ণ করেছি- যা পবিত্র - হয়তো তারা এর আয়াতগুলো নিয়ে চিন্তা-ভাবনা করবে। যারা বুদ্ধিমত্তার অধিকারী তারা মনোযোগ দিবে।"],
  "38:30": ["And We granted Sulayman to Dawud — an excellent servant; truly he was ever-turning back.", "আমরা দাঊদকে দান করেছিলাম সোলায়মান, একজন ভালো এবং অনুগত ভৃত্য।"],
  "38:31": ["When there were presented to him at evening the ones standing in rows in stillness, the excellent ones.", "একদিন সে সুন্দর ঘোড়া নিয়ে আচ্ছন্ন হয়ে পড়লো, যতক্ষন না রাত নামলো।"],
  "38:32": ["He said: \"I have loved the love of good over the remembrance of my Rabb, until it vanished behind the veil.\"", "সে তখন বলল, “আমি আমার প্রভুর উপাসনা উপভোগের চেয়ে পার্থিব বিষয় বেশি উপভোগ করেছিলাম, যতক্ষন না সূর্য ডুবে গেল।"],
  "38:33": ["\"Bring them back to me\" — and he set about stroking the shins and the necks.", "“এগুলোকে ফিরিয়ে আনো।” (বিদায় জানাতে,) সে এগুলোর পা ও ঘাড়ে হাত বুলিয়ে দিল।"],
  "38:34": ["And We tested Sulayman, and cast upon his seat a body; then he turned back.", "আমরা এভাবে সোলায়মানকে পরীক্ষায় ফেলেছিলাম; তাকে প্রচুর পার্থিব সম্পদ দিয়ে আমরা অনুগ্রহ করেছিলাম, কিন্তু সে দৃড়ভাবে সমর্পিত ছিল।"],
  "38:35": ["He said: \"My Rabb, forgive me, and grant me a kingdom not fitting for anyone after me; truly You are the Grantor.\"", "সে বলল, “আমার প্রভু, আমাকে ক্ষমা করুন, এবং আমাকে একটি রাজত্য দিন যা কখনো কারো দ্বারা অর্জিত হয়নি। আপনি মঞ্জুরকারী।”"],
  "38:36": ["So We subjected to him the wind, running at his command, gently, wherever it turned.", "আমরা (তার প্রার্থনায় সাড়া দিয়েছিলাম এবং) বাতাসকে তার আজ্ঞাবহ করলাম, সে যেখানেই চাইতো বৃষ্টি পতিত হতো।"],
  "38:37": ["And the devils — every builder and diver.", "আর শয়তানরা, নির্মান করতো এবং ডুব দিতো।"],
  "38:38": ["And others, bound together in fetters.", "অন্যদেরকে তার আয়ত্তাধীনে রাখা হয়েছিল।"],
  "38:39": ["This is Our gift; so give unstintingly, or withhold, without reckoning.", "“এটি তোমার প্রতি আমাদের জীবিকা; তুমি উদারভাবে দিতে পারো, অথবা বিরত থাকতে পারো, সীমাহীনভাবে।”"],
  "38:40": ["And truly with Us he has near access and a good return.", "সে আমাদের সাথে একটি সম্মানিত অবস্থানের, এবং একটি চমৎকার আবাসের যোগ্য হয়েছে।"],
  "38:41": ["And remember Our servant Ayyub, when he called to his Rabb: \"The devil has touched me with toil and torment.\"", "স্মরণ করো আমাদের বান্দা আইয়ুবের কথা: সে তার প্রভুকে ডেকেছিল, “শয়তান আমাকে দুর্দশাগ্রস্থ করেছে অসচ্ছলতা ও যন্ত্রণা দিয়ে।”"],
  "38:42": ["Strike with your foot: here is a cool bathing-place and a drink.", "“তোমার পা দিয়ে ভূমিতে আঘাত করো। একটি ঝর্ণা তোমাকে নিরাময় এবং পানীয় দিবে।”"],
  "38:43": ["And We granted him his family, and the like of them with them, as a mercy from Us, and a reminder for people of understanding.", "আমরা তার জন্য তার পরিবারকে ফিরিয়ে দিলাম; দ্বিগুন করে। এমনই আমাদের দয়া; যারা বুদ্ধিমত্তার অধিকারী তাদের জন্য একটি স্মারক।"],
  "38:44": ["And take a bundle in your hand, and strike with it, and do not swear falsely. We found him sabir — an excellent servant; truly he was ever-turning back.", "“এখন, তুমি ভূখন্ডে ভ্রমণ করবে এবং বার্তা প্রচার করবে, তোমার অঙ্গীকার পূর্ণ করতে।” আমরা তাকে দৃড় পেয়েছিলাম। কতই না ভাল বান্দা! সে ছিল একজন আত্মসমর্পণকারী।"],
  "38:45": ["And remember Our servants Ibrahim and Ishaq and Yaqub, possessors of strength and vision.", "আরো স্মরণ করো আমাদের বান্দা ইব্রাহিম, ইসহাক এবং ইয়াকুবকে। তারা ছিল প্রাচুর্যশালী, এবং অন্তর্দৃষ্টিসম্পন্ন।"],
  "38:46": ["We made them devoted, with an exclusive remembrance of the Home.", "আমরা তাদেরকে দান করেছিলাম এক মহা অনুগ্রহ: পরকালের সচেতনতা।"],
  "38:47": ["And truly with Us they are among the chosen, the best.", "তারা ছিল পছন্দকৃত, কারণ তারা ছিল সর্বাধিক সৎকর্মশীলদের অন্তর্ভূক্ত।"],
  "38:48": ["And remember Ismail and Al-Yasa and Dhu'l-Kifl — each among the best.", "স্মরণ করো ইসমাইল, ইয়াসা, এবং যুলকিফলকে; সর্বাধিক সৎকর্মশীলদের মাঝে।"],
  "38:49": ["This is a reminder; and truly the mindful have a good return.", "এটি একটি স্মারক: সৎকর্মশীলরা এক চমৎকার নিয়তির অর্জন করেছে।"],
  "38:50": ["Gardens of Eden, opened wide to them are the doors.", "ইডেনের বাগানগুলো তাদের জন্য দরজা খুলে দেবে।"],
  "38:51": ["Reclining therein, they are called therein to abundant fruit and drink.", "সেখানে আরাম করা অবস্থায়, তাদেরকে নানা রকম ফল এবং পানীয় দেয়া হবে।"],
  "38:52": ["And with them are those who restrain their glances, age-mates alike.", "তাদের থাকবে চমৎকার সঙ্গী।"],
  "38:53": ["This is what you were promised for the Day of Reckoning.", "এরই যোগ্য তোমরা হয়েছ হিসাবের দিনে।"],
  "38:54": ["Truly this is Our provision; it has no end.", "আমাদের জীবিকা অফুরন্ত।"],
  "38:55": ["This — and truly the transgressors have an evil return.", "সীমালঙ্ঘনকারীদের ক্ষেত্রে, তারা টেনে এনেছে এক শোচনীয় নিয়তি।"],
  "38:56": ["Hell, which they enter — how evil a resting-place!", "নরক হচ্ছে সে জায়গা যেখানে তারা পুড়বে; কি এক শোচনীয় আবাস!"],
  "38:57": ["This, then let them taste it: scalding water and ice.", "সেখানে তারা যা আস্বাদন করবে তা হবে নারকীয় পানীয় এবং তিক্ত খাদ্য।"],
  "38:58": ["And others of its kind, in pairs.", "এবং এই রকমের আরো অনেক কিছু।"],
  "38:59": ["Here is a host rushing in with you. No welcome to them; they enter the Fire.", "“এটি একটি দল যাদেরকে তোমাদের সাথে নিক্ষেপ করা হবে।” তারা (নরকের বাসিন্দাদের দ্বারা) সাদরে গৃহীত হবে না। তারা নরকাগ্নিতে পোড়ার যোগ্য।"],
  "38:60": ["They say: \"No — you: no welcome to you! You brought it upon us. How evil a settled place!\"", "নবাগতরা উত্তর দিবে, “তোমরাও সাদরে গৃহীত নও। তোমরাই তো আমাদের পূর্ববর্তী ছিলে এবং আমাদেরকে পথভ্রষ্ট করেছো। অতএব, এই শোচনীয় সমাপ্তি ভোগ করো।"],
  "38:61": ["They say: \"Our Rabb, whoever brought this upon us, increase for them a doubled punishment in the Fire.\"", "তারা আরো বলবে, “আমাদের প্রভু, এরাই সে ব্যক্তি যারা আমাদেরকে এর মাঝে পরিচালিত করেছিল; তাদের জন্য নরকাগ্নির শাস্তি দ্বিগুন করে দিন।”"],
  "38:62": ["And they say: \"Why do we not see men whom we used to count among the evil ones?\"", "তারা বলবে, “কেমন করে আমরা (নরকে) সে লোকদের দেখছি না যাদেরকে আমরা অন্যায়কারীদের সাথে গুনতাম?"],
  "38:63": ["Did we take them as a laughing-stock, or have their eyes swerved from them?", "\"আমরা তাদেরকে উপহাস করতাম; আমরা তাদের থেকে আমাদের চোখ ফিরিয়ে নিতাম।”"],
  "38:64": ["Truly that is the truth: the people of the Fire disputing with one another.", "এটি একটি পূর্বনির্ধারিত সত্য: নরকের লোকেরা একে অন্যের সাথে বিবাদ করবে।"],
  "38:65": ["Say: \"I am only a warner, and there is no ilah but Allah, the One, the Overpowering.\"", "বল, “আমি তোমাদের সতর্ক করি; আল্লাহর পাশে অন্যকোন উপাস্য নেই, একক, সর্বোচ্চ।"],
  "38:66": ["Rabb of the heavens and the earth and what is between them, the Mighty, the Forgiving.", "“আকাশমণ্ডলী ও পৃথিবী, এবং এদের মধ্যকার সবকিছুর প্রভু; সর্বশক্তিমান, ক্ষমাকারী।”"],
  "38:67": ["Say: \"It is a mighty tiding.\"", "বল, “এখানে এক মহা সংবাদ আছে।"],
  "38:68": ["You are turning away from it.", "“যাতে তোমরা সম্পূর্ণ অন্যমনস্ক।"],
  "38:69": ["I had no knowledge of the Highest Assembly when they disputed.", "“উর্ধ সমাজের (মালা-ইল-আলা) বিবাদ সম্বন্ধে পূর্বে আমার কোন জ্ঞান ছিল না৷”"],
  "38:70": ["Nothing is revealed to me except that I am a clear warner.", "“আমি প্রত্যাদেশপ্রাপ্ত যে আমার একমাত্র দায়িত্ব তোমাদের কাছে সতর্কবানী পৌছে দেয়া।”"],
  "38:71": ["When your Rabb said to the malakat: \"I am creating a human from clay.\"", "তোমার প্রভু ফেরেশতাদের বললেন, “আমি কাদামাটি থেকে একজন মানুষ সৃষ্টি করছি।"],
  "38:72": ["And when I have proportioned him and breathed into him of My spirit, then fall down to him prostrating.", "“আমি তার নকশা করলে, এবং আমার রুহ থেকে তার মধ্যে ফুকে দিলে, তোমরা তার সামনে সেজদাবনত হবে।”"],
  "38:73": ["And the malakat prostrated, all of them together.", "ফেরেশতারা সেজদায় পড়েছিল, তাদের সকলে,"],
  "38:74": ["Except Iblis; he grew proud, and was among the kafirin.", "শয়তান ছাড়া; সে প্রত্যাখান করছিল, এবং অত্যন্ত ঔদ্ধত, অকৃতজ্ঞ ছিল।"],
  "38:75": ["Allah said: \"O Iblis, what kept you from prostrating to what I created with My hands? Were you proud, or were you among the exalted?\"", "তিনি বল্লেন, “হে শয়তান, কিসে তোমাকে তার সামনে সেজদা করা থেকে বিরত রেখেছে যাকে আমি আমার নিজ হাতে সৃষ্টি করেছি? তুমি কি খুব উদ্ধত? তুমি কি বিদ্রোহ করছো?”"],
  "38:76": ["He said: \"I am better than him: You created me from fire, and created him from clay.\"", "সে বলল, “আমি তার চেয়ে উত্তম; আপনি আমাকে আগুন থেকে সৃষ্টি করেছেন, এবং তাকে সৃষ্টি করেছেন কাদামাটি থেকে।”"],
  "38:77": ["Allah said: \"Then get out of it — you are cast out.\"", "তিনি বললেন, “একারণে, তুমি অবশ্যই নির্বাসিত হবে, তুমি বিতাড়িত হবে।"],
  "38:78": ["And My curse is upon you until the Day of Judgment.", "“তুমি বিচার দিবস পর্যন্ত আমার অভিশাপ টেনে এনেছ।”"],
  "38:79": ["He said: \"My Rabb, grant me respite until the day they are raised.\"", "সে বলল, “আমার প্রভু, পূনরুত্থান দিবস পর্যন্ত আমাকে অবকাশ দিন।”"],
  "38:80": ["Allah said: \"Then you are among the respited.\"", "তিনি বললেন, “তোমাকে অবকাশ দেয়া হল।"],
  "38:81": ["Until the known appointed time.", "“নির্ধারিত দিন পর্যন্ত।”"],
  "38:82": ["He said: \"Then by Your might, I will surely mislead them all.\"", "সে বলল, “আমি আপনার মহিমার শপথ করছি, যে আমি তাদের সকলকে পথভ্রষ্ট করবো।"],
  "38:83": ["Except Your devoted servants among them.", "\"আপনার উপাসনাকারীদের ব্যতীত যারা সম্পূর্ণরূপে একমাত্র আপনার প্রতি নিবেদিত।”"],
  "38:84": ["Allah said: \"Then the truth — and the truth I speak:\"", "তিনি বললেন, “এটাই সত্য, এবং সত্য হল সবই যা আমি বলি।"],
  "38:85": ["I will surely fill Hell with you, and with those of them who follow you, all together.", "\"আমি তোমাকে এবং যারা তোমার অনুসরণ করে তাদের সবাইকে দিয়ে নরক পূর্ণ করবো।”"],
  "38:86": ["Say: \"I ask you no reward for it, and I am not one of those who take on burdens.\"", "বল, “আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না, এবং আমি কোন ছদ্মবেশী নই।"],
  "38:87": ["It is nothing but a reminder for the worlds.", "“এটি বিশ্বের জন্য একটি স্মারক।"],
  "38:88": ["And you will surely know its account after a while.", "“এবং তোমরা অবশ্যই অল্প সময়ের মধ্যে বুঝতে পারবে।”"],
  "39:1": ["The sending down of the Book from Allah, the Almighty, the Wise.", "এটি ঐশীগ্রন্থের একটি প্রত্যাদেশ সর্বশক্তিমান, প্রজ্ঞাময় আল্লাহর পক্ষ থেকে।"],
  "39:2": ["Indeed, We have sent down to you the Book with truth; so worship Allah, devoting the religion exclusively to Allah.", "আমরা তোমার কাছে এই ঐশীগ্রন্থ অবতীর্ণ করেছি,সত্য নিষ্ঠার সঙ্গে; তুমি আল্লাহর উপাসনা করবে,তোমার ধর্মকে একমাত্র তাঁর প্রতি উৎসর্গ করে।"],
  "39:3": ["Indeed, devoted religion is for Allah. And those who have taken protectors besides Allah say: \"We worship them only so that they may bring us near to Allah by nearness.\" Indeed, Allah judges between them in that over which they differ. Indeed, Allah does not guide one who is a lying kafir.", "নিঃসন্দেহে, ধর্ম একমাত্র আল্লাহর জন্য উৎসর্গকৃত হবে। যারা তাঁর পাশে উপাস্য স্থাপন করে তারা বলে,“আমাদেরকে আল্লাহর নিকটে আনার জন্যই শুধু তাদেরকে আমরা শরিক বানাই; কারণ তারা এক উত্তম অবস্থানে রয়েছে!” তাদের বিতর্কের বিষয়ে আল্লাহ তাদের বিচার করবেন। আল্লাহ এমন মিথ্যাবাদী,অবিশ্বাসীদের পথ দেখান না।"],
  "39:4": ["If Allah willed to take a son, Allah would have chosen, from what Allah creates, whatever Allah wills. Glory be to Allah! Allah is the One, the Overpowering.", "যদি আল্লাহ কোণ পুত্র চাইতেন, তিনি তাঁর সৃষ্টি থেকে যাকেই চাইতেন পছন্দ করতে পারতেন। মহিমা তাঁরই; তিনি আল্লাহ, একক স্বত্বা,সর্বোচ্চ।"],
  "39:5": ["Allah created the heavens and the earth with truth; Allah wraps the night over the day and wraps the day over the night, and subjected the sun and the moon, each running for an appointed term. Indeed, Allah is the Almighty, the Forgiving.", "তিনি আকাশমণ্ডলী এবং পৃথিবী সৃষ্টি করেছেন সত্য নিষ্ঠার সঙ্গে।তিনি রাতকে দিনের উপর গড়িয়ে দেন, এবং দিনকে রাতের উপর গড়িয়ে দেন। তিনি সূর্য এবং চাঁদকে নিয়োজিত করেছেন, প্রত্যেকে চলছে একটি সুনির্ধারিত মেয়াদের জন্য। নিঃসন্দেহে,তিনি সর্বশক্তিমান, ক্ষমাশীল।"],
  "39:6": ["Allah created you from a single soul, then made from it its mate, and sent down for you from the livestock eight pairs. Allah creates you in the bellies of your mothers, creation after creation, in three darknesses. That is Allah, your Rabb; to Allah belongs dominion. There is no ilah but Allah. So where do you turn away?", "তিনি তোমাদেরকে এক ব্যক্তি থেকে সৃষ্টি করেছেন, তারপর তার থেকে সৃষ্টি করেছেন তার সঙ্গিনীকে। তিনি তোমাদের প্রতি আট প্রকার পালিত-পশু অবতীর্ণ করেছেন। তিনি তোমাদের সৃষ্টি করেন তোমাদের মায়ের পেটে,সৃষ্টির পর সৃষ্টি,তিন ধাপ অন্ধকারের মধ্যে। এমনই আল্লাহ তোমাদের প্রভু। তাঁর অধীনেই রয়েছে সকল সার্বভৌমত্ব। তাঁর পাশে অন্য কোন উপাস্য নেই। কি করে তোমরা পথভ্রষ্ট হতে পার?"],
  "39:7": ["If you disbelieve, indeed Allah has no need of you, and Allah is not pleased with disbelief for the servants; but if you are grateful, Allah is pleased with it for you. No burden-bearer bears the burden of another. Then to your Rabb is your return, and Allah will inform you of what you used to do. Indeed, Allah is knowing of what is in the hearts.", "যদি তোমরা অবিশ্বাস কর, আল্লাহর কাউকে প্রয়োজন নেই। কিন্তু তিনি তাঁর বান্দাদের ভুল সিদ্ধান্ত নেওয়া দেখতে অপছন্দ করেন। কোন আত্মা অন্য কোন আত্মার পাপ বহন করে না। অবশেষে,তোমাদের প্রভুর কাছেই তোমাদের ফিরে যাওয়া,তখন তিনি তোমাদের সবকিছু জানাবেন যা তোমরা করেছিলে। তিনি গভীরতম চিন্তাগুলো সম্পর্কে পুরোপুরি অবগত।"],
  "39:8": ["And when harm touches a human, he calls his Rabb, turning back to Allah; then when Allah bestows on him a blessing from Allah, he forgets what he used to call upon before, and sets up equals to Allah, to lead astray from the way of Allah. Say: \"Enjoy your disbelief a little; indeed you are among the companions of the Fire.\"", "যখন মানুষ দূর্দশাগ্রস্থ হয়, সে তার প্রভুর কাছে মিনতি করে,আন্তরিকভাবে তাঁর প্রতি নিবেদিত হয়ে। কিন্তু তিনি তাকে অনুগ্রহ করা মাত্রই, সে তার পূর্বের মিনতি ভুলে যায়, উপাস্য স্থাপন করে আল্লাহর সাথে সমকক্ষ করতে এবং অন্যদেরকে তাঁর পথ থেকে বিচ্যুত করতে। বল, “তোমাদের অবিশ্বাসকে কিছুকাল ভোগ করে নাও; তোমরা টেনে এনেছ নরকাগ্নি।”"],
  "39:9": ["Is one who is devout during the hours of the night, prostrating and standing, bewareful of the Hereafter and hoping for the mercy of his Rabb? Say: \"Are those who know equal to those who do not know?\" Only the people of understanding remember.", "এটা কি উত্তম নয় তাদের একজন হওয়া যারা রাতে ধ্যান করে, সেজদা করে এবং জেগে থাকে, পরকালের বিষয়ে সচেতন হয়ে, এবং তাদের প্রভুর দয়া অন্বেষণ করে? বল, “যারা জানে তারা কি তাদের সমান যারা জানে না?”কেবল যারা বুদ্ধিমত্তার অধিকারী তারাই মনোযোগ দেবে।"],
  "39:10": ["Say: \"O My servants who believe, be mindful of your Rabb. For those who do good in this world is good, and the earth of Allah is spacious. Indeed, the sabirin are paid their reward in full without reckoning.\"", "বল, “হে,আমার বান্দারা যারা বিশ্বাস করেছ, তোমরা তোমাদের প্রভুকে ভক্তি করবে।” যারা এই দুনিয়ায় সৎকর্ম করবে তাদের জন্য, এক ভালো পুরস্কার। আল্লাহর পৃথিবী প্রশস্ত, এবং যারা দৃঢ়তার সাথে অধ্যবসায়ী তারা তাদের প্রতিফল উদারভাবে পাবে, অফুরুন্ত।"],
  "39:11": ["Say: \"Indeed, I am commanded to worship Allah, devoting the religion exclusively to Allah.\"", "বল, “আমি আদেশপ্রাপ্ত হয়েছি আল্লাহর উপাসনা করতে, ধর্মকে সম্পূর্ণরূপে একমাত্র তাঁর প্রতি উৎসর্গ করে।"],
  "39:12": ["And I am commanded to be the first of those who submit.", "“এবং আমি আদেশপ্রাপ্ত হয়েছিলাম সর্বাধিক আত্মসমর্পণকারী হতে।”"],
  "39:13": ["Say: \"Indeed, I fear, if I disobey my Rabb, the punishment of a great day.\"", "বল, “আমি ভয় করি, যদি আমি আমার প্রভুকে অমান্য করি, এক মহা দিনের শাস্তিকে।”"],
  "39:14": ["Say: \"Allah I worship, devoting my religion exclusively to Allah.\"", "বল, “আল্লাহই একমাত্র সত্ত্বা যার উপাসনা আমি করি,আমার ধর্মকে সপুরোপুরি একমাত্র তাঁর প্রতি উৎসর্গ করে।"],
  "39:15": ["So worship what you wish besides Allah. Say: \"Indeed, the khasirin are those who lose themselves and their families on the Day of Resurrection. Truly, that is the clear loss.\"", "“অতএব, তাঁর পাশে যা কিছুকে তোমাদের ইচ্ছা উপাসনা করো।” বল, “প্রকৃত ক্ষতিগ্রস্ত তারাই পুনরুত্থান দিনে যারা তাদের আত্মা, এবং তাদের পরিবার হারিয়েছে।” সুনিশ্চিতভাবে,এটাই আসল ক্ষতি।"],
  "39:16": ["For them are, from above them, canopies of fire and from beneath them canopies. With this Allah warns the servants of Allah. O My servants, be mindful of Me.", "তাদের উপরে এবং তাদের নিচে আগুনের পিণ্ড থাকবে। আল্লাহ এভাবে তাঁর বান্দাদের সতর্ক করেনঃ হে আমার বান্দারা,তোমরা আমাকে ভক্তি করবে।"],
  "39:17": ["And those who avoid the false arbiter so as not to worship it, and turn back to Allah — for them is the glad news. So give glad news to My servants.", "তাদের ক্ষেত্রে যারা সকল উপাস্যের উপাসনা পরিত্যাগ করে, এবং নিজেদেরকে পুরোপুরি একমাত্র আল্লাহর প্রতি উৎসর্গ করে, তারা সুখ পাওয়ার উপযুক্ত হয়েছে। আমার বান্দাদের সুসংবাদ দাও।"],
  "39:18": ["Those who listen to the word and follow the best of it — those are the ones Allah has guided, and those are the people of understanding.", "তারা হল সেই ব্যক্তি যারা সকল বানী পরীক্ষা করে, তারপর সর্বোৎকৃষ্টটি অনুসরণ করে। এরাই সে ব্যক্তি যাদেরকে আল্লাহ পথ- প্রদর্শন করেছেন; এরাই সে ব্যক্তি যারা বুদ্ধিমত্তার অধিকারী।"],
  "39:19": ["So is one upon whom the word of punishment has become due — can you rescue one who is in the Fire?", "তাদের সম্পর্কে যারা শাস্তির উপযুক্ত হয়েছে, তুমি কি তাদের রক্ষা করতে পার যারা ইতোমধ্যেই নরকে রয়েছে?"],
  "39:20": ["But those who were mindful of their Rabb — for them are chambers, and above them chambers built, with rivers flowing beneath them. A promise of Allah; Allah does not fail the promise.", "তাদের ক্ষেত্রে যারা তাদের প্রভুকে ভক্তি-শ্রদ্ধা করে, তাদের জন্য প্রাসাদের উপর প্রাসাদ নির্মিত থাকবে, প্রবাহিত ঝর্ণাসহ। এটা আল্লাহর অঙ্গীকার, এবং আল্লাহ কখনো তাঁর অঙ্গীকার ভঙ্গ করেন না।"],
  "39:21": ["Do you not see that Allah sends down from the sky water, and threads it through as springs in the earth, then brings out with it crops of differing colors; then it withers and you see it yellowed; then Allah makes it crumbled chaff. Indeed, in that is a reminder for people of understanding.", "তুমি কি দেখ না যে আল্লাহ আকাশ থেকে পানি বর্ষণ করেন, তারপর একে ভূগর্ভস্থ কূপে রাখেন, এরপর তা দ্বারা উৎপাদন করেন বিভিন্ন রঙের গাছপালা, এরপর তারা বাড়তে থাকে হলুদ হয়ে যাওয়া পর্যন্ত, এরপর তিনি তাদেরকে খড়কুটো করে দেন? এটি তাদের জন্য একটি স্মারক হওয়া উচিৎ যাদের বুদ্ধিমত্তা আছে।"],
  "39:22": ["So is one whose chest Allah has opened to submission, so that he is upon a light from his Rabb? Woe to those whose hearts are hardened against the remembrance of Allah. Those are in clear error.", "যদি আল্লাহ কারো হৃদয়কে আত্মসমর্পনে সন্তুষ্ট রাখেন, সে অনুসরণ করতে থাকবে তার প্রভুর পক্ষ থেকে একটি আলো। অতএব, তাদের জন্য দুর্ভাগ্য যাদের হৃদয় আল্লাহর বার্তার বিপক্ষে কঠিন; তারা বহুদূরে পথভ্রষ্ট।"],
  "39:23": ["Allah has sent down the best hadith as a book, consistent and oft-repeated; the skins of those who stand in awe of their Rabb shiver from it, then their skins and their hearts soften toward the remembrance of Allah. That is the guidance of Allah; with it Allah guides whom Allah wills. And whomever Allah leaves astray, for them there is no guide.", "আল্লাহ এর মধ্যে প্রকাশ করেছেন সর্বোৎকৃষ্ট হাদিস; একটি গ্রন্থ যা সামঞ্জস্যপূর্ণ, এবং নির্দেশ করে উভয় পথ (স্বর্গ ও নরক)। যারা তাদের প্রভুকে ভক্তি-শ্রদ্ধা করে তাদের চামড়া তা থেকে শিহরিত হয়, এরপর তাদের চামড়া এবং তাদের হৃদয় আল্লাহর বার্তার জন্য নরম হয়। এমনই আল্লাহর পথনির্দেশনা। যার উপর ইচ্ছা তিনি তা অর্পণ করেন। তাদের ক্ষেত্রে যারা আল্লাহ দ্বারা পথভ্রষ্ট, কোনকিছুই তাদের পথ-প্রদর্শন করতে পারে না।"],
  "39:24": ["So can one shield, with their face, from the evil of punishment on the Day of Resurrection? And it will be said to the wrongdoers: \"Taste what you used to earn.\"", "পুনরুত্থান দিনে কারো মুখমন্ডলকে ভয়ঙ্কর শাস্তি থেকে রক্ষা পাওয়া থেকে উত্তম আর কি হতে পারে? সীমালঙ্ঘনকারীদের বলা হবে, “তোমরা যা অর্জন করেছ তার পরিণাম আস্বাদন করো।\""],
  "39:25": ["Those before them denied, so the punishment came to them from where they did not perceive.", "তাদের পূর্বে অন্যরা অবিশ্বাস করেছে এবং, ফলস্বরূপ, শাস্তি তাদের দুর্দশাগ্রস্থ করেছে যেখান থেকে তারা কখনো আশাই করেনি।"],
  "39:26": ["So Allah made them taste disgrace in the life of this world; and the punishment of the Hereafter is greater, if only they knew.", "আল্লাহ তাদের অভিশপ্ত করেছেন এই জীবনে অপমানিত করে, এবং পরকালের শাস্তি হবে আরো অধিকতর মন্দ, যদি শুধু তারা জানতো।"],
  "39:27": ["And We have set forth for people in this Quran every example, so that they may remember.", "আমরা লোকদের জন্য এই কুরআনে সকল প্রকার উদাহরণ উদ্ধৃত করেছি, যাতে তারা সতর্ক হতে পারে।"],
  "39:28": ["An Arabic Quran, without crookedness, so that they may be mindful.", "একটি আরবি কুরআন, কোন অস্পষ্টতা ছাড়াই, যাতে তারা সৎকর্মশীল হতে পারে।"],
  "39:29": ["Allah sets forth an example: a man with quarreling partners, and a man wholly devoted to a single man — are the two equal as an example? Praise belongs to Allah. Rather, most of them do not know.", "আল্লাহ এক লোকের উদাহরণ দেন যে বিরোধপূর্ণ অংশীদারদের (হাদিস) সাথে কারবার করে, সে লোকের তুলনায় যে কারবার করে শুধু একটি সামঞ্জস্যপূর্ণ উৎসের (কুরআনের) সাথে। তারা কি একই রকম? প্রশংসা আল্লাহর; তাদের বেশিরভাগই জানে না।"],
  "39:30": ["Indeed, you will die, and indeed, they will die.", "তুমি (মুহাম্মদ) অবশ্যই মারা যাবে, ঠিক যেমন তারা মারা যাবে।"],
  "39:31": ["Then indeed, on the Day of Resurrection, before your Rabb, you will dispute.", "পুনরুত্থানের দিনে, তোমাদের প্রভুর সামনে, তোমরা পরস্পর বিবাদ করবে।"],
  "39:32": ["So who is more wrong than one who lies about Allah and denies the truth when it comes to him? Is there not in Hell a lodging for the kafirin?", "তার থেকে অধিক মন্দ আর কে যে আল্লাহর প্রতি মিথ্যা আরোপ করে, এবং অবিশ্বাস করে সে সত্যে যা তার কাছে এসেছে? নরক কি অবিশ্বাসীদের জন্য সঠিক প্রতিফল নয়?"],
  "39:33": ["And the one who brought the truth and confirmed it — those are the mindful.", "তাদের ক্ষেত্রে যারা সত্যকে তুলে ধরে, এবং তাতে বিশ্বাস করে, তারাই হল সৎকর্মশীল।"],
  "39:34": ["For them is whatever they wish with their Rabb. That is the recompense of the good-doers.", "তারা যা আকাঙ্ক্ষা করবে সবকিছুই পাবে, তাদের প্রভুর কাছে। সৎকর্মশীলদের জন্য এটাই পুরস্কার।"],
  "39:35": ["So that Allah may wipe away from them the worst of what they did, and recompense them their reward with the best of what they used to do.", "আল্লাহ তাদের পাপপূর্ণ কাজগুলোকে মোচন করে দেন, এবং তাদের ভালো কাজের জন্য তাদেরকে উদারভাবে পুরস্কৃত করেন।"],
  "39:36": ["Is not Allah sufficient for the servant of Allah? Yet they frighten you with those besides Allah. And whomever Allah leaves astray, for them there is no guide.", "আল্লাহ কি তাঁর বান্দার জন্য যথেষ্ট নয়? তারা তোমাকে ভয় দেখায় আল্লাহর পাশে তাদের স্থাপন করা উপাস্যদের দিয়ে। যাকে আল্লাহ পথভ্রষ্ট করেন, কোনকিছুই তাকে পথ প্রদর্শন করতে পারে না।"],
  "39:37": ["And whomever Allah guides — for them there is no misleader. Is not Allah the Almighty, the Rabb of requital?", "এবং যাকে আল্লাহ পথ প্রদর্শন করেন, কোনকিছুই তাকে পথভ্রষ্ট করতে পারে না। আল্লাহ কি সর্বশক্তিমান, প্রতিশোধগ্রহণকারী নন?"],
  "39:38": ["And if you ask them who created the heavens and the earth, they will surely say: \"Allah.\" Say: \"Have you considered what you call upon besides Allah? If Allah should intend harm for me, can they remove the harm from me? Or if Allah should intend mercy for me, can they hold back from me the mercy of Allah?\" Say: \"Allah is sufficient for me. Upon Allah rely those who rely.\"", "যদি তুমি তাদের জিজ্ঞাসা করো, “কে আকাশমন্ডলী এবং পৃথিবী সৃষ্টি করেছে?” তারা বলবে, “আল্লাহ।” বল, “কেন তবে তোমরা আল্লাহর পাশে উপাস্যদের স্থাপন করো? যদি আল্লাহ আমার জন্য কোন দুর্দশা চান, তারা কি এমন দুর্দশা লাঘব করতে পারে? এবং তিনি যদি আমার জন্য কল্যান চান, তারা কি এমন কল্যান আটকাতে পারে?’’ বল, ‘আল্লাহ আমার জন্য যথেষ্ট।” তাঁরই প্রতি আস্থাশীলদের আস্থা রাখা উচিত।"],
  "39:39": ["Say: \"O my people, act according to your station; indeed, I am acting. Soon you will know.\"", "বল, “হে আমার লোকেরা, তোমাদের সর্বোত্তমটি করো আর আমি আমার সর্বোত্তমটি করবো; তোমরা অবশ্যই দেখতে পাবে।"],
  "39:40": ["Who is it that punishment will come to, disgracing them, and a lasting punishment will descend upon them?", "“(তোমরা দেখতে পাবে) কে টেনে এনেছে নিজের লজ্জাজনক শাস্তি, এবং যোগ্য হয়েছে এক চিরস্থায়ী শাস্তির।”"],
  "39:41": ["Indeed, We have sent down upon you the Book for people, with truth. So whoever is guided — it is for their own soul; and whoever goes astray — they go astray only against their own soul. And you are not over them a guardian.", "আমরা তোমার মাধ্যমে মানুষের জন্য ঐশী-গ্রন্থ প্রকাশ করেছি, সত্যসহকারে। অতপর, যেকেউ সুপথপ্রাপ্ত হয় সে তার নিজের ভালোর জন্যই সুপথপ্রাপ্ত হয়, এবং যেকেউ বিপথে যায় সে বিপথে যেয়ে তার নিজেরই ক্ষতি করে। তুমি তাদের উকিল নও।"],
  "39:42": ["Allah takes the souls at the time of their death, and those that have not died, in their sleep. Then Allah holds the soul on which death has been decreed, and sends the others back until an appointed term. Indeed, in that are signs for people who reflect.", "ঈশ্বর আত্মাদের মৃত্যু দেন যখন তাদের জীবনের শেষ হয়, এবং ঘুমের সময় ও। এভাবে, তিনি কতককে ফিরিয়ে নেন তাদের ঘুমের মধ্যে, এবং অন্যরা জীবিত থাকার অনুমতি পায় তাদের পূর্ব নির্ধারিত সময় কালের শেষ পর্যন্ত। এটা সেসব লোকদের জন্য শিক্ষা হওয়া উচিৎ যারা ভেবে দেখে।"],
  "39:43": ["Or have they taken intercessors besides Allah? Say: \"Even though they possess nothing and do not reason?\"", "তারা কি তাদের এবং ঈশ্বরের মঝে মধ্যস্থতা করার জন্য সুপারিশকারী উদ্ভাবন করেছে? বল, “যদি এমন হয় যে তাদের কোন ক্ষমতা বা বোধশক্তি নেই?”"],
  "39:44": ["Say: \"All intercession belongs to Allah. To Allah belongs the dominion of the heavens and the earth; then to Allah you will be returned.\"", "বল, “সকল সুপারিশ ঈশ্বরের অধীনে।” তাঁর অধীনেই রয়েছে আকাশ মণ্ডলী এবং পৃথিবীর সকল সার্বভৌমত্ব, এরপর তাঁর কাছেই তোমারা ফিরে যাবে।"],
  "39:45": ["And when Allah alone is mentioned, the hearts of those who do not believe in the Hereafter shrink with aversion; and when those besides Allah are mentioned, at once they rejoice.", "যখন শুধু মাত্র ঈশ্বরকে উল্লেখ করা হয়, যারা পরকালে বিশ্বাস করে না তাদের হৃদয় বিমুখতায় সঙ্কুচিত হয়ে যায়। কিন্তু যখন তাঁর পাশে অন্যদের উল্লেখ করা হয়, তখন তারা সন্তুষ্ট হয়।"],
  "39:46": ["Say: \"O Allah, Originator of the heavens and the earth, Knower of the unseen and the seen, You judge between Your servants in that over which they differ.\"", "ঘোষণা করঃ “আমাদের উপাস্য, আকাশমণ্ডলী ও পৃথিবীর সূচনাকারী, সকল গোপন এবং প্রকাশ্য বিষয়ের জ্ঞাতা, আপনিই একমাত্র সত্ত্বা যিনি তাঁর বান্দাদের মধ্যে বিচার করবেন তাঁদের বিবাদের বিষয়ে।”"],
  "39:47": ["And if those who did wrong had all that is in the earth and the like of it besides, they would offer it as ransom from the evil of punishment on the Day of Resurrection. And there appeared to them from Allah what they did not reckon.", "যারা সীমালঙ্ঘন করেছে তারা যদি পৃথিবীর সবকিছুর মালিক হয়, এমনকি এর দিগুন পরিমাণের, তারা তৎক্ষণাৎ তা দিয়ে দিবে পুনরুত্থান দিনের ভয়ানক শাস্তি এড়াতে। ঈশ্বর কর্তৃক তাদেরকে দেখানো হবে যা তারা কখনই আশা করেনি।"],
  "39:48": ["And the evil of what they earned appeared to them, and there befell them that which they used to mock.", "তাদেরকে পাপপূর্ণ কাজগুলো দেখানো হবে যা তারা অর্জন করেছিলো,এবং যে জিনিসকে তারা উপহাস করতো সেগুলোই তাদেরকে হানা দিতে ফিরে আসবে।"],
  "39:49": ["So when harm touches a human, he calls Us; then when We bestow on him a blessing from Us, he says: \"I was given it only because of knowledge.\" Rather, it is a trial, but most of them do not know.", "যদি মানুষকে দুর্দশা স্পর্শ করে, সে আমাদের কাছে মিনতি করে, কিন্তু আমরা তার প্রতি কোন অনুগ্রহ দান করা মাত্রই, সে বলে,“আমি এটা পেয়েছি আমার চতুরতার কারনে!” নিশ্চয়, এটি কেবলমাত্র একটি পরীক্ষা, কিন্তু তাদের বেশির ভাগই জানে না।"],
  "39:50": ["Those before them said the same, but what they used to earn availed them nothing.", "তাদের পূর্বে যারা ছিল তারাও একই রকম বলেছে, এবং তাদের উপার্জন তাদেরকে সমান্যতম সাহায্যও করেনি।"],
  "39:51": ["So the evils of what they earned struck them. And those of these who did wrong — the evils of what they earned will strike them, and they cannot escape.", "তারা ভোগ করেছিলো তাদের মন্দ কাজের পরিণতি। একইভাবে, বর্তমান প্রজন্মদের মধ্যে সীমালঙ্ঘনকারীরা ভোগ করবে তাদের মন্দ কাজের পরিণতি; তারা পালাতে পারবে না।"],
  "39:52": ["Do they not know that Allah spreads out provision for whom Allah wills and measures it? Indeed, in that are signs for people who believe.", "তারা কি উপলব্ধি করে না যে ঈশ্বরই সে সত্ত্বা যিনি যার জন্য পছন্দ করেন জীবিকা বৃদ্ধি করে দেন, আর আটকিয়ে রাখেন? এগুলো লোকদের জন্য শিক্ষা যারা বিশ্বাস করে।"],
  "39:53": ["Say: \"O My servants who have exceeded against themselves, do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Indeed, Allah is the Forgiving, the Raheem.\"", "ঘোষণা করঃ “হে আমার বান্দারা যারা সীমাতিক্রম করেছ, ঈশ্বরের দয়া থেকে কখনো হতাশ হইয়ো না। কারন ঈশ্বর সকল পাপ ক্ষমা করেন। তিনি ক্ষমাকারী, সবচেয়ে দয়ালু।”"],
  "39:54": ["And turn back to your Rabb and submit to Allah before the punishment comes to you; then you will not be helped.", "তোমরা তোমাদের প্রভুকে মান্য করবে, এবং তাঁর কাছে পরিপূর্ণ আত্মসমর্পণ করবে, শাস্তি তোমাদের কাছে আসার আগেই, তখন তোমরা সাহায্য প্রাপ্ত হবে না।"],
  "39:55": ["And follow the best of what has been sent down to you from your Rabb, before the punishment comes to you suddenly while you do not perceive.", "এবং সর্বোত্তম পথ অনুসরণ করো যা তোমাদের জন্য নির্দেশ করা হয়েছে তোমাদের প্রভুর পক্ষ থেকে, শাস্তি তোমাদের কাছে হঠাৎ আসার আগেই যখন তোমরা সামান্যই তা আশা করো।"],
  "39:56": ["Lest a soul say: \"O my regret, for what I fell short in on the side of Allah, and I was indeed among the mockers.\"", "পাছে কোন আত্মা বলে, \"আল্লাহর আদেশ অমান্য করার জন্য আমি কত দুঃখিত! আমি অবশ্যই বিদ্রূপকারীদের একজন ছিলাম।\""],
  "39:57": ["Or lest it say: \"If only Allah had guided me, I would have been among the mindful.\"", "অথবা বলে, \"যদি আল্লাহ আমাকে পথ দেখাতেন, তাহলে আমি অবশ্যই সৎকর্মশীলদের অন্তর্ভুক্ত হতাম।\""],
  "39:58": ["Or lest it say, when it sees the punishment: \"If only I had a return, then I would be among the good-doers.\"", "অথবা যখন এটি শাস্তি দেখে, তখন বলে, \"যদি আমি আবার সুযোগ পাই, আমি সৎকর্ম করব।\""],
  "39:59": ["Yes indeed, My signs came to you, but you denied them and were arrogant, and you were among the kafirin.", "হ্যাঁ মূলত (তুমি যথেষ্ট সুযোগ পেয়েছ)। আমার প্রমাণ তোমার কাছে এসেছিল, কিন্তু তুমি সেগুলো প্রত্যাখ্যান করেছ, অহংকার করেছ এবং অবিশ্বাসী হয়ে গিয়েছিলে।"],
  "39:60": ["And on the Day of Resurrection you will see those who lied about Allah, their faces blackened. Is there not in Hell a lodging for the mutakabbirin?", "যারা আল্লাহর উপর মিথ্যা আরোপ করেছে, পুরুন্থানের দিন তুমি তাদের মুখমণ্ডল দুর্বিষহ দেখতে পাবে। নরক কি অহংকারীদের জন্য উপযুক্ত শাস্তি নয়?"],
  "39:61": ["And Allah will save those who were mindful, with their triumph. Evil will not touch them, nor will they grieve.", "আর যারা সৎকর্ম করেছে, আল্লাহ তাদেরকে রক্ষা করবেন; তিনি তাদেরকে প্রতিদান দেবেন। তাদের কোন ক্ষতি স্পর্শ করবে না এবং তাদের কোন দুঃখও থাকবেনা।"],
  "39:62": ["Allah created everything, and Allah is guardian over everything.", "আল্লাহ সকল কিছুর স্রষ্টা, এবং তিনি সকল কিছুর উপর পূর্ণ নিয়ন্ত্রণ রাখেন।"],
  "39:63": ["To Allah belong the keys of the heavens and the earth. And those who disbelieve in the signs of Allah — those are the khasirin.", "আসমান ও পৃথিবীর সকল সিদ্ধান্ত তাঁরই, আর যারা আল্লাহর প্রত্যাদেশসমূহ অবিশ্বাস করে, তারাই প্রকৃত ক্ষতিগ্রস্ত।"],
  "39:64": ["Say: \"Is it other than Allah that you command me to worship, O ignorant ones?\"", "বল, \"হে অজ্ঞরা, তোমরা কি আমাকে আল্লাহ ব্যতীত অন্যের উপাসনা করতে উৎসাহিত করছো?\""],
  "39:65": ["And it has been revealed to you and to those before you: \"If you associate partners, your work will surely be voided, and you will surely be among the khasirin.\"", "তোমার প্রতি এবং তোমার পূর্ববর্তীদের প্রতি প্রকাশ করা হয়েছে যে, যদি তুমি কখনও প্রতিমা উপাসনা করো, তাহলে তোমার সমস্ত আমল নিষ্ফল হয়ে যাবে এবং তুমি ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হবে।"],
  "39:66": ["Rather, worship Allah and be among the shakirin.", "অতএব, তোমরা একমাত্র আল্লাহর ইবাদত করবে এবং কৃতজ্ঞ হবে।"],
  "39:67": ["And they did not value Allah at the true worth; the whole earth will be in the grasp of Allah on the Day of Resurrection, and the heavens folded in the right hand of Allah. Glory be to Allah, exalted above what they associate.", "তারা কখনোই আল্লাহর বিশালত্ব উপলব্ধি করতে পারবে না। পুনরন্থানের দিন সমগ্র পৃথিবী তাঁর মুঠোয় থাকবে। বস্তুত, সমস্ত বিশ্বজগৎ তাঁর ডান হাতে ভাঁজ করা থাকবে।* তিনি মহিমান্বিত; তিনি কোন অংশীদারের প্রয়োজনের চেয়ে অনেক উঁচুতে।"],
  "39:68": ["And the Trumpet is blown, and whoever is in the heavens and whoever is in the earth is thunderstruck, except whom Allah wills. Then it is blown a second time, and at once they are standing, watching.", "শিঙ্গায় ফুঁ দেওয়া হবে, যার ফলে আকাশ ও পৃথিবীর সকলেই অজ্ঞান হয়ে পড়বে, তবে আল্লাহ যাদেরকে রক্ষা করবেন তারা ছাড়া। তারপর আরেকবার ফুঁ দেওয়া হবে, যার ফলে তারা সকলেই উঠে দাঁড়াবে, আর দেখতে থাকবে।"],
  "39:69": ["And the earth shines with the light of its Rabb, and the records are laid down, and the nabis and the witnesses are brought, and judgment is made between them with justice, and they are not wronged.", "অতঃপর পৃথিবী তার প্রতিপালকের আলোতে আলোকিত হবে। লিপিবদ্ধ নথি ঘোষণা করা হবে, নবীগন ও সাক্ষীদের সামনে আনা হবে। অতঃপর প্রত্যেকের ন্যায়সঙ্গত বিচার করা হবে, সামান্যতম অন্যায় ছাড়াই।"],
  "39:70": ["And every soul is paid in full for what it did, and Allah knows best what they do.", "প্রত্যেক আত্মা যা কিছু করেছে তার প্রতিদান পাবে, কারণ তিনি তাদের কৃতকর্ম সম্পর্কে পূর্ণ অবগত।"],
  "39:71": ["And those who kafara are driven to Hell in groups, until when they come to it, its gates are opened and its keepers say to them: \"Did rusul not come to you from among yourselves, reciting to you the signs of your Rabb and warning you of the meeting of this day of yours?\" They say: \"Yes indeed, but the word of punishment has proved true against the kafirin.\"", "যারা অবিশ্বাস করেছিল তাদেরকে দলে দলে নরকের দিকে নিয়ে যাওয়া হবে। যখন তারা নরকের কাছে পৌঁছাবে এবং তার দরজাগুলো খুলে দেওয়া হবে, তখন তার রক্ষীরা বলবে, \"তোমাদের মধ্যে কি তোমাদের কাছে এমন বার্তাবাহকরা আসেনি যারা তোমাদের কাছে তোমাদের প্রতিপালকের প্রত্যাদেশ পাঠ করতেন এবং এই দিনের সাক্ষাতের বিষয়ে তোমাদের সতর্ক করতেন?\" তারা বলবে, \"হ্যাঁ, অবশ্যই। কিন্তু অবিশ্বাসীদের উপর 'শাস্তি' শব্দটি ইতিমধ্যেই সীলমোহর করে দেয়া হয়েছে।\""],
  "39:72": ["It is said: \"Enter the gates of Hell, to abide therein forever.\" How wretched is the lodging of the mutakabbirin.", "বলা হবে, \"নরকের দরজা দিয়ে প্রবেশ করো, সেখানে তোমরা চিরকাল থাকবে।\" অহংকারীদের জন্য কতই না নিকৃষ্ট পরিণতি!"],
  "39:73": ["And those who were mindful of their Rabb are driven to the Garden in groups, until when they come to it and its gates are opened and its keepers say to them: \"Peace be upon you; you have done well, so enter it, abiding forever.\"", "যারা তাদের প্রতিপালকের প্রতি ভিতশ্রদ্‌ধ ছিল, তাদেরকে দলে দলে সর্গের দিকে নিয়ে যাওয়া হবে। যখন তারা সর্গের কাছে পৌঁছাবে এবং তার দরজাগুলো খুলে দেওয়া হবে, তখন তার রক্ষীরা বলবে, \"তোমাদের উপর শান্তি বর্ষিত হোক; তোমরা জয়ী হয়েছো। অতএব, তোমরা এখানে চিরকাল অবস্থান করবে।\""],
  "39:74": ["And they say: \"Praise belongs to Allah, who was true to us in the promise and made us inherit the earth; we settle in the Garden wherever we wish.\" So how good is the reward of the workers.", "তারা বলবে, \"সমস্ত প্রশংসা আল্লাহর, যিনি আমাদের সাথে করা তাঁর প্রতিশ্রুতি পূর্ণ করেছেন এবং আমাদেরকে পৃথিবীর উত্তরাধিকারী করেছেন, আমরা যেমন ইচ্ছা সর্গ উপভোগ করব।\" কর্মশীলদের জন্য কত সুন্দর প্রতিদান!"],
  "39:75": ["And you see the malakat circling around the arsh, glorifying their Rabb with praise, and judgment is made between them with justice. And it is said: \"Praise belongs to Allah, Rabb of the worlds.\"", "তুমি দেখতে পাবে যে, ফেরেশতারা আরশের চারপাশে ভেসে বেড়াচ্ছে, তাদের প্রতিপালকের প্রশংসা ও মহিমা ঘোষণা করছে। সকলের প্রতি ন্যায়সঙ্গত রায় ঘোষণার পর ঘোষণা করা হবে: \"সমস্ত প্রশংসা আল্লাহর, যিনি মহাবিশ্বের প্রতিপালক।\""],
  "40:1": ["Ha Mim", "হ. ম. (হা মীম)"],
  "40:2": ["The sending down of the Book from Allah, the Mighty, the Knowing", "ঐশীগ্রন্থের এই প্রকাশনাবলি সর্বশক্তিমান, সর্বজ্ঞ আল্লাহর পক্ষ থেকে।"],
  "40:3": ["Forgiver of offense, Accepter of repentance, Severe in punishment, of long reach — there is no deity but Allah — to Allah is the arrival", "পাপসমূহ ক্ষমাকারী, অনুশোচনা গ্রহনকারী, শাস্তি প্রয়োগে কঠোর এবং সকল ক্ষমতার মালিক। তাঁর পাশে অন্য কোন উপাস্য নেই। তাঁর কাছেই চূড়ান্ত নিয়তি।"],
  "40:4": ["None disputes concerning the signs of Allah except those who kafara, so let not their moving about in the towns deceive you", "তারা ব্যতীত কেউ আল্লাহর প্রকাশনাবলির বিরুদ্ধে তর্ক করে না যারা অবিশ্বাস করে। তাদের আপাত সফলতায় অভিভূত হইও না।"],
  "40:5": ["Before them the people of Nuh cried lies, and the parties after them; and every community resolved against their Rasul to seize him, and they disputed with falsehood to refute the truth with it, so I seized them — and how was the punishment", "তাদের আগে নূহের লোকেরা অবিশ্বাসী ছিল, আর তাদের পরে ছিল অন্য অনেক বিরোধী। প্রত্যেক সম্প্রদায় তাদের বার্তাবাহককে কষ্ট দিতো তাকে নিষ্ক্রিয় করতে। আর তারা মিথ্যা দিয়ে তর্ক করতো। পরিনামে, আমি তাদেরকে শাস্তি দিয়েছিলাম; কত ভয়াবহ ছিল আমার শাস্তি!"],
  "40:6": ["And thus the word of your Rabb proved true against those who kafara: that they are companions of the Fire", "সুতরাং, যারা অবিশ্বাস করে তাদের উপর তোমার প্রভুর রায় ইতিমধ্যেই এটে দেয়া আছে, যে তারা নরকের বাসিন্দা।"],
  "40:7": ["Those who bear the raised-frame and those around it glorify with the praise of their Rabb, and believe in Allah, and seek forgiveness for those who believed: Our Rabb, Your mercy and Your knowledge encompass everything, so forgive those who turned and followed Your way, and shield them from the punishment of the blaze", "যারা আরশের কাজে নিয়োজিত এবং যারা এর আশেপাশে আছে তারা সবাই তাদের প্রভুর  মহিমা ঘোষণা করে এবং গুণকীর্তণ করে,  এবং তাঁর প্রতি বিশ্বাস রাখে। আর তারা তাদের জন্য ক্ষমা প্রার্থনা করে যারা বিশ্বাস করে:\"আমাদের প্রভু, আপনার ক্ষমা এবং আপনার জ্ঞান সবকিছু পরিবেষ্টন করে। তাদেরকে ক্ষমা করুন যারা অনুশোচনা করে এবং আপনার পথ অনুসরণ করে, এবং তাদেরকে নরকের শাস্তি থেকে নিষ্কৃতি দিন।\""],
  "40:8": ["Our Rabb, and admit them into the gardens of Eden that You promised them, and those of their fathers and their spouses and their offspring who are salih — truly You are the Mighty, the Wise", "“আমাদের প্রভু, এবং তাদেরকে ইডেন বাগানগুলোয় প্রবেশ করান যার প্রতিশ্রুতি আপনি দিয়েছেন তাদের জন্য এবং তাদের পিতা-মাতা, স্বামী-স্ত্রী, ও সন্তানদের মধ্যে সৎকর্মশীলদের জন্য। আপনি সর্বশক্তিমান, সবচেয়ে জ্ঞানী।\""],
  "40:9": ["And shield them from the evils; and whomever You shield from the evils that day, You have had mercy on them — and that is the immense win", "“এবং তাদেরকে পাপে পতিত হওয়া থেকে রক্ষা করুন। যাকে আপনি পাপে পতিত হওয়া থেকে রক্ষা করেন, ঐদিন, সে আপনার দয়া পেয়েছে। এটাই সর্বশ্রেষ্ঠ বিজয়”।"],
  "40:10": ["Those who disbelieve will be called out: Allah's loathing is greater than your loathing of yourselves, when you were called to belief but you kafara", "যারা অবিশ্বাস করে তাদেরকে বলা হবে, “এমনকি তোমাদের নিজেদের প্রতি তোমাদের ঘৃনার চেয়ে তোমাদের প্রতি আল্লাহর ঘৃনা নিকৃষ্টতম। কারন তোমাদেরকে বিশ্বাস করতে আমন্ত্রণ করা হয়েছিল, কিন্তু তোমরা অবিশ্বাস করা পছন্দ করেছিলে।"],
  "40:11": ["They will say: Our Rabb, You caused us to die twice and You gave us life twice, so we acknowledge our faults — is there then any way of exit", "তারা বলবে, \"আমাদের প্রভু, আপনি আমাদের দুই মৃত্যু দিয়েছেন, ” এবং আপনি আমাদের দুই জীবন দিয়েছেন; এখন আমরা আমাদের পাপ স্বীকার করেছি। কোন উপায় আছে কি?"],
  "40:12": ["That is because, when Allah alone was called upon, you kafara; but if partners were associated with Allah, you believed — so the judgment belongs to Allah, the High, the Great", "এটা এ কারণে যে যখন একমাত্র আল্লাহর কথা বলা হতো তোমরা তখন অবিশ্বাস করতে, কিন্তু যখন তাঁর সাথে অন্যদের উল্লেখ করা হতো, তোমরা বিশ্বাস করতে। অতএব, আল্লাহর রায় হয়ে গেছে; তিনি সবচেয়ে উর্ধ্বে, মহান।"],
  "40:13": ["It is Allah who shows you Allah's signs and sends down for you provision from the sky — and none takes heed except whoever turns back", "তিনিই সে সত্ত্বা যিনি অনবরত তোমাদেরকে তাঁর প্রমানাদি দেখান, এবং আকাশ থেকে তোমাদের কাছে জীবিকা পাঠান। যারা পুরোপুরি আত্মসমর্পণ করে তারাই কেবল মনোযোগ দিতে পারে।"],
  "40:14": ["So call upon Allah, devoting the religion exclusively to Allah, even if the kafirin are averse", "অতএব, তোমরা তোমাদের উপাসনা পুরোপুরিভাবে একমাত্র আল্লাহর প্রতি নিবেদন করবে, এমনকি যদিও অবিশ্বাসীরা তা অপছন্দ করে।"],
  "40:15": ["Exalted in degrees, Possessor of the raised-frame — casts the spirit of Allah's command upon whom Allah wills of Allah's servants, to warn of the Day of Meeting", "সর্বোচ্চ পদমর্যাদাসমূহের মালিক, এবং সমস্ত রাজত্বের শাসক। তিনি অনুপ্রেরণা পাঠান, তাঁর প্রত্যাদেশ দিয়ে, তাঁর বান্দাদের মধ্যে থেকে যার কাছেই তিনি পছন্দ করেন, তলবের দিন সম্পর্কে সতর্ক করতে।"],
  "40:16": ["The day they come forth, nothing of them is concealed from Allah: Whose is the sovereignty this day? Allah's — the One, the Overpowering", "এটা সে দিন যখন সকলে পুরোপুরি প্রকাশিত হবে; তাদের কেউ আল্লাহ থেকে কোন কিছু লুকাবে না। ঐদিনের সকল সার্বভৌমত্ব কার অধীনে? আল্লাহর, একক, সর্বোচ্চ।"],
  "40:17": ["This day every soul is requited for what it earned; no wrong this day — truly Allah is swift in reckoning", "ঐদিন, প্রত্যেক তার জন্য আত্মা প্রতিদান পাবে যাকিছুই সে অর্জন করেছে। সেদিন কোন অবিচার থাকবে না। আল্লাহ হিসাব গ্রহনে দক্ষ।"],
  "40:18": ["And warn them of the approaching day, when the hearts are at the throats, held in; the wrongdoers will have no bosom-friend and no intercessor who is obeyed", "তাদেরকে আসন্ন দিন সম্পর্কে সতর্ক করো, যখন হৃদয়গুলো আতংকিত হবে, এবং অনেকে হবে অনুতপ্ত। সীমালঙ্ঘনকারীদের কোন বন্ধু থাকবে না, না থাকবে কোন সুপারিশকারী যার কথা মান্য করা হবে।"],
  "40:19": ["Allah knows the treachery of the eyes and what the chests conceal", "তিনি সম্পূর্ণ অবগত চোখ যা দেখে না, এবং সবকিছু সম্পর্কে যা মন গোপন করে।"],
  "40:20": ["And Allah judges with the truth; and those whom they call upon besides Allah judge nothing at all — truly Allah is the Hearing, the Seeing", "আল্লাহ ন্যায়সঙ্গতভাবে বিচার করেন, যখন তাঁর পাশে তারা যে উপাস্যদের কাছে মিনতি করে, তারা কোনকিছু বিচার করতে পারে না। আল্লাহ সে সত্ত্বা যিনি শুনেন, দেখেন।"],
  "40:21": ["Have they not journeyed through the land to look how the end was of those before them? They were stronger than them in strength and in tracks through the land, but Allah seized them for their offenses, and they had no shielder from Allah", "তারা কি পৃথিবীতে ঘুড়ে দেখেনি এবং তাদের পূর্ববর্তীদের পরিনতি লক্ষ্য করেনি? পৃথিবীতে তারা তাদের চেয়ে শক্তিশালী, এবং অধিক উৎপাদনশীল ছিল। কিন্তু আল্লাহ তাদের পাপসমূহের জন্য তাদেরকে শাস্তি দিয়েছিলেন, এবং কিছুই তাদেরকে আল্লাহ থেকে রক্ষা করতে পারেনি।"],
  "40:22": ["That is because their rusul used to come to them with the clear proofs, but they kafara, so Allah seized them — truly Allah is powerful, severe in punishment", "এটা এ কারণে যে তাদের বার্তাবাহকরা তাদের কাছে স্পষ্ট প্রমাণাদি নিয়ে গিয়েছিল, কিন্তু তারা অবিশ্বাস করেছিল। পরিনামে, আল্লাহ তাদের শাস্তি দিয়েছিলেন। তিনি শক্তিমান, শাস্তি প্রদানে কঠোর।"],
  "40:23": ["And We sent Musa with Our signs and a clear warrant", "আমরা মূসাকে আমাদের নিদর্শনাবলী এবং অসমান্য কর্তৃত্ব দিয়ে পাঠিয়েছিলাম।"],
  "40:24": ["To Fir'awn and Haman and Qarun, but they said: a sorcerer, a liar", "ফেরাউন, হামান, এবং ক্বারুনের কাছে। কিন্তু তারা বলেছিল, “একজন যাদুকর; মিথ্যুক।"],
  "40:25": ["But when he brought them the truth from Us, they said: kill the sons of those who believed with him, and let their nisa live — yet the scheme of the kafirin is nothing but error", "যখন সে তাদেরকে আমাদের পক্ষ থেকে সত্য দেখালো, তারা বলেছিল, \"তার সাথে যারা বিশ্বাস করেছে তাদের পুত্রদের হত্যা করো, এবং কন্যাদের রেহাই দাও।” এভাবে, অবিশ্বাসীদের চক্রান্ত সবসময় অন্যায়।"],
  "40:26": ["And Fir'awn said: leave me to kill Musa, and let him call upon his Rabb — I fear he may change your religion, or bring corruption to appear in the land", "ফেরাউন বলেছিল, \"চল মূসাকে আমি হত্যা করি, এবং তার প্রভুর কাছে তাকে মিনতি করতে দাও। আমার ভয় হয় পাছে সে তোমাদের ধর্মকে কলুষিত করে ফেলে, অথবা স্থলভাগ জুড়ে মন্দ ছড়ায়।"],
  "40:27": ["And Musa said: I seek refuge in my Rabb and your Rabb from every proud one who does not believe in the Day of Reckoning", "মুসা বলেছিল, \"আমি আমার প্রভু এবং তোমাদের প্রভুর কাছে আশ্রয় প্রার্থনা করছি, প্রত্যেক উদ্ধত ব্যক্তি থেকে যে হিসাবগ্রহণের দিনে বিশ্বাস করে না।"],
  "40:28": ["And a believing man from Fir'awn's family, who hid his belief, said: will you kill a man because he says my Rabb is Allah, when he has brought you the clear proofs from your Rabb? And if he is a liar, upon him is his lie; and if he is sadiq, some of what he promises you will befall you — truly Allah does not guide whoever is an extravagant liar", "ফেরাউনের লোকদের মধ্যে একজন বিশ্বাসী লোক, যে তার সত্য গোপন করেছিল, বলেছিল, ”কেমন করে তুমি একজন মানুষকে হত্যা করবে শুধুমাত্র বলার জন্য, \"আমার প্রভু আল্লাহ, এবং সে তোমার প্রভুর পক্ষ থেকে তোমাকে পরিষ্কার প্রমাণ দেখিয়েছে? যদি সে মিথ্যাবাদী হয়, সেটা তার সমস্যা এবং যদি সে সত্যবাদী হয়, তুমি তার প্রতিশ্রুতি থেকে উপকৃত হও। নিশ্চয়, আল্লাহ সীমালঙ্ঘনকারী, মিথ্যাবাদীদের পথপ্রদর্শন করেন না।"],
  "40:29": ["O my people, the kingdom is yours today, manifest in the land — but who will help us against Allah's might if it comes to us? Fir'awn said: I show you nothing but what I see, and I guide you to nothing but the way of right course", "যে বিশ্বাস করেছিল সে বলল, ”হে আমার লোকেরা, আমি ভয় করি যে পূর্ববর্তী বিরোধীদের মত তোমাদেরও একই পরিণতি হয়।"],
  "40:30": ["And the mumin said: O my people, I fear for you a day like the day of the parties", "যে বিশ্বাস করেছিল সে বলল, ”হে আমার লোকেরা, আমি ভয় করি যে পূর্ববর্তী বিরোধীদের মত তোমাদেরও একই পরিণতি হয়।"],
  "40:31": ["Like the way of the people of Nuh, and Aad, and Thamud, and those after them — and Allah wills no wrong for the servants", "নূহ, এবং আদম, সামূদ, এবং অন্য বিরোধীরা যারা তাদের পরে এসেছিল। আল্লাহ মানুষের জন্য কোন অবিচার চান না।"],
  "40:32": ["And, O my people, I fear for you the Day of Calling", "\"হে আমার লোকেরা, আমি তোমাদের জন্য ভয় করি সেই আহ্বানের দিবসের।\""],
  "40:33": ["A day when you turn back, fleeing — you will have no protector from Allah; and whomever Allah leads astray has no guide", "এটা সেই দিন, যখন তোমরা ঘুড়ে দাড়াতে এবং পালানোর ইচ্ছা করতে পার। কিন্তু কোন কিছুই তখন তোমাদেরকে আল্লাহ থেকে রক্ষা করতে পারবে না। যাকেই আল্লাহ পথভ্রষ্ট করেন, কোনকিছুই তাকে পথ দেখাতে পারে না।"],
  "40:34": ["And Yusuf came to you before with the clear proofs, but you never ceased to doubt what he brought you, until when he perished you said: Allah will never send a Rasul after him — thus does Allah lead astray whoever is extravagant and doubting", "এর আগে ইউসুফ তোমাদের কাছে এসেছিল স্পষ্ট প্রকাশনাবলী  নিয়ে, কিন্তু  তোমরা তার বার্তায় সন্দেহ করে যাচ্ছিলে। তারপর সে যখন মারা গেল তোমরা বলেছো, \"আল্লাহ তার পরে অন্য কোন বার্তাবাহক পাঠাবেন না। (সে-ই শেষ বার্তাবাহক ছিল)! আল্লাহ এভাবে তাদেরকে পথভ্রষ্ট করেন যারা সীমালঙ্ঘনকারী, সন্দিহান।"],
  "40:35": ["Those who dispute the signs of Allah without any warrant having come to them — how great is the loathing in the sight of Allah and in the sight of those who believe — thus does Allah set a seal upon every heart of a proud, overpowering one", "তারা আল্লাহর প্রকাশনাবলীর বিরুদ্ধে তর্ক করে, কোন ভিত্তি ছাড়া। এটি একটি বৈশিষ্ট্য যা আল্লাহ এবং যারা বিশ্বাস করে তাদের দ্বারা তীব্রভাবে ঘৃনিত হয়।"],
  "40:36": ["And Fir'awn said: Haman, build for me a tower, that I may reach the means", "ফেরাউন বলেছিল, \"হে হামান, আমার জন্য একটি উচুঁ মিনার তৈরি করো, যেন আমি পৌঁছাতে পারি এবং আবিষ্কার করি।"],
  "40:37": ["The means of the skies, to look over to the deity of Musa — and I think he is a liar — thus was made attractive to Fir'awn the evil of his deed, and he was turned away from the way; and the scheme of Fir'awn was in nothing but ruin", "\"আমি স্বর্গে পৌঁছাতে চাই, এবং মুসার উপাস্যকে একবার দেখে নিতে চাই। আমি বিশ্বাস করি যে সে একজন মিথ্যুক।” এভাবে ফেরাউনের মন্দ কাজগুলোকে তার চোখে সুশোভিত করে দেয়া হয়েছে, এবং এভাবে (সে সঠিক) পথ অনুসরণ করা থেকে বিরত ছিল। ফেরাউনের চক্রান্ত সত্যই মন্দ।"],
  "40:38": ["And the mumin said: O my people, follow me — I will guide you to the way of right course", "সে ব্যক্তি বলল যে বিশ্বাস করেছিল যে, ”হে আমার লোকেরা, আমাকে অনুসরণ করো, এবং আমি তোমাদেরকে সঠিক পথ প্রদর্শন করবো।"],
  "40:39": ["O my people, this worldly life is only an enjoyment, and the Last is the abode of settlement", "\"হে আমার লোকেরা, এই প্রথম জীবন একটি সাময়িক বিভ্রম, যখন পরকালই হলো চিরস্থায়ী আবাস।\""],
  "40:40": ["Whoever does an evil is requited nothing but its like; and whoever does good, male or female, and is a mumin — those will enter the Garden, provided for in it without reckoning", "যেকেউ একটি পাপ করে, শুধু তার জন্য প্রতিফল গ্রহন করে এবং যেকেউ সৎ কাজ করে- পুরুষ অথবা নারী - বিশ্বাসী অবস্থায়, এরা প্রবেশ করবে স্বর্গে যেখানে তারা জীবিকা পায়, সীমাহীনভাবে।"],
  "40:41": ["And, O my people, what is it with me that I call you to deliverance while you call me to the Fire", "\"হে আমার লোকেরা, যখন আমি তোমাদেরকে বাচাঁতে আমন্ত্রণ করি, তোমরা আমাকে  আমন্ত্রণ করো নরকাগ্নির দিকে।"],
  "40:42": ["You call me to disbelieve in Allah and to associate with Allah that of which I have no knowledge, while I call you to the Mighty, the Forgiving", "\"তোমরা আমাকে  আমন্ত্রণ করো আল্লাহর প্রতি অকৃতজ্ঞ হওয়ার জন্য, এবং তাঁর পাশে  উপাস্যদের স্থাপন করার জন্য যাদেরকে আমি চিনি না। আমি তোমাদেরকে সর্বশক্তিমান, ক্ষমাকারীর দিকে আমন্ত্রণ করি।"],
  "40:43": ["No doubt: that to which you call me has no claim in this world or in the Last — and that our return is to Allah, and that the musrifin ones are the companions of the Fire", "\"কোন সন্দেহ নেই যে আমাকে যা করতে তোমরা আমন্ত্রণ করো এই বিশ্বে তার কোন ভিত্তি নেই, না আছে পরকালে, আর আমাদের চুড়ান্ত প্রত্যাবর্তন আল্লাহর কাছে, এবং যে সীমালঙ্ঘনকারীরা টেনে এনেছে নরকাগ্নি।"],
  "40:44": ["Soon you will remember what I say to you; and I entrust my affair to Allah — truly Allah sees the servants", "\"একদিন তোমাদের স্মরণ হবে যা এখন আমি তোমাদের বলছি। আমি এ ব্যাপারে আল্লাহর উপর বিচার ছেড়ে দিচ্ছি; আল্লাহ সকল লোকদের দ্রষ্টা।"],
  "40:45": ["So Allah shielded him from the evils of what they planned, and the evil of punishment befell Fir'awn's family", "আল্লাহ এরপর তাকে তাদের মন্দ ষড়যন্ত্র থেকে রক্ষা করলেন, যেখানে ফেরাউনের লোকেরা টেনে এনেছে নিকৃষ্টতম শাস্তি।"],
  "40:46": ["The Fire — they are presented to it morning and evening; and the day the Hour rises: admit Fir'awn's family into the most severe punishment", "তাদের কাছে নরক দেখানো হবে দিনে এবং রাতে, এবং পুনরুত্থান দিনে: \"ফেরাউনের লোকদের নিকৃষ্টতম শাস্তিতে প্রবেশ করাও।\""],
  "40:47": ["And when they argue in the Fire, the weak will say to those who were proud: we were followers for you — will you then avail us against a share of the Fire", "যখন তারা নরকে তর্ক করবে, অনুসারীরা তাদের নেতাদের বলবে, \"আমরা তোমাদের অনুসারী ছিলাম, তোমরা কি এই নরকের কোন অংশ থেকে নিষ্কৃতি দিতে পারো?\""],
  "40:48": ["Those who were proud will say: we are all in it — Allah has indeed judged between the servants", "নেতারা বলবে, “আমরা এখানে একসাথে সবাই আছি। আল্লাহ লোকদের মাঝে বিচার করেছেন।\""],
  "40:49": ["And those in the Fire will say to the keepers of Jahannam: call upon your Rabb to lighten for us a day of the punishment", "যারা নরকাগ্নিতে তারা নরকের তত্ত্বাবধায়কদের বলবে, \"তোমাদের প্রভুকে ডাকো তোমাদের জন্য শাস্তি কমাতে, একদিনের জন্য হলেও।\""],
  "40:50": ["They will say: did your rusul not come to you with the clear proofs? They will say: yes indeed. They will say: then call — but the call of the kafirin is in nothing but error", "তারা বলবে, \"তোমরা কি তোমাদের বার্তাবাহকদের পাওনি যারা তোমাদের কাছে পরিষ্কার বার্তা পৌঁছিয়েছিল?” তারা উত্তর দিবে, \"হ্যা আমরা পেয়েছিলাম।” তারা বলবে, \"তাহলে মিনতি করো (তোমাদের যতটুক ইচ্ছা); অবিশ্বাসীদের মিনতি সবসময় বৃথা।\""],
  "40:51": ["We will surely help Our rusul and those who believed in this worldly life, and on the day the witnesses rise", "নিশ্চিতভাবে, আমরা আমাদের বার্তাবাহকদের এবং যারা বিশ্বাস করে তাদেরকে বিজয় দিবো, এই দুনিয়ায় এবং সে দিনও যখন সাক্ষীদের তলব করা হবে।"],
  "40:52": ["A day when the excuse of the wrongdoers will not benefit them — theirs is the curse, and theirs is the evil abode", "ঐদিন, অবিশ্বাসীদের কৈফিয়তগুলো তাদের উপকারে আসবে না। তারা টেনে এনেছে নিন্দা; তারা টেনে এনেছে নিকৃষ্ট নিয়তি।"],
  "40:53": ["And We gave Musa the guidance, and We made the children of Israel inherit the Book", "আমরা মূসাকে পথনির্দেশনা দিয়েছিলাম, এবং ইসরাইলের সন্তানদের ঐশীগ্রন্থের উত্তরাধিকার করালাম।"],
  "40:54": ["A guidance and a reminder for people of understanding", "(তাদের ইতিহাস) হলো একটি শিক্ষা এবং তাদের জন্য একটি স্মারক যারা বুদ্ধিমত্তা অধিকার করে।"],
  "40:55": ["So be of the sabirin — the promise of Allah is true — and seek forgiveness for your offense, and glorify with the praise of your Rabb in the evening and the early mornings", "সেজন্য, ধৈর্যশীল হও, কারণ আল্লাহর প্রতিশ্রুতি সত্য, এবং তোমাদের পাপের জন্য ক্ষমা চাও, এবং তোমার প্রভুর গুণকীর্তন ও প্রশংসা করো দিনে ও রাতে।"],
  "40:56": ["Those who dispute the signs of Allah without any warrant having come to them — in their chests is nothing but pride, and they will never reach it — so seek refuge in Allah; truly Allah is the Hearing, the Seeing", "নিশ্চিতভাবে, আল্লাহর প্রকাশনাবলীর বিরুদ্ধে যারা প্রমাণ ছাড়া তর্ক করে, তারা ঔদ্ধত্যতা প্রকাশ করে যা তাদের বুকে লুকায়িত, এবং এ বিষয়ে তারা সচেতনও নয়। অতএব, আল্লাহর কাছে আশ্রয় প্রার্থনা করো; তিনি শ্রবণকারী, দ্রষ্টা।"],
  "40:57": ["The creation of the skies and the earth is greater than the creation of people, but most people do not know", "এমনকি মানব জাতি সৃষ্টির চেয়ে আরো বেশি অসাধারণ আকাশমণ্ডলী এবং পৃথিবীর সৃষ্টি, কিন্তু বেশিরভাগ মানুষ জানে না।"],
  "40:58": ["And the unseeing and the seeing are not equal, nor are those who believed and did the good deeds and the evil-doer — little do you remember", "অন্ধ এবং চক্ষুষ্মান সমান নয়। না  যারা বিশ্বাস করে এবং সৎ কাজ করে তারা পাপীদের সমান। কদাচিৎ, তোমরা সতর্ক হও।"],
  "40:59": ["The Hour is coming — no doubt in it — but most people do not believe", "নিশ্চিতভাবে, সে ঘন্টা (বিচার দিবস) আসছে, এ বিষয়ে কোন সন্দেহ নেই, কিন্তু অধিকাংশ লোক বিশ্বাস করে না।"],
  "40:60": ["And your Rabb has said: call upon Me — I will answer you; those who scorn My worship will enter Jahannam, entering abject", "তোমাদের প্রভু বলেন, \"আমার কাছে অনুনয় করো, এবং আমি তোমাদের প্রতি সাড়া দিবো। নিশ্চয়, যারা আমার উপাসনা করতে অত্যন্ত উদ্ধত তারা জাহান্নামে প্রবেশ করবে, বলপূর্বকভাবে।\""],
  "40:61": ["It is Allah who made for you the night to rest in, and the day for sight — truly Allah is Possessor of bounty over people, but most people do not give thanks", "আল্লাহ সে সত্ত্বা যিনি রাতের নকশা করেছেন যেন তাতে তোমরা বিশ্রাম নিতে পারো, এবং দিনকে করেছেন আলোকিত। আল্লাহ লোকদের প্রতি অনেক অনুগ্রহ প্রদান করেছেন, কিন্তু অধিকাংশ লোক কৃতজ্ঞ নয়।"],
  "40:62": ["That is Allah, your Rabb, Creator of everything — there is no deity but Allah — so how are you turned away", "এমনই আল্লাহ - তোমাদের প্রভু, সবকিছুর সৃষ্টিকর্তা। তিনি ছাড়া কোন উপাস্য নেই। কিভাবে তোমরা বিচ্যুত হও?"],
  "40:63": ["Thus are turned away those who used to deny the signs of Allah", "তারা বিচ্যুত হয় যারা আল্লাহর প্রকাশনাবলি উপেক্ষা করে।"],
  "40:64": ["It is Allah who made the earth a settlement for you and the sky a structure, and formed you and formed you excellently, and provided you from the good things — that is Allah, your Rabb; so blessed be Allah, Rabb of the worlds", "আল্লাহ সে সত্ত্বা যিনি তোমাদের জন্য পৃথিবীকে বাসযোগ্য, এবং আকাশকে দূর্ভেদ্য করেছেন, এবং তিনি তোমাদের নকশা করেছেন, এবং তোমাদের নকশা করেছেন ভালোভাবে। তিনি সে সত্ত্বা যিনি তোমাদেরকে ভাল জীবিকা সরবরাহ করেন। এমনই আল্লাহ তোমাদের প্রভু; আল্লাহ সবচেয়ে মর্যাদাসম্পন্ন, মহাবিশ্বের প্রভু।"],
  "40:65": ["Allah is the Living — there is no deity but Allah — so call upon Allah, devoting the religion exclusively to Allah; praise belongs to Allah, Rabb of the worlds", "তিনি চিরজীবী ; তিনি ছাড়া কোন উপাস্য নেই। তোমরা একমাত্র তার উপাসনা করো, তোমাদের ধর্মকে পুরোপুরি একমাত্র তার নিকট উৎসর্গ করে। প্রশংসা আল্লাহর, মহাবিশ্বের প্রভু।"],
  "40:66": ["Say: I have been forbidden to worship those you call upon besides Allah, since the clear proofs came to me from my Rabb; and I have been commanded to submit to the Rabb of the worlds", "বল, ”তোমরা আল্লাহর পাশে যে উপাসিতদের উপাসনা করো আমাকে সেগুলোর উপাসনা করতে নিষেধ করা হয়েছে, যখন আমার প্রভুর কাছ থেকে আমার নিকট স্পষ্ট প্রকাশনাবলী এসেছে। আমাকে আদেশ করা হয়েছে, মহাবিশ্বের প্রভুর নিকট আত্মসমর্পন করতে।\""],
  "40:67": ["It is Allah who created you from dust, then from a drop, then from a clot; then brings you out a child; then that you reach your strength; then that you become old — and among you is one who dies before — and that you reach an appointed term, that perhaps you may reason", "তিনি সে সত্ত্বা যিনি তোমাদেরকে ধূলিকণা থেকে সৃষ্টি করেছেন, এবং পরবর্তীতে অতিক্ষুদ্র একটি ফোঁটা থেকে, তারপর ঝুলন্ত ভ্রুন থেকে, তারপর তিনি তোমাদেরকে শিশু হিসেবে বের করে আনেন, তারপর তিনি তোমাদেরকে প্রাপ্ত-বয়ষ্কে পৌঁছতে দেন, তারপর তোমরা বৃদ্ধ হও- তোমাদের কেউ কেউ এর আগেই মারা যাও। তোমরা অর্জন কর একটি পূর্বনির্ধারিত বয়স, যাতে তোমরা বুঝতে পার।"],
  "40:68": ["It is Allah who gives life and causes death; so when Allah decrees an affair, Allah only says to it be, and it is", "তিনিই একমাত্র সত্ত্বা যিনি নিয়ন্ত্রণ করেন জীবন এবং মৃত্যু। কোন কিছু সম্পন্ন করতে তিনি শুধু একে বলেন, “হও”এবং তা হয়ে যায়।"],
  "40:69": ["Have you not seen those who dispute the signs of Allah — how they are turned away", "তুমি কি তাদের লক্ষ্য করেছো যারা আল্লাহর প্রমাণাদির বিরুদ্ধে তর্ক করে, এবং কিভাবে তারা পথচ্যুত হয়?"],
  "40:70": ["Those who cried lies to the Books and to what Our rusul brought — they will soon know", "তারাই সে ব্যাক্তি যারা অবিশ্বাস করেছিল ঐশীগ্রন্থে, এবং বার্তাসমূহে, যা আমরা আমাদের বার্তাবাহকদের দিয়ে পাঠিয়েছিলাম। অতএব, তারা অবশ্যই খুঁজে পাবে।"],
  "40:71": ["When the fetters are on their necks, and the chains, they are dragged", "তাদের গলার চারপাশে থাকবে শিকল, এবং তাদেরকে টানতে সে শিকল ব্যবহার করা হবে।"],
  "40:72": ["Into the scalding water, then into the Fire they are burnt", "নিন্মস্তরে, এরপর আগুনে, তারা পুড়বে।"],
  "40:73": ["Then it will be said to them: where is that which you used to associate besides Allah", "তাদেরকে জিজ্ঞেস করা হবে, \"কোথায় সে উপাসিতরা যাদেরকে তোমরা উপাসনা করতে,"],
  "40:74": ["They will say: they are lost to us — no, we never used to call upon anything before — thus does Allah lead the kafirin astray", "\"আল্লাহর পাশে?” তারা বলবে, \"তারা আমাদেরকে পরিত্যাগ করেছে। প্রকৃতপক্ষে, যখন আমরা তাদের উপাসনা করেছিলাম, আমরা কোনকিছুরই উপাসনা করছিলাম না।” এভাবে আল্লাহ অবিশ্বাসীদের পথভ্রষ্ট করেন।"],
  "40:75": ["That is because you used to rejoice in the land without truth, and because you used to exult", "এর কারন পৃথিবীতে তোমরা মিথ্যা মতবাদে আনন্দ করতে, এবং তোমরা সেগুলোর প্রচার করতে।"],
  "40:76": ["Enter the doors of Jahannam, abiding in it — what an evil lodging for the proud", "জাহান্নামের দরজা দিয়ে প্রবেশ করো, যেখানে তোমরা চিরকাল বাস করো। উদ্ধত ব্যক্তিদের জন্য শোচনীয় নিয়তি।"],
  "40:77": ["So be of the sabirin — the promise of Allah is true; so either We show you some of what We promise them, or We take you — to Us they return", "তুমি ধৈর্যশীল হবে, কারন আল্লাহর প্রতিশ্রুতি সত্য। যদি আমরা তোমাকে এমন কিছু (শাস্তি) দেখাই, যার প্রতিশ্রুতি আমরা তাদের দিয়েছিলাম, অথবা এর পূর্বে তোমার জীবনাবসান করি, তারা আমাদের কাছে ফিরে আসবে।"],
  "40:78": ["And We sent rusul before you — among them are those whose story We narrated to you, and among them are those whose story We did not narrate to you; and it was not for a Rasul to bring a sign except by Allah's permission — so when Allah's command came, it was judged with the truth, and there the falsifiers lost", "আমরা তোমার আগে বার্তাবাহকদের পাঠিয়েছিলাম - যাদের কাউকে কাউকে আমরা তোমার কাছে উল্লেখ করেছিলাম এবং কাউকে কাউকে তোমার কাছে উল্লেখ করিনি। আল্লাহর অনুমোদন ছাড়া বার্তাবাহক কোন অলৌকিকতা উপস্থাপন করতে পারে না। একবার আল্লাহর বিচার প্রকাশ হলে, সত্য কর্তৃত্ব করে এবং মিথ্যাবাদীরা প্রকাশিত হয় এবং অপদস্থ হয়।"],
  "40:79": ["It is Allah who made the cattle for you, that you ride on them and eat from them", "আল্লাহ সে সত্ত্বা যিনি তোমাদের জন্য পালিত-পশু তৈরি করেছেন, কয়েকটিতে তোমরা আরোহণ করো এবং কয়েকটিকে তোমরা খাও।"],
  "40:80": ["And in them you have benefits, and that you may reach thereby a need in your chests, and upon them and upon the ships you are carried", "তারা তোমাদেরকে বাড়তি সুবিধাও দেয় যা তোমাদের অনেকের প্রয়োজনীয়তা পূর্ণ করে। তাদের উপর, এবং জাহাজে, তোমাদেরকে বহন করা হয়।"],
  "40:81": ["And Allah shows you Allah's signs — so which of Allah's signs do you disavow", "তিনি এভাবে তোমাদেরকে তাঁর প্রমাণসমূহ দেখান। আল্লাহর কোন প্রমাণগুলোকে তোমরা অস্বীকার করবে?"],
  "40:82": ["Have they not journeyed through the land to look how the end was of those before them? They were more numerous than them and stronger in strength and in tracks through the land — but what they earned did not avail them", "তারা  কি পৃথিবীতে ঘুরে বেড়ায়নি এবং তাদের পরিণাম লক্ষ্য করে না, যারা তাদের আগে এসেছিল? তারা সংখ্যায় বড়, ক্ষমতায় বড়,  এবং পৃথিবীতে একটি বড় উত্তরাধিকারের মালিক ছিল। অথচ তাদের কোন অর্জন তাদেরকে নুন্যতম সাহায্য করতে পারে নি।"],
  "40:83": ["But when their rusul came to them with the clear proofs, they rejoiced in the knowledge they had, and there befell them what they used to mock", "যখন তাদের বার্তাবাহক তাদের কাছে স্পষ্ট প্রমাণাদি নিয়ে গিয়েছিল, তারা উত্তরাধিকারসূত্রে প্রাপ্ত জ্ঞানে মত্ত ছিল, এবং ঠিক যে বিষয়টি নিয়ে তারা উপহাস করতো তা-ই তাদের পতনের কারণ ছিল।"],
  "40:84": ["But when they saw Our might, they said: we believe in Allah alone, and we disbelieve in what we used to associate", "পরবর্তীতে, তারা যখন আমাদের শাস্তি দেখল তারা বলেছিল, \"এখন আমরা আল্লাহর একত্বে বিশ্বাস করি, এবং আমরা এখন অবিশ্বাস করি সে প্রতিমা উপাসনাকে যা আমরা চর্চা করতাম।"],
  "40:85": ["But their faith did not benefit them when they saw Our might — the way of Allah which has passed before among Allah's servants — and there the kafirin lost", "তাদের বিশ্বাস তখন তাদেরকে সামান্যতম সাহায্য করতে পারেনি, একবার যখন তারা আমাদের শাস্তি দেখেছিল। এমনই আল্লাহর পদ্ধতি যা তাঁর সৃষ্টিগুলোর ব্যাপারে প্রতিষ্ঠিত; অবিশ্বাসীরা সর্বদা ধ্বংসপ্রাপ্ত।"],
  "41:1": ["Ha Mim", "হ. ম. (হা মীম)"],
  "41:2": ["A sending-down from the Rahman, the Rahim", "পরম করুণাময়, পরম দয়ালু আল্লাহর কাছ থেকে একটি প্রকাশনা।"],
  "41:3": ["A book whose verses are made clear, an Arabic recital for a people who know", "একটি ঐশীগ্রন্থ যার আয়াতগুলো পূর্ণ বিস্তারিতভাবে জানায়, আরবি কুরআনে, মানুষের জন্য যারা জানে।"],
  "41:4": ["A herald of glad news and a warner; yet most of them turn away, so they do not hear", "একটি শুভ সংবাদ বহনকারী, একইসাথে সতর্ককারী। তবে, তাদের অধিকাংশই মুখ ফিরিয়ে নেয়; তারা শুনে না।"],
  "41:5": ["They say: our hearts are in covers against what you call us to, and in our ears is a heaviness, and between us and you is a veil; so act — we are acting", "তারা বলেছিল, \"পূর্ব থেকে আমাদের মন স্থির হয়ে আছে, আমাদের কান তোমার বার্তার প্রতি বধির এবং একটি অন্তরায় তোমার থেকে আমাদেরকে আলাদা করে। তুমি যা চাও করো, এবং আমরাও তা-ই করবো।\""],
  "41:6": ["Say: I am only a human like you; it is revealed to me that your ilah is one ilah; so stand upright toward Allah and seek forgiveness from Allah; and woe to the associators", "বল, আমি তোমাদের মত একজন মানুষের চেয়ে বেশি কিছু নই, যাকে প্রত্যাদেশ দেয়া হয়েছে যে তোমাদের খোঁদা এক। তোমরা তাঁর প্রতি নিবেদিত হবে এবং তাঁর কাছে ক্ষমা চাও। দু:খ তো প্রতিমা উপাসকদের।"],
  "41:7": ["Those who do not give the alms, and of the Hereafter they are rejectors", "যারা বাধ্যতামূলক দান (যাকাত) দেয় না, এবং পরকাল সম্পর্কে, তারা অবিশ্বাসী।"],
  "41:8": ["Truly those who believe and do good deeds — for them is a reward unstinted", "তাদের ক্ষেত্রে যারা বিশ্বাস করে এবং সৎ জীবন যাপন করে,তারা একটি যথোপযুক্ত প্রতিদান পায়।"],
  "41:9": ["Say: do you indeed reject the One who created the earth in two days, and set up equals for Allah? That is the Rabb of the worlds", "বল, \"তোমরা অবিশ্বাস কর  সে সত্ত্বাকে যিনি  দুই দিনে পৃথিবী সৃষ্টি করেছিলেন, এবং তোমরা তাঁর সাথে সমমর্যাদা দিতে শরিক স্থাপন করো, যদিও তিনি মহাবিশ্বের প্রভু।"],
  "41:10": ["And Allah set in it anchors from above it, and blessed abundance in it, and measured in it its provision in four days, alike for all who ask", "তিনি এর উপর স্থাপন করেছেন ভারসাম্যরক্ষাকারী (পর্বতমালা), একে উর্বর করেছেন, এবং তিনি চার দিনে এর জীবিকা গণনা করেছেন, এর অধিবাসীদের চাহিদা মেটাতে"],
  "41:11": ["Then Allah turned to the sky while it was smoke, and said to it and to the earth: come willingly or unwillingly; they said: we come willingly", "তারপর তিনি আকাশের দিকে ফিরলেন, যখন তা তখনও গ্যাস ছিল, এবং বলেছিলেন একে, ও পৃথিবীকে,\"অস্তিত্বে আসো, ইচ্ছায় বা অনিচ্ছায়। ”তারা বলেছিল, \"আমরা আসি স্বেচ্ছায়।\""],
  "41:12": ["So Allah completed them into seven heavens in two days, and revealed in each heaven its command; and We adorned the nearest sky with lamps as a guard — that is the decree of the Mighty, the Knowing", "এভাবে, তিনি সাতটি  মহাবিশ্ব দুই দিনে সম্পূর্ণ করেছিলেন, এবং প্রত্যেক মহাবিশ্বের জন্য আইনসমূহ প্রকাশ করলেন। এবং আমরা নিম্নতম মহাবিশ্বকে বাতি দিয়ে সুশোভিত করেছিলাম, এবং এর চারপাশে পাহারাদারদের বসিয়েছি। এমনি সর্বশক্তিমান, সর্বজ্ঞের নকশা।"],
  "41:13": ["So if they turn away, say: I have warned you of a thunderstrike like the thunderstrike of Ad and Thamud", "যদি তারা মুখ ফিরিয়ে নেয়, তাহলে বল, “আমি তোমাদেরকে সতর্ক করছি একটি বিপর্যয়ের বিষয়ে, এটা সেই বিপর্যয়ের মতো যা আদ এবং সামূদ জাতিকে বিলুপ্ত করেছিল।"],
  "41:14": ["When the Rasuls came to them from before them and from behind them — worship none but Allah — they said: if our Rabb willed, malakat would be sent down; so we reject what you were sent with", "তাদের বার্তাবাহক তাদের কাছে গিয়েছিল, সেই সাথে তাদের আগে এবং তাদের পরে, এ বলে যে, \"তোমরা আল্লাহ ছাড়া উপাসনা করবে না। “তারা বলেছিল, \"যদি আমাদের প্রভু চাইতেন, তিনি ফেরেশতা পাঠাতেন। যা তুমি বল তাতে আমরা অবিশ্বাসী।\""],
  "41:15": ["As for Ad, they grew arrogant in the land without right and said: who is stronger than us in strength? Have they not seen that Allah, who created them, is stronger than them in strength? And they used to deny Our verses", "আদের ক্ষেত্রে, তারা পৃথিবীতে উদ্ধত হয়ে পড়েছিল, সত্যের বিরোধিতা করতো, এবং বলেছিল, \"কে আমাদের চেয়ে বেশি ক্ষমতাধর?”তারা কি অনুধাবন করেনি যে আল্লাহ, যিনি তাদের সৃষ্টি করেছেন, তাদের চেয়ে বেশি ক্ষমতাধর? তারা আমাদের প্রকাশনাবলীর প্রতি অকৃতজ্ঞ ছিল।"],
  "41:16": ["So We sent upon them a raging wind on days of misfortune, to let them taste the punishment of disgrace in the life of this world; and the punishment of the Hereafter is more disgraceful — and they will not be helped", "ফলস্রুতিতে, আমরা তাদের উপর তীব্র বাতাস পাঠিয়েছিলাম, শোচনীয় কিছু দিনের জন্য। এই জীবনে আমরা এভাবে অপমানকর শাস্তি দিয়ে তাদেরকে কষ্ট দিয়েছিলাম, এবং পরকালের শাস্তি আরো অপমানকর, তারা কখনোই জয়লাভ করতে পারবে না।"],
  "41:17": ["And as for Thamud, We guided them, but they preferred blindness to the guidance, so the thunderstrike of the humiliating punishment seized them for what they used to earn", "আর সামুদের ক্ষেত্রে, তাদেরকে আমরা পথনির্দেশনা প্রদান করেছিলাম, কিন্তু তারা পথনির্দেশনার উপরে পছন্দ করেছিল অন্ধত্বকে। পরিনামে, সর্বনাশা এবং লজ্জাজনক শাস্তি তাদেরকে ধ্বংস করেছিল, তারা যা অর্জন করেছিল তার কারনে।"],
  "41:18": ["And We saved those who believed and were ever mindful", "আমরা সবসময় তাদেরকে রক্ষা করি যারা বিশ্বাস করে এবং সৎ জীবনযাপন করে।"],
  "41:19": ["And on the day Allah's enemies are gathered to the Fire, they are marshaled into it", "সে দিনটি আসবে যখন আল্লাহর শত্রুদেরকে নরকাগ্নির দিকে তলব করা হবে, বলপূর্বকভাবে।"],
  "41:20": ["Until, when they come to it, their hearing and their sight and their skins testify against them for what they used to do", "একবার তারা সেখানে পৌছঁলে, তাদের নিজেদের শ্রবণশক্তি, চোখ, এবং চামড়া সাক্ষী বহন করবে সবকিছুর যা তারা করেছিল।"],
  "41:21": ["And they will say to their skins: why did you testify against us? They will say: Allah gave us speech — Allah who gives speech to all things — who created you the first time; and to Allah you return", "তারা তাদের চামড়াকে বলবে, \"কেন তোমরা আমাদের বিরুদ্ধে সাক্ষী বহন করেছো? তারা উত্তর দিবে, \"আল্লাহ আমাদেরকে বাকশক্তি দিয়েছেন; তিনিই সে সত্ত্বা যিনি সবকিছুকে কথা বলার শক্তি দেন। তিনি সেই সত্ব্বা যিনি তোমাকে প্রথম বার সৃষ্টি করেছিলেন, এবং এখন তুমি তার কাছে ফিরে এসেছো।,\""],
  "41:22": ["And you were not hiding from your hearing, your sight, and your skins testifying against you; but you thought that Allah does not know much of what you do", "তোমাদের লুকানোর কোন উপায় নেই তোমাদের নিজেদের কান, তোমাদের চোখ, অথবা তোমাদের চামড়া থেকে। প্রকৃতপক্ষে, তোমরা ভেবেছিলে যে তোমরা যা করো তার বেশির ভাগ সম্পর্কে আল্লাহ অনবগত ছিলেন।"],
  "41:23": ["And that is the supposition you supposed about your Rabb; it has ruined you, so you became losers", "তোমাদের প্রভু সম্পর্কে এ ধরণের ভাবনা তোমাদের পতনের কারন হবে, এবং এরপর তোমরা ক্ষতিগ্রস্ত হয়ে পড়ো।"],
  "41:24": ["So if they endure, the Fire is their lodging; and if they plead for pardon, they are not among the pardoned", "যদি তারা তাদের পথে চলতে থাকে, নরক হবে তাদের নিয়তি, এবং যদি তারা অজুহাত তৈরি করে, তাদেরকে ক্ষমা করা হবে না।"],
  "41:25": ["And We assigned to them companions who made attractive to them what was before them and what was behind them; and the word came true against them among nations that passed away before them, of jinn and humans; truly they were losers", "আমরা তাদেরকে সহচর নিযুক্ত করি যারা তাদের চোখে সাজিয়ে দেয় সবকিছু, যা তারা করে। এভাবে, তারা শেষপর্যন্ত একই পরিনতি টেনে আনে পূর্ববর্তী জীন ও মানুষ সম্প্রদায়গুলোর মতো, ওরাও ক্ষতিগ্রস্থ ছিল।"],
  "41:26": ["And those who reject say: do not listen to this recital, and drown it in idle talk, so that you may prevail", "যারা অবিশ্বাস করেছিল তারা বলল, \"এই কুরআনের প্রতি মনোযোগ দিও না এবং একে বিকৃত করো, যাতে তোমরা জয়ী হতে পারো।"],
  "41:27": ["So We will surely let those who reject taste a severe punishment, and We will recompense them the worst of what they used to do", "আমরা নিশ্চিতভাবে এই অবিশ্বাসীদেরকে কঠোর শাস্তির মাধ্যমে কষ্ট দিবো। আমরা নিশ্চিতভাবে তাদের মন্দ কাজের জন্য তাদেরকে প্রতিদান দিবো।"],
  "41:28": ["That is the recompense of Allah's enemies: the Fire; for them in it is the abode of eternity, as recompense for their denying Our verses", "এমনই হলো প্রতিফল যা আল্লাহর শত্রুদের জন্য অপেক্ষা করে। নরক হবে তাদের চিরস্থায়ী আবাস; আমাদের প্রকাশনাবলী পরিত্যাগ করার জন্য একটি ন্যায্য প্রতিফল।"],
  "41:29": ["And those who reject will say: our Rabb, show us those who led us astray from among the jinn and humans; we will set them beneath our feet, so that they become among the lowest", "যারা অবিশ্বাস করেছিল তারা বলবে, \"আমাদের প্রভু, আমাদের দেখান - জ্বীন ও মানুষ - এই দুই প্রকারের মধ্যে তাদেরকে যারা আমাদেরকে বিভ্রান্ত করেছিল, যাতে আমরা তাদেরকে আমাদের পায়ের নিচে পদদলিত করতে পারি, এবং তাদেরকে নিম্নতম অবস্থায় রাখুন।\""],
  "41:30": ["Truly those who said our Rabb is Allah, and then stood firm — the malakat are sent down to them: do not fear and do not grieve, and be glad with the Garden you were promised", "যারা ঘোষনা করে,\"আমাদের প্রভু হলো আল্লাহ, ” এরপর সৎ জীবন-যাপন করে, ফেরেশতারা তাদের উপর অবতরণ করে: \"তোমাদের কোন ভয় থাকবে না, না তোমরা শোক করবে। আনন্দ করো শুভ সংবাদে যে স্বর্গ তোমাদের জন্য সংরক্ষণ করা হয়েছে।"],
  "41:31": ["We are your protectors in the life of this world and in the Hereafter; and for you in it is what your souls desire, and for you in it is what you call for", "আমরা তোমাদের বন্ধু, এই জীবনে এবং পরকালে। এতে তোমাদের জন্য থাকবে যে কোন কিছু যার জন্য তোমরা ইচ্ছা পোষন করো; তোমাদের জন্য থাকবে যে কোন কিছু যা তোমরা চাও।"],
  "41:32": ["A gift sent down from the Forgiving, the Rahim", "\"(এমনই তোমাদের) চূড়ান্ত আবাস, একজন ক্ষমাকারী, সবচেয়ে দয়ালুর পক্ষ থেকে। \""],
  "41:33": ["And who speaks better than one who calls to Allah, does good, and says: I am among the submitters", "কে তার চেয়ে উত্তম কথা বলতে পারে যে আল্লাহর দিকে আহবান করে, সৎ কাজ করে এবং বলে, \"আমি আত্মসমর্পণকারীদের একজন\"?"],
  "41:34": ["And the good deed and the bad deed are not equal; repel with that which is better, and the one between whom and you there is enmity becomes as though a close friend", "ভালো প্রতিক্রিয়া এবং মন্দ প্রতিক্রিয়া সমান নয়। তুমি যথাসম্ভব সুন্দর প্রতিক্রিয়া অবলম্বন করবে। এভাবে, যে ব্যক্তি তোমার শত্রু ছিল, সে তোমার সবচেয়ে ভাল বন্ধু হয়ে যেতে পারে।"],
  "41:35": ["And none is granted it but those who endure, and none is granted it but one of a great portion", "কেউ তা অর্জন করতে পারে না তারা ব্যতিত যারা দৃড়তার সাথে অধ্যবসায়ী। কেউ তা অর্জন করতে পারে না তারা ব্যতিত যারা অত্যন্ত সৌভাগ্যবান।"],
  "41:36": ["And if a sting from Shaytan stings you, seek refuge with Allah; truly Allah is the Hearing, the Knowing", "যখন শয়তান তোমার কাছে কোন ধারনা ফিস ফিস করে, তুমি আল্লাহর নিকট আশ্রয় খুঁজবে। তিনি শ্রোতা, সর্বজ্ঞ।"],
  "41:37": ["And of Allah's signs are the night and the day and the sun and the moon; do not bow to the sun or to the moon, but bow to Allah who created them, if it is Allah you worship", "তাঁর প্রমানসমূহের মধ্যে রয়েছে রাত ও দিন, এবং সূর্য ও চাঁদ। সূর্যের সামনে সেজদা করো না, চাঁদের সামনেও না; তোমরা আল্লাহর সামনে সেজদায় পতিত হবে যিনি তাদের সৃষ্টি করেছেন, যদি সত্যি তোমরা কেবল তাঁর উপাসনা করো।"],
  "41:38": ["And if they grow arrogant, those near your Rabb glorify Allah by night and by day, and they never weary", "যদি তারা এটা করতে অত্যন্ত উদ্ধত হয়, তাহলে তোমার প্রভুর সান্নিধ্যে যারা রয়েছে তারা তাঁর মহিমা প্রকাশ করে রাতে ও দিনে, কখনো ক্লান্ত না হয়ে।"],
  "41:39": ["And of Allah's signs is that you see the earth humbled; and when We send down water upon it, it stirs and rises; truly the One who revived it will surely revive the dead; truly Allah is over all things powerful", "তাঁর প্রমানসমূহের মধ্যে রয়েছে যে তুমি ভূমিকে দেখো স্থির, এরপর, যখনই আমরা এর উপর পানি বর্ষণ করি, এতে জীবনের স্পন্দন হয়। নিশ্চয়, যে সত্ত্বা একে পূনরূজ্জীবিত করেছেন মৃতকেও তিনি পূনরূজ্জীবিত করতে পারেন। তিনি সর্বশক্তিমান।"],
  "41:40": ["Truly those who deviate about Our verses are not hidden from Us; is one cast into the Fire better, or one who comes secure on the Day of Rising? Do what you will — truly Allah sees what you do", "নিশ্চয়, যারা আমাদের প্রকাশনাবলি বিকৃত করে তারা আমাদের কাছ থেকে গোপন নয়। যে ব্যক্তিকে নরকে নিক্ষেপ করা হয় সে উত্তম, নাকি যে ব্যক্তি পুনরুত্থান দিনে আসে নিরাপদ হয়ে? তোমরা যা চাও করো; তিনি সবকিছুর দেখেন যা তোমরা করো।"],
  "41:41": ["Truly those who reject the Reminder when it comes to them — and truly it is a mighty book", "যারা কুরআনের প্রমানকে প্রত্যাখ্যান করেছে যখন তা তাদের কাছে এসেছিল, তারা প্রত্যাখ্যান করেছে একটি সম্মানিত গ্রন্থকেও।"],
  "41:42": ["Falsehood does not come to it from before it or from behind it; a sending-down from the Wise, the Praiseworthy", "কোন মিথ্যা এতে প্রবেশ করতে পারতো না, অতীতে বা ভবিষ্যতে; সবচেয়ে প্রজ্ঞাবান, প্রশংসনীয়ের পক্ষ থেকে একটি প্রকাশনা।"],
  "41:43": ["Nothing is said to you but what was said to the Rasuls before you; truly your Rabb is forgiving and possessor of a painful penalty", "যা তোমাকে বলা হয়, ঠিক একই কথা পূর্ববর্তী বার্তাবাহকদেরও বলা হয়েছিল। তোমার প্রভু ক্ষমাশীলতার অধিকারী, এবং তিনি যন্ত্রনাদায়ক শাস্তিরও অধিকারী।"],
  "41:44": ["Had We made it a recital in a foreign tongue, they would have said: why are its verses not made clear — is it foreign and clear-Arabic? Say: it is, for those who believe, guidance and healing; and those who do not believe — in their ears is a heaviness, and it is blindness over them; those are the ones called from a far-off place", "যদি আমরা একে একটি অ-আরবী কুরআন করতাম তারা বলতো, “এটি কেন ঐ ভাষায় এসেছে?” হোক এটি আরবিয় অথবা অ-আরবীয়, বল, “যারা বিশ্বাস করে তাদের জন্য, এটি একটি পথপ্রদর্শক এবং নিরাময়। আর যারা অবিশ্বাস করে, তারা এর প্রতি হবে বধির এবং অন্ধ, যেন তাদেরকে বহুদূর থেকে ডাকা হচ্ছে।”"],
  "41:45": ["And We gave Musa the Book, and they differed over it; and had not a word preceded from your Rabb, judgment would have been made between them; and truly they are in a doubting doubt about it", "আমরা মূসাকে ঐশীগ্রন্থ দিয়েছি এবং এতেও বিবাদ করা হয়েছিল। যদি এটি তোমার প্রভুর পূর্বনির্ধারিত সিদ্ধান্ত না হতো, অবিলম্বে তাদের বিচার করা হতো। প্রকৃতপক্ষে, তারা অনেক বেশি সন্দেহ পোষন করে।"],
  "41:46": ["Whoever does good, it is for their own soul, and whoever does ill, it is against it; and your Rabb is not unjust to the servants", "যেকেউ সৎকর্ম করে, তা তার নিজের ভালোর জন্য করে, এবং যেকেউ মন্দকর্ম করে তা তার নিজের ক্ষতির জন্য করে। তোমার প্রভু লোকদের প্রতি কখনো অন্যায়কারী নন।"],
  "41:47": ["To Allah returns the knowledge of the Hour; no fruit comes out of its husk, and no female bears or gives birth except with Allah's knowledge; and on the day Allah calls them — where are My partners? — they will say: we declare to You that none of us is a witness", "তাঁর কাছেই রয়েছে সে ঘন্টা (মহাবিশ্বের পরিসমাপ্তি) সম্পর্কে জ্ঞান। কোন ফলই তাদের খোল থেকে বেরিয়ে আসে না, না কোন নারী গর্ভধারণ করে বা জন্ম দেয়, তাঁর জ্ঞান ছাড়া। সে দিন আসবে যখন তিনি তাদের জিজ্ঞেস করবেন: \"কোথায় সে উপাস্যরা যা তোমরা আমার পাশে স্থাপন করেছ?”তারা বলবে, \"আমরা আপনার কাছে ঘোষনা করি যে আমাদের কেউ এর সাক্ষ্য বহন করে না।"],
  "41:48": ["And lost to them is what they used to call upon before, and they will think there is no escape for them", "তারা যাদেরকে প্রতিমায় করেছিল সেই উপাস্যরা তাদেরকে প্রত্যাখ্যান করবে, এবং তারা অনুধাবন করবে যে পালানোর কোন উপায় নেই।"],
  "41:49": ["Man does not weary of calling for good; but if evil touches him, he is despairing, hopeless", "মানুষ ভাল জিনিসের জন্য মিনতি করে কখনো ক্লান্ত হয় না। এবং যখন দুর্দশা তার উপর পতিত হয়, সে হতাশ, বেপরোয়া হয়ে যায়।"],
  "41:50": ["And if We let him taste a mercy from Us after distress that touched him, he will surely say: this is mine; and I do not think the Hour is coming; and if I return to my Rabb, the best is surely mine with Allah; so We will surely tell those who reject what they did, and We will let them taste a hard punishment", "এবং যখন আমরা তাকে কিছু দূর্ভোগের পর অনুগ্রহ করি, সে বলে, \"এটা আমার অধীনে। আমি বিশ্বাস করি না যে সে সময় কখনো সংঘটিত হবে। এমনকি আমি আমার প্রভুর কাছে ফিরে গেলেও আমি তাঁর কাছে উত্তম জিনিস পাবো। সুনিশ্চিতভভাবে, আমরা অবিশ্বাসীদেরকে তাদের কাজের বিষয়ে অবহিত করবো, এবং তাদেরকে কঠোর শাস্তি দেব।"],
  "41:51": ["And when We bless man, he turns aside and keeps to his side; and when evil touches him, his calling is wide", "যখন আমরা মানুষকে অনুগ্রহ করি, সে মুখ ফিরিয়ে নেয়, এবং বিমুখতায় আরো বেশি ঝুঁকে পড়ে, এবং যখন সে কোন দূর্দশা ভোগ করে, সে উচ্চৈঃস্বরে মিনতি করে।"],
  "41:52": ["Say: tell me — if it is from Allah and then you reject it, who is more astray than one in far opposition?", "ঘোষনা করো: \"যদি এটি সত্যিই আল্লাহ থেকে হয়,  আর তোমরা একে প্রত্যাখ্যান করার সিদ্ধান্ত নাও? কে তার চেয়ে অধিক পথভ্রষ্ট যে এর বিরোধিতা করার সিদ্ধান্ত নেয়?\""],
  "41:53": ["We will show them Our signs on the horizons and in themselves, until it becomes clear to them that it is the truth; is it not sufficient concerning your Rabb that Allah is witness over all things?", "আমরা তাদেরকে আমাদের প্রমাণাদি দেখাবো দিগন্তসমূহে, এবং তাদের নিজেদের মধ্যে, যতক্ষণ না তারা অনুধাবন করে যে এটাই সত্য। তোমার প্রভু কি যথেষ্ট নয়, সবকিছুর সাক্ষী হিসেবে?"],
  "41:54": ["Truly they are in doubt about meeting their Rabb; truly Allah encompasses all things", "প্রকৃতপক্ষে, তারা তাদের প্রভুর সাথে সাক্ষাতের বিষয়ে সন্দিহান। তিনি সবকিছুর বিষয়ে পূর্ণ অবগত।"],
  "42:1": ["Ha Mim", "হ. ম. (হা মীম)"],
  "42:2": ["Ayn Sin Qaf", "আ. স. ক.  (আয়িন সিন কাফ)"],
  "42:3": ["Thus Allah, the Mighty, the Wise, reveals to you and to those who were before you.", "তোমার, এবং তোমার পূর্ববর্তীদের অনুপ্রেরণায় আছেন, আল্লাহ, সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "42:4": ["To Allah belongs what is in the heavens and what is in the earth, and Allah is the Exalted, the Supreme.", "আকাশমন্ডলীর সবকিছু এবং পৃথিবীর সবকিছু তাঁর অধীনে,এবং তিনি সর্বাধিক উচ্চ, মহান।"],
  "42:5": ["The heavens nearly cleave asunder from above them, and the malakat declare the glory of their Rabb in praise and ask forgiveness for those on earth. Indeed, Allah is the Forgiving, the Raheem.", "তাদের উপর আকাশমন্ডলী প্রায় চূর্ণ হয়ে যায়, তাঁর প্রতি ভক্তিতে এবং স্বর্গদূতরা তাদের প্রভুর প্রশংসা এবং মহিমা ঘোষনা করে, এবং তারা ক্ষমা চায় তাদের জন্য যারা পৃথিবীর উপর আছে। নি:সন্দেহে,আল্লাহ ক্ষমাকারী,সবচেয়ে দয়ালু।"],
  "42:6": ["And those who take protectors besides Allah — Allah keeps watch over them, and you are not set over them as a disposer.", "যারা তাঁর পাশে অন্য উপাস্য স্থাপন করে,আল্লাহ সেই সত্ত্বা যিনি তাদের দায়িত্বে রয়েছেন; তুমি তাদের উকিল নও।"],
  "42:7": ["And thus We revealed to you an Arabic recitation, that you may warn the mother of the towns and those around it, and warn of the Day of Gathering in which there is no doubt: a party in the Garden and a party in the Blaze.", "আমরা এভাবে তোমার কাছে আরবি কুরআন প্রকাশ করি কেন্দ্রীয় সম্প্রদায় এবং এর আশেপাশের সবাইকে সতর্ক করতে, এবং সতর্ক করতে আহবান দিনের বিষয়ে যা অনিবার্য। শেষপর্যন্ত কারো পরিনতি হবে স্বর্গে, আর কারো নরকে।"],
  "42:8": ["And if Allah had willed, Allah would have made them one community; but Allah admits whom Allah wills into mercy, and the wrongdoers have no protector and no helper.", "যদি আল্লাহ চাইতেন, তিনি তাদেরকে এক সম্প্রদায়ভুক্ত করতে পারতেন। কিন্তু তিনি তাঁর দয়ায় যাকেই চান উদ্ধার করেন। আর সীমালঙ্ঘনকারীদের ক্ষেত্রে, তাদের না আছে কোন অভিভাবক, আর না কোন সাহায্যকারী।"],
  "42:9": ["Or have they taken protectors besides Allah? Yet Allah is the Protector, and Allah gives life to the dead, and Allah is over all things powerful.", "তারা কি তাঁর পাশে অন্য প্রভুদের খুঁজে পেয়েছে? শুধুমাত্র আল্লাহ প্রভু এবং মনিব। তিনিই সে সত্ত্বা যিনি মৃতকে পুনরুজ্জীবিত করেন, এবং তিনি সর্বশক্তিমান সত্ত্বা।"],
  "42:10": ["And whatever you differ about in anything, its decision rests with Allah. That is Allah, my Rabb; upon Allah I trust, and to Allah I turn back.", "তোমরা এই বার্তার কোন অংশ নিয়ে বিবাদ করলে,এর বিচারের ভার আল্লাহর হাতে। এমনই আল্লাহ আমার প্রভু। আমি তাঁর উপর আস্থা রাখি,এবং তাঁর কাছে আমি আত্মসমর্পণ করি।"],
  "42:11": ["Originator of the heavens and the earth, Allah made for you spouses from yourselves and pairs from the cattle, spreading you forth thereby. There is nothing like a likeness of Allah, and Allah is the All-Hearing, the All-Seeing.", "আকাশমণ্ডলী এবং পৃথিবীর সূচনাকারী। তিনি তোমাদের জন্য স্বামী-স্ত্রী সৃষ্টি করেছেন তোমাদের নিজেদের মধ্য থেকে, এবং প্রাণীদের জন্যও। তিনি এভাবে তোমাদেরকে বংশবৃদ্ধির উপায় প্রদান করেন। কোন কিছু নেই যা তাঁর সমান। তিনি শ্রোতা, দ্রষ্টা।"],
  "42:12": ["To Allah belong the keys of the heavens and the earth; Allah spreads provision for whom Allah wills and measures it. Indeed, Allah is knowing of all things.", "আকাশমণ্ডলী এবং পৃথিবী তাঁর একচ্ছত্র নিয়ন্ত্রণাধীন। তিনিই সে সত্ত্বা যিনি যার জন্য ইচ্ছা জীবিকা বৃদ্ধি করেন, অথবা তা কমিয়ে দেন। তিনি সবকিছু সম্পর্কে পূর্ণ অবগত।"],
  "42:13": ["Allah laid down for you of the Way what was charged to Nuh, and what We revealed to you, and what We charged to Ibrahim and Musa and Isa: establish the Way and do not divide therein. Grievous to the associators is what you call them to. Allah chooses for it whom Allah wills and guides to it whoever turns back.", "তিনি তোমাদের জন্য জারি করেছেন সে একই ধর্ম যা জারি করেছিলেন নুহের জন্য, এবং যা আমরা প্রত্যাদেশ করেছিলাম তোমার প্রতি, এবং যা আমরা জারি করেছিলাম ইব্রাহীম, মুসা, এবং ঈসার উপর: \"তুমি এই একটি ধর্ম মেনে চলবে, এবং একে বিভক্ত করবে না। প্রতিমা-উপাসকরা তাতে ভীষন ক্ষুব্ধ হবে যা করতে  তুমি তাদের আমন্ত্রণ করো। আল্লাহ নিজের দিকে পুনরুদ্ধার করেন যাকেই তিনি চান;  আল্লাহ শুধু তাদেরকে নিজের পথ দেখান যারা পুরোপুরিভাবে আত্মসমর্পণ করে।"],
  "42:14": ["They did not divide except after knowledge came to them, out of envy among themselves. And had not a decree from your Rabb preceded to an appointed term, judgement would have been passed between them. And indeed those who received the scriptures after them are in disquieting doubt about it.", "দুঃখজনকভাবে, তারা দলে-উপদলে ভাগ হয়েছিল শুধুমাত্র জ্ঞান আসার পর, তাদের নিজেদের মধ্যে ঈর্ষা এবং বিদ্বেষের কারণে। যদি তাদেরকে একটি সুনির্দিষ্ট অন্তর্বর্তী সময়ের জন্য অবকাশ দেয়ার পূর্বনির্ধারিত সিদ্ধান্ত তোমার প্রভুর পক্ষ থেকে না থাকতো, তাদের বিচার অবিলম্বে করা হত।"],
  "42:15": ["So to that call, and stand firm as you were commanded, and do not follow their desires, and say: I believe in what Allah has sent down of books, and I was commanded to do justice among you. Allah is our Rabb and your Rabb; for us our deeds and for you your deeds; no proof is there between us and you. Allah will gather us together, and to Allah is the arrival.", "এটাই তুমি প্রচার করবে এবং অবিচলভাবেকরতে থাকো যা করতে তোমাকে আদেশ করা হয়, এবং তাদের ইচ্ছার অনুসরণ করো না। এবং ঘোষনা করো, \"আমি বিশ্বাস করি আল্লাহর অবতীর্ণ সকল ঐশিগ্রন্থে। আমাকে তোমাদের মধ্যে ন্যায়সঙ্গতভাবে বিচার করতে আদেশ করা হয়েছে। আল্লাহ একইসাথে আমাদের প্রভু এবং তোমাদের প্রভু। আমাদের রয়েছে আমাদের কর্ম, তোমাদের রয়েছে তোমাদের কর্ম। আমাদের এবং তোমাদের মাঝে কোন তর্ক-বিবাদ নেই। আল্লাহ আমাদের সবাইকে একসাথে একত্রিত করবেন; তাঁর কাছেই চূড়ান্ত নিয়তি।"],
  "42:16": ["And those who argue about Allah after the answer has been given to it — their argument is void before their Rabb, and upon them is wrath, and for them is a severe punishment.", "যারা আল্লাহ সম্পর্কে তর্ক করে, তাঁর বার্তা পাওয়ার পর, তাদের তর্ক আল্লাহ বাতিল করে দেন। তারা টেনে এনেছে নিন্দা, এবং তারা কঠিন শাস্তি অর্জন করেছে।"],
  "42:17": ["Allah is the one who sent down the Book with the truth and the Balance. And what tells you — perhaps the Hour is near.", "আল্লাহ সেই সত্ত্বা যিনি ঐশিগ্রন্থ পাঠিয়েছেন, সত্য এবং আইন পৌঁছে দিতে। যতটুকু তুমি জানো, সে সময় (বিচার দিবস) হয়তো খুব নিকটে।\""],
  "42:18": ["Those who do not believe in it hasten it on, while those who believe are in awe of it and know that it is the truth. Indeed, those who doubt the Hour are in error far away.", "যারা এতে বিশ্বাস করে না তারা এর প্রতি চ্যালেঞ্জ করছে। আর যারা বিশ্বাস করে, তারা এটা সম্পর্কে উদ্বিগ্ন, এবং তারা জানে যে এটা সত্য। নিঃসন্দেহে, যারা সে সময়কে অস্বীকার করে, তারা বহুদূরে পথভ্রষ্ট হয়েছে।"],
  "42:19": ["Allah is subtle-kind to the servants, providing for whom Allah wills, and Allah is the Powerful, the Mighty.", "আল্লাহ তাঁর সব সৃষ্টি সম্পর্কে পূর্ণ  অবগত; তিনি যাকেই ইচ্ছা জীবিকা দেন। তিনি ক্ষমতাশালী, সর্বশক্তিমান।"],
  "42:20": ["Whoever wills the tillage of the Hereafter, We increase for that one in their tillage; and whoever wills the tillage of this near world, We give them thereof, but they have in the Hereafter no allotted portion.", "যে কেউ পরকালের পুরষ্কার খোঁজে, আমরা তার জন্য পুরষ্কার বহুগুনে বাড়িয়ে দেই। এবং যে কেউ দুনিয়ার বস্তু খোঁজে, আমরা তাকে তা থেকে দেই, কিন্তু পরকালে সে কোন অংশ পায় না।"],
  "42:21": ["Or have they partners who laid out for them of the Way what Allah did not permit? And were it not for the decisive word, judgement would have been passed between them. And indeed the wrongdoers have a painful punishment.", "তারা অনুসরণ করে উপাস্যদের যারা তাদের জন্য জারি করে ধর্মীয় আইনসমূহ যা কখনো আল্লাহ দ্বারা অনুমোদিত হয়নি। যদি পূর্বনির্ধারিত সিদ্ধান্ত না থাকতো,তৎক্ষণাৎ তাদের বিচার হয়ে যেতো। আসলে, সীমালঙ্ঘনকারীরা টেনে এনেছে এক যন্ত্রনাদায়ক শাস্তি ।"],
  "42:22": ["You will see the wrongdoers in awe of what they earned, and it will befall them; and those who believed and did the good deeds are in the meadows of the Gardens, having what they wish with their Rabb. That is the great favor.", "তুমি দেখবে যে সীমালঙ্ঘনকারীরা সবকিছু সম্পর্কে চিন্তিত যা তারা করেছিল ; সবকিছু ফিরে আসবে এবং তাদেরকে তাড়া করবে। আর তাদের ক্ষেত্রে যারা বিশ্বাস করেছিল এবং সৎ জীবন যাপন করেছিল, তারা স্বর্গের বাগানগুলোতে থাকবে। তারা তাদের প্রভুর কাছ থেকে পাবে, যা কিছুই তারা ইচ্ছা করে। এটি সে বিশাল অনুগ্রহ।"],
  "42:23": ["That is the good news Allah gives to the servants who believe and do good deeds. Say: I do not ask of you a reward for it except affection among kin; and whoever commits a good deed, We increase for that one good therein. Indeed, Allah is Forgiving, Thankful.", "এটি আল্লাহর পক্ষ থেকে তাঁর বান্দাদের জন্য সুসংবাদ যারা বিশ্বাস করে ও সৎ জীবনযাপন করে। বল, \"আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না। আমি চাই যে তোমাদের প্রত্যেকে নিজ নিজ আত্মীয়-স্বজনদের যত্ন নাও।\" যেকেউ একটি সৎকাজ করে, আমরা তার পুরষ্কারকে এর জন্য বহুগুণে বাড়িয়ে দেই। আল্লাহ ক্ষমাকারী, কৃতজ্ঞ।"],
  "42:24": ["Or do they say: he fabricated a lie against Allah? But if Allah willed, Allah would seal up your heart; and Allah blots out the falsehood and establishes the truth by Allah's words. Indeed, Allah is knowing of what the chests hold.", "তারা কি বলছে, \"সে (রাশাদ) আল্লাহ সম্বন্ধে মিথ্যা রচনা করেছে!\"? যদি আল্লাহ চাইতেন, তিনি তোমাদের মনে মোহর মেরে দিতে পারতেন, কিন্তু আল্লাহ মিথ্যা মুছে ফেলেন এবং তাঁর শব্দাবলী দিয়ে সত্য স্থাপন করেন। তিনি গভীরতম চিন্তাগুলো সম্পর্কে পূর্ণ অবগত।"],
  "42:25": ["And Allah is the one who accepts repentance from the servants and passes over the bad deeds, and knows what you do.", "তিনি সে সত্ত্বা যিনি তাঁর বান্দাদের থেকে অনুশোচনা গ্রহন করেন, এবং পাপগুলো ক্ষমা করে দেন। তোমাদের করা সবকিছু সম্পর্কে তিনি সম্পূর্ণ অবগত।"],
  "42:26": ["And Allah answers those who believe and do good deeds, and increases them of favor; and for the kafirin is a severe punishment.", "যারা বিশ্বাস করে এবং সৎ জীবনযাপন করে তারা তাঁর প্রতি সাড়া দেয় । তিনি তাদের উপর তাঁর অনুগ্রহ বর্ষণ করবেন। আর অবিশ্বাসীদের ক্ষেত্রে,তারা টেনে এনেছে এক কঠোর শাস্তি।"],
  "42:27": ["And if Allah spread out provision for the servants, they would transgress in the earth; but Allah sends down in measure what Allah wills. Indeed, Allah is aware of, seeing, the servants.", "যদি আল্লাহ তাঁর বান্দাদের জন্য জীবিকা বৃদ্ধি করতেন, তারা পৃথিবীতে সীমালঙ্ঘন করতো। এজন্যই তিনি এটি পরিমিতভাবে পাঠান যার জন্যই তিনি চান। তিনি তাঁর বান্দাদের বিষয়ে পূর্ণ অবগত এবং দ্রষ্টা।"],
  "42:28": ["And Allah is the one who sends down the rain after they despaired, and unfolds Allah's mercy, and Allah is the Protector, the Praised.", "তিনিই সে সত্ত্বা যিনি বৃষ্টি অবতীর্ণ করেন তারা হতাশ হবার পর, এবং তাঁর দয়া ছড়িয়ে দেন। শুধুমাত্র তিনিই মনিব, সবচেয়ে প্রশংসনীয়।"],
  "42:29": ["And among the signs of Allah are the creation of the heavens and the earth, and the creatures scattered through them, and Allah is powerful over gathering them whenever Allah wills.", "তাঁর প্রমাণাদির মধ্যে রয়েছে আকাশমণ্ডলী এবং পৃথিবীর সৃষ্টি, এবং সে সৃষ্টিগুলো যা তিনি এদের মধ্যে ছড়িয়ে দেন। তিনি তাদেরকে তলব করতে সক্ষম, যখন তিনি চান।"],
  "42:30": ["And whatever affliction befalls you is for what your hands earned, and Allah passes over much.", "খারাপ যা কিছুই তোমাদের ক্ষেত্রে ঘটে তা তোমাদের নিজেদের কর্মের ফল, এবং (তোমাদের পাপের) অনেকগুলো তিনি এড়িয়ে যান।"],
  "42:31": ["And you cannot go beyond power in the earth, and you have besides Allah no protector and no helper.", "তোমরা কখনো পালাতে পারবে না, এবং আল্লাহর পাশে প্রভু এবং মনিব হিসেবে তোমাদের কেউ নেই।"],
  "42:32": ["And among the signs of Allah are the ships that run in the sea, like towering landmarks.", "তার প্রমাণাদির মধ্যে আছে জাহাজগুলো, যা পতাকার মত পালতোলে সমুদ্রে ভেসে বেড়ায়।"],
  "42:33": ["If Allah wills, Allah stills the wind, and they become lying motionless upon its surface. Indeed in that are signs for everyone sabir, grateful.", "যদি তিনি চাইতেন, তিনি বাতাসকে স্থির করে দিতে পারতেন, যা তাদেরকে পানির উপরিভাগে গতিহীন করে দেয়। এগুলো তাদের জন্য প্রমাণ যারা অবিচল, কৃতজ্ঞ।"],
  "42:34": ["Or Allah destroys them for what they earned, and passes over much.", "তিনি তাদেরকে ধ্বংস করতে পারতেন, তাদের নিজেদের কাজের প্রতিফল হিসেবে। তা সত্ত্বেও, তিনি (তাদের পাপের) অনেকগুলো এড়িয়ে যান।"],
  "42:35": ["And Allah lets those who dispute about Our signs know that they have no escape-way.", "আমাদের প্রমাণের বিরুদ্ধে যারা তর্ক করে,তারা খু্ঁজে পাবে যে তাদের কোন ভিত্তি নেই।"],
  "42:36": ["So whatever you are given of anything, enjoy the life of this near world; but what is with Allah is better and more lasting, for those who believe and trust in their Rabb.", "তোমাদের যা কিছুই দেওয়া হোক না কেন, তা এই জীবনের ক্ষণস্থায়ী বস্তুর চেয়ে বেশি কিছু নয়। আল্লাহ যা অধিকার করেন তা অনেক উত্তম এবং চিরস্থায়ী,  তাদের জন্য যারা বিশ্বাস করে এবং তাদের আল্লাহতে আস্থা রাখে।"],
  "42:37": ["And those who avoid the great sins and the obscenitys, and when they are angry, they forgive.", "তারা গুরুতর পাপসমূহ এবং অনৈতিকতা এড়িয়ে চলে, এবং যখন  রাগান্বিত হয়, তারা ক্ষমা করে দেয়।"],
  "42:38": ["And those who answer their Rabb, establish the prayer, whose affair is consultation among them, and spend of what We provided them.", "তারা সংযোগ প্রার্থনার মাধ্যমে তাদের আল্লাহর প্রতি সাড়া দেয়। তাদের বিষয়াদিতে সিদ্ধান্ত হয় তাদের নিজেদের মধ্যে পরামর্শের পর, এবং তাদের প্রতি আমাদের জীবিকা থেকে তারা দেয় (দানে)।"],
  "42:39": ["And those who, when wrong afflicts them, stand up for themselves.", "যখন তাদের সাথে স্পষ্ট অবিচার করা হয়, তারা তাদের অধিকারের জন্য সোচ্চার হয়।"],
  "42:40": ["And the recompense of a bad deed is a bad deed like it; but whoever passes over and sets things right, their reward is upon Allah. Indeed, Allah does not love the wrongdoers.", "যদিও কোন অবিচারের সঠিক শাস্তি হলো একটি সমতুল্য শাস্তি,যারা ক্ষমা করে এবং সৎকর্মশীলতা বজায় রাখে তারা আল্লাহর দ্বারা পুরষ্কৃত হয়। তিনি অন্যায়কে ভালবাসেন না।"],
  "42:41": ["And whoever stands up for themselves after being wronged — those have no way of blame against them.", "নিশ্চয়, তারা কোন ভুল করে না, যারা তাদের অধিকারের জন্য সোচ্চার হয়, যখন তাদের সাথে অবিচার করা হয়।"],
  "42:42": ["Blame is only upon those who wrong the people and transgress in the earth without right. Those have a painful punishment.", "তারাই ভুল, যারা লোকদের সাথে অন্যায় আচরণ করে এবং কোন উস্কানি না থাকা সত্ত্বেও আগ্রাসন অবলম্বন করে। এরা টেনে এনেছে এক যন্ত্রণাদায়ক শাস্তি।"],
  "42:43": ["And whoever is sabir and forgives — indeed that is of the resolve of great affairs.", "ধৈর্য্য এবং ক্ষমাশীলতা অবলম্বন করা চরিত্রের প্রকৃত জোরকে প্রতিফলন করে।"],
  "42:44": ["And whomever Allah leads astray has no protector after that. And you will see the wrongdoers, when they see the punishment, saying: is there any way of return?", "যাকেই আল্লাহ পথভ্রষ্ট করেন, সে কখনো অন্য কোন প্রভু খুঁজে পাবে না, এবং তুমি এমন সীমালঙ্ঘনকারীদের দেখবে, যখন তারা শাস্তি দেখে  বলছে যে,\"আমরা কি আরেকবার সুযোগ পেতে পারি? \""],
  "42:45": ["And you will see them presented before it, humbled by abasement, looking with a hidden glance. And those who believed will say: indeed the khasirin are those who lose themselves and their families on the Day of Rising. Indeed the wrongdoers are in a lasting punishment.", "তুমি তাদেরকে দেখবে, অপমানিত এবং অপদস্থ হয়ে, এর মুখোমুখি হবে, এবং তাকাবে, যদিও না তাকানোর চেষ্টা করবে। যারা বিশ্বাস করেছিল তারা ঘোষনা করবে, \"তারা প্রকৃত ক্ষতিগ্রস্ত যারা পূনরুত্থান দিবসে তাদের আত্না এবং তাদের পরিবারকে হারিয়েছে। সীমালঙ্ঘনকারীরা চিরস্থায়ী শাস্তির যোগ্য হয়েছে।\""],
  "42:46": ["And they have no protectors to help them besides Allah, and whomever Allah leads astray has no way.", "আল্লাহর বিরুদ্ধে তাদেরকে সাহায্য করার জন্য সেখানে কোন মিত্র থাকবে না। যাকেই আল্লাহ পথভ্রষ্ট করেন, সে কখনো পথপ্রাপ্ত হয় না।"],
  "42:47": ["Answer your Rabb before a day comes for which there is no turning back from Allah. You have no refuge that day, and no one to disavow for you.", "তোমরা তোমাদের প্রভুর প্রতি সাড়া দিবে, সে দিনের আগে যা আল্লাহর দ্বারা অনিবার্য করা হয়েছে। ঐদিন তোমাদের জন্য না থাকবে কোন আশ্রয়স্থল, না কোন উকিল।"],
  "42:48": ["So if they turn away, We did not send you as a keeper over them; upon you is only the conveyance. And when We let a human taste mercy from Us, that one rejoices in it; and if a bad deed afflicts them for what their hands sent forth, then indeed the human is ungrateful.", "যদি তারা মুখ ফিরিয়ে নেয়, আমরা তোমাকে তাদের অভিভাবক হিসেবে পাঠাইনি। তোমার একমাত্র দায়িত্ব বার্তা পৌঁছে দেয়া। যখন আমরা মানুষের উপর দয়া বর্ষণ করি, তারা গর্বিত হয়ে ওঠে, এবং দুর্দশা যখন তাদেরকে পীড়া দেয়, তাদের নিজেদের কাজের পরিনামে, মানুষ অবিশ্বাসীতে পরিনত হয়।"],
  "42:49": ["To Allah belongs the kingdom of the heavens and the earth; Allah creates what Allah wills; Allah grants to whom Allah wills females, and grants to whom Allah wills males.", "আকাশমণ্ডলী এবং পৃথিবীর সার্বভৌমত্ব আল্লাহর অধীনে। তিনি সৃষ্টি করেন যা কিছুই তিনি ইচ্ছা করেন, তিনি যাকে ইচ্ছা কন্যা সন্তান দেন, এবং যাকে ইচ্ছা পুত্র  সন্তান দেন।"],
  "42:50": ["Or Allah pairs them, males and females, and makes whomever Allah wills barren. Indeed, Allah is knowing, powerful.", "অথবা, হয়তো তিনি নারী এবং পুরুষদের একে অন্যকে বিয়ে করতে দেন, এরপর যাকেই তিনি চান বন্ধ্যা করেন। তিনি সর্বজ্ঞ, সর্বশক্তিমান।"],
  "42:51": ["It is not for a human that Allah should speak to them except by revelation, or from behind a veil, or by sending a Rasul who reveals by Allah's permission what Allah wills. Indeed, Allah is the Exalted, the Wise.", "কোন মানুষ আল্লাহর সাথে যোগাযোগ করতে পারে না, প্রত্যাদেশের মাধ্যমে, অথবা কোন অন্তরালের পেছন থেকে, অথবা কোন বার্তাবাহক পাঠানোর মাধ্যম ব্যতীত, যার দ্বারা তিনি যা চান প্রকাশ করেন।তিনি সবচেয়ে উর্দ্ধে, সবচেয়ে প্রজ্ঞাবান।"],
  "42:52": ["And thus We revealed to you a spirit of Our command. You did not know what the Book was, nor faith, but We made it a light by which We guide whom We will of Our servants. And indeed you guide to a straight path.", "এভাবে, আমরা তোমাকে অনুপ্রাণিত করেছি একটি প্রকাশনার বিষয়ে যা আমাদের প্রত্যাদেশ ঘোষনা করে। ঐশিগ্রন্থ, অথবা বিশ্বাস সম্পর্কে তোমার কোন ধারণা ছিল না। তাসত্ত্বেও, আমরা একে একটি অলোকবর্তিকা করেছি পথনির্দেশনা দেওয়ার জন্য আমাদের বান্দাদের মধ্য থেকে যাকেই আমরা পছন্দ করি। নিশ্চয় তুমি সরল পথে পরিচালিত করো।"],
  "42:53": ["The path of Allah, to whom belongs what is in the heavens and what is in the earth. Indeed, to Allah all affairs arrive.", "আল্লাহর পথ, যাঁর অধীনে আকাশমণ্ডলীর সবকিছু এবং পৃথিবীর সবকিছু। নিঃসন্দেহে,সব ব্যাপার আল্লাহর দ্বারা নিয়ন্ত্রিত হয়।"],
  "43:1": ["Ha Mim", "হ. ম. (হা মীম)"],
  "43:2": ["By the clear Book", "এবং সে জ্ঞানালোকপূর্ণ ঐশীগ্রন্থ।"],
  "43:3": ["We have made it an Arabic recitation, so that you may reason", "আমরা একে একটি আরবি কুরআন করেছি,  যাতে তোমরা বুঝতে পারো।"],
  "43:4": ["And it is in the mother of the Book with Us, exalted and wise", "এটি আমাদের মাধ্যমে মূল গ্রন্থে সংরক্ষিত, যা সম্মানিত এবং প্রজ্ঞাপূর্ণ।"],
  "43:5": ["Shall We then turn the remembrance away from you in pardon, since you are a people exceeding?", "আমাদের কি উচিত শুধু এই বাস্তব সত্যটা উপেক্ষা করা যে তোমরা সীমা-লংঘন করেছো?"],
  "43:6": ["How many a Nabi We sent among the former ones", "আমরা পূর্ববর্তী প্রজন্মগুলোতে অনেক নবী পাঠিয়েছি।"],
  "43:7": ["No Nabi came to them, but they used to mock him", "প্রতিবার যখন একজন বার্তাবাহক তাদের কাছে গিয়েছিলো, তারা তার প্রতি উপহাস করেছিল।"],
  "43:8": ["So We destroyed those stronger than them in might, and the example of the former ones passed on", "পরিনামে, আমরা লোকদের নিশ্চিহ্ন করেছিলাম যারা এমনকি এদের চেয়ে আরো বেশি ক্ষমতাধর ছিল। আমরা এভাবে পূর্ববর্তী সম্প্রদায়গুলো থেকে উদাহরণ স্থাপন করি।"],
  "43:9": ["If you ask them who created the heavens and the earth, they will surely say: \"The Mighty, the Knowing created them\"", "যদি তুমি তাদের জিজ্ঞেস করতে, \"কে আকাশমণ্ডলী ও পৃথিবী সৃষ্টি করেছিলেন, \" তারা বলতো, \"সর্বশক্তিমান, সর্বজ্ঞ তাদের সৃষ্টি  করেছেন।\""],
  "43:10": ["The one who made the earth a bed for you and made for you ways therein, so that you may be guided", "তিনিই সে সত্ত্বা যিনি পৃথিবীকে তোমাদের জন্য বাসযোগ্য করেছেন, এবং সেখানে তোমাদের জন্য রাস্তা সৃষ্টি করেছেন, যাতে তোমরা সঠিক পথ অনুসরণ করতে পারো।"],
  "43:11": ["And the one who sent down from the sky water in measure, and We raised with it a dead town — thus you are brought out", "তিনিই সে সত্ত্বা যিনি আকাশ থেকে পানি বর্ষণ করেন, যথাযথ পরিমানে, তার দ্বারা মৃত জমিকে জীবিত করতে। একইভাবে, তোমরা পুনরুত্থিত হবে।"],
  "43:12": ["And the one who created all the pairs, and made for you from the ships and the cattle what you ride", "তিনিই সে সত্ত্বা যিনি সৃষ্টি করেছেন সকল প্রকার, জোড়ায় জোড়ায় (পুরুষ ও নারী), এবং তিনি তোমাদের আরোহণের জন্য জাহাজ এবং পালিত পশু সৃষ্টি করেছেন।"],
  "43:13": ["So that you sit firm upon their backs, then remember the favor of your Rabb when you are settled upon it, and say: \"Glory to the one who made this subject for us, and we were not bound with it\"", "তোমরা যখন তাদের উপর অবস্থান করো,তোমরা তোমাদের প্রভুর পক্ষ থেকে এমন অনুগ্রহের মূল্যায়ন করবে,এবং বলো,\"মহিমা সে সত্ত্বার যিনি আমাদের জন্য একে বশীভূত করেছেন। আমরা নিজেরা তাদেরকে নিয়ন্ত্রণ করতে পারতাম না।"],
  "43:14": ["And to our Rabb we are indeed returning", "\"আমরা অবশেষে আমাদের প্রভুর কাছে ফিরে যাই।\""],
  "43:15": ["They made for Allah a share of Allah's servants — indeed the human is clearly committing kufr", "এমনকি  তারা তাঁর নিজের সৃষ্টি থেকে একটি অংশকে তাঁর জন্য নির্ধারণ করে! নিশ্চয়, মানুষ চরম অকৃতজ্ঞ।"],
  "43:16": ["Has Allah taken, from what Allah creates, daughters, and chosen you with sons?", "তিনি কি তাঁর সৃষ্টিজগতের  মধ্য থেকে নিজের জন্য কন্যাদের পছন্দ করেছেন, যখন তোমাদেরকে পূত্র দিয়ে অনুগ্রহ করেন?"],
  "43:17": ["And when one of them is given glad tidings of what is set forth as a likeness for the Raheem, his face becomes black while he holds it in", "যখন তাদের কাউকে (একটি কন্যা সন্তানের) সংবাদ দেয়া হয় যেমন তারা সবচেয়ে দয়ালুর জন্য দাবি করেছিল, তার মুখমণ্ডল   দুর্দশা এবং রাগে  অন্ধকারাচ্ছন্ন হয়!"],
  "43:18": ["Or one raised amid adornment, who in a dispute cannot make things plain?", "(তারা বলে,) \"সে সন্তানে কি ভাল আছে যাকে লালন-পালন করা হয় রমনীয় হওয়ার জন্য, এবং যুদ্ধে সাহায্য করতে পারে না?\""],
  "43:19": ["They made the malakat, who are servants of the Rahman, females. Did they witness their creation? Their witness will be written, and they will be asked", "তারা দাবি করেছিল যে, সবচেয়ে দয়ালুর বান্দা ফেরেশতারা হলো নারী! তারা কি তাদের সৃষ্টি প্রত্যক্ষ করেছে? তাদের দাবী লিপিবদ্ধ আছে, এবং তাদেরকে জিজ্ঞেস করা হবে।"],
  "43:20": ["They said: \"If the Rahman had willed, we would not have worshipped them.\" They have no knowledge of that — they only conjecture", "তারা এমনকি বলেছিল, \"যদি সবচেয়ে দয়ালু ইচ্ছা করতেন, আমরা তাদের উপাসনা করতাম না।\" তাদের এমন দাবীর কোন ভিত্তি নেই; তারা শুধু অনুমান করে।"],
  "43:21": ["Or did We bring them a book before it, to which they hold fast?", "আমরা কি তাদেরকে এর পূর্বে কোন গ্রন্থ দিয়েছি, আর তারা এর সমর্থন করছে?"],
  "43:22": ["No, but they said: \"We found our fathers upon a way, and we are guided upon their tracks\"", "বাস্তবতা হচ্ছে: তারা বলেছিল, \"আমরা আমাদের মাতা-পিতাকে পেয়েছিলাম নির্দিষ্ট কিছু অনুশীলন চালিয়ে যেতে, এবং আমরা তাদের পদাঙ্ক অনুসরণ করছি।\""],
  "43:23": ["Likewise, We never sent a warner into a town before you but its softened ones said: \"We found our fathers upon a way, and we are following their tracks\"", "ঠিক তেমনি, যখন আমরা কোন সম্প্রদায়ের কাছে একজন সতর্ককারী পাঠাতাম, ঐ সম্প্রদায়ের নেতারা বলতো, \"আমরা আমাদের মাতা-পিতাকে পেয়েছিলাম নির্দিষ্ট কিছু অনুশীলন অনুসরণ করতে , এবং আমরা তাদের পদাঙ্ককে বহাল থাকবো।\""],
  "43:24": ["Say: \"What if I bring you better guidance than that upon which you found your fathers?\" They said: \"We disbelieve in that with which you were sent\"", "(বার্তাবাহক) বলতো, \"যদি এমন হয় যে তোমরা  তোমাদের পিতা-মাতা থেকে উত্তরাধিকারসূত্রে যা পেয়েছো তার চেয়ে আমি তোমাদের কাছে উত্তম পথনির্দেশনা নিয়ে এসেছি? \"তারা বলতো, \"তুমি যে বার্তা এনেছো তাতে আমরা অবিশ্বাসী ।\""],
  "43:25": ["So We requited them. See how was the outcome of the mukazzibin", "পরিনামে, আমরা তদের প্রতিদান দিয়েছিলাম। প্রত্যাখ্যানকারীদের পরিনামসমূহ লক্ষ্য করো।"],
  "43:26": ["And when Ibrahim said to his father and his people: \"I am clear of what you worship\"", "ইব্রাহিম তার পিতাকে এবং তার লোকদের বলেছিল, \"আমি প্রত্যাখ্যান করি যা তোমরা উপাসনা করো।"],
  "43:27": ["Except the One who originated me — that One will guide me", "আমাকে পথ দেখাতে পারেন শুধু সে সত্ত্বা যিনি আমার সূচনা করেছেন।\""],
  "43:28": ["And Allah made it a lasting word among his posterity, so that they may return", "(ইব্রাহিমের) এই উদাহরণ পরবর্তী প্রজন্মগুলোর জন্য একটি চিরস্থায়ী উদাহরণ উপস্থাপন করে; হয়তো তারা তাদের আত্মাকে পুনরুদ্ধার করবে।"],
  "43:29": ["But We gave enjoyment to these and their fathers, until the truth came to them, and a Rasul making clear", "প্রকৃতপক্ষে, আমি এই লোকদের এবং তাদের পূর্বপুরুষদের যথেষ্ট সুযোগ দিয়েছি, এরপর তাদের কাছে এসেছিল সত্য, এবং একজন স্পষ্ট বার্তাবাহক।"],
  "43:30": ["And when the truth came to them, they said: \"This is magic, and we disbelieve in it\"", "যখন সত্য তাদের কাছে এসেছিল, তারা বলেছিল, \"এটা জাদু, এবং আমরা তাতে অবিশ্বাসী। \""],
  "43:31": ["They said: \"Why was this recitation not sent down upon a great man from one of the two towns?\"", "তারা বলেছিল, \"যদি শুধু এই কুরআন  দুই সম্প্রদায়ের (মক্কা বা ইয়াথরিবের) অন্যকোন বিশিষ্ট মানুষের মাধ্যমে অবতীর্ণ হতো!\""],
  "43:32": ["Do they divide the mercy of your Rabb? We divided among them their livings in the worldly life, and We raised some of them above others by degrees, so that some of them take others in subjection. And the mercy of your Rabb is better than what they gather", "তারা কি সে ব্যক্তি যারা তোমার প্রভুর দয়া নির্ধারণ করে? আমরা এই জীবনে তাদের অংশ নির্ধারণ করেছি, মর্যাদায়  তাদের কাউকে অন্যদের উপর স্থান দিয়ে, যেন তারা একে অন্যকে সেবা দিতে পারে। তোমার প্রভু থেকে দয়া অনেক উত্তম যেকোন জিনিসের চেয়ে যা তারা জমা করতে পারে।"],
  "43:33": ["Were it not that people would become one community, We would have made for whoever disbelieves in the Rahman roofs of silver for their houses, and stairways upon which they mount", "যদি সব মানুষ এক (অবিশ্বাসী) ধর্মগোষ্ঠী হয়ে যাওয়ার আশংকা না থাকতো, যারা পরম দয়াময়কে অবিশ্বাস করে আমরা তাদের সবাইকে দান করতাম  রুপার ছাঁদবিশিষ্ট অট্রালিকা আর সিঁড়ি যা দিয়ে তারা আরোহণ করতে পারতো।"],
  "43:34": ["And for their houses doors, and couches upon which they recline", "তাদের অট্রালিকাগুলোতে থাকতো চিত্তাকর্ষক দরজা, এবং বিলাসবহুল আসবাবপত্র।"],
  "43:35": ["And adornment — yet all of that is but the enjoyment of the worldly life, and the hereafter with your Rabb is for those who guard", "এছাড়া অনেক অলংকার। এগুলো হলো এই নিম্নমানের জীবনের অস্থায়ী বস্তুসামগ্রী। পরকাল- তোমার প্রভুর নিকট- সৎকর্মশীলদের জন্য অনেক অনেক উত্তম।"],
  "43:36": ["And whoever turns away from the remembrance of the Rahman, We assign to that one a devil, and it becomes a companion to that one", "যেকেউ সবচেয়ে দয়ালুর বার্তাকে উপেক্ষা করে, আমরা একজন শয়তানকে তার ধ্রুব সহচর হিসেবে  নিযুক্ত  করি।"],
  "43:37": ["They bar them from the way, while they think they are guided", "এমন সহচর তাদেরকে পথ থেকে সরিয়ে দিবে, যদিও তাদেরকে বিশ্বাস করায় যে তারা সুপথপ্রাপ্ত"],
  "43:38": ["Until, when they come to Us, one says: \"If only between me and you there were the distance of the two easts.\" What an evil companion!", "যখন সে আমাদের সামনে আসে সে বলবে, \"ওহ তুমি যদি আমার থেকে দুই পূর্বের দূরত্বের মতো দূরে থাকতে। কি এক শোচনীয় সহচর! \""],
  "43:39": ["It will not benefit you today, since you wronged, that you share in the punishment", "তোমরা দু'জনেই যে শাস্তির ভাগিদার হবে, সীমালঙ্ঘনকারী হিসেবে,সেটা তোমাকে সেদিন সান্ত্বনা দিবে না।"],
  "43:40": ["Can you then make the deaf hear, or guide the unseeing, and whoever is in clear straying?", "তুমি কি বধিরকে শুনাতে পারো; তুমি কি অন্ধকে দেখাতে পারো, অথবা তাদেরকে যারা বহুদূর পথভ্রষ্ট?"],
  "43:41": ["So if We take you away, We shall requite them", "আমরা এর আগে তোমাকে মরতে দেই অথবা না দেই, অবশ্যই আমরা তাদেরকে প্রতিদান দিবো।"],
  "43:42": ["Or We show you that which We promised them — We are powerful over them", "অথবা,আমরা হয়তো তোমাকে (সে শাস্তি) দেখাবো যা আমরা তাদেরকে অঙ্গীকার করেছিলাম। তারা আমাদের পূর্ণ নিয়ন্ত্রণে।"],
  "43:43": ["So hold fast to what was revealed to you — you are on a straight path", "যা তোমার কাছে প্রকাশ করা হয় তা তুমি অবিচলভাবে প্রচার করবে ; তুমি সঠিক পথে আছো।"],
  "43:44": ["It is a reminder for you and for your people, and soon you will be asked", "এটি তোমার এবং তোমার লোকদের জন্য একটি বার্তা; তোমাদের সবাইকে প্রশ্ন করা হবে।"],
  "43:45": ["Ask those of Our rusul We sent before you: did We ever make deities besides the Rahman to be worshipped?", "তোমার পূর্বে পাঠানো বার্তাবাহকদের যাচাই করো: \"আমরা কি কখনো অন্যকোন উপাস্য নিয়োগ করেছি- সবচেয়ে দয়ালুর পাশে- উপাসিত হতে?\""],
  "43:46": ["Indeed We sent Musa with Our signs to Fir'awn and his chiefs, and he said: \"I am the Rasul of the Rabb of the worlds\"", "উদাহরণস্বরুপ, আমরা মূসাকে ফেরাউন এবং তার সভাসদের কাছে আমাদের প্রমাণাদিসহ পাঠিয়েছিলাম, ঘোষনা করে যে: \"আমি মহাবিশ্বের প্রভুর পক্ষ থেকে একজন বার্তাবাহক। \""],
  "43:47": ["And when he brought them Our signs, they laughed at them", "যখন সে তাদেরকে আমাদের প্রমাণাদি দেখালো, তারা তাদেরকে নিয়ে উপহাস করলো।"],
  "43:48": ["We showed them no sign but that it was greater than its sister, and We seized them with the punishment, so that they might return", "প্রত্যেকটি নিদর্শন যা আমরা তাদেরকে দেখিয়েছিলাম পূর্বের কোন একটির চেয়ে বড় ছিল। আমরা তাদেরকে মহামারী দিয়ে কষ্ট দিয়েছিলাম, হয়তো তারা অনুশোচনা করবে।"],
  "43:49": ["They said: \"O sorcerer, call on your Rabb for us according to the pledge with you — we shall be guided\"", "তারা বলেছিল, “হে যাদুকর!, আমাদের পক্ষ হয়ে তোমার প্রভুর কাছে মিনতি করো, যেহেতু  (এই মহামারী দূর করতে) তাঁর সাথে তোমার একটি চুক্তি আছে; আমরা তারপর সুপথপ্রাপ্ত হবো।”"],
  "43:50": ["And when We uncovered the punishment from them, they broke the pledge", "কিন্তু যখনই আমরা তাদের দুর্দশা দূর করেছিলাম, তারা মুখ ফিরিয়ে নিয়েছিল।"],
  "43:51": ["Fir'awn called out among his people, saying: \"My people, is not the kingdom of the Riverland mine, and these rivers flowing beneath me? Do you not see?\"", "ফেরাউন তার লোকদের কাছে ঘোষনা করলো, “হে আমার লোকেরা, আমি কি মিশরের রাজত্বের অধিকারী  নই, এবং এই প্রবাহিত নদীগুলো কি আমার অধীনে নয়? তোমরা কি দেখো না?"],
  "43:52": ["Or am I not better than this one, who is despised and can hardly make plain?", "“কোন ব্যক্তি উত্তম; আমি নাকি সে ব্যক্তি যে নিচু স্বভাবের এবং  কথা বলতে কষ্ট হয়?"],
  "43:53": ["Why were not bracelets of gold cast upon him, or the malakat come with him joined?", "“কেন তাহলে সে কোন স্বর্ন ভান্ডারের মালিক নয়; কেন তাহলে ফেরেশতারা তার সঙ্গে থাকে না?”"],
  "43:54": ["So he made his people take it lightly, and they obeyed him — they were a wicked people", "সে এভাবে তার লোকদের বোকা বানিয়েছিল, এবং তারা তাকে মান্য করেছিল; তারা ছিল অন্যায়কারী লোক।"],
  "43:55": ["And when they grieved Us, We requited them and drowned them all", "যখন তারা আমাদের বিরোধীতায় স্থির থাকলো, আমরা তাদেরকে শাস্তি দিয়েছিলাম এবং তাদের সবাইকে ডুবিয়ে দিলাম।"],
  "43:56": ["And We made them a precedent and an example for the later ones", "আমরা তাদেরকে পূর্ববর্তী করেছিলাম এবং অন্যদের জন্য একটি উদাহরণ।"],
  "43:57": ["And when the son of Mary was set forth as an example, your people turned away from it", "যখন মরিয়মের পুত্রকে একটি উদাহরণ হিসেবে উদ্ধৃত করা হয়েছিল, তোমার লোকেরা তা উপেক্ষা করেছিলো।"],
  "43:58": ["They said: \"Are our deities better, or is he?\" They only set it forth to you for dispute — they are a contentious people", "তারা বলেছিল, “আমাদের উপাস্যদের উপাসনা করা উত্তম, নাকি তার উপাসনা করা?” তারা এটা বলেছিল শুধু তোমার সাথে তর্ক করার জন্য। প্রকৃতপক্ষে, তারা সে লোক যারা বিরোধিতায় যোগ দিয়েছে।"],
  "43:59": ["He is only a servant whom We favored, and We made him an example for the children of Israel", "সে একজন বান্দার চেয়ে বেশি কিছু ছিল না যার প্রতি আমরা অনুগ্রহ করেছিলাম, এবং আমরা তাকে ইসরাইলের সন্তাদের জন্য একটি উদাহরণ হিসেবে পাঠিয়েছিলাম।"],
  "43:60": ["If We willed, We could make malakat among you, succeeding one another in the earth", "যদি আমরা চাইতাম, আমরা তোমাদের স্বর্গদূত করতে পারতাম যারা বসতি স্থাপন করতো এবং পৃথিবীতে বংশ বিস্তার করতো।"],
  "43:61": ["He is knowledge for the Hour — so do not doubt it — and follow Me. This is a straight path", "বিশ্বের সমাপ্তি জানার জন্য সে কাজ করবে চিহ্নিতকারী হিসেবে, যেন এ সম্পর্কে তোমরা আর  কখনো কোন সন্দেহ পোষন না করো। তোমরা আমার অনুসরণ করবে; এটাই সঠিক পথ।"],
  "43:62": ["Let not the devil turn you aside — the devil is to you a clear enemy", "তোমরা শয়তানকে বাধা দিতে দিও না; সে তোমাদের সবচেয়ে স্পষ্ট  শত্রু।"],
  "43:63": ["And when Isa came with the clarity, he said: \"I have brought you wisdom, and I will make plain to you some of what you differ about. So guard Allah and obey me\"", "যখন ঈসা প্রমানসমূহ নিয়ে গিয়েছিল, সে বলল, “আমি তোমাদের কাছে প্রজ্ঞা নিয়ে, এবং কিছু বিষয় সুস্পষ্ট করতে আসি যেগুলো নিয়ে তোমরা বিবাদ করো। তোমরা আল্লাহর ভক্তি করবে এবং আমাকে মান্য করবে।"],
  "43:64": ["Indeed Allah is my Rabb and your Rabb, so worship Allah. This is a straight path", "আল্লাহ আমার এবং তোমাদের প্রভু, তোমরা কেবল তাঁর উপাসনা করবে। এটাই সঠিক পথ।\""],
  "43:65": ["The parties differed among themselves. Woe to those who wronged from the punishment of a painful day", "বিরোধীরা নিজেদের মধ্যে বিবাদ করেছিল। দুর্ভোগ তাদের প্রতি যারা এক যন্ত্রণাদায়ক দিনের শাস্তি থেকে সীমালঙ্ঘন করে।"],
  "43:66": ["Do they wait for anything but the Hour, that it comes to them suddenly while they do not perceive?", "তারা কি অপেক্ষা করছে সে সময়ের (বিচার দিবস) আকস্মিকভাবে আসার জন্য যখন তারা এর প্রত্যাশা খুব কমই করে?"],
  "43:67": ["Friends on that day are enemies to one another, except the guarded ones", "ঐদিন ঘনিষ্ঠ বন্ধুরাও একে অন্যের শত্রু হয়ে পড়বে, সৎকর্মশীলরা ব্যতীত ।"],
  "43:68": ["Servants, no fear upon you today, nor will you grieve", "হে আমার বান্দারা, ঐদিন তোমাদের কোন ভয় থাকবে না, না তোমরা শোক করবে।"],
  "43:69": ["Those who believed in Our signs and were submitting", "তারা সে ব্যক্তি যারা আমাদের প্রকাশনাবলিতে বিশ্বাস করেছিল, এবং আত্মসমর্পণকারী ছিল।"],
  "43:70": ["Enter the garden, you and your spouses, in delight", "স্বর্গে প্রবেশ করো, তোমাদের সঙ্গীদের সাথে, এবং আনন্দ করো।"],
  "43:71": ["They are moved around among with sheets of gold and cups, and therein is what souls desire and eyes delight in, and therein you abide forever", "তাদেরকে পরিবেশন করা হবে সোনালী ট্রে এবং পেয়ালা, এবং তারা সবকিছু পাবে যার জন্য হৃদয় আকাঙ্ক্ষা করে এবং চোখ ইচ্ছা পোষণ করে। তোমরা সেখানে চিরকাল বসবাস করো।"],
  "43:72": ["That is the garden you have inherited for what you used to do", "তোমাদের কর্মের বিনিময়ে তোমরা এই স্বর্গের উত্তরাধিকারী হবে।"],
  "43:73": ["In it you have abundant fruit, from which you eat", "এতে তোমরা পাবে সব রকমের ফল, যা থেকে তোমরা খাও।"],
  "43:74": ["Indeed the guilty are in the punishment of hell, abiding forever", "নিশ্চয়, অপরাধী ব্যাক্তি জাহান্নামের শাস্তিতে চিরকাল বাস করবে।"],
  "43:75": ["It is never lightened for them, and they are despair-struck in it", "তাদের জন্য শাস্তি কখনো কমানো হবে না; তারা তাতে আবদ্ধ থাকবে।"],
  "43:76": ["We did not wrong them, but they were the ones who wronged", "তাদের ক্ষতি আমরা করিনি; তারাই তাদের নিজ আত্মার ক্ষতি করেছিল।"],
  "43:77": ["They will call out: \"O warden, let your Rabb decree an end for us.\" It will be said: \"You are staying\"", "তারা মিনতি করবে: \"হে মালেক, তোমার প্রভু যেন আমাদের ধ্বংস করেন।\" সে বলবে, \"তোমরা অবস্থান করছো চিরকাল।"],
  "43:78": ["We brought you the truth, but most of you are averse to the truth", "\"আমরা তোমাদেরকে সত্য দিয়েছি, কিন্তু তোমাদের বেশির ভাগ সত্যকে ঘৃনা করো।\""],
  "43:79": ["Or have they settled a matter? Then We are settling", "তারা কি কিছু ষড়যন্ত্রের পরিকল্পনা করেছে? আমরাও পরিকল্পনা করছি।"],
  "43:80": ["Or do they think We do not hear their secret and their private talk? Yes indeed, and Our rusul are with them recording", "তারা কি মনে করে যে আমরা তাদের গোপনীয়তা এবং ষড়যন্ত্রগুলো শুনি না? হ্যা নিশ্চয়; আমাদের বার্তাবাহকেরা তাদের সাথে আছে, লিপিবদ্ধ করছে।"],
  "43:81": ["Say: \"If the Raheem had a child, I would be the first of the servants\"", "ঘোষনা করো: \"যদি সবচেয়ে দয়ালুর একজন পূত্রসন্তান থাকতো, এরপরেও আমি সর্বপ্রথম উপাসনাকারী হতাম।\""],
  "43:82": ["Glory to the Rabb of the heavens and the earth, the Rabb of the high seat, above what they describe", "তিনি মহিমান্বিত; তিনি আকাশমণ্ডলী এবং পৃথিবীর প্রভু, বিশাল রাজত্বের প্রভু, তাদের দাবির অনেক উর্দ্ধে।"],
  "43:83": ["So leave them to wade idle and play, until they meet the day they are promised", "তাদেরকে বিভ্রমে এবং ক্রিড়া-কৌতুকে থাকতে দাও যতক্ষণ না পর্যন্ত তারা তাদের দিনের সাক্ষাত করে যা তাদের জন্য অপেক্ষা করছে"],
  "43:84": ["And Allah is the one who is a deity in the heaven and a deity in the earth — and Allah is the Wise, the Knowing", "তিনিই সে একমাত্র সত্ত্বা যিনি আকাশে একজন দেবতা এবং পৃথিবীতে একজন দেবতা। তিনি সবচেয়ে জ্ঞানী, সর্বজ্ঞ।"],
  "43:85": ["Blessed is the one to whom belongs the kingdom of the heavens and the earth and what is between them; with Allah is the knowledge of the Hour, and to Allah you return", "সবচেয়ে প্রশংসিত সে সত্ত্বা যিনি আকাশমন্ডলী এবং পৃথিবী, এবং এদের মধ্যকার সবকিছুর সকল সার্বভৌমত্বের অধিকারী। তাঁর কাছেই রয়েছে সে সময় (বিশ্বের সমাপ্তি) সম্পর্কিত জ্ঞান, এবং তাঁর কাছেই তোমরা ফিরে যাবে।"],
  "43:86": ["Those they call upon besides Allah possess no intercession — except one who bears witness to the truth while they know", "যাদেরকে তারা তাঁর পাশে উপাস্য স্থাপন করে তাদের কারোরই মধ্যস্থতা করার কোন ক্ষমতা নেই,  যদি না তাদের মধ্যস্থতা সত্যের সাথে মিলে যায়, এবং তারা পুরোপুরি জানে।"],
  "43:87": ["And if you ask them who created them, they will surely say: \"Allah.\" So how are they turned away?", "যদি তুমি তাদেরকে জিজ্ঞেস করতে, কে তাদেরকে সৃষ্টি করেছে, তারা বলত, \"আল্লাহ\"। তবে কেন তারা পথচ্যুত হয়?"],
  "43:88": ["And the word of Allah: \"My Rabb, these are a people who do not believe\"", "ঘোষনা করা হবে যে: \"হে আমার প্রভু, এই লোকেরা বিশ্বাস করে না।\""],
  "43:89": ["So pardon them and say: \"Peace.\" Soon they will know", "তুমি তাদেরকে উপেক্ষা করবে এবং বল, \"শান্তি;\" তারা নিশ্চয়ই খুঁজে পাবে।"],
  "44:1": ["Ha Mim", "হ. ম. (হা মীম)"],
  "44:2": ["By the clear Book", "এবং এই জ্ঞানালোকপূর্ণ ঐশীগ্রন্থ।"],
  "44:3": ["We sent it down on a blessed night — We had been warners", "আমরা একে অবতীর্ণ করেছি একটি অনুগ্রহপ্রাপ্ত রাতে, কারণ আমরা সতর্ক করি।"],
  "44:4": ["In it is made distinct every wise decree", "এতে (ঐশীগ্রন্থে), প্রজ্ঞার প্রত্যেকটি বিষয় সহজবোধ্য করা হয়েছে।"],
  "44:5": ["A command from Us — We were the senders", "এটা আমাদের থেকে একটি পূর্বনির্ধারিত আদেশ যে আমরা বার্তাবাহকদের প্রেরণ করি।"],
  "44:6": ["A mercy from your Rabb — Allah is the All-Hearing, the All-Knowing", "এটি তোমার প্রভুর পক্ষ থেকে একটি দয়া। তিনি শ্রবণকারী, সর্বজ্ঞ।"],
  "44:7": ["Rabb of the heavens and the earth and all that lies between them, if you are certain", "আকাশমণ্ডলী এবং পৃথিবীর প্রভু, এবং এদের মধ্যকার সবকিছুর প্রভু। যদি শুধু তুমি নিশ্চিত হতে পারতে!"],
  "44:8": ["There is no ilah but Allah: Allah gives life and gives death — Rabb of you and Rabb of your forefathers of old", "তাঁর পাশে অন্য কোন উপাস্য নেই। তিনি নিয়ন্ত্রণ করেন জীবন এবং মৃত্যু; তোমাদের প্রভু এবং তোমাদের পূর্বপুরুষদের প্রভু।"],
  "44:9": ["But they are in doubt, playing around", "নিশ্চয়, তারা সন্দিহান, অমনোযোগী।"],
  "44:10": ["So watch for the day when the sky brings clear smoke", "অত:এব, সে দিনটির জন্য অপেক্ষা করো যখন আকাশ পরিবেষ্টনকারী ধোঁয়া নিয়ে আসে।"],
  "44:11": ["It will cover the people: \"This is a painful punishment.\"", "এটা লোকদের পুরোপুরি ঢেকে ফেলবে; এটি একটি যন্ত্রণাদায়ক শাস্তি।"],
  "44:12": ["Our Rabb, lift this punishment from us — we are muminin", "\"আমাদের প্রভু, আমাদের জন্য এই শাস্তি দূর করুন; আমরা বিশ্বাসী।\""],
  "44:13": ["How can they take the reminder, when a clear Rasul has come to them?", "এখন যখন অনেক দেরী হয়ে গেছে, তারা স্মরন করে! একজন জ্ঞান দানকারী বার্তাবাহক তাদের কাছে এসেছিল।"],
  "44:14": ["Then they turned away from him and said: \"A tutored madman!\"", "কিন্তু তারা তার থেকে মুখ ফিরিয়ে নিয়েছিল, এ বলে যে, \"উচ্চ শিক্ষিত, কিন্তু পাগল!\""],
  "44:15": ["We shall lift the punishment a little — you are sure to fall back", "আমরা কিছু সময়ের জন্য শাস্তি দূর করবো; দ্রুতই তোমরা প্রত্যাবর্তন করবে।"],
  "44:16": ["On the day We seize with the greatest seizing, We shall be requiting", "সেদিন যখন আমরা বড় আঘাতটি দিয়ে আঘাত করি , তখন আমরা প্রতিশোধ নিবো।"],
  "44:17": ["And indeed We tested Fir'awn's people before them, and a noble Rasul came to them,", "আমরা তাদের পূর্বে পরীক্ষা করেছি ফেরাউনের লোকদের; একজন সম্মানিত বার্তাবাহক তাদের কাছে গিয়েছিল।"],
  "44:18": ["Saying: \"Give up the servants of Allah — I am a trustworthy Rasul to you,", "ঘোষনা করে যে: \"আল্লাহর বান্দারা, আমার কথা শোনো। আমি তোমাদের প্রতি একজন বিশ্বস্ত বার্তাবাহক।"],
  "44:19": ["And do not rise up over Allah — I bring you a clear warrant,", "এবং, \"আল্লাহর বিরুদ্ধে সীমালঙ্ঘন করো না। আমি তোমাদের কাছে নিয়ে আসি শক্তিশালী প্রমাণসমূহ।"],
  "44:20": ["And I seek refuge with my Rabb and your Rabb from your stoning me.", "\"আমি আশ্রয় প্রার্থনা করি আমার প্রভু এবং তোমাদের প্রভুর কাছে, যদি তোমরা আমার বিরোধিতা করো।"],
  "44:21": ["And if you do not believe me, then keep apart from me.\"", "\"যদি তোমরা বিশ্বাস করতে না চাও, তাহলে আমাকে শুধু আমার মতো থাকতে দাও।\""],
  "44:22": ["So he called his Rabb: \"These are a guilty people.\"", "পরবর্তীতে, সে তার প্রভুর কাছে মিনতি করেছিল: \"এরা অন্যায়কারী লোক'"],
  "44:23": ["So travel by night with My servants — you will surely be followed", "(আল্লাহ বললেন, ) \" আমার বান্দাদের নিয়ে রাতে ভ্রমন করো; তোমাদেরকে ধাওয়া করা হবে।"],
  "44:24": ["And leave the sea behind, becalmed — they are a drowned host", "\"দ্রুত সাগর পার হও; তাদের সৈন্যরা ডুবে যাবে।\""],
  "44:25": ["How many gardens and springs they left behind", "এভাবে, তারা ফেলে এসেছিল অনেক বাগান এবং ঝর্ণা।"],
  "44:26": ["And crops, and a noble dwelling", "শস্যসমূহ এবং একটি বিলাসবহুল জীবন।"],
  "44:27": ["And blessings in which they took delight", "অনুগ্রহসমূহ যা তারা উপভোগ করেছিল।"],
  "44:28": ["So it was; and We had another people inherit it all", "এই সবকিছু আমরা অন্য লোকদের দ্বারা উত্তরাধিকার করতে দিয়েছিলাম।"],
  "44:29": ["Nor did the sky or the earth weep for them, nor were they given respite", "না আকাশমণ্ডলী, না পৃথিবী তাদের জন্য কেঁদেছিল, এবং তাদেরকে অবকাশ দেয়া হয়নি।"],
  "44:30": ["And We did rescue the Children of Israel from the humiliating punishment,", "ইতোমধ্যে, আমরা ইসরাইলের সন্তানদের অপমানজনক অত্যাচার থেকে রক্ষা করেছিলাম।"],
  "44:31": ["From Fir'awn — he was arrogant, among the transgressors", "ফেরাউনের কাছ থেকে; সে ছিল একজন স্বৈরশাসক।"],
  "44:32": ["And We chose them with knowledge, above all peoples", "আমরা তাদেরকে সকল লোকদের থেকে পছন্দ করেছিলাম, জ্ঞাতসারে।"],
  "44:33": ["And We gave them signs in which was a clear test", "আমরা তাদেরকে এতোগুলো প্রমান দেখিয়েছিলাম, যা স্থাপন করেছিল এক মহা-পরীক্ষা।"],
  "44:34": ["Indeed, these people say:", "বর্তমান প্রজন্মগুলো বলে,"],
  "44:35": ["\"There is nothing but our first death, and we shall not be raised.\"", "\"আমরা প্রথম মৃত্যুতেই শুধু মারা যাই; আমরা কখনোই পুনরুত্থিত হবো না!"],
  "44:36": ["So bring back our fathers, if you are sadiq", "\"আমাদের পূর্বপুরুষদের ফিরিয়ে আনো, যদি তোমরা সত্যবাদী হও।\""],
  "44:37": ["Are they better, or the people of Tubba and those before them? We destroyed them — they were a guilty people", "তারা কি তুব্বার লোকদের চেয়ে এবং তাদের পূর্বের অন্যদের চেয়ে উত্তম? আমরা তাদের অপরাধের জন্য তাদেরকে নিশ্চিহ্ন করেছিলাম"],
  "44:38": ["We did not create the heavens and the earth and what lies between them in play", "আমরা সৃষ্টি করিনি আকাশমণ্ডলী এবং পৃথিবী, এবং এদের মধ্যকার সবকিছু, কেবল খেল-তামাশা করতে।"],
  "44:39": ["We created them only in truth, yet most of them do not know", "আমরা তাদেরকে একটি নির্দিষ্ট উদ্দেশ্যে সৃষ্টি করেছি, কিন্তু তাদের অধিকাংশ জানে না।"],
  "44:40": ["The Day of Decision is the appointed time for them all", "সিদ্ধান্তের দিনটি তাদের জন্য অপেক্ষা করছে।"],
  "44:41": ["The day when a protector shall not avail a protector anything, and they will not be helped", "এটা সে দিন যখন কোন বন্ধু তার বন্ধুকে কোনভাবে সাহায্য করতে পারবে না; না কেউ সাহায্য পাবে।"],
  "44:42": ["Except one upon whom Allah has mercy — Allah is the Mighty, the Raheem", "কেবলমাত্র তারা যারা আল্লাহ থেকে দয়া অর্জন করে। তিনি সর্বশক্তিমান, সবচেয়ে দয়ালু।"],
  "44:43": ["The tree of Zaqqum", "নিশ্চয়, তিক্ততার গাছ-"],
  "44:44": ["Is the food of the guilty,", "পাপীদের জন্য খাদ্য সরবরাহ করবে।"],
  "44:45": ["Like scalding mire, boiling in the bellies,", "ক্ষারের মতো, এটি পাকস্থলীতে ফুটবে।"],
  "44:46": ["Like the seething of scalding water", "নারকীয় পানীয়ের ফুটন্ত জলের মতো।"],
  "44:47": ["Seize him and drag him to the heart of the blaze", "তাকে ধরো এবং নরকের কেন্দ্রে নিক্ষেপ করো।"],
  "44:48": ["Then pour over his head the punishment of scalding water", "তারপর তার মাথার উপর নরকের শাস্তি ঢালো।"],
  "44:49": ["Taste — you it is who were the mighty, the noble!", "\"এর স্বাদ নাও; তুমি তো ছিলে বেশ ক্ষমতাধর, বেশ সম্মানিত।\""],
  "44:50": ["This is what you used to doubt", "এটা তা-ই, যাতে তোমরা সন্দেহ করতে।"],
  "44:51": ["The guarded ones are in a secure abode,", "সৎকর্মশীলরা থাকবে একটি নিরাপদ অবস্থানে।"],
  "44:52": ["In gardens and springs,", "বাগান এবং ঝর্ণাসমূহ উপভোগরত।"],
  "44:53": ["Clothed in fine silk and rich brocade, facing one another,", "মখমল এবং রেশমী বস্ত্র পরিধানরত; একে অন্যের কাছাকাছি।"],
  "44:54": ["So it is; and We shall wed them to fair-eyed companions,", "আমরা তাদেরকে চমৎকার জীবন-সঙ্গী প্রদান করলাম।"],
  "44:55": ["There they call for every fruit, in safety", "তারা সেখানে সকল প্রকারের ফল উপভোগ করে, পরিপূর্ণ শান্তিতে।"],
  "44:56": ["They taste no death there except the first death, and the punishment of the blaze is warded from them,", "তারা সেখানে মৃত্যুর স্বাদ গ্রহন করে না- প্রথম মৃত্যুর পর- এবং তিনি তাদেরকে নরকের শাস্তি থেকে নিষ্কৃতি দিয়েছেন।"],
  "44:57": ["As a bounty from your Rabb — that is the great triumph", "এমনই তোমার প্রভুর পক্ষ থেকে অনুগ্রহ। এমনই হলো মহা বিজয়।"],
  "44:58": ["We have made it easy upon your tongue, so that they may remember", "আমরা এভাবে এটিকে তোমার ভাষায় স্পষ্ট করেছি, যাতে তারা মনোযোগ দিতে পারে।"],
  "44:59": ["So keep watch — they are watching", "অতএব, অপেক্ষা করো; তাদেরকেও অপেক্ষা করতে হবে।"],
  "45:1": ["Ha Mim", "হ. ম. (হা মীম)"],
  "45:2": ["The sending-down of the Book is from Allah, the Almighty, the Wise.", "এই ঐশীগ্রন্থের প্রকাশনা আল্লাহ থেকে, সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "45:3": ["Indeed, in the heavens and the earth are signs for the muminin.", "বিশ্বাসীদের জন্য আকাশমণ্ডলী এবং পৃথিবী প্রমানাদিতে পূর্ণ।"],
  "45:4": ["And in your creation, and in what is scattered of creatures, are signs for people who are certain.", "তোমাদের সৃষ্টিতে, এবং সকল প্রানীদের সৃষ্টিতেও, লোকদের জন্য প্রমাণ রয়েছে যারা নিশ্চিত।"],
  "45:5": ["And in the alternation of the night and the day, and in what Allah sends down from the sky of provision and brings the earth to life with it after its death, and in the directing of the winds — are signs for people who reason.", "এছাড়া, রাত এবং দিনের পরিবর্তনে, এবং জীবিকাসমূহ যা আল্লাহ আকাশ থেকে অবতীর্ণ করেন মৃত ভূমিকে পুনর্জীবিত করতে, এবং বায়ূপ্রবাহ নিয়ন্ত্রনে; এই সবকিছু লোকদের জন্য প্রমান যারা বোঝে।"],
  "45:6": ["These are the verses of Allah, which We recite to you in truth. So in what account after Allah and the verses of Allah will they believe?", "এগুলো আল্লাহর প্রকাশনাবলি যা আমরা তোমার কাছে সত্য সহকারে আবৃতি করি। আল্লাহ এবং তাঁর প্রকাশনাবলি ব্যতীত অন্য কোন হাদীসে তারা বিশ্বাস করে?"],
  "45:7": ["Woe to every fabricating sinner.", "দূর্ভোগ প্রত্যেক মিথ্যা উদ্ভাবক, অপরাধীর প্রতি।"],
  "45:8": ["Who hears the verses of Allah recited to him, then persists, obstinate, as if he had not heard them — so give him tidings of a painful punishment.", "যে ব্যক্তি তার কাছে আবৃতি করা আল্লাহর প্রকাশনাবলি শুনে, এরপর ঔদ্ধতের সাথে তার পথের উপরেই জোর দেয়, যেন সে কখনো সেগুলো শুনেনি। তাকে এক যন্ত্রণাকর শাস্তির প্রতিশ্রুতি দাও।"],
  "45:9": ["And when he knows anything of Our verses, he takes them in mockery. Those — for them is a humiliating punishment.", "যখন সে আমাদের প্রকাশনাবলি সম্পর্কে কোনকিছু শিখে, সে সেগুলোকে উপহাস করে। এরা টেনে এনেছে এক লজ্জাকর শাস্তি।"],
  "45:10": ["Behind them is Hell, and nothing of what they earned avails them, nor what they took besides Allah as protectors; and for them is a great punishment.", "তাদের জন্য অপেক্ষায় আছে জাহান্নাম। তাদের উপার্জন তাদেরকে সাহায্য করবে না, না করবে আল্লাহর পাশে তাদের স্থাপিত প্রতিমা। তারা টেনে এনেছে এক ভয়ানক শাস্তি।"],
  "45:11": ["This is guidance. And those who disbelieve in the verses of their Rabb — for them is a punishment of painful affliction.", "এটি একটি আলোকবর্তিকা, এবং যারা তাদের প্রভুর এই প্রকাশনাবলিতে অবিশ্বাস করে তারা টেনে এনেছে নিন্দা এবং একটি যন্ত্রণাদায়ক শাস্তি।"],
  "45:12": ["It is Allah who subjected the sea for you, so that the ships sail in it by the command of Allah, and so that you may seek of the bounty of Allah, and so that you may be grateful.", "আল্লাহ সে সত্ত্বা যিনি সাগরকে তোমাদের সেবায় নিয়োজিত করেছেন, যাতে করে জাহাজগুলো এতে ঘুড়ে-বেড়াতে পারে তাঁর আইনানুসারে। তোমরা এভাবে তাঁর জীবিকা খোঁজ, যাতে তোমরা কৃতজ্ঞ হও।"],
  "45:13": ["And Allah has subjected to you whatever is in the heavens and whatever is on the earth, all from Allah. Indeed, in that are signs for people who reflect.", "তিনি তোমাদের সেবায় আকাশমন্ডলী এবং পৃথিবীর সবকিছুকে নিয়োজিত করেছেন; সবকিছু তাঁর পক্ষ থেকে। এগুলো সে লোকদের জন্য প্রমান যারা অনুধাবন করে।"],
  "45:14": ["Say to those who believe to forgive those who do not hope for the days of Allah, that Allah may repay a people for what they used to earn.", "যারা বিশ্বাস করেছে তাদের বলো ক্ষমা করতে তাদেরকে যারা আল্লাহর দিনগুলোর প্রত্যাশা করে না। সবাইকে তিনি সম্পূর্ণ মূল্য দিবেন, যা কিছুই তারা অর্জন করেছে।"],
  "45:15": ["Whoever does salihness, it is for their own soul; and whoever does evil, it is against it. Then to your Rabb you will be returned.", "যেকেউ সৎকর্ম করে তার নিজের ভালোর জন্যই তা করে, এবং যেকেউ মন্দকর্ম করে তার নিজের ক্ষতির জন্যই তা করে। তোমাদের প্রভুর কাছে তোমরা ফিরে যাবে।"],
  "45:16": ["And We gave the Children of Israel the Scripture, and judgment, and Nabihood, and We provided them from the good things, and favored them above the worlds.", "আমরা ইসরাইলের সন্তানদেরকে ঐশীগ্রন্থ, প্রজ্ঞা এবং নবীত্ব দিয়েছিলাম, এবং তাদেরকে ভাল জীবিকা দিয়েছিলাম; অন্য লোকদের চেয়ে তাদের উপর আমরা অধিক অনুগ্রহ অর্পণ করেছিলাম।"],
  "45:17": ["And We gave them clear proofs of the matter, and they did not differ except after the knowledge came to them, out of envy among themselves. Indeed, your Rabb will judge between them on the Day of Resurrection concerning what they used to differ about.", "আমরা এখানে তাদেরকে সুস্পষ্ট প্রত্যাদেশ দিয়েছি। দূ:খজনকভাবে, তাদের কাছে জ্ঞান আসার পূর্ব পর্যন্ত তারা এই নিয়ে বিবাদ করেনি।  এটা তাদের পক্ষ থেকে হিংসার ফল। নিশ্চয়, তোমার প্রভু পুনরুত্থান দিবসে তাদের বিচার করবেন সবকিছুর বিষয়ে যাতে তারা বিবাদ করেছে।"],
  "45:18": ["Then We placed you upon a laid-course of the matter; so follow it, and do not follow the desires of those who do not know.", "আমরা এরপর তোমাকে সঠিক আইনগুলো প্রতিষ্ঠা করতে মনোনীত করেছিলাম; তুমি এর অনুসরণ করো, এবং তাদের ইচ্ছার অনুসরণ করো না যারা জানে না।"],
  "45:19": ["Indeed, they will never avail you anything against Allah. And the wrongdoers — some of them are protectors of others; and Allah is the protector of the salihin.", "আল্লাহর বিরুদ্ধে তারা তোমাকে সামান্যতম সাহায্য করতে পারে না। সীমালঙ্ঘনকারীরাই নিজেদের মধ্যে একে অন্যের সাথে মিত্রতা করে, যখন আল্লাহ সৎকর্মশীলদের প্রভু।"],
  "45:20": ["These are insights for people, and guidance and mercy for people who are certain.", "এটা লোকদের জন্য প্রদান করে জ্ঞানালোক, এবং পথনির্দেশনা, এবং দয়া তাদের জন্য যারা নিশ্চিত।"],
  "45:21": ["Or do those who commit the evil deeds think that We will make them like those who believe and do the salihin deeds — equal in their living and their dying? Evil is what they judge.", "যারা মন্দ কাজ করে তারা কি আশা করে যে আমরা তাদের সাথে একইরকম আচরণ করবো যেমন করি তাদের সাথে যারা বিশ্বাস করে এবং সৎকর্মশীল জীবন-যাপন করে? তাদের জীবন এবং তাদের মৃত্যু কি একই রকম? নিশ্চয়, তাদের বিচার ভুল।"],
  "45:22": ["And Allah created the heavens and the earth in truth, so that every soul may be repaid for what it earned; and they will not be wronged.", "আল্লাহ আকাশমণ্ডলী এবং পৃথিবীকে সৃষ্টি করেছেন একটি নির্দিষ্ট উদ্দেশ্যে, প্রত্যেক আত্মাকে তার জন্য মূল্য দিতে যাকিছুই এটি অর্জন করেছে, সামান্যতম অবিচার ছাড়া।"],
  "45:23": ["Have you seen the one who has taken desire as a ilah, and Allah led that one astray upon knowledge, and sealed over the hearing and the heart, and placed a covering over the sight? So who can guide that one after Allah? Then will you not remember?", "তুমি কি সে ব্যক্তিকে লক্ষ্য করেছো যার দেবতা তার অহংকার? পরিনামে, আল্লাহ তাকে পথভ্রষ্ট করেন, তার জ্ঞান থাকা সত্ত্বেও, তার শ্রবণশক্তি এবং তার মনে মোহর মেরে দেন, এবং তার চোখে পর্দা দিয়ে দেন। আল্লাহর এমন সিদ্ধান্তের পর, কে তখন তাকে পথ দেখাতে পারে? তোমরা কি সতর্ক হবে না?"],
  "45:24": ["And they say: \"There is nothing but our worldly life; we die and we live, and nothing destroys us but time.\" And they have no knowledge of that; they only assume.", "তারা বলেছিল, \"আমরা শুধুমাত্র এই জীবনে বেচেঁ থাকি; আমরা বেচেঁ থাকি এবং মারা যাই এবং সময়ই কেবল আমাদের মৃত্যু ঘটায়!\" এ সম্পর্কে তাদের কোন নিশ্চিত জ্ঞান নেই; তারা শুধু অনুমান করে।"],
  "45:25": ["And when Our verses are recited to them as clear proofs, their only argument is that they say: \"Bring our forefathers, if you are sadiq.\"", "যখন তাদের কাছে আমাদের প্রকাশনাবলি আবৃতি করা হয়, স্পষ্টভাবে, তারা শুধু এই তর্ক করে যে, \"আমাদের পূর্বপুরুষদের ফিরিয়ে আনো, যদি তুমি সত্যবাদী হও।\""],
  "45:26": ["Say: \"Allah gives you life, then brings you to death, then gathers you to the Day of Resurrection, in which there is no doubt — but most people do not know.\"", "বল, \"আল্লাহ তোমাদেরকে জীবন দান করেছেন, এরপর তিনি তোমাদেরকে মৃত করেন, এরপর তিনি পুনরুত্থান দিবসে তোমাদের তলব করবেন, যা অনিবার্য। কিন্তু অধিকাংশ লোক জানে না।"],
  "45:27": ["And to Allah belongs the kingdom of the heavens and the earth; and on the day the Hour rises, that day the falsifiers will lose.", "আকাশমন্ডলী এবং পৃথিবীর সকল সার্বভৌমত্ব আল্লাহর অধীনে। সেদিন যখন সে সময় (বিচার) সংঘটিত হয়, সেদিনই মিথ্যাবাদীরা হেরে যায়।"],
  "45:28": ["And you will see every nation kneeling; every nation will be called to its record: \"Today you are repaid for what you used to do.\"", "তুমি প্রত্যেক সম্প্রদায়কে নতজানু হতে দেখবে । প্রত্যেক সম্প্রদায়কে তাদের নথি দেখতে ডাকা হবে। আজকে তোমরা সবকিছুর জন্য মূল্য পাও যা তোমরা করেছ।"],
  "45:29": ["\"This is Our record, speaking to you in truth. We were recording what you used to do.\"", "এটা আমাদের রেকর্ড; এটা তোমাদের সম্পর্কে সত্য বলে। আমরা রেকর্ড করে আসছি সবকিছু যা তোমরা করেছো।"],
  "45:30": ["So as for those who believed and did the salihin deeds, their Rabb will admit them into mercy. That is the clear winning.", "আর যারা বিশ্বাস করে এবং সৎকর্ম করে, তাদের প্রভু তাদেরকে তাঁর দয়ায় প্রবেশ করাবেন। এটা মহাবিজয়।"],
  "45:31": ["But as for those who kafara: \"Were My verses not recited to you, yet you were arrogant and were a mujrim people?\"", "আর যারা অবিশ্বাস করে: \"আমার প্রকাশনাবলি কি তাদের কাছে আবৃতি করা হয়নি, কিন্তু তোমরা উদ্ধত হয়ে পড়েছিলে এবং অন্যায়কারী মানুষ ছিলে?"],
  "45:32": ["And when it is said: \"The promise of Allah is true, and the Hour — there is no doubt in it,\" you say: \"We do not know what the Hour is; we only assume an assumption, and we are not certain.\"", "যখন এটা ঘোষনা করা হয় যে আল্লাহর প্রতিশ্রুতি সত্য এবং (বিচারের) সে সময় অনিবার্য, তোমরা বলেছিলে, \"আমরা জানি না কি সে সময়! আমরা এটা সম্পর্কে পুরোপুরি অনুমানে আছি; আমরা  নিশ্চিত নই।\""],
  "45:33": ["And the evils of what they did become manifest to them, and what they used to mock encircles them.", "তাদের কাজের মন্দগুলো তাদের কাছে সহজবোধ্য হয়ে উঠবে, এবং ঠিক যে বিষয়গুলো নিয়ে তারা তামাশা করেছিল সেগুলো ফিরে আসবে এবং তাদেরকে তাড়া করবে।"],
  "45:34": ["And it will be said: \"Today We forget you, as you forgot the meeting of this day of yours; and your destination is the Fire, and you have no helpers.\"", "এটা ঘোষনা করা হবে: \"আজ আমরা তোমাদের ভুলে গিয়েছি, ঠিক যেমন তোমরা এই দিনের সাক্ষাতকে ভুলে গিয়েছিলে। তোমাদের আবাস নরকাগ্নিতে, এবং তোমাদের কোন সাহায্যকারী থাকবে না।"],
  "45:35": ["That is because you took the verses of Allah in mockery, and worldly life deceived you. So today they will not come out of it, nor will they be allowed to seek appeasement.", "এর কারণ তোমরা আল্লাহর প্রকাশনাবলি নিরর্থকভাবে নিয়েছিলে এবং প্রথম জীবন নিয়ে ব্যস্ত ছিলে। পরিনামে, তারা সেখান থেকে কখনো বের হতে পারবে না, না তাদেরকে ক্ষমা করা হবে।"],
  "45:36": ["So to Allah belongs all praise — Rabb of the heavens, and Rabb of the earth, Rabb of the worlds.", "সকল প্রশংসা আল্লাহর অধীনে; আকাশমন্ডলীর প্রভু, পৃথিবীর প্রভু, মহাবিশ্বের প্রভু।"],
  "45:37": ["And grandeur belongs to Allah in the heavens and the earth; Allah is the Almighty, the Wise.", "তাঁর অধীনেই আকাশমন্ডলী এবং পৃথিবীর সকল আধিপত্য। তিনি সর্বশক্তিমান, পরম দয়ালু।"],
  "46:1": ["Ha Mim", "হ. ম. (হা মীম)"],
  "46:2": ["The sending down of the Book, from Allah, the Mighty, the Wise.", "এই ঐশিগ্রন্থের অবতরণ সর্বশক্তিমান, সবচেয়ে জ্ঞানী ঈশ্বরের পক্ষ থেকে।"],
  "46:3": ["We did not create the heavens and the earth and what is between them except in truth and for an appointed term, and those who deny turn away from that of which they are warned.", "আমরা আকাশমণ্ডলী এবং পৃথিবী, এবং এদের মধ্যকার সবকিছু সৃষ্টি করিনি, একটি সুনির্দিষ্ট উদ্দেশ্য, এবং একটি সসীম সময়ের জন্য ছাড়া।"],
  "46:4": ["Say: Tell me about those you call upon besides Allah — show me what they created of the earth, or do they have a share in the heavens? Bring me a scripture from before this, or a trace of knowledge, if you are sadiq.", "বল, \"ঈশ্বরের পাশে তোমরা যে উপাস্যদের স্থাপন করেছ তাদের বিষয়ে ভেবে দেখো। তারা পৃথিবীতে কী সৃষ্টি করেছিল আমাকে দেখাও। স্বর্গের কোন অংশের মালিকানা কি তাদের আছে? এই গ্রন্থের পূর্ববর্তী অন্যকোন ঐশিগ্রন্থ, অথবা প্রতিষ্ঠিত জ্ঞানের কোন অংশ আমাকে দেখাও যা তোমাদের শিরককে সমর্থন করে, যদি তোমরা সত্যবাদী হও।\""],
  "46:5": ["And who is further astray than one who calls upon, besides Allah, those who do not answer him until the Day of Rising? And they are unmindful of their calling.", "তাদের চেয়ে কে অধিকতর পথভ্রষ্ট যারা ঈশ্বরের পাশে অংশীদার স্থাপন করে উপাস্যদের যা তাদের প্রতি কখনো সাড়া দিতে পারে না যতক্ষণ না বিচারের দিন আসে, এবং তাদের উপাসনা সম্পর্কে সম্পূর্ণ অসচেতন?"],
  "46:6": ["And when people are gathered, those called upon will be enemies to them, and will deny that they were ever worshipped.", "এবং যখন মানুষকে তলব করা হয় (বিচার দিবসে),তাদের উপাস্যরা তাদের শত্রু হয়ে পড়বে, এবং তাদের অংশীদারবাদকে প্রত্যাখ্যান করবে।"],
  "46:7": ["And when our clear signs are recited to them, those who deny say, when the truth comes to them: This is clear magic.", "যখন আমাদের প্রকাশনাবলী তাদের কাছে আবৃতি করা হয়েছিল, যথেষ্ট পরিষ্কারভাবে, যারা অবিশ্বাস করেছিল তারা তাদের কাছে আসা সত্য সম্পর্কে বলেছিল, \"এটা স্পষ্টত জাদু!\""],
  "46:8": ["Or do they say: He fabricated it? Say: If I fabricated it, you possess for me nothing against Allah. Allah knows best what you pour forth into it. Sufficient is Allah as a witness between me and you, and Allah is the Forgiving, the Raheem.", "যখন তারা বলে,\"সে এটি বানিয়েছে,\" বল, \"যদি আমি এটি বানাতাম, তাহলে তুমি আমাকে ঈশ্বরের কাছ থেকে রক্ষা করতে পারতে না। তিনি তোমাদের পরিকল্পনার সবকিছু সম্পর্কে সম্পূর্ণ সচেতন। আমার এবং তোমাদের মধ্যে সাক্ষী হিসেবে তিনি যথেষ্ট। তিনি ক্ষমাকারী, সবচেয়ে দয়ালু।\""],
  "46:9": ["Say: I am not an innovation among the Rasuls, and I do not know what will be done with me or with you. I follow only what is revealed to me, and I am nothing but a clear warner.", "বল, \"আমি অন্য বার্তাবাহকদের থেকে আলাদা নই। আমার কোন ধারণা নেই আমার অথবা তোমাদের সাথে কি ঘটবে। আমি কেবল অনুসরণ করি যা আমার কাছে প্রকাশ হয়। আমি একজন স্পষ্ট সতর্ককারীর চেয়ে বেশি কিছু নই।\""],
  "46:10": ["Say: Have you considered — if it is from Allah and you deny it, and a witness from the Children of Israel bears witness to the like of it and believes, while you grow arrogant? Allah does not guide the wrongdoing people.", "বল, \"যদি এটি ঈশ্বরের পক্ষ থেকে হয় আর তোমরা একে অবিশ্বাস করেছো? ইসরাইলের সন্তানদের মধ্য থেকে একজন সাক্ষী একই রকম একটি ঘটনার সাক্ষ্য বহন করেছে, এবং সে বিশ্বাস করেছে, যখন তোমরা উদ্ধত হয়ে পড়েছো। নিশ্চয়, ঈশ্বর অন্যায়কারী লোকদের পথ দেখান না।\""],
  "46:11": ["And those who deny say to those who believe: If it were any good, they would not have preceded us to it. And since they were not guided by it, they will say: This is an old fabrication.", "যারা অবিশ্বাস করেছিল তারা তাদের সম্পর্কে বলেছিল যারা বিশ্বাস করেছিল, \"যদি এটি ভাল কিছু হতো, তারা এটি আমাদের আগে গ্রহন করতো না।\" যেহেতু তারা এর দিকে পথ-নির্দেশিত ছিল না, তারা বলেছিল, \"এটি একটি পুরাতন মিথ্যা-উদ্ভাবন!\""],
  "46:12": ["And before it was the scripture of Musa, a guide and a mercy, and this is a confirming scripture in a clear Arabic tongue, to warn those who wronged and as glad tidings for the doers of good.", "এর আগে, মূসার গ্রন্থ পথ-নির্দেশনা এবং দয়া   প্রদান করেছিল। এটিও একটি ঐশীগ্রন্থ যা নিশ্চিত করে, আরবিতে, তাদেরকে সতর্ক করতে যারা সীমালঙ্ঘন করেছিল, এবং সৎকর্মশীলদের সুসংবাদ দিতে।"],
  "46:13": ["Those who say: Our Rabb is Allah, and then stand firm — no fear is upon them, nor will they grieve.", "নিশ্চয়, যারা বলে, \"আমাদের প্রভু ঈশ্বর, \" এরপর সৎ জীবন-যাপন করে, তাদের কোন ভয় থাকবে না, না তারা শোক করবে।"],
  "46:14": ["Those are the companions of the garden, abiding in it forever, as repayment for what they used to do.", "তারা উপযুক্ত হয়েছে স্বর্গের, যেখানে তারা চিরকাল বাস করে; তাদের কাজের জন্য একটি পুরষ্কার।"],
  "46:15": ["We enjoined the human to kindness toward his parents: his mother carried him unwillingly and bore him unwillingly, and his carrying and his weaning are thirty months, until, when he reaches his full strength and reaches forty years, he says: My Rabb, inspire me to thank for Your blessing which You bestowed upon me and upon my parents, and to do salih work that You approve, and make my descendants salih. I have repented to You, and I am one of those who submit.", "আমরা মানুষকে তার মাতা-পিতার প্রতি সম্মান করতে আদেশ করেছি। কষ্ট করে তার মা তাকে গর্ভধারণ করেছে, কষ্ট করে তাকে জন্ম দিয়েছে, এবং ত্রিশ মাস কাছ থেকে তার যত্ন নিয়েছে। যখন সে পৌঁছে পূর্ণ-বয়সে, এবং পৌঁছে ৪০ বছরে, তার বলা উচিত, “আমার প্রভু, আমাকে চালনা করুন সে অনুগ্রহের মূল্য উপলব্ধিতে যা আপনি আমার উপর এবং আমার মাতা-পিতার উপর অর্পণ করেছেন, এবং সৎকর্মে যা আপনাকে সন্তুষ্ট করে। আমার সন্তানদেরও সৎকর্মশীল হতে দিন। আমি আপনার কাছে অনুশোচনা করেছি; আমি একজন আত্মসমর্পণকারী।"],
  "46:16": ["Those are the ones from whom we accept the best of what they did and pass over their misdeeds, among the companions of the garden — the true promise they were promised.", "তাদের থেকে আমরা সৎকর্ম গ্রহণ করি, আর পাপগুলো এড়িয়ে যাই। তারা স্বর্গের উপযুক্ত। এটা সে সত্য প্রতিশ্রুতি, যে প্রতিশ্রুতি তাদেরকে দেয়া হয়।"],
  "46:17": ["And the one who says to his parents: Fie upon you both! Do you promise me that I will be brought forth, when generations have passed away before me? And they both cry to Allah for help: Woe to you! Believe — the promise of Allah is true. But he says: This is nothing but tales of the ancients.", "এরপর রয়েছে সে ব্যক্তি যে তার মাতা-পিতাকে বলে, \"দূর্ভোগ তোমাদের প্রতি; তোমরা কি আমাকে বলছো যে (মৃত্যুর পর) আমি আবার জীবিত হবো? কেমন করে যারা আমাদের পূর্বে মারা গিয়েছে তারা কখনো ফিরে আসে না? মাতা-পিতারা ঈশ্বরের সাহায্যের জন্য কান্না করে এবং বলে, \"দূর্ভোগ তোমার প্রতি; দয়া করে বিশ্বাস করো! ঈশ্বরের প্রতিশ্রুতি সত্য।\" সে বলে, \"অতীতের কল্প-কাহিনী!\""],
  "46:18": ["Those are the ones upon whom the word proved true, among the nations that passed away before them, of jinn and humankind. They were the khasirin.", "এমনই হলো সে ব্যক্তিরা যারা প্রত্যেক জীন ও মানুষ প্রজন্মের মধ্যে অবিশ্বাসী হিসেবে চিহ্নিত; তারা ক্ষতিগ্রস্থ।"],
  "46:19": ["And for each are degrees according to what they did, and their deeds will be paid to them in full, and they will not be wronged.", "তারা সবাই তাদের প্রাপ্য পদমর্যাদা অর্জন করে, তাদের কর্ম অনুযায়ী। তাদের কাজের জন্য তাদেরকে তিনি মূল্য পরিশোধ করবেন, সামান্যতম অবিচার ছাড়া।"],
  "46:20": ["And the day the kafirin are presented to the fire: You exhausted your good things in the life of this world and enjoyed them. So today you are repaid the punishment of humiliation for what you used to do arrogantly on earth without truth, and for what you used to do defiantly.", "সেদিন আসবে যখন যারা অবিশ্বাস করেছিল তাদের কাছে নরকাগ্নি উপস্থাপন করা হবেঃ \"তোমরা তোমাদের পার্থিব জীবনে তোমাদেরকে দেয়া ভাল সুযোগগুলো নষ্ট করেছো, এবং তোমরা সেগুলো নিয়ে আনন্দিত ছিলে। পরিনামে, আজ তোমরা লজ্জাজনক শাস্তি লাভ করেছো পৃথিবীতে, কোন ভিত্তি ছাড়া তোমাদের সম্পাদিত ঔদ্ধত্যের একটি প্রতিফল হিসেবে, এবং তোমাদের মন্দ কাজগুলোর জন্য।\""],
  "46:21": ["And remember the brother of Aad, when he warned his people in Al-Ahqaf — though warners had passed before him and after him — that you worship none but Allah; I fear for you the punishment of a tremendous day.", "স্মরণ করো যে বালিয়াড়িতে আ'দের ভাই তার লোকদের সতর্ক করেছিল, তার আগে এবং তার পরেও অসংখ্য সতর্কবার্তা প্রদান করা হয়েছিল: \"তোমরা ঈশ্বর ব্যতীত কারো উপাসনা করবে না। আমি তোমাদের জন্য এক গুরুত্বপূর্ণ দিনের শাস্তির ভয় করি।\""],
  "46:22": ["They said: Have you come to us to turn us away from our alihah? Then bring us what you promise us, if you are of the sadiqin.", "তারা বলেছিল, \"তুমি কি এসেছো আমাদেরকে আমাদের উপাস্যদের থেকে দূরে সরিয়ে দিতে? তুমি যার হুমকি দাও (সে শাস্তি) আনার জন্য আমরা তোমাকে চ্যালেঞ্জ করি, যদি তুমি সত্যবাদী হও।"],
  "46:23": ["He said: Knowledge rests only with Allah, and I convey to you what I was sent with; but I see that you are a people who are ignorant.", "সে বলেছিল, \"এ বিষয়ে জ্ঞান রয়েছে ঈশ্বরের কাছে; আমি তোমাদের কাছে শুধু তা-ই পৌঁছে দেই যা পৌঁছানোর জন্য আমাকে পাঠানো হয়েছে। তবে, আমি দেখি যে তোমরা অজ্ঞ লোক।\""],
  "46:24": ["Then, when they saw it as a cloud advancing toward their valleys, they said: This is a cloud that will bring us rain. Rather, it is what you hastened — a wind in which is painful punishment.", "যখন তারা দেখলো ঝড় তাদের দিকে আসছে, তারা বলল, \"এই ঝড় আমাদের জন্য অতি প্রয়োজনীয় বৃষ্টি নিয়ে আসবে।\" বরং, এটা তা-ই যা আনতে তোমরা (হূদকে) চ্যালেঞ্জ করেছিলে; প্রচন্ড বাতাস যেখানে আছে যন্ত্রনাদায়ক শাস্তি।"],
  "46:25": ["It razes everything by the command of its Rabb, and by morning nothing was to be seen but their dwellings. Thus we repay the mujrim people.", "এটি সবকিছু ধ্বংস করেছিল, যেভাবে এর প্রভু নির্দেশ করেছিলেন। সকালের মধ্যে, তাদের বাড়িগুলো ছাড়া কিছুই দাড়িয়ে ছিল না। আমরা এভাবে অপরাধী লোকদের প্রতিফল দেই।"],
  "46:26": ["We had established them in what we have not established you, and gave them hearing and sight and hearts; yet their hearing, their sight, and their hearts availed them nothing when they denied the signs of Allah, and what they used to mock befell them.", "আমরা তাদেরকে একইভাবে প্রতিষ্ঠা করেছিলাম ঠিক যেমন তোমাদেরকে প্রতিষ্ঠা করেছিলাম,  এবং প্রদান করেছিলাম শ্রবণশক্তি, চোখ ও মন। কিন্তু তাদের শ্রবণশক্তি, চোখ এবং মন তাদেরকে সামান্যতম সাহায্য করেনি। এটা এ কারনে যে তারা ঈশ্বরের প্রকাশনাবলি উপেক্ষা করার  সিদ্ধান্ত নিয়েছিল।  তাই,  যেসব ভবিষ্যদ্বাণী ও সতর্কবার্তা নিয়ে তারা উপহাস করেছিল সেগুলোই তাদের ধ্বংসের কারণ হয়েছিল।"],
  "46:27": ["We destroyed the settlements around you and turned the signs toward them, that they might turn back.", "আমরা তোমাদের চারপাশের অনেক সম্প্রদায়কে  নিশ্চিহ্ন করেছি, আমরা প্রমানগুলোর ব্যাখ্যা দেয়ার পর, যাতে তারা অনুশোচনা করে।"],
  "46:28": ["So why did those not help them — the ones they took as alihah besides Allah, seeking nearness through them? Rather, they were lost to them, and that was their fabrication and what they used to invent.", "কেন তাহলে সে উপাস্যরা তাদেরকে সাহায্য করতে ব্যর্থ হয় যাদেরকে তারা ঈশ্বরের নিকটবর্তী হওয়ার জন্য স্থাপন করে? তারাই উল্টো তাদেরকে পরিত্যাগ করেছে। এমনই ছিল মিথ্যা উপাস্যরা, তারা যাদের উপাসনা করেছিল; তাদের উদ্ভাবিত উদ্ভাবনগুলি ছিল এরকম।"],
  "46:29": ["And when we turned to you a band of the jinn listening to the recitation: when they were present at it, they said: Listen quietly. And when it was finished, they returned to their people as warners.", "স্মরণ করো যে আমরা কিছু সংখ্যক জীনকে তোমার দিকে পরিচালিত করেছিলাম, যাতে করে তারা কুরআন শুনতে পারে। যখন তারা সেখানে পৌঁছে গিয়েছিল, তারা বলেছিল, \"শোন\"। এটি সমাপ্ত হওয়া মাত্রই, তারা তাদের লোকদের নিকট ছুটলো, সতর্ক করতে।"],
  "46:30": ["They said: O our people, we have heard a scripture sent down after Musa, confirming what is before it, guiding to the truth and to a straight path.", "তারা বলল, \"হে আমাদের লোকেরা, আমরা একটি গ্রন্থ শুনেছি যা মূসার পরে প্রকাশিত হয়েছে, এবং পূর্ববর্তী ঐশীগ্রন্থগুলোকে নিশ্চিত করে। এটি দিকনির্দেশনা দেয় সত্যের দিকে; সঠিক পথের দিকে।"],
  "46:31": ["O our people, answer the caller of Allah and believe in Allah; Allah will forgive you your offenses and shield you from a painful punishment.", "\"হে আমাদের লোকেরা, ঈশ্বরের ডাকে সাড়া দাও, এবং তাঁর প্রতি বিশ্বাস রাখো। তাহলে তিনি তোমাদের পাপগুলো ক্ষমা করে দিবেন, এবং এক যন্ত্রনাদায়ক শাস্তি থেকে তোমাদেরকে নিষ্কৃতি দিবেন।\""],
  "46:32": ["Whoever does not answer the caller of Allah can never escape on earth, and will have no protectors besides Allah. Those are in clear error.", "যারা ঈশ্বরের ডাকে সাড়া দিতে ব্যর্থ হয় তারা পালাতে পারবে না, এবং তাঁকে ছাড়া কোন প্রভু পাবে না; তারা বহুদূর পথভ্রষ্ট হয়েছে।"],
  "46:33": ["Do they not see that Allah, who created the heavens and the earth and was not wearied by creating them, is able to give life to the dead? Yes, Allah is over everything able.", "তারা কি অনুধাবন করে না যে ঈশ্বর, যিনি আকাশমন্ডলী ও পৃথিবী সৃষ্টি করেছেন সামান্যতম প্রচেষ্টা ছাড়া, মৃতকে পুনর্জীবিত করতে সক্ষম? হ্যাঁ নিশ্চয়; তিনি সর্বশক্তিমান।"],
  "46:34": ["And the day the kafirin are presented to the fire: Is this not the truth? They will say: Yes, by our Rabb. It will be said: Then taste the punishment for what you used to deny.", "সেদিন যখন অবিশ্বাসীদের কাছে নরকাগ্নি উপস্থাপন করা হবে, তাদেরকে জিজ্ঞেস করা হবে, \"এটা কি সত্য নয়?\" তারা উত্তর দিবে, \"হ্যাঁ নিশ্চয়, আমাদের প্রভুর শপথ।\" তিনি বলবেন, \"তাহলে তোমাদের অবিশ্বাসের জন্য শাস্তি ভোগ করো।\""],
  "46:35": ["So be of the sabirin, as those of resolve among the Rasuls were sabir, and do not hasten for them. On the day they see what they are promised, it will be as though they tarried but an hour of a day. The message has been conveyed. Are any destroyed but the defiant people?", "একারনে, ধৈর্যশীল হও তোমার পূর্বের বার্তাবাহকদের মতো যারা ছিল শক্তিমত্তার অধিকারী এবং ধৈর্য্য-অবলম্বন করতো। শাস্তি দেখার জন্য তাড়াহুড়োয় থেকো না, এটা তাদের কাছে অনিবার্যভাবে আসবে। তারা যেদিন এটি দেখবে, এটি মনে হবে যেন তারা দিনের এক ঘন্টা অবস্থান করেছিল। এটি একটি ঘোষণা :  এরা কি অন্যায়কারীরা নয় যারা প্রতিনিয়ত নির্মূল হয়?"],
  "47:1": ["Those who disbelieve and bar the path of Allah — their works are lost.", "যারা অবিশ্বাস করে এবং ঈশ্বরের পথে বাধা দেয়, তিনি তাদের কাজগুলো অকার্যকর করে দেন।"],
  "47:2": ["And those who believe and do the right deeds, and believe in what was sent down upon Muhammad — and it is the truth from their Rabb — Allah wipes away their bad deeds and sets their state right.", "যারা বিশ্বাস করে এবং সৎকর্মশীল কাজ করে, এবং বিশ্বাস করে যা অবতীর্ণ করা হয়েছিল মুহাম্মদের উপর- যা তাদের ঈশ্বরের পক্ষ থেকে আসা সত্য- তিনি তাদের পাপগুলো ক্ষমা করে দেন, এবং তাদেরকে পরিতৃপ্তি দিয়ে সৌভাগ্যবান করেন।"],
  "47:3": ["That is because those who disbelieve followed falsehood, and those who believe followed the truth from their Rabb. Thus does Allah set forth for the people their parables.", "এটা এ কারণে যে, যারা অবিশ্বাস করে তারা অনুসরণ করছে মিথ্যা, আর যারা বিশ্বাস করে তারা অনুসরণ করছে তাদের প্রভুর পক্ষ থেকে আসা সত্য। ঈশ্বর এভাবে লোকদের জন্য উদ্ধৃতি দেন, তাদের উদাহরণসমূহ।"],
  "47:4": ["So when you meet those who disbelieve, strike the necks, until when you have struck them down heavily, bind fast the bonds. Then, afterward, either an act of favor or ransom, until the war lays down its burdens. That is so; and if Allah willed, Allah would take victory over them, but rather so that Allah may test some of you by means of others. And those who are slain in the path of Allah — their works will never be lost.", "যদি তোমরা (যুদ্ধে) তাদের মুখোমুখি হও যারা অবিশ্বাস করে, তোমরা আঘাত করতে পারো ঘাড়ে। যদি তোমরা তাদেরকে বন্দী হিসেবে নাও তোমরা তাদেরকে মুক্ত করতে পারো অথবা তাদের থেকে মুক্তিপণ নিতে পারো, যতক্ষণ না যুদ্ধ শেষ হয়। যদি ঈশ্বর চাইতেন, তিনি তোমাদেরকে বিজয় দান করতে পারতেন, যুদ্ধ করা ছাড়া। কিন্তু এভাবে তিনি তোমাদেরকে একে অন্যের দ্বারা পরীক্ষা করেন। আর তাদের ক্ষেত্রে যারা আল্লাহর উদ্দেশ্যে নিহত হয়, তিনি তাদের উৎসর্গকে কখনো নষ্ট হতে দেন না।"],
  "47:5": ["Allah will guide them and set their state right.", "তিনি তাদেরকে পথ দেখাবেন, এবং তাদেরকে পরিতৃপ্তি দিয়ে অনুগ্রহ করবেন।"],
  "47:6": ["And admit them into the garden, whose ways Allah has made known to them.", "তিনি তাদেরকে স্বর্গে প্রবেশ করাবেন, যা তিনি তাদের কাছে বর্ণনা করেছিলেন।"],
  "47:7": ["O you who believe: if you help Allah, Allah will help you and make your feet firm.", "হে তোমরা যারা বিশ্বাস করো, যদি তোমরা ঈশ্বরকে সমর্থন করো, তিনি তোমাদেরকে সমর্থন করবেন, এবং তোমাদের অবস্থানকে দৃঢ় করবেন।"],
  "47:8": ["And those who disbelieve — wretchedness is theirs, and their works are lost.", "যারা অবিশ্বাস করে তারা দু:খ-কষ্ট টেনে আনে। তিনি তাদের কাজগুলো একেবারেই বৃথা করে দেন।"],
  "47:9": ["That is because they loathed what Allah sent down, so their works are void.", "এটা এ কারণে যে তারা ঘৃনা করেছিল যা ঈশ্বর প্রকাশ করেছিলেন এবং পরিনামে, তিনি তাদের কাজগুলো অকার্যকর করে দেন।"],
  "47:10": ["Have they not journeyed through the land to see how was the end of those before them? Allah razed them, and for the kafirin there is the like of it.", "তারা কি পৃথিবীতে ঘুড়ে বেড়ায়নি এবং তাদের পূর্ববর্তীদের পরিনাম দেখেনি? ঈশ্বর তাদের কাজগুলো  ধ্বংস করে দিয়েছিলেন; সকল অবিশ্বাসীরা একই নিয়তি ভোগ করবে।"],
  "47:11": ["That is because Allah is the protector of those who believe, and the kafirin have no protector.", "এটা এ কারণে যে ঈশ্বর তাদের প্রভু যারা বিশ্বাস করে, অপরদিকে অবিশ্বাসীদের কোন প্রভু নেই।"],
  "47:12": ["Allah will admit those who believe and do the right deeds into gardens beneath which rivers flow. And those who disbelieve take their enjoyment and eat as the cattle eat — and the fire is their lodging.", "যারা বিশ্বাস করে এবং সৎকর্মশীল জীবন-যাপন করে ঈশ্বর তাদেরকে প্রবেশ করান প্রবাহিত ঝর্ণাসহ বাগানসমূহে। আর তাদের ক্ষেত্রে যারা অবিশ্বাস করে, তারা বাচেঁ এবং খায় যেমন খায় অন্য প্রানীরা, এরপর নরকাগ্নীতে শেষ হয়।"],
  "47:13": ["How many a town, stronger in might than your town which expelled you, have We destroyed — and no helper was there for them.", "অনেক সম্প্রদায় সে সম্প্রদায়ের চেয়ে অনেক বেশি শক্তিশালী ছিল যারা তোমাকে তোমার শহর থেকে উচ্ছেদ করেছিল; যখন আমরা তাদের ধ্বংস করেছিলাম, কেউ তাদের সাহায্য করতে পারেনি।"],
  "47:14": ["Is one who stands upon clear proof from their Rabb like those whose evil deeds are made to look attractive to them, and who follow their desires?", "যারা তাদের প্রভুর দ্বারা আলোকিত তারা কি তাদের মতো যাদের মন্দ কাজগুলো তাদের চোখে সুশোভিত করা হয়েছে, এবং তারা তাদের নিজের মত অনুসরণ করে?"],
  "47:15": ["The likeness of the garden promised to the muttaqin: in it rivers of water, never stale; and rivers of milk whose taste never changes; and rivers of wine, a delight for the drinkers; and rivers of strained honey. And theirs therein is every fruit, and forgiveness from their Rabb. Is that like one who abides forever in the fire, given scalding water to drink, that cuts through their bowels?", "স্বর্গ, যা সৎকর্মশীলদের জন্য অঙ্গীকার করা হয়েছে তার উপমা হলোঃ এর আছে অদূষিত পানির নদীসমূহ, এবং বিশুদ্ধ  দুধের নদীসমূহ, এবং শরাবের নদীসমূহ- যা পানকারীদের জন্য সুস্বাদু- এবং পরিশোধিত মধুর নদীসমূহ। সেখানে তাদের আছে সব ধরণের ফল, এবং তাদের প্রভুর পক্ষ থেকে ক্ষমা। (তারা কি উত্তম) নাকি যারা চিরকালের জন্য নরকাগ্নীতে বাস করে, এবং নারকীয় পানি পান করে যা তাদের অন্ত্রগুলোকে ছিঁড়ে ফেলে?"],
  "47:16": ["And among them are those who listen to you, until when they leave your presence they say to those given knowledge: \"What did he say just now?\" Those are the ones upon whose hearts Allah has set a seal, and they follow their desires.", "তাদের কেউ কেউ তোমার কথা শুনে, এরপর এরা চলে যাওয়া মাত্রই তাদেরকে জিজ্ঞেস করে যারা বিজ্ঞ, “সে এইমাত্র কি বলেছে?” ঈশ্বর এভাবে তাদের হৃদয়ে মোহর এঁটে দেন এবং, পরিনামে, তারা তাদের নিজেদের মতামত অনুসরণ করে।"],
  "47:17": ["And those who are guided — Allah increases them in guidance and gives them their mindfulness.", "আর তাদের ক্ষেত্রে যারা পথনির্দেশনা পেয়েছে, তিনি তাদের পথনির্দেশনা ত্বরান্বিত করেন, এবং তাদের জন্য সৎকর্মশীলতা মঞ্জুর করেন।"],
  "47:18": ["So do they wait for anything but the Hour, that it come upon them suddenly? Its signs have already come. How, then, will it be for them when their reminder comes to them?", "তারা কি অপেক্ষা করছে- যে পর্যন্ত না সে সময় তাদের কাছে হঠাৎ করে আসে? ইতিমধ্যে এর সব নিদর্শন এসে গেছে। একবার যখন সে ঘন্টা তাদের কাছে আসে, কিভাবে তারা তাদের বার্তা থেকে উপকৃত হবে?"],
  "47:19": ["So know that there is no ilah but Allah, and seek forgiveness for your offense, and for the believing men and the believing nisa. And Allah knows your comings and goings and your lodgings.", "তোমরা জেনে রাখো যে: ঈশ্বরের পাশে অন্যকোন উপাস্য নেই, \"  এবং ক্ষমা চাও তোমাদের পাপ এবং সকল বিশ্বাসী নারী-পুরুষের পাপের জন্য। ঈশ্বর তোমাদের  সিদ্ধান্ত এবং তোমাদের চূড়ান্ত নিয়তি সম্পর্কে পূর্ণ অবগত।"],
  "47:20": ["And those who believe say: \"Why has no chapter been sent down?\" Then, when a firm chapter is sent down and fighting is mentioned in it, you see those in whose hearts is sickness looking at you with the look of one covered over by death. They would be better off.", "যারা বিশ্বাস করেছিল তারা বলেছিল: \"কখন একটি নতুন সূরা প্রকাশিত হবে?\" কিন্তু যখন একটি সহজবোধ্য সূরা প্রকাশিত হলো, যেখানে যুদ্ধের উল্লেখ করা হয়েছিল, তখন তুমি তাদেরকে দেখতে তোমার দিকে তাকিয়ে আছে যারা তাদের হৃদয়ে সন্দেহ পোষন করেছিল, যেন মৃত্যু তাদের কাছে এসেই পড়েছে। তারা এইভাবে উন্মোচিত হয়েছিল।"],
  "47:21": ["Obedience and a kind word. Then, when the matter is resolved, if only they had been true to Allah, it would have been better for them.", "অনুগত থাকা এবং ন্যায়নিষ্ঠ কথাই তাদের কাছ থেকে প্রত্যাশিত। যদি শুধু তারা ঈশ্বরের প্রতি আত্মবিশ্বাস দেখাতো, যখন যুদ্ধের জন্য একত্রিত হতে ডাকা হয়েছিল, এটা তাদের জন্য উত্তম হতো।"],
  "47:22": ["So might it be that, if you turn away, you would spread corruption in the land and sever your kin-ties?", "এটাও কি তোমাদের উদ্দেশ্য যে তোমরা চলে যাবার সাথে সাথেই মন্দ কাজ করবে এবং তোমাদের আত্মীয়দের সাথে দুর্ব্যবহার করবে?"],
  "47:23": ["Those are the ones Allah has cursed — made them deaf and blinded their sight.", "এরা তারাই যারা ঈশ্বর থেকে অভিশাপ টেনে এনেছিল, যার দ্বারা তিনি তাদেরকে বধির এবং অন্ধ করেছিলেন।"],
  "47:24": ["Do they not reflect upon the Recitation, or are there locks upon their hearts?", "কেন তারা যত্নসহকারে কুরআন অধ্যয়ন করে না? তাদের অন্তর কি তালাবদ্ধ?"],
  "47:25": ["Those who turned back on their heels after the guidance had become clear to them — Shaytan beguiled them and gave them respite.", "নিশ্চয়, যারা পিছনে ধাবিত হয়, তাদের কাছে সুস্পষ্টভাবে পথ-নির্দেশনা প্রকাশিত হবার পর, শয়তান তাদেরকে প্ররোচিত করেছে এবং তাদেরকে বিপথগামী করেছে।"],
  "47:26": ["That is because they said to those who loathed what Allah sent down: \"We will obey you in part of the matter.\" And Allah knows their secrets.", "এটা এ কারনে যে তারা তাদেরকে বলেছিল যারা ঘৃনা করতো যা ঈশ্বর অবতীর্ণ করেছেন, \"আমরা তোমাদেরকে মান্য করবো সুনির্দিষ্ট ব্যাপারে।\" ঈশ্বর সম্পূর্ণভাবে তাদের গোপন ষড়যন্ত্র  জানেন।"],
  "47:27": ["So how will it be when the malakat take them, striking their faces and their backs?", "এটা তাদের জন্য কেমন হবে যখন ফেরেশতারা তাদের মৃত্যু ঘটাবে? তারা তাদের প্রহার করবে তাদের মুখে এবং তাদের পশ্চাৎপ্রান্তে।"],
  "47:28": ["That is because they followed what angered Allah and loathed Allah's approval — so their works are void.", "এটা একারণে যে তারা অনুসরণ করেছিল যা আল্লাহকে রাগান্বিত করেছিল এবং ঘৃনা করতো সে বিষয়গুলো যা তাঁকে সন্তুষ্ট করে। ফলশ্রুতিতে, তিনি তাদের কাজগুলো নিষ্ফল করে দিয়েছেন।"],
  "47:29": ["Or do those in whose hearts is sickness suppose that Allah will never bring out their rancor?", "যারা তাদের হৃদয়ে সন্দেহ পোষণ করেছিল তারা কি মনে করে যে আল্লাহ তাদের মন্দ চিন্তাগুলো প্রকাশ করবেন না?"],
  "47:30": ["And if We willed, We would show them to you, and you would know them by their marks. And you will surely know them by the slant of their speech. And Allah knows your works.", "যারা তাদের হৃদয়ে সন্দেহ পোষণ করেছিল তারা কি মনে করে যে আল্লাহ তাদের মন্দ চিন্তাগুলো প্রকাশ করবেন না?"],
  "47:31": ["And We will surely test you, until We know the strivers among you and the sabirin, and We test your report.", "নিশ্চয় আমরা তোমাদের পরীক্ষা করবো, তোমাদের মধ্যে তাদেরকে আলাদা করতে যারা সংগ্রাম করে, এবং দৃড়তার সাথে অধ্যবসায়ী। আমরা অবশ্যই তোমাদের সত্যিকার বৈশিষ্ট্য প্রকাশ করবো।"],
  "47:32": ["Those who disbelieve and bar the path of Allah and oppose the Rasul after the guidance has become clear to them will never harm Allah at all, and their works will be void.", "যারা অবিশ্বাস করে এবং ঈশ্বরের পথে বাধা দেয়, এবং তাদের জন্য পথ-নির্দেশনা সুস্পষ্টভাবে প্রকাশিত হবার পর বার্তাবাহকদের বিরোধিতা করে, কখনোই ঈশ্বরকে সামান্যতম আঘাত করবে না। উল্টো, তিনি তাদের কাজগুলোঅকার্যকর করেন।"],
  "47:33": ["O you who believe: obey Allah and obey the Rasul, and do not void your works.", "হে তোমরা যারা বিশ্বাস করো, তোমরা মান্য করবে ঈশ্বরকে, এবং মান্য করবে বার্তাবাহককে। অন্যথায়, তোমাদের সকল কাজ বৃথা হয়ে যাবে।"],
  "47:34": ["Those who disbelieve and bar the path of Allah, then die while they are kafirin — Allah will never forgive them.", "যারা অবিশ্বাস করে এবং ঈশ্বরের পথে বাঁধা দেয়, এরপর অবিশ্বাসী হিসেবে মারা যায়, ঈশ্বর তাদেরকে কখনো ক্ষমা করবেন না।"],
  "47:35": ["So do not falter and call for peace while you have the upper hand. Allah is with you, and Allah will never let your works go to waste.", "একারণে, তোমরা দ্বিধান্বিত হইও না এবং শান্তির আশায় আত্মসমর্পণ করো না, কারণ তোমাদেরকে বিজয়ের নিশ্চয়তা দেয়া হয়, এবং আল্লাহ তোমাদের সাথে আছেন। তিনি কখনো তোমাদের চেষ্টা বিফলে যেতে দিবেন না।"],
  "47:36": ["The life of this world is nothing but play and diversion. And if you believe and are mindful, your rewards will be given to you, and Allah will not ask you for your wealth.", "এই পার্থিব জীবন খেলা এবং অহমিকার চেয়ে বেশি কিছু নয়। কিন্তু যদি তোমরা বিশ্বাস করো এবং সৎ জীবন-যাপন করো, তিনি তোমাদের পুরষ্কৃত করবেন, তোমাদের কাছে কোন টাকা না চেয়ে।"],
  "47:37": ["If Allah were to ask you for it and press you hard, you would stint, and your rancor would be brought out.", "যদি তিনি তোমাদের কাছে টাকা চাইতেন, এতো পরিমানে যে তোমাদের জন্য কষ্টকর হয়ে দাঁড়ায়, তোমরা কৃপন হয়ে পড়তে, এবং তোমাদের লুকায়িত মন্দকর্ম প্রকাশ হয়ে যেতো।"],
  "47:38": ["Here you are, called to spend in the path of Allah, yet among you are those who stint. Whoever stints only stints against himself — Allah is the Self-Sufficient, and you are the needy. And if you turn away, Allah will substitute another people in your place, and they will not be the likes of you.", "তোমরা আল্লাহর উদ্দেশ্যে ব্যয় করতে আমন্ত্রিত, কিন্তু তোমাদের কেউ কেউ কৃপণ হয়ে পড়ো। কৃপণরা তাদের নিজ আত্নার প্রতিই কৃপণ। ঈশ্বর ধনী, যেখানে তোমরা দরিদ্র।"],
  "48:1": ["Indeed We have bestowed on you a clear triumph", "(হে বার্তাবাহক) আমরা তোমার উপর অর্পণ করেছি এক মহা বিজয়।"],
  "48:2": ["So that Allah may forgive you the offense that came before and the offense that comes after, and complete the blessing upon you, and guide you on a straight path", "এর দ্বারা ঈশ্বর ক্ষমা করেন তোমার অতীতের পাপসমূহ, একই সাথে ভবিষ্যত্বের পাপসমূহ, আর তোমার উপর তাঁর অনুগ্রহসমূহ পূর্ণ করেন এবং তোমাকে সরল পথে পরিচালিত করেন ।"],
  "48:3": ["And Allah will help you with a mighty help", "উপরন্তু, ঈশ্বর তোমাকে সমর্থন করবেন - যে সমর্থন নড়বড়ে নয়  ।"],
  "48:4": ["Allah is the One who sent down tranquility into the hearts of the muminin, so that they increase in faith along with their faith; to Allah belong the hosts of the heavens and the earth, and Allah has always been knowing, wise", "তিনিই সে সত্ত্বা যিনি বিশ্বাসীদের হৃদয়ে পরিতৃপ্তি দেন- তাদের বিশ্বাসে আরো বিশ্বাস দিয়ে ত্বরান্বিত করতে । আকাশমন্ডলী এবং পৃথিবীর সকল বাহিনী ঈশ্বরের অধীনে। ঈশ্বর সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "48:5": ["So that Allah may admit the believing men and the believing nisa into gardens beneath which rivers flow, to stay forever in them, and wipe their evil deeds away from them — and that is, with Allah, a tremendous win", "নিশ্চয় তিনি বিশ্বাসী পুরুষ এবং নারীদের প্রবেশ করাবেন প্রবাহিত ঝর্ণাসহ বাগানসমূহে, যেখানে তারা চিরকাল বাস করবে। তিনি তাদের পাপসমূহ ক্ষমা করে দেবেন। এটি, ঈশ্বরের দৃষ্টিতে, এক মহা বিজয়।"],
  "48:6": ["And Allah will punish the munafiq men and the munafiq nisa, and the associating men and the associating nisa who think of Allah the thought of evil; the turn of evil circles upon them, and the wrath of Allah is upon them, and Allah has cursed them, and prepared hell for them — and evil is their arrival", "এবং তিনি প্রতিশোধ গ্রহন করবেন ভণ্ড পুরুষ ও নারী এবং প্রতিমা উপাসনাকারী পুরুষ ও নারীদের থেকে, কারণ তারা ঈশ্বর সম্পর্কে   মন্দ ধারণা পোষণ করেছে।  তাদের মন্দকর্ম উল্টো তাদেরই বিপর্যয় ঘটাবে। কারণ ঈশ্বর তাদের প্রতি রাগান্বিত, তাদের নিন্দা করেন এবং তাদের জন্য প্রস্তুত রেখেছেন নরক । কি এক শোচনীয় পরিণতি!"],
  "48:7": ["And to Allah belong the hosts of the heavens and the earth, and Allah has always been mighty, wise", "আকাশমন্ডলী এবং পৃথিবীর সকল বাহিনী ঈশ্বরের অধীনে। ঈশ্বর সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "48:8": ["We have sent you as a witness, a bearer of good news, and a warner", "তোমাকে আমরা পাঠিয়েছি একজন সাক্ষী, সুসংবাদবহনকারী, এবং সতর্ককারী হিসেবে।"],
  "48:9": ["So that you believe in Allah and in Allah's Rasul, and give Allah support, and honor Allah, and glorify Allah morning and evening", "যাতে তোমরা লোকেরা হয়তো  ঈশ্বর ও তাঁর বার্তাবাহককে বিশ্বাস করবে, এবং  তাঁকে ভক্তি করবে, এবং তাঁকে মান্য করবে, এবং তাঁর মহিমা ঘোষণা করবে, দিনে ও রাতে।"],
  "48:10": ["Those who make a deal with you are in fact making a deal with Allah; the hand of Allah is above their hands; so whoever breaks the pledge, breaks it only against themselves, and whoever fulfills what was pledged to Allah, Allah will give them a tremendous reward", "নিশ্চয়, যারা তোমার প্রতি আনুগত্যের অঙ্গিকার করে, তারা ঈশ্বরের প্রতিই আনুগত্যের অঙ্গিকার করছে । ঈশ্বর তাদের অঙ্গিকারকে সমর্থন করেন; তিনি তাঁর হাত রাখেন তাদের হাতের উপর। যারা এমন অঙ্গিকার লংঘন করে, তারা লংঘন করে তাদের নিজের ক্ষতি করতে। আর তাদের ক্ষেত্রে যারা আল্লাহর সাথে তাদের অঙ্গীকার পূর্ণ করে, তিনি তাদেরকে এক মহা প্রতিদান প্রদান করবেন।"],
  "48:11": ["Those who stayed behind of the desert Arabs will say to you: our wealth and our families kept us busy, so ask forgiveness for us. They say with their tongues what is not in their hearts. Say: who can own anything for you against Allah, if Allah intends harm for you or intends benefit for you? No — Allah has always been aware of what you do", "অলস আরবরা যারা পিছনে রয়ে যায়, বলবে, \"আমরা আমাদের টাকা-পয়সা এবং আমাদের পরিবার নিয়ে আচ্ছন্ন ছিলাম, তাই আমাদের জন্য ক্ষমা প্রার্থনা করো।\" তারা তাদের মুখে বলে, যা তাদের অন্তরে নেই। বল, \"কে তোমাদেরকে ঈশ্বর থেকে রক্ষা করতে পারে, যদি তিনি তোমাদের জন্য কোন দূর্ভোগ চান, অথবা যদি তিনি তোমাদের জন্য কোন অনুগ্রহ চান ? \" ঈশ্বর তোমাদের করা সবকিছু সম্পর্কে পূর্ণ অবগত।"],
  "48:12": ["You thought that the Rasul and the muminin would never return to their families, and that was adorned in your hearts, and you thought the thought of evil, and you were a people ruined", "তোমরা গোপনে বিশ্বাস করেছিলে যে, বার্তাবাহক ও বিশ্বাসীরা পরাজিত হবে এবং  কখনো তাদের পরিবারে ফিরে আসবে না, আর এটা তোমাদের হৃদয়ে দৃঢ়ভাবে প্রতিষ্ঠিত ছিল। তোমরা মন্দ ধারণা পোষণ করেছিলে এবং অন্যায়কারী মানুষে পরিণত হয়েছিলে।"],
  "48:13": ["And whoever does not believe in Allah and in Allah's Rasul — We have prepared a blaze for the unmuminin", "যেকেউ ঈশ্বর ও তাঁর বার্তাবাহককে বিশ্বাস করা প্রত্যাখ্যান করে, আমরা অবিশ্বাসীদের জন্য প্রস্তুত রেখেছি একটি নরকাগ্নি ।"],
  "48:14": ["And to Allah belongs the dominion of the heavens and the earth; Allah forgives whomever Allah wills and punishes whomever Allah wills, and Allah has always been forgiving, merciful", "আকাশমণ্ডলী ও পৃথিবীর সার্বভৌমত্ব ঈশ্বরের অধীনে । তিনি যাকে ইচ্ছা ক্ষমা করেন, এবং যাকে ইচ্ছা শাস্তি দেন। ঈশ্বর ক্ষমাকারী, সবচেয়ে দয়ালু।"],
  "48:15": ["The ones who stayed behind will say, when you set out to take the gains: let us follow you. They want to substitute the word of Allah. Say: you will never follow us. This is what Allah declared to you before. Then they will say: no, you envy us. No — they understood only a little", "যখন তোমাদের যুদ্ধলব্ধ মাল সংগ্রহের সময় হয়, তখন সে বসে থাকা লোকেরা যারা পিছনে রয়ে যায় বলবে , \"চল এটি ভাগাভাগি করতে আমরা তোমাদের অনুসরণ করি!\" তারা এভাবে ঈশ্বরের বানী বিকৃত করার ইচ্ছা করে। বল, \"তোমরা আমাদের অনুসরণ করবে না। এটি ঈশ্বরের সিদ্ধান্ত।\" তারা এরপর বলবে, \" আমাদের প্রতি  তোমরা নিশ্চয় ঈর্শান্বিত (পিছনে থেকে যাবার  কারণে) \"। প্রকৃতপক্ষে, তারা খুব কমই কিছু বুঝে।"],
  "48:16": ["Say to the desert Arabs who stayed behind: you will be called against a people of severe fighting — you will kill them or they will submit. If you obey, Allah will give you a good reward; but if you turn away as you turned away before, Allah will punish you with a painful punishment", "অলস আরবদের বল যারা পিছনে রয়ে যায়, \"তোমাদের আমন্ত্রণ  করা হবে শক্তিশালী মানুষদের মুখোমুখি হতে আর তাদের সাথে লড়াই করতে, যদিনা তারা আত্মসমর্পন করে। যদি তোমরা মেনে চল, ঈশ্বর তোমাদেরকে এক মহা প্রতিদান দিয়ে পুরষ্কৃত করবেন । কিন্তু যদি তোমরা আবারো মুখ ফিরিয়ে নাও, যেমন তোমরা অতীতে করেছিলে, তিনি এক যন্ত্রণাদায়ক শাস্তি দিয়ে তোমাদের থেকে প্রতিশোধ গ্রহণ করবেন ।"],
  "48:17": ["There is no blame on the blind, no blame on the lame, and no blame on the sick; whoever obeys Allah and Allah's Rasul, Allah will admit them into gardens beneath which rivers flow, and whoever turns away, Allah will punish them with a painful punishment", "অন্ধরা দোষী হবে না, পঙ্গুরা দোষী হবে না, অসুস্থরা দোষী হবে না। যারা ঈশ্বর এবং তাঁর বার্তাবাহককে মেনে চলে, তিনি তাদেরকে প্রবাহিত ঝর্ণাসহ বাগানসমূহে প্রবেশ করাবেন। আর যারা মুখ ফিরিয়ে নেয়, তিনি এক যন্ত্রণাদায়ক শাস্তি দিয়ে তাদের থেকে প্রতিশোধ গ্রহণ করবেন।"],
  "48:18": ["Allah was pleased with the muminin when they made a deal with you under the tree; Allah knew what was in their hearts, so Allah sent down tranquility upon them and rewarded them with a near triumph", "ঈশ্বর সে বিশ্বাসীদের প্রতি সন্তুষ্ট যারা গাছের নিচে তোমার প্রতি আনুগত্যের অঙ্গীকার  করেছিল । তিনি জানতেন তাদের হৃদয়ে কী ছিল এবং, ফলশ্রুতিতে, তিনি তাদেরকে পরিতৃপ্তি দিয়ে অনুগ্রহ করলেন এবং তাদেরকে একটি আসন্ন বিজয় দিয়ে পুরস্কৃত করলেন ।"],
  "48:19": ["And many gains they will take — and Allah has always been mighty, wise", "উপরন্ত,  তারা অনেক যুদ্ধলব্ধ মাল অর্জন করেছিল। ঈশ্বর সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "48:20": ["Allah promised you many gains that you will take, so Allah hastened this one for you and held back the hands of people from you, so that it may be a sign for the muminin and so that Allah may guide you on a straight path", "ঈশ্বর তোমাদেরকে অনেক যুদ্ধলব্ধ মালের প্রতিস্রুতি দিয়েছেন যা তোমরা অর্জন করবে। এভাবে তিনি তোমাদের জন্য কিছু সুবিধা  এই জীবনে অগ্রীম প্রদান করলেন এবং তিনি তোমাদের বিরুদ্ধে লোকেদের আগ্রাসনের হাতকে ঠেকিয়ে রেখেছেন, আর একে বিশ্বাসীদের জন্য করেছেন একটি নিদর্শন। তিনি এভাবে তোমাদেরকে সরল পথ প্রদর্শন করেন।"],
  "48:21": ["And others that you had no power over — Allah has already encompassed them, and Allah has always been able over everything", "আর সে দলটির ক্ষেত্রে যাদেরকে তোমরা কখনোই পরাজিত করতে পারতে না, ঈশ্বর তাদের ভার নিয়েছিলেন; ঈশ্বর সর্বশক্তিমান।"],
  "48:22": ["If those who kafara had fought you, they would have turned their backs, and then found no protector and no helper", "যদি কখনো অবিশ্বাসীরা তোমাদের সাথে লড়াই করতো, তারা ঘুরে দাঁড়াতো এবং  পালিয়ে যেতো। তাদের কোন প্রভু ও মনিব নেই; তাদের কোন সাহায্যকারী  নেই।"],
  "48:23": ["Such is the way of Allah that has passed before, and you will never find any change in the way of Allah", "ইতিহাসের সর্বত্র ঈশ্বরের নিয়ম এমনই, এবং তুমি ঈশ্বরের নিয়ম অপরিবর্তনীয় পাবে।"],
  "48:24": ["And Allah is the One who held back their hands from you and your hands from them, in the inner part of Makkah, after Allah had given you victory over them; and Allah sees all that you do", "তিনিই সে সত্ত্বা যিনি তোমাদের বিরুদ্ধে তাদের আগ্রাসনের হাতকে ঠেকিয়ে রেখেছেন, এবং মক্কা উপত্যকায় তাদের বিরুদ্ধে তোমাদের আগ্রাসনের হাতকে ঠেকিয়ে রেখেছেন, তাদের উপর তোমাদের বিজয় প্রদান  করার পর। ঈশ্বর সবকিছুর দ্রষ্টা, যা কিছু তোমরা করো।"],
  "48:25": ["They are the ones who kafara and barred you from the sacred mosque, and the offering held back from reaching its place. Were it not for believing men and believing nisa you did not know — that you might trample them and disgrace strike you from them without knowledge — so that Allah may admit whomever Allah wills into Allah's mercy. Had they stood apart, We would have punished those of them who kafara with a painful punishment", "তারাই তো অবিশ্বাস করেছিল এবং তোমাদেরকে পবিত্র মসজিদে যেতে বাঁধা দিয়েছিল, আর এমনকি তোমাদের উৎসর্গগুলোকেও তাদের গন্তব্যে পৌঁছতে দেয়নি। সেখানে (শত্রু শিবিরের ভেতর) ছিল বিশ্বাসী পুরুষ ও নারীরা যাদেরকে তোমরা চিনতে না, এবং তাদেরকে তোমরা প্রায় আঘাতই  করে ফেলেছিলে, অজ্ঞাতসারে। ঈশ্বর এভাবে তাঁর দয়ায় যাকেই চান প্রবেশ করান। যদি তারা অনড় থাকে, তবে তিনি এক যন্ত্রণাদায়ক শাস্তি দিয়ে তাদের মধ্যে যারা অবিশ্বাস করে তাদের থেকে প্রতিশোধ নিবেন।"],
  "48:26": ["When those who kafara put the blaze in their hearts — the blaze of the pagan way — then Allah sent down Allah's tranquility upon Allah's Rasul and upon the muminin, and bound them fast to the word of ilahfearing, and they were most deserving of it and most worthy of it; and Allah has always been knowing of everything", "যেখানে যারা অবিশ্বাস করেছিল তারা ছিল রাগান্বিত আর তাদের হৃদয় ছিল অজ্ঞতার দিনগুলোর গর্বে পূর্ণ, সেখানে আল্লাহ তাঁর বার্তাবাহক ও বিশ্বাসীদের অনুগ্রহ করলেন শান্তিপূর্ণ পরিতৃপ্তি দিয়ে,  এবং তাদের পরিচালিত করলেন সৎকর্মশীলতার কথা মেনে চলার দিকে । এটা তা-ই যার জন্য তারা যথাযোগ্য ছিল। ঈশ্বর সবকিছু সম্পর্কে পূর্ণ সচেতন।"],
  "48:27": ["Allah has made the Rasul's vision come true in truth: you will surely enter the sacred mosque, if Allah wills, secure, shaving your heads and cutting your hair short, without fear. Allah knew what you did not know, and appointed, besides that, a near triumph", "ঈশ্বর তাঁর বার্তাবাহকের সত্যনিষ্ঠ দূরদৃষ্টি পূর্ণ করেছেন : তোমরা পবিত্র মসজিদে প্রবেশ করবে, ঈশ্বর চাইলে, পুরোপুরি নিরাপদে, এবং  সেখানে তোমরা তোমাদের  চুল কাটবে অথবা ছোট করবে (তীর্থযাত্রার আচারানুষ্ঠানগুলো সম্পন্ন করার জন্য) । তোমাদের কোন ভয় থাকবে না। যেহেতু তিনি জানতেন  যা তোমরা জানতে না, তিনি এটিকে এক আসন্ন বিজয় দিয়ে জুড়ে দিয়েছেন।"],
  "48:28": ["Allah is the One who sent Allah's Rasul with the guidance and the religion of truth, to make it appear over all religion — and Allah is sufficient as a witness", "তিনিই সে সত্ত্বা যিনি তাঁর বার্তাবাহককে পথ-নির্দেশনা এবং সত্যের ধর্ম  দিয়ে পাঠিয়েছেন, অন্য সকল ধর্মের উপর একে জয়ী করতে। সাক্ষী হিসেবে আল্লাহই যথেষ্ট ।"],
  "48:29": ["Muhammad is the Rasul of Allah, and those with him are hard against the unmuminin, merciful among themselves. You see them bowing, prostrating, seeking bounty from Allah and Allah's pleasure. Their mark is on their faces, from the trace of prostration. That is their likeness in the Torah, and their likeness in the Gospel: like a crop that sends out its shoot, then strengthens it, then grows hard, then stands straight on its stalk, so that the growers marvel — so that Allah may enrage the unmuminin with them. Allah has promised those of them who believe and do salih deeds forgiveness and a tremendous reward", "মোহাম্মদ- ঈশ্বরের বার্তাবাহক- আর তার সাথে যারা আছে তারা অবিশ্বাসীদের বিরুদ্ধে কঠোর  ও অনমনীয় , কিন্তু নিজেদের মধ্যে দয়ালু ও সহানুভূতিশীল। তুমি তাদের দেখবে অবনত হয় ও সিজদা করে, যেহেতু তারা ঈশ্বরের অনুগ্রহ ও সমর্থন অন্বেষণ করে। তাদের চিহ্নসমূহ রয়েছে তাদের মুখমণ্ডলে, সিজদা করার কারণে । এই একই উদাহরণ আছে তাওরাতে। ইঞ্জিলে তাদের উদাহরণ চারাগাছের মত যা বৃদ্ধি পেয়ে লম্বা ও মজবুত হয়, আর কৃষকদের পরিতৃপ্ত করে। তিনি এভাবে অবিশ্বাসীদের ক্রোধান্বিত করে। ঈশ্বর তাদের মধ্যে যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে তাদেরকে ক্ষমা ও এক মহা প্রতিদানের প্রতিশ্রুতি দেন।"],
  "49:1": ["O you who believe, do not go ahead of Allah and Allah's Rasul, and be mindful of Allah. Allah hears and knows.", "হে তোমরা যারা বিশ্বাস করো, আল্লাহ এবং তাঁর বার্তাবাহকের উপর তোমাদের মতকে স্থান দিবে না।  তোমরা আল্লাহকে ভক্তি করবে। আল্লাহ শ্রবণকারী, সর্বজ্ঞ।"],
  "49:2": ["O you who believe, do not raise your voices above the voice of the Nabi, and do not speak loudly to him as some of you speak loudly to one another, lest your deeds be voided while you perceive nothing.", "হে তোমরা যারা বিশ্বাস করো, তোমাদের কন্ঠকে নবীর কন্ঠের চেয়ে উঁচু করবে না, না তোমরা তার প্রতি চিৎকার-চেচাঁমেচি করবে যেমন তোমরা একে-অন্যের সাথে  চিৎকার-চেচাঁমেচি করো, পাছে তোমাদের কাজগুলো অকার্যকর হয়ে পড়ে যখন তোমরা খেয়াল করো না।"],
  "49:3": ["Those who lower their voices in the presence of Allah's Rasul are the ones whose hearts Allah has tested for mindfulness. Theirs is forgiveness and a great reward.", "নিশ্চয়, যারা তাদের কন্ঠকে আল্লাহর বার্তাবাহকের সামনে নিচু করে তারা সে ব্যক্তি যাদের হৃদয় আল্লাহর দ্বারা সৎকর্মশীল হয়ে উঠতে প্রস্তুত করা হয়। তারা ক্ষমা ও এক মহা প্রতিদানের অর্জন করেছে।"],
  "49:4": ["Those who call out to you from behind the chambers — most of them do not reason.", "যারা দেয়ালের বাহির থেকে তোমাকে ডাকে, তাদের অধিকাংশ বুঝে না।"],
  "49:5": ["If only they had waited sabirly until you came out to them, it would have been better for them. Allah is forgiving, merciful.", "যদি তারা ধৈর্য ধারণ করতো তুমি বের হয়ে তাদের কাছে না আসা পর্যন্ত, এটি তাদের জন্য উত্তম হতো। আল্লাহ ক্ষমাকারী, সবচেয়ে দয়ালু।"],
  "49:6": ["O you who believe, if a defiant person comes to you with a report, verify it, so that you do not strike a people out of ignorance and end up regretting what you did.", "হে তোমরা যারা বিশ্বাস করো, যদি কোন অন্যায়কারী লোক তোমাদের কাছে কোন সংবাদ নিয়ে আসে, তোমরা প্রথমে অনুসন্ধান করবে, পাছে তোমরা, অজ্ঞতাবশত, কিছু লোকের প্রতি অন্যায় করে বসো,এরপর যা তোমরা করেছো তার জন্য দুখি:ত ও অনুতপ্ত হও।"],
  "49:7": ["Know that among you is Allah's Rasul. If he obeyed you in much of the matter, you would fall into hardship. But Allah has made faith dear to you and adorned it in your hearts, and made unbelief, defiance, and disobedience hateful to you. Those are the ones on the right course.", "এবং  জানো যে তোমাদের মাঝে আল্লাহর বার্তাবাহক এসেছেন। সে যদি তোমাদের অনেক কিছুতে কান দিতো, তোমরা তোমাদের জন্য বিষয়গুলো কঠিন করে ফেলতে। কিন্তু আল্লাহ তোমাদেরকে শিখিয়েছেন বিশ্বাসকে ভালবাসতে,  এবং একে তোমাদের হৃদয়ে সুশোভিত করেছেন; এবং তিনি তোমাদের তৈরি করেছেন অবিশ্বাস, অন্যায়, আর অবাধ্যতার প্রতি ঘৃনা দিয়ে। এরাই পথপ্রাপ্ত ব্যক্তি।"],
  "49:8": ["A bounty from Allah and a blessing; Allah is knowing, wise.", "এমনই আল্লাহর পক্ষ থেকে দয়া এবং  তাঁর অনুগ্রহ। আল্লাহ সর্বজ্ঞ, সবচেয়ে প্রজ্ঞাবান।"],
  "49:9": ["If two parties of muminin fight each other, make peace between them. If one of them aggresses against the other, then fight the one that aggresses until it turns back to the command of Allah. And if it turns back, make peace between them with justice and act equitably. Allah loves the equitable.", "যদি বিশ্বাসীদের দুই দল একে অন্যের সাথে যুদ্ধ করে থাকে, তোমরা তাদের পূন:র্মিলিত করবে। যদি একদল অন্যটির উপর আগ্রাসী হয়, তোমরা আগ্রাসী দলটির সাথে লড়াই করবে যতক্ষণ না তারা আল্লাহর আদেশের কাছে সমর্পণ করে।  একবার যখন তারা সমর্পণ করে, তোমরা ন্যায়সংগতভাবে দল দু'টিকে পূন:র্মিলিত করবে।  তোমরা ন্যায়পরায়ণতা বজায় রাখবে; আল্লাহ তাদেরকে ভালবাসেন যারা ন্যায়পরায়ণ।"],
  "49:10": ["The muminin are but brothers, so make peace between your two brothers, and be mindful of Allah, so that you may be shown mercy.", "বিশ্বাসীরা একটি পরিবারের সদস্য; তোমরা তোমাদের পরিবারে শান্তি বজায় রাখবে এবং আল্লাহকে ভক্তি-শ্রদ্ধা করো, যাতে তোমরা দয়া অর্জন করতে পারো।"],
  "49:11": ["O you who believe, let no people mock a people — they may be better than them — and let no nisa mock nisa — they may be better than them. Do not belittle one another, and do not call one another by nicknames. Wretched is the name of defiance after faith. Whoever does not repent — those are the wrongdoers.", "হে তোমরা যারা বিশ্বাস করো,  কোন লোক অন্য লোককে নিয়ে উপহাস করবে না, কারণ তারা তাদের চেয়ে উত্তম হতে পারে। না কোন নারী অন্য নারীকে নিয়ে উপহাস করবে,কারণ তারা তাদের চেয়ে উত্তম হতে পারে। না তোমরা একে অন্যকে নিয়ে হাসাহাসি  করবে, অথবা তোমাদের নাম নিয়ে মজা করবে। বিশ্বাস অর্জনের পর অনৈতিকতায় ফিরে যাওয়া অবশ্যই মন্দ। যেকেউ এর পরে অনুশোচনা করে না, এরাই সীমালঙ্ঘনকারী।"],
  "49:12": ["O you who believe, avoid much suspicion, for some suspicion is sin. Do not spy, and let none of you backbite another. Would any of you like to eat the flesh of his dead brother? You would loathe it. Be mindful of Allah. Allah is ever-accepting of repentance, merciful.", "হে তোমরা যারা বিশ্বাস করো, তোমরা কোন প্রকার সন্দেহ করা এড়িয়ে চলবে, এমনকি সামান্যতম সন্দেহ করাও পাপ। তোমরা একে অন্যকে নিয়ে গোয়েন্দাগিরি করবে না, না তোমরা একে অন্যকে নিয়ে গীবত করবে; এটা তেমন ঘৃন্যকর যেমন তোমাদের মৃত ভাইয়ের মাংস খাওয়া। তোমরা নিশ্চয় একে ঘৃনা করো। তোমরা আল্লাহকে মান্য করবে। আল্লাহ উদ্ধারকারী, সবচেয়ে দয়ালু।"],
  "49:13": ["O people, We created you from a male and a female, and made you into peoples and tribes so that you may know one another. The most honored of you with Allah is the most mindful of Allah among you. Allah is knowing, aware.", "হে মানুষ, আমরা তোমাদের একই নর এবং নারী থেকে সৃষ্টি করেছি, আর তোমাদেরকে করেছি স্বতন্ত্র মানুষ এবং গোত্র, যাতে তোমরা একে অন্যকে চিনতে পারো।  আল্লাহর দৃষ্টিতে তোমাদের মধ্যে সর্বোত্তম হচ্ছে যে সবচেয়ে বেশি সৎকর্মশীল।"],
  "49:14": ["The desert Arabs said: \"We believe.\" Say: \"You do not believe; rather say: we have submitted.\" For faith has not yet entered your hearts. But if you obey Allah and Allah's Rasul, nothing will be detracted from your deeds. Allah is forgiving, merciful.", "আরবরা বলেছিল, \"আমরা মুমিন (বিশ্বাসী)।\" বল, \"তোমরা বিশ্বাসী হওনি; তোমাদের বলা উচিত ছিল, 'আমরা মুসলিম (আত্মসমর্পণকারী), যতক্ষন না বিশ্বাস তোমাদের হৃদয়ে স্থাপিত হয়।\" যদি তোমরা আল্লাহ এবং তাঁর বার্তাবাহককে মান্য করো, তিনি তোমাদের কোন কাজকে  বিফলে দিবেন না। আল্লাহ ক্ষমাকারী, সবচেয়ে দয়ালু।"],
  "49:15": ["The muminin are only those who believe in Allah and Allah's Rasul, then do not doubt, and strive with their wealth and their lives in the way of Allah. Those are the sadiqin.", "তারাই মুমিন (বিশ্বাসী) যারা আল্লাহ এবং তাঁর বার্তাবাহককে বিশ্বাস করে, তারপর কোনরূপ সন্দেহ না থাকার মর্যাদা অর্জন করে, আর তাদের অর্থ এবং জীবন দিয়ে আল্লাহর উদ্দেশ্যে সংগ্রাম করে। এরাই সত্যবাদী ব্যক্তি।"],
  "49:16": ["Say: \"Do you make Allah know your religion, when Allah knows what is in the heavens and what is in the earth? Allah knows everything.\"", "বল, \"তোমরা কি আল্লাহকে তোমাদের ধর্ম সম্পর্কে জানাচ্ছো? আল্লাহ আকাশমন্ডলী এবং পৃথিবীর সবকিছু জানেন। আল্লাহ সর্বজ্ঞ।\""],
  "49:17": ["They hold it as a favor over you that they submitted. Say: \"Do not hold your submission up as a favor. Rather, Allah holds it as a favor over you that Allah guided you to faith, if you are sadiq.\"", "তারা এমন আচরণ করে যেন আত্মসমর্পণ আলিঙ্গন করে তারা তোমাকে অনুগ্রহ করছে! বল, \"তোমরা আত্মসমর্পণ আলিঙ্গন করে আমাকে কোনভাবে অনুগ্রহ করছো না। আল্লাহই সে সত্ত্বা যিনি তোমাদেরকে বিশ্বাসে পথ দেখানোর মাধ্যমে তোমাদের প্রতি বিশাল অনুগ্রহ করছেন, যদি তোমরা আন্তরিক হও।\""],
  "49:18": ["Allah knows the unseen of the heavens and the earth, and Allah sees all that you do.", "আল্লাহ আকাশমন্ডলী এবং পৃথিবীর সকল গোপনীয়তা জানেন; আল্লাহ তোমাদের করা সবকিছুর দ্রষ্টা।"],
  "50:1": ["Qaf. By the Qur'an, the glorious.", "ক. (ক্বাফ) এবং মহিমান্বিত কুরআন।"],
  "50:2": ["No, they marvel that a warner from among them has come to them; the kafirin said, \"This is a marvellous thing.\"", "তাদের মধ্য থেকে তাদের কাছে একজন সতর্ককারী আসাটা তাদের কাছে অদ্ভুত লেগেছিল! অবিশ্বাসীরা বলল, “এটা আসলেই অদ্ভুত।"],
  "50:3": ["\"When we have died and become dust? That is a far return.\"", "“আমরা মরে গিয়ে ধুলো হয়ে যাবার পর, তা অসম্ভব।”"],
  "50:4": ["We know what the earth diminishes of them, and with Us is a guarded record.", "তাদের মধ্যে কে মাটির সাথে মিশে যায় সে সম্পর্কে আমরা সম্পূর্ণ অবগত; আমাদের কাছে আছে নির্ভুল নথি ।"],
  "50:5": ["No, they denied the truth when it came to them, so they are in a mixed-up affair.", "তারা সত্য প্রত্যাখ্যান করেছিল যখন তা তাদের কাছে এসেছিল; তারা পুরোপুরি সন্দিহান।"],
  "50:6": ["Have they not looked at the sky above them — how We built it and adorned it, and it has no openings?", "তারা কি তাদের উপর আকাশের দিকে তাকায়নি, আর কেমন করেই বা একে আমরা নির্মাণ করলাম এবং একে সুসজ্জিত করলাম, কোন ত্রুটি ছাড়া?"],
  "50:7": ["And the earth, We spread it out and cast into it anchors, and We grew in it of every kind, splendid.", "এবং আমরা সৃষ্টি করলাম পৃথিবী, আর এর উপর ছড়িয়ে দিলাম পর্বতসমূহ, আর এতে ফলিয়েছি  সকল প্রকার সুন্দর উদ্ভিদ।"],
  "50:8": ["An insight and a reminder for every returning servant.", "এটি একটি জ্ঞানালোক, এবং একটি স্মারক প্রত্যেক সৎকর্মশীল উপাসনাকারীর জন্য।"],
  "50:9": ["And We sent down from the sky water blessed, and We grew with it gardens and grain of the harvest.", "এবং আমরা আকাশ থেকে অনুগ্রহপূর্ণ পানি পাঠালাম, এটি দিয়ে বাগান বিকশিত করতে ও শস্য ফলাতে।"],
  "50:10": ["And palms towering, with spathes in clusters.", "লম্বা খেজুর গাছ, গুচ্ছবদ্ধ ফল সহ।"],
  "50:11": ["A provision for the servants; and We revived with it a dead town. Likewise is the coming-forth.", "লোকদের জন্য রিজিক। এবং আমরা এর দ্বারা মৃত ভূমিকে পুনরুজ্জীবিত করি; তোমাদেরকে একই ভাবে পুনরুত্থিত করা হয়।"],
  "50:12": ["Before them the people of Nuh denied, and the companions of ar-Rass, and Thamud,", "তাদের পূর্বে অবিশ্বাসী ছিল নূহের লোকেরা, রাসের অধিবাসীরা, ও সামুদ।"],
  "50:13": ["and Aad, and Fir'awn, and the brethren of Lut,", "এবং আদ, ফেরাউন, ও লুত-ভ্রাতৃবৃন্দ।"],
  "50:14": ["and the companions of the Thicket, and the people of Tubba'. Each denied the Rasuls, so the warning came true.", "এবং বনের অধিবাসী, ও তুবার লোকেরা। তাদের সকলেই বার্তাবাহকদের অবিশ্বাস করেছিল আর, পরিণামে, আমার শাস্তি তাদের উপর পড়েছিল।"],
  "50:15": ["Were We worn out by the first creation? No, they are in doubt about a new creation.", "আমরা কি প্রথম সৃষ্টি দ্বারা অত্যধিক ভারগ্রস্ত হয়ে গেলাম? এ কারনে-ই কি তারা পুনরুত্থান নিয়ে সন্দেহ করে?"],
  "50:16": ["And We created the human, and We know what his soul whispers to him, and We are nearer to him than the rope of the vein.", "আমরা মানুষ সৃষ্টি করলাম, আর আমরা জানি সে নিজের কাছে চুপি চুপি কি বলে। আমরা তার গ্রীবাস্থিত শিরার চেয়েও অধিকতর নিকটবর্তী।"],
  "50:17": ["When the two receivers receive, on the right and on the left, seated.", "দু'জন লিপিবদ্ধকারী (ফেরেশতা), ডানে ও বায়ে, অনবরত লিপিবদ্ধ করছে।"],
  "50:18": ["Not a word is uttered but with him is a watcher, ready.", "সতর্ক সাক্ষ্য ব্যতিত কোন কিছু সে বলে না।"],
  "50:19": ["And the stupor of death comes with the truth. That is what you used to turn away from.", "পরিশেষে, মৃত্যুর সে অনিবার্য অচেতনাবস্থা আসে; ঠিক যেটা তুমি এড়াতে চেয়েছিলে।"],
  "50:20": ["And the trumpet is blown. That is the Day of the Warning.", "শিঙ্গায় ফুঁ দেয়া হয়; এটি সেই প্রতিশ্রুত দিন।"],
  "50:21": ["And every soul comes, with it a driver and a witness.", "প্রত্যেক আত্মা একজন পরিচালনাকারী ও একজন সাক্ষী সহ আসে।"],
  "50:22": ["You were indeed unmindful of this, so We uncovered your covering from you, and your sight today is sharp.", "তুমি এর প্রতি উদাসীন থাকতে। আমরা এখন তোমার মুখাবরণ সরিয়ে দেই; আজ, তোমার দৃষ্টি ইস্পাত (এর মতো দৃঢ়)।"],
  "50:23": ["And its companion says, \"This is what is ready with me.\"", "সঙ্গী বলল, “এই যে আমার জোরালো সাক্ষ্য।”"],
  "50:24": ["Cast into Jahannam every stubborn denier,", "জাহান্নামে নিক্ষেপ করো প্রত্যেক একগুঁয়ে অবিশ্বাসীকে।"],
  "50:25": ["withholder of good, transgressor, doubter,", "দান করতে নিষেধকারী, আগ্রাসক, সন্দেহে পূর্ণ।"],
  "50:26": ["who set up with Allah another ilah — so cast him into the severe punishment.\"", "সে ঈশ্বরের পাশে স্থাপন করে অন্য উপাস্য। তাকে নিক্ষেপ করো কঠিন শাস্তিতে।"],
  "50:27": ["His companion says, \"Our Rabb, I did not make him transgress, but he was in far error.\"", "তার সঙ্গী বলল, “আমাদের প্রভু, আমি তাকে পথভ্রষ্ট করিনি; সে ছিল বহুদূর পথভ্রষ্ট।”"],
  "50:28": ["It is said, \"Do not contend in My presence, for I already brought you the warning.", "তিনি বললেন, ‘আমার সামনে বিবাদ করো না; আমি তোমাদেরকে যথেষ্ট সতর্ক করেছি।"],
  "50:29": ["The word is not changed with Me, and I am not unjust to the servants.\"", "“এখন আর কিছুই পরিবর্তিত হতে পারে না। আমি লোকদের প্রতি কখনই অবিচারক নই।”"],
  "50:30": ["The Day We say to Jahannam, \"Are you filled?\" and it says, \"Is there more?\"", "এটা-ই সে দিন যখন আমরা নরককে জিজ্ঞেস করবো, “তোমার কি যথেষ্ট আছে?” এটি বলবে, “আমাকে আরো দাও।”"],
  "50:31": ["And the Garden is brought near to the mindful, not far.", "সৎকর্মশীলদের স্বর্গ প্রদান করা হবে, অনায়াসে।"],
  "50:32": ["\"This is what you were promised, for every returning watcher,", "এটা তা-ই যা প্রত্যেক অনুশোচনাকারী, অবিচল ব্যক্তিকে অঙ্গীকার করা হয়েছিল।"],
  "50:33": ["who revered the Rahman in the unseen and came with a returning heart.", "তারা তাদের একান্তে পরম করুনাময়কে ভক্তি করেছিল, আর এসেছে পূর্ণহৃদয় নিয়ে।"],
  "50:34": ["Enter it in peace. That is the Day of Eternity.", "এতে প্রবেশ করো শান্তিতে; এটি চিরস্থায়িত্বের দিন।"],
  "50:35": ["They have therein what they wish, and with Us is more.\"", "তারা সেখানে যা চায় তা-ই পায়, এবং আমাদের কাছে এমনকি আরও বেশি আছে।"],
  "50:36": ["And how many generations We destroyed before them who were harder than them in might; they tunnelled through the land — is there any escape?", "তাদের পূর্বে অনেক প্রজন্ম, যারা অধিক শক্তিশালী ছিল, আমরা তাদের ধ্বংস করেছিলাম। তারা জমিনে খুঁজে বেরিয়েছিল, তারা কি পালানোর কোন পথ পেয়েছিল?"],
  "50:37": ["Indeed in that is a reminder for one who has a heart, or who lends an ear while witnessing.", "তাদের প্রত্যেকের জন্য এটি শিক্ষা হওয়া উচিত, যাদের একটি মন আছে, অথবা শুনতে ও প্রত্যক্ষ করতে সক্ষম।"],
  "50:38": ["And We created the heavens and the earth and what is between them in six days, and no weariness touched Us.", "আমরা আকাশমণ্ডলী ও পৃথিবী এবং এদের মধ্যকার সবকিছু ছয় দিনে সৃষ্টি করেছি, এবং কোন ক্লান্তি আমাদের স্পর্শ করেনি।"],
  "50:39": ["So be of the sabirin over what they say, and glorify with the praise of your Rabb before the rising of the sun and before the setting,", "অতএব, তাদের কথায় ধৈর্যশীল হও, এবং সূর্যোদয়ের পূর্বে ও সূর্যাস্তের পূর্বে তোমার প্রভুর প্রশংসা ও মহিমা ঘোষণা করো।"],
  "50:40": ["and in the night glorify Allah, and after the prostration.", "তুমি তাঁর নাম নিয়ে ধ্যান করো রাতে, এবং সেজদার পর।"],
  "50:41": ["And listen for the Day the Caller calls from a near place.", "সেদিনের জন্য প্রস্তুত হও যখন আহবানকারী আহবান করে এক স্থান থেকে যা নিকটবর্তী।"],
  "50:42": ["The Day they hear the shout in truth — that is the Day of the Coming-Out.", "যখন তারা সে অবশ্যম্ভাবী কান্না শোনে; ঐ দিন-ই তোমরা বেরিয়ে আসো।"],
  "50:43": ["Indeed it is We who give life and cause death, and to Us is the arrival.", "আমরা সেই সত্তা যারা জীবন ও মৃত্যু নিয়ন্ত্রণ করি; আমাদের কাছে রয়েছে সে চুড়ান্ত নিয়তি।"],
  "50:44": ["The Day the earth splits from them swiftly — that is a gathering easy for Us.", "সেদিন আসবে যখন পৃথিবী তাড়াহুড়ায় ফেটে যাবে, যা তাদের জাগিয়ে দিবে। এমন আহবান আমাদের জন্য সহজ।"],
  "50:45": ["We know best what they say, and you are not an overpowerer over them. So remind, by the Qur'an, whoever fears the warning.", "তারা যা কিছু বলে সে সম্পর্কে আমরা পূর্ণ অবগত, যখন তাদের উপর তোমার কোন ক্ষমতা নেই। অতএব, তাদেরকে এই কুরআন দিয়ে স্মরণ করিয়ে দাও যারা আমার সতর্ক-বার্তাকে ভক্তি করে।"],
  "51:1": ["By the scatterers scattering,", "প্রবাহমান বাতাস।"],
  "51:2": ["and the bearers of a heavy load,", "বহন করে বৃষ্টি।"],
  "51:3": ["and the runners running with ease,", "নিয়ে আসে রিজিক।"],
  "51:4": ["and the apportioners of the affair —", "বিতরণ করে এগুলোকে আদেশ অনুযায়ী।"],
  "51:5": ["that which you are promised is true,", "যা তোমাদের কাছে অঙ্গীকার করা হয় তা অবশ্যই ঘটবে।"],
  "51:6": ["and the Reckoning will surely befall.", "বিচারের দিন অনিবার্য।"],
  "51:7": ["By the sky with its woven courses,", "নিখুঁতভাবে সৃষ্ট আকাশ থাকা সত্ত্বেও।"],
  "51:8": ["you are in discordant speech,", "সত্যকে তোমরা বিতর্কিত করে যাচ্ছো।"],
  "51:9": ["turned away from it, whoever turns away.", "এ থেকে বিচ্যুত করে বিচ্যুতকারীরা।"],
  "51:10": ["Doom to the conjecturers,", "দূর্ভোগ মিথ্যাপন্থিদের।"],
  "51:11": ["those who are in a fog, unheeding.", "তাদের ভুলের বিষয়ে, তারা সম্পূর্ণ অমনোযোগী।"],
  "51:12": ["They ask: \"When is the Day of Reckoning?\"", "তারা বিচারের দিনকে প্রশ্নবিদ্ধ করে।"],
  "51:13": ["The Day they are burned upon the Fire:", "সেদিন তাদেরকে আগুনের সামনে হাজির করা হয়।"],
  "51:14": ["\"Taste your trial — this is what you used to hasten.\"", "আস্বাদন করো শাস্তি; একেই তোমরা চ্যালেঞ্জ করতে।"],
  "51:15": ["Indeed, the vigilant are in gardens and springs,", "সৎকর্মশীলরা বাগান ও ঝর্ণাগুলো অর্জন করেছে।"],
  "51:16": ["taking what their Rabb gave them; they were before that doers of good.", "তারা তাদের প্রভুর পুরস্কার পায়, কারন তারা সৎকর্মশীল ছিল।"],
  "51:17": ["Little of the night would they sleep,", "কদাচিৎ তারা সম্পূর্ণ রাত ঘুমাতো।"],
  "51:18": ["and in the small hours they would seek forgiveness.", "রাতের শেষ প্রহরে, তারা ক্ষমা প্রাপ্তির জন্য প্রার্থনা করতো।"],
  "51:19": ["And in their wealth is a due for the asker and the deprived.", "তাদের অর্থের একটি অংশ আলাদা থাকতো ভিক্ষুক ও অভাবগ্রস্তদের জন্য।"],
  "51:20": ["And in the earth are signs for those of certainty —", "যারা নিশ্চিত, তাদের জন্য ভরপুর নিদর্শন আছে পৃথিবীতে।"],
  "51:21": ["and in yourselves; will you not see?", "আর তোমাদের নিজেদের মধ্যে; তোমরা কি দেখতে পাও?"],
  "51:22": ["And in the sky is your provision and what you are promised.", "আকাশে আছে তোমাদের জীবিকা, এবং সবকিছু যার প্রতিশ্রুতি তোমাদেরকে দেয়া হয়।"],
  "51:23": ["So by the Rabb of the sky and the earth, it is surely true, just as you speak.", "আকাশ ও পৃথিবীর প্রভুর শপথ, এটি তোমাদের কথা বলার মতোই বাস্তব সত্য।"],
  "51:24": ["Has the account of the honored guests of Ibrahim reached you?", "তুমি কি ইব্রাহিমের সন্মানিত অতিথিদের ইতিহাস লক্ষ্য করেছ?"],
  "51:25": ["When they entered upon him and said, \"Peace,\" he said: \"Peace — a people unknown to us.\"", "তার সাথে তারা সাক্ষাত করেছিল, আর বলল, “শান্তি।” সে বলল, “তোমাদের প্রতি শান্তি, অপরিচিত লোকেরা!”"],
  "51:26": ["He turned aside to his household and came with a fat calf,", "সে তার পরিবারকে একটি মোটাতাজা বাছুর প্রস্তুত করতে বলল।"],
  "51:27": ["brought it near to them, and said: \"Will you not eat?\"", "যখন সে এটি তাদের খেদমতে রাখল, সে খেয়াল করে বলল, “তোমরা কি খাবে না?”"],
  "51:28": ["Then he sensed fear from them; they said: \"Do not fear,\" and gave him glad tidings of a knowing boy.", "সে তাদের ব্যাপারে মনে মনে ভয় পোষণ করলো। তারা বলল, “ভয় পেয়ো না,” এবং তারা একটি জ্ঞানবান সন্তানের সুসংবাদ দিল।"],
  "51:29": ["Then his imra'a came forward in obstinacy, struck her face, and said: \"An jawza, barren!\"", "তার স্ত্রী অবাক হলো। তার মুখমণ্ডলে কুঞ্চিত ভাব নিয়ে: “আমি এক বৃদ্ধ বন্ধ্যা।\""],
  "51:30": ["They said: \"Thus has your Rabb said — Allah is the Wise, the Knowing.\"", "তারা বলল, “এমনি তোমার প্রভু বলেছেন। তিনি সবথেকে জ্ঞানী, সর্বজ্ঞ।”"],
  "51:31": ["He said: \"So what is your affair, O envoys?\"", "সে বলল, “তোমাদের উদ্দেশ্য কি, হে বার্তাবাহকগণ?”"],
  "51:32": ["They said: \"We have been sent to a guilty people,", "তারা বলল, “আমরা অপরাধী লোকদের প্রতি প্রেরিত হয়েছি?”"],
  "51:33": ["to send upon them stones of clay,", "\"আমরা তাদের উপর কাদামাটির পাথর বর্ষণ করবো।"],
  "51:34": ["marked by your Rabb for the exceeders.\"", "“সীমালঙ্ঘনকারীদের জন্য তোমার প্রভুর দ্বারা চিহ্নিত।”"],
  "51:35": ["Then We brought out whoever of the muminin was in it;", "আমরা এরপর সকল বিশ্বাসীদের উদ্ধার করেছিলাম।"],
  "51:36": ["We found none in it but one house of the submitted.", "আমরা সেখানে একটি ঘরের বেশি আত্মসমর্পণকারী পাইনি।"],
  "51:37": ["And We left in it a sign for those who fear the painful punishment.", "আমরা একে একটি শিক্ষা হিসাবে স্থাপন করেছি তাদের জন্য যারা যন্ত্রণাদায়ক শাস্তিকে ভয় পায়।"],
  "51:38": ["And in Musa — when We sent him to Fir'awn with a clear warrant;", "মুসার জীবনীতে (শিক্ষা রয়েছে)। আমরা তাকে স্পষ্ট নিদর্শনসহ ফেরাউনের কাছে পাঠিয়েছিলাম ।"],
  "51:39": ["then he turned away with his backing and said: \"A sorcerer or a madman.\"", "কিন্তু সে অহংকারে মুখ ফিরিয়ে নিল, এবং বলল, “জাদুকর, অথবা উম্মাদ।”"],
  "51:40": ["So We seized him and his hosts and cast them into the sea, and he was blameworthy.", "ফলস্বরূপ, আমরা তাকে ও তার সৈন্য বাহিনীকে শাস্তি দিলাম। আমরা তাদেরকে সমুদ্রে নিক্ষেপ করলাম, সে-ই ছিল দোষী ব্যাক্তি।"],
  "51:41": ["And in Ad — when We sent upon them the barren wind;", "আদ জাতির মাঝে (শিক্ষা রয়েছে)। আমরা তাদের উপর পাঠিয়েছিলাম  সর্বনাশা বায়ু।"],
  "51:42": ["it left nothing it came upon without making it like decayed rubble.", "এটি যা কিছুর উপর এসেছিল, একে সম্পূর্ণ ধ্বংস করেছিল ।"],
  "51:43": ["And in Thamud — when it was said to them: \"Take enjoyment until a time.\"", "সামুদ জাতির মাঝে (শিক্ষা রয়েছে)। তাদেরকে বলা হয়েছিল, “কিছুকাল উপভোগ করো।"],
  "51:44": ["Then they defied the command of their Rabb, so the thunderstrike seized them as they looked on.", "তারা বিদ্রোহ করেছিল তাদের প্রভুর হুকুমের বিরুদ্ধে। ফলস্বরূপ, বজ্রপাত তাদেরকে আঘাত করেছিল যখন তারা তাকিয়েছিল।"],
  "51:45": ["They could not stand up at all, nor were they the ones given victory.", "তারা কখনই উঠে দাড়াতে পারলো না, না তারা সাহায্য পেল।"],
  "51:46": ["And the people of Nuh before — they were a rebellious people.", "এবং তার পূর্বে নূহের লোকরা; তারা ছিল পাপী লোক।"],
  "51:47": ["And the sky — We built it with strength, and We are the Vast.", "আমরা আকাশকে সৃষ্টি করেছি আমাদের হাত দিয়ে এবং আমরা একে সম্প্রসারিত করতে থাকবো।"],
  "51:48": ["And the earth — We spread it; how excellent are the bed-makers.", "এবং আমরা পৃথিবীকে বানিয়েছি বাসযোগ্য; একটি নিখুঁত নকশা।"],
  "51:49": ["And of everything We created two, that you may remember.", "আমরা সবকিছুর একটি জোড়া (পুরুষ ও নারী) সৃষ্টি করেছি, যাতে তোমরা মনোযোগ দাও।"],
  "51:50": ["So flee to Allah — I am a clear warner to you from Allah.", "তোমরা ঈশ্বরের কাছে পলায়ন করো। আমি তোমাদের নিকট এক স্পষ্ট সতর্ককারী হিসেবে তাঁর দ্বারা প্রেরিত।"],
  "51:51": ["And do not set up with Allah another ilah — I am a clear warner to you from Allah.", "ঈশ্বরের পাশে অন্য কোন উপাস্য স্থাপন করো না। আমি তোমাদের কাছে এক স্পষ্ট সতর্ককারী হিসেবে তাঁর দ্বারা প্রেরিত।"],
  "51:52": ["Likewise, no Rasul came to those before them but they said: \"A sorcerer or a madman.\"", "অনবরত, যখনি কোন বার্তাবাহক পূর্ববর্তী প্রজন্মদের কাছে গিয়েছিল, তারা বলেছিল, “জাদুকর, ” নয়তো “ঊম্মাদ।”"],
  "51:53": ["Did they exhort one another with it? No — they were a transgressing people.", "তারা কি পরস্পর চুক্তি করেছিল? নিশ্চয়, তারা সীমালঙ্ঘনকারী।"],
  "51:54": ["So turn away from them; you are not to be blamed.", "তুমি তাদের উপেক্ষা করতে পারো, তোমাকে দোষারোপ করা হবেনা ।"],
  "51:55": ["And remind — indeed, the reminder benefits the muminin.", "এবং স্মরণ করিয়ে দাও, কারন স্মরণ করানো বিশ্বাসীদের উপকার করে।"],
  "51:56": ["I created jinn and humankind only to serve Allah;", "একমাত্র আমার উপাসনা করার উদ্দেশ্য ছাড়া আমি জিন ও মানুষদের সৃষ্টি করিনি ।"],
  "51:57": ["I want no provision from them, nor do I want them to feed Me.", "তাদের কাছে আমার কোন জীবিকার প্রয়োজন নেই, না আমাকে খাওয়ানোর জন্য তাদেরকে আমার প্রয়োজন আছে।"],
  "51:58": ["Allah is the Provider, the One Firm in strength.", "ঈশ্বর জীবিকাদাতা, সকল শক্তির অধিকারী, সর্বোচ্চ।"],
  "51:59": ["So those who wronged will have a guilt like the guilt of their companions — let them not hasten.", "সীমালঙ্ঘনকারীরা তাদের পূর্ববর্তী অনুরূপদের মতো একই ভাগ্য টেনে এনেছে; তাদের উচিত নয় চ্যালেঞ্জ করা।"],
  "51:60": ["So woe to those who disbelieve, from their Day which they are promised.", "তাদের প্রতি দুঃখ যারা অবিশ্বাস করে সেই দিনকে যা তাদের জন্য অপেক্ষা করছে।"],
  "52:1": ["By the mount", "সিনাই পর্বত।"],
  "52:2": ["and by written lines", "লিপিবদ্ধ সে ঐশীগ্রন্থ।"],
  "52:3": ["on a sheet spread open", "বইপত্র আকারে প্রকাশিত।"],
  "52:4": ["and by the House built and kept", "আবাদকৃত সে তীর্থস্থান।"],
  "52:5": ["and by the roof raised up", "সুউচ্চ সে ছাদ।"],
  "52:6": ["and by the sea set ablaze", "সে সমুদ্র যা প্রজ্বলিত করা হয়।"],
  "52:7": ["truly the punishment of Allah is befalling", "তোমার প্রভুর প্রতিশোধ অনিবার্য।"],
  "52:8": ["nothing can push it back", "মহাবিশ্বের কোন শক্তি একে থামাতে পারে না।"],
  "52:9": ["the day the sky churns in turmoil", "সেদিন আসবে যখন আকাশ প্রচণ্ড বজ্রপাত ঘটাবে।"],
  "52:10": ["and the mountains are set moving", "পর্বতগুলো মুছে ফেলা হবে।"],
  "52:11": ["woe that day to the mukazzibin", "ঐদিন দূর্ভোগ অবিশ্বাসীদের-"],
  "52:12": ["who wade in idle play", "যারা তাদের ভুলের মাঝে, অসতর্ক।"],
  "52:13": ["the day they are called to the fire of Hell with a call", "তাদেরকে একত্রে জাহান্নামের দিকে নিয়ে যাওয়া হবে, বলপূর্বক।"],
  "52:14": ["\"This is the fire you used to deny", "এটা-ই সে আগুন যাতে তোমরা অবিশ্বাস করতে।"],
  "52:15": ["is this magic, or do you not see", "এটা কি জাদু, নাকি তোমরা দেখো না?"],
  "52:16": ["enter it and endure, or do not endure — it is all the same to you; you are only repaid what you used to do", "অগ্নিদহন ভোগ করো। তোমরা ধৈর্য্য ধরো অথবা অধৈর্য্য হও, তা তোমাদের জন্য সমান হবে। তোমরা যা করেছ এটি তার সঠিক প্রতিফল।"],
  "52:17": ["truly the ilah-fearing are in gardens and bliss", "সৎকর্মশীলরা অর্জন করেছে বাগানগুলো ও পরম সুখ।"],
  "52:18": ["delighting in what Allah gave them, and Allah protected them from the punishment of the blaze", "তারা উপভোগ করে যা তাদের প্রভু তাদের জন্য সংরক্ষিত রেখেছেন; তাদের প্রভু তাদেরকে নরকের আগুন থেকে নিষ্কৃতি দিয়েছেন।"],
  "52:19": ["\"Eat and drink in delight for what you used to do", "খুশি মনে খাও ও পান করো, তোমাদের কাজের বিনিময়ে।"],
  "52:20": ["reclining on couches ranged in rows, and We pair them with fair-eyed companions", "তারা বিলাসবহুল আসবাবপত্রে আরাম করে এবং আমরা তাদেরকে সুন্দর সঙ্গী দিয়ে জুড়বো।"],
  "52:21": ["and those who believed, whose offspring followed them in belief — We join their offspring with them, and We will not cheat them of anything of their deeds. Every person is held as a pledge for what he earned", "তাদের জন্য যারা বিশ্বাস করেছিল এবং তাদের সন্তানেরাও বিশ্বাসে তাদের অনুসরণ করেছিল, আমরা তাদের সন্তানদের তাদের সাথে মিলিত করবো। আমরা কখনই কোন কাজের জন্য তাদের পুরস্কার দিতে ব্যর্থ হই না। প্রত্যেক ব্যক্তি যা সে করেছিল তার প্রাপ্য পায়।"],
  "52:22": ["and We supply them with fruit and flesh of whatever they desire", "আমরা তাদেরকে সরবরাহ করবো ফল ও মাংস যা তারা ভালবাসে।"],
  "52:23": ["they pass a cup around among themselves — no idle talk is in it, and no sinning", "তারা উপভোগ করবে পানীয় যেগুলো কখনো দূষিত নয়, আর পান করা কখনো পাপ নয়।"],
  "52:24": ["and their boys move among them as though they were pearls kept hidden", "তাদের সেবায় থাকবে সুরক্ষিত মুক্তার মতো সেবকরা।"],
  "52:25": ["and they turn to one another, asking", "তারা পরস্পরের সাথে সাক্ষাত করবে এবং নিজেদের মধ্যে স্মৃতিচারণ করবে।"],
  "52:26": ["They say: \"Once, among our people, we lived in awe", "তারা বলবে, “আমরা আমাদের লোকদের মধ্যে দয়ালু ও নম্র ছিলাম।"],
  "52:27": ["so Allah favored us and protected us from the punishment of the scorching blast", "“ঈশ্বর আমাদেরকে অনুগ্রহ করেছেন এবং মন্দ বাতাসের নিদারুন যন্ত্রণা থেকে আমাদের নিষ্কৃতি দিয়েছেন।"],
  "52:28": ["we used to call upon Allah before. Truly Allah is the Good, the Raheem", "“আমরা তাঁর কাছে মিনতি করতাম; তিনি পরম দয়ালু, পরম করুনাময়।\""],
  "52:29": ["So remind — for by the favor of Allah you are no soothsayer, nor mad", "তুমি লোকদের স্মরণ করিয়ে দাও। তোমার প্রতি তোমার প্রভুর অনুগ্রহে, না তুমি গণক, না উম্মাদ।"],
  "52:30": ["or do they say: a poet — one for whom we await the turn of death", "তারা বলতে পারে, “সে একজন কবি; চল আমরা শুধু তার মৃত্যু পর্যন্ত অপেক্ষা করি।”"],
  "52:31": ["Say: wait — I am waiting with you", "বল, “যাও অপেক্ষা করো; আমিও তোমাদের সাথে অপেক্ষা করবো।”"],
  "52:32": ["is it their minds that command them this, or are they a transgressing people", "তাদের স্বপ্নই কি তাদের আচরণ নির্দেশ করে নাকি তারা স্বভাবতই মন্দ?"],
  "52:33": ["or do they say: you have simply said it? No, they do not believe", "তারা কি বলে, “সে এর সবই বানিয়েছে?” নাকি, তারা কেবলই অবিশ্বাসী।"],
  "52:34": ["so let them bring a tale like it, if they are sadiq", "তারা এর মতো একটি হাদিস তৈরি করুক, যদি তারা সত্যবাদী হয়।"],
  "52:35": ["were they created without a thing, or are they the creators", "তারা কি শূন্য থেকে সৃষ্টি হয়েছে? তারা কি সৃষ্টিকর্তা?"],
  "52:36": ["or did they create the heavens and the earth? No, they have no certainty", "তারা কি আকাশমণ্ডলী ও পৃথিবী সৃষ্টি করেছিল? প্রকৃতপক্ষে, তারা কোন বিষয়ে নিশ্চিত নয়।"],
  "52:37": ["or do they have the storehouses of Allah, or are they the ones in control", "তাদের কাছে কি তোমার প্রভুর ধনভাণ্ডার আছে? তারা কি নিয়ন্ত্রনে রয়েছে?"],
  "52:38": ["or do they have a ladder by which they listen? Then let their listener bring a clear warrant", "তারা কি এমন সিঁড়ি বেয়ে ওঠে যা তাদের শুনতে সাহায্য করে? তাদের শ্রবণকারীরা তাদের প্রমাণ দেখাক।"],
  "52:39": ["or does Allah have daughters while you have sons", "তাঁর কি কন্যা আছে, যখন তোমাদের আছে পুত্র?"],
  "52:40": ["or do you ask them a reward, so that they are weighed down with liability", "তুমি কি তাদের কাছে কোন পারিশ্রমিক চাচ্ছো, এবং তারা এর দ্বারা ভারগ্রস্থ?"],
  "52:41": ["or do they have the unseen, so they are writing it down", "তারা কি ভবিষ্যৎ জানে, আর তা নথিভুক্ত করেছে?"],
  "52:42": ["or do they intend a scheme? Those who disbelieve — they are the ones schemed against", "তারা কি ষড়যন্ত্রের নকশা করছে? অবিশ্বাসীদের ষড়যন্ত্র তাদের নিজেদের বিরুদ্ধেই উল্টো কাজ করে।"],
  "52:43": ["or do they have a ilah other than Allah? Glorified is Allah above all they associate", "তাদের কি ঈশ্বরের পাশে অন্য উপাস্য আছে? ঈশ্বর পবিত্র, অংশীদার থাকা থেকে অনেক ঊর্ধ্বে।"],
  "52:44": ["and if they see a fragment of the sky falling, they say: piled-up clouds", "যখন তারা আকাশ থেকে বস্তুপিণ্ড পড়তে দেখবে, তারা বলবে, “পুঞ্জিভূত মেঘ!”"],
  "52:45": ["so leave them until they meet their day in which they are struck down", "তাদেরকে উপেক্ষা করো যতক্ষন না তারা সেদিনের সম্মুখীন হয় যাতে তারা আবদ্ধ হয়ে যায়।"],
  "52:46": ["a day when their scheming will avail them nothing, nor will they be helped", "সে দিনে, তাদের চক্রান্ত তাদের রক্ষা করতে পারবে না, না তারা সাহায্যপ্রাপ্ত হবে।"],
  "52:47": ["and there is a punishment besides that for those who did wrong, but most of them do not know", "যারা সীমালঙ্ঘন করে তারা এখানেই শাস্তি ভোগ করে, কিন্তু তাদের অধিকাংশই জানে না।"],
  "52:48": ["so be of the sabirin for the judgment of Allah, for you are in Our sight, and glorify with the praise of Allah when you rise", "তুমি তোমার প্রভুর হুকুম পালনে দৃঢ়ভাবে অধ্যবসায়ী হও- তুমি আমাদের দৃষ্টিতে আছো- এবং তোমাদের প্রভুর পবিত্রতা ঘোষণা করো ও প্রশংসা করো যখন তোমরা উঠো।"],
  "52:49": ["and in the night hours glorify Allah, and at the setting of the stars", "এছাড়া রাতের বেলায় তাঁর পবিত্রতা ঘোষণা করো, এবং উষাতে যখন তারাগুলো মলিন হয়ে যায়।"],
  "53:1": ["By the star when it plunges", "যখন তারকারাজি ঝরে পরে।"],
  "53:2": ["Your companion has not strayed, nor been misled", "তোমাদের বন্ধু (মুহাম্মদ) পথভ্রষ্ট ছিল না, না সে প্রতারিত ছিল।"],
  "53:3": ["Nor does he speak from desire", "না সে মনগড়া কথা বলতো।"],
  "53:4": ["It is nothing but revelation revealed", "এটি ছিল ঐশ্বরিক উদ্দীপনা।"],
  "53:5": ["Taught by one mighty in power", "সবচেয়ে শক্তিশালী দ্বারা নির্দেশিত।"],
  "53:6": ["One of enduring strength, then he poised himself evenly", "সকল কর্তৃত্বের অধিকারী। তাঁর সর্বোচ্চ উচ্চতা থেকে।"],
  "53:7": ["While at the highest horizon", "সর্বোচ্চ দিগন্তটিতে।"],
  "53:8": ["Then he drew near and hung low", "তিনি নিচে নেমে আরও নিকটবর্তী করলেন।"],
  "53:9": ["And was two bow-lengths away, or nearer", "যে পর্যন্ত না তিনি যথাসম্ভব কাছাকাছি হলেন।"],
  "53:10": ["Then Allah revealed to Allah's servant what was revealed", "তিনি এরপর তাঁর বান্দার কাছে প্রকাশ করলেন যা প্রকাশ করার ছিল।"],
  "53:11": ["The heart did not lie about what it saw", "মন কখনোই কল্পনা করেনি যা সে দেখেছিল।"],
  "53:12": ["Will you then doubt what he sees", "যা সে দেখেছিল তাতে কি তোমরা সন্দেহ করছো?"],
  "53:13": ["And certainly he saw it in another descent", "তিনি তাকে দেখেছিলেন অন্য এক অবতরণে।"],
  "53:14": ["At the Lote Tree of the utmost limit", "পরম স্থানটিতে।"],
  "53:15": ["Near it is the Garden of Shelter", "যেখানে চিরস্থায়ী স্বর্গ অবস্থিত।"],
  "53:16": ["When that which covers covered the Lote Tree", "সম্পূর্ণ স্থানটি অভিভূতময় ছিল।"],
  "53:17": ["The eye neither swerved nor transgressed", "চোখগুলো দ্বিধাগ্রস্ত হয়নি, না হয়েছিল অন্ধ।"],
  "53:18": ["He certainly saw some of the greatest signs of his Rabb", "সে তাঁর প্রভুর মহা নিদর্শনাবলি দেখেছিল।"],
  "53:19": ["Have you seen al-Lat and al-Uzza", "একে তুলনা করো উদ্ভাবিত নারী উপাস্য আলা'ত ও আল-উযযাহ- এর সাথে।"],
  "53:20": ["And Manat, the third, the other", "এবং মানা'ত, তৃতীয় জন।"],
  "53:21": ["Is yours the male and Allah the female", "তোমাদের কি পুত্র আছে যখন তাঁর এগুলো আছে কন্যা হিসেবে?"],
  "53:22": ["That indeed would be an unfair division", "কি এক অসন্মানকর বণ্টন!"],
  "53:23": ["They are nothing but names which you and your fathers named; Allah has sent down no warrant for them; they follow only conjecture and what the selves desire, yet guidance has certainly come to them from their Rabb", "এগুলো কেবলই নাম যা তোমরা বানিয়েছ, তোমরা আর তোমাদের পিতৃপুরুষরা। আল্লাহ কখনোই এমন মিথ্যাচারের অনুমোদন দেননি। তারা অনুসরণ করে অনুমানের, এবং ব্যক্তিগত ইচ্ছার, যখন এখানে তাদের প্রভুর পক্ষ থেকে সত্য পথনির্দেশনা এসেছে।"],
  "53:24": ["Or shall the human have whatever the self wishes", "মানুষ আসলে কি চায়?"],
  "53:25": ["To Allah belong the Last and the First", "পরকাল ও এই দুনিয়া উভয়ই ঈশ্বরের অধীনে।"],
  "53:26": ["And how many malakat are in the heavens whose intercession avails nothing, except after Allah gives permission for whomever Allah wills and is pleased with", "এমনকি স্বর্গের ফেরেশতাদেরও সুপারিশ করার অধিকার নেই। কেবল সে লোকেরাই ঈশ্বর দ্বারা অনুমোদিত যারা তাঁর ইচ্ছা ও তাঁর অনুমোদন অনুসারে কাজ করে।"],
  "53:27": ["Indeed those who do not believe in the Last name the malakat with the naming of the female", "পরকালে যারা অবিশ্বাস করে তারা ফেরেশতাদের নারীবাচক নাম দিয়েছে।"],
  "53:28": ["And they have no knowledge of it; they follow only conjecture, and conjecture avails nothing against the truth", "এ বিষয়ে তাদের কোন জ্ঞান ছিল না; তারা কেবল অনুমান করেছিল। অনুমান সত্যের কোন বিকল্প নয়।"],
  "53:29": ["So turn away from whoever turns away from Allah's reminder and wants only the nearer life", "তুমি তাদেরকে উপেক্ষা করো যারা আমাদের বার্তা থেকে মুখ ফিরিয়ে নেয় এবং দুনিয়ার এই জীবন নিয়ে মোহাচ্ছন্ন হয়ে থাকে।"],
  "53:30": ["That is the utmost of their knowledge; indeed your Rabb knows best who strays from Allah's way, and your Rabb knows best who is guided", "এটা তাদের জ্ঞানের সীমা। তোমার প্রভু তাদের বিষয়ে সম্পূর্ণ অবগত যারা তাঁর পথ থেকে পথভ্রষ্ট হয়েছে, এবং তিনি তাদের বিষয়ে সম্পূর্ণ অবগত যারা সুপথপ্রাপ্ত।"],
  "53:31": ["And to Allah belongs whatever is in the heavens and whatever is in the earth, so that Allah may recompense those who do evil for what they did, and recompense those who do good with the best", "আকাশমণ্ডলীর সবকিছু ও পৃথিবীর সবকিছু ঈশ্বরের। যারা মন্দ কাজ করে তিনি তাদের প্রতিফল দেবেন আর সৎকর্মশীলদের পুরস্কৃত করবেন তাদের সৎকর্মশীলতার জন্য।"],
  "53:32": ["Those who avoid the great sins and the obscenitys, except for small faults; indeed your Rabb is abundant in forgiveness, knowing you best when you were raised up from the earth and when you were embryos in the bellies of your mothers; so do not claim purity for yourselves; your Rabb knows best who guards", "তারা স্পষ্ট পাপ ও সীমালঙ্ঘন এড়িয়ে চলে, ছোটখাটো অপরাধসমূহ ব্যতীত। তোমার প্রভুর ক্ষমাশীলতা বিশাল। তখন থেকেই তিনি তোমাদের সম্পর্কে পূর্ণ অবগত যখন পৃথিবী থেকে তিনি তোমাদের সূচনা করেছিলেন , আর যখন তোমরা তোমাদের মায়ের পেটে ভ্রুন ছিলে। সুতরাং, নিজেকে নিয়ে বড়াই করো না; তিনি সৎকর্মশীলদের ব্যাপারে পূর্ণ অবগত।"],
  "53:33": ["Have you seen the one who turned away", "তুমি কি সে ব্যক্তির দিকে খেয়াল করেছ যে মুখ ফিরিয়ে নিয়েছিল?"],
  "53:34": ["And gave a little, then held back", "কদাচিৎ সে দান করতো আর তা-ও খুব সামান্য।"],
  "53:35": ["Does he have knowledge of the unseen, so he sees", "তার কি ভবিষ্যত জ্ঞান ছিল? সে কি তা দেখতে পারতো?"],
  "53:36": ["Or was he not told of what is in the written sheets of Musa", "সে কি অবগত ছিল না মুসার ঐশীগ্রন্থের শিক্ষার বিষয়ে?"],
  "53:37": ["And Ibrahim who fulfilled", "আর ইব্রাহিমের যে পূর্ণ করেছিল?"],
  "53:38": ["That no bearer of a load bears the load of another", "কোন আত্মা অন্য আত্মার পাপ বহন করে না।"],
  "53:39": ["And that the human shall have nothing but what the self strives for", "প্রত্যেক মানুষ তার নিজের কাজের জন্য দায়ী।"],
  "53:40": ["And that the striving shall soon be seen", "এবং প্রত্যেকের কাজগুলো দেখানো হবে।"],
  "53:41": ["Then the fullest recompense is given", "এরপর তাদের এসব কাজের জন্য পূর্ণ প্রাপ্য দেয়া হবে।"],
  "53:42": ["And that to your Rabb is the ultimate end", "তোমার প্রভুর দিকেই চূড়ান্ত নিয়তি।"],
  "53:43": ["And that Allah is the one who makes laugh and makes weep", "তিনিই সে সত্ত্বা যিনি তোমাদের হাসান ও কাঁদান।"],
  "53:44": ["And that Allah is the one who gives death and gives life", "তিনিই সে সত্ত্বা যিনি মৃত্যু ও জীবন নিয়ন্ত্রণ করেন।"],
  "53:45": ["And that Allah created the two kinds, the male and the female", "তিনিই সে সত্ত্বা যিনি সৃষ্টি করেছেন দুই প্রকার, পুরুষ ও নারী-"],
  "53:46": ["From a drop when it is emitted", "এক অতি ক্ষুদ্র বীর্যের ফোঁটা থেকে।"],
  "53:47": ["And that upon Allah is the second raising", "তিনি পুনঃসৃষ্টি ঘটাবেন।"],
  "53:48": ["And that Allah is the one who enriches and grants sufficiency", "তিনিই সে সত্ত্বা যিনি তোমাদের ধনী অথবা দরিদ্র করেন।"],
  "53:49": ["And that Allah is the Rabb of Sirius", "তিনি নক্ষত্রপুঞ্জের প্রভু।"],
  "53:50": ["And that Allah destroyed the first Ad", "তিনিই সে সত্ত্বা যিনি প্রাচীন “আদ” সম্প্রদায়কে বিলুপ্ত করেছিলেন।"],
  "53:51": ["And Thamud, so nothing remained", "এবং মুছে দিয়েছিলেন ‘সামুদ’ সম্প্রদায়কে।"],
  "53:52": ["And the people of Nuh before; indeed they were more unjust and more transgressing", "এছাড়া এর পূর্বে নূহের লোকদের; তারা ছিল মন্দ সীমালঙ্ঘনকারী।"],
  "53:53": ["And the overturned cities, Allah plunged them", "ছডম ও গোমোরা -এর) দুষ্ট জনপদগুলো ছিল সবচেয়ে নীচু।"],
  "53:54": ["So that which covers covered them", "ফলস্বরুপ, তারা একদম নিশ্চিহ্ন হয়েছিল।"],
  "53:55": ["So which of your Rabb's bounties do you doubt", "তোমার প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পারো?"],
  "53:56": ["This is a warner from among the former warners", "এটি একটি সতর্কবানী পুরনোগুলোর মতো।"],
  "53:57": ["The imminent has drawn near", "অনিবার্য সময়টি আসন্ন।"],
  "53:58": ["There is none besides Allah to uncover it", "ঈশ্বর ব্যতিত কেউ তা প্রকাশ করতে পারে না।"],
  "53:59": ["Do you then marvel at this tale", "তোমরা কি এ বিষয়ে প্রশ্ন করছো?"],
  "53:60": ["And you laugh and do not weep", "তোমরা কি কান্নার বদলে হাসছো?"],
  "53:61": ["And you are heedless", "তোমরা কি তোমাদের পথে গোঁ ধরে আছো?"],
  "53:62": ["So prostrate yourselves to Allah and worship", "তোমরা ঈশ্বরের সামনে সেজদাবনত হও, এবং উপাসনা করো।"],
  "54:1": ["The Hour has drawn near and the moon has split.", "সে সময় নিকটবর্তি হয়েছে, এবং চাঁদ বিভক্ত হয়েছে।"],
  "54:2": ["But if they see a sign they turn away and say: \"A persistent magic.\"", "তারপর তারা একটি অলৌকিক নিদর্শন দেখল; কিন্তু তারা মুখ ফিরিয়ে নিল এবং বলল, “পুরনো জাদু”।"],
  "54:3": ["And they denied and followed their desires; and every matter is settled.", "তারা অবিশ্বাস করলো, তাদের মতের অনুসরণ করলো এবং তাদের পুরনো প্রথায় লেগে থাকলো।"],
  "54:4": ["And news has come to them containing a deterrent.", "তাদের সাবধান করতে যথেষ্ট সতর্কবানী প্রদান করা হয়েছে।"],
  "54:5": ["Far-reaching wisdom, yet the warnings do not avail.", "বিশাল প্রজ্ঞা; কিন্তু সকল সতর্কবানী বিফল হয়েছে।"],
  "54:6": ["So turn away from them. On the day the caller calls to something dreadful,", "তাদের উপেক্ষা করো; সেদিন আসবে যখন আহবানকারী এক ভয়াবহ দুর্যোগের ঘোষণা দিবে।"],
  "54:7": ["their eyes humbled, they come out of the graves as if they were locusts spread abroad,", "তাদের অপমানিত চোখগুলো নিয়ে, তারা কবর থেকে বেরিয়ে আসে বিক্ষিপ্ত পঙ্গপালের মতো।"],
  "54:8": ["hastening to the caller. The rejectors say: \"This is a day of hardship.\"", "যখন তারা আহবানকারীর ডাকে সাড়া দেবে, অবিশ্বাসীরা বলবে, “এ এক কঠিন দিন।”"],
  "54:9": ["Before them the people of Nuh denied; they denied Our servant, saying: \"A madman,\" and drove him away.", "তাদের আগে নূহের লোকেরা অবিশ্বাস করেছিল। তারা আমাদের বান্দাকে অবিশ্বাস করেছিল আর বলেছিল, “উন্মাদ!” তার উপর নির্যাতন করা হয়েছিল।"],
  "54:10": ["So he called to his Rabb: \"I am overcome,\" and he was granted victory.", "সে তার প্রভুর কাছে মিনতি করলো, “আমি নির্যাতিত; আমাকে বিজয় দিন।”"],
  "54:11": ["So We opened the gates of the sky with water poured down,", "আমরা তখন আকাশের দরজাগুলো খুলে দিয়েছিলাম, পানি বর্ষণ করতে।"],
  "54:12": ["and We burst the earth with springs, and the waters met upon a decree decreed.", "এবং আমরা পৃথিবী থেকে সজোরে ঝর্ণা প্রবাহিত করেছিলাম। পানিগুলো এক পূর্বনির্ধারিত সিদ্ধান্ত কার্যকর করতে।"],
  "54:13": ["And We carried him upon a vessel of planks and nails,", "আমরা তাকে গাছের গুড়ি ও দড়ি দিয়ে নির্মিত জলযানে চড়িয়েছিলাম।"],
  "54:14": ["running under Our watch — a recompense for one who had rejected.", "এটি চলেছিল আমাদের সতর্ক দৃষ্টির আওতায়; সে ব্যক্তির জন্য পুরষ্কার যাকে প্রত্যাখান করা হয়েছিল।"],
  "54:15": ["And We left it as a sign; so is there any who will remember?", "একে আমরা একটি শিক্ষা হিসেবে স্থাপন করেছি। তোমাদের কেউ কি শিখতে চাও?"],
  "54:16": ["So how was My punishment and My warnings?", "সতর্কবানীর পর কত ভয়াবহ ছিল আমার শাস্তি!"],
  "54:17": ["And We have made the Recitation easy for remembrance; so is there any who will remember?", "আমরা কুরআনকে শেখার জন্য সহজ করেছি। তোমাদের কেউ কি শিখতে চাও?"],
  "54:18": ["Ad denied; so how was My punishment and My warnings?", "আদ জাতি অবিশ্বাস করেছিল। পরিনামে, সতর্কবানীর পর কত ভয়াবহ ছিল আমার শাস্তি।"],
  "54:19": ["We sent upon them a screaming wind on a day of unrelenting ill-omen,", "আমরা তাদের উপর প্রবল বাতাস প্রেরন করেছিলাম, এক অবিরাম দুর্দশার দিনে।"],
  "54:20": ["plucking up people as if they were trunks of uprooted palms.", "এটি লোকদের চারদিকে ছুড়ে ফেলেছিল যেন তারা ছিল জীর্ণশীর্ণ খেজুর গাছের গুড়ি।"],
  "54:21": ["So how was My punishment and My warnings?", "সতর্কবানীর পর কত ভয়াবহ ছিল আমার শাস্তি!"],
  "54:22": ["And We have made the Recitation easy for remembrance; so is there any who will remember?", "আমরা কুরআনকে শেখার জন্য সহজ করেছি। তোমাদের কেউ কি শিখতে চাও?"],
  "54:23": ["Thamud denied the warnings.", "সামুদ জাতি সতর্ক-বাণী প্রত্যাখ্যান করেছিল।"],
  "54:24": ["And they said: \"Are we to follow a mortal, one from among us? Then we would be in error and in a blaze.\"", "তারা বলেছিল, “আমরা কি অনুসরণ করবো আমাদেরই একজনকে; একজন মানুষকে? আমরা তাহলে পথভ্রষ্ট হবো, এরপর শেষ পর্যন্ত নরকে যাবো।"],
  "54:25": ["Shall the Reminder be cast upon him from among us? Rather, he is an insolent liar.", "“বার্তা কি আমাদের পরিবর্তে তার কাছে পৌঁছাল? সে ঘোর মিথ্যাবাদী।”"],
  "54:26": ["They will know by morning who the insolent liar is.", "আগামীকাল তারা দেখতে পাবে কে ঘোর মিথ্যাবাদী।"],
  "54:27": ["We are sending the naqah as a trial for them; so watch them and be of the sabirin.", "আমরা উটকে তাদের জন্য পরীক্ষা হিসেবে পাঠাচ্ছি। তাদের প্রতি দৃষ্টি রাখো এবং ধৈর্য ধর।"],
  "54:28": ["And tell them that the water is to be divided among them: every draught is brought in turn.", "তাদেরকে জানাও যে পানি তাদের মধ্যে ভাগ করে দেয়া হবে; (উটটি) তার জন্য নির্দিষ্ট দিনে পানি পানের অনুমতি পাবে।"],
  "54:29": ["So they called their companion, and he took in hand and hamstrung her.", "কিন্তু তারা (উটটিকে) হত্যা করতে তাদের বন্ধুকে প্ররোচিত করলো, আর সে রাজি হয়েছিল।"],
  "54:30": ["So how was My punishment and My warnings?", "পরিণামে, কত ভয়াবহ ছিল আমার শাস্তি! তাদেরকে সতর্ক করা হয়েছিল।"],
  "54:31": ["We sent upon them a single shout, and they became like trampled chaff.", "আমরা তাদের উপর পাঠিয়েছিলাম বায়ুপ্রবাহ, যার ফলে তারা কর্তিত খড়কুটোর মতো হয়ে গিয়েছিল ।"],
  "54:32": ["And We have made the Recitation easy for remembrance; so is there any who will remember?", "আমরা কুরআনকে শেখার জন্য সহজ করেছি। তোমাদের কেউ কি শিখতে চাও?"],
  "54:33": ["The people of Lut denied the warnings.", "লুতের লোকেরা সতর্কবানী প্রত্যাখ্যান করেছিল।"],
  "54:34": ["We sent upon them a burning blast — except the family of Lut; We rescued them at dawn,", "আমরা তাদের উপর পাথর বর্ষণ করেছিলাম। শুধু লুতের পরিবারকে ভোর-বেলায় রক্ষা করা হয়েছিল।"],
  "54:35": ["a favor from Us; thus We repay the shakir.", "আমরা তাকে ও তার পরিবারকে সৌভাগ্যশালী করেছিলাম; আমরা এভাবে কৃতজ্ঞদের পুরস্কৃত করি।"],
  "54:36": ["And We warned them of Our seizing, but they cast doubt on the warnings.", "সে তাদেরকে আমাদের প্রতিশোধের বিষয়ে সতর্ক করেছিল, কিন্তু তারা সতর্কবার্তাকে উপহাস করেছিল।"],
  "54:37": ["And they demanded his guests of him, so We blotted out their eyes: \"Taste My punishment and My warnings.\"", "তারা তার মেহমানদের বিষয়ে তার সাথে স্বার্থপর আলোচনা করেছিল; আমরা তাদের অন্ধ করে দিয়েছিলাম। আমার শাস্তি ভোগ কর; তোমাদের সতর্ক করা হচ্ছিল।"],
  "54:38": ["And there came upon them, in the early morning, an abiding punishment.", "পরের দিন খুব ভোরে, এক বিধ্বংসী শাস্তি তাদের উপর আঘাত হানলো।"],
  "54:39": ["\"Taste My punishment and My warnings.\"", "আমার শাস্তি ভোগ করো; তোমাদের সতর্ক করা হচ্ছিল।"],
  "54:40": ["And We have made the Recitation easy for remembrance; so is there any who will remember?", "আমরা কুরআনকে শেখার জন্য সহজ করেছি। তোমাদের কেউ কি শিখতে চাও?"],
  "54:41": ["And the warnings came to the family of Fir'awn.", "ফেরাউনের লোকদের সতর্ক করা হয়েছিল।"],
  "54:42": ["They denied all Our signs, so We seized them with a seizure mighty and overwhelming.", "তারা আমাদের সকল নিদর্শন প্রত্যাখ্যান করেছিল। পরিণামে, আমরা তাদের থেকে তেমন প্রতিশোধ নিয়েছিলাম যেমন একজন সর্বশক্তিমান, সর্বজ্ঞের উচিৎ।"],
  "54:43": ["Are your rejectors better than those of old, or do you have immunity in the scripture?", "তোমাদের অবিশ্বাসীরা কি ঐসব অবিশ্বাসীদের থেকে উত্তম? ঐশীগ্রন্থ কি তোমাদের পাপ-মুক্ত করে দিয়েছে?"],
  "54:44": ["Or do they say: \"We are a host, triumphant\"?", "সম্ভবত তারা ভাবে, “আমরাই জয়ী হব।”"],
  "54:45": ["The host shall be routed and they will turn their backs.", "তাদের সকলে পরাজিত হবে; তারা মুখ ফিরিয়ে নিবে আর পালাবে।"],
  "54:46": ["Nay, the Hour is their tryst, and the Hour is more calamitous and more bitter.", "সে ঘণ্টা তাদের জন্য অপেক্ষা করছে আর সে ঘণ্টা অধিক মন্দ এবং অধিক যন্ত্রণাদায়ক।"],
  "54:47": ["Indeed the mujrimin are in error and in a blaze.", "নিশ্চয়, অপরাধীরা পথভ্রষ্ট, আর শেষ পর্যন্ত নরকে যাবে।"],
  "54:48": ["On the day they are dragged in the fire upon their faces: \"Taste the touch of Saqr.\"", "তাদেরকে নরকের আগুনে টেনে নিয়ে যাওয়া হবে, বলপূর্বক। শাস্তির যন্ত্রনা ভোগ কর।"],
  "54:49": ["Indeed We created everything by measure,", "আমাদের সৃষ্ট সবকিছু সঠিকভাবে পরিমিত।"],
  "54:50": ["and Our command is but one, like the blink of an eye.", "আমাদের হুকুম চোখের এক পলকেই সম্পন্ন হয়।"],
  "54:51": ["And We destroyed your own kind; so is there any who will remember?", "আমরা তোমাদের অনুরূপ ব্যক্তিদের ধ্বংস করেছিলাম। তোমরা কেউ কি শিখতে চাও?"],
  "54:52": ["And everything they did is in the scripture,", "তারা যা কিছু করেছিল তা ঐশীগ্রন্থগুলোতে লিপিবদ্ধ রয়েছে।"],
  "54:53": ["and every small and great thing is written down.", "সবকিছু, ছোট অথবা বড় লিপিবদ্ধ করা হয়।"],
  "54:54": ["Indeed the ilah-fearing are in a garden and a river,", "নিশ্চয়, সৎকর্মশীলরা বাগান ও নদীগুলো লাভের যোগ্য।"],
  "54:55": ["in a seat of truth, in the presence of an all-powerful Sovereign.", "সন্মানজনক একটি অবস্থানের, একজন সর্বশক্তিমান রাজার কাছে।"],
  "55:1": ["The the Raheem", "পরম করুণাময়।"],
  "55:2": ["Taught the Quran", "কুরআনের শিক্ষক।"],
  "55:3": ["Allah created man", "মানুষের সৃষ্টিকর্তা।"],
  "55:4": ["Taught him clear speech", "তিনি তাদেরকে শিখিয়েছেন কিভাবে পার্থক্য করতে হয়।"],
  "55:5": ["The sun and the moon move by exact measure", "সূর্য ও চাঁদ নিখুঁতভাবে গণনাকৃত।"],
  "55:6": ["And the stars and the trees bow down", "তারকারাজি ও বৃক্ষকূল সেজদা করে।"],
  "55:7": ["And Allah raised up the sky and set the balance in place", "তিনি আকাশ সৃষ্টি করেছেন এবং আইন প্রতিষ্ঠা করেছেন।"],
  "55:8": ["So that you do not transgress in the balance", "তোমরা আইনের সীমা অতিক্রম করো না।"],
  "55:9": ["And weigh with equity, and do not cheat the balance", "তোমরা ন্যায় বিচার প্রতিষ্ঠা কর; আইন লঙ্ঘন কর না।"],
  "55:10": ["And Allah laid down the earth for mankind", "তিনি সকল সৃষ্টির জন্য পৃথিবী সৃষ্টি করেছেন।"],
  "55:11": ["In it are fruit, and palms with their sheaths", "এতে রয়েছে ফল-ফলাদি, এবং খেজুর গাছ - এদের ঝুলন্ত ফলসহ।"],
  "55:12": ["And grain with its husk, and fragrant herbs", "আরও আছে খাদ্যশস্য ও মসলা।"],
  "55:13": ["So which of the bounties of your Rabb do you two deny", "(হে মানুষ ও জিন) তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:14": ["Created man from clay that rings, like pottery", "তিনি মানুষকে সৃষ্টি করেছেন, কুমোরের কাঁদা সদৃশ পুরনো কাঁদা থেকে।"],
  "55:15": ["And created the jinn from a mingled blaze of fire", "এবং জিনদের সৃষ্টি করেছেন জ্বলন্ত আগুন থেকে।"],
  "55:16": ["So which of the bounties of your Rabb do you two deny", "(হে মানুষ ও জিন) তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:17": ["The Rabb of the two easts and the Rabb of the two wests", "দুই পূর্ব এবং দুই পশ্চিমের প্রভু।"],
  "55:18": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:19": ["The two seas flow free and meet", "তিনি দুই সাগরকে আলাদা করেন যখন এরা মিলিত হয়।"],
  "55:20": ["Between them is a barrier they do not transgress", "এদের মধ্যে একটি দেয়াল রাখা হয়, যা এদেরকে সীমাতিক্রমে বাধা দেয়।"],
  "55:21": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:22": ["From them come out pearls and coral", "এদের উভয়ের থেকে তোমরা মুক্তা ও প্রবাল পাও।"],
  "55:23": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:24": ["And to Allah belong the ships raised in the sea like mountains", "তিনি তোমাদেরকে জাহাজ দিয়েছেন যা পতাকার মত সাগরে ঘুরে বেড়ায়।"],
  "55:25": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:26": ["All upon it perishes", "পৃথিবীর প্রত্যেকে ধ্বংসশীল।"],
  "55:27": ["And the face of your Rabb remains, full of majesty and honor", "কেবলমাত্র তোমার প্রভুর উপস্থিতি স্থায়ী হয়। যিনি রাজকীয় ক্ষমতা ও সন্মানের অধিকারী।"],
  "55:28": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:29": ["Whoever is in the heavens and the earth asks of Allah; every day Allah is engaged in some affair", "আকাশমণ্ডলী ও পৃথিবীর সকলে তাঁর কাছে মিনতি করে। প্রত্যেক দিন তিনি সম্পূর্ণ নিয়ন্ত্রনরত।"],
  "55:30": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:31": ["Soon We shall be free for you, O you two weights", "হে মানুষ ও জিন, আমরা তোমাদের হিসাবের জন্য ডাকবো।"],
  "55:32": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:33": ["O company of jinn and mankind, if you are able to pass through the regions of the heavens and the earth, then pass through; you shall not pass through except by a warrant", "হে জীন ও মানুষ, যদি তোমরা আকাশমণ্ডলী ও পৃথিবীর শেষ সীমা ভেদ করতে পারো, তবে এগিয়ে যাও আর ভেদ করো।  অনুমোদন ছাড়া তোমরা প্রবেশ করতে পারো না।"],
  "55:34": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:35": ["A flame of fire and molten brass will be sent upon you both, and you shall not prevail", "তোমরা আগুন ও ধাতুর গোলাবর্ষণে ধ্বংসপ্রাপ্ত হও, এবং তোমরা জয়ী হতে পারো না।"],
  "55:36": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:37": ["And when the sky splits open, it becomes like a rose of oil", "যখন আকাশ ভেঙ্গে যায় এবং রঙের মতো গোলাপি বর্ণ ধারণ করে।"],
  "55:38": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:39": ["On that day no human and no jinn will be asked about his wrong", "ঐ দিন, না কোন মানুষ, না কোন জীন, তার পাপ সম্পর্কে জিজ্ঞাসিত হবে।"],
  "55:40": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:41": ["The guilty will be known by their marks, and seized by the forelocks and the feet", "(এটি এ কারনে যে) অপরাধীদেরকে তাদের অঙ্গভঙ্গি দেখে চেনা যাবে; তাদেরকে মাথার অগ্রভাগের চুল ও পা ধরে নিয়ে যাওয়া হবে।"],
  "55:42": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:43": ["This is the Hell which the guilty denied", "এটা জাহান্নাম যা অপরাধীরা প্রত্যাখ্যান করতো।"],
  "55:44": ["They move back and forth between it and scalding water at the boil", "এটিতে এবং এক অসহনীয় নিন্মস্তরের (হামিম) মধ্যে তারা ঘুরতে থাকবে।"],
  "55:45": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:46": ["And for the one who feared the standing before his Rabb, two gardens", "যারা তাদের প্রভুর মহিমাকে সম্মান করে তাদের জন্য, দুটি বাগান (একটি জিনদের জন্য এবং একটি মানুষদের জন্য)।"],
  "55:47": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:48": ["Two gardens with spreading branches", "খাদ্যসামগ্রীতে পরিপূর্ণ।"],
  "55:49": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার"],
  "55:50": ["In them two springs run", "এদের মধ্যে রয়েছে দুটি ঝর্ণা, প্রবাহমান।"],
  "55:51": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:52": ["In them are two of every kind of fruit", "এদের প্রত্যেকটি ফল, দুই প্রকার।"],
  "55:53": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:54": ["Reclining on couches lined with brocade, and the fruit of the two gardens is near at hand", "যখন সাটিনের  আবরণযুক্ত আসবাবে আরাম করবে, ফলগুলো তখন তাদের হাতের নাগালে থাকে।"],
  "55:55": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:56": ["In them are those restrained of gaze, whom no human has touched before them, and no jinn", "তাদের সুন্দর সঙ্গিদের কখনই কোন মানুষ অথবা জিন স্পর্শ করেনি।"],
  "55:57": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:58": ["As if they were gems and coral", "তারা রত্ন ও প্রবলের মত দেখতে।"],
  "55:59": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:60": ["Is the recompense of good anything but good", "ভালোত্বের পুরস্কার ভালোত্ব ছাড়া কি হতে পারে?"],
  "55:61": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:62": ["And below them both, two gardens", "এদের নিচে আছে দুটি বাগান (একটি জিনদের জন্য এবং একটি মানুষদের জন্য)।"],
  "55:63": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:64": ["Dark green", "পাশাপাশি।"],
  "55:65": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:66": ["In them two gushing springs", "এদের মধ্যে আছে পানির কূপ যা থেকে উত্তোলন করতে হয়।"],
  "55:67": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:68": ["In them are fruit, palms, and pomegranates", "এদের মধ্যে আছে ফল, খেজুর গাছ, এবং আনার।"],
  "55:69": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:70": ["In them are good and beautiful ones", "এদের মধ্যে আছে সুন্দর সঙ্গিরা।"],
  "55:71": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:72": ["Fair-eyed ones, restrained in the pavilions", "তাঁবুতে আবদ্ধ"],
  "55:73": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:74": ["Whom no human has touched before them, and no jinn", "কোন মানুষ কখনো তাদের স্পর্শ করেনি, না কোন জিন।"],
  "55:75": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:76": ["Reclining on green cushions and fine, beautiful carpets", "তারা সবুজ গালিচায় আরাম করে, সুন্দর পারিপার্শ্বিকতায়। চতুর্দিকের পরিবেষ্টনে।"],
  "55:77": ["So which of the bounties of your Rabb do you two deny", "তোমাদের প্রভুর কোন বিস্ময়কে তোমরা অস্বীকার করতে পার?"],
  "55:78": ["Blessed be the name of your Rabb, full of majesty and honor", "তোমার প্রভুর নাম, যিনি মহিমা ও সম্মানের অধিকারী, অত্যন্ত মহিমান্বিত"],
  "56:1": ["When the Befalling befalls.", "যখন সে অনিবার্য ঘটনা ঘটবে।"],
  "56:2": ["There is no giving the lie to its occurrence.", "কোন কিছু এর ঘটার সময়কে থামাতে পারে না।"],
  "56:3": ["It brings some low and raises others high.", "এটি কাউকে নিচে নামাবে, আর কাউকে উপরে তুলবে।"],
  "56:4": ["When the earth is shaken.", "পৃথিবীকে ঝাঁকানো হবে।"],
  "56:5": ["And the rocky landforms are leveled and scattered.", "পর্বতমালা মুছে ফেলা হবে।"],
  "56:6": ["And they become scattered dust.", "যেন কখনো তাদের অস্তিত্ব ছিল না।"],
  "56:7": ["And you become three companies.", "তোমরা তিন স্তরে বিভক্ত হয়ে পড়বে।"],
  "56:8": ["And the companions of the right — what of the companions of the right!", "যারা পরম সুখের যোগ্য তারা পরম সুখে থাকবে।"],
  "56:9": ["And the companions of the left — what of the companions of the left!", "যারা দুর্দশার যোগ্য তারা দুর্দশায় থাকবে।"],
  "56:10": ["And the forerunners, the forerunners!", "এরপর আছে অভিজাতদের অভিজাত।"],
  "56:11": ["Those are the ones brought near.", "তারাই (ঈশ্বরের) সবচেয়ে নিকটবর্তী হবে।"],
  "56:12": ["In the garden of delight.", "পরম সুখের বাগানগুলোতে।"],
  "56:13": ["A company of the ancients.", "অনেকেই প্রথম প্রজন্মগুলো থেকে ।"],
  "56:14": ["And a few of the later ones.", "পরবর্তী প্রজন্মগুলো থেকে অল্প সংখ্যক।"],
  "56:15": ["Upon inlaid couches.", "বিলাসবহুল আসবাবপত্রে।"],
  "56:16": ["Reclining on them, facing one another.", "সবকিছু উপভোগ করে, তারা হবে প্রতিবেশী।"],
  "56:17": ["Eternal youths move about among them.", "তাদের সেবায় থাকবে অমর সেবকগন।"],
  "56:18": ["With cups and ewers and a cup from a running spring.", "পেয়ালা, জগ এবং বিশুদ্ধ পানীয় নিয়ে।"],
  "56:19": ["They suffer no splitting head from it and no draining.", "এগুলো কখনো ফুরিয়ে যায় না, না এরা একঘেয়ে হয়ে যায়।"],
  "56:20": ["And fruit of whatever they choose.", "তাদের পছন্দের ফল-ফলাদি।"],
  "56:21": ["And flesh of birds from whatever they desire.", "পাখির মাংস যা তারা আকাংখা করে।"],
  "56:22": ["And fair-eyed ones.", "সুন্দর সঙ্গীরা।"],
  "56:23": ["Like pearls concealed.", "সুরক্ষিত মুক্তার মতো।"],
  "56:24": ["A reward for what they used to do.", "তাদের কাজের জন্য পুরস্কার।"],
  "56:25": ["They hear in it no idle talk and no word of sin.", "তারা কখনই সেখানে কোন ভিত্তিহীন কথা শোনে না, না পাপপূর্ণ কথাবার্তা।"],
  "56:26": ["Only a saying: \"Peace, peace.\"", "শুধু উচ্চারিত হবেঃ “শান্তি, শান্তি।”"],
  "56:27": ["And the companions of the right — what of the companions of the right!", "যারা ডান পাশের তারা ডান পাশে থাকবে।"],
  "56:28": ["In pruned lote-trees.", "ঘন ফল বাগানে।"],
  "56:29": ["And banana-trees ranged in rows.", "সুগন্ধি ফল-ফলাদি।"],
  "56:30": ["And shade spread out.", "দীর্ঘ ছায়া।"],
  "56:31": ["And water poured forth.", "পর্যাপ্ত পানি।"],
  "56:32": ["And fruit in plenty.", "অনেক ফল।"],
  "56:33": ["Never cut off and never withheld.", "কখনো শেষ হবার নয়; কখনো নিষিদ্ধ নয়।"],
  "56:34": ["And couches raised high.", "বিলাসবহুল আসবাবপত্র।"],
  "56:35": ["We raised them up with a raising.", "আমরা তাদের জন্য সঙ্গি -সঙ্গিনী সৃষ্টি করি।"],
  "56:36": ["And made them maidens.", "পূর্বে কখনো স্পর্শ করা হয়নি।"],
  "56:37": ["Fair and equal in age.", "একেবারে মানানসই।"],
  "56:38": ["For the companions of the right.", "তাদের জন্য যারা ডান পাশের।"],
  "56:39": ["A company of the ancients.", "অনেকেই প্রথমদিককার প্রজন্মগুলো থেকে।"],
  "56:40": ["And a company of the later ones.", "অনেকেই পরবর্তী প্রজন্মগুলো থেকে।"],
  "56:41": ["And the companions of the left — what of the companions of the left!", "যারা বাঁ দিকের, তারা বাঁ দিকে থাকবে।"],
  "56:42": ["In scorching wind and scalding water.", "দুর্দশা ও অগ্নিকাণ্ডে।"],
  "56:43": ["And shade of scalding smoke.", "এমনকি তাদের ছায়াও উত্তপ্ত।"],
  "56:44": ["Neither cool nor generous.", "কখনই ঠাণ্ডা নয়, কখনই সহনীয় নয়।"],
  "56:45": ["They were before that softened by ease.", "তারা ধনী ছিল।"],
  "56:46": ["And they persisted obstinately in the great sin.", "তারা ঈশ্বরের প্রতি ঘোর মিথ্যাচারে অটল থাকত।"],
  "56:47": ["And they used to say: \"What! When we die and become dust and bones, are we indeed to be raised?", "তারা বলতো, “আমরা মরে যাবার পর এবং ধুলো ও হাড় হয়ে যাবার পর, আমরা পুনরুত্থিত হবো?"],
  "56:48": ["And our earliest fathers?\"", "“আমাদের পূর্ব পুরুষরাও কি হবে?”"],
  "56:49": ["Say: the ancients and the later ones —", "বল, “প্রথমদিককার প্রজন্মগুলো এবং পরবর্তী প্রজন্মগুলো।"],
  "56:50": ["will be gathered to the appointed time of a known day.", "তলব করা হবে এক পূর্ব নির্ধারিত দিনের সাক্ষাতকারে ।"],
  "56:51": ["Then you, the straying ones, the mukazzibin!", "“তখন তোমরা, হে অবিশ্বাসী পথভ্রষ্টরা।"],
  "56:52": ["You will eat from the zaqqum-tree.", "“খাবে তিক্ততার বৃক্ষ থেকে।"],
  "56:53": ["Filling your bellies from it.", "“তা দিয়ে তোমাদের পেট ভরিয়ে।"],
  "56:54": ["And drinking over it scalding water.", "“এরপর এর সাথে নারকীয় পানীয় পান করে ।"],
  "56:55": ["Drinking the drink of the thirst-maddened.", "“এরপর বালুর পানীয় মিলিয়ে।”"],
  "56:56": ["This is their lodging on the day of reckoning.", "বিচারের দিনে এমনি তাদের অংশ।"],
  "56:57": ["We created you — so why do you not believe?", "আমরা তোমাদের সৃষ্টি করেছি, যদি কেবল তোমরা বিশ্বাস করতে পারতে!"],
  "56:58": ["Have you considered what you emit?", "তোমরা কি লক্ষ্য করেছ সে বীর্য যা তোমরা উৎপাদন করো?"],
  "56:59": ["Is it you who create it, or are We the Creators?", "এটা কি তোমরা সৃষ্টি করেছিলে, নাকি আমরা করেছিলাম?"],
  "56:60": ["We decreed death among you, and We cannot be outstripped.", "তোমাদের জন্য আমাদের কাছে রয়েছে পূর্ব নির্ধারিত মৃত্যু। কোন কিছুই আমাদের থামাতে পারে না-"],
  "56:61": ["So that We may substitute the likes of you and raise you up in what you do not know.", "প্রতিস্থাপন করা হতে তোমাদের পরিবর্তে নতুন প্রজন্মকে, এবং প্রতিষ্ঠা করতে যা তোমরা জানো না।"],
  "56:62": ["You have surely known the first raising — so why do you not remember?", "তোমরা প্রথম সৃষ্টি সম্পর্কে জানো। তোমরা কি স্মরণ করো না?"],
  "56:63": ["Have you considered what you till?", "তোমরা কি লক্ষ্য করেছ সে শস্যগুলো যা তোমরা কাটো?"],
  "56:64": ["Is it you who sow it, or are We the sowers?", "তোমরা কি সেগুলো উৎপন্ন করেছিলে, নাকি আমরা করেছিলাম?"],
  "56:65": ["If We willed, We would make it crumbled, and you would remain laughing.", "যদি আমরা চাই, আমরা একে খড় কুটো করে দিতে পারি। তখন তোমরা বিলাপ করবেঃ"],
  "56:66": ["We are in liability indeed!", "“আমরা ক্ষতিগ্রস্থ।"],
  "56:67": ["Nay, we are deprived!", "“আমাদের বঞ্চিত করা হয়েছে।”"],
  "56:68": ["Have you considered the water you drink?", "তোমরা কি লক্ষ্য করেছ সে পানি যা তোমরা পান করো?"],
  "56:69": ["Is it you who sent it down from the clouds, or are We the senders-down?", "তোমরা কি একে মেঘ থেকে নামিয়ে এনেছিলে, নাকি আমরা এনেছিলাম?"],
  "56:70": ["If We willed, We would make it bitter — so why do you not give thanks?", "যদি আমরা চাই, তবে আমরা একে লবণাক্ত করে দিতে পারি। তোমাদের কৃতজ্ঞ হওয়া উচিৎ।"],
  "56:71": ["Have you considered the fire you kindle?", "তোমরা কি সে আগুনকে লক্ষ্য করেছ যা তোমরা জ্বালাও?"],
  "56:72": ["Is it you who raised up its tree, or are We the raisers-up?", "তোমরা কি এর গাছগুলোর সূচনা করেছিলে, নাকি আমরা করেছিলাম?"],
  "56:73": ["We made it a reminder and a provision for those who draw strength.", "আমরা একে করলাম একটি স্মারক এবং একটি কার্যকর বস্তু ব্যবহারকারীদের জন্য।"],
  "56:74": ["So glorify the name of your Rabb the Great.", "তুমি তোমরা প্রভুর নামের পবিত্রতা ঘোষণা করো, যিনি মহান।"],
  "56:75": ["I swear by the falling-place of the stars.", "আমি নক্ষত্রদের অবস্থানের শপথ করছি।"],
  "56:76": ["And it is indeed a great oath, if only you knew.", "এটি একটি শপথ, যদি তোমরা কেবল জানতে, যা অসাধারণ।"],
  "56:77": ["It is a noble recitation.", "এটি একটি সন্মানিত কুরআন।"],
  "56:78": ["In concealed scrolls.", "একটি সংরক্ষিত গ্রন্থে।"],
  "56:79": ["None touch it but the purified.", "কেউ এটি উপলব্ধি করতে পারে না আন্তরিক ব্যক্তি ব্যতীত।"],
  "56:80": ["A sending-down from the Rabb of all worlds.", "মহাবিশ্বের প্রভুর পক্ষ থেকে একটি প্রকাশনা।"],
  "56:81": ["Do you take this discourse so lightly?", "তোমরা কি এই বর্ণনাকে অবজ্ঞা করছো?"],
  "56:82": ["And you make your living out of denying it.", "তোমরা কি তোমাদের অবিশ্বাস করাকে ব্যবসা বানাও?"],
  "56:83": ["Why then, when it reaches the throat,", "যখন সময় এসে যায় আর এটি (তোমাদের আত্মা) তোমাদের কণ্ঠে পৌঁছে-"],
  "56:84": ["and you, at that moment, are looking on,", "তখন তোমরা চারদিকে তাকাবে।"],
  "56:85": ["and We are nearer to it than you, but you do not see —", "তোমাদের চেয়ে আমরা এর অধিক নিকটবর্তী, কিন্তু তোমরা দেখ না।"],
  "56:86": ["so if you are not to be called to account,", "যদি এটি সত্য হয় যে তোমাদের কোন জবাবদিহিতা নেই-"],
  "56:87": ["send it back, if you are sadiq.", "কেন তোমরা (তোমাদের আত্মাকে) পুনরায় ফিরিয়ে নাও না, যদি তোমরা সত্যবাদী হয়ে থাক?"],
  "56:88": ["But if such a one is among the brought-near,", "যদি সে আমার নিকটবর্তীদের একজন হয়-"],
  "56:89": ["then a soul at rest, and sweet fragrance, and a garden of delight.", "তবে আনন্দ, ফুলসম্ভার এবং পরম সুখের বাগানসমূহ।"],
  "56:90": ["And if such a one is among the companions of the right,", "আর যদি সে ডান পার্শ্বস্থদের একজন হয়-"],
  "56:91": ["then: \"Peace to you,\" from the companions of the right.", "শান্তিই তাদের ভাগ্য যারা ডান পার্শ্বস্থ।"],
  "56:92": ["And if such a one is among the mukazzibin, the strayers,", "কিন্তু যদি সে অবিশ্বাসী, পথভ্রষ্টদের একজন হয়-"],
  "56:93": ["then a lodging of scalding water,", "তবে আগুনের একটি বাসস্থান-"],
  "56:94": ["and entering into the blaze.", "আর নরকে জ্বলতে থাকা,"],
  "56:95": ["Indeed this is the truth of certainty.", "এটি ধ্রুব সত্য।"],
  "56:96": ["So glorify the name of your Rabb the Great.", "তুমি তোমরা প্রভুর নামের পবিত্রতা ঘোষণা করো, যিনি মহান।"],
  "57:1": ["All that is in the heavens and the earth glorifies Allah, and Allah is the Mighty, the Wise.", "আকাশমণ্ডলী ও পৃথিবীর সবকিছু ঈশ্বরের মহিমা ঘোষণা করছে। তিনি সর্বশক্তিমান, সবচেয়ে প্রজ্ঞাবান।"],
  "57:2": ["For Allah belongs the kingdom of the heavens and the earth; Allah gives life and brings death, and Allah is over all things powerful.", "তাঁর অধীনে রয়েছে আকাশমণ্ডলী ও পৃথিবীর রাজত্ব। তিনি জীবন ও মৃত্যু নিয়ন্ত্রন করেন। তিনি সর্বশক্তিমান।"],
  "57:3": ["Allah is the First and the Last, the Outward and the Inward, and Allah is knowing of all things.", "তিনি শুরু এবং শেষ। তিনি বাহিরতম এবং ভিতরতম। তিনি সকল বস্তু সম্পর্কে পূর্ণ অবগত।"],
  "57:4": ["Allah is the one who created the heavens and the earth in six days, then settled upon the high-seat; Allah knows what enters into the earth and what comes out of it, and what descends from the heaven and what ascends into it, and Allah is with you wherever you are, and Allah sees all that you do.", "তিনি সেই সত্ত্বা যিনি আকাশমণ্ডলী ও পৃথিবী সৃষ্টি করেছিলেন ছয় দিনে, এরপর সকল কর্তৃত্ব গ্রহন করলেন। সবকিছু তিনি জানেন যা পৃথিবীতে প্রবেশ করে এবং যা এর থেকে বের হয়ে আসে, আর সবকিছু যা আকাশ থেকে নেমে আসে, এবং যা এতে আরোহন করে। তিনি তোমাদের সাথে আছেন যেখানেই তোমরা থাক না কেন। ঈশ্বর সবকিছু দেখেন যা তোমরা করো।"],
  "57:5": ["For Allah belongs the kingdom of the heavens and the earth, and to Allah the affairs return.", "তাঁর অধীনে রয়েছে আকাশমণ্ডলী ও পৃথিবীর রাজত্ব। সকল বস্তু ঈশ্বর দ্বারা নিয়ন্ত্রিত হয়।"],
  "57:6": ["Allah enters the night into the day and enters the day into the night, and Allah is knowing of what is within the chests.", "তিনি রাতকে দিনের সাথে মিলিয়ে দেন এবং দিনকে রাতের সাথে মিলিয়ে দেন। তিনি ভিতরকার চিন্তাগুলো সম্পর্কে পূর্ণ অবগত।"],
  "57:7": ["Believe in Allah and in Allah's Rasul, and spend of what Allah has made you successors to; those of you who believe and spend — for them is a great reward.", "ঈশ্বর এবং তাঁর বার্তাবাহককে বিশ্বাস করো, আর তা থেকে দাও যা তিনি তোমাদের উপর অর্পণ করেছেন। তোমাদের মধ্যে যারা বিশ্বাস করে এবং (দান হিসেবে) দেয় তারা এক মহা প্রতিদানের যোগ্য হয়েছে।"],
  "57:8": ["What is the matter with you that you do not believe in Allah, when the Rasul calls you to believe in your Rabb? And Allah has already taken your pledge, if you are muminin.", "কেন তোমরা ঈশ্বর ও তাঁর বার্তাবাহককে বিশ্বাস করছো না যখন বার্তাবাহক তোমাদের দাওয়াত দিচ্ছে তোমাদের প্রভুর প্রতি বিশ্বাস আনতে? তিনি তোমাদের থেকে একটি অঙ্গীকার নিয়েছেন, যদি তোমরা বিশ্বাসী হয়ে থাক।"],
  "57:9": ["Allah is the one who sends down upon Allah's servant clear signs, to bring you out from darknesses into the light; and indeed Allah is toward you gentle in mercy, merciful.", "তিনি সেই সত্ত্বা যিনি তাঁর বান্দার কাছে স্পষ্ট প্রকাশনাবলি অবতীর্ণ করেন, তোমাদেরকে অন্ধকার থেকে আলোতে পরিচালিত করতে। ঈশ্বর তোমাদের প্রতি করুণাময়, পরম দয়ালু।"],
  "57:10": ["What is the matter with you that you do not spend in the way of Allah, when to Allah belongs the inheritance of the heavens and the earth? Not equal among you are those who spent before the triumph and fought; those are greater in degree than those who spent after and fought. Yet to each Allah has promised the most beautiful, and Allah is aware of all that you do.", "কেন তোমরা ঈশ্বরের পথে ব্যয় করো না, যখন আকাশমণ্ডলী ও পৃথিবীর সকল সম্পদ ঈশ্বরের? তোমাদের মধ্যে যারা বিজয়ের পূর্বে ব্যয় করে ও সংগ্রাম করে তারা বাকিদের থেকে আলাদা। তারা অর্জন করে অধিকতর পদমর্যাদা তাদের চেয়ে যারা বিজয়ের পরে ব্যয় করে ও সংগ্রাম করে। প্রত্যেকের জন্য, ঈশ্বর মুক্তির অঙ্গীকার করেন। তোমরা যা কিছু করো ঈশ্বর সে সম্পর্কে পূর্ণ অবগত।"],
  "57:11": ["Who is it that will loan Allah a good loan, so that Allah may multiply it for them, and for them is a generous reward?", "কে ঈশ্বরকে ঋণ দিতে পছন্দ করে, সৎকর্মশীলতার ঋণ, যেন তা তার জন্য বহুগুনে বর্ধিত হয়, এবং পরিনত হয় এক মহা প্রতিদানে?"],
  "57:12": ["On the day you see the believing men and believing nisa, their light hastening before them and on their right hands: glad tidings to you this day of gardens beneath which rivers flow, abiding therein forever. That is the great win.", "সেদিন আসবে যখন তুমি বিশ্বাসী পুরুষ ও নারীদের দেখবে তাদের আলো বিচ্ছুরিত হচ্ছে তাদের সামনে এবং তাদের ডান দিক থেকে । তোমাদের জন্য সুসংবাদ যে, ঐ দিন, তোমাদের থাকবে প্রবাহিত ঝর্ণাসহ বাগান। তোমরা চিরকাল সেখানে বাস করবে। এটাই মহাবিজয়।"],
  "57:13": ["On the day the munafiqin, men and nisa, say to those who believed: \"Wait for us, let us touch some of your light,\" it will be said: \"Go back behind yourselves and seek a light.\" Then a wall is struck between them, having a door: its inner side holds mercy, and its outer side, facing them, holds the punishment.", "ঐদিন, যারা বিশ্বাস করেছিল তাদেরকে ভণ্ড পুরুষ ও নারীরা বলবে, “দয়া করে তোমাদের কিছু আলো আমাদের (শোষণ করতে) দাও।” বলা হবে, “তোমরা পিছনে ফিরে যাও, এবং আলোর খোঁজ করো।” তাদের মধ্যে একটি অন্তরায় স্থাপন করা হবে, যার দরজা ভিতর দিকের দয়াকে আলাদা করে, বাইরের শাস্তি থেকে।"],
  "57:14": ["They will call to them: \"Were we not with you?\" They will say: \"Yes, but you put yourselves to trial and you waited and doubted, and idle wishes deceived you until the command of Allah came, and the deceiver deceived you about Allah.\"", "তারা তাদেরকে ডেকে বলবে, “আমরা কি তোমাদের সাথে ছিলাম না?” তারা উত্তর দেবে, “হ্যাঁ, কিন্তু তোমরা তোমাদের আত্মার সাথে প্রতারণা করেছিলে, সন্দেহকারী ছিলে, এবং মন-মতো চিন্তার কারণে বিপথগামী হয়েছিলে, যে পর্যন্ত না ঈশ্বরের বিচার এসে পড়েছিল। তোমরা মোহের কারণে ঈশ্বর থেকে সরে পড়েছিলে।"],
  "57:15": ["So today no ransom is taken from you, nor from those who kafara. Your shelter is the fire — it is your master — and what an evil arrival.", "“অতএব, আজ তোমাদের থেকে কোন মুক্তিপণ নেয়া হবে না, না তাদের থেকে যারা অবিশ্বাস করেছিল। আগুন হল তোমাদের বাসস্থান; এটি তোমাদের প্রভু এবং শোচনীয় বাসস্থান।”"],
  "57:16": ["Has the time not come for those who believed for their hearts to be humbled to the remembrance of Allah and to what has descended of the truth, and not to be like those who were given the books before? The length grew long upon them and their hearts hardened, and many of them are rebellious.", "যারা বিশ্বাস করেছে তাদের জন্য তাদের হৃদয় খুলে দেয়ার এটাই কি সময় নয় ঈশ্বরের বার্তার জন্য, এবং সে সত্যের জন্য যা এখানে প্রকাশ হয়? তাদের উচিত নয় পূর্ববর্তী ঐশীগ্রন্থের অনুসারিদের মতো হওয়া যাদের হৃদয় সময়ের সাথে সাথে কঠিন হয়ে পড়েছিল এবং, পরিণামে, তাদের অনেকেই অন্যায়কারীতে পরিনত হয়েছিল।"],
  "57:17": ["Know that Allah gives life to the earth after its death; We have made the signs clear to you, so that you may reason.", "জেনে রাখো যে ঈশ্বর জমিনকে এর মৃত্যুর পর পুনরুজ্জীবিত করেন। এইভাবে আমরা প্রকাশনাবলি তোমাদের জন্য ব্যাখ্যা করি, যাতে হয়তো তোমরা বুঝবে।"],
  "57:18": ["Indeed the musaddiqin men and musaddiqat nisa who loan Allah a good loan — it will be multiplied for them, and for them is a generous reward.", "নিশ্চয়, দানশীল পুরুষ ও নারীরা ঈশ্বরকে ঋণ  দেয়- ভালো কাজের ঋণ। তারা তাদের পুরস্কার বহুগুনে বর্ধিত অবস্থায় পাবে; তারা উদার প্রতিদানের যোগ্য হয়েছে।"],
  "57:19": ["Those who believe in Allah and in Allah's rusul — those are the sadiqin and the witnesses with their Rabb; theirs is their reward and their light. And those who disbelieve and deny our signs — those are the companions of the blaze.", "যারা ঈশ্বর ও তাঁর বার্তাবাহককে বিশ্বাস করেছে তারা সাধু ও শহীদ। তাদের জন্য তাদের প্রভুর কাছে সংরক্ষিত আছে তাদের পুরস্কার এবং তাদের আলো। আর যারা অবিশ্বাস করেছে এবং আমাদের প্রকাশনাবলি প্রত্যাখ্যান করেছে, তারা টেনে এনেছে নরক।"],
  "57:20": ["Know that the life of this world is only play and diversion and adornment, and vaunting among yourselves, and vying in increase in wealth and in children: like a rain-shower whose growth marvels the kafirin, then it withers and you see it yellow, then it becomes crumbled. And in the final world is severe punishment and forgiveness from Allah and pleasure. And the life of this world is nothing but the provision of deception.", "জেনে রাখো যে এই দুনিয়ার জীবন খেলা আর তামাশা, আর তোমাদের মধ্যে গর্ব করা, অর্থ ও সন্তান জমা করার চেয়ে বেশি কিছু নয়। এটি প্রচুর বৃষ্টির মত যা চারাগাছ উৎপন্ন করে এবং অবিশ্বাসীদের সন্তুষ্ট করে। কিন্তু এরপর চারাগাছগুলো অপ্রয়োজনীয় খড় কুটোয় পরিণত হয়, আর বাতাস তা উড়িয়ে নিয়ে যায়। পরকালে রয়েছে হয় কঠিন শাস্তি, নয়তো ঈশ্বর থেকে ক্ষমা ও সম্মতি। এই দুনিয়ার জীবন ক্ষণস্থায়ী মোহের চেয়ে বেশি কিছু নয়।"],
  "57:21": ["Race ahead toward forgiveness from your Rabb and toward a garden whose width is as the width of the heaven and the earth, prepared for those who believe in Allah and in Allah's rusul. That is the bounty of Allah, which Allah gives to whom Allah wills, and Allah is the possessor of the great bounty.", "অতএব, তোমরা প্রতিযোগিতা করো তোমাদের প্রভুর পক্ষ থেকে ক্ষমা আর এমন এক স্বর্গের জন্য যার ব্যাপ্তি আকাশ ও পৃথিবীকে পরিবেষ্টন করে। এটি তাদের জন্য অপেক্ষা করে যারা ঈশ্বর ও তাঁর বার্তাবাহককে বিশ্বাস করেছিল। এমনি ঈশ্বরের করুণা যা তিনি যার উপর ইচ্ছা অর্পণ করেন। ঈশ্বর অসীম করুণার অধিকারী।"],
  "57:22": ["No calamity strikes in the earth or in yourselves except it is in a book before We bring it forth; indeed that is easy for Allah.", "যা কিছু পৃথিবীতে, বা তোমাদের সাথে ঘটে তা ইতিমধ্যেই লিপিবদ্ধ আছে, এমনকি সৃষ্টির পূর্বেই। এটি করা ঈশ্বরের জন্য সহজ।"],
  "57:23": ["So that you may not grieve over what has escaped you, nor rejoice over what has come to you; and Allah does not love every conceited vaunter.", "সুতরাং, তোমাদের যাকিছুই হারায় তার জন্য দু:খ করা উচিত নয়, না কোনকিছু নিয়ে গর্ব করা উচিত যা তিনি তোমাদের উপর অর্পণ করেছেন। ঈশ্বর তাদের ভালোবাসেন না যারা  দাম্ভিক, অহংকারী।"],
  "57:24": ["Those who stint and order people to stint; and whoever turns away — then indeed Allah is the rich, the praised.", "তারা কৃপণ এবং লোকদের কৃপণ হতে উৎসাহ দেয়। কেউ মুখ ফিরিয়ে নিলেও ঈশ্বর ধনী, প্রশংসিত।"],
  "57:25": ["We have surely sent our rusul with clear proofs, and sent down with them the book and the scale, so that people may stand in equity; and We sent down the iron, in which is severe strength and benefit for people, and so that Allah may know who helps Allah and Allah's rusul in the unseen. Indeed Allah is powerful, mighty.", "আমরা আমাদের বার্তাবাহকদের স্পষ্ট প্রমানের সমর্থন দিয়ে পাঠিয়েছিলাম এবং আমরা তাদের কাছে নাজিল করেছিলাম ঐশীগ্রন্থ ও আইন যাতে লোকেরা ন্যায় বিচার প্রতিষ্ঠিত রাখতে পারে। আর আমরা পাঠিয়ে ছিলাম লোহা, যাতে রয়েছে শক্তি ও লোকদের জন্য অনেক উপকারিতা। এই সবকিছু ঈশ্বরের আলাদা করার জন্য তাদেরকে যারা তাঁকে ও তাঁর বার্তাবাহককে সমর্থন করা বেছে নেবে, অটল বিশ্বাস থেকে। ঈশ্বর ক্ষমতাধর, সর্ব শক্তিমান।"],
  "57:26": ["We have surely sent Nuh and Ibrahim, and placed Nabihood and the books among their descendants; some of them are guided, and many of them are rebellious.", "আমরা নুহ এবং ইব্রাহিমকে পাঠিয়েছিলাম, আর আমরা তাদের বংশধরদের প্রদান করেছিলাম নবুয়াত ও ঐশীগ্রন্থ। তাদের কেউ কেউ সুপথে ছিল, যখন অনেকেই ছিল অন্যায়কারী।"],
  "57:27": ["Then We followed in their tracks with our rusul, and We followed with Isa son of Maryam, and gave him the gospel, and placed in the hearts of those who followed him gentle mercy and mercy. And a monasticism they invented — We did not write it upon them — except as seeking the pleasure of Allah, yet they did not keep it with its due keeping. So We gave those of them who believed their reward, and many of them are rebellious.", "তাদের পরবর্তীতে, আমরা আমাদের বার্তাবাহকদের পাঠালাম । আমরা পাঠিয়েছিলাম মরিয়ম পুত্র ঈসাকে, এবং আমরা তাকে দিয়েছিলাম ইঞ্জিল, আর আমরা তার অনুসারীদের অন্তরে সমমর্মিতা ও দয়ার সঞ্চার করলাম। কিন্তু তারা বৈরাগ্যবাদ চালু করলো যা আমরা কখনই তাদের জন্য জারি করিনি। আমরা তাদেরকে কেবল ঈশ্বরের অনুমোদিত হুকুমসমূহ মেনে চলতে বলেছিলাম।  কিন্তু তারা বার্তা মেনে চলেনি যেমন ভাবে তাদের উচিৎ ছিল। পরিণামে, তাদের মধ্যে যারা বিশ্বাস করেছিল আমরা তাদেরকে তাদের প্রতিদান দিয়েছিলাম, যখন তাদের অনেকেই ছিল অন্যায়কারী।"],
  "57:28": ["O you who believe, be mindful of Allah and believe in Allah's Rasul; Allah will give you a double portion of Allah's mercy, and make for you a light by which you walk, and forgive you. And Allah is forgiving, merciful.", "হে তোমরা যারা বিশ্বাস করো, তোমরা ঈশ্বরকে ভক্তি করো এবং তাঁর বার্তাবাহককে বিশ্বাস করো। তাহলে তিনি তাঁর  দয়ায় তোমাদের জন্য দ্বিগুন পুরস্কার দিবেন, তোমাদেরকে পথ দেখাতে আলো দিয়ে অলংকৃত করবেন এবং তোমাদের ক্ষমা করবেন। ঈশ্বর ক্ষমাকারী, পরম দয়ালু।"],
  "57:29": ["So that the people of the book may know that they have power over nothing of the bounty of Allah, and that the bounty is in Allah's hand; Allah gives it to whom Allah wills, and Allah is the possessor of the great bounty.", "সুতরাং, পূর্ববর্তী ঐশীগ্রন্থের অনুসারীদের জানা উচিত যে তারা ঈশ্বরের দয়া ও করুণার একচ্ছত্র মালিক না এবং সকল করুণা ঈশ্বরের হাতে। তিনি যার উপর ইচ্ছা তা আরোপ করেন। ঈশ্বর সীমাহীন করুণার অধিকারী।"],
  "58:1": ["Allah has heard the words of the imra'a who disputes with you about her husband and complains to Allah. Allah hears your exchange with each other; truly Allah hears and sees.", "ঈশ্বর সে নারীর কথা শুনেছেন যে তার স্বামীর বিষয়ে তোমার সাথে বিতর্ক করেছিল, এবং ঈশ্বরের কাছে অভিযোগ করেছিল। তোমরা দুজনে যা আলোচনা করেছিলে ঈশ্বর এর সবকিছু শুনেছেন। ঈশ্বর শ্রবণকারী, দ্রষ্টা।"],
  "58:2": ["Those of you who declare of their nisa that they are not their mothers — their mothers are none but those who gave birth to them. Yet they say a disavowed word and a swerving one; yet Allah passes over and forgives.", "তোমাদের মধ্যে যারা তাদের স্ত্রীকে মা গন্য করে (তাদের সাথে যৌন সহবাস নিষিদ্ধ ঘোষণা করে আর) আলাদা থাকে, তারা ভালো করেই জানে যে তারা তাদের মা নয়। তাদের মা হলো সে নারী যে তাদের জন্ম দিয়েছিল। নিশ্চয়, তারা ধর্মনিন্দা ও মিথ্যাচার করছে। ঈশ্বর মার্জনাকারী, ক্ষমাকারী।"],
  "58:3": ["And those who declare of their nisa and then go back on what they said — then the freeing of a neck before the two touch one another. That is what you are admonished by, and Allah is aware of what you do.", "যারা এই পন্থায় স্ত্রীদের থেকে আলাদা থাকে, এরপর পুনর্মিলিত হয়, তারা যৌন সম্পর্ক পুনরায় শুরু করার পূর্বে একজন দাস মুক্ত করে প্রায়শ্চিত্ত করবে। এটি তোমাদেরকে জ্ঞান দিয়ে আলোকিত করার জন্যে। ঈশ্বর জানেন যাকিছু তোমরা করো।"],
  "58:4": ["So whoever does not find the means, then a fast of two consecutive months before the two touch one another; and whoever is unable, then feeding sixty of the poor. That is so that you may trust in Allah and the Rasul. And those are the limits of Allah, and for the kafirin there is a painful punishment.", "যদি তোমরা মুক্ত করার জন্য কোন দাস না পাও, যৌন সম্পর্ক পুনরায় শুরু করার পূর্বে টানা দুই মাস রোজা থাকবে। যদি তোমরা রোজা থাকতে না পার, তবে তোমরা ষাট জন গরীব লোককে খাওয়াবে। তোমরা ঈশ্বর ও তাঁর বার্তাবাহককে বিশ্বাস করবে। এগুলো ঈশ্বরের আইন। অবিশ্বাসীরা টেনে এনেছে এক যন্ত্রণাদায়ক শাস্তি।"],
  "58:5": ["Those who oppose Allah and the Rasul shall be brought low, just as those before them were brought low. We have already sent down clear signs, and for the kafirin there is a humiliating punishment.", "নিশ্চয়, যারা ঈশ্বর ও তাঁর বার্তাবাহকের বিরুদ্ধে লড়াই করে তারা পরাজিত হয়, যেমন তাদের পূর্ববর্তী অনুরূপ ব্যক্তিরা পরাজিত হয়েছিল। আমরা স্পষ্ট প্রমাণাদি অবতীর্ণ করেছি, আর প্রত্যাখ্যানকারীরা টেনে এনেছে এক লজ্জাজনক শাস্তি।"],
  "58:6": ["On the day Allah raises them all together, then tells them what they did. Allah counted it while they forgot it, and Allah is witness over all things.", "সে দিন আসবে যখন ঈশ্বর তাদের সকলকে পুনরুত্থিত করবেন, এরপর তাদের জানাবেন যা কিছু তারা করেছিল। ঈশ্বর সবকিছু লিপিবদ্ধ করেছেন, যদিও তারা তা ভুলে গেছে। ঈশ্বর সবকিছু প্রত্যক্ষ করেন।"],
  "58:7": ["Do you not see that Allah knows what is in the heavens and what is in the earth? No private talk of three takes place but Allah is the fourth of them, and no private talk of five but Allah is the sixth of them, and nothing less than that or more but Allah is with them wherever they are. Then Allah will tell them what they did on the day of standing. Truly Allah knows all things.", "তুমি কি অনুধাবন করো না যে ঈশ্বর আকাশমণ্ডলী ও পৃথিবীর সবকিছু জানেন? কোন তিন ব্যক্তি গোপন চক্রান্ত করতে পারে না তাঁকে ছাড়া- তাদের চতুর্থ ব্যক্তি হিসেবে, না পাঁচ ব্যক্তি তাঁকে ছাড়া - তাদের ষষ্ঠ ব্যক্তি হিসাবে, না এর চেয়ে কম, না এর বেশি হিসেবে, সেখানে তাদের সাথে তিনি থাকেন যেখানেই তারা থাকুক না কেন। অতঃপর, পুনরুত্থান দিনে, তিনি তাদের জানাবেন যাকিছু তারা করেছিল। ঈশ্বর সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "58:8": ["Do you not see those who were forbidden from private talk, yet they go back to what they were forbidden from, and whisper together in sin and hostility and disobedience to the Rasul? And when they come to you, they greet you with what Allah never greeted you with, and they say to themselves: why does Allah not punish us for what we say? Sufficient for them is Jahannam — they enter it. How evil an arrival.", "তুমি কি তাদের লক্ষ্য করেছো যাদেরকে নিষেধ করা হয়েছিল গোপনে চক্রান্ত করতে, এরপর চক্রান্তে জেদ ধরে থাকে? তারা চক্রান্ত করে পাপ, সীমালঙ্ঘন ও বার্তাবাহকের অবাধ্যতা করতে। যখন তারা তোমার কাছে আসে, তারা তোমাকে অভিবাদন জানায়, ঈশ্বর যা জারি করেছেন তা ব্যতীত অন্য এক অভিবাদন দিয়ে। তারা নিজেরা মনে মনে বলে, “আমাদের কথার জন্য ঈশ্বর আমাদের শাস্তি দেবেন না।” জাহান্নাম হল তাদের একমাত্র প্রতিফল, যেখানে তারা জ্বলবে; কি এক শোচনীয় ভাগ্য।"],
  "58:9": ["O you who trust, when you whisper together, do not whisper in sin and hostility and disobedience to the Rasul, but whisper in goodness and mindfulness. And be mindful of Allah, to whom you shall be gathered.", "হে যারা বিশ্বাস কর, যদি তোমাদের গোপনে পরামর্শ করতে হয়, তবে তোমরা পাপ, সীমালঙ্ঘন ও বার্তাবাহককে অমান্য করতে পরামর্শ করো না। তোমরা সৎকর্ম ও পূন্য করার জন্য পরামর্শ কর। তোমরা ঈশ্বরকে ভক্তি করো, যার সামনে তোমাদের একত্রিত করা হবে।"],
  "58:10": ["Private talk is only from Shaytan, to grieve those who trust; yet it harms them nothing except by Allah's leave. And upon Allah let the trusting place their trust.", "গোপন চক্রান্ত শয়তানের ধারণা, যারা দ্বারা সে তাদের ক্ষতি করতে চায় যারা বিশ্বাস করেছে। কিন্তু, সে তাদেরকে ঈশ্বরের ইচ্ছার বিরুদ্ধে ক্ষতি করতে পারে না। বিশ্বাসীরা ঈশ্বরে আস্থা রাখবে।"],
  "58:11": ["O you who trust, when you are told to make room in the gatherings, then make room; Allah will make room for you. And when it is said rise up, then rise up. Allah raises up those among you who trust, and those given knowledge, by degrees; and Allah is aware of what you do.", "হে যারা বিশ্বাস করো, যদি তোমাদের বলা হয়, “দয়া করে জায়গা দাও, ” তোমরা পরস্পরকে বসার জন্য জায়গা দেবে। ঈশ্বর তবে তোমাদের জন্য জায়গা তৈরি করবেন। যদি তোমাদের বলা হয় জেগে উঠো এবং এগিয়ে যাও, জেগে উঠবে এবং এগিয়ে যাবে। তোমাদের মধ্যে যারা বিশ্বাস করে, আর যারা জ্ঞানার্জন করে ঈশ্বর তাদেরকে উচ্চ পদমর্যাদায় উন্নীত করেন। তোমরা যাকিছু করো ঈশ্বর সে সম্পর্কে সম্পূর্ণ অবগত।"],
  "58:12": ["O you who trust, when you whisper with the Rasul, offer ahead of your whisper a donation. That is better for you and purer. And if you do not find the means, then Allah is forgiving, merciful.", "হে তোমরা যারা বিশ্বাস করো, যখন তোমরা বার্তাবাহকের সাথে আলোচনা করতে চাও, তোমরা তা করার পূর্বে (গরিবদের) দান করবে। এটি তোমাদের জন্য উত্তম ও পবিত্রতর। যদি তোমরা তা করতে সমর্থ না হও, তবে ঈশ্বর ক্ষমাশীল, পরম দয়ালু।"],
  "58:13": ["Were you in awe of offering ahead of your whispers donations? So, since you did not do it and Allah relented toward you, then establish the prayer, and give the alms, and obey Allah and the Rasul; and Allah is aware of what you do.", "যদি তোমরা আলোচনা করার পূর্বে দান করতে ব্যর্থ হও, তারপর অনুশোচনা করো, ঈশ্বর তোমাদের অনুশোচনা গ্রহন করেন। তোমরা সংযোগ প্রার্থনা (সালাত) পালন করো, যাকাত আদায় করো এবং ঈশ্বর ও তাঁর বার্তাবাহককে মান্য করো। তোমরা যা কিছু করো ঈশ্বর সে বিষয়ে সম্পূর্ণ অবগত।"],
  "58:14": ["Do you not see those who turn toward a people upon whom Allah's wrath rests? They are neither of you nor of them, and they swear to the falsehood while they know.", "তুমি কি তাদের লক্ষ্য করেছো যারা সেসব লোকদের বন্ধু বানায় যাদের উপর ঈশ্বর রাগান্বিত? তারা না তোমার সাথে, না তাদের সাথে। তারা জেনে-শুনে মিথ্যা শপথ করে!"],
  "58:15": ["Allah has prepared for them a severe punishment; evil indeed is what they used to do.", "ঈশ্বর তাদের জন্য কঠোর শাস্তি প্রস্তুত রেখেছেন। নিশ্চয় শোচনীয় যা তারা করে চলেছে।"],
  "58:16": ["They took their oaths as a shield, and turned others away from the path of Allah; so for them there is a humiliating punishment.", "তারা তাদের শপথকে ঈশ্বরের পথে বাধা দেবার উপায় হিসেবে ব্যবহার করে। পরিণামে, তারা টেনে এনেছে এক লজ্জাজনক শাস্তি।"],
  "58:17": ["Nor will their wealth or their children avail them anything against Allah. Those are the companions of the fire; they abide in it forever.", "না তাদের অর্থ, না তাদের সন্তানেরা ঈশ্বরের বিরুদ্ধে তাদের সাহায্য করবে। তারা টেনে এনেছে নরকাগ্নি, যেখানে তারা চিরকাল বাস করে।"],
  "58:18": ["On the day Allah raises them all together, they will swear to Allah as they swear to you, and they think they stand upon something. Truly they — they are the kazibin.", "সে দিন আসবে যখন ঈশ্বর তাদের সকলকে পূনরুত্থিত করবেন। তারা তখন তাঁর কাছে শপথ করবে, ঠিক যেমন এখন তারা তোমাদের কাছে শপথ করে, এই ভেবে যে তারা আসলেই সঠিক! নিশ্চয়, তারাই আসল মিথ্যাবাদী।"],
  "58:19": ["Shaytan gained mastery over them and made them forget the remembrance of Allah. Those are the party of Shaytan. Truly the party of Shaytan — they are the khasirin.", "শয়তান তাদের উপর ভর করেছে, এবং তাদেরকে দিয়ে ঈশ্বরের বার্তা অবজ্ঞা করিয়েছে।  এরাই শয়তানের দল। নিঃসন্দেহে, শয়তানে দল পরাজিত।"],
  "58:20": ["Those who oppose Allah and the Rasul — those are among the abased.", "নিশ্চয়, যারা ঈশ্বর ও তাঁর বার্তাবাহকের বিরোধিতা করে তারা হবে নিম্নতমদের সাথে।"],
  "58:21": ["Allah has written: I and the rusul of Allah shall surely overcome. Truly Allah is strong, mighty.", "ঈশ্বর আইন জারি করেছেনঃ “ আমি ও আমার বার্তাবাহকরা অবশ্যই জয়ী হব।”"],
  "58:22": ["You will not find a people who trust in Allah and the last day showing affection to those who oppose Allah and the Rasul, even if they are their fathers or their sons or their brothers or their kin. Those are the ones in whose hearts trust is written, and whom Allah strengthened with a spirit from Allah. And Allah will enter them into gardens beneath which rivers flow, to abide therein forever. Allah is pleased with them and they are pleased with Allah. Those are the party of Allah. Truly the party of Allah — they are the ones who attain success.", "যারা ঈশ্বর ও শেষ দিনে বিশ্বাস করে তুমি সে লোকদের বন্ধুত্ব করতে দেখবে না তাদের সাথে যারা ঈশ্বর ও তাঁর বার্তাবাহকের বিরোধিতা করে, এমনকি যদিও তারা তাদের পিতামাতা, অথবা তাদের সন্তান, অথবা তাদের ভাই-বোন, অথবা তাদের গোত্র হয়। এদের জন্য, তিনি তাদের হৃদয়ে বিশ্বাস স্থাপিত করেন, এবং তাঁর পক্ষ থেকে  প্রেরণা দিয়ে তাদের সমর্থন দেন, এবং তাদেরকে প্রবেশ করান প্রবাহিত ঝর্ণা সহ বাগানে যেখানে তারা চিরকাল বাস করে। ঈশ্বর তাদের প্রতি সন্তুষ্ট এবং তারাও  তাঁর প্রতি সন্তুষ্ট। এরাই ঈশ্বরের দল। অবশ্যই, ঈশ্বরের দলই জয়ী।"],
  "59:1": ["Whatever is in the heavens and whatever is on the earth glorifies Allah, and Allah is the Mighty, the Wise.", "ঈশ্বরের মহিমা ঘোষণা করছে আকাশমণ্ডলী ও পৃথিবীর সবকিছু, এবং তিনি সর্বশক্তিমান, সবচেয়ে প্রজ্ঞাবান।"],
  "59:2": ["It is Allah who drove out those who kafara among the people of the Book from their dwellings at the first gathering. You did not think they would leave, and they thought their fortresses would hold them back from Allah; but Allah came upon them from where they did not reckon, and cast terror into their hearts. They tore down their houses with their own hands and with the hands of the muminin; so take lesson, O people of vision.", "তিনিই সে সত্ত্বা যিনি ঐশ্বীগ্রন্থের লোকদের মধ্যে যারা অবিশ্বাস করেছিল তাদেরকে তাদের ঘর থেকে একসাথে উচ্ছেদ করেছিলেন। তোমরা কখনো ধারনা করোনি যে তারা প্রস্থান করবে, আর তারা ভেবেছিল যে তাদের প্রস্তুতি ঈশ্বর থেকে তাদের রক্ষা করবে। কিন্তু এরপর ঈশ্বর তাদের কাছে এমনভাবে আসলেন যা তারা কখনো আশা করেনি, আর তাদের হৃদয়ে আতংক ছুঁড়ে দিয়েছিলেন। তাই, তারা তাদের ঘর-বাড়ি ত্যাগ করেছিল স্বেচ্ছায়, তদুপরি বিশ্বাসীদের চাপে। এর থেকে তোমাদের শিক্ষা নেয়া উচিত, হে তোমরা যারা দূরদর্শিতার অধিকারী।"],
  "59:3": ["Had Allah not decreed exile upon them, Allah would have punished them in this world; and they have in the hereafter the punishment of the Fire.", "ঈশ্বর যদি তাদের যেতে বাধ্য না করতেন, তিনি হয়তো তাদেরকে  (চলে যেতে বাধ্য করার চেয়েও অধিকতর মন্দ) প্রতিদান এই জীবনে দিতেন। পরকালে তিনি তাদের নরকের শাস্তি দেবেন।"],
  "59:4": ["That is because they opposed Allah and Allah's Rasul; and whoever opposes Allah should know that Allah is severe in punishment.", "এটি এই কারনে যে তারা ঈশ্বর ও তাঁর বার্তাবাহকের বিরোধিতা করেছিল। যারা ঈশ্বর ও তাঁর বার্তাবাহকের বিরোধিতা করে, ঈশ্বর তাদের জন্য শাস্তি প্রয়োগে অত্যন্ত কঠোর।"],
  "59:5": ["Whatever palm-trees you cut down or left standing on their roots, it was by Allah's leave, so that Allah might disgrace the defiant.", "তোমরা কোন গাছ কাট, অথবা একে এর কাণ্ডের উপর দাড়িয়ে থাকতে দাও, তা ঈশ্বরের ইচ্ছা অনুসারে হয়। তিনি অবশ্যই অন্যায়কারীদের অপমানিত করবেন।"],
  "59:6": ["And whatever Allah turned back to Allah's Rasul from them, you charged against it neither horses nor riding mounts; rather, Allah sets Allah's rusul over whom Allah wills, and Allah has power over all things.", "যাকিছু ঈশ্বর তাঁর বার্তাবাহকের জন্য ফিরিয়ে দিয়েছিলেন তা তোমাদের যুদ্ধ প্রচেষ্টার ফল ছিল না, তা তোমরা ঘোড়ার উপর লড়াই করে থাকো অথবা পায়ের উপর। ঈশ্বরই সে সত্ত্বা যিনি যার জন্য ইচ্ছা তার বিরুদ্ধে তাঁর বার্তাবাহকদের পাঠান। ঈশ্বর সর্বশক্তিমান।"],
  "59:7": ["And whatever Allah turns back to the Rasul from the people of the towns belongs to Allah and to the Rasul, and to near kin, to orphans, to the needy, and to the wayfarer, so that it may not keep circulating among the rich among you. And whatever the Rasul gives you, take it; and whatever the Rasul forbids you, refrain from it. And be mindful of Allah; truly Allah is severe in punishment.", "যাকিছু ঈশ্বর (পরাজিত) সম্প্রদায়গুলো থেকে তাঁর বার্তাবাহককে ফিরিয়ে দেন তা ঈশ্বর এবং তাঁর বার্তাবাহকের কাছে যাবে (দান হিসাবে)। তোমরা তা আত্মীয়-স্বজন, এতিম, গরীব ও ভ্রমণরত বিদেশীদের দাও। এভাবে, এটি তোমাদের শক্তিশালীদের একচেটিয়া অধিকারে থাকবে না। তোমাদেরকে বার্তাবাহকের দেয়া যুদ্ধলব্ধ সম্পদ তোমরা রাখতে পার, কিন্তু যা তিনি তোমাদের নিতে নিষেধ করেন তা নিও না। তোমরা ঈশ্বরকে ভক্তি কর। ঈশ্বর শাস্তি প্রদানে কঠোর।"],
  "59:8": ["It is for the needy muhajirin who were driven out of their dwellings and their possessions, seeking bounty from Allah and approval, and helping Allah and Allah's Rasul. Those are the true ones.", "সে অভাবিদের (তোমরা দিবে) যারা দেশত্যাগ করেছিল। তাদেরকে তাদের বাড়ি থেকে উচ্ছেদ করা হয়েছিল আর তাদের ভূসম্পত্তি থেকে বঞ্চিত করা হয়েছিল কারন তারা ঈশ্বরের করুণা ও সন্তুষ্টি অন্বেষণ করতো, এবং কারন তারা ঈশ্বর ও তাঁর বার্তাবাহককে সমর্থন করেছিল। এরাই সত্যবাদী।"],
  "59:9": ["And those who settled in the dwelling and in faith before them love whoever emigrates to them, and they find no want in their hearts for what they were given, and they prefer others above themselves, even though need be upon them. And whoever is preserved from the stinginess of their own soul — those are the ones who attain success.", "আর যারা তাদেরকে ঘর ও আশ্রয় দিয়েছিল, এবং তাদের পূর্ব থেকেই বিশ্বাসী ছিল, তারা তাদেরকে ভালোবাসে যারা দেশত্যাগ করে তাদের কাছে এসেছিল, এবং তাদেরকে সাহায্য করায় তাদের হৃদয়ে কোন সংশয় বোধ করে না। প্রকৃতপক্ষে, তারা অনায়াসে নিজেদের চেয়ে তাদেরকে অগ্রাধিকার দেয়, এমনকি তারা তা দিয়ে দেয় যা তাদেরই প্রয়োজন। নিশ্চয়, যারা তাদের সহজাত কৃপণতাকে জয় করতে পারে তারাই সফলকাম।"],
  "59:10": ["And those who came after them say: Our Rabb, forgive us and our brothers who preceded us in faith, and place no rancor in our hearts toward those who believe. Our Rabb, truly Allah is gentle in mercy and mercy-giving.", "যারা তাদের পর বিশ্বাসী হয়েছিল তারা বলে, “আমাদের প্রভু, ক্ষমা করুন আমাদের ও আমাদের ভাইদের যারা বিশ্বাসে আমাদের অগ্রণী এবং আমাদের হৃদয়কে রক্ষা করুন তাদের বিরুদ্ধে কোন ঘৃণা পোষণ করা থেকে যারা বিশ্বাস করেছে।  আমাদের প্রভু,  আপনি দয়াবান, পরম করুণাময়।”"],
  "59:11": ["Have you not regarded the munafiqin saying to their brothers among the people of the Book who kafara: If you are driven out, we will surely go out with you, and we will never obey anyone against you; and if you are fought against, we will surely help you. And Allah bears witness that they are truly liars.", "তুমি কি তাদের লক্ষ্য করেছো যারা ভণ্ডামি নামক মহামারীতে আক্রান্ত, এবং কেমন করে তারা বলেছিল ঐশীগ্রন্থের লোকদের যারা অবিশ্বাসে তাদের সঙ্গী, “যদি তোমাদের উচ্ছেদ করা হয় আমরাও তোমাদের সাথে বের হয়ে যাব, এবং কখনো এমন কাউকে মানবো না যারা তোমাদের বিরোধিতা করে। যদি কেউ তোমাদের সাথে লড়াই করে, আমরা তোমাদের হয়ে লড়াই করবো।” ঈশ্বর সাক্ষ্য দেন যে তারা মিথ্যাবাদী।"],
  "59:12": ["If they are driven out, they will not go out with them; and if they are fought against, they will not help them; and even if they help them, they will surely turn their backs, and then they will find no help.", "প্রকৃতপক্ষে, যদি তাদের উচ্ছেদ করা হতো, তারা তাদের সাথে বের হতো না, এবং যদি কেউ তাদের সাথে লড়াই করতো, তারা তাদের সমর্থণ দিতো না। এমনকি তারা সমর্থন দিলেও, তারা মুখ ফিরিয়ে নিতো এবং পালিয়ে যেতো। তারা কখনো জয়ী হতে পারতো না।"],
  "59:13": ["You are indeed a greater dread in their hearts than Allah. That is because they are a people who do not understand.", "নিশ্চয়, তোমরা তাদের হৃদয়ে আরো বেশি আতংক সঞ্চার করো তাদের ঈশ্বর ভীতির চেয়ে। এটি এই কারনে যে তারা সেসব লোক যারা অনুধাবন না।"],
  "59:14": ["They will not fight you all together except in fortified towns or from behind walls. Their might among themselves is severe; you reckon them united, yet their hearts are diverse. That is because they are a people who do not reason.", "তারা তোমাদের সাথে লড়াই করতে মিলিত হয় না যদিনা তারা সুরক্ষিত দালানে, অথবা দেয়ালের আড়ালে থাকে। তাদের কাছে নিজেদের শক্তিকে দুর্দান্ত মনে হয়। তুমি হয়তো ভাববে যে তারা ঐক্যবদ্ধ, আসলে তাদের হৃদয়গুলো বিভক্ত। এটি এই কারনে যে তারা সেসব লোক যারা বোঝে না।"],
  "59:15": ["They are like those who came shortly before them: they tasted the heavy cost of their course, and they have a painful punishment.", "তাদের ভাগ্য তাদের অনুরূপ ব্যক্তিদের মত যারা তাদের পূর্ববর্তী ছিল।  তারা তাদের সিদ্ধান্তের পরিণাম ভোগ করেছিল। তারা নিজেদের উপর টেনে এনেছে এক যন্ত্রণাদায়ক শাস্তি।"],
  "59:16": ["Like the satan when it said to the human: Disbelieve. And when the human kafara, it said: I disown you; I fear Allah, Rabb of the worlds.", "তারা শয়তানের মতঃ যে মানবজাতিকে বলে, “অবিশ্বাস করো,” এরপর সে অবিশ্বাস করা মাত্র, সে বলে, “আমি তোমাকে অস্বীকার করছি। আমি মহাবিশ্মের প্রভু ঈশ্বরকে ভয় করি।”"],
  "59:17": ["So the end of them both is that they are in the Fire, abiding in it forever; and that is the recompense of the wrongdoers.", "তাদের উভয়ের নিয়তি নরকাগ্নি, যেখানে তারা চিরকাল বাস করে। সীমালঙ্ঘনকারীদের জন্য এটাই প্রতিফল।"],
  "59:18": ["O you who believe, be mindful of Allah, and let every soul look to what it has sent ahead for the morrow. And be mindful of Allah; truly Allah is fully aware of what you do.", "হে যারা বিশ্বাস কর, তোমরা ঈশ্বরকে ভক্তি কর, এবং প্রত্যেক আত্মা যাচাই করে দেখুক যে সে কি করেছে আগামীকালের জন্য। তোমরা ঈশ্বরকে ভক্তি কর, তোমরা যাকিছু কর ঈশ্বর সে সম্পর্কে সম্পূর্ণ অবগত।"],
  "59:19": ["And do not be like those who forgot Allah, so Allah made them forget themselves. Those are the defiant.", "তাদের মত হইও না যারা ঈশ্বরকে ভুলে গিয়েছিল, তাই তিনি তাদের নিজেদের ভুলিয়ে দিয়েছিলেন। এরাই অন্যায়কারী।"],
  "59:20": ["Not equal are the companions of the Fire and the companions of the Garden. The companions of the Garden are the winners.", "নরকাগ্নি এবং স্বর্গের বাসিন্দারা সমান নয়; স্বর্গের বাসিন্দারা বিজয়ী।"],
  "59:21": ["If We had sent down this recitation upon a mountain, you would have seen it humbled, splitting apart from awe of Allah. And these are the likenesses We strike for the people, so that they may reflect.", "যদি আমরা এই কুরআনকে কোন পর্বতের উপর নাজিল করতাম, তুমি একে দেখতে কাঁপতে কাঁপতে টুকরো হয়ে যাচ্ছে, ঈশ্বরের প্রতি ভক্তিতে। আমরা লোকদের জন্য এই উদাহরণগুলো দেই, যাতে তারা ভেবে দেখে।"],
  "59:22": ["That is Allah: there is no ilah but Allah, the Knower of the hidden and the witnessed. Allah is the Compassionate, the Raheem.", "তিনিই সে এক ঈশ্বর; তাঁর পাশে অন্য কোন উপাস্য নেই। সকল গোপন ও প্রকাশ্য বিষয় জানেন। তিনি সবচেয়ে করুনাময়, সবচেয়ে দয়ালু।"],
  "59:23": ["That is Allah: there is no ilah but Allah — the Sovereign, the Holy, the Peace, the Giver of faith, the Watcher, the Mighty, the Overpowering, the Most High. Allah is exalted far above what they associate.", "তিনিই সে এক ঈশ্বর; তাঁর পাশে অন্য কোন উপাস্য নেই। রাজা, সবচেয়ে পবিত্র, শান্তি, সবচেয়ে বিশ্বস্ত, সর্বোচ্চ, সর্বশক্তিমান, সবচেয়ে শক্তিধর, সবচেয়ে সন্মানিত। মহিমা ঈশ্বরের, অংশীদার থাকা থেকে অনেক ঊর্ধ্বে।"],
  "59:24": ["That is Allah, the Creator, the Bringer-forth, the Former. To Allah belong the most beautiful names. Whatever is in the heavens and the earth glorifies Allah, and Allah is the Mighty, the Wise.", "তিনিই সে এক ঈশ্বর; সৃষ্টিকর্তা, সূচনাকারী, নকশাকারী। সবচেয়ে সুন্দর নামগুলো তাঁর। আকাশমণ্ডলী ও পৃথিবীর সবকিছু তাঁর মহিমা ঘোষণা করে। তিনি সর্বশক্তিমান, সবচেয়ে প্রজ্ঞাবান।"],
  "60:1": ["O you who believe, do not take My enemy and your enemy as allies, offering them affection, when they have kafara in the truth that came to you and drove out the Rasul and you for believing in Allah your Rabb. If you went out striving your utmost in My way and seeking My pleasure, do you then show them affection in secret, when I know what you conceal and what you make open? Whoever of you does that has strayed from the right way.", "হে তোমরা যারা বিশ্বাস কর, তোমরা বন্ধু  করো না আমার শত্রু এবং তোমাদের শত্রুদের, তাদের প্রতি ভালোবাসা ও বন্ধুত্বের হাত প্রসারিত করে দিয়ে, তা সত্ত্বেও যে তারা সেই সত্যে অবিশ্বাস করেছে যা তোমাদের কাছে এসেছে। তারা বার্তাবাহক ও তোমাদের প্রতি অত্যাচার করে শুধু এই কারনে যে তোমরা বিশ্বাস করো তোমাদের প্রভু ঈশ্বরকে। যদি তোমরা আমার পথে সংগ্রামের জন্য একত্রিত হও, আমার অনুগ্রহ সন্ধানে, তবে কেমন  করে গোপনে তোমরা তাদের ভালবাসতে পার? আমি পুরোপুরি অবগত যা তোমরা লুকাও আর যা তোমরা প্রকাশ করো। তোমাদের মধ্যে যারা তা করে তারা নিশ্চয় সঠিক পথ থেকে বিচ্যুত হয়েছে।"],
  "60:2": ["If they overtake you they will be enemies to you, and they will stretch out toward you their hands and their tongues with evil, and they wish that you would disbelieve.", "যখনি তারা তোমাদের মুখোমুখি হয়, তারা তোমাদের সাথে শত্রুর মত আচরণ করে, এবং তোমাদের আঘাত করে তাদের হাত ও তাদের জিহবা দিয়ে। তারা চায় তোমরা অবিশ্বাস করো।"],
  "60:3": ["Neither your kin nor your children will ever benefit you on the Day of Standing; Allah will decide between you, and Allah sees what you do.", "তোমাদের আত্মীয়-স্বজন এবং তোমাদের অর্থ কখনো তোমাদের সাহায্য করতে পারে না। পুনরুত্থান দিনে, তিনি তোমাদের মাঝে বিচার করবেন। ঈশ্বর দেখেন যা কিছু তোমরা করো।"],
  "60:4": ["There has been a good pattern for you in Ibrahim and those with him, when they said to their people: We are clear of you and of what you worship besides Allah; we reject you, and enmity and hatred have shown openly between us and you forever, until you believe in Allah alone. Except for the word of Ibrahim to his father: I will surely ask forgiveness for you, though I possess nothing from Allah for you. Our Rabb, upon You we rely, and to You we turn back, and to You is the arrival.", "তোমাদের জন্য রয়েছে ইব্রাহিম ও তার সাথীদের দারা স্থাপিত একটি ভাল উদাহরণ। তারা তাদের লোকদের বলেছিল, “আমরা তোমাদের এবং সে উপাস্যদের প্রত্যাখ্যান করি যাদেরকে তোমরা ঈশ্বরের পাশে উপাসনা করো। আমরা তোমাদের অভিযুক্ত করি, এবং তোমরা  আমাদের থেকে শত্রুতা ও ঘৃণা ছাড়া কিছু দেখবে না যতক্ষণ পর্যন্ত না তোমরা এক ঈশ্বরে বিশ্বাস কর।” কিন্তু, ইব্রাহীমের একটি ভুল হয়েছিল যখন সে তার পিতাকে বলেছিল, “আমি তোমার ক্ষমার জন্য প্রার্থনা করবো, কিন্তু আমার কোন ক্ষমতা নেই ঈশ্বর থেকে তোমাকে রক্ষা করার।”  “আমাদের প্রভু, আমরা আপনার উপর আস্থা রাখি এবং আপনার নিকট আত্মসমর্পণ করি; আপনার কাছেই চূড়ান্ত নিয়তি।"],
  "60:5": ["Our Rabb, do not make us a trial for those who disbelieve, and forgive us, our Rabb; You are the Mighty, the Wise.", "“আমাদের প্রভু, অবিশ্বাসীদের দ্বারা আমাদের নিপীড়িত হতে দিয়েন না, এবং আমাদের ক্ষমা করুন। আপনি সর্বশক্তিমান, সবচেয়ে প্রজ্ঞাবান”।"],
  "60:6": ["There was a good pattern in them for you, for whoever hopes for Allah and the Last Day; and whoever turns away, Allah is the Self-Sufficient, the Praised.", "যারা ঈশ্বর ও শেষ দিনকে চায় তাদের জন্য একটি ভাল উদাহরণ স্থাপিত আছে। আর তাদের ক্ষেত্রে যারা মুখ ফিরিয়ে নেয়, (তাদেরকে) ঈশ্বরের কোন প্রয়োজন নেই, সবচেয়ে প্রশংসিত।"],
  "60:7": ["Perhaps Allah will place affection between you and those among them whom you counted as enemies, and Allah is Able, and Allah is Forgiving, Raheem.", "ঈশ্বর হয়তো তোমাদের ও তাদের মধ্যে শত্রুতাকে ভালোবাসায় পরিবর্তিত করে দেবেন। ঈশ্বর সর্বশক্তিমান। ঈশ্বর ক্ষমাশীল, সবচেয়ে করুণাময়।"],
  "60:8": ["Allah does not forbid you, regarding those who have not killed you in religion nor driven you from your homes, that you be good to them and act with equity toward them; Allah loves the equitable.", "ঈশ্বর তোমাদের নিষেধ করেন না তাদের সাথে বন্ধুসুলভ হতে যারা ধর্ম নিয়ে তোমাদের সাথে লড়াই করে না, এবং তোমাদেরকে তোমাদের ঘর থেকে উচ্ছেদ করে না। তোমরা তাদের সাথে বন্ধুসুলভ হতে পারো এবং তাদের প্রতি ন্যায়পরায়ণ হও। ঈশ্বর  ন্যায়পরায়ণদের ভালোবাসেন।"],
  "60:9": ["Allah only forbids you from taking as allies those who killed you in religion, drove you from your homes, and backed your expulsion; and whoever takes them as allies, those are the wrongdoers.", "ঈশ্বর তোমাদেরকে শুধু তাদের সাথে বন্ধুসুলভ হতে নিষেধ করেন যারা তোমাদের সাথে যুদ্ধ করে ধর্ম নিয়ে, তোমাদেরকে তোমাদের ঘর থেকে উচ্ছেদ করে,  এবং তোমাদের নির্বাসিত করতে অন্যদের সাথে সঙ্ঘবদ্ধ হয়। তোমরা তাদের সাথে বন্ধুসুলভ হবে না। যারা তাদের সাথে বন্ধুসুলভ হয় তারা সীমালঙ্ঘনকারী।"],
  "60:10": ["O you who believe, when believing nisa come to you as muhajirin, test them; Allah knows best their faith. If you know them to be believing, do not send them back to the kafirin; they are not lawful for them, nor are they lawful for them. And give them what they spent. There is no blame on you if you marry them, once you have given them their rewards, and do not hold fast to the marriage bonds of the kafirin. Ask for what you spent, and let them ask for what they spent; that is the decree of Allah — Allah judges between you, and Allah is Knowing, Wise.", "হে যারা বিশ্বাস করো, যখন বিশ্বাসী নারীরা (শত্রুদের পরিত্যাগ করে আর) তোমাদের কাছে আশ্রয় চায়, তোমরা তাদের পরীক্ষা করো। ঈশ্বর তাদের বিশ্বাস সম্পর্কে পূর্ণ অবগত। যদি তোমরা একবার নিশ্চিত করো যে তারা বিশ্বাসী, তোমরা অবিশ্বাসীদের কাছে তাদের ফেরত পাঠাবে না। তারা বৈধ নয় তাদের সাথে বিবাহ বন্ধনে আবদ্ধ থাকতে, না অবিশ্বাসীরা অনুমোদিত তাদের বিয়ে করতে। অবিশ্বাসীরা যে মোহরানা দিয়েছে তা ফিরিয়ে দাও। তাদের বিয়ে করে তোমরা কোন ভুল করো না, যদি না তোমরা তাদেরকে তাদের প্রাপ্য মোহরানা পরিশোধ কর। অবিশ্বাসী স্ত্রীদের রেখো না (যদি তারা শত্রুদের সাথে যোগ দিতে চায়)। তোমরা তাদের কাছে সে মোহরানা চাইতে পার যা তোমরা পরিশোধ করেছিলে, এবং তারা তা চাইতে পারে যা তারা দিয়েছিল। এটা ঈশ্বরের নিয়ম, তিনি তোমাদের মধ্যে শাসন করেন। ঈশ্বর সর্বজ্ঞ, সবচেয়ে প্রজ্ঞাবান।"],
  "60:11": ["And if anything of your nisa slips away to the kafirin, and you then settle the score, give those whose nisa have gone the like of what they spent. And be mindful of Allah, the One you believe in.", "যদি তোমাদের কারো স্ত্রী শত্রু শিবিরে যোগ দেয়, এবং তোমরা লড়াই করতে বাধ্য হও, তোমরা শত্রুদের বাধ্য করবে সে লোকদের ক্ষতিপূরণ দিতে যারা তাদের স্ত্রীদের হারিয়েছিল, তাদেরকে তা দিয়ে যা তারা তাদের স্ত্রীদের জন্য খরচ করেছিল। তোমরা ঈশ্বরকে ভক্তি করবে, যার উপর তোমরা বিশ্বাস করো।"],
  "60:12": ["O Prophet, when believing nisa come to you pledging that they will associate nothing with Allah, will not steal, will not commit adultery, will not kill their children, will not bring a slander they fabricate between their hands and their legs, and will not disobey you in what is recognized as good — then accept their pledge and seek forgiveness for them from Allah. Allah is Forgiving, Raheem.", "হে নবী, যখন বিশ্বাসী নারীরা (যারা অবিশ্বাসীদের পরিত্যাগ করেছে) তোমার কাছে আশ্রয় অন্বেষণ চায়, তোমার কাছে অঙ্গীকার করে যে তারা ঈশ্বরের পাশে অন্য উপাস্য স্থাপন করবে না, না চুরি করবে, না ব্যাভিচার করবে, না তাদের সন্তানদের হত্যা করবে, না কোন মিথ্যা উদ্ভাবন করবে, না তোমার ন্যায়নিষ্ঠ হুকুম অমান্য করবে, তুমি তাদের অঙ্গীকার গ্রহন কর, এবং ঈশ্বরের কাছে তাদের ক্ষমার জন্য প্রার্থনা কর । ঈশ্বর ক্ষমাশীল, পরম করুণাময়।"],
  "60:13": ["O you who believe, do not take as allies a people upon whom the wrath of Allah has fallen, who have despaired of the Hereafter just as the kafirin have despaired of the companions of the graves.", "হে যারা বিশ্বাস কর, তাদের সাথে বন্ধুসুলভ হইও না যাদের প্রতি ঈশ্বর রাগান্বিত, এবং যারা অবিশ্বাসে আশাহীন ভাবে আটকে আছে; তারা ঠিক তেমন আশাহীন যেমন আশাহীন সেই অবিশ্বাসীরা যারা ইতিমধ্যে কবরের মধ্যে আছে।"],
  "61:1": ["All that is in the heavens and all that is in the earth glorifies Allah, and Allah is the Almighty, the Wise.", "আকাশমণ্ডলী ও পৃথিবীর সবকিছু ঈশ্বরের মহিমা ঘোষণা করছে। তিনি সর্বশক্তিমান, সবচেয়ে প্রজ্ঞাবান।"],
  "61:2": ["O you who believe, why do you say what you do not do?", "হে যারা বিশ্বাস কর, কেন তোমরা বল যা তোমরা কর না?"],
  "61:3": ["It is a matter of great loathing to Allah that you say what you do not do.", "ঈশ্বরের কাছে সবচেয়ে ঘৃণিত বিষয় হলো তোমাদের বলা যা তোমরা কর না।"],
  "61:4": ["Indeed, Allah loves those who fight in the way of Allah in ranks, as if they were a solid, well-compacted structure.", "ঈশ্বর তাদের ভালোবাসেন যারা তাঁর কারনে লড়াই করে সম্মিলিতভাবে এক স্তম্ভে, কোন দেয়ালের ইটগুলোর মতো।"],
  "61:5": ["And when Musa said to his people: O my people, why do you harm me when you know that I am the Rasul of Allah to you? So when they swerved, Allah swerved their hearts, and Allah does not guide the defiant people.", "স্মরণ কর যে মুসা তার লোকদের বলেছিল, “হে আমার লোকেরা, কেন তোমরা আমাকে আঘাত কর, যদিও তোমরা জানো যে আমি তোমাদের কাছে ঈশ্বরের বার্তাবাহক?” যখন তারা পথচ্যুত হলো, ঈশ্বর তাদের হৃদয়কে বিমুখ করে দিলেন। কারন ঈশ্বর মন্দ লোকদের পথ দেখান না।"],
  "61:6": ["And when Isa son of Maryam said: O children of Israel, I am the Rasul of Allah to you, confirming what lies before me of the Torah and bringing good news of a Rasul who comes after me, whose name is Ahmad. But when he came to them with the clear proofs, they said: this is clear sorcery.", "স্মরণ কর, মরিয়মের পুত্র ঈসা বলেছিল, “হে ইসরাইলের সন্তানেরা, আমি তোমাদের প্রতি ঈশ্বরের বার্তাবাহক, তওরাতকে নিশ্চিত করছি এবং আমার পর একজন বার্তাবাহক আগমনের সুসংবাদ দিচ্ছি যারা নামকে করা হবে আরও বেশি প্রশংসিত (আহমদ)।” অতঃপর যখন সে তাদের স্পষ্ট প্রমাণদি দেখাল, তারা বলল, “এটা স্পষ্ট জাদু।”"],
  "61:7": ["And who is more wrong than one who fabricates against Allah a lie while he is called to Islam? And Allah does not guide the people who do wrong.", "সে ব্যক্তির চেয়ে কে অধিক মন্দ যে ঈশ্বর সম্পর্কে মিথ্যা উদ্ভাবন করে, এবং তাকে আত্মসমর্পণে দাওয়াত দেওয়া হচ্ছে? ঈশ্বর মন্দ লোকদের পথ দেখান না।"],
  "61:8": ["They want to extinguish the light of Allah with their mouths, but Allah completes the light, even if the kafirin are averse.", "তারা তাদের মুখ দিয়ে ঈশ্বরের আলো নেভাতে চায়। কিন্তু ঈশ্বর তাঁর আলোকে নির্ভুলভাবে পূর্ণ করার উপর জোর দেন, অবিশ্বাসীদের সত্ত্বেও।"],
  "61:9": ["It is Allah who sent the Rasul with the guidance and the religion of truth, to raise it above all religion, even if the associators are averse.", "তিনি তাঁর বার্তাবাহককে পাঠিয়েছেন পথনির্দেশনা এবং সত্য ধর্ম দিয়ে, আর একে সকল ধর্মের উপর কর্তৃত্বকারী করবেন, প্রতিমা উপাসকদের সত্ত্বেও।"],
  "61:10": ["O you who believe, shall I point you toward a trade that will save you from a painful punishment?", "হে তোমরা যারা বিশ্বাস কর, চল আমি তোমাদেরকে একটি বাণিজ্য সম্পর্কে জানাই যা তোমাদেরকে যন্ত্রণাদায়ক শাস্তি থেকে রক্ষা করবে।"],
  "61:11": ["You believe in Allah and the Rasul, and you strive in the way of Allah with your wealth and your lives. That is better for you, if you know.", "ঈশ্বর ও তাঁর বার্তাবাহককে বিশ্বাস কর এবং ঈশ্বরের পথে সংগ্রাম কর তোমাদের অর্থ ও তোমাদের জীবন দিয়ে। এটি তোমাদের জন্য সর্বোত্তম বাণিজ্য, যদি তোমরা কেবল জানতে।"],
  "61:12": ["Allah forgives you your offenses and admits you into gardens beneath which rivers flow, and pleasant dwellings in gardens of Eden. That is the great win.", "বিনিময়ে, তিনি তোমাদের পাপ ক্ষমা করেন এবং তোমাদের প্রবেশ করান প্রবাহিত ঝর্ণাসহ বাগানগুলোতে, সাথে রয়েছে ইডেনের সুন্দর অট্টালিকা বিশিষ্ট বাগানগুলো। এটিই সর্বোত্তম বিজয়।"],
  "61:13": ["And another you love: help from Allah and a triumph near at hand. And give good news to the muminin.", "উপরন্তু, তোমরা পাও এমনকিছু যা তোমরা সত্যিকারভাবে ভালবাসোঃ  ঈশ্বরের পক্ষ থেকে সমর্থন ও প্রতিশ্রুত বিজয়। বিশ্বাসীদের সুসংবাদ দাও।"],
  "61:14": ["O you who believe, be helpers of Allah, as Isa son of Maryam said to the answerers: who are my helpers unto Allah? The answerers said: we are Allah's helpers. So a party of the children of Israel believed and a party kafara, and We strengthened those who believed against their enemy, and they gained the upper hand.", "হে যারা বিশ্বাস কর, ঈশ্বরের সমর্থনকারী হও, মরিয়ম পুত্র ঈসার শিষ্যদের মত, যখন সে তাদের বলল, “ঈশ্বরের পথে কে আমরা সমর্থনকারী,” তারা বলল, “আমরা ঈশ্বরের সমর্থনকারী।” এরূপে, ইসরাইলের সন্তানদের একটি দল বিশ্বাস করলো এবং অন্য দলটি অবিশ্বাস করল। যারা বিশ্বাস করেছিল আমরা তাদেরকে তাদের শত্রুদের বিরুদ্ধে সাহায্য করলাম, যতক্ষণ না তারা জয়ী হল।"],
  "62:1": ["All that is in the heavens and all that is in the earth glorifies Allah, the Sovereign, the Holy, the Mighty, the Wise.", "আকাশমণ্ডলীর সবকিছু এবং পৃথিবীর সবকিছু ঈশ্বরের মহিমা ঘোষণা করে; যিনি রাজা, সবচেয়ে পবিত্র, সর্বশক্তিমান, সবচেয়ে প্রজ্ঞাবান।"],
  "62:2": ["Allah is the one who raised up among the unlettered a Rasul from among themselves, to recite to them the signs of Allah and to purify them and to teach them the Book and the wisdom — though before that, they were surely in clear error.", "তিনিই সে সত্ত্বা যিনি (ঐশীগ্রন্থ সম্পর্কে) অজ্ঞ লোকদের কাছে একজন বার্তাবাহক পাঠিয়েছিলেন  তাদেরই মধ্য থেকে, তাদের কাছে তাঁর প্রকাশনাবলি আবৃতি করতে, তাদেরকে পবিত্র করতে, তাদেরকে শিক্ষা দিতে ঐশীগ্রন্থ ও প্রজ্ঞা। এর আগে, তারা অত্যধিক পথচ্যুত হয়ে গিয়েছিল।"],
  "62:3": ["and others among them who have not yet joined them — and Allah is the Mighty, the Wise.", "এবং তাদের পরবর্তী বহু প্রজন্মের কাছে। তিনি সর্বশক্তিমান, সবচেয়ে প্রজ্ঞাবান।"],
  "62:4": ["That is the bounty of Allah, which Allah bestows on whomever Allah wills; and Allah is the possessor of the great bounty.", "এমনি ঈশ্বরের করুণা তা তিনি যার প্রতি ইচ্ছা অর্পণ করেন। ঈশ্বর অসীম করুণার অধিকারী।"],
  "62:5": ["The likeness of those who were made to carry the Torah, then did not carry it, is like the donkey carrying written leaves. Wretched is the likeness of the people who rejected the signs of Allah — and Allah does not guide the wrongdoing people.", "যাদেরকে তওরাত দেয়া হয়েছিল এরপর তা মেনে চলতে ব্যর্থ হয়েছিল তাদের উদাহরণ সেই গাধার মত যে সাহিত্যের মহান কর্ম বহন করছে। নিশ্চয় শোচনীয় সেই লোকদের উদাহরণ যারা ঈশ্বরের প্রকাশনাবলি প্রত্যাখ্যান করেছিল। ঈশ্বর মন্দ লোকদের পথ দেখান না।"],
  "62:6": ["Say: O you of the rivaling party, if you warrant that you are allies of Allah apart from other people, then wish for death — if you are sadiq.", "বল, ‘হে ইহুদিরা, যদি তোমরা দাবি কর যে তোমরা ঈশ্বরের বাছাইকৃত, অন্য সকল লোকদের বাদ দিয়ে, তবে তোমাদের উচিৎ মৃত্যু কামনা করা যদি তোমরা সত্যবাদী হও!”"],
  "62:7": ["Yet they will never wish it, for what their hands have sent ahead — and Allah is knowing of the wrongdoers.", "তারা কখনই তা কামনা করবে না, তারা যা করেছে তার কারনে। ঈশ্বর মন্দদের সম্পর্কে পূর্ণ অবগত।"],
  "62:8": ["Say: The death you flee from will surely meet you; then you will be returned to the knower of the unseen and the witnessed, and Allah will tell you what you used to do.", "বল, “যে মৃত্যুকে তোমরা এড়াতে চাও তা আগে বা পরে তোমাদের পাকড়াও করবে। এরপর তোমরা সকল গোপন ও প্রকাশ্য বিষয়ে জ্ঞানীর কাছে ফিরে যাবে, তখন তিনি তোমাদের জানাবেন যাকিছু তোমরা করেছিলে।"],
  "62:9": ["O you who believe, when the call is made for the prayer on the day of gathering, hasten to the remembrance of Allah and leave your dealing — that is better for you, if you know.", "হে যারা বিশ্বাস কর, যখন শুক্রবারের সম্মিলিত প্রার্থনার (সালাত আল-জুম্মাহর) ঘোষণা দেয়া হয়, তোমরা ঈশ্বরের স্মরণে দ্রুত মিলিত হও, এবং সকল ব্যবসা বন্ধ কর। এটি তোমাদের জন্য উত্তম, যদি কেবল তোমরা জানতে।"],
  "62:10": ["Then when the prayer is completed, spread out in the land and seek from the bounty of Allah, and remember Allah much, so that you may attain success.", "প্রার্থনা সম্পন্ন হলে, তোমরা জমিনে ছড়িয়ে পড়তে পারো  ঈশ্বরের অনুগ্রহ সন্ধানে, এবং ঈশ্বরকে ঘন ঘন স্মরণ করতে থাক যাতে তোমরা সফলকাম হতে পার।"],
  "62:11": ["And when they saw a trade or a diversion, they rushed to it and left you standing. Say: What is with Allah is better than diversion and better than trade — and Allah is the best of providers.", "যখন তাদের কেউ কেউ কোন ব্যবসায়িক লেনদেন বা কিছু বিনোদনের সম্মুখীন হয়, তারা এর দিকে দ্রুত ছুটে যায় এবং তোমাকে দাড় করিয়ে রাখে! বল, “যা ঈশ্বরের কাছে আছে তা বিনোদন বা ব্যবসা থেকে অনেক অনেক উত্তম। ঈশ্বর সর্বোত্তম রিজিকদাতা।"],
  "63:1": ["When the munafiqin come to you, they say: We testify that you are the Rasul of Allah. And Allah knows that you are the Rasul of Allah, and Allah testifies that the munafiqin are liars.", "যখন ভণ্ডরা তোমার কাছে আসে তারা বলে, “আমরা সাক্ষ্য দেই যে আপনি ঈশ্বরের বার্তাবাহক।” ঈশ্বর জানেন যে তুমি ঈশ্বরের বার্তাবাহক, এবং ঈশ্বর সাক্ষ্য দেন যে ভণ্ডরা মিথ্যাবাদী।"],
  "63:2": ["They have taken their oaths as a shield, and they turned away from the path of Allah. Evil is what they used to do.", "তাদের লোক-দেখানো বিশ্বাসের আড়ালে, তারা মানুষকে ঈশ্বরের পথে বাধা দেয়। নিশ্চয় শোচনীয় যা তারা করে।"],
  "63:3": ["That is because they believed, then kafara, so a seal was stamped over their hearts, and they do not understand.", "এটা এ কারনে যে তারা বিশ্বাস করেছিল, এরপর অবিশ্বাস করলো। সুতরাং, তাদের মনগুলো তালাবদ্ধ; তারা বোঝে না।"],
  "63:4": ["And when you see them, their bodies impress you; and when they speak, you listen to their speech. They are like propped-up wood. They think every shout is against them. They are the enemy, so beware of them. May Allah kill them! How are they turned away?", "যখন তুমি তাদের দেখ, তুমি হয়তো তাদের বাহ্যরূপ দেখে অভিভূত হবে। আর যখন তারা কথা বলে, তুমি হয়তো তাদের বাকপটুতা শুনে থাকবে। তারা দাঁড়িয়ে থাকা কাঠের তক্তার মতো। প্রতিটি আহবানকে তারা নিজেদের বিরুদ্ধে মনে করে। এরাই আসল শত্রু; তাদের ব্যাপারে সাবধান হও। ঈশ্বর তাদের নিন্দা করেন; তারা পথচ্যুত হয়েছে।"],
  "63:5": ["And when it is said to them: Come, so that the Rasul of Allah may ask forgiveness for you, they twist aside their heads, and you see them turning away while they are arrogant.", "যখন তাদের বলা হয়, “আসো, ঈশ্বরের বার্তাবাহক তোমাদের জন্য ক্ষমা প্রার্থনা করবে,” তারা উপহাস করে তাদের মাথা ঘুরিয়ে নেয়, আর তুমি দেখ তারা অন্যদের বাধা দেয় এবং উদ্ধত আচরণ করে।"],
  "63:6": ["It is all the same to them whether you ask forgiveness for them or do not ask forgiveness for them: Allah will never forgive them. Indeed, Allah does not guide the rebellious people.", "এটি তাদের জন্য সমান, তুমি তাদের ক্ষমার জন্য প্রার্থনা কর অথবা তাদের ক্ষমার জন্য প্রার্থনা না কর; ঈশ্বর তাদের ক্ষমা করবেন না। কারন ঈশ্বর মন্দ লোকদের পথ প্রদর্শন করেন না।"],
  "63:7": ["They are the ones who say: Do not spend on those who are with the Rasul of Allah until they disperse. Yet to Allah belong the storehouses of the heavens and the earth. But the munafiqin do not understand.", "তারাই সেসব ব্যক্তি যারা বলে, “তাদেরকে কোন অর্থ দিও না যারা ঈশ্বরের বার্তাবাহকের অনুসরণ করে, হয়তো তারা তাকে পরিত্যাগ করবে!” কিন্তু, ঈশ্বরের কাছে রয়েছে আকাশমণ্ডলী ও পৃথিবীর সকল ধন-সম্পদ, কিন্তু ভণ্ডরা অনুধাবন করে না।"],
  "63:8": ["They say: If we return to the city, the mightiest among us will surely drive out from it the most humbled. But might belongs to Allah, and to the Rasul, and to the muminin. Yet the munafiqin do not know.", "তারা বলে, “যদি তোমরা সেই শহরে ফিরে যাও, সেখানকার ক্ষমতাধররা দুর্বললোকদের উচ্ছেদ করবে (এবং আমরা অত্যাচারের শিকার হবো)।” (তাদের জানা উচিৎ যে) সকল মর্যাদা ঈশ্বর ও তাঁর বার্তাবাহকের, এবং বিশ্বাসীদের। কিন্তু, ভণ্ডরা জানে না।"],
  "63:9": ["O you who believe, let not your wealth nor your children divert you from the remembrance of Allah. And whoever does that, those are the khasirin.", "হে যারা বিশ্বাস কর, তোমাদের অর্থ ও তোমাদের সন্তানদের কারনে ঈশ্বরের স্মরণ থেকে বিচ্যুত হইও না। যারা তা করে তারা ক্ষতিগ্রস্থ।"],
  "63:10": ["And spend from what We have provided you, before death comes to one of you and one says: My Rabb, if only You had delayed me to a near term, so that I could give charity and be among the salihin.", "তোমাদেরকে আমাদের দেয়া জীবিকা থেকে তোমরা দাও তোমাদের কাছে মৃত্যু আসার পূর্বে, অন্যথায় তোমরা বল, “আমাদের প্রভু, শুধু যদি কিছু সময়ের জন্য আপনি একে বিলম্বিত করাতে পারতেন! আমি তবে দানশীল হতাম এবং সৎকর্মশীলদের সাথে যোগ দিতাম।"],
  "63:11": ["And Allah will never delay a soul when its term comes. And Allah is fully aware of what you do.", "ঈশ্বর কখনই কোন আত্মার মৃত্যুর নির্ধারিত সময়কে বিলম্বিত করেন না। তোমরা যা কিছু কর ঈশ্বর সে সম্পর্কে সম্পূর্ণ অবগত।"],
  "64:1": ["Whatever is in the heavens and whatever is in the earth glorifies Allah. To Allah belongs the kingdom, and to Allah belongs the praise, and Allah is over everything able.", "আকাশমণ্ডলীর সবকিছু এবং পৃথিবীর সবকিছু ঈশ্বরের মহিমা ঘোষণা করে। সকল রাজত্ব তাঁর, এবং সকল প্রশংসা তাঁর, এবং তিনি সর্বশক্তিমান।"],
  "64:2": ["It is the One who created you, so among you is one who disbelieves and among you is one who believes. And Allah sees what you do.", "তিনিই সে সত্ত্বা যিনি তোমাদের সৃষ্টি করেছেন, এরপর তোমাদের মধ্যে আছে অবিশ্বাসী ও বিশ্বাসী। ঈশ্বর তোমাদের করা সবকিছুর পূর্ণ দ্রষ্টা।"],
  "64:3": ["Created the heavens and the earth in truth, and formed you, and made your forms good. And to Allah is the arrival.", "তিনি একটি নির্দিষ্ট উদ্দেশ্যে আকাশমণ্ডলী ও পৃথিবী সৃষ্টি করেছেন, তোমাদের নকশা করেছেন এবং তোমাদের নকশাকে নিখুঁত করেছেন, এরপর তাঁর দিকেই চূড়ান্ত নিয়তি।"],
  "64:4": ["Knows what is in the heavens and the earth, and knows what you conceal and what you make open. And Allah is knowing of what lies in the chests.", "তিনি আকাশমণ্ডলী ও পৃথিবীর সবকিছু জানেন, এবং তিনি জানেন যা কিছু তোমরা গোপন কর আর যা কিছু তোমরা প্রকাশ কর। ঈশ্বর গভীরতম চিন্তাগুলো সম্পর্কে পূর্ণ অবগত।"],
  "64:5": ["Has there not come to you the news of those who kafara before? They tasted the heavy cost of their affair, and for them is a painful punishment.", "তোমরা কি তাদের লক্ষ্য করেছো যারা অতীতে অবিশ্বাস করেছিল, এরপর তাদের সিদ্ধান্তের ফল ভোগ করেছিল? তারা যন্ত্রণাদায়ক শাস্তির ভোগ করেছিল।"],
  "64:6": ["That is because their envoys kept coming to them with the clear proofs, and they said: \"Are mere humans to guide us?\" So they kafara and turned away, and Allah was free of need. And Allah is self-sufficient, praiseworthy.", "এটা এই কারনে যে তাদের বার্তাবাহকরা স্পষ্ট প্রমানাদি নিয়ে তাদের কাছে গিয়েছিল, কিন্তু তারা বলেছিল, “আমরা কি  আমাদের মত মানুষের অনুসরণ করব?” তারা অবিশ্বাস করলো এবং মুখ ফিরিয়ে নিয়েছিল। তাদেরকে ঈশ্বরের প্রয়োজন নেই; ঈশ্বর অভাব মুক্ত, প্রশংসনীয়।"],
  "64:7": ["Those who kafara claim that they will never be raised. Say: Yes indeed, and by my Rabb, you will surely be raised, then you will surely be told of what you did. And that is easy for Allah.", "যারা অবিশ্বাস করেছিল তারা দাবি করে যে তারা পুনরুত্থিত হবে না! হ্যাঁ নিশ্চয়, আমার প্রভুর শপথ, তোমরা পুনরুত্থিত হবে, এবং তোমাদেরকে হিসাব দিতে হবে সবকিছুর জন্য যা তোমরা করেছো। এটি ঈশ্বরের জন্য করা সহজ।"],
  "64:8": ["So believe in Allah and the Rasul and the light that We sent down. And Allah is fully aware of what you do.", "অতএব, তোমরা বিশ্বাস কর ঈশ্বর ও তাঁর বার্তাবাহককে, এবং সে আলো যা আমরা এখানে প্রকাশ করেছি। তোমরা যা কিছু কর সে সম্পর্কে ঈশ্বর পূর্ণ অবগত।"],
  "64:9": ["The day gathering you for the day of gathering — that is the day of loss. And whoever believes in Allah and does what is salih, Allah will remit the evil deeds from them and will enter them into a garden beneath which rivers flow, remaining therein forever. That is the great win.", "সে দিন আসবে যখন তিনি তোমাদেরকে  আহবানের দিন তলব করবেন। এটাই পারস্পরিক দোষারোপের দিন। যে কেউ আল্লাহকে বিশ্বাস করে এবং সৎ জীবন যাপন করে, তিনি তার পাপ মোচন করবেন, এবং তাকে প্রবেশ করাবেন প্রবাহিত ঝর্ণা সহ বাগানে। তারা সেখানে চিরকাল বসবাস করে। এটাই সর্বশ্রেষ্ঠ বিজয়।"],
  "64:10": ["And those who kafara and denied Our signs — those are companions of the fire, remaining therein forever. And evil is the arrival.", "আর যারা অবিশ্বাস করে ও আমাদের প্রকাশনাবলি প্রত্যাখ্যান করে, তারা নরকাগ্নির বাসিন্দা; তারা সেখানে চিরকাল বাস করে। কি এক শোচনীয় নিয়তি!"],
  "64:11": ["No calamity strikes except by Allah's permission. And whoever believes in Allah, Allah guides their heart. And Allah is knowing of everything.", "তোমাদের কোনকিছুই ঘটে না ঈশ্বরের ইচ্ছা অনুসারে ব্যতিত । যে কেউ ঈশ্বরে বিশ্বাস করে, তিনি তার হৃদয়কে পথ দেখাবেন। ঈশ্বর সকল বস্তু সম্পর্কে পূর্ণ অবগত।"],
  "64:12": ["And obey Allah and obey the Rasul. But if you turn away, then upon Our Rasul is only the clear conveying.", "তোমরা ঈশ্বরকে মান্য কর এবং বার্তাবাহককে মান্য কর। যদি তোমরা মুখ ফিরিয়ে নাও, তবে আমাদের বার্তাবাহকের একমাত্র উদ্দেশ্য হল বার্তা পৌঁছে দেওয়া।"],
  "64:13": ["Allah — there is no ilah but Allah. And upon Allah let the muminin rely.", "ঈশ্বর : তাঁর পাশে অন্য কোন উপাস্য নেই। বিশ্বাসীরা ঈশ্বরে আস্থা রাখুক।"],
  "64:14": ["O you who believe, indeed among your spouses and your children are enemies to you, so beware of them. And if you pass over and pardon and forgive, then indeed Allah is forgiving, merciful.", "হে যারা বিশ্বাস কর, তোমাদের জীবনসঙ্গী এবং তোমাদের সন্তানরা তোমাদের শত্রু হতে পারে; সতর্ক হও। যদি তোমরা মার্জনা কর, ভুলে যাও এবং ক্ষমা করো, তবে ঈশ্বর ক্ষমাশীল, সবচেয়ে করুণাময়।"],
  "64:15": ["Only your wealth and your children are a trial, and with Allah is a great reward.", "তোমাদের অর্থ ও তোমাদের সন্তানাদি একটি পরীক্ষা, এবং ঈশ্বরের কাছে আছে এক মহা প্রতিদান।"],
  "64:16": ["So be mindful of Allah as much as you are able, and listen and obey, and spend good for yourselves. And whoever is guarded from the stinginess of their own self — those are the ones who attain success.", "অতএব, তোমরা ঈশ্বরের ভক্তি কর যত বেশি তোমরা পারো, এবং শোন, এবং মেনে চলো, এবং দাও (দান হিসেবে) তোমাদের নিজেদের ভালোর জন্য। যেকেউ তার নিজের কৃপণতা থেকে সুরক্ষিত, এরাই সফলকাম ব্যক্তি।"],
  "64:17": ["If you lend Allah a good loan, Allah will multiply it for you and forgive you. And Allah is grateful, forbearing.", "যদি তোমরা ঈশ্বরকে সততার ঋণ দাও, তিনি তোমাদের জন্য পুরস্কার বহুগুনে বৃদ্ধি করবেন, এবং তোমাদের ক্ষমা করবেন। ঈশ্বর যথার্থ মূল্যায়নকারী, সহনশীল।"],
  "64:18": ["Knower of the unseen and the witnessed, the mighty, the wise.", "সকল গোপন ও প্রকাশ্য বিষয়ের জ্ঞানী; সর্বশক্তিমান। সবচেয়ে প্রজ্ঞাবান।"],
  "65:1": ["O Prophet, when you divorce nisa, then divorce them for their count and count the count; and be mindful of Allah your Rabb. Do not turn them out of their houses, and let them not go out, unless they come with a clear obscenity. And those are the limits of Allah; and whoever transgresses the limits of Allah has wronged themselves. You know not — Allah may bring about a matter after that.", "হে নবি, যখন তোমরা পুরুষরা কোন নারীকে তালাক দাও, তোমরা নিশ্চিত হবে যে তালাকের অন্তবর্তীকাল পূর্ণ করা হয়েছে। তোমরা এই অন্তবর্তীকাল নির্ভুলভাবে গণনা করবে। তোমরা তোমাদের প্রভু ঈশ্বরকে ভক্তি করবে। তাদেরকে তাদের বাড়ি থেকে বের করে দিও না, না তোমরা তাদের জন্য জীবনকে অতিষ্ঠ করে তুলবে, নিজ থেকে তাদেরকে বের হয়ে যেতে বাধ্য করতে, যদি না তারা কোন প্রমাণিত ব্যভিচার করে। এগুলো ঈশ্বরের আইন। যেকেউ ঈশ্বরের আইন লঙ্ঘন করে সে তার নিজের বিরুদ্ধে অবিচার করে। তুমি কখনো জানো না; হয়তো ঈশ্বর চান এর থেকে ভালো কিছু হোক।"],
  "65:2": ["So when they reach their term, hold them fast with fairness, or part with them with fairness; and call as witnesses men of justice from among you, and establish the witnessing for Allah. That is what one who believes in Allah and the Last Day is admonished with. And whoever is mindful of Allah, Allah will make a way out for them.", "অন্তবর্তীকাল পূর্ণ হওয়া মাত্র, তোমরা তাদের সাথে ন্যায়সঙ্গতভাবে পুনর্মিলিত হতে পারো অথবা ন্যায়সঙ্গতভাবে আলাদা হয়ে যেতে পারো। তালাকের সাক্ষী হওয়ার জন্য ঈশ্বরের সামনে তোমরা দুজন ন্যায়পরায়ণ সাক্ষী রাখবে। এর কারণ, জ্ঞান দান করা তাদেরকে যারা ঈশ্বর ও শেষ দিবসে বিশ্বাস করে। যেকেউ ঈশ্বরকে ভক্তি-শ্রদ্ধা করে, তিনি তার জন্য প্রস্থানের পথ সৃষ্টি করবেন।"],
  "65:3": ["And Allah will provide them from whence they reckon not; and whoever relies upon Allah, Allah is sufficient for them. Indeed, Allah reaches Allah's command; Allah has set a measure for every thing.", "এবং তার জন্য জীবনোপকরণ সরবরাহ করবেন যেখান থেকে সে কখনো আশা করেনি। যে কেউ ঈশ্বরের প্রতি আস্থা রাখে, তিনি তার জন্য যথেষ্ট। ঈশ্বরের হুকুম সম্পাদিত হয়েছে। ঈশ্বর সবকিছুর জন্য এর নিয়তি নির্ধারণ করেছেন।"],
  "65:4": ["And those of your nisa who have despaired of the monthly course — if you are in doubt — their count is three months, and those who have not yet had the course; and those with burdens, their term is that they lay down their burdens. And whoever is mindful of Allah, Allah will make ease for them in their affair.", "আর যে নারী রজোবন্ধে পৌঁছেছে, যদি তোমাদের কোন সন্দেহ থাকে, তাদের অন্তবর্তীকাল হবে তিন মাস। আর যাদের ঋতুস্রাব হয়নি, এবং আবিষ্কার করে যে তারা অন্তঃসত্ত্বা, তাদের অন্তবর্তীকাল শেষ হবে সন্তান প্রসব করার পর। যে কেউ ঈশ্বরকে ভক্তি করে, তিনি সব কিছু তার জন্য সহজ করে দেন।"],
  "65:5": ["That is the command of Allah, which Allah has sent down to you; and whoever is mindful of Allah, Allah will erase their misdeeds for them and make great for them a reward.", "এটি ঈশ্বরের হুকুম যা তিনি তোমাদের কাছে অবতীর্ণ করেন। যে কেউ ঈশ্বরকে ভক্তি করে, তিনি তার পাপ ক্ষমা করেন এবং তাকে উদারভাবে পুরস্কৃত করেন।"],
  "65:6": ["Lodge them where you lodge according to your means, and do not harm them so as to straiten them. And if they are with burden, spend upon them until they lay down their burdens. Then if they nurse for you, give them their wages; and settle the matter between yourselves with fairness. And if you suffer hardship, another shall nurse for them.", "তোমরা একই ঘরে তাদের বাস করতে দেবে যেখানে তারা তোমাদের সাথে বাস করতো এবং তাদের জীবনকে এতো দুঃসহ করে তুলো না যে তারা নিজ থেকে বের হয়ে যায়। যদি তারা অন্তঃসত্ত্বা হয়, তোমরা তাদের জন্য খরচ করবে যতক্ষণ না তারা সন্তান প্রসব করে। যদি তারা নবজাতককে স্তন্য দান করে, এই সেবার জন্য তোমরা তাদের প্রাপ্য পারিশ্রমিক দাও। তোমরা তোমাদের মধ্যে শান্তিপূর্ণ সম্পর্ক বজায় রাখবে। যদি তোমরা অমত করো, তবে শিশুটিকে স্তন্য দান করতে অন্য নারীকে তোমরা ভাড়া করতে পার।"],
  "65:7": ["Let the one of abundance spend from their abundance; and the one whose provision is measured, let them spend from what Allah has given them. Allah charges no soul except with what Allah has given it; Allah will make ease after hardship.", "ধনী স্বামী তার সামর্থ্য অনুসারে ভরণপোষণ দিবে, এবং গরীব সে অনুসারে দিবে যা ঈশ্বর তার উপর অর্পণ করেছেন। আল্লাহ কোন আত্মাকে তাঁকে দেয়া সামর্থ্যের অতিরিক্ত বোঝা চাপিয়ে দেন না। ঈশ্বর কষ্টের পর আরাম দিবেন।"],
  "65:8": ["And how many a township was insolent toward the command of its Rabb and Allah's rusul; so Allah reckoned it a severe reckoning and punished it a dreadful punishment.", "অনেক সম্প্রদায় তাদের প্রভুর প্রত্যাদেশাবলি ও তাঁর বার্তাবাহকদের বিরুদ্ধে বিদ্রোহ করেছিল। পরিণামে, আমরা তাদের কাছ থেকে কঠোর হিসাব নিয়েছিলাম, এবং তাদেরকে প্রতিদান দিয়েছিলাম এক যন্ত্রণাদায়ক প্রতিদান।"],
  "65:9": ["So it tasted the heavy cost of its affair, and the outcome of its affair was loss.", "তারা তাদের সিদ্ধান্তের পরিণাম ভোগ করেছিল, এক অসামান্য ক্ষতি।"],
  "65:10": ["Allah has prepared for them a severe punishment. So be mindful of Allah, O people of understanding who believe. Allah has sent down to you a reminder.", "ঈশ্বর তাদের জন্য কঠিন শাস্তি প্রস্তুত করেছেন। অতএব, তোমরা ঈশ্বরকে ভক্তি কর, হে যারা বুদ্ধিমত্তার অধিকারী এবং বিশ্বাস করেছো। ঈশ্বর তোমাদের কাছে একটি বার্তা অবতীর্ণ করেছেন-"],
  "65:11": ["A Rasul reciting to you the signs of Allah, clear, to bring those who believe and do salih deeds out of darkness into light. And whoever believes in Allah and does salihness, Allah will make them enter gardens beneath which rivers flow, abiding therein forever; Allah has made good provision for them.", "একজন বার্তাবাহক যে তোমাদের কাছে ঈশ্বরের প্রকাশনাবলি আবৃতি করে, স্পষ্টভাবে, তাদেরকে অন্ধকার থেকে আলোতে পরিচালিত করতে যারা বিশ্বাস করে ও সৎ জীবন যাপন করে। যেকেউ ঈশ্বরে বিশ্বাস করে ও সৎ জীবন যাপন করে, তিনি তাকে প্রবাহিত ঝর্ণা সহ বাগানে প্রবেশ করাবেন; তারা সেখানে চিরকাল বাস করবে। ঈশ্বর তাদেরকে উদারভাবে পুরস্কার দেবেন।"],
  "65:12": ["Allah is the one who created seven heavens, and of the earth the like of them; the command descends between them, so that you may know that Allah is powerful over every thing, and that Allah has encompassed every thing in knowledge.", "ঈশ্বর সৃষ্টি করেছেন সাত মহাকাশ এবং একই সংখ্যক পৃথিবী। এগুলোর মধ্যে প্রত্যাদেশাবলি প্রবাহিত হয়। এটি কেবল তোমাদের জানানোর জন্য যে ঈশ্বর সর্বশক্তিমান এবং ঈশ্বর সকল বস্তু সম্পর্কে পূর্ণ অবগত।"],
  "66:1": ["O Prophet, why do you forbid what Allah has permitted for you, seeking the approval of your nisa? And Allah is Forgiving, Raheem.", "হে নবী, কেন তুমি তা নিষিদ্ধ করো, যা ঈশ্বর তোমার জন্য আইনসিদ্ধ করেছেন, কেবল তোমার স্ত্রীদের সন্তুষ্ট করতে? ঈশ্বর ক্ষমাশীল, করুনাময়।"],
  "66:2": ["Allah has ordained for you a dissolution of your oaths, and Allah is your Protector; and Allah is the Knowing, the Wise.", "ঈশ্বর তোমাদের কসমের ক্ষেত্রে করনীয় বিষয়ে তোমাদের জন্য আইন প্রকাশ করেছেন। ঈশ্বর তোমাদের প্রভু, এবং তিনি সর্বজ্ঞ, পরম জ্ঞানী।"],
  "66:3": ["And when the Prophet confided a talk to one of his nisa, and she reported it, and Allah disclosed it to him, he knew part of it and turned away from part. And when he told her of it, she said, \"Who told you this?\" He said, \"The Knowing, the Well-Aware told me.\"", "নবী একটি বিশেষ কথার ক্ষেত্রে তার কিছু স্ত্রীদের বিশ্বাস করেছিল, এরপর তাদের একজন তা ছড়িয়ে দিল, এবং ঈশ্বর এ বিষয়ে তাকে জানিয়ে দিলেন। সে এরপর তার স্ত্রীকে এ বিষয়ে কিছু জানালো,আর কিছু এড়িয়ে গেলো। তার স্ত্রী তাকে জিজ্ঞেস করল, “এটা তোমাকে কে জানিয়েছে?” সে বলল, “আমি জেনেছি সর্বজ্ঞ, সব জানলেওয়ালার মাধ্যমে।”"],
  "66:4": ["If you two repent to Allah — your hearts have inclined — and if you support each other against him, then Allah is his Protector, and Jibril, and the salihin among the muminin, and the malakat after that are backers.", "যদি তোমরা দু'জন ঈশ্বরের কাছে অনুশোচনা করো, তবে তোমাদের হৃদয় শুনেছে। কিন্তু সকলে তোমরা তার বিরুদ্ধে জোট বাধঁলেও, ঈশ্বর তার মিত্র, এবং জিব্রাইল ও সৎকর্মশীল বিশ্বাসীগণও। এছাড়া, ফেরেশতারা তার সাহায্যকারী।"],
  "66:5": ["Perhaps, if he divorces you, his Rabb will substitute for him nisa better than you: submitting, believing, devout, repentant, worshipping, wandering, previously married and virgins.", "যদি সে তোমাদের তালাক দেয়, তার প্রভু তোমাদের স্থানে তাকে তোমাদের থেকে উত্তম স্ত্রী দেবেন; আত্মসমর্পণকারী (মুসলিম), বিশ্বাসী (মুমিন), মান্যকারী, অনুশোচনাকারী, উপাসনাকারী, সৎকর্মশীল, হয়তো পূর্বে বিবাহিত বা কুমারী।"],
  "66:6": ["O you who believe, guard yourselves and your families from a fire whose fuel is people and stones, over which are hard, severe malakat who do not disobey Allah in whatever Allah has commanded them, and they do what they are commanded.", "হে তোমরা যারা বিশ্বাস কর, নিজেকে ও তোমাদের পরিবারকে নরকাগ্নি থেকে রক্ষা কর, যার জ্বালানি মানুষ ও পাথর। একে পাহারা দিচ্ছে কঠোর এবং শক্তিশালী ফেরেশতারা যারা কখনো ঈশ্বরকে অমান্য করে না; তাদেরকে যা হুকুম করা হয় তারা তা সম্পাদন করে।"],
  "66:7": ["O you who disbelieve, do not offer excuses today; you are only recompensed for what you used to do.", "হে যারা অবিশ্বাস করেছ, আজ  দু:খ প্রকাশ করো না। তোমরা যা করেছ, শুধু এর জন্যই তোমরা প্রতিফল পাও।"],
  "66:8": ["O you who believe, turn to Allah in sincere repentance; perhaps your Rabb will remove from you your evil deeds and admit you into gardens beneath which rivers flow — a day when Allah will not disgrace the Prophet and those who believed with him. Their light hastens before them and at their right hands, as they say, \"Our Rabb, complete our light for us and forgive us; You are over everything able.\"", "হে যারা বিশ্বাস কর, তোমরা ঈশ্বরের কাছে অনুশোচনা করবে, যা হবে এক দৃঢ় অনুশোচনা। তাহলে, তোমাদের প্রভু তোমাদের পাপ ক্ষমা করবেন আর তোমাদের প্রবেশ করাবেন প্রবাহিত ঝর্ণাসহ বাগানে। ঐ দিন, ঈশ্বর নবীকে ও তার সাথে যারা ছিল তাদেরকে নিরাশ করবেন না। তাদের আলো তাদের সামনে এবং তাদের ডান দিকে বিচ্ছুরিত হবে। তারা বলবে, “আমাদের প্রভু, আমাদের জন্য আমাদের আলোকে পূর্ণাঙ্গ করুন, এবং আমাদের ক্ষমা করুন; আপনি সর্বশক্তিমান।”"],
  "66:9": ["O Prophet, strive against the kafirin and the munafiqin, and be hard on them; their shelter is Jahannam, and evil is the arrival.", "হে নবী, অবিশ্বাসী ও ভণ্ডদের বিরুদ্ধে সংগ্রাম কর এবং তাদের প্রতি কঠোর হও। তাদের বাসস্থান জাহান্নাম, এবং এক শোচনীয় ভাগ্য।"],
  "66:10": ["Allah struck an example for those who kafara: the imra'a of Nuh and the imra'a of Lut. They were under two of Our salih servants, and they betrayed them, yet the two availed them nothing against Allah at all. And it was said, \"Enter the fire with those entering.\"", "আল্লাহ উদাহরণ হিসেবে তাদের উল্লেখ করেন যারা অবিশ্বাস করেছিল, নূহের স্ত্রী এবং লুতের স্ত্রী। তারা আমাদের দু’জন সৎকর্মশীল বান্দার সাথে বিবাহ বন্ধনে আবদ্ধ ছিল, কিন্তু তারা তাদের সাথে বিশ্বাসঘাতকতা করেছিল এবং পরিণামে তারা তাদেরকে ঈশ্বরের বিরুদ্ধে একেবারেই সাহায্য করতে পারেনি। তাদের দুজনকে বলা হয়েছিল, “তাদের সাথে নরকাগ্নিতে প্রবেশ কর যারা এর যোগ্য।”"],
  "66:11": ["And Allah struck an example for those who believed: the imra'a of Fir'awn, when she said, \"Rabb, build for me a house with You in the garden, and shelter me from Fir'awn and his work, and shelter me from the wrongdoing people.\"", "এবং উদাহরণ হিসেবে ঈশ্বর তাদের উদ্ধৃতি দেন যারা বিশ্বাস করেছিল যেমন ফেরাউনের স্ত্রী। সে বলেছিল, “আমার প্রভু,স্বর্গে আপনার কাছে আমার জন্য একটি ঘর নির্মাণ করুন এবং আমাকে রক্ষা করুন ফেরাউন ও তার কাজকর্ম থেকে; আমাকে রক্ষা করুন সীমালঙ্ঘনকারী লোকদের থেকে।”"],
  "66:12": ["And Maryam, daughter of Imran, who fortified her opening, and We blew into it of Our spirit, and she affirmed the word and the writings of her Rabb, and she was among the qanitin.", "এছাড়া ছিল, ইমরানের কন্যা- মরিয়ম। সে তার সতীত্ব বজায় রেখেছিল, এরপর আমাদের আত্মা থেকে আমরা তার মধ্যে ফুঁকে দিলাম। সে তার প্রভুর বানীতে ও তাঁর ঐশীগ্রন্থে বিশ্বাস করেছিল; সে ছিল অনুগত।"],
  "67:1": ["Blessed be the One in whose hand is all rule, and who is able over everything.", "সবচেয়ে মহিমান্বিত সে সত্ত্বা যাঁর হাতে রয়েছে সকল রাজত্ব, এবং তিনি সর্বশক্তিমান।"],
  "67:2": ["The One who created death and life to test which of you is best in deed; and Allah is the mighty, the forgiving.", "সে সত্ত্বা যিনি সৃষ্টি করেছেন মৃত্যু এবং জীবন, তোমাদের মধ্যে তাদেরকে আলাদা করার উদ্দেশ্যে যারা উত্তম কাজ করবে। তিনি সর্বশক্তিমান, ক্ষমাশীল।"],
  "67:3": ["The One who created seven heavens in layers — you see no gap in the creation of the Rahman. Turn the gaze back: do you see any crack?", "তিনি স্তরে স্তরে সৃষ্টি করেছেন, সাত মহাবিশ্ব। সবচেয়ে করুনাময়ের সৃষ্টিতে তুমি কোন অসম্পূর্ণতা দেখো না। দেখতে থাক; তুমি কি কোন ত্রুটি দেখো?"],
  "67:4": ["Then turn the gaze back twice over; it returns to you defeated and regretful.", "বার বার দেখো; তোমার চোখ হতবুদ্ধ ও পরাজিত হয়ে ফিরবে।"],
  "67:5": ["We adorned the nearest heaven with lamps and made it a stoning for the satans; and We prepared for them the punishment of the blaze.", "আমরা সর্বনিম্ন মহাবিশ্বকে প্রদীপ দিয়ে সজ্জিত করেছি এবং এর সীমান্তকে শয়তানদের বিরুদ্ধে ক্ষেপণাস্ত্র দিয়ে সুরক্ষিত করেছি; আমরা তাদের জন্য প্রস্তুত রেখেছি নরকের শাস্তি।"],
  "67:6": ["For those who disbelieve in their Rabb there is the punishment of Jahannam — and evil is the arrival.", "যারা তাদের প্রভুকে অবিশ্বাস করে, তাদের জন্য জাহান্নামের শাস্তি। কি এক শোচনীয় নিয়তি।"],
  "67:7": ["When they are cast into it they hear it roaring while it seethes.", "যখন তারা সেখানে নিক্ষিপ্ত হয়, তারা এর হুংকার শুনতে পায় যখন তা ধোঁয়া ছড়ায়।"],
  "67:8": ["It nearly bursts apart with rage. Every time a host is cast into it, its keepers ask them: \"Did no warner come to you?\"", "প্রচণ্ড ক্রোধে এটি প্রায় বিস্ফোরিত হয়। যখনই কোন দলকে সেখানে নিক্ষেপ করা হয়, এর প্রহরীরা তাদের জিজ্ঞাসা করবে, “তোমরা কি কোন সতর্ককারী পাওনি?”"],
  "67:9": ["They say: \"Yes — a warner came to us, but we rejected him and said: Allah has sent down nothing; you are in nothing but great error.\"", "তারা উত্তর দেবে, “হ্যাঁ নিশ্চয়, আমাদের কাছে একজন সতর্ককারী এসেছিল, কিন্তু আমরা অবিশ্বাস করেছিলাম আর বলেছিলাম, “ঈশ্বর কোন কিছু প্রকাশ করেননি। তোমরা পুরোপুরি পথভ্রষ্ট।”"],
  "67:10": ["And they say: \"If only we had listened or understood, we would not be among the companions of the blaze.\"", "তারা আরও বলে, “যদি আমরা শুনতাম বা বুঝতাম, তবে আমরা নরকের বাসিন্দা হতাম না!”"],
  "67:11": ["So they confess their guilt. Away with the companions of the blaze!", "এভাবে, তারা তাদের পাপ স্বীকার করেছিল। দু:খ তো নরকের বাসিন্দাদের।"],
  "67:12": ["Those who hold reverent awe toward their Rabb in the unseen — for them is forgiveness and a great reward.", "আর যারা তাদের প্রভুকে ভক্তি-শ্রদ্ধা করে, তাদের একাকিত্বে, তারা অর্জন করেছে ক্ষমা এবং এক মহা প্রতিদান।"],
  "67:13": ["Whether you hide your speech or speak it aloud, Allah knows what the breasts hide.", "তোমরা তোমাদের কথা গোপন করো অথবা প্রকাশ করো, তিনি গভীরতম চিন্তাগুলো সম্পর্কে সম্পূর্ণ অবগত।"],
  "67:14": ["Would not the One who created know, when Allah is the subtle, the aware?", "তিনি কি জানবেন না যে তিনি কি সৃষ্টি করেছেন? তিনি মহীয়ান, সবচেয়ে অবগত।"],
  "67:15": ["It is Allah who subdued the earth for you: walk upon its surface and eat of Allah's provision; to Allah is the rising.", "তিনিই সে সত্ত্বা যিনি পৃথিবীকে তোমাদের সেবায় নিয়োজিত করেছেন। এর আনাচে-কানাচে ঘুরে বেড়াও, এবং তাঁর জীবিকা থেকে খাও। তাঁর কাছেই, চুড়ান্ত তলব।"],
  "67:16": ["Do you feel safe from the One in the sky, that Allah will make the earth sink with you — and then it sways?", "তোমরা কি নিশ্চয়তা দাও যে আকাশে যিনি আছেন তিনি পৃথিবীকে আঘাত করবেন না এবং একে ভেঙে ফেলবেন না?"],
  "67:17": ["Or do you feel safe from the One in the sky, that Allah will send a burning blast down upon you? Then you will know what My warning is like.", "তোমাদের কি নিশ্চয়তা দেয়া হয়েছে যে, আকাশে যিনি আছেন তিনি তোমাদের উপর প্রবল ঝড় পাঠাবেন না? তখন কি তোমরা আমার সতর্কবানীর মূল্য উপলব্ধি করবে?"],
  "67:18": ["Those before them rejected too — so how was the rejection?", "তাদের পূর্বে অন্যরা অবিশ্বাস করেছিল; কি ভয়াবহ ছিল আমার প্রতিশোধ!"],
  "67:19": ["Have they not seen the birds above them, ranged in ranks and drawing in? Nothing holds them fast but the Rahman; Allah sees all things.", "তারা কি তাদের উপরস্থ পাখিগুলোকে দেখেনি স্তম্ভাকারে বিন্যস্ত হতে  এবং তাদের পাখা বিস্তৃত করতে? পরম করুণাময় হলেন সেই সত্ত্বা যিনি তাদেরকে বাতাসে ধরে রাখেন।  তিনি সবকিছু দেখেন।"],
  "67:20": ["What host is this that is yours, to help you other than the Rahman? The kafirin are in nothing but deception.", "কোথায় ঐসব সৈন্যরা যারা পরম করুণাময়ের বিরুদ্ধে তোমাদের সাহায্য করতে পারে? নিশ্চয়, অবিশ্বাসীরা প্রতারিত।"],
  "67:21": ["What one is this who will provide for you if Allah held back the provision? No — they persist in insolent defiance and aversion.", "কে আছে যে তোমাদের জীবিকা দিবে, যদি তিনি তাঁর জীবিকা আটকে রাখেন? নিশ্চয়, তারা সীমালঙ্ঘন এবং বিমুখতার গভীরে নিমজ্জিত হয়েছে।"],
  "67:22": ["Who is better guided: one who walks fallen on his face, or one who walks upright on a straight path?", "সে ব্যক্তি যে হাঁটার সময় মুখ থুবড়ে পড়ে সে উত্তম, না সে ব্যক্তি যে সঠিক পথে সোজা হাঁটে?"],
  "67:23": ["Say: it is Allah who raised you up and gave you hearing, sight, and hearts — yet how little you give thanks.", "বল, “তিনি সেই সত্ত্বা যিনি তোমাদের সূচনা করেছেন, এবং তোমাদের দান করেছেন শ্রবণ শক্তি, চোখ এবং মস্তিস্ক। তোমরা খুব কমই কৃতজ্ঞ।”"],
  "67:24": ["Say: it is Allah who spread you out over the earth, and to Allah you will be gathered.", "বল, “তিনিই সে সত্ত্বা যিনি তোমাদেরকে পৃথিবীতে স্থান দিয়েছেন, এবং তাঁর সামনেই তোমাদের তলব করা হবে।”"],
  "67:25": ["And they say: \"When is this promise, if you are sadiq?\"", "তারা চ্যালেঞ্জ করেঃ “কখন সেই ভবিষ্যৎবাণী সংঘটিত হবে, যদি তোমরা সত্যবাদী হও?”"],
  "67:26": ["Say: the knowledge is only with Allah; I am only a clear warner.", "বল, “ঈশ্বরের কাছেই রয়েছে এর জ্ঞান; আমি একজন স্পষ্ট সতর্ককারীর চেয়ে বেশি কিছু নই।”"],
  "67:27": ["So when they see it brought near, the faces of those who kafara turn wretched; and it will be said: \"This is the very thing you used to call for.\"", "যখন তারা একে সংঘটিত হতে দেখে, যারা অবিশ্বাস করেছিল তাদের মুখ দুর্দশাগ্রস্থ হয়ে পড়বে, এবং ঘোষণা করা হবে যেঃ “এটি তা-ই যা নিয়ে তোমরা উপহাস করতে।”"],
  "67:28": ["Say: tell me — if Allah destroys me and those with me, or shows mercy to us, who will shield the kafirin from a painful punishment?", "বল, “ঈশ্বর আমাকে ও আমার সাথে যারা আছে, তাদেরকে যদি ধ্বংস করার সিদ্ধান্ত নেন অথবা আমাদের প্রতি তাঁর দয়া বর্ষণ করেন, কে আছে যে অবিশ্বাসীদের রক্ষা করবে এক যন্ত্রণাদায়ক শাস্তি থেকে?”"],
  "67:29": ["Say: Allah is the Rahman; in Allah we believe, and on Allah we rely. You will soon know who is in clear error.", "বল, “তিনি সবচেয়ে করুণাময়; আমরা তাকে বিশ্বাস করি, এবং আমরা তাঁর প্রতি আস্থা রাখি। তোমরা নিশ্চয় জানতে পারবে কে সত্যিকারর্থে বহুদূর পথভ্রষ্ট।”"],
  "67:30": ["Say: tell me — if your water sinks away, who will bring you flowing water?", "বল, “যদি তোমাদের পানি ভূগর্ভে ডুবে যায়, কে দেবে তোমাদের পরিষ্কার পানি?”"],
  "68:1": ["N, by the pen and what they write.", "নুন, কলম, এবং যা তারা (লোকেরা) লিখে।"],
  "68:2": ["You are not, by the favor of your Rabb, mad.", "তোমার প্রভুর পক্ষ থেকে তুমি একটি বিশাল অনুগ্রহ অর্জন করেছ; তুমি পাগল নও।"],
  "68:3": ["And indeed for you is a reward without stint.", "তুমি যথোপযুক্ত প্রতিদান অর্জন করেছ।"],
  "68:4": ["And indeed you are of a mighty character.", "তুমি মহান নৈতিক চরিত্র দ্বারা অনুগ্রহপ্রাপ্ত।"],
  "68:5": ["So you will see, and they will see.", "তুমি দেখবে, এবং তারাও দেখবে।"],
  "68:6": ["Which of you is the one afflicted.", "তোমাদের কে নিন্দিত।"],
  "68:7": ["Indeed, your Rabb knows best who strays from the way, and knows best the rightly guided.", "তোমার প্রভু তাদের বিষয়ে সম্পূর্ণ অবগত যারা তাঁর পথ থেকে সরে গেছে এবং তিনি তাদের বিষয়ে সম্পূর্ণ অবগত যারা সুপথ প্রাপ্ত।"],
  "68:8": ["So do not obey the mukazzibin.", "প্রত্যাখ্যানকারীদের মান্য করো না।"],
  "68:9": ["They wish that you would soften, so that they would soften.", "তারা চায় যে, তুমি আপস করো, যাতে তারাও আপস করতে পারে।"],
  "68:10": ["And do not obey every vile swearer.", "মান্য করো না কোন হীন শপথকারীকে ।"],
  "68:11": ["A backbiter, going about with slander.", "কোন পরনিন্দাকারীকে, কোন কুৎসা রটনাকারীকে।"],
  "68:12": ["A withholder of good, a transgressor, a sinner.", "দান করতে নিষেধকারীকে, কোন সীমালঙ্ঘনকারীকে, কোন পাপীকে।"],
  "68:13": ["Harsh, and after that, base-born.", "অকৃতজ্ঞ, এবং লোভীকে।"],
  "68:14": ["Just because he has wealth and sons.", "এমনকি যদিও তার আছে যথেষ্ট অর্থ ও সন্তানাদি।"],
  "68:15": ["When Our verses are recited to him, he says: 'Tales of the ancients!'", "যখন আমাদের প্রকাশনাবলি তার কাছে পাঠ করা হয়, সে বলে, “অতীতের কল্প-কাহিনী!”"],
  "68:16": ["We shall brand him on the snout.", "আমরা তার মুখমণ্ডল চিহ্নিত করে দিবো।"],
  "68:17": ["We tested them as We tested the companions of the garden, when they swore to cut it by morning.", "আমরা তাদের পরীক্ষা করেছি যেমন আমরা পরীক্ষা করেছিলাম বাগানের মালিকদের, যারা কসম খেয়েছিল যে সকালে তারা ফসল কাটবে।"],
  "68:18": ["And they made no exception.", "তারা এতোটাই শতভাগ নিশ্চিত ছিল।"],
  "68:19": ["Then a deluge from your Rabb swept over it while they slept.", "যখন তারা ঘুমিয়ে ছিল, তখন তোমার প্রভুর কাছ থেকে একটি বয়ে যাওয়া (ঝড়) এর উপর দিয়ে গেল।"],
  "68:20": ["And by morning it was like the cut-down one.", "সকাল নাগাদ, এটি শস্যহীন হয়ে পড়লো।"],
  "68:21": ["So they called out to one another in the morning.", "তারা সকালে একে অন্যের কাছে গেল।"],
  "68:22": ["Set out early to your tillage, if you are going to cut.", "“চল আমরা ফসল কাটতে যাই।"],
  "68:23": ["So they set out, whispering under their breath.", "যাবার পথে, তারা একে অন্যের উপর আস্থা রাখলো।"],
  "68:24": ["Let no poor person enter it upon you today.", "এ ব্যাপারে যে, এরপর থেকে, তাদের কেউ গরীব থাকবে না।"],
  "68:25": ["And they went early, hard in purpose, fully able.", "তারা তাদের ফসল কাটার বিষয়ে এতোটাই শতভাগ নিশ্চিত ছিল।"],
  "68:26": ["But when they saw it, they said, 'We have gone astray.'", "কিন্তু যখন তারা তা দেখল, তারা বলল, “আমরা কতটা ভুল ছিলাম!"],
  "68:27": ["'No, we are the ones deprived.'", "“এখন, আমাদের কিছুই নেই!”"],
  "68:28": ["The most moderate of them said, 'Did I not tell you? Why did you not glorify?'", "তাদের মধ্যে সৎকর্মশীলরা বলল, “যদি কেবল আমরা (ঈশ্বরের) মহিমা ঘোষণা করতাম!”"],
  "68:29": ["They said, 'Glory to our Rabb — we were wrongdoers.'", "তারা বলল, “আমাদের প্রভুর মহিমা। আমরা সীমালঙ্ঘন করেছি।”"],
  "68:30": ["Then they turned on one another, blaming.", "তারা একে অন্যের উপর দোষারোপ শুরু করলো।"],
  "68:31": ["They said, 'Woe to us — we were transgressors.'", "তারা বলল, “দুঃখ আমাদের। আমরা পাপ করেছি।"],
  "68:32": ["'Perhaps our Rabb will substitute for us something better than it; indeed, to our Rabb we turn eagerly.'", "“আমাদের প্রভু যেন আমাদেরকে আরেকটি উত্তম বাগান দান করেন। আমরা আমাদের প্রভুর কাছে অনুশোচনা করি।”"],
  "68:33": ["Such is the punishment; and the punishment of the hereafter is greater, if only they knew.", "এমনই ছিল প্রতিদান। কিন্তু পরকালের শাস্তি অধিকতর মন্দ, যদি কেবল তারা জানত।"],
  "68:34": ["Indeed, for the mindful are gardens of bliss with their Rabb.", "সৎকর্মশীলগণ অর্জন করেছে, তাদের প্রভুর কাছে, পরম সুখের বাগান।"],
  "68:35": ["Shall We make the submitters like the guilty?", "আমরা কি আত্মসমর্পণকারীদের গণ্য করবো অপরাধীদের মত?"],
  "68:36": ["What is the matter with you? How do you judge?", "তোমাদের যুক্তিতে সমস্যা কোথায়?"],
  "68:37": ["Or do you have a book in which you study?", "তোমাদের কি মান্য করার অন্যকোন গ্রন্থ আছে?"],
  "68:38": ["That you have in it whatever you choose?", "এর মধ্যে, তোমরা কি যা চাও তা-ই পাও?"],
  "68:39": ["Or do you have oaths binding upon Us, reaching to the Day of Rising, that you shall have whatever you decree?", "অথবা, তোমরা কি আমাদের কাছ থেকে দৃড় নিশ্চয়তা পেয়েছ যে পুনরুত্থান দিনে তোমরা যা চাও তা-ই পাবে?"],
  "68:40": ["Ask them which of them is guarantor of that.", "তাদের জিজ্ঞেস করো, “কে তোমাদেরকে এমন অঙ্গীকার দেয়?”"],
  "68:41": ["Or do they have partners? Then let them bring their partners, if they are sadiq.", "তাদের কি অন্যকোন উপাস্য আছে? তাদের উপাস্যরা তাদের সাহায্য করুক, যদি তারা সত্যবাদী হয়।"],
  "68:42": ["The Day the shin is bared, and they are called to prostrate, but they cannot.", "সেদিন আসবে যখন তারা প্রকাশিত হয়ে পড়বে, এবং তাদেরকে সেজদা করতে বলা হবে, কিন্তু তারা সক্ষম হবে না।"],
  "68:43": ["Their eyes humbled, abasement overwhelming them — and they had been called to prostrate while they were whole.", "তাদের দৃষ্টি নতজানু হবে, অপমান তাদেরকে ঘিরে ফেলবে। তাদেরকে সেজদা করতে আমন্ত্রন জানানো হতো যখন তারা অক্ষত ও সক্ষম ছিল।"],
  "68:44": ["So leave Me with the one who denies this account; We shall draw them on gradually from where they know not.", "অতএব, আমাকে তাদের বিষয়ে ব্যবস্থা নিতে দাও যারা এই হাদিস প্রত্যাখ্যান করে, আমরা তাদেরকে সেখানে পরিচালিত করবো যেখানে তারা কখনই অনুধাবন করে না।"],
  "68:45": ["And I give them respite — My scheme is firm.", "আমি তাদেরকে যথেষ্ট ছাড় দেব; আমার পরিকল্পনা অভেদ্য।"],
  "68:46": ["Or do you ask them a wage, so that they are weighed down with liability?", "তুমি কি তাদের কাছে অর্থ চাইছো, তাই তারা জরিমানার কারণে ভারগ্রস্থ হয়ে পড়েছে?"],
  "68:47": ["Or do they have the unseen, that they write it down?", "তারা কি ভবিষ্যৎ জানে? তাদের কাছে কি তা লিপিবদ্ধ আছে?"],
  "68:48": ["So be of the sabirin for the judgment of your Rabb, and do not be like the companion of the fish, when he cried out, choked with grief.", "তুমি তোমার প্রভুর হুকুম পালনে দৃঢ়তার সাথে অবিচল থাকবে। (ইউনুস, ) যে মাছের ভিতর থেকে ডেকেছিল তার মতো হইও না।"],
  "68:49": ["Had not a favor from his Rabb overtaken him, he would have been cast out onto the open ground, disgraced.", "যদি তোমার প্রভুর পক্ষ থেকে করুণা না হতো, তবে সে পাপী হিসেবে মরুভূমিতে নিক্ষিপ্ত হতো।"],
  "68:50": ["So his Rabb chose him and made him among the salihin.", "কিন্তু তার প্রভু তাকে অনুগ্রহ করলেন, এবং তাকে সৎকর্মশীল বানালেন।"],
  "68:51": ["And indeed those who deny almost make you slip with their eyes when they hear the reminder, and they say, 'He is surely mad.'", "যারা অবিশ্বাস করে, তারা যখন বার্তা শোনে তারা তাদের চাহনি দিয়ে উপহাস করে এবং বলে, “সে পাগল!”"],
  "68:52": ["And it is nothing but a reminder for all the world.", "এটি প্রকৃতপক্ষে বিশ্ববাসীর কাছে একটি বার্তা।"],
  "69:1": ["The Reality", "সে তর্কাতীত (ঘটনা)।"],
  "69:2": ["What is the Reality?", "কি এক তর্কাতীত (ঘটনা)!"],
  "69:3": ["What could tell you what the Reality is?", "এটি সত্যিই তর্কাতীত।"],
  "69:4": ["Thamud and Aad denied the Striking.", "সামুদ ও আ'দ অবিশ্বাস করেছিল আঘাতকারীকে।"],
  "69:5": ["As for Thamud, they were destroyed by the Transgression.", "সামুদের ক্ষেত্রে, তারা বিলুপ্ত হয়েছিল বিধ্বংসী (কম্পন) দ্বারা।"],
  "69:6": ["And as for Aad, they were destroyed by a roaring, violent wind.", "আ'দের ক্ষেত্রে, তারা বিলুপ্ত হয়েছিল এক অনবরত, তীব্র ঝড় দ্বারা।"],
  "69:7": ["It was set loose on them for seven nights and eight days without letup, so that you would see the people lying dead in it as if they were trunks of collapsed palm-trees.", "একে তিনি তাদের উপর ছেড়ে দিয়েছিলেন সাত রাত ও আট দিনের জন্য, হিংস্রভাবে। তুমি লোকদের দেখতে পেতে চারদিকে ছুড়ে পড়ছিল, ক্ষয়প্রাপ্ত খেজুর গাছের কাণ্ডের মতো।"],
  "69:8": ["So do you see any remnant of them?", "তুমি কি তাদের কারো চিহ্ন পাও?"],
  "69:9": ["And Fir'awn came, and those before him, and the Overturned Cities, in their sin.", "ফেরাউন, তার পূর্বে অন্যরা এবং (সডমের) পাপিরা ছিল মন্দ।"],
  "69:10": ["They disobeyed the Rasul of their Rabb, so a towering seizure seized them.", "তারা তাদের প্রভুর বার্তাবাহককে অমান্য করেছিল। পরিণামে, তিনি তাদের প্রতিদান দিয়েছিলেন, বিধ্বংসী এক প্রতিদান।"],
  "69:11": ["When the water transgressed, We carried you in the running vessel.", "বন্যাটি ছিল বিধ্বংসী, তাই আমরা তোমাদের ভাসমান (নৌযানে) আরোহণ করিয়েছিলাম।"],
  "69:12": ["So that We might make it a reminder for you, and a heeding ear might take it to heart.", "আমরা তোমাদের জন্য একে করেছি একটি শিক্ষা, যাতে কোন শ্রবনরত কান বুঝতে পারে।"],
  "69:13": ["Then, when the trumpet is blown with a single blast,", "একবার যখন শিঙ্গায় ফুঁ দেয়া হয়।"],
  "69:14": ["and the earth and the mountains are lifted up and pounded with a single pounding,", "পৃথিবী ও পর্বতমালাকে বয়ে আনা হবে এবং চূর্ণ-বিচূর্ণ করা হবে; একেবারেই চূর্ণ-বিচূর্ণ।"],
  "69:15": ["then on that day the Event comes to pass.", "ঐটা সেই দিন যখন সে অনিবার্য ঘটনা সংঘটিত হবে।"],
  "69:16": ["And the sky splits open, and on that day it is frail.", "আকাশ ফেটে পড়বে, এবং ছিন্ন হবে।"],
  "69:17": ["And the malakat will be ranged at its edges, and the arsh of your Rabb will be carried above them that day by eight bearers.", "ফেরেশতারা চারদিকে থাকবে, এবং তোমার প্রভুর রাজ্য তখন পরিবেষ্টন করবে আট (মহাবিশ্বে)।"],
  "69:18": ["On that day you will be brought forth, and nothing of you will remain hidden.", "ঐদিন, তোমাদের আসল চেহারা উন্মোচিত হবে, তোমাদের কোনকিছুই গোপন করা যাবে না।"],
  "69:19": ["As for the one who is given his book in his right hand, he will say: \"Here, take and read my book.", "আর যে ব্যক্তি তার রেকর্ড তার ডান হাতে পায়, সে বলবে, “এসো আমার নথিটি পড়।"],
  "69:20": ["I was sure I would meet my reckoning.", "“আমার বিশ্বাস ছিল যে আমাকে জবাবদিহি করতে হবে। ”"],
  "69:21": ["So he lives in contentment,", "সে সুখী জীবন অর্জন করেছে।"],
  "69:22": ["in a lofty garden,", "একটি মহিমান্বিত স্বর্গে।"],
  "69:23": ["with fruit-clusters hanging within reach.", "এর ফলগুলো হাতের নাগালের মধ্যে।"],
  "69:24": ["Eat and drink with pleasure for what you sent ahead in the days now past.\"", "অতীতের দিনগুলোয় তোমাদের কাজের বিনিময়ে সানন্দে খাও এবং পান করো।"],
  "69:25": ["But as for the one given his book in his left hand, he will say: \"If only I had not been given my book,", "আর যার নথি তার বাম হাতে দেয়া হবে, সে বলবে, “হায়, আমি যদি কখনই আমার নথি না পেতাম।"],
  "69:26": ["and had never known what my reckoning was!", "“আমি যদি কখনই আমার হিসাব না জানতাম।"],
  "69:27": ["If only it had been the decisive end!", "“আমার মৃত্যুই যদি চিরস্থায়ী হত।"],
  "69:28": ["My wealth was no use to me;", "“আমার টাকাপয়সা আমাকে সাহায্য করতে পারে না।"],
  "69:29": ["my power has perished away from me.\"", "“আমার সকল ক্ষমতা চলে গেছে।”"],
  "69:30": ["Seize him and shackle him,", "তাকে নিয়ে চলো এবং তাকে শৃঙ্খলিত করো।"],
  "69:31": ["then into the Blazing Fire with him,", "তাকে নরকে পুঁড়াও।"],
  "69:32": ["then bind him in a chain seventy cubits long — thread him through.", "সত্তুর হাত লম্বা শিকলে, তাকে বাঁধ।"],
  "69:33": ["He did not believe in Allah the Great,", "কারন সে সবচেয়ে মহান আল্লাহকে বিশ্বাস করতো না ।"],
  "69:34": ["and never urged the feeding of the needy.", "না সে গরিবদের খাওয়ানোর পরামর্শ দিত ।"],
  "69:35": ["So today he has no devoted friend here,", "পরিণামে, এখানে তার কোন বন্ধু নেই।"],
  "69:36": ["and no food except foul, festering filth", "না কোন খাদ্য, তেতো প্রকারের খাদ্য ব্যতীত।"],
  "69:37": ["that none but the erring eat.", "পাপীদের খাবার।"],
  "69:38": ["Nay, I swear by all that you see", "আমি তার শপথ করি যা তোমরা দেখো।"],
  "69:39": ["and by all that you do not see:", "এবং যা তোমরা দেখো না।"],
  "69:40": ["it is indeed the word of a noble Rasul,", "এটি একজন সন্মানিত বার্তাবাহকের কথা।"],
  "69:41": ["not the word of a poet — little do you believe —", "না কোন কবির কথা; তোমরা খুব কম ক্ষেত্রেই বিশ্বাস করো।"],
  "69:42": ["nor the word of a soothsayer — little do you remember.", "না কোন ভবিষ্যৎ-বক্তার কথা; তোমরা খুব কম ক্ষেত্রেই উপদেশ গ্রহণ করো।"],
  "69:43": ["It is a sending-down from the Rabb of the worlds.", "মহাবিশ্বের প্রভুর পক্ষ থেকে একটি প্রকাশনা।"],
  "69:44": ["If he had invented some sayings in Our name,", "যদি সে অন্য কোন শিক্ষা উচ্চারণ করতো।"],
  "69:45": ["We would have seized him by the right hand,", "আমরা তাকে শাস্তি দিতাম।"],
  "69:46": ["then We would have cut off his lifeline,", "আমরা তার কাছে প্রত্যাদেশ পাঠানো বন্ধ করে দিতাম।"],
  "69:47": ["and none of you could have held Us back.", "তোমাদের কেউ তাকে সাহায্য করতে পারতে না।"],
  "69:48": ["Yet it is a reminder for the mindful,", "এটি সৎকর্মশীলদের জন্য একটি সতর্কবানী।"],
  "69:49": ["and We know that some of you deny it.", "আমরা জানি; তোমাদের কেউ কেউ প্রত্যাখ্যানকারী।"],
  "69:50": ["And it is surely bitter regret for the kafirin.", "এটি তো কেবল অবিশ্বাসীদের জন্য দুঃখ।"],
  "69:51": ["And it is the certain truth.", "এটি পরম সত্য।"],
  "69:52": ["So glorify the name of your Rabb, the Most Great.", "অতএব, তুমি তোমার প্রভুর নামের মহিমা ঘোষণা করবে, যিনি সবচেয়ে মহান।"],
  "70:1": ["A questioner asked about the punishment that will befall.", "একজন প্রশ্নকারী অনিবার্য শাস্তির বিষয়ে প্রশ্ন করতে পারে।"],
  "70:2": ["For the kafirin there is none to push it back.", "অবিশ্বাসীদের জন্য, কেউ তা থামাতে পারবে না।"],
  "70:3": ["It is from Allah, possessor of the ascents.", "ঈশ্বর থেকে; উচ্চতম উচ্চতার অধিকারী।"],
  "70:4": ["The malakat and the spirit ascend to Allah on a day whose measure is fifty thousand years.", "ফেরেশতারা, তাদের প্রতিবেদন নিয়ে, তাঁর দিকে এক দিনে আরোহণ করে, যা পঞ্চাশ হাজার বছরের সমান।"],
  "70:5": ["So be of the sabirin with beautiful patience.", "অতএব, তুমি সদয় ধৈর্য ধারন করো।"],
  "70:6": ["They see it as far away,", "কারন তারা তা দেখে অনেক দূরে।"],
  "70:7": ["and We see it as near.", "আর আমরা একে দেখি খুব নিকটে।"],
  "70:8": ["On the day the sky becomes like boiling mire,", "সেদিন আসবে যখন আকাশ গলিত পাথরের মতো হবে।"],
  "70:9": ["and the mountains become like drifting fluff,", "পর্বতমালা হবে তুলতুলে পশমের মতো।"],
  "70:10": ["no bosom friend will ask after a bosom friend,", "কোন বন্ধু তার অন্তরঙ্গ বন্ধুর খবর নিবে না।"],
  "70:11": ["for they are made to see one another. The guilty one would wish to ransom himself from the punishment of that day with his children,", "যখন এরা তাদের দেখবে, অপরাধীরা ইচ্ছা করবে যদি সে তার নিজের সন্তান-সন্ততিকে ক্ষতিপূরণ হিসেবে দিতে পারতো, ঐ দিনের শাস্তি থেকে তাকে রক্ষা করতে।"],
  "70:12": ["with his spouse and his brother,", "তার স্ত্রী, এবং তার ভাইকেও।"],
  "70:13": ["with his kin who sheltered him,", "এমনকি তার সমগ্র জাতিকে যারা তার লালন পালন করেছিল।"],
  "70:14": ["and with all who are on earth, every one of them, if only that could save him.", "এমনকি পৃথিবীর সকল লোককে, যদি তা তাকে রক্ষা করতে পারে।"],
  "70:15": ["No indeed — it is a blaze,", "না; এটি জ্বলছে।"],
  "70:16": ["one that keeps tearing at the flesh,", "জ্বালাতে উদগ্রীব।"],
  "70:17": ["calling whoever turned their back and walked away,", "এটি আহবান করে তাদেরকে যারা মুখ ফিরিয়ে নিয়েছিল।"],
  "70:18": ["who gathered and hoarded.", "তাদেরকে যারা জমা করতো আর গুনতো।"],
  "70:19": ["Indeed the human being was created fretful and grasping:", "নিশ্চয়, মানুষ উদ্বিগ্ন।"],
  "70:20": ["when evil touches him, he is full of distress,", "দুর্দশা স্পর্শ করলে, হতাশ।"],
  "70:21": ["and when good touches him, he is tight-fisted.", "সম্পদ দ্বারা সৌভাগ্যবান হলে, কৃপণ।"],
  "70:22": ["Except those who pray,", "উপাসনাকারীরা ব্যতিত।"],
  "70:23": ["who are constant in their prayer,", "যারা সবসময় তাদের সংযোগ প্রার্থনা (সালাত) পালন করে।"],
  "70:24": ["and in whose wealth there is a known right", "তাদের অর্থের একটি অংশ আলাদা করা থাকে।"],
  "70:25": ["for the beggar and the deprived,", "গরীব ও অভাবগ্রস্থদের জন্য।"],
  "70:26": ["and who affirm the Day of Recompense,", "তারা বিশ্বাস করে বিচার দিনকে।"],
  "70:27": ["and who stand in awe of the punishment of their Rabb —", "তারা তাদের প্রভুর প্রতিদানকে ভক্তি-শ্রদ্ধা করে।"],
  "70:28": ["for no one is safe from the punishment of their Rabb —", "তাদের প্রভুর প্রতিশোধকে হাল্কা ভাবে নেয় না।"],
  "70:29": ["and who guard their private parts,", "তারা তাদের সতীত্ব বজায় রাখে।"],
  "70:30": ["except with their spouses or those their right hands possess; for those are beyond blame,", "(তাদের সম্পর্ক আছে) কেবল মাত্র তাদের স্বামী/স্ত্রীর সাথে, অথবা যা আইনত তাদের-"],
  "70:31": ["but whoever seeks beyond that — those are the ones who transgress.", "যেকেউ এই সীমা অতিক্রম করে সে একজন পাপী।"],
  "70:32": ["And those who keep their trusts and their pledges,", "এবং বিশ্বাসীরা তাদের কথা রাখে; তারা বিশ্বস্ত।"],
  "70:33": ["who stand firm in their testimony,", "তাদের সাক্ষ্য সত্যনিষ্ঠ।"],
  "70:34": ["and who carefully guard their prayer.", "তারা ধারাবাহিকভাবে তাদের সংযোগ প্রার্থনা (সালাত) পালন করে, যথাসময়ে।"],
  "70:35": ["Those shall be in gardens, honored.", "স্বর্গে, তারা একটি সন্মানিত অবস্থানের যোগ্য হয়েছে।"],
  "70:36": ["So what is with those who disbelieve, rushing ahead of you,", "যারা অবিশ্বাস করে, তাদেরকে কি বাধাঁ দিচ্ছে, তোমার সাথে যোগ দেয়ার ক্ষেত্রে?"],
  "70:37": ["in bands to the right and to the left?", "ডানে ও বামে, তারা পালায়।"],
  "70:38": ["Does every one of them hope to be admitted into a garden of bliss?", "কেমন করে তাদের কেউ পরম সুখের স্বর্গে প্রবেশের আশা করতে পারে?"],
  "70:39": ["No indeed! We created them out of what they know.", "কখনো না; আমরা তাদের সৃষ্টি করেছি এবং তারা জানে কি থেকে।"],
  "70:40": ["So I swear by the Rabb of the east and the west — We are truly able", "আমি শপথ করি পূর্ব এবং পশ্চিমের প্রভুর; আমরা সক্ষম-"],
  "70:41": ["to replace them with people better than them, and none can outstrip Us.", "তোমাদের স্থানে উত্তম লোকদের আনতে; আমরা কখনো পরাজিত হতে পারি না।"],
  "70:42": ["So leave them to wade in idle talk and to play, until they meet the day they are promised,", "অতএব, তাদেরকে বিভ্রমে এবং ক্রিয়াকর্মে পড়ে থাকতে দাও, যতক্ষণ না তারা সে দিনের সাক্ষাৎ পায়, যা তাদের জন্য অপেক্ষা করছে।"],
  "70:43": ["the day they come out of the graves in haste, as if rushing toward an erected post,", "ঐদিন তারা তাড়াহুড়া করে কবর থেকে বের হয়ে আসবে, যেন একত্রে চালিত হচ্ছে (বলিদানের) বেদির দিকে।"],
  "70:44": ["their eyes humbled, abasement overwhelming them. That is the day they were promised.", "তাদের দৃষ্টি অবনমিত থাকবে, লজ্জা তাদের ঢেকে ফেলবে। এটাই সে দিন যা তাদের জন্য অপেক্ষা করছে।"],
  "71:1": ["We sent Nuh to his people to warn his people before a painful punishment comes to them.", "আমরা নূহকে তার লোকদের কাছে পাঠিয়েছিলামঃ “তুমি তোমার লোকদের সতর্ক করো একটি যন্ত্রণাদায়ক শাস্তি তাদের কাছে আসার আগে।”"],
  "71:2": ["He said: O my people, I am a clear warner to you.", "সে বলল, “হে আমার লোকেরা, আমি তোমাদের কাছে একজন স্পষ্ট সতর্ককারী।"],
  "71:3": ["Worship Allah, and be mindful of Allah, and obey me.", "“তোমাদের সতর্ক করতে যে তোমরা ঈশ্বরের উপাসনা করো, তাঁকে সম্মান করো, এবং আমাকে মান্য করো।"],
  "71:4": ["Allah will forgive you of your offenses and grant you extension to a named term; the term of Allah, when it comes, cannot be delayed — if only you knew.", "“তিনি তবে তোমাদের পাপ ক্ষমা করবেন এবং একটি পূর্বনির্ধারিত সময় পর্যন্ত তোমাদের অবকাশ দেবেন। অবশ্যই, ঈশ্বরের সাথে সাক্ষাতের নির্ধারিত সময় কখনো বিলম্বিত হতে পারে না, একবার এর সময় হলে, যদি শুধু তোমরা জানতে।”"],
  "71:5": ["He said: My Rabb, I called my people night and day.", "সে বলল, “আমার প্রভু, আমি আমার লোকদের দাওয়াত দিয়েছি রাতে ও দিনে।"],
  "71:6": ["But my call has only increased them in fleeing.", "“কিন্তু আমার দাওয়াত কেবল তাদের বিমুখতা বাড়িয়ে দিয়েছিল।"],
  "71:7": ["And whenever I called them, that You might forgive them, they put their fingers in their ears, and covered themselves with their garments, and persisted, and grew ever more arrogant.", "“যখনি আমি তাদের দাওয়াত দিয়েছিলাম যে আপনি তাদের ক্ষমা করবেন, তারা তাদের কানে আঙ্গুল দিয়েছে, নিজেদের ঢেকে ফেলেছে তাদের কাপড় দিয়ে, জিদ করেছে, এবং উদ্ধত হয়েছে।"],
  "71:8": ["Then I called them out loud.", "“এরপর আমি তদের দাওয়াত দিয়েছিলাম জনসমক্ষে।"],
  "71:9": ["Then I declared it to them openly, and confided it to them in secret.", "“এরপর আমি তাদের কাছে ঘোষণা করেছিলাম উচ্চস্বরে, এবং আমি তাদের সাথে কথা বলেছিলাম ব্যক্তিগতভাবে।"],
  "71:10": ["And I said: Seek forgiveness of your Rabb; your Rabb has always been forgiving.", "“আমি বলেছিলাম, “তোমাদের প্রভুর কাছে ক্ষমা প্রার্থনা করো; তিনি ক্ষমাশীল।"],
  "71:11": ["Allah will send the sky upon you pouring.", "“তিনি তবে তোমাদের জন্য উদারভাবে বৃষ্টি বর্ষণ করবেন।"],
  "71:12": ["And supply you with wealth and sons, and make for you gardens, and make for you rivers.", "“আর তোমাদের দেবেন অর্থ ও সন্তানাদি, এবং ফলের বাগান ও ঝর্ণা।"],
  "71:13": ["What is the matter with you, that you do not hope for gravity for Allah?", "কেন তোমরা ঈশ্বরের সম্মান করতে সংগ্রাম করো না?"],
  "71:14": ["And Allah created you in stages.", "তিনিই সে সত্ত্বা যিনি তোমাদের সৃষ্টি করেছেন পর্যায়ক্রমে।"],
  "71:15": ["Do you not see how Allah created seven heavens in layers?", "তোমরা কি অনুধাবন করো না যে ঈশ্বর সাত মহাবিশ্ব সৃষ্টি করেছেন স্তরে স্তরে।"],
  "71:16": ["And made the moon a light in them, and made the sun a blazing lamp.", "সেখানে তিনি চাঁদের নকশা করেছেন একটি আলো হিসেবে, আর সূর্যকে স্থাপন করেছেন একটি প্রদীপ হিসেবে।"],
  "71:17": ["And Allah grew you from the earth as a growth.", "এবং ঈশ্বর পৃথিবী থেকে তোমাদের অঙ্কুরিত করেছেন উদ্ভিদের মতো।"],
  "71:18": ["Then Allah returns you into it, and brings you out.", "এরপর তিনি এর মধ্যে তোমাদের ফিরে যেতে দেন, এবং তিনি অবশ্যই তোমাদের বের করে আনবেন।"],
  "71:19": ["And Allah made the earth for you a spread-out carpet.", "পৃথিবীকে ঈশ্বর তোমাদের জন্য বাসযোগ্য করেছেন।"],
  "71:20": ["So that you may thread through it wide ways.", "যাতে তোমরা সেখানে রাস্তা নির্মাণ করতে পারো।"],
  "71:21": ["Nuh said: My Rabb, they have disobeyed me, and followed those whose wealth and children have only increased them in loss.", "নুহ বলেছিল, “আমার প্রভু, তারা আমাকে অমান্য করেছিল আর তাদের অনুসরণ করেছিল যারা আরও বেশি কলুষিত ছিল যখন অর্থ ও সন্তানাদি পেয়ে সৌভাগ্যশালী ছিল।"],
  "71:22": ["And they planned a great plan.", "‘তারা চক্রান্ত করেছিল ভয়াবহ চক্রান্ত।"],
  "71:23": ["And they said: Do not leave your ilahs, and do not leave Wadd, nor Suwa, nor Yaghuth, and Ya'uq, and Nasr.", "“তারা বলেছিল, “তোমাদের উপাস্যদের ত্যাগ করো না। ত্যাগ করো না ওয়াদ্দ, সুয়আ, ইয়াঘউথ, ইয়াউক ও নাসরকে।\""],
  "71:24": ["And they have led many astray; so increase the wrongdoers only in straying.", "“তারা অনেককে পথভ্রষ্ট করেছে। অতএব, মন্দদের ক্ষতির গভীরে নিমজ্জিত হতে দাও।”"],
  "71:25": ["For their errs they were drowned and made to enter a fire, and they found for themselves, besides Allah, no helpers.", "পাপের কারনে তাদের ডুবিয়ে দেয়া হয়েছিল এবং নরকাগ্নির জন্য নির্ধারিত হলো। ঈশ্বর থেকে রক্ষা পেতে তারা কোন সাহায্যকারী পাইনি।"],
  "71:26": ["And Nuh said: My Rabb, do not leave upon the earth a single dwelling of the kafirin.", "নুহ আরও বলেছিল, “আমার প্রভু, পৃথিবীতে একজন অবিশ্বাসীকেও ছেড়ে দেবেন না।"],
  "71:27": ["If You leave them, they will lead Your servants astray, and they will beget none but an immoral kafir.", "“কারন যদি আপনি তাদের ছেড়ে দেন, তারা কেবল আপনার বান্দাদের পথভ্রষ্ট করবে এবং মন্দ অবিশ্বাসী ছাড়া কোনকিছু জন্ম দেবে না।"],
  "71:28": ["My Rabb, forgive me and my children, and whoever enters my house as a mumin, and the believing men and the believing nisa; and do not increase the wrongdoers except in ruin.", "“আমার প্রভু, আমাকে ক্ষমা করুন ও আমার পিতামাতাকে এবং যেকেউ আমার গৃহে বিশ্বাসী হিসেবে প্রবেশ করে তাদেরকে, এবং সকল বিশ্বাসী পুরুষ ও নারীকে। কিন্তু অবিশ্বাসীদের ধ্বংস ছাড়া কিছু দেবেন না।”"],
  "72:1": ["Say: it was revealed to me that a band of the jinn listened and said: We heard a marvellous recitation.", "বল, “আমাকে প্রত্যাদিষ্ট হয়েছি যে জিনদের একটি দল শুনেছিল, তারপর বলল, “আমরা এক বিস্ময়কর কুরআন শুনেছি।"],
  "72:2": ["It guides to the course, so we believed in it, and we will never associate with our Rabb anyone.", "“এটি সৎকর্মশীলতার দিকে পথনির্দেশ করে, এবং একে আমরা বিশ্বাস করেছি; আমরা কখনো আমাদের প্রভুর পাশে কোন উপাস্য স্থাপন করবো না।"],
  "72:3": ["And that exalted is the new-made of our Rabb, that has taken no companion and no child.", "“আমাদের একমাত্র প্রভু হলেন সর্বোচ্চ। কখনো তাঁর কোন সঙ্গি ছিল না, না ছিল পুত্র।"],
  "72:4": ["And that the foolish one among us used to say of Allah a transgression.", "আমাদের মধ্যে বোকারাই ঈশ্বর সম্পর্কে এমন নির্বোধের মতো কথা বলতো।"],
  "72:5": ["And we thought that humankind and the jinn would never say of Allah a lie.", "“আমরা মনে করতাম যে ঈশ্বর সম্পর্কে না মানুষ, না জীনরা, মিথ্যা বলতে পারে।"],
  "72:6": ["And that men of humankind used to seek refuge with men of the jinn, and they increased them in overwhelming.", "“মানুষরা জীনদের মাধ্যমে শক্তি খুজঁতো, কিন্তু তারা কেবল নিজেদের অনেক অনেক দুর্দশায় জর্জরিত করেছে।"],
  "72:7": ["And they thought, as you thought, that Allah would never raise anyone.", "“তারা মনে করতো, ঠিক যেমন তোমরা মনে করতে, যে ঈশ্বর অন্যকোন (বার্তাবাহক) পাঠাবেন না।"],
  "72:8": ["And we touched the sky and found it filled with severe guards and fire-missiles.", "“আমরা আকাশ স্পর্শ করেছিলাম, আর একে পেলাম শক্তিশালী প্রহরী ও ক্ষেপণাস্ত্র দ্বারা পূর্ণ।"],
  "72:9": ["And we used to sit in it, seats for listening; but whoever listens now finds a fire-missile keeping watch over him.", "“আমরা গুপ্তচরবৃত্তির জন্য সেখানে বসে থাকতাম। যেকেউ শুনে, তাকে এক শক্তিশালী ক্ষেপণাস্ত্র ধাওয়া করে।"],
  "72:10": ["And we do not know whether evil is intended for those on earth, or whether their Rabb intends for them a course.", "“আমাদের কোন ধারণা নেই পৃথিবীর বাসিন্দাদের জন্য খারাপ কিছু করার ইচ্ছা আছে, না তাদের প্রভু তাদের পুনরুদ্ধার করতে চান।"],
  "72:11": ["And among us are the sound ones, and among us are below that: we were paths torn apart.", "“আমাদের কেউ কেউ সৎ-কর্মপরায়ণ এবং কেউ কেউ কম সৎ-কর্মপরায়ণ; আমরা বিভিন্ন পথ অনুসরণ করি।"],
  "72:12": ["And we thought that we could never be beyond Allah's power on earth, nor could we be beyond the power in fleeing.", "“আমরা খুব ভালভাবে জানতাম যে পৃথিবীতে আমরা ঈশ্বর থেকে কখনো পালাতে পারবো না; আমরা কখনো পালিয়ে যেতে এবং মুক্তি পেতে পারবো না।"],
  "72:13": ["And when we heard the guidance we believed in it, so whoever believes in the Rabb fears neither diminution nor overwhelming.", "যখন আমরা পথনির্দেশনা শুনেছিলাম, আমরা তাতে বিশ্বাস স্থাপন করেছি। যেকেউ তার প্রভুকে বিশ্বাস করে সে কখনো কোন অবিচার, না কোন কষ্টের আশংকা করবে।"],
  "72:14": ["And among us are the submitters, and among us are the deviators; so whoever submits — those have sought a course.", "“আমাদের মধ্যে আছে আত্মসমর্পণকারীরা, এবং আমাদের মধ্যে আছে আপোষকারীরা।” যারা আত্মসমর্পণ করেছে, তারা সঠিক পথে আছে।"],
  "72:15": ["And as for the deviators, they were firewood for Hell.", "আপোষকারীদের ক্ষেত্রে, তারা হবে জাহান্নামের জ্বালানী।"],
  "72:16": ["And if they had kept straight upon the path, We would have given them water to drink, abundant.", "যদি তারা সঠিক পথে থাকে, আমরা প্রচুর পরিমান পানি দিয়ে তাদের সৌভাগ্যবান করবো।"],
  "72:17": ["To try them thereby; and whoever turns away from the remembrance of the Rabb, a mounting punishment is threaded through them.", "আমরা অবশ্যই তাদের সকলকে পরীক্ষা করব। যে ব্যক্তি তার প্রভুর বার্তাকে উপেক্ষা করে, তিনি তাকে ক্রমবর্ধমান শাস্তির দিকে পরিচালিত করবেন।"],
  "72:18": ["And that the place of prostration belongs to Allah, so invoke no one alongside Allah.", "উপাসনার স্থানগুলো ঈশ্বরের; ঈশ্বরের পাশে অন্য কাউকে ডেকো না।"],
  "72:19": ["And that when the servant of Allah stood up calling upon Allah, they nearly became a thick mass upon him.", "যখন ঈশ্বরের বান্দা একমাত্র তাঁর ওকালতি করেছিল, তাদের প্রায় সকলেই তার বিরোধিতা করার জন্য একত্রিত হয়ে গেল।"],
  "72:20": ["Say: I only call upon my Rabb, and I associate no one with Allah.", "বল, “আমি একমাত্র আমার প্রভুর উপাসনা করি; আমি কখনই তাঁর পাশে কোন উপাস্য স্থাপন করি না।”"],
  "72:21": ["Say: I have no power over you, neither for harm nor for a course.", "বল, “আমার কোন ক্ষমতা নেই তোমাদের ক্ষতি করার, না তোমাদের পথ দেখাবার।”"],
  "72:22": ["Say: no one can shelter me from Allah, and I will not find, apart from Allah, any refuge sought.", "বল, “কেউ আমাকে ঈশ্বরের হাত থেকে রক্ষা করতে পারে না, না আমি তার পাশে অন্য কোন আশ্রয় পেতে পারি।"],
  "72:23": ["Except for a reaching from Allah and the Rasuls; and whoever disobeys Allah and the Rasul, there awaits the fire of Hell, remaining in it forever.", "“আমি ঈশ্বরের ঘোষণা ও বার্তা পৌঁছে দেই।” যারা ঈশ্বর ও তার বার্তাবাহককে অমান্য করে তারা টেনে আনে নরকের আগুন, যেখানে তারা চিরকাল বাস করে।"],
  "72:24": ["Until, when they see what they are promised, they will know who is weaker as a helper and fewer in number.", "একবার যখন তারা দেখে তাদের জন্য কি অপেক্ষা করছে, তারা দেখতে পাবে কারা সত্যিকার অর্থে শক্তিতে দুর্বল ও সংখ্যায় কম।"],
  "72:25": ["Say: I do not know whether what you are promised is near, or whether my Rabb appoints for it a term.", "বল, “আমি জানি না তোমাদের কাছে যার অঙ্গীকার করা হয় তা কি শীঘ্রই ঘটবে, নাকি আমার প্রভু কিছু সময়ের জন্য একে বিলম্বিত করাবেন।”"],
  "72:26": ["Knower of the unseen, and the unseen is disclosed to no one.", "তিনি ভবিষ্যত জান্তা; তিনি কারো কাছে ভবিষ্যতের কথা প্রকাশ করেন না।"],
  "72:27": ["Except one approved as a Rasul; then threads through, before and behind, watch-posts.", "শুধু তিনি পছন্দ করেন এমন একজন বার্তাবাহকের কাছে, তিনি অতীত ও ভবিষ্যৎ থেকে নির্দিষ্ট সংবাদ প্রকাশ করেন।"],
  "72:28": ["So that Allah may know that they have conveyed the messages of their Rabb, and Allah has encompassed all that is with them, and has counted everything in number.", "এর কারণ নিশ্চিত করা যে তারা তাদের প্রভুর বানী পৌঁছে দিয়েছে। তাদের কাছে যা আছে সে সম্পর্কে তিনি পুরোপুরি অবহিত। তিনি সমস্ত বস্তুর সংখ্যা গণনা করে রেখেছেন।"],
  "73:1": ["O you who are wrapped up", "ও হে চাদর আবৃত।"],
  "73:2": ["Stand through the night, except a little of it", "রাতে ধ্যান করো, কদাচিৎ ছাড়া।"],
  "73:3": ["its half, or diminish from it a little", "এর অর্ধেক, বা কিছু কম।"],
  "73:4": ["or add to it, and recite the Qur'an with a measured recitation", "বা কিছু বেশি। এবং কুরআন পড় প্রথম থেকে শেষ পর্যন্ত।"],
  "73:5": ["Indeed We shall bring down upon you a weighty word", "তোমাকে আমরা একটি ভারি বার্তা দিব।"],
  "73:6": ["Indeed the rising of the night presses harder and is more upright in word", "রাতের ধ্যান বেশি কার্যকর, এবং বেশি ন্যায়নিষ্ঠ।"],
  "73:7": ["Indeed you have in the day a long occupation", "দিনের বেলায় তোমার অনেকটা সময় অন্যান্য বিষয়ের জন্য রয়েছে ।"],
  "73:8": ["And remember the name of your Rabb, and devote yourself to your Rabb with a full devotion", "তুমি তোমার প্রভুর নাম স্মরণ কর, তাঁর আরো নিকট থেকে নিকটে আসতে।"],
  "73:9": ["Rabb of the east and of the west; there is no ilah but Allah; so take Allah as a trustee", "পূর্ব ও পশ্চিমের প্রভু, তাঁর পাশে অন্য উপাস্য নেই। তোমার উকিল হিসাবে তাঁকে বেছে নেয়া উচিত।"],
  "73:10": ["And be of the sabirin over what they say, and forsake them with a beautiful forsaking", "এবং তাদের কথার বিপরীতে দৃঢ় থাকো, এবং তাদের উপেক্ষা কর সুন্দরভাবে।"],
  "73:11": ["Leave Me with the mukazzibin, the possessors of blessing, and give them a little respite", "এবং প্রত্যাখ্যানকারীদের আমার হাতে ছেড়ে দাও, যাদের অনুগ্রহ করা হয়েছে উদারভাবে; তাদেরকে শুধু কিছু সময় দাও।"],
  "73:12": ["Indeed with Us are warning-seizures and a blaze", "আমাদের কাছে আছে কঠোর শাস্তি, এবং নরক।"],
  "73:13": ["and a food that chokes, and a painful punishment", "খাবার যা কষ্ট করে গেলা যায় ও যন্ত্রণাদায়ক শাস্তি।"],
  "73:14": ["the day the earth and the rocky landforms quake, and the rocky landforms become a dune poured loose", "সেদিন আসবে যখন পৃথিবী ও পর্বতমালা কম্পিত হবে, এবং পর্বতমালা ভারহীন স্তূপে পরিণত হবে।"],
  "73:15": ["Indeed We sent to you a Rasul as a witness over you, just as We sent to Fir'awn a Rasul", "আমরা তোমাদের কাছে একজন বার্তাবাহক পাঠিয়েছি, ঠিক যেমন আমরা ফেরাউনের কাছে একজন বার্তাবাহক পাঠিয়েছিলাম।"],
  "73:16": ["Fir'awn disobeyed the Rasul, so We seized him with a seizure heavy in cost", "ফেরাউন বার্তাবাহককে অমান্য করেছিল এবং পরিণামে, আমরা তাকে কঠিন শাস্তি দিয়েছিলাম।"],
  "73:17": ["So how will you guard yourselves, if you deny a day that turns children white-haired", "যদি তোমরা অবিশ্বাস করো, তবে কেমন করে এমন এক দিনকে তোমরা এড়াতে পারো যা এতো ভয়াবহ যে এটি শিশুদের বানিয়ে দেয় ধূসর কেশযুক্ত?"],
  "73:18": ["the sky is split open by it; that was ever a promise to be done", "আকাশ সেখান থেকে বিদীর্ণ হবে। তাঁর প্রতিশ্রুতি সত্য।"],
  "73:19": ["Indeed this is a reminder; so whoever wills, let them take a way to their Rabb", "এটি একটি সতর্কবাণী; যার ইচ্ছা, সে যেন তার প্রভুর দিকের পথ বেছে নেয়।"],
  "73:20": ["Indeed your Rabb knows that you stand less than two-thirds of the night, and its half, and its third, and a party of those with you; and Allah measures the night and the day. Knowing that you will not count it, Allah has relented toward you, so recite what is made easy of the Qur'an. Allah knows that among you will be sick ones, and others striking out across the land seeking from the bounty of Allah, and others killed in the way of Allah. So recite what is easy of it, establish the prayer, give the alms, and lend Allah a goodly loan. Whatever good you send ahead for yourselves, you will find it with Allah; it is better and greater in reward. And seek forgiveness of Allah; indeed Allah is forgiving, merciful.", "তোমার প্রভু জানেন যে তুমি রাতের দুই-তৃতীয়াংশ, অথবা এর অর্ধেক বা এর এক তৃতীয়াংশ সময় ধ্যান কর এবং তোমার সাথে যারা বিশ্বাস করেছে তাদের মধ্যেও কেউ কেউ তা করে। ঈশ্বর রাত ও দিনের নকশা করেছেন এবং তিনি জানেন যে তোমরা সর্বদা এটি করতে পারো না। তিনি তোমাদের ক্ষমা করেছেন। পরিবর্তে, তোমরা কুরআনের যতটুকু পার ততটুকু পাঠ কর। তিনি জানেন যে তোমাদের কেউ কেউ অসুস্থ থাকতে পার, অন্যরা হয়তো ঈশ্বরের জীবিকা লাভের চেষ্টায় ভ্রমন করতে পার, এবং অন্যান্যরা হয়তো ঈশ্বরের পথে সংগ্রাম করতে পারো। তোমরা এর থেকে যতটুকু পারো পাঠ করো, এবং সংযোগ প্রার্থনা (সালাত) পালন করো, বাধ্যতামূলক দান (যাকাত) দাও, এবং ঈশ্বরকে এক ন্যায়পরায়ণতার ঋণ দাও। তোমাদের আত্মার সমর্থনে যাকিছু ভালো তোমরা সামনে পাঠাবে, ঈশ্বরের কাছে তোমরা তা আরও উত্তমরুপে ও উদারভাবে পুরস্কৃত অবস্থায় পাবে। ঈশ্বরের কাছে ক্ষমার জন্য প্রার্থনা করো। ঈশ্বর ক্ষমাশীল, পরম দয়ালু।"],
  "74:1": ["O you who are enwrapped,", "হে লুকায়িত রহস্য।"],
  "74:2": ["Rise and warn.", "প্রকাশিত হও এবং সতর্ক করো।"],
  "74:3": ["And your Rabb, magnify.", "তোমার প্রভুর প্রশংসা করো।"],
  "74:4": ["And your garments, purify.", "তোমার পোশাক শুদ্ধ করো।"],
  "74:5": ["And the affliction, forsake.", "যা ভুল তা ত্যাগ করো।"],
  "74:6": ["And do not bestow a favor to gain more.", "তোমার ভাগ্য নিয়ে সন্তুষ্ট থাকো।"],
  "74:7": ["And for your Rabb, be of the sabirin.", "অবিচলভাবে তোমার প্রভুর স্মরণ করো।"],
  "74:8": ["Then when the blast is sounded in the Trumpet,", "অতঃপর, যখন শিংগায় ফুঁ দেয়া হয়।"],
  "74:9": ["That day is a day of hardship,", "এটা হবে এক কঠিন দিন।"],
  "74:10": ["Not at all easy upon the kafirin.", "অবিশ্বাসীদের জন্য, সহজ নয়।"],
  "74:11": ["Leave Me with the one whom I created alone,", "আমাকে সে ব্যক্তির বিষয়ে সিদ্ধান্ত নিতে দাও যাকে আমি একজন ব্যক্তি হিসাবে সৃষ্টি করেছিলাম।"],
  "74:12": ["And I made for him wealth spread wide,", "তাকে আমি দিয়েছিলাম- প্রচুর অর্থ।"],
  "74:13": ["And sons ever-present,", "এবং দেখার জন্য সন্তানদের।"],
  "74:14": ["And I smoothed for him a smooth path.", "আমি তার জন্য সবকিছু সহজ করে দিয়েছিলাম।"],
  "74:15": ["Yet he hopes that I should give yet more.", "এরপরও, সে আরো পাওয়ার জন্য লোভী।"],
  "74:16": ["No — he was set against Our signs.", "সে একগুঁয়েভাবে এই প্রমানাদি মানতে অস্বীকার করলো।"],
  "74:17": ["I will overwhelm him with a hard ascent.", "আমি তাকে ক্রমবর্ধমান শাস্তি দেব।"],
  "74:18": ["He reflected and calculated.", "কারণ, সে চিন্তাভাবনা করেছিল, এরপর সিদ্ধান্ত নিল।"],
  "74:19": ["Perdition — how he calculated!", "দু:খজনক তার সিদ্ধান্ত ।"],
  "74:20": ["Then again, perdition — how he calculated!", "নিশ্চয়, দু:খজনক তার সিদ্ধান্ত।"],
  "74:21": ["Then he looked,", "সে দেখলো।"],
  "74:22": ["Then he frowned and scowled,", "সে ভ্রূকুটি করলো আর ঘ্যানঘ্যান করলো।"],
  "74:23": ["Then he turned away and grew arrogant,", "এরপর, সে অহংকারে মুখ ফিরিয়ে নিল।"],
  "74:24": ["And said: \"This is nothing but magic handed down —", "সে বলল, “এ তো চতুর জাদু!"],
  "74:25": ["Nothing but the speech of a human.\"", "“এটি মানুষের তৈরি।”"],
  "74:26": ["I will thrust him into the Fire of Saqar.", "আমি তাকে শাস্তিতে প্রবেশ করাবো।"],
  "74:27": ["And what tells you what Saqar is?", "কি রকম শাস্তি!"],
  "74:28": ["It leaves nothing behind and spares nothing,", "সর্বোতভাবে সম্পূর্ণ এবং বোধগম্য।"],
  "74:29": ["A scorching against humankind.", "সব লোকের কাছে স্পষ্ট।"],
  "74:30": ["Over it are nineteen.", "এর উপর আছে উনিশ।"],
  "74:31": ["We made the keepers of the Fire nothing but malakat, and We made their number nothing but a trial for those who disbelieve — so that those given the Scripture may be certain, and those who believe may increase in faith, and so that those given the Scripture and the muminin may not doubt, and so that those in whose hearts is sickness and the kafirin may say: \"What did Allah intend by this as an example?\" Thus Allah leads astray whom Allah wills and guides whom Allah wills. None knows the hosts of your Rabb but Allah, and it is nothing but a reminder for humankind.", "আমরা নরকের তত্ত্বাবধায়ক হিসেবে ফেরেশতাদের নিযুক্ত করেছি, এবং আমরা তাদের সংখ্যা নির্ধারণ করেছি (১৯) (১) অবিশ্বাসীদের বিরক্ত করতে (২) খ্রিস্টান ও ইহুদীদের বুঝাতে (যে এটি একটি ঐশীগ্রন্থ) (৩) আস্থাবানদের আস্থা আরো শক্তিশালী করতে (৪) খ্রিস্টান, ইহুদী সেই সাথে বিশ্বাসীদের হৃদয় থেকে সন্দেহের সব ছিটেফোঁটা দূর করতে, এবং (৫) তাদেরকে প্রকাশ করার জন্য যারা হৃদয়ে সন্দেহ পোষণ করে , এবং অবিশ্বাসীদের; তারা বলবে, “ঈশ্বর এই রুপকের মাধ্যমে কি বুঝিয়েছেন?” ঈশ্বর এভাবে যাকে ইচ্ছা পথভ্রষ্ট করেন এবং যাকে ইচ্ছা পথ দেখান। তোমার প্রভুর সৈন্যদের বিষয়ে তিনি ব্যতিত কেউ জানে না। এটি লোকদের জন্য একটি সতর্কবার্তা।"],
  "74:32": ["No — by the moon,", "অবশ্যই, (আমি শপথ করি) চাঁদের।"],
  "74:33": ["And by the night when it retreats,", "এবং রাতের যখন তা অতিবাহিত হয়।"],
  "74:34": ["And by the morning when it shines,", "এবং প্রভাতের যখন তা আলো ছড়ায়।"],
  "74:35": ["Surely it is one of the greatest.", "এটি বড়ো অলৌকিকতাসমূহের একটি।"],
  "74:36": ["A warner to humankind,", "মানব জাতির প্রতি একটি সতর্কবার্তা।"],
  "74:37": ["For whoever of you wills to advance or to stay behind.", "তোমাদের মধ্যে যে এগিয়ে যেতে চায় অথবা পেছনে পড়ে থাকতে চায়, তার জন্য।"],
  "74:38": ["Every soul is a pledge for what it earned,", "প্রত্যেক আত্মা এর পাপের ফাঁদে আটকে যায়।"],
  "74:39": ["Except the companions of the Right.", "ডান পার্শ্বস্থরা ছাড়া।"],
  "74:40": ["In gardens they ask one another", "স্বর্গে, তারা জিজ্ঞেস করবে।"],
  "74:41": ["About the mujrimin:", "অপরাধীদের বিষয়ে।"],
  "74:42": ["\"What drove you down into Saqar?\"", "“কিসে তোমাদের এই শাস্তিতে নিয়ে এসেছে?”"],
  "74:43": ["They say: \"We were not of those who pray,", "তারা বলবে, “আমরা সংযোগ প্রার্থনা (সালাত) পালন করিনি।"],
  "74:44": ["And we did not feed the needy,", "“আমরা গরীবদের খেতে দিতাম না।"],
  "74:45": ["And we used to wade along with the waders,", "“আমরা ভ্রান্তদের সাথে ভুল পথে চলতাম।"],
  "74:46": ["And we used to deny the Day of Judgment,", "“আমরা বিচার দিনকে অবিশ্বাস করতাম।"],
  "74:47": ["Until certainty came to us.\"", "“এখন আমাদের কাছে নিশ্চয়তা আসা পর্যন্ত।”"],
  "74:48": ["So no intercession of intercessors avails them.", "সুপারিশকারীদের সুপারিশ কখনো তাদের সাহায্য করবে না।"],
  "74:49": ["So what is with them that they turn away from the reminder,", "তারা এই সতর্কবার্তার প্রতি এতো বিমুখ কেন?"],
  "74:50": ["As if they were startled donkeys", "জেব্রার মতো দৌড়ানো।"],
  "74:51": ["Fleeing from a hunting lion?", "যেগুলো সিংহ থেকে পালাচ্ছে।"],
  "74:52": ["No — every one of them wants to be given sheets spread out.", "তাদের প্রত্যেকে কি ব্যক্তিগতভাবে ঐশীগ্রন্থ পেতে চায়।"],
  "74:53": ["No — they do not fear the Hereafter.", "নিশ্চয়, তারা পরকালকে ভয় করে না।"],
  "74:54": ["No — it is a reminder,", "নিশ্চয়, এটি একটি স্মারক।"],
  "74:55": ["And whoever wills remembers it.", "তাদের জন্য যারা মনোযোগ দিতে চায়।"],
  "74:56": ["And none remember unless Allah wills. Allah alone is worthy of awe and worthy of forgiveness.", "তারা মনোযোগ দিতে পারে না ঈশ্বরের ইচ্ছার বিরুদ্ধে। তিনি সৎ-কর্মশীলতার উৎস; তিনি ক্ষমাশীলতার উৎস।"],
  "75:1": ["I swear by the Day of Resurrection.", "আমি পুনরুত্থান দিবসের শপথ করছি।"],
  "75:2": ["And I swear by the blaming self.", "এবং আমি দোষারোপকারী আত্মার শপথ করছি।"],
  "75:3": ["Does man think We shall not gather his bones?", "মানুষ কি মনে করে যে আমরা তার হাড়গুলো পুননির্মান করবো না?"],
  "75:4": ["Indeed, We are able to shape his fingertips.", "হ্যা নিশ্চয়; আমরা তার আঙুলের ডগা পুননির্মান করতে সক্ষম।"],
  "75:5": ["Rather, man wants to carry on in immorality ahead of him.", "কিন্তু মানুষ বিশ্বাসপ্রবন শুধু তাতে যা সে তার সামনে দেখে।"],
  "75:6": ["He asks, \"When is the Day of Resurrection?\"", "সে পুনরুত্থান দিবসে সন্দেহ করে।"],
  "75:7": ["So when the sight is dazzled with lightning,", "একবার যখন দৃষ্টি শানিত করা হয়।"],
  "75:8": ["and the moon sinks away,", "এবং চাঁদকে অন্ধকারাচ্ছন্ন করা হয় ।"],
  "75:9": ["and the sun and the moon are gathered together,", "এবং সূর্য ও চাঁদ একে অন্যের উপর আছড়ে পড়ে।"],
  "75:10": ["man says that day, \"Where is the escape?\"", "মানুষ ওই দিন বলবে, \"পলায়নের উপায় কোথায়?\""],
  "75:11": ["No! There is no helper.", "নি:সন্দেহে, পলায়নের কোন উপায় নেই।"],
  "75:12": ["To your Rabb that day is the settling.", "তোমাদের প্রভুর কাছে,ঐদিন, চূড়ান্ত নিয়তি।"],
  "75:13": ["Man is told that day what he sent ahead and left behind.", "মানুষকে জানানো হবে, ঐদিন, সবকিছু যা সে নিজেকে এগিয়ে নিতে করেছে, এবং সবকিছু যা সে নিজেকে পেছানোর জন্য করেছে।"],
  "75:14": ["Rather, man has clear insight into himself,", "মানুষ তার নিজের বিচারক হবে।"],
  "75:15": ["even if he casts his excuses.", "কোন অজুহাত গ্রহন করা হবে না।"],
  "75:16": ["Do not move your tongue with it to hurry it.", "এটি দ্রুত করতে তোমার জিহবা নাড়বে না।"],
  "75:17": ["Indeed, upon Us is its gathering and its recitation.", "আমরাই এটি কুরআন আকারে সংগ্রহ করবো।"],
  "75:18": ["So when We recite it, follow its recitation.", "একবার আমরা এটি আবৃতি করলে, তুমি  অনুসরণ করবে এমনি এক কুরআন।"],
  "75:19": ["Then upon Us is its clarification.", "তারপর আমরাই এটি ব্যাখ্যা করবো।"],
  "75:20": ["No! Rather, you love the immediate", "প্রকৃতপক্ষে, তোমরা এই ক্ষনস্থায়ী জীবনকে ভালবাসো।"],
  "75:21": ["and you leave behind the Hereafter.", "যখন পরকালকে অবহেলা করছো।"],
  "75:22": ["Faces that day are radiant,", "কিছু মুখ, ঐদিন, সুখী হবে।"],
  "75:23": ["gazing toward their Rabb.", "তাদের প্রভুর দিকে তাকিয়ে।"],
  "75:24": ["And faces that day are gloomy,", "অন্য মুখগুলো, ঐদিন, দুর্দশাগ্রস্থ হবে।"],
  "75:25": ["thinking a crushing blow will be dealt them.", "আশা করতে থাকবে সবচেয়ে নিকৃষ্ট কিছু।"],
  "75:26": ["No! When it reaches the throat,", "প্রকৃতপক্ষে, যখন (আত্মা) গলা পর্যন্ত পৌঁছায়।"],
  "75:27": ["and it is said, \"Who can cure?\"", "এবং একে আদেশ করা হয়: \"বেরিয়ে যাও!\""],
  "75:28": ["and he knows that it is the parting,", "সে জানে যে এটাই পরিসমাপ্তি।"],
  "75:29": ["and leg is wrapped around leg,", "এক পা অন্য পায়ের পাশে নিশ্চল পরে থাকবে।"],
  "75:30": ["to your Rabb that day is the driving.", "তোমার প্রভুর কাছে, ঐদিন, তলব করা হবে।"],
  "75:31": ["He neither believed nor prayed,", "কারণ সে না দান করতো, না সংযোগ প্রার্থনা (সালাত) পালন করতো।"],
  "75:32": ["but denied and turned away,", "কিন্তু সে অবিশ্বাস করেছিল এবং মুখ ফিরিয়ে নিয়েছিল।"],
  "75:33": ["then went off to his family, strutting.", "তার পরিবারের সাথে, সে ঔদ্ধত্যপনা দেখিয়েছে।"],
  "75:34": ["Woe to you — woe to you!", "তুমি এর উপযুক্ত হয়েছো।"],
  "75:35": ["Then woe to you — woe to you!", "নিশ্চয়ই, তুমি এর উপযুক্ত হয়েছো।"],
  "75:36": ["Does man think he will be left aimless?", "মানুষ কি মনে করে যে সে কিছুই থাকবে না?"],
  "75:37": ["Was he not a drop of emitted fluid?", "সে কি নির্গত এক ফোঁটা বীর্য ছিল না?"],
  "75:38": ["Then he was a clot, created and proportioned,", "এরপর তিনি এর থেকে একটি ভ্রুন সৃষ্টি করেছিলেন।"],
  "75:39": ["and made from him the two mates, the male and the female.", "তিনি এরপর একে পুরুষ অথবা নারী বানিয়েছিলেন।"],
  "75:40": ["Is not that One able to give life to the dead?", "তিনি কি এরপর মৃতকে পুনর্জীবিত করতে অক্ষম?"],
  "76:1": ["Has there come upon the human a span of time when he was nothing mentioned?", "এটা কি বাস্তব নয় যে একটা সময় ছিল যখন মানুষ বলে উল্লেখ করার মতো কিছু ছিল না?"],
  "76:2": ["We created the human from a mingled drop, to test him, and made him hearing and seeing.", "আমরা মানুষকে সৃষ্টি করেছিলাম একটি তরল মিশ্রণ থেকে, মাতাপিতা দু'জন থেকে, তাকে পরীক্ষা করার উদ্দেশ্যে। আর তাই, আমরা তাকে একজন শ্রোতা ও দ্রষ্টা করেছি।"],
  "76:3": ["We guided him the way, either thankful or thankless.", "আমরা তাকে দেখালাম দুটি পথ, তারপর, হয়তো সে কৃতজ্ঞ হয় নয়তো অকৃতজ্ঞ হয়।"],
  "76:4": ["We have prepared for the thankless chains and fetters and a blaze.", "আমরা অবিশ্বাসীদের জন্য প্রস্তুত করলাম শিকল, বেড়ি, এবং এক জ্বলন্ত নরক।"],
  "76:5": ["The good ones drink from a cup whose mixture is Kafoor,", "আর পূণ্যবানদের ক্ষেত্রে, তারা সুস্বাদু পানীয়ের কাপ থেকে পান করবে।"],
  "76:6": ["a spring Allah's servants drink from, bursting it forth in full flow.", "একটি ঝর্ণা- যা সংরক্ষিত আল্লাহর প্রতি নিবেদিতদের জন্য; এটি বের হয়ে আসবে প্রবল বেগে যেমন তারা চায়।"],
  "76:7": ["They fulfill the vows and fear a day whose evil was spreading far and wide.", "তারা তাদের প্রতিশ্রুতি পূর্ণ করে এবং এমন এক দিনকে সমীহ করে যা অত্যন্ত কঠিন।"],
  "76:8": ["And they feed the food, though they love it, to a needy one, an orphan, and a captive,", "তারা তাদের প্রিয় খাবার দান করে দরিদ্র, এতিম এবং বন্দীদের।"],
  "76:9": ["saying: We feed you only for the face of Allah; we want from you no recompense and no thanks.", "\"আমরা তোমাদের খাওয়াই আল্লাহর উদ্দেশ্যে; না আমরা তোমাদের কাছ থেকে আশা করি পুরস্কার, না ধন্যবাদ।"],
  "76:10": ["Indeed, we fear from our Rabb a day frowning and pitch dark.", "\"আমরা আমাদের প্রভুকে ভয় করি সে দিনের ব্যাপারে যা দূর্দশা এবং যন্ত্রণায় পূর্ণ।\""],
  "76:11": ["So Allah shielded them from the evil of that day, and gave them radiance and joy,", "পরিনামে, ঈশ্বর তাদের রক্ষা করেন সে দিনের অমঙ্গল থেকে, এবং তাদেরকে পুরস্কৃত করেন আনন্দ ও পরিতৃপ্তি দিয়ে।"],
  "76:12": ["and recompensed them for what they endured: a garden and silk.", "তাদের অবিচলতার জন্য তিনি তাদের পুরস্কৃত করেন স্বর্গ, এবং রেশম দিয়ে।"],
  "76:13": ["Reclining in it upon couches, they see in it neither sun nor bitter cold;", "তারা সেখানে বিলাসবহুল আসবাবের উপর আরাম করে। না তারা ভোগ করে সূর্যের তাপ, না কোন শীতলতা।"],
  "76:14": ["close over them its shade, and its fruit clusters are subdued, easy to reach.", "ছায়া সেখানে তাদের আবৃত করে, এবং ফলফলাদি নাগালের মধ্যে আনা হয়।"],
  "76:15": ["And they are moved among with vessels of silver and cups of crystal,", "তাদেরকে পানীয় পরিবেশন করা হয় রুপার পাত্র ও কাপে যা আলোকপ্রবাহী।"],
  "76:16": ["crystal of silver, measured to the full measure.", "আলোকপ্রবাহী কাপ, যদিও রুপার তৈরী; এই সবকিছুর যথার্থ যোগ্যই তারা ছিল।"],
  "76:17": ["and they are given to drink in it a cup whose mixture is Zanjabeel,", "তারা উপভোগ করে সুস্বাদু পানীয়।"],
  "76:18": ["a spring in it called Salsabeel.", "সেখানকার একটি ঝরনা থেকে যা ‘সালসাবিল’ নামে পরিচিত।"],
  "76:19": ["And youths, everlasting, move among them; when you see them you would count them scattered pearls,", "তাদের সেবায় থাকবে চিরজীবী সেবকরা। তুমি যখন তাদের দেখবে, তাদেরকে বিক্ষিপ্ত মুক্তার মত দেখাবে।"],
  "76:20": ["and when you look, then you look upon bliss and a great dominion.", "তুমি যেখানেই তাকাও, তুমি দেখবে সুখ ও এক চমৎকার রাজত্ব।"],
  "76:21": ["Upon them garments of green Sundus and Istabraq, adorned with bracelets of silver; and their Rabb gave them to drink a beverage that purifies.", "তাদের উপর থাকবে সবুজ মখমল, সাটিন বস্ত্র ও রূপার অলঙ্কার। তাদের প্রভু তাদের  সরবরাহ করবেন বিশুদ্ধ পানীয়।"],
  "76:22": ["This was for you a recompense, and your striving was thanked.", "এটা সে পুরস্কার যা তোমাদের জন্য অপেক্ষা করে, কেননা তোমাদের প্রচেষ্টার মূল্যায়ন হয়েছে।"],
  "76:23": ["We, We brought down upon you the Quran, a bringing down.", "আমরা তোমাদের নিকট এই কুরআন প্রকাশ করেছি; যা আমাদের পক্ষ থেকে একটি বিশেষ প্রকাশ।"],
  "76:24": ["So endure for the command of your Rabb, and obey not among them a sinner or a thankless one,", "তোমরা অবিচলতার সাথে তোমাদের প্রভুর প্রত্যাদেশ পালন করবে, আর তাদের মধ্যকার কোন পাপী অবিশ্বাসীকে মান্য করবে না।"],
  "76:25": ["and remember the name of your Rabb morning and evening,", "আর তোমাদের প্রভুর নাম স্মরণ করো দিনে ও রাতে।"],
  "76:26": ["and in the night bow down to Allah and glorify Allah the night long.", "রাতের বেলায়, তাঁর সামনে সেজদায় পড়ো, এবং বহু দীর্ঘ-রাতজুড়ে তাঁর মহিমা ঘোষণা করো।"],
  "76:27": ["These love the swift and leave behind them a heavy day.", "এইসব লোকেরা এই ক্ষনস্থায়ী জীবন নিয়ে আচ্ছন্ন, যখন উপেক্ষা করছে- তাদের ঠিক সামনের- এক ভারী দিনকে।"],
  "76:28": ["We created them and strengthened their sinews; and when We will, We substitute their likes, a substitution.", "আমরা তাদের সৃষ্টি করলাম, এবং তাদের প্রতিষ্ঠিত করলাম, আর, যখনই আমরা চাই, আমরা তাদের জায়গায় অন্যদের প্রতিস্থাপন করতে পারি।"],
  "76:29": ["Indeed, this is a reminder; so whoever wills, let him take a way to his Rabb.", "এটি একটি স্মারক: যেকেউ চায় তার প্রভুর পথ বেছে নিবে।"],
  "76:30": ["You will not except that Allah wills; Allah is ever knowing, wise.", "যা কিছু তোমরা ইচ্ছা করো, তা ঈশ্বরের ইচ্ছানুযায়ী হয়। ঈশ্বর সর্বজ্ঞ, জ্ঞানী।"],
  "76:31": ["Allah admits whom Allah wills into Allah's mercy; and for the wrongdoers is prepared a painful punishment.", "তিনি যাকে ইচ্ছা তাঁর দয়ায় প্রবেশ করান। আর সীমালঙ্ঘনকারীদের ক্ষেত্রে , তিনি তাদের জন্য একটি যন্ত্রণাদায়ক শাস্তি প্রস্তুত করেছেন।"],
  "77:1": ["By those sent forth one after another,", "(স্বর্গদূত) পর্যায়ক্রমে প্রেরিত।"],
  "77:2": ["then the storm-winds that storm,", "বাতাস চালনা করতে।"],
  "77:3": ["and the spreaders that spread,", "মেঘমালা সঞ্চালিত করতে।"],
  "77:4": ["then the separators that separate,", "খাদ্যদ্রব্য সরবরাহ করতে।"],
  "77:5": ["then the casters casting down a reminder,", "সংবাদ বিলি করতে।"],
  "77:6": ["an excuse or a warning —", "শুভ সংবাদ, একই সাথে সতর্কবার্তা।"],
  "77:7": ["indeed, what you are promised is bound to befall.", "যার প্রতিশ্রুতি দেয়া হয়, তা আসবে।"],
  "77:8": ["So when the stars are blotted out,", "সুতরাং, যখন তারাগুলোকে নিভিয়ে দেয়া হয়।"],
  "77:9": ["and when the sky is opened,", "আকাশ উন্মুক্ত করা হয়।"],
  "77:10": ["and when the mountains are leveled and scattered,", "পর্বতমালা ধ্বংস করা হয়।"],
  "77:11": ["and when the Rasuls are given their appointed time —", "বার্তাবাহকদের তলব করা হয়।"],
  "77:12": ["for which day were they put off?", "এটা সেই নির্ধারিত দিন।"],
  "77:13": ["For the Day of Decision.", "সিদ্ধান্তের দিন।"],
  "77:14": ["And what tells you what the Day of Decision is?", "কী এক সিদ্ধান্তের দিন!"],
  "77:15": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:16": ["Did We not destroy the earlier ones?", "আমরা কি পূর্বের প্রজন্মদের ধ্বংস করিনি?"],
  "77:17": ["Then We made the later ones follow them.", "তারপর, আমরা তাদের পর অন্যদের আসতে দেইনি?"],
  "77:18": ["Thus we do with the mujrimin.", "অপরাধীদের সাথে আমরা এমনই করি।"],
  "77:19": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:20": ["Did we not create you from a lowly fluid?", "আমরা কি তোমাদের নিম্নমানের তরল থেকে সৃষ্টি করিনি?"],
  "77:21": ["And we placed it in a firm settling-place,", "এরপর, আমরা তা রেখেছি সুরক্ষিত আধারে।"],
  "77:22": ["for a known measure.", "একটি নির্দিষ্ট সময়ের জন্য।"],
  "77:23": ["So we measured, and excellent are the measurers.", "আমরা তা পরিমাপ করেছিলাম যথাযথভাবে। আমরা সর্বোত্তম নকশাকারী।"],
  "77:24": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:25": ["Did we not make the earth a gathering-place", "আমরা কি পৃথিবীকে একটি আবাস বানাইনি?"],
  "77:26": ["for the living and the dead?", "জীবিত এবং মৃতদের জন্য?"],
  "77:27": ["And we set therein towering anchors, and gave you to drink sweet water.", "আমরা এতে স্থাপন করেছি উচুঁ পর্বতমালা, এবং তোমাদের পান করার জন্য প্রদান করেছি বিশুদ্ধ পানি।"],
  "77:28": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:29": ["Set out to that which you used to deny!", "সেখানে যাও, যেখানে যাবার বিষয়ে অবিশ্বাস পোষনে তোমরা অভ্যস্ত ছিলে।"],
  "77:30": ["Set out to a shade with three branches,", "যাও, তিনটি ভিন্ন ঘনত্বের ছায়ায়।"],
  "77:31": ["neither giving shade nor availing against the flame.", "অথচ, এটি না সরবরাহ করে শীতলতা, না রক্ষা করে তাপ থেকে।"],
  "77:32": ["It is hurled with evil like palaces,", "এটি অট্টালিকাসমূহের মতো বড় স্ফুলিঙ্গ নিক্ষেপ করে।"],
  "77:33": ["as if they were beautiful yellow ones.", "উটের বর্ণের মতো হলুদ।"],
  "77:34": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:35": ["This is the day they shall not speak,", "এটা সেই দিন, যখন তারা কথা বলে না।"],
  "77:36": ["nor be permitted to offer excuses.", "না তাদের ক্ষমা চাওয়ার অনুমতি দেয়া হবে।"],
  "77:37": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:38": ["This is the Day of Decision: we have gathered you and the earlier ones.", "এটি সিদ্ধান্তের দিন। আমরা তোমাদের এবং পূর্ববর্তী প্রজন্মদের তলব করেছি।"],
  "77:39": ["So if you have a scheme, then scheme against us!", "যদি তোমাদের কোন ষড়যন্ত্র থাকে, তবে এগিয়ে যাও এবং ষড়যন্ত্র করো।"],
  "77:40": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:41": ["Indeed the mindful shall be amid shade and springs,", "সৎকর্মশীলরা ছায়া এবং ঝর্ণা উপভোগ করবে।"],
  "77:42": ["and fruits of what they desire.", "এবং ফল যা তারা আকাঙ্খা করে।"],
  "77:43": ["Eat and drink pleasantly for what you used to do.", "তোমাদের কাজের বিনিময়ে আনন্দের সাথে খাও এবং পান করো।"],
  "77:44": ["Indeed, thus we repay the doers of good.", "আমরা এভাবে পুরষ্কৃত করি পুণ্যকারীদের।"],
  "77:45": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:46": ["Eat and enjoy a little — you are mujrimin.", "খাও এবং উপভোগ কর সাময়িকভাবে; তোমরা অপরাধী।"],
  "77:47": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:48": ["And when they are told, Bow, they do not bow.", "যখন তাদের বলা হয়, \"নত হও, \" তারা নত হয় না।"],
  "77:49": ["Woe, that day, to the mukazzibin!", "দিনটি হবে প্রত্যাখ্যানকারীদের জন্য দুঃখের।"],
  "77:50": ["So in what account, after it, will they believe?", "এটি ছাড়া, কোন হাদিসে, তারা সমর্থন করে?"],
  "78:1": ["About what do they question one another?", "তারা কি নিয়ে প্রশ্ন করছে?"],
  "78:2": ["Concerning the great tiding,", "সে মহা ঘটনা।"],
  "78:3": ["the one about which they are at variance.", "তারা যাতে বিবাদ করে।"],
  "78:4": ["Nay, they shall soon know.", "নিশ্চয়, তারা দেখতে পাবে।"],
  "78:5": ["Then nay, they shall soon know.", "নিঃসন্দেহে, তারা দেখতে পাবে।"],
  "78:6": ["Did We not make the earth a bed,", "আমরা কি পৃথিবীকে বাসযোগ্য করিনি?"],
  "78:7": ["and the rocky landforms as stakes?", "এবং পর্বতমালাকে ভারসাম্য রক্ষাকারী?"],
  "78:8": ["We created you in pairs,", "আমরা তোমাদের সৃষ্টি করেছিলাম (একে অপরের) সাথী হিসেবে ।"],
  "78:9": ["and made your sleep a rest,", "আমরা সৃষ্টি করেছি ঘুম, যাতে তোমরা বিশ্রাম করতে পারো।"],
  "78:10": ["and made the night a garment,", "আমরা রাতকে একটি আবরণ হিসেবে বানালাম।"],
  "78:11": ["and made the day a living.", "এবং জীবিকা খোঁজার জন্য দিন।"],
  "78:12": ["We built above you seven sturdy layers", "আমরা তোমাদের উপর সাত মহাবিশ্ব সৃষ্টি করেছি।"],
  "78:13": ["and made a blazing lamp.", "আমরা সৃষ্টি করেছি এক উজ্জ্বল বাতি।"],
  "78:14": ["We sent down from the press water pouring,", "মেঘ থেকে আমরা অবতীর্ন করি অবিরাম প্রবাহিত পানি।"],
  "78:15": ["to bring forth with it grain and growing things,", "এর দ্বারা খাদ্যশস্য এবং উদ্ভিদ উৎপন্ন করতে।"],
  "78:16": ["and gardens close-entwined.", "এবং নানারকম ফলের বাগান।"],
  "78:17": ["Indeed the day of division is an appointed time,", "সিদ্ধান্তের দিনটি নির্ধারিত।"],
  "78:18": ["the day the blast is blown, and you come in hosts.", "দিনটিতে শিঙ্গায় ফুঁ দেয়া হয়, আর তোমরা দলেবলে আসো।"],
  "78:19": ["The sky is opened wide and becomes as doors,", "দরজার মত খোলা হবে স্বর্গ।"],
  "78:20": ["and the rocky landforms are set moving, levelled and scattered.", "পর্বতমালা সরিয়ে ফেলা হবে, যেন এরা ছিল একটি মরীচিকা।"],
  "78:21": ["Indeed Jahannam is a watch-post in wait,", "জাহান্নাম অনিবার্য।"],
  "78:22": ["a place of return for the transgressors,", "সীমালঙ্ঘনকারীদের জন্য, এটি হবে তাদের আবাস।"],
  "78:23": ["tarrying therein through ages upon ages.", "তারা তাতে অবস্থান করে দীর্ঘকাল।"],
  "78:24": ["They taste therein neither coolness nor drink,", "তারা এর মাঝে না কখনো স্বাদ পায় শীতলতার, না কোন পানীয়ের।"],
  "78:25": ["but only scalding and dregs,", "শুধু একটি অগ্নিকুন্ডলী, এবং তিক্ত খাদ্য।"],
  "78:26": ["a fitting requital.", "একটি ন্যায্য প্রতিফল।"],
  "78:27": ["Indeed they never hoped for a reckoning,", "তারা কখনো আশা করেনি যে হিসাব দিতে হবে।"],
  "78:28": ["and they denied Our signs with a great denial.", "এবং আমাদের নিদর্শনগুলো সম্পূর্ণরূপে প্রত্যাখ্যান করেছিল।"],
  "78:29": ["Everything We have counted in a book.", "আমরা সবকিছুর হিসাব রাখলাম একটি নথিতে।"],
  "78:30": ["So taste! We shall increase you in nothing but punishment.", "ভোগ করো পরিনতিসমূহ; আমরা শুধু তোমাদের শাস্তি বাড়িয়ে দিবো।"],
  "78:31": ["Indeed the ilah-fearing shall have a triumph:", "সৎকর্মশীলরা অর্জন করেছে এক পুরস্কারের।"],
  "78:32": ["gardens and grapes,", "ফলের বাগান এবং আঙ্গুর।"],
  "78:33": ["and buxom maidens of matching age,", "চমকপ্রদ স্বামী-স্ত্রী"],
  "78:34": ["and cups brimming over.", "সুস্বাদু পানীয়।"],
  "78:35": ["They hear therein no idle talk nor lying,", "এর মাঝে তারা কখনো কোন অর্থহীন বা মিথ্যা কিছু শুনবে না।"],
  "78:36": ["a reward from your Rabb, a gift beyond reckoning,", "তোমাদের প্রভুর পক্ষ থেকে একটি পুরস্কার; এক উদার প্রতিদান।"],
  "78:37": ["Rabb of the heavens and the earth and what is between them, the the Raheem — none has leave to address Allah.", "আকাশমন্ডলী ও পৃথিবী, এবং এদের মধ্যকার সবকিছুর প্রভু। সবচেয়ে করুনাময়। কেউ তার সিদ্ধান্ত বাতিল করতে পারে না।"],
  "78:38": ["The day the Spirit and the malakat stand in ranks; they speak only one whom the the Raheem permits, speaking what is right.", "সেদিন আসবে যখন সে আত্মা এবং স্বর্গদূতেরা এক সারিতে দাঁড়াবে। যারা সবচেয়ে করুনাময়ের দ্বারা অনুমোদিত তারা ব্যতীত আর কেউ কথা বলবে না এবং তারা শুধু বলবে, যা সত্য।"],
  "78:39": ["That is the true Day; whoever wills may take a way back to his Rabb.", "এমনই হলো সে অনিবার্য দিন। যেকেউ চায় তাকে তার প্রভুর কাছে আশ্রয় নিতে দাও।"],
  "78:40": ["We have warned you of a punishment near at hand, the day a person sees what his hands have put forth; and the kafir says: \"If only I had been dust!\"", "একটি আসন্ন শাস্তি সম্পর্কে আমরা তোমাদের যথেষ্ট সতর্ক করেছি। এটা সেই দিন যখন প্রত্যেকে পরীক্ষা করবে যা তার হাত সামনে পাঠিয়েছে এবং অবিশ্বাসী বলবে, \"হায়, আমি যদি ধুলা হতাম।\""],
  "79:1": ["By those who wrench out with a drowning wrench,", "বলপূর্বক (অবিশ্বাসীদের আত্না) ছিনিয়ে নেয়া (ফেরেশতারা)।"],
  "79:2": ["and those who rush, rushing,", "আর আনন্দ সহকারে যারা আলতোভাবে (বিশ্বাসীদের আত্মা) নেয় তারা।"],
  "79:3": ["and those who glide, gliding,", "আর যারা ভেসে বেড়ায় সব জায়গায়।"],
  "79:4": ["and those who race ahead, racing,", "আগ্রহভরে একে অন্যের সাথে পাল্লা দিয়ে-"],
  "79:5": ["and those who steer the affair.", "বিভিন্ন আদেশ সম্পন্ন করতে।"],
  "79:6": ["the day the tremor quakes,", "সে দিন যখন কম্পন নাড়া দেয়।"],
  "79:7": ["and the follower follows it,", "দ্বিতীয় বিকট শব্দের পর।"],
  "79:8": ["hearts, that day, are trembling,", "নির্দিষ্ট কিছু মন আতংকিত হবে।"],
  "79:9": ["their eyes are humbled.", "তাদের চোখগুলো বশীভূত হবে।"],
  "79:10": ["They say: \"Are we to be returned to the pit?\"", "তারা বলবে, \"আমরা কবর থেকে পুনরায় সৃষ্টি হয়েছি।\""],
  "79:11": ["\"When we are crumbling bones?\"", "\"আমরা পঁচা হাড়ে পরিণত হবার পর কিভাবে এটা ঘটলো?\""],
  "79:12": ["They say: \"Then that is a losing return.\"", "তারা বলেছিল, \"এটা এক অসম্ভব পুনরাবৃত্তি।\""],
  "79:13": ["But it is only one driving blast,", "কেবল একটি ডাকই যথেষ্ট।"],
  "79:14": ["then suddenly they are upon the surface.", "যার ফলে তারা জেগে উঠে।"],
  "79:15": ["Has the account of Musa come to you?", "তুমি কি মুসার কাহিনী জেনেছো?"],
  "79:16": ["when his Rabb called him at the holy valley of Tuwa —", "তার প্রভু তাকে তুয়ার পবিত্র উপত্যকায় ডেকেছিলেন।"],
  "79:17": ["\"Go to Fir'awn; he has transgressed,", "“ফেরাউনের কাছে যাও; সে সীমালঙ্ঘন করেছে।\""],
  "79:18": ["and say: 'Would you be willing to purify yourself,", "তাকে বল, \"তুমি কি সংশোধিত হবে না? \""],
  "79:19": ["and I guide you to your Rabb, so that you may fear?'\"", "“চল আমি তোমাকে তোমার প্রভুর পথ দেখাই, যাতে তুমি ভক্তিপূর্ন হতে পারো।"],
  "79:20": ["and showed him the greatest sign.", "তারপর সে তাকে মহা অলৌকিকতাটি দেখালো।"],
  "79:21": ["But he denied and disobeyed,", "কিন্তু সে অবিশ্বাস করলো এবং বিদ্রোহ করলো।"],
  "79:22": ["then he turned away, striving,", "তারপর সে দ্রুত মুখ ফিরিয়ে নিল।"],
  "79:23": ["and assembled and proclaimed,", "সে তলব করলো এবং ঘোষণা করলো।"],
  "79:24": ["and said: \"I am your Rabb, the most high!\"", "সে বলল, \"আমি তোমাদের প্রভু; সবচেয়ে উর্ধ্বে।\""],
  "79:25": ["So Allah seized him as a warning, for the end and for the beginning.", "পরিনামে,আল্লাহ তাকে শাস্তি দিলেন পরকালে, সেই সাথে প্রথম জীবনেও।"],
  "79:26": ["Indeed, in that is a lesson for whoever fears.", "এটি ভক্তদের জন্য একটি শিক্ষা।"],
  "79:27": ["Are you harder in creation than the sky? Allah built it,", "আকাশমন্ডলীর চেয়ে তোমাদের সৃষ্টি কি বেশি কঠিন? তিনি এটি নির্মাণ করেছেন।"],
  "79:28": ["raised its height and made it even,", "তিনি এর বস্তুগুলো উঠালেন এবং একে নিঁখুত করলেন।"],
  "79:29": ["and darkened its night and brought out its forenoon,", "তিনি এর রাতকে বানালেন অন্ধকার এবং এর সকালকে করেছেন আলোকিত।"],
  "79:30": ["and the earth, after that, was spread out,", "তিনি পৃথিবীকে বানিয়েছে ডিম্বাকৃতির।"],
  "79:31": ["and its water and its pasture were drawn out from it,", "এর থেকে, তিনি উৎপন্ন করলেন এর নিজস্ব পানি এবং চারনভূমি।"],
  "79:32": ["and the mountains were anchored,", "তিনি পর্বতসমূহ প্রতিষ্ঠিত করলেন।"],
  "79:33": ["as a provision for you and for your cattle.", "এই সবকিছু তোমাদের এবং তোমাদের প্রাণীগুলোকে জীবনোপকরন প্রদান করতে।"],
  "79:34": ["Then, when the greatest overwhelming comes,", "তারপর, যখন বিকট শব্দ আসে।"],
  "79:35": ["the day the human remembers what he strove,", "এটি সেই দিন যখন মানুষের মনে পড়বে সবকিছু যা সে করেছিল।"],
  "79:36": ["and the blaze comes forth for whoever sees —", "অস্তিত্বে আনা হবে স্বর্গ ।"],
  "79:37": ["so as for whoever transgressed", "আর তার ক্ষেত্রে যে সীমালঙ্ঘন করেছিল।"],
  "79:38": ["and preferred the nearer life,", "যে আচ্ছন্ন ছিল এই জীবনে নিয়ে।"],
  "79:39": ["then the blaze is the destination.", "নরকই হবে আবাস।"],
  "79:40": ["And as for whoever feared the standing of the Rabb and restrained the soul from desire,", "আর তার ক্ষেত্রে  যে তার প্রভুর মহিমাকে ভক্তি করেছিল, এবং পাপপূর্ণ লালসা থেকে নিজেকে বিরত রেখেছিল।"],
  "79:41": ["then the Garden is the destination.", "স্বর্গই হবে আবাস।"],
  "79:42": ["They ask you about the Hour: when is its anchoring?", "তারা তোমাকে জিজ্ঞেস করে সে ঘন্টা  সম্পর্কে, আর কখন তা সংঘটিত হবে!"],
  "79:43": ["You have no part in its remembrance.", "এর সময় ঘোষণা করার জন্য পূর্বনির্ধারিত ব্যক্তি তুমি নও (মুহাম্মাদ)।"],
  "79:44": ["To your Rabb is its end.", "এর নিয়তি ঠিক করেন তোমার প্রভু। যাও এর প্রত্যাশা করো।"],
  "79:45": ["You are only a warner to whoever fears it.", "তোমার দায়িত্ব তাদেরকে সতর্ক করা যারা এর আশা করে।"],
  "79:46": ["As if they, on the day they see it, had tarried only an evening or its forenoon.", "যেদিন তারা তা দেখবে, তারা অনুভব করবে যেন তারা টিকে ছিল এক সন্ধ্যা বা অর্ধেক দিন।"],
  "80:1": ["He frowned and turned away", "সে (মুহাম্মদ) ভ্রু কুঁচকে মুখ ফিরিয়ে নিয়েছিল।"],
  "80:2": ["when the blind man came to him.", "যখন অন্ধ লোকটি তার কাছে এসেছিল।"],
  "80:3": ["And what tells you — perhaps he would become pure,", "কেমন করে তুমি জানো? হয়তো সে নিজেকে পরিশুদ্ধ করবে।"],
  "80:4": ["or he would remember, and the reminder would benefit him.", "অথবা হয়তো সে সতর্ক হবে, আর বার্তাটি থেকে উপকৃত হবে।"],
  "80:5": ["But as for the one who is self-sufficient,", "এবং ধনী লোকটির ক্ষেত্রে ।"],
  "80:6": ["you give your attention to him,", "তুমি তোমার মনোযোগ তার প্রতি দিয়েছিলে।"],
  "80:7": ["and it is not upon you that he does not become pure.", "যদিও তুমি তার মুক্তির নিশ্চয়তা দিতে পারতে না।"],
  "80:8": ["And as for the one who comes to you striving", "সে ব্যক্তি যে তোমার কাছে এসেছিল আগ্রহ নিয়ে।"],
  "80:9": ["while he is in reverent awe,", "এবং আসলেই ভক্তিপূর্ণ।"],
  "80:10": ["you are diverted from him.", "তুমি তাকে উপেক্ষা করেছিলে।"],
  "80:11": ["No indeed — it is a reminder;", "নিশ্চয়, এটি একটি স্মারক।"],
  "80:12": ["so whoever wills remembers it.", "যেকেউ চায় মনোযোগ দিবে।"],
  "80:13": ["It is in honored written sheets,", "সম্মানিত ঐশীগ্রন্থগুলোতে৷"],
  "80:14": ["raised high, purified,", "প্রশংসিত এবং নিখাদ৷"],
  "80:15": ["in the hands of scribes", "বার্তাবাহকদের হাতে (লিখিত)।"],
  "80:16": ["noble and good.", "যারা সম্মানিত এবং সৎকর্মশীল।"],
  "80:17": ["Perish the human — how committing kufr he is!", "দুর্ভোগ মানুষ জাতির প্রতি ; সে খুব অকৃতজ্ঞ৷"],
  "80:18": ["From what thing was he created?", "কি থেকে তাকে তিনি সৃষ্টি করেছিলেন ?"],
  "80:19": ["From a drop he was created, then proportioned;", "অতিক্ষুদ্র ফোঁটা থেকে, তিনি তাকে সৃষ্টি করেন আর তার নকশা করেন।"],
  "80:20": ["then the way was made easy for him;", "এরপর তিনি তার জন্য সে পথটির দিকে অঙ্গুলিনির্দেশ করেন।"],
  "80:21": ["then he was made to die, and was buried;", "এরপর তিনি তাকে দেন মৃত্যু, এবং রাখেন কবরে।"],
  "80:22": ["then, when Allah wills, Allah raises him up.", "যখন তিনি চান, তিনি তাকে পুনরুজ্জীবিত করেন।"],
  "80:23": ["No indeed — he has not yet accomplished what he was commanded.", "সে তাঁর প্রত্যাদেশাবলি বহাল রাখবে।"],
  "80:24": ["So let the human look at his food:", "মানুষ তার খাদ্য নিয়ে ভেবে দেখুক।"],
  "80:25": ["We poured the water down in torrents,", "আমরা পানি বর্ষণ করি উদারভাবে।"],
  "80:26": ["then We split the earth wide open,", "এরপর আমরা মাটি চিরে পথ করে দেই।"],
  "80:27": ["then We grew grain in it,", "তাতে আমরা উৎপন্ন করি খাদ্যশস্য।"],
  "80:28": ["and grapes and green fodder,", "আঙ্গুর এবং চারণভূমি।"],
  "80:29": ["and olives and palm-trees,", "জলপাই এবং তাল।"],
  "80:30": ["and gardens overgrown,", "নানারকম ফলের বাগান।"],
  "80:31": ["and fruit and fodder,", "ফল-ফলাদি এবং শাকসবজি।"],
  "80:32": ["as a delight for you and for your livestock.", "তোমাদের আর তোমাদের প্রাণীদের জন্য জীবনোপকরণ প্রদান করতে।"],
  "80:33": ["Then, when the deafening blast comes,", "তারপর, যখন আঘাতটি আসবে।"],
  "80:34": ["the day a person flees from his brother,", "এটাই সে দিন যখন কোন ব্যক্তি পালিয়ে যায় তার ভাইকে ছেড়ে।"],
  "80:35": ["and his mother and his father,", "তার মা ও বাবাকে ছেড়ে।"],
  "80:36": ["and his companion and his children,", "তার সহধর্মী-সহর্মিনী ও সন্তানাদিকে ছেড়ে।"],
  "80:37": ["each person among them that day has an affair that occupies him.", "তাদের প্রত্যেকে, ঐদিন, তার নিজের নিয়তি নিয়ে দুশ্চিন্তা করবে।"],
  "80:38": ["Faces that day are beaming,", "ঐদিন কিছু চেহারা হবে সুখী।"],
  "80:39": ["laughing, rejoicing,", "হাস্যজ্জল এবং আনন্দিত।"],
  "80:40": ["and faces that day will have dust upon them,", "অন্য চেহারাগুলো, ঐদিন, দু:খে ছেয়ে যাবে।"],
  "80:41": ["overwhelmed by darkness.", "অনুশোচনায় কাতর।"],
  "80:42": ["Those are the kafirin, the immoral.", "এরাই অন্যায়কারী অবিশ্বাসী।"],
  "81:1": ["When the sun is folded up,", "যখন সূর্যকে আবর্তন করা হয়।"],
  "81:2": ["and when the stars fall scattering,", "তারাগুলো একে অন্যের উপর আছড়ে পড়ে।"],
  "81:3": ["and when the rocky landforms are set in motion,", "পর্বতসমূহ নিশ্চিহ্ন হয়।"],
  "81:4": ["and when the ten-month naqahs are left untended,", "প্রজনন বন্ধ করা হয়।"],
  "81:5": ["and when the wild creatures are herded together,", "জানোয়ারদের তলব করা হয়।"],
  "81:6": ["and when the seas are set ablaze,", "মহাসমুদ্রগুলোতে প্রজ্বলিত হয়।"],
  "81:7": ["and when souls are paired, each with its match,", "আত্মাগুলোকে তাদের দেহে ফিরিয়ে আনা হয়।"],
  "81:8": ["and when the one buried alive is asked", "যে মেয়েটিকে জীবন্ত কবর দেয়া হয়েছিল তাকে জিজ্ঞেস করা হয়:"],
  "81:9": ["for what offense she was killed,", "কোন অপরাধের জন্য তাকে হত্যা করা হয়েছিল?"],
  "81:10": ["and when the written sheets are unfolded,", "নথিগুলো জানিয়ে দেয়া হবে।"],
  "81:11": ["and when the sky is stripped away,", "আকাশমন্ডলী সরিয়ে ফেলা হবে।"],
  "81:12": ["and when the Blaze is made to blaze,", "নরক প্রজ্বলিত হবে।"],
  "81:13": ["and when the Garden is brought near,", "স্বর্গ উপস্থাপিত হবে।"],
  "81:14": ["every soul shall know what it has brought before.", "প্রত্যেক আত্মা সবকিছু জানবে যা এটি নিয়ে এসেছে।"],
  "81:15": ["Nay, I swear by those that slip away,", "আমি দৃঢ় শপথ করি ছায়াপথগুলোর নামে।"],
  "81:16": ["the swift runners that hide away,", "তাদের কক্ষপথে চলছে নির্ভুলভাবে।"],
  "81:17": ["and the night when it spreads its darkness,", "রাতের নামে যখন তা ঘনিয়ে আসে।"],
  "81:18": ["and the morning when it breathes,", "আর সকাল যখন তা দম নেয়।"],
  "81:19": ["It is indeed the word of a Rasul, noble,", "এটি একজন সম্মানিত বার্তাবাহকের উক্তি।"],
  "81:20": ["possessed of strength, firmly established with the Rabb of the high seat,", "সিংহাসনের অধিকারী  দ্বারা অনুমোদিত, পূর্ণ সমর্থিত।"],
  "81:21": ["obeyed there, and one to be trusted.", "তাকে মান্য করতে হবে এবং আস্থা রাখতে হবে।"],
  "81:22": ["Your companion is not mad;", "তোমাদের বন্ধু (রাশাদ) পাগল নয়।"],
  "81:23": ["he indeed saw it at the clear horizon.", "তিনি তাকে উঁচু দিগন্তে দেখেছিলেন।"],
  "81:24": ["It is not one to withhold the unseen,", "সে কোন খবর গোপন রাখছে না ।"],
  "81:25": ["and it is not the word of a stoned devil.", "এটি কোন বিতাড়িত শয়তানের কথা নয়।"],
  "81:26": ["So where are you going?", "তা এখন, তোমরা যাবে কোথায়?"],
  "81:27": ["It is nothing but a reminder for those who know,", "এটি সব মানুষের জন্য একটি বার্তা।"],
  "81:28": ["for whoever among you wills to go straight.", "তাদের জন্য যারা সোজা চলতে চায়।"],
  "81:29": ["And you will not, unless Allah, Rabb of those who know, wills.", "যা কিছুই তোমরা ইচ্ছা করো তা আল্লাহর ইচ্ছার অধীনে হয়, মহাবিশ্বের প্রভু ।"],
  "82:1": ["When the sky is split open", "যখন আকাশমন্ডলী চূর্ণ-বিচূর্ণ করা হয়।"],
  "82:2": ["and when the stars are scattered", "গ্রহগুলোকে ইতস্তত ছড়িয়ে দেয়া হয়।"],
  "82:3": ["and when the seas burst forth", "মহাসাগরগুলো বিস্ফোরিত  হয় ।"],
  "82:4": ["and when the graves are overturned", "কবর খুলে দেয়া হয় ।"],
  "82:5": ["a soul will know what it sent ahead and left behind", "প্রত্যেকটি আত্মা দেখতে পাবে কি তাকে অগ্রগামী করেছে,আর কি তাকে পশ্চাৎপদ করেছে।"],
  "82:6": ["O human, what deceived you concerning your Rabb, the Generous?", "হে মানব জাতি,কি তোমাদেরকে সরিয়ে দিয়েছিল তোমাদের প্রভু থেকে, যিনি সবচেয়ে সম্মানিত?"],
  "82:7": ["the One who created you, then shaped you, then balanced you", "সে সত্ত্বা যিনি তোমাদের সৃষ্টি করেছেন, তোমাদের নকশা করেছেন, এবং তোমাদের নিঁখুত করেছেন৷"],
  "82:8": ["in whatever form Allah willed, Allah mounted you", "যে নকশাই তিনি পছন্দ করেছিলেন, তা তিনি নির্মাণ করেছেন।"],
  "82:9": ["No! But you deny the Judgment", "নিশ্চয়, তোমরা ধর্মে অবিশ্বাস করো।"],
  "82:10": ["and there are keepers over you", "এই বাস্তবতায় বেখবর যে তোমাদের চারপাশে (অদৃশ্য) রক্ষক আছে ।"],
  "82:11": ["noble recorders", "তারা সত্যনিষ্ঠ নথিভুক্তকারি।"],
  "82:12": ["they know what you do", "তারা তোমাদের করা সবকিছু নথিভুক্ত করে।"],
  "82:13": ["indeed the good ones are in bliss", "নিশ্চয়, সৎকর্মশীলরা পরম সুখ অর্জন করেছে।"],
  "82:14": ["and indeed the fujjar are in the Blaze", "যেখানে অন্যায়কারীরা উপযুক্ত হয়েছে নরকের৷"],
  "82:15": ["they will enter it on the Day of Judgment", "তাতে পতিত হবে বিচার দিবসে৷"],
  "82:16": ["and they will not be absent from it", "তারা কখনো তা ছেড়ে যায় না।"],
  "82:17": ["and what tells you what the Day of Judgment is?", "বিচারের দিন হলো অন্যরকম।"],
  "82:18": ["then again, what tells you what the Day of Judgment is?", "কি এক অসাধারণ দিন ; বিচারের দিন৷"],
  "82:19": ["a day when no soul possesses anything for another soul, and the command that day belongs to Allah", "এটা সেই দিন যখন কোন আত্মা অন্য আত্মাকে সাহায্য করতে পারে না, এবং সকল সিদ্ধান্ত, ঐদিন, আল্লাহর অধীনে হবে।"],
  "83:1": ["Woe to those who give short measure,", "দূর্ভোগ প্রতারকদের প্রতি।"],
  "83:2": ["who, when they measure for people, take it in full,", "যারা লোকদের থেকে নেবার বেলায় পূর্ণমাত্রায় চায়।"],
  "83:3": ["and when they measure for them or weigh for them, they give less.", "কিন্তু সে পরিমান বা ওজন তাদেরকে দেবার বেলায়, তারা প্রতারণা করে।"],
  "83:4": ["Do those not think that they will be raised", "তারা কি জানে না যে তাদের পুনর্জীবিত করা হবে?"],
  "83:5": ["for a great day,", "এক মহাতাৎপর্যপূর্ণ দিনে?"],
  "83:6": ["the day people stand before the Rabb of the worlds?", "এটা সেই দিন যখন সব মানুষ মহাবিশ্বের প্রভুর সামনে দাঁড়াবে।"],
  "83:7": ["No indeed, the record of the fujjar is in Sijjin.", "নিশ্চয়, অন্যায়কারী লোকের বইটি রয়েছে সীজ্জিনে।"],
  "83:8": ["And what tells you what Sijjin is?", "তুমি কি জানো সীজ্জিন কী?"],
  "83:9": ["A written record.", "সংখ্যা দ্বারা কাঠামোবদ্ধ একটি বই।"],
  "83:10": ["Woe that day to the mukazzibin,", "ঐদিন দূর্ভোগ প্রত্যাখ্যানকারীদের প্রতি।"],
  "83:11": ["who deny the Day of Recompense.", "তারা বিচারের দিনে বিশ্বাস করে না।"],
  "83:12": ["None denies it but every transgressor steeped in sin,", "তাতে কেউ অবিশ্বাস করে না সীমালঙ্ঘনকারী, পাপী ব্যতীত।"],
  "83:13": ["who, when our signs are recited to him, says: \"These are but tales of the ancients.\"", "যখন আমাদের প্রকাশনাবলী তার কাছে আবৃত্তি করা হয়, সে বলে, \"অতীতের কল্প-কাহিনী!\""],
  "83:14": ["No indeed; rather, what they used to earn has rusted upon their hearts.", "নিশ্চয়, তাদের পাপের দ্বারা তাদের হৃদয়ে আবরণ পড়েছে।"],
  "83:15": ["No indeed, they will be veiled from their Rabb that day.", "নিশ্চয়, তারা আলাদা হবে, ঐদিন, তাদের প্রভুর কাছ থেকে।"],
  "83:16": ["Then they enter the blaze,", "তারপর তাদের নিক্ষেপ করা হবে নরকে।"],
  "83:17": ["and it is said: \"This is what you used to deny.\"", "তাদের বলা হবে, \"এটা তা-ই, যা তোমরা অস্বীকার করতে।\""],
  "83:18": ["No indeed, the record of the good is in the Highest.", "নিশ্চয়, সৎকর্মশীলদের বইটি থাকবে 'ইল্লীয়িন-এ।"],
  "83:19": ["And what tells you what the Highest is?", "তুমি কি জানো 'ইল্লীয়িন কি?"],
  "83:20": ["A written record.", "সংখ্যা দ্বারা কাঠামোবদ্ধ একটি বই।"],
  "83:21": ["Those brought near bear witness to it.", "তাদের দ্বারা প্রত্যক্ষযোগ্য যারা আমার নিকটবর্তী।"],
  "83:22": ["The good ones are in delight,", "সৎকর্মশীলরা পরমসুখ অর্জন করেছে।"],
  "83:23": ["on couches, looking on.", "বিলাসবহুল আসবাবপত্রের উপরে তারা পর্যবেক্ষণ করে।"],
  "83:24": ["You recognize in their faces the radiance of delight.", "তুমি তাদের চেহারায় পরমসুখের আবেশ চিনতে পারবে।"],
  "83:25": ["They are given drink of a sealed nectar,", "তাদের পানীয়গুলো সুস্বাদু করা হবে প্রবিত্র মিশ্রণে।"],
  "83:26": ["whose seal is musk — and in that let the strivers vie.", "এর শেষ অংশ কস্ত্তরির মত। এটা তা-ই যার জন্য প্রতিযোগীদের প্রতিযোগিতা করা উচিত।"],
  "83:27": ["Its blend is from Tasnim,", "এতে বিশেষ স্বাদসমূহ মিশ্রিত থাকবে ।"],
  "83:28": ["a spring from which the brought-near drink.", "একটি ঝর্ণা থেকে যা সংরক্ষিত তাদের জন্য যারা আমার নিকটে।"],
  "83:29": ["Those who sinned used to laugh at those who believed,", "অন্যায়কারীরা তাদের নিয়ে হাসতো যারা বিশ্বাস করেছিল ।"],
  "83:30": ["and when they passed by them they would wink at one another,", "যখন তারা তাদের পাশ দিয়ে যেতো, তারা ব্যঙ্গ-বিদ্রূপ করতো।"],
  "83:31": ["and when they returned to their people, they returned delighted.", "যখন তারা তাদের লোকদের সাথে একত্রিত হতো,তারা ঠাট্টা করতো।"],
  "83:32": ["And when they saw them, they said: \"These are surely astray.\"", "যখনই তারা তাদের দেখতো, তারা বলতো, \"এই লোকেরা বহুদূর পথভ্রষ্ট!\""],
  "83:33": ["Yet they were not sent over them as keepers.", "\"(অদৃশ্য) প্রহরীর মত এমন কিছু তাদের নেই।\""],
  "83:34": ["So today those who believe laugh at the kafirin,", "আজ, যারা বিশ্বাস করেছিল তারা অবিশ্বাসীদের প্রতি হাসছে।"],
  "83:35": ["on couches, looking on.", "বিলাসবহুল আসবাবপত্রের উপর থেকে তারা পর্যবেক্ষণ করে।"],
  "83:36": ["Shall the kafirin be recompensed for what they used to do?", "সন্দেহাতীতভাবে, অবিশ্বাসীরা যা করেছিল তার জন্য তাদের থেকে প্রতিশোধ গ্রহন করা হবে।"],
  "84:1": ["When the sky splits open,", "সময় আসবে যখন আকাশে ফাটল ধরবে।"],
  "84:2": ["and gives ear to its Rabb, as is due,", "এটি এর প্রভুর নিকট আত্মসমর্পণ করবে এবং বিলপ্ত হবে।"],
  "84:3": ["and when the earth is spread out", "পৃথিবীকে সমতল করা হবে।"],
  "84:4": ["and casts out what is within it and empties itself,", "এটি এর অভ্যন্তরস্থ-বস্তু নির্গত করবে,  যখন তা বিস্ফোরিত হবে।"],
  "84:5": ["and gives ear to its Rabb, as is due,", "এটি এর প্রভুর নিকট আত্মসমর্পণ করবে এবং বিলপ্ত হবে।"],
  "84:6": ["O human, you are surely toiling toward your Rabb with toil, and you will meet your Rabb.", "হে মানুষ, তোমরা অপ্রত্যাবর্তনীয়ভাবে এগিয়ে যাচ্ছো তোমাদের প্রভুর সাথে সাক্ষাতের জন্য।"],
  "84:7": ["So as for the one who is given his record in his right hand,", "সে ব্যক্তির ক্ষেত্রে যে তার ডান হাতে নিজের কর্মফল গ্রহণ করে,"],
  "84:8": ["he will be reckoned with an easy reckoning,", "তার হিসাব-নিকাশ হবে সহজ।"],
  "84:9": ["and he will return to his people, happy.", "সে তার লোকদের কাছে আনন্দ নিয়ে ফিরে যাবে।"],
  "84:10": ["But as for the one who is given his record behind his back,", "সে ব্যক্তির ক্ষেত্রে যে তার বাম হাতে নিজের কর্মফল গ্রহণ করে,"],
  "84:11": ["he will call out for ruin,", "সে হবে অনুশোচনায় কাতর।"],
  "84:12": ["and he will be made to enter the blaze.", "এবং নরকে পুড়বে।"],
  "84:13": ["Indeed he was among his people, happy,", "সে তার লোকদের সাথে ঔদ্ধত্যপূর্ণ আচরণ করতো।"],
  "84:14": ["for he thought that he would never answer.", "সে ভেবেছিল, তাকে কখনো হিসাব দিতে ডাকা হবে না।"],
  "84:15": ["Nay, his Rabb was always watching him.", "হ্যাঁ নিশ্চয়, তার প্রভু তার দ্রষ্টা ছিলেন।"],
  "84:16": ["So I swear by the awe,", "আমি শপথ করি গোলাপিবর্ণ গোধূলির নামে।"],
  "84:17": ["and by the night and what it gathers in,", "এবং রাত যখন তা ছড়িয়ে পড়ে।"],
  "84:18": ["and by the moon when it grows full,", "এবং চাঁদ ও এর বিভিন্ন দশার নামে।"],
  "84:19": ["you will surely ride stage after stage.", "তোমাদের নেয়া হবে এক ধাপ থেকে আরেক ধাপে।"],
  "84:20": ["So what is the matter with them that they do not believe?", "কেন তারা বিশ্বাস করে না?"],
  "84:21": ["And when the Recitation is recited to them, they do not prostrate.", "এবং যখন তাদের কাছে কোর'আন আবৃত্তি করা হয়, তারা সেজদায় পড়ে না।"],
  "84:22": ["Nay, those who disbelieve, they deny.", "এর কারণ যারা অবিশ্বাস করেছিল তারা প্রত্যাখ্যান করছে (কোর'আন)।"],
  "84:23": ["And Allah knows best what they harbor.", "আল্লাহ তাদের গভীরতম চিন্তাগুলো সম্পর্কে পুরোপুরি অবগত।"],
  "84:24": ["So give them glad tidings of a painful punishment,", "তাদেরকে যন্ত্রণাদায়ক শাস্তির প্রতিশ্রুতি দাও।"],
  "84:25": ["except those who believe and do salih deeds; for them is an unstinted reward.", "আর যারা বিশ্বাস করেছিল এবং সৎ জীবন-যাপন করেছিল, তারা এমন এক প্রতিদান পায় যা যথা উপযুক্ত।"],
  "85:1": ["By the sky with its towers", "আকাশ এবং এর ছায়াপথগুলো।"],
  "85:2": ["And the promised day", "সেই প্রতিশ্রুত দিন।"],
  "85:3": ["And the witness and the witnessed", "সেই প্রত্যক্ষদর্শী এবং প্রত্যক্ষ বিষয়।"],
  "85:4": ["Perish the companions of the Trench", "দূর্ভোগ গিরিখাতের সে লোকদের প্রতি।"],
  "85:5": ["The fire with its kindling", "তারা একটি অগ্নীকুন্ডলী জ্বালিয়েছিল।"],
  "85:6": ["When they sat upon it", "তারপর এর পাশে বসলো৷"],
  "85:7": ["And they were witnesses over what they did to the muminin", "যাতে বিশ্বাসীদের অগ্নিদগ্ধ হতে দেখা যায়।"],
  "85:8": ["They requited them only because they believed in Allah, the Mighty, the Praiseworthy", "তারা তাদের ঘৃণা করেছিল শুধুমাত্র সর্বশক্তিমান, প্রশংসনীয় ঈশ্বরকে বিশ্বাস করার কারনেই।"],
  "85:9": ["To whom belongs the dominion of the heavens and the earth; and Allah is witness over everything", "আসমান ও পৃথিবীর রাজত্ব তাঁরই। এবং ঈশ্বর সকল কিছুর সাক্ষী।"],
  "85:10": ["Those who persecuted the believing men and the believing nisa, then did not repent — theirs is the punishment of Hell, and theirs is the punishment of the burning", "নিশ্চয়, যারা বিশ্বাসী পুরুষ ও নারীদের কষ্ট দেয়, এরপর অনুশোচনা করতে ব্যর্থ হয়, তারা টেনে এনেছে জাহান্নামের শাস্তি; তারা টেনে এনেছে দগ্ধ হবার শাস্তি।"],
  "85:11": ["Those who believed and did the salihin deeds — theirs are gardens beneath which rivers flow; that is the great win", "নিশ্চয়, যারা বিশ্বাস করেছিল এবং সৎ জীবন-যাপন করেছিল, তারা প্রবাহিত ঝর্নাসহ বাগানের উপযুক্ত হয়েছে। এটাই শ্রেষ্ঠ বিজয়।"],
  "85:12": ["The seizing of your Rabb is severe", "নিশ্চয়, তোমাদের প্রভুর আঘাত কঠোর।"],
  "85:13": ["It is Allah who begins and brings back", "তিনিই সে সত্ত্বা যিনি সূচনা করেন এবং পুনরাবৃত্তি করেন।"],
  "85:14": ["And Allah is the Forgiving, the Affectionate", "আর তিনিই ক্ষমাকারী, সবচেয়ে দয়ালু।"],
  "85:15": ["Possessor of the high seat, the Glorious", "মহিমান্বিত সিংহাসনের মালিক।"],
  "85:16": ["A doer of whatever Allah wills", "তিনি করেন, যাকিছু তিনি চান।"],
  "85:17": ["Has the account of the hosts come to you", "তুমি কি সেনাদলগুলোর ইতিহাস লক্ষ্য করেছো?"],
  "85:18": ["Fir'awn and Thamud", "ফেরাউন এবং সামুদের?"],
  "85:19": ["Nay, those who kafara are in denial", "যারা অবিশ্বাস করে তারা প্রত্যাখ্যানের মহামারী রোগে আক্রান্ত ।"],
  "85:20": ["And Allah encompasses them from behind", "আল্লাহ তাদের বিষয়ে পুরোপুরি সচেতন।"],
  "85:21": ["Nay, it is a glorious reading", "নিশ্চয়, এটি গৌরবময় কোর'আন।"],
  "85:22": ["In a preserved tablet", "আছে একটি সংরক্ষিত মূল ফলকে।"],
  "86:1": ["By the sky and the path-beater.", "আকাশ এবং আল-তারেকের নামে শপথ।"],
  "86:2": ["And what tells you what the path-beater is?", "তুমি কি জানো আল-তারেক কি?"],
  "86:3": ["The star that pierces through.", "এক উজ্জ্বল তারা।"],
  "86:4": ["Indeed, every soul has a guardian over it.", "নি:সন্দেহে, সবাই সুরক্ষিত।"],
  "86:5": ["So let the human look at what he was created from.", "মানুষ তার সৃষ্টি নিয়ে ভেবে দেখুক।"],
  "86:6": ["He is created from water, gushing,", "তাকে সৃষ্টি করা হয়েছে নির্গত তরল থেকে।"],
  "86:7": ["issuing from between the loins and the dust.", "মেরুদণ্ড এবং ভেতরের অঙ্গের মধ্য থেকে।"],
  "86:8": ["Indeed, Allah is able to bring him back.", "তিনি নি:সন্দেহে তাকে পুনরুজ্জীবিত করতে সক্ষম।"],
  "86:9": ["The day the secrets are tested,", "সে দিন যখন সকল গোপনীয়তা জানাজানি হয়ে যাবে।"],
  "86:10": ["then he will have no strength and no helper.", "তার কোন ক্ষমতা থাকবে না, না কোন সাহায্যকারী।"],
  "86:11": ["And the sky that returns,", "আকাশের নামে যা বর্ষণ করে (পানি)।"],
  "86:12": ["and the earth that splits.", "পৃথিবীর নামে যা বিদীর্ণ হয় (উদ্ভিদ উৎপন্ন করতে)।"],
  "86:13": ["It is a decisive saying,", "এটি একটি গুরুত্বপূর্ণ বিবরণ।"],
  "86:14": ["and it is no jest.", "হালকাভাবে নেয়ার মত নয়।"],
  "86:15": ["They are scheming a scheme,", "তারা গোপন পরিকল্পনা করে।"],
  "86:16": ["and I am scheming a scheme.", "তবে, আমি তা-ই করি।"],
  "86:17": ["So give respite to the kafirin; give them a little time.", "অবিশ্বাসীদের কেবল অবকাশ দাও এক সংক্ষিপ্ত অবকাশ।"],
  "87:1": ["Glorify the name of your Rabb, the Most High", "তোমার প্রভুর নামের মহিমা প্রকাশ করো, যিনি সুউচ্চ।"],
  "87:2": ["who created and proportioned", "তিনি সৃষ্টি করেন এবং আকার দেন।"],
  "87:3": ["and who decreed and guided", "তিনি নকশা করেন এবং পথ দেখান৷"],
  "87:4": ["and who brought out the herbage", "তিনি উৎপন্ন করেন চারণভূমির ঘাস।"],
  "87:5": ["then made it darkened chaff", "এরপর একে পরিনত করেন হালকা খড়ে।"],
  "87:6": ["We will have you recite, and you will not forget", "আমরা তোমার কাছে আবৃতি করবো ; ভূলে যেও না।"],
  "87:7": ["except what Allah wills to make forgotten; indeed Allah knows the open-loud and what is concealed", "আল্লাহর ইচ্ছানুসারে সবকিছু হয় ; তিনি জানেন যা ঘোষণা করা হয় এবং যা গোপন করা হয়।"],
  "87:8": ["And We will make you attain the easy", "আমরা তোমাকে সহজতম পথের দিকে পরিচালনা করবো।"],
  "87:9": ["So remind, if the reminder benefits", "অতঃএব, তুমি স্মরণ করিয়ে দেবে; সম্ভবত স্মরণ করিয়ে দিলে উপকার হবে৷"],
  "87:10": ["Whoever holds reverent awe will remember", "ভক্তিকারী মনোযোগ দিবে।"],
  "87:11": ["And the wretched one will avoid it", "দুর্বৃত্ত তা এড়িয়ে যাবে।"],
  "87:12": ["the one who enters the greatest fire", "পরিনামে সে বিশাল নরকাগ্নি ভোগ করবে।"],
  "87:13": ["then neither dies in it nor lives", "যেখানে সে কখনো মারা যায় না, না জীবিত থাকে।"],
  "87:14": ["He has attained success who purifies himself", "নিশ্চয় সে ব্যক্তি সফল যে তার আত্মাকে উদ্ধার করে।"],
  "87:15": ["and remembers the name of his Rabb and takes warmth", "তার প্রভুর নাম স্মরণের মাধ্যমে, এবং সংযোগ প্রার্থনা (সালাত) পালনের মাধ্যমে।"],
  "87:16": ["But you prefer the nearer life", "নিশ্চয়, তোমরা এই প্রথম জীবন নিয়ে মোহে আছো।"],
  "87:17": ["And the last is better and more lasting", "যদিও পরকাল অনেক উত্তম এবং চিরস্থায়ী।"],
  "87:18": ["Indeed this is in the former written-sheets", "এটা পূর্বেকার শিক্ষাগুলোতে নথিভুক্ত আছে৷"],
  "87:19": ["The written-sheets of Ibrahim and Musa", "ইব্রাহিম এবং মূসার শিক্ষাগুলো ।"],
  "88:1": ["Has there come to you the account of the covering?", "তুমি কি সে অভিভূতকারীর বিষয়ে সচেতন।"],
  "88:2": ["Faces that day are humbled,", "ঐদিন চেহারাগুলো হবে লজ্জিত।"],
  "88:3": ["working, toiling,", "পরিশ্রমরত এবং ক্লান্ত৷"],
  "88:4": ["entering a fiercely blazing fire.", "জ্বলন্ত নরকাগ্নিতে দূর্দশাগ্রস্থ।"],
  "88:5": ["They are given to drink from a spring at full boil.", "অগ্নিকুন্ডলি পাকানো ঝর্না থেকে পানরত।"],
  "88:6": ["They have no food except from what pleads humbly,", "তাদের কোন খাদ্য থাকবে না, অব্যবহার্য ধরণ ব্যতীত।"],
  "88:7": ["it neither fattens nor avails against hunger.", "এটি কখনো পরিপুষ্ট করে না, না ক্ষুধা নিবারণ করে৷"],
  "88:8": ["Faces that day are at ease,", "ঐদিন অন্য চেহারাসমূহ আনন্দে পূর্ণ থাকবে।"],
  "88:9": ["pleased with their striving,", "তাদের কাজে সন্তুষ্ট।"],
  "88:10": ["in a lofty garden.", "প্রশংসিত স্বর্গোদ্যানে।"],
  "88:11": ["They hear no idle talk therein.", "তাতে, কোন অশোভন কথা শুনা যায় না৷"],
  "88:12": ["Therein is a flowing spring,", "তাতে, একটি ঝর্ণা প্রবাহিত হয়৷"],
  "88:13": ["therein couches raised high,", "তাতে, বিলাসবহুল আসবাবপত্র আছে।"],
  "88:14": ["and goblets laid out,", "এবং পানীয়কে সহজলভ্য করা আছে।"],
  "88:15": ["and cushions ranged in rows,", "এবং সারি সারি কলস।"],
  "88:16": ["and carpets spread about.", "এবং আদ্যোপান্ত কার্পেট।"],
  "88:17": ["Do they not look at the camels, how they were created?", "কেন তারা ভেবে দেখে না উটগুলো এবং তাদের সৃষ্টি নিয়ে?"],
  "88:18": ["And at the sky, how it was raised?", "এবং আকাশ ও এর উত্থান নিয়ে।"],
  "88:19": ["And at the mountains, how they were erected?", "এবং পর্বতসমূহ ও এদের গঠন নিয়ে।"],
  "88:20": ["And at the earth, how it was spread out?", "এবং পৃথিবী ও এর নির্মাণ নিয়ে।"],
  "88:21": ["So remind — you are only a reminder.", "তুমি স্মরণ করিয়ে দিবে, কারণ এই স্মারক পৌঁছে দেয়াই তোমার উদ্দেশ্য।"],
  "88:22": ["You are not a keeper over them,", "তাদের উপর তোমার কোন ক্ষমতা নেই৷"],
  "88:23": ["except whoever turns away and denies —", "আর যারা মুখ ফিরিয়ে নেয় এবং অবিশ্বাস করে।"],
  "88:24": ["then Allah will punish them with the greatest punishment.", "আল্লাহ তাদেরকে পতিত করবেন মহা শাস্তিতে৷"],
  "88:25": ["Indeed, to Us is their return.", "আমাদের কাছে তাদের চূড়ান্ত নিয়তি৷"],
  "88:26": ["Then upon Us is their reckoning.", "এরপর আমরা তাদেরকে হিসাবের জন্য ডাকবো।"],
  "89:1": ["By the dawn,", "শপথ ভোরের।"],
  "89:2": ["and by ten nights,", "এবং সে দশটি রাত।"],
  "89:3": ["and by the even and the odd,", "শপথ জোড় এবং বিজোড়ের।"],
  "89:4": ["and by the night when it journeys on.", "শপথ রাতের যখন তা অতিবাহিত হয়।"],
  "89:5": ["Is there in that an oath for the vigilant?", "এক জ্ঞানগর্ভ শপথ, সে ব্যক্তির জন্য যে বুদ্ধিমত্তার অধিকারী।"],
  "89:6": ["Have you not seen how your Rabb dealt with Ad,", "তুমি কি লক্ষ্য করেছ তোমার প্রভু আদের প্রতি কি করেছিলেন?"],
  "89:7": ["Iram of the pillars,", "ইরাম, উঁচু দালানের শহর।"],
  "89:8": ["the like of which was not created in the towns?", "এর মতো কোথাও কিছু ছিল না।"],
  "89:9": ["And Thamud, who hewed the rock in the valley,", "এছাড়া সামূদ, যারা তাদের উপত্যকায় পাথর খোদাই করতো।"],
  "89:10": ["and Fir'awn of the stakes,", "এবং ফেরাউন যার প্রবল ক্ষমতা ছিল।"],
  "89:11": ["those who transgressed in the towns", "তারা সবাই জমিনে সীমালঙ্ঘন করেছিল।"],
  "89:12": ["and multiplied corruption in them,", "তারা সবখানে মন্দ ছড়ায়৷"],
  "89:13": ["so your Rabb poured over them a scourge of punishment.", "পরিনামে, তোমাদের প্রভু তাদের উপর চাবুকের শাস্তি ঢেলে দিলেন৷"],
  "89:14": ["Indeed, your Rabb is ever at the watch-post.", "তোমার প্রভু সবসময় সজাগ।"],
  "89:15": ["As for the human: when his Rabb tests him and honors him and favors him, he says, \"My Rabb has honored me.\"", "যখন মানব জাতিকে তার প্রভুর দ্বারা পরীক্ষা করা হয়, অনুগ্রহসমূহ এবং আনন্দ দিয়ে, সে বলে, \"আমার প্রভু আমার প্রতি উদার।"],
  "89:16": ["And when his Rabb tests him and straitens his provision, he says, \"My Rabb has humiliated me.\"", "কিন্তু যদি তিনি তাকে পরীক্ষা করেন জীবিকা কম দিয়ে, সে বলে, \" আমার প্রভু আমাকে অপদস্ত করছেন! \""],
  "89:17": ["No indeed! You do not honor the orphan,", "ভুল! তুমিই তা নিজের উপর এনেছিলে এতিমের প্রতি খেয়াল না রেখে।"],
  "89:18": ["and you do not urge one another to feed the poor,", "এবং গরিবের প্রতি দান করার উকালতি না করে।"],
  "89:19": ["and you devour the inheritance greedily,", "এবং অসহায় এতিমের উত্তরাধিকার ভোগ করে।"],
  "89:20": ["and you love wealth with an immense love.", "এবং টাকা-পয়সাকে খুব বেশি ভালোবেসে৷"],
  "89:21": ["No indeed! When the earth is crushed, utterly crushed,", "নিশ্চয়, যখন পৃথিবী চূর্ণ-বিচূর্ণ হয়, সম্পূর্ণ চূর্ণ-বিচূর্ণ।"],
  "89:22": ["and your Rabb comes, and the malakat in ranks upon ranks,", "এবং তোমাদের প্রভু আসেন, সারিতে সারিতে ফেরেশতাদের নিয়ে৷"],
  "89:23": ["and Hell is brought that day — that day the human remembers, but what use is the reminder to him?", "ঐদিন, জাহান্নামকে অস্তিত্বে আনা হবে । মানব জাতি স্মরণ করবে - কিন্তু কতই না বিস্ময়কর স্মারক - তখন খুব দেরি হয়ে যাবে৷"],
  "89:24": ["He says, \"If only I had sent something ahead for my life.\"", "সে বলবে , \"ইস, আমি যদি আমার (চিরস্থায়ী) জীবনের জন্য প্রস্তুতি নিতাম।"],
  "89:25": ["So on that day no one punishes as Allah punishes,", "ঐদিন, তাঁর শাস্তির চেয়ে নিকৃষ্টতর শাস্তি হতে পারে না।"],
  "89:26": ["and no one binds as Allah binds.", "কোন বন্দিত্ব তাঁর বন্দিত্বের মতো কার্যকর নয়৷"],
  "89:27": ["O settled soul,", "আর তোমার ক্ষেত্রে, হে পরিতৃপ্ত আত্মা।"],
  "89:28": ["return to your Rabb, pleased and pleasing,", "তোমার প্রভুর কাছে ফিরে যাও, আনন্দিত এবং আনন্দ প্রদানরত৷"],
  "89:29": ["and enter among the servants of your Rabb,", "আমার বান্দাদের মধ্যে স্বাগতম।"],
  "89:30": ["and enter the garden of your Rabb.", "আমার স্বর্গে স্বাগতম।"],
  "90:1": ["I swear by this town", "আমি এই শহরের নামে দৃড় শপথ করি।"],
  "90:2": ["and you are free in this town", "যে শহরটিতে তুমি বাস করো।"],
  "90:3": ["and a father and what he begot", "জন্ম দেয়া এবং জন্ম হওয়া।"],
  "90:4": ["We have truly created the human being in toil", "আমরা মানুষ জাতিকে (তার নিজের মুক্তির জন্য) কঠিন শ্রম দিতে সৃষ্টি করেছি।"],
  "90:5": ["Does he think that no one will have power over him", "সে কি মনে করে যে কেউ তাকে কখনো হিসাব দেয়ার জন্য ডাকবে না?"],
  "90:6": ["He says: \"I have squandered heaps of wealth\"", "সে অহংকার করে, \"আমি অনেক বেশি টাকা ব্যয় করেছি!\""],
  "90:7": ["Does he think that no one saw him", "সে কি মনে করে যে কেউ তাকে দেখে না?"],
  "90:8": ["Have We not made two eyes for him", "আমরা কি তাকে দু'টি চোখ দেইনি?"],
  "90:9": ["and a tongue and two lips", "একটি জিহবা এবং দুটি ঠোঁট?"],
  "90:10": ["and guided him to the two ways", "আমরা কি তাকে দু'টি পথ দেখাইনি?"],
  "90:11": ["But he did not charge up the steep pass", "তার উচিত কঠিন পথ বেছে নেয়া।"],
  "90:12": ["What can tell you what the steep pass is", "কোনটি কঠিন পথ?"],
  "90:13": ["It is to free a captive", "দাস মুক্তি করা।"],
  "90:14": ["or to feed on a day of hunger", "কষ্টের সময়, খাওয়ানো।"],
  "90:15": ["an orphan near of kin", "এতিমদের যারা সম্পর্কিত।"],
  "90:16": ["or a destitute person in the dust", "অথবা সে গরীবকে যার প্রয়োজন।"],
  "90:17": ["then becoming one of those who believe and exhort one another to patience and exhort one another to mercy", "এবং তাদের একজন হওয়া যারা বিশ্বাস করে, এবং একে অন্যকে অবিচল হতে উদ্বুদ্ধ করে, এবং একে অন্যকে দয়ালু হতে উদ্বুদ্ধ করে।"],
  "90:18": ["Those are the companions of the right", "এরা সুখ অর্জন করেছে।"],
  "90:19": ["And those who disbelieve in Our signs, they are the companions of the left", "আর তাদের ক্ষেত্রে যারা আমাদের প্রকাশনাবলি অবিশ্বাস করেছে, তারা দুর্দশা টেনে এনেছে।"],
  "90:20": ["Upon them is an enclosed fire", "তারা নরকাগ্নিতে আবদ্ধ থাকবে।"],
  "91:1": ["By the sun and its forenoon,", "শপথ সূর্য এবং এর উজ্জ্বলতার।"],
  "91:2": ["and the moon when it follows it,", "এর অনুসরণকারী চাঁদের।"],
  "91:3": ["and the day when it brings it to light,", "দিনের যা প্রকাশ করে।"],
  "91:4": ["and the night when it covers it,", "রাতের যা ঢেকে দেয়।"],
  "91:5": ["and the sky and what built it,", "সূর্যের এবং তাঁর, যিনি একে তৈরি করেছিলেন।"],
  "91:6": ["and the earth and what spread it out,", "পৃথিবীর এবং তাঁর, যিনি একে ধরে রেখেছেন।"],
  "91:7": ["and the soul and what formed it,", "আত্মার এবং তাঁর, যিনি একে সৃষ্টি করেছিলেন।"],
  "91:8": ["then inspired it with its immorality and its salihness,", "এরপর একে দেখালেন কি মন্দ আর কি খারাপ।"],
  "91:9": ["He has attained success who purified it,", "সে ব্যক্তি সফল যে একে পাপমুক্ত করে।"],
  "91:10": ["and he has failed who buried it,", "সে ব্যক্তি ব্যর্থ যে একে অবহেলা করে।"],
  "91:11": ["Thamud denied in their transgression,", "সামূদের অবিশ্বাস তাদের সীমালঙ্ঘনের কারণ হয়েছিল।"],
  "91:12": ["when their most wretched one rose up,", "তারা তাদের মধ্যকার নিকৃষ্টকে অনুসরণ করেছিল।"],
  "91:13": ["So the Rasul of Allah said to them, \"The naqah of Allah and her being given to drink.\"", "আল্লাহর বার্তাবাহক তাদের বলেছিলেন, \"এটি আল্লাহর উট ; একে পান করতে দাও।"],
  "91:14": ["So they denied him and cut her down, and their Rabb crushed them for their offense and leveled it.", "তারা তাকে অবিশ্বাস করেছিল এবং একে জবাই করলো। তাদের প্রভু এরপর তাদের পাপের জন্য প্রতিশোধ নিয়েছিলেন এবং তাদের নির্মূল করলেন।"],
  "91:15": ["and Allah does not fear its outcome.", "এরপরও, যারা তাদের পরে এসেছিল তারা অসতর্ক থেকে যায়।"],
  "92:1": ["By the night when it covers,", "রাতের শপথ যখন তা আবৃত করে।"],
  "92:2": ["and the day when it clears,", "দিন যখন তা প্রকাশ করে।"],
  "92:3": ["and by what created the male and the female —", "এবং তাঁর, যিনি সৃষ্টি করেছেন নারী ও পুরুষ।"],
  "92:4": ["your striving is indeed diverse.", "তোমাদের কাজগুলো বিভিন্ন রকমের।"],
  "92:5": ["So as for the one who gave and was mindful,", "তাদের ক্ষেত্রে যারা দান করে এবং সৎকর্মশীলতা বজায় রাখে।"],
  "92:6": ["and affirmed the best,", "এবং ঐশীগ্রন্থ মেনে চলে।"],
  "92:7": ["We will ease that one toward the easy.", "আমরা তাকে সুখের দিকে পরিচালিত করবো।"],
  "92:8": ["And as for the one who withheld and deemed self-sufficient,", "কিন্তু যে ব্যক্তি কৃপন, যদিও সে ধনী।"],
  "92:9": ["and denied the best,", "এবং ঐশীগ্রন্থে অবিশ্বাস করে।"],
  "92:10": ["We will ease that one toward the hardship,", "আমরা তাকে দুর্দশার দিকে পরিচালিত করবো।"],
  "92:11": ["and his wealth will avail him nothing when he plunges to ruin.", "তার বিপদে তার টাকা তাকে সাহায্য করতে পারবে না।"],
  "92:12": ["Upon Us is the guidance,", "আমরা পথনির্দেশনা প্রদান করি।"],
  "92:13": ["and upon Us are the Last and the First.", "আমরা নিয়ন্ত্রণ করি পরকাল , সে সাথে এই জীবন।"],
  "92:14": ["So I have warned you of a blazing fire;", "তোমাকে আমি জ্বলন্ত নরকাগ্নি সম্পর্কে সতর্ক করেছি।"],
  "92:15": ["none enters it but the wretched one,", "মন্দরা ছাড়া কেউ তাতে পুড়বে না।"],
  "92:16": ["who denied and turned away.", "যারা অবিশ্বাস করে এবং মুখ ফিরিয়ে নেয়।"],
  "92:17": ["And the most mindful will be kept from it —", "একে এড়াবে সৎকর্মশীলরা।"],
  "92:18": ["the one who gives that wealth to purify himself,", "যারা তাদের অর্থ থেকে দান করে।"],
  "92:19": ["with no favor from anyone that is sought to be repaid,", "বিনিময়ে কোন কিছু না চেয়ে।"],
  "92:20": ["but only seeking the face of his Rabb the Most High.", "শুধু তার প্রভুকে চেয়ে, যিনি সুউচ্চ ।"],
  "92:21": ["And soon he will be pleased.", "সে নিশ্চয় মুক্তি অর্জন করবে।"],
  "93:1": ["By the forenoon", "পূর্বাহ্নের শপথ।"],
  "93:2": ["And by the night when it settles still", "রাতের শপথ যখন তা নেমে আসে।"],
  "93:3": ["Your Rabb has not abandoned you, nor turned away in displeasure", "তোমার প্রভু কখনো তোমাকে পরিত্যাগ করেননি, না তিনি ভুলে গিয়েছিলেন।"],
  "93:4": ["And the hereafter is better for you than the first", "পরকাল তোমার জন্য অনেক উত্তম এই প্রথম (জীবন)-এর চেয়ে।"],
  "93:5": ["And your Rabb will surely give you, and you will be pleased", "আর তোমার প্রভু তোমাকে যথেষ্ট দিবেন; তুমি খুশি হবে।"],
  "93:6": ["Did Allah not find you an orphan and give you shelter", "তিনি কি তোমাকে এতিম পাননি এবং তোমাকে একটি বাড়ি দেননি?"],
  "93:7": ["And Allah found you lost, and guided you", "তিনি তোমাকে পথভ্রষ্ট পেয়েছিলেন, এবং তোমাকে পথ দেখিয়েছেন।"],
  "93:8": ["And Allah found you in need, and enriched you", "তিনি তোমাকে গরীব পেয়েছিলেন , এবং তোমাকে ধনী করেছেন।"],
  "93:9": ["So as for the orphan, do not overpower", "সুতরাং, তুমি এতিমকে পরিত্যাগ করো না।"],
  "93:10": ["And as for the one who asks, do not drive away", "না তুমি ভিক্ষুককে তিরস্কার করবে।"],
  "93:11": ["And as for the blessing of your Rabb, speak of it", "তুমি তোমার প্রতি তোমার প্রভুর অর্পিত অনুগ্রহ ঘোষণা করবে।"],
  "94:1": ["Did We not open your chest for you", "আমরা কি তোমার মেজাজ ঠান্ডা করিনি?"],
  "94:2": ["And We laid your load down from you", "এবং আমরা তোমার (পাপের) বোঝা হালকা করেছিলাম।"],
  "94:3": ["the one that was breaking your back", "যে বিষয়টা তোমার পিছনে বোঝা হয়েছিল।"],
  "94:4": ["And We raised your remembrance on high for you", "আমরা তোমাকে একটি সম্মানিত অবস্থানে উন্নিত করেছিলাম।"],
  "94:5": ["So indeed with hardship comes ease", "কষ্টের সাথে রয়েছে অর্জন।"],
  "94:6": ["Indeed with hardship comes ease", "নিশ্চয়, কষ্টের সাথে রয়েছে অর্জন।"],
  "94:7": ["So when you are free, then toil", "যখনই সম্ভব হয় তুমি সংগ্রাম করবে।"],
  "94:8": ["And turn eagerly to your Rabb", "কেবল তোমার প্রভুর অন্বেষনে।"],
  "95:1": ["By the fig and the olive,", "শপথ ডুমুর ও জলপাই-এর।"],
  "95:2": ["and the mount of Sinai,", "সিনাই পর্বত।"],
  "95:3": ["and this secure town —", "এবং এই সম্মানিত শহর (মক্কা)।"],
  "95:4": ["Indeed We created humankind in the finest form,", "আমরা মানুষকে সর্বোত্তম নকশায় সৃষ্টি করেছি।"],
  "95:5": ["then We turned them back to the lowest of the low,", "এরপর তাকে ফিরিয়ে দিলাম সর্বনিম্ন হীনতায়।"],
  "95:6": ["except those who believed and did good works; for them is a reward unstinted.", "তাদের ব্যতীত যারা বিশ্বাস করে এবং সৎকর্মশীল জীবন-যাপন করে; তারা যথাযোগ্য পুরষ্কার পায়।"],
  "95:7": ["So what, after all this, makes you deny the Judgment?", "এরপরও কেন তোমরা বিশ্বাসী হতে প্রত্যাখ্যান করো?"],
  "95:8": ["Is not Allah the most just of judges?", "সকল প্রজ্ঞাবানদের থেকে, আল্লাহ কি সবচেয়ে প্রজ্ঞাবান নন?"],
  "96:1": ["Read in the name of your Rabb who created", "পড়, তোমার প্রভুর নামে, যিনি সৃষ্টি করেছেন।"],
  "96:2": ["created the human from a clot", "তিনি মানুষকে সৃষ্টি করেছেন ভ্রূণ থেকে।"],
  "96:3": ["Read, and your Rabb is the most generous", "পড়, এবং তোমার প্রভু, সবচেয়ে প্রশংসিত।"],
  "96:4": ["who taught by the pen", "শিক্ষা দেন কলমের দ্বারা।"],
  "96:5": ["taught the human what he did not know", "তিনি মানুষকে শেখান যা সে কখনো জানতো না।"],
  "96:6": ["No — truly the human transgresses", "নিশ্চয়, মানুষ সীমালঙ্ঘন করে।"],
  "96:7": ["whenever he sees himself free from need", "যখন সে ধনী হয়।"],
  "96:8": ["truly to your Rabb is the return", "তোমার প্রভুর কাছে চূড়ান্ত নিয়তি।"],
  "96:9": ["Have you seen the one who forbids", "তুমি কি সে ব্যক্তিকে দেখেছ যে বাধাঁ দেয়।"],
  "96:10": ["a servant when he prays?", "অন্যদেরকে প্রার্থনা করা থেকে?"],
  "96:11": ["Have you seen: if he is upon guidance", "পথনির্দেশনা অনুসরণ করা কি তার জন্য উত্তম নয়?"],
  "96:12": ["or commands guarding,", "অথবা সৎকর্মশীলতার সমর্থন করা?"],
  "96:13": ["have you seen: if he denies and turns away —", "যদি সে অবিশ্বাস করে এবং মুখ ফিরিয়ে নেয়।"],
  "96:14": ["does he not know that Allah sees?", "সে কি বুঝে না যে আল্লাহ দেখেন?"],
  "96:15": ["No! If he does not cease, We will seize him by the forelock,", "নিশ্চয়, যদি সে বিরত না থাকে, আমরা তার মাথার চুলগুচ্ছ ধরে নিয়ে যাবো।"],
  "96:16": ["a lying, erring forelock.", "একটি চুলগুচ্ছ যা অবিশ্বাসী এবং পাপী।"],
  "96:17": ["Let him call his people then —", "সে তখন তার সাহায্যকারীদের ডাকুক।"],
  "96:18": ["We will call the ones who drive away.", "আমরা ডাকবো দোযখের তত্ত্বাবধায়কদের।"],
  "96:19": ["No! Do not obey him — bow down and draw near.", "তাকে তুমি মান্য করবে না; তুমি সেজদা করবে এবং নিকটতর হও।"],
  "97:1": ["Indeed We sent it down in the night of the decree.", "আমরা একে নিয়তির রজনীতে প্রকাশ করেছি।"],
  "97:2": ["And what tells you what the night of the decree is?", "নিয়তির রজনীটি কতই না অসাধারণ!"],
  "97:3": ["The night of the decree is better than a thousand months.", "নিয়তির রজনীটি হাজার মাসের চেয়ে উত্তম।"],
  "97:4": ["The malakat and the spirit descend therein by permission of their Rabb with every command.", "ফেরেশতারা এবং আত্মা সেখানে নামে, তাদের প্রভুর অনুমতিক্রমে, সম্পাদন করতে প্রতিটি আদেশ।"],
  "97:5": ["Peace it is until the rising of the dawn.", "ভোরের আগমন পর্যন্ত এটি শান্তিপূর্ণ।"],
  "98:1": ["The kafirin among the people of the written sheets and the associators were not free to break away until the clear proof came to them.", "ঐশীগ্রন্থের লোকদের যারা অবিশ্বাস করেছিল, আর যারা শরিক উপাসনাকারী, তারা তাদের পথেই অনড় থাকে, যদিও তাদেরকে প্রমাণ দেয়া হয়েছে।"],
  "98:2": ["A Rasul from Allah, reciting purified written-sheets,", "আল্লাহর পক্ষ থেকে একজন বার্তাবাহক তাদের কাছে ঐশ্বরিক নির্দেশনাবলি আবৃত্তি করছে।"],
  "98:3": ["in which are lasting writings.", "যাতে আছে মূল্যবান শিক্ষাসমূহ।"],
  "98:4": ["Those given the written sheets did not split except after the clear proof had come to them.", "প্রকৃতপক্ষে, যারা ঐশীগ্রন্থ পেয়েছে তারা বিবাদ করে না যতক্ষণ না তাদেরকে প্রমাণ দেয়া হয়।"],
  "98:5": ["They were commanded only to worship Allah, devoting the religion to Allah alone, upright, and to establish the prayer and give the alms; and that is the lasting religion.", "তাদেরকে কেবল বলা হয়েছিল ঈশ্বরের উপাসনা করতে, ধর্মকে পুরোপুরি শুধু তাঁর প্রতি উৎসর্গ করে, সংযোগ প্রার্থনা (সালাত) পালন করো, এবং বাধ্যতামূলক দান (যাকাত) দাও। এমনি হলো যথার্থ ধর্ম।"],
  "98:6": ["Truly, the kafirin among the people of the written sheets and the associators are in the fire of Jahannam, abiding therein forever; those are the worst of creation.", "ঐশীগ্রন্থের লোকদের মধ্যে যারা অবিশ্বাস করেছিল, এবং প্রতিমা উপাসকরা চিরকালের জন্য টেনে এনেছে জাহান্নামের আগুন। তারা হলো নিকৃষ্ট সৃষ্টি।"],
  "98:7": ["Truly, those who believed and did salih deeds — those are the best of creation.", "যারা বিশ্বাস করেছে এবং সৎ জীবন-যাপন করেছে তারা হলো সর্বোত্তম সৃষ্টি।"],
  "98:8": ["Their reward with their Rabb is gardens of Eden, rivers flowing beneath them, abiding therein forever. Allah is pleased with them, and they are pleased with Allah. That is for whoever holds reverent awe of their Rabb.", "তাদের প্রভুর কাছে তাদের পুরষ্কার হলো প্রবাহিত ঝর্ণাসহ ইডেনের বাগানগুলো, যেখানে তারা চিরকাল বাস করে। আল্লাহ তাদের প্রতি সন্তুষ্ট, এবং তারা তাঁর প্রতি সন্তুষ্ট।"],
  "99:1": ["When the earth quakes with its quaking", "যখন পৃথিবীকে ভীষণভাবে নাড়ানো হয়।"],
  "99:2": ["and the earth casts out its burdens", "এবং পৃথিবী এর বোঝাগুলো উদ্গিরন করে।"],
  "99:3": ["and the human says: What is the matter with it?", "মানুষ বিস্মিত হবে : “কি ঘটছে?”"],
  "99:4": ["That day it tells its account", "ঐদিন, এটি এর সংবাদ বলবে।"],
  "99:5": ["because your Rabb has inspired it.", "যা তোমার প্রভু একে আদেশ করেছেন।"],
  "99:6": ["That day the people go forth in diverse groups, to see their deeds.", "ঐদিন, প্রত্যেক দিক থেকে লোকেরা আসবে, তাদের কাজগুলো তাদেরকে দেখাতে।"],
  "99:7": ["So whoever does a mote's weight of good shall see it,", "যে কেউ একটি পরমানুর ভরের সমান ভাল কাজ করেছে, সে তা দেখবে।"],
  "99:8": ["and whoever does a mote's weight of evil shall see it.", "এবং যেকেউ একটি পরমানুর ভরের সমান মন্দ কাজ করেছে, সে তা দেখবে।"],
  "100:1": ["By the chargers breathing hard,", "দ্রুত ছুটে চলা ধাবনকারীর শপথ।"],
  "100:2": ["and those striking sparks of fire,", "যে প্রজ্জ্বলিত করে অগ্নিস্ফুলিঙ্গ।"],
  "100:3": ["and those raiding at dawn,", "(শত্রুর উপর) হামলা করে সকালের মধ্যে।"],
  "100:4": ["and they stirred up dust with it,", "সেখানে আতংক সৃষ্টি করে।"],
  "100:5": ["and they penetrated with it into the midst of the gathering —", "ভেদ করে তাদের এলাকার প্রানকেন্দ্র।"],
  "100:6": ["indeed, man is ungrateful to the Rabb.", "মানব জাতি তার প্রভুর প্রতি অকৃতজ্ঞ।"],
  "100:7": ["And man is a witness to that.", "সে এই বাস্তবতার সাক্ষ্য বহন করে।"],
  "100:8": ["And man is intense in the love of wealth.", "সে পার্থিব জিনিস অতিরিক্ত ভালবাসে।"],
  "100:9": ["Does man not know that, when what is in the graves is scattered abroad,", "সে কি অনুধাবন করে না যে সেদিন আসবে যখন কবর উন্মুক্ত করা হবে?"],
  "100:10": ["and what is in the hearts is brought to light,", "এবং সকল গোপনীয়তা সামনে আনা হবে।"],
  "100:11": ["their Rabb is well aware of them that day?", "তারা, ঐদিন দেখবে, যে তাদের প্রভু তাদের সম্পর্কে জ্ঞাত।"],
  "101:1": ["The striking.", "এক চরম বিপর্যয়।"],
  "101:2": ["What is the striking?", "কি এক চরম বিপর্যয়?"],
  "101:3": ["And what tells you what the striking is?", "তোমার কি কোন ধারণা আছে ঐ চরম বিপর্যয়ের বিষয়ে?"],
  "101:4": ["On the day when people become like the scattered spread,", "এটা সেদিন যখন লোকেরা বেরিয়ে আসে প্রজাপতির ঝাঁকের মতো।"],
  "101:5": ["and the mountains become like fluffed wool.", "পর্বতগুলো হবে তুলতুলে পশমের মতো।"],
  "101:6": ["Then as for the one whose scales weigh heavy,", "তার ক্ষেত্রে যার পাল্লা ভারী।"],
  "101:7": ["then he is in a pleasing life.", "সে সুখী (অনন্ত) জীবন অতিবাহিত করবে।"],
  "101:8": ["And as for the one whose scales weigh light,", "তার ক্ষেত্রে যার পাল্লা হালকা।"],
  "101:9": ["then his mother is a plunge.", "তার ভাগ্য নিম্নমানের।"],
  "101:10": ["And what tells you what it is?", "তুমি কি জানো এটি কি?"],
  "101:11": ["A blazing fire.", "জ্বলন্ত অগ্নিকুণ্ড।"],
  "102:1": ["The race to gain more has distracted you", "তোমরা জমা করা নিয়ে মোহাচ্ছন্ন থাকো।"],
  "102:2": ["until you swerved aside to the graves", "যতক্ষণ না তোমরা কবরে যাও।"],
  "102:3": ["By no means! You will soon know", "নিশ্চয়, তোমরা বুঝতে পাবে।"],
  "102:4": ["Then by no means — you will soon know", "নি:সন্দেহে, তোমরা বুঝতে পাবে।"],
  "102:5": ["By no means! If you knew with the knowledge of certainty", "যদি শুধু তোমরা নিশ্চিত বুঝতে।"],
  "102:6": ["you would surely see the Blaze", "তোমরা নরকের কল্পনা করবে।"],
  "102:7": ["Then you will surely see it with the eye of certainty", "এরপর তোমরা এটি দেখবে নিশ্চয়তার চোখ দিয়ে।"],
  "102:8": ["Then you will surely be asked that day about the comfort", "এরপর, ঐদিন, তোমাদের প্রশ্ন করা হবে, তোমাদের ভোগ করা অনুগ্রহসমূহ সম্পর্কে।"],
  "103:1": ["By the press!", "অপরাহ্নের শপথ।"],
  "103:2": ["Indeed, humankind is surely in loss.", "মানবজাতি ভীষণভাবে ক্ষতিগ্রস্ত।"],
  "103:3": ["Except those who believed and did the salihin deeds and exhorted one another to the truth and exhorted one another to patience.", "তারা ছাড়া যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে, এবং একে অন্যকে সত্যে আঁকড়ে থাকতে উদ্ধুদ্ধ করে, এবং একে অন্যকে অবিচল থাকতে উদ্ধুদ্ধ করে।"],
  "104:1": ["Woe to every slanderer and backbiter.", "দূর্ভোগ প্রত্যেক পরনিন্দাকারী, অপবাদকারীর।"],
  "104:2": ["The one who gathers wealth and counts it.", "সে টাকা জমায় আর তা হিসাব করে।"],
  "104:3": ["He thinks his wealth will make him immortal.", "যেন তার টাকা তাকে অমর করবে।"],
  "104:4": ["No indeed! He will surely be cast into the Crushing Fire.", "কখনো নয়; তাকে নিক্ষেপ করা হবে সে ধ্বংসকারীর মধ্যে।"],
  "104:5": ["And what can tell you what the Crushing Fire is?", "তুমি কি জানো ধ্বংসকারীটি কি?"],
  "104:6": ["It is the fire of Allah, ever kindled.", "আল্লাহর জ্বলন্ত নরকাগ্নি।"],
  "104:7": ["It is the fire that rises over the hearts.", "এটি তাদের আপাদমস্তক পোড়ায়।"],
  "104:8": ["Indeed it is sealed over them.", "তারা সেখানে আবদ্ধ থাকবে।"],
  "104:9": ["In outstretched pillars.", "বর্ধিত স্তম্ভে।"],
  "105:1": ["Did you not see how your Rabb dealt with the companions of the elephant?", "তুমি কি লক্ষ্য করেছ তোমার প্রভু হাতিওয়ালাদের সাথে কি করেছিলেন?"],
  "105:2": ["Did your Rabb not make their scheme go to ruin?", "তিনি কি তাদের ষড়যন্ত্রকে উল্টো তাদের বিরুদ্ধে যেতে দেননি?"],
  "105:3": ["And sent upon them birds in flocks,", "তিনি তাদের উপর পাঠালেন পাখিদের ঝাঁক।"],
  "105:4": ["hurling at them stones of sijjil,", "যা তাদের উপর শক্ত পাথর বর্ষণ করলো।"],
  "105:5": ["and made them like husk eaten up.", "তিনি তাদেরকে চিবানো খড়ের মতো করে দিলেন।"],
  "106:1": ["For the uniting of Quraysh", "এটি কোরাইশদের দ্বারা লালিত হওয়া উচিত।"],
  "106:2": ["their uniting for the winter and summer journeys", "যেভাবে তারা শীত ও গ্রীষ্মের কাফেলাদের লালন করে।"],
  "106:3": ["So let them serve the Rabb of this House", "তারা এই তীর্থস্থানের প্রভুর উপাসনা করবে।"],
  "106:4": ["who fed them from hunger and secured them from fear", "কারণ তিনিই সে সত্ত্বা যিনি তাদের ক্ষুধার পর খাবার দিয়েছেন, আর ভয়ের পর তাদের নিরাপত্তা দিয়েছেন।"],
  "107:1": ["Have you seen the one who denies the religion?", "তুমি কি জানো কে সত্যিকার অর্থে বিশ্বাস প্রত্যাখান করে?"],
  "107:2": ["That is the one who drives the orphan away,", "ঐ ব্যক্তি যে এতিমের সাথে দুর্ব্যবহার করে।"],
  "107:3": ["and does not urge anyone to feed the poor.", "এবং গরীবদের খাওয়ানো সমর্থন করে না।"],
  "107:4": ["So woe to those who pray,", "এবং তাদের প্রতি দূর্ভোগ যারা সংযোগ প্রার্থনা (সালাত) পালন করে-"],
  "107:5": ["those who are heedless of their prayer,", "যারা তাদের প্রার্থনায় পুরোপুরি অমনোযোগী।"],
  "107:6": ["those who act only to be seen,", "তারা কেবল লোক দেখানো কাজ করে।"],
  "107:7": ["and withhold even the smallest help.", "আর তারা দান করতে নিষেধ করে।"],
  "108:1": ["Indeed We gave you the Kawthar", "আমরা তোমাকে অনেক কিছু উদারভাবে দিয়ে সৌভাগ্যবান করেছি।"],
  "108:2": ["So pray for your Rabb and sacrifice", "সুতরাং, তুমি তোমার প্রভুর কাছে প্রার্থনা করো (সালাত), এবং দান করো।"],
  "108:3": ["Indeed the one who hates you is the one cut off", "তোমার প্রতিদ্বন্দ্বী পরাজিত হবে।"],
  "109:1": ["Say, O kafirin:", "বল, “হে তোমরা অবিশ্বাসীরা।"],
  "109:2": ["I do not worship what you worship,", "আমি উপাসনা করি না তোমরা যার উপাসনা করো।"],
  "109:3": ["nor do you worship what I worship,", "না তোমরা উপাসনা করো আমি যার উপাসনা করি।"],
  "109:4": ["nor do I worship what you have worshipped,", "না আমি কখনো উপাসনা করবো তোমরা যার উপাসনা করো।"],
  "109:5": ["nor do you worship what I worship.", "না তোমরা কখনো উপাসনা করবে আমি যার উপাসনা করি।"],
  "109:6": ["For you your religion, and for me my religion.", "“তোমাদের ধর্ম তোমাদের কাছে, এবং আমার ধর্ম আমার কাছে।”"],
  "110:1": ["When the help of Allah comes, and the triumph,", "যখন আল্লাহ থেকে আসে সাফল্য, এবং বিজয়।"],
  "110:2": ["and you see people entering the religion of Allah in companies,", "তুমি লোকদের দলে দলে আল্লাহর ধর্ম গ্রহণ করতে দেখবে।"],
  "110:3": ["then glorify your Rabb with praise, and seek forgiveness from Allah — indeed, Allah is ever forgiving.", "তুমি তোমার প্রভুর মহিমা ও প্রশংসা করো, এবং ক্ষমার জন্য তাঁর কাছে মিনতি করো। তিনিই পরিত্রাণকারী।"],
  "111:1": ["Perished be the two hands of Abu Lahab, and perished is he.", "আবি লাহাবের কাজগুলো নিন্দিত এবং সে নিন্দিত।"],
  "111:2": ["Neither his wealth nor what he earned was of any avail to him.", "তার অর্থ-বিত্ত এবং যাকিছুই সে অর্জন করেছে কখনো তাকে সাহায্য করবে না।"],
  "111:3": ["Soon he will enter a fire of flame.", "সে টেনে এনেছে জ্বলন্ত নরক।"],
  "111:4": ["And his imra'a, the carrier of firewood —", "তার স্ত্রীও, যে নির্যাতনের নেতৃত্ব দিয়েছিল।"],
  "111:5": ["around her neck is a rope of twisted fiber.", "সে তার গলায় কাঁটার রশি নিয়ে (পুনরুজ্জীবিত) হবে।"],
  "112:1": ["Say: Allah is one.", "ঘোষণা করো, “তিনি এক এবং একমাত্র ঈশ্বর।"],
  "112:2": ["Allah, the unique.", "“পরম ঈশ্বর।"],
  "112:3": ["Allah did not beget, nor was begotten.", "“তিনি কখনো জন্ম দেননি। না তাঁকে জন্ম দেয়া হয়েছিল।"],
  "112:4": ["And there has never been anyone equal to Allah.", "“কেউ তাঁর সমান নয়।”"],
  "113:1": ["Say: I seek refuge in the Rabb of the dawn", "বল, “আমি আশ্রয় প্রার্থনা করি প্রভাতের প্রভুর কাছে।"],
  "113:2": ["From the evil of what has been created", "“তাঁর সৃষ্টির অনিষ্ট থেকে”"],
  "113:3": ["And from the evil of the darkness when it closes in", "অন্ধকারের অনিষ্ট থেকে যখন তা গভীর হয়।"],
  "113:4": ["And from the evil of those who blow on knots", "গোলযোগ সৃষ্টিকারীর অনিষ্ট থেকে।"],
  "113:5": ["And from the evil of the envier when he envies", "“হিংসুকের অনিষ্ট থেকে, যখন তারা হিংসা করে।”"],
  "114:1": ["Say: I seek refuge with the Rabb of people", "বল, \" আমি মানুষের প্রভুর নিকট ক্ষমা প্রার্থনা করি।"],
  "114:2": ["the King of people", "\"মানুষের রাজা।"],
  "114:3": ["the ilah of people", "\"মানুষের উপাস্য।"],
  "114:4": ["from the evil of the whisperer who slinks away", "\"গোপনে কুমন্ত্রনাদাতার অনিষ্ট থেকে।"],
  "114:5": ["who whispers into the chests of people", "“যে কুমন্ত্রনা দেয় মানুষের বুকে।"],
  "114:6": ["from among the jinn and people", "“হোক সে জ্বীনদের কেউ, বা মানুষদের কেউ।”"],
};
